insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:1-bbaace2045','adm-cm',1,'¿Cuáles son los valores superiores del ordenamiento jurídico según la Constitución?','["La libertad, la justicia, la igualdad y el pluralismo político", "La libertad, la seguridad, la igualdad y la solidaridad", "La justicia, la paz, la igualdad y la democracia", "La libertad, la justicia, la dignidad y el pluralismo político"]'::jsonb,0,'Art. 1.1 CE','España propugna como valores superiores la libertad, la justicia, la igualdad y el pluralismo político.','abr. 2026 · 1.er ejercicio'),
('adm-cm:1-de374bebd1','adm-cm',1,'Según la Constitución, la soberanía nacional reside en:','["Las Cortes Generales", "El pueblo español", "El Rey", "La Nación y las Comunidades Autónomas"]'::jsonb,1,'Art. 1.2 CE','La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.',null),
('adm-cm:1-e7a694be3b','adm-cm',1,'La forma política del Estado español es:','["La Monarquía constitucional", "El Estado autonómico", "La Monarquía parlamentaria", "La República federal"]'::jsonb,2,'Art. 1.3 CE','La forma política del Estado español es la Monarquía parlamentaria.',null),
('adm-cm:1-f5117d5d7f','adm-cm',1,'Respecto al castellano, todos los españoles tienen:','["Solo el derecho a usarlo", "Solo el deber de conocerlo", "El derecho a conocerlo y el deber de usarlo", "El deber de conocerlo y el derecho a usarlo"]'::jsonb,3,'Art. 3.1 CE','Todos los españoles tienen el deber de conocer el castellano y el derecho a usarlo.',null),
('adm-cm:1-d590d1b3bc','adm-cm',1,'¿Cómo es la bandera de España según la Constitución?','["Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales roja, amarilla y roja, las tres de la misma anchura entre sí", "Tres franjas verticales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales amarilla, roja y amarilla, siendo la roja de doble anchura que cada amarilla"]'::jsonb,0,'Art. 4.1 CE','Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada una de las rojas.',null),
('adm-cm:1-59b747a752','adm-cm',1,'¿Cuál es la capital del Estado según la Constitución?','["La ciudad de Madrid y su área metropolitana", "La villa de Madrid", "La que determine una ley orgánica", "La sede del Gobierno, sea cual sea"]'::jsonb,1,'Art. 5 CE','La capital del Estado es la villa de Madrid.',null),
('adm-cm:1-8898fd29f1','adm-cm',1,'Según el art. 6, los partidos políticos:','["Son órganos del Estado", "Necesitan autorización administrativa previa", "Expresan el pluralismo político", "Pueden tener estructura interna no democrática"]'::jsonb,2,'Art. 6 CE','Los partidos expresan el pluralismo político y su estructura interna y funcionamiento deben ser democráticos.',null),
('adm-cm:1-0dc55c1511','adm-cm',1,'¿Cuál de estos principios NO garantiza el art. 9.3 de la Constitución?','["La publicidad de las normas", "La jerarquía normativa", "La interdicción de la arbitrariedad de los poderes públicos", "La retroactividad de las disposiciones sancionadoras desfavorables"]'::jsonb,3,'Art. 9.3 CE','Se garantiza lo contrario: la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales.',null),
('adm-cm:1-6c75d353e2','adm-cm',1,'Las normas sobre derechos fundamentales se interpretan de conformidad con:','["La Declaración Universal de Derechos Humanos y los tratados ratificados por España", "La jurisprudencia del Tribunal Supremo y los tratados ratificados por España, en ese orden de prelación", "La Declaración Universal de Derechos Humanos y las leyes orgánicas que los desarrollen", "La doctrina del Tribunal Constitucional y los Estatutos de Autonomía vigentes"]'::jsonb,0,'Art. 10.2 CE','Se interpretan conforme a la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales ratificados por España.',null),
('adm-cm:1-a0fa4881ba','adm-cm',1,'Según la Constitución, ¿puede un español de origen ser privado de su nacionalidad?','["Sí, por sentencia firme", "No, en ningún caso", "Sí, si adquiere otra nacionalidad", "Sí, por decisión del Gobierno"]'::jsonb,1,'Art. 11.2 CE','Ningún español de origen podrá ser privado de su nacionalidad.',null),
('adm-cm:1-77434c8da2','adm-cm',1,'¿A qué edad son mayores de edad los españoles según la Constitución?','["16 años", "21 años", "18 años", "La fija cada Comunidad Autónoma"]'::jsonb,2,'Art. 12 CE','Los españoles son mayores de edad a los dieciocho años.',null),
('adm-cm:1-006e804799','adm-cm',1,'Los extranjeros pueden ejercer el derecho de sufragio activo y pasivo:','["En las elecciones municipales y autonómicas, atendiendo a criterios de reciprocidad", "En las elecciones municipales, sin necesidad de criterios de reciprocidad", "En las elecciones municipales y europeas, siempre que residan en España", "En las elecciones municipales, atendiendo a criterios de reciprocidad"]'::jsonb,3,'Art. 13.2 CE','Solo los españoles son titulares del art. 23, salvo el sufragio activo y pasivo en las elecciones municipales con reciprocidad. Este apartado se reformó en 1992.',null),
('adm-cm:1-00c1237ea5','adm-cm',1,'Según el art. 15 de la Constitución, la pena de muerte:','["Queda abolida, salvo lo que dispongan las leyes penales militares para tiempos de guerra", "Queda abolida, salvo para los delitos de terrorismo que determine una ley orgánica", "Queda abolida en todo caso, sin ninguna excepción en el texto constitucional", "Queda abolida, salvo lo que dispongan las leyes penales militares en estado de sitio"]'::jsonb,0,'Art. 15 CE','Queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.',null),
('adm-cm:1-8cb4301aa3','adm-cm',1,'¿Cuánto puede durar como máximo la detención preventiva antes de poner al detenido en libertad o a disposición judicial?','["24 horas", "72 horas", "48 horas", "5 días"]'::jsonb,1,'Art. 17.2 CE','La detención preventiva no puede durar más de lo estrictamente necesario y, como máximo, 72 horas.',null),
('adm-cm:1-57a3c8ce85','adm-cm',1,'¿Qué procedimiento regula la ley para la inmediata puesta a disposición judicial de toda persona detenida ilegalmente?','["El recurso de amparo", "El recurso de inconstitucionalidad", "El habeas corpus", "La cuestión prejudicial"]'::jsonb,2,'Art. 17.4 CE','La ley regula el procedimiento de habeas corpus.',null),
('adm-cm:1-d958c4d2e9','adm-cm',1,'¿En qué casos se puede entrar en un domicilio según la Constitución?','["Con consentimiento del titular, resolución judicial o autorización de la autoridad gubernativa", "Solo con resolución judicial o en caso de flagrante delito", "Con consentimiento del titular o resolución judicial, pero nunca sin ellos", "Con consentimiento del titular, resolución judicial o en caso de flagrante delito"]'::jsonb,3,'Art. 18.2 CE','Ninguna entrada o registro sin consentimiento del titular o resolución judicial, salvo flagrante delito.',null),
('adm-cm:1-028c2e8135','adm-cm',1,'El secuestro de publicaciones y otros medios de información solo puede acordarse:','["En virtud de resolución judicial", "Por orden del Ministerio del Interior", "Por acuerdo del Consejo de Ministros", "Por la autoridad gubernativa en casos urgentes"]'::jsonb,0,'Art. 20.5 CE','Solo podrá acordarse el secuestro en virtud de resolución judicial.',null),
('adm-cm:1-411d51fe2b','adm-cm',1,'Para reuniones en lugares de tránsito público y manifestaciones se exige:','["Autorización previa de la autoridad", "Comunicación previa a la autoridad", "Autorización judicial", "Nada: son totalmente libres"]'::jsonb,1,'Art. 21.2 CE','Se da comunicación previa a la autoridad, que solo puede prohibirlas por razones fundadas de alteración del orden público.',null),
('adm-cm:1-842e043691','adm-cm',1,'¿Qué asociaciones prohíbe expresamente la Constitución?','["Las secretas y las que persigan fines políticos", "Las no inscritas en el registro y las de carácter paramilitar", "Las secretas y las de carácter paramilitar", "Las de carácter paramilitar y las formadas solo por extranjeros"]'::jsonb,2,'Art. 22.5 CE','Se prohíben las asociaciones secretas y las de carácter paramilitar.',null),
('adm-cm:1-d92ab7d646','adm-cm',1,'El art. 23.2 reconoce el derecho a acceder a las funciones y cargos públicos:','["En condiciones de igualdad, según el orden de antigüedad que fijen las leyes", "En condiciones de igualdad, siempre que se posea la nacionalidad española de origen", "Conforme a los méritos que libremente aprecie cada Administración", "En condiciones de igualdad, con los requisitos que señalen las leyes"]'::jsonb,3,'Art. 23.2 CE','Los ciudadanos tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.',null),
('adm-cm:1-003df116dc','adm-cm',1,'Según el art. 24.2, todos tienen derecho:','["Al Juez ordinario predeterminado por la ley", "A elegir el juez que les juzgue", "A ser juzgados por un jurado en todo caso", "A un tribunal especial según su profesión"]'::jsonb,0,'Art. 24.2 CE','Todos tienen derecho al Juez ordinario predeterminado por la ley, a la defensa y a la asistencia de letrado, entre otros.',null),
('adm-cm:1-3dcb53eafa','adm-cm',1,'La Administración civil puede imponer sanciones que impliquen privación de libertad:','["Sí, en casos graves", "No, en ningún caso", "Sí, con autorización judicial posterior", "Solo durante el estado de alarma"]'::jsonb,1,'Art. 25.3 CE','La Administración civil no podrá imponer sanciones que, directa o subsidiariamente, impliquen privación de libertad.',null),
('adm-cm:1-2bd891c6fb','adm-cm',1,'Según la Constitución, la enseñanza básica es:','["Voluntaria y gratuita", "Obligatoria y de pago", "Obligatoria y gratuita", "Voluntaria y de pago"]'::jsonb,2,'Art. 27.4 CE','La enseñanza básica es obligatoria y gratuita.',null),
('adm-cm:1-d0562e9ba7','adm-cm',1,'El derecho a la huelga de los trabajadores se reconoce en:','["El art. 37.2", "El art. 35.1", "El art. 7", "El art. 28.2"]'::jsonb,3,'Art. 28.2 CE','El art. 28.2 reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses.',null),
('adm-cm:1-c49e86c4e2','adm-cm',1,'Según el art. 30.1, defender a España es para los españoles:','["Un derecho y un deber", "Solo un deber", "Solo un derecho", "Una obligación exclusiva de las Fuerzas Armadas"]'::jsonb,0,'Art. 30.1 CE','Los españoles tienen el derecho y el deber de defender a España.',null),
('adm-cm:1-5e61b704ae','adm-cm',1,'El art. 32.1 reconoce el derecho a contraer matrimonio:','["Al hombre y la mujer, a partir de la edad que fije cada Comunidad Autónoma", "Al hombre y la mujer, con plena igualdad jurídica", "Al hombre y la mujer, previa autorización del Registro Civil", "A los españoles mayores de edad, en forma civil o religiosa"]'::jsonb,1,'Art. 32.1 CE','El hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.',null),
('adm-cm:1-5c62e01d2b','adm-cm',1,'¿Qué artículo modificó la reforma constitucional de 2024?','["El art. 135, sobre estabilidad presupuestaria", "El art. 13.2, sobre el sufragio de los extranjeros en elecciones municipales", "El art. 49, sobre las personas con discapacidad", "El art. 69.3, sobre la elección de los senadores provinciales"]'::jsonb,2,'Art. 49 CE','La reforma de febrero de 2024 modificó el art. 49. Las anteriores fueron la de 1992 (art. 13.2) y la de 2011 (art. 135); la de mayo de 2026 modificó el art. 69.3.',null),
('adm-cm:1-8ae3155af6','adm-cm',1,'Según el art. 53.1, el ejercicio de los derechos del Capítulo II solo puede regularse:','["Por decreto-ley", "Por reglamento del Gobierno", "Por ley de las Comunidades Autónomas exclusivamente", "Por ley, que deberá respetar su contenido esencial"]'::jsonb,3,'Art. 53.1 CE','Vinculan a todos los poderes públicos y solo por ley, que respete su contenido esencial, podrá regularse su ejercicio.',null),
('adm-cm:1-741c5a8b0c','adm-cm',1,'¿Qué derechos pueden protegerse mediante recurso de amparo ante el Tribunal Constitucional?','["El art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30", "Todos los derechos del Capítulo II del Título I, incluida su Sección 2.ª", "El art. 14 y los principios rectores del Capítulo III del Título I", "La Sección 1.ª del Capítulo II, pero no la igualdad del art. 14"]'::jsonb,0,'Art. 53.2 CE','Cabe amparo para el art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30, en su caso tras acudir a los tribunales ordinarios.',null),
('adm-cm:1-05385a13b7','adm-cm',1,'El Defensor del Pueblo es:','["Alto comisionado del Gobierno, designado por el Consejo de Ministros", "Alto comisionado de las Cortes Generales, designado por estas", "Alto comisionado de las Cortes Generales, designado por el Rey", "Alto comisionado del Consejo General del Poder Judicial"]'::jsonb,1,'Art. 54 CE','Es alto comisionado de las Cortes Generales, designado por ellas para la defensa de los derechos del Título I.',null),
('adm-cm:1-ec035f8eac','adm-cm',1,'Según el art. 55.1, los derechos pueden suspenderse cuando se declare el estado de:','["Alarma", "Alarma, excepción o sitio", "Excepción o sitio", "Solo sitio"]'::jsonb,2,'Art. 55.1 CE','La suspensión general cabe en el estado de excepción o de sitio, no en el de alarma.',null),
('adm-cm:1-d873eb045f','adm-cm',1,'La suspensión individual de derechos para investigaciones sobre bandas armadas o terrorismo se regula mediante:','["Real decreto", "Ley ordinaria", "Orden ministerial", "Ley orgánica"]'::jsonb,3,'Art. 55.2 CE','Una ley orgánica puede determinar la suspensión individual de los derechos de los arts. 17.2 y 18.2 y 3 en esas investigaciones.',null),
('adm-cm:1-ff8dfa0c2d','adm-cm',1,'¿Qué principios garantiza el art. 9.3 de la Constitución en relación con las normas?','["La legalidad, la jerarquía normativa y la retroactividad de las normas favorables", "La legalidad, la competencia normativa y la publicidad de las normas", "La legalidad, la jerarquía normativa y la publicidad de las normas", "La seguridad jurídica, la reserva de ley y la jerarquía normativa"]'::jsonb,2,'Art. 9.3 CE','Garantiza, entre otros, el principio de legalidad, la jerarquía normativa y la publicidad de las normas.',null),
('adm-cm:1-d64bacfa99','adm-cm',1,'Según el art. 17.1, toda persona tiene derecho a:','["Una vivienda en propiedad", "La asistencia jurídica gratuita en cualquier caso", "La libertad y a la seguridad", "Un trabajo remunerado"]'::jsonb,2,'Art. 17.1 CE','Toda persona tiene derecho a la libertad y a la seguridad.',null),
('adm-cm:1-e36511ea71','adm-cm',1,'Según el art. 31.2, la programación y ejecución del gasto público responden a los criterios de:','["Rentabilidad y beneficio", "Discrecionalidad política", "Prioridad territorial", "Eficiencia y economía"]'::jsonb,3,'Art. 31.2 CE','El gasto público realizará una asignación equitativa de los recursos públicos, y su programación y ejecución responderán a los criterios de eficiencia y economía.',null),
('adm-cm:1-856c208ab7','adm-cm',1,'Según el art. 18.4, la ley limitará el uso de:','["El derecho de reunión y manifestación", "Los medios de comunicación social de titularidad pública", "La informática, para garantizar el honor y la intimidad", "Las armas de fuego, para garantizar la seguridad ciudadana"]'::jsonb,2,'Art. 18.4 CE','La ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar.',null),
('adm-cm:1-bf0c4b3778','adm-cm',1,'El ejercicio de la libertad de expresión e información:','["Requiere autorización previa en los medios de titularidad pública", "No puede restringirse mediante ningún tipo de censura previa", "Puede someterse a censura previa en estados de alarma, excepción y sitio, por ley orgánica", "Solo se ejerce por periodistas"]'::jsonb,1,'Art. 20.2 CE','El ejercicio de estos derechos no puede restringirse mediante ningún tipo de censura previa.',null),
('adm-cm:1-24ba763e72','adm-cm',1,'El secreto de las comunicaciones puede levantarse:','["Por decisión del Gobierno", "Mediante resolución judicial", "Por orden policial", "Nunca en ningún caso"]'::jsonb,1,'Art. 18.3 CE','Se garantiza el secreto de las comunicaciones, salvo resolución judicial.',null),
('adm-cm:1-04b7634ba8','adm-cm',1,'Las demás lenguas españolas distintas del castellano:','["Solo son oficiales en el ámbito educativo de cada Comunidad Autónoma", "Son también oficiales en las respectivas Comunidades Autónomas de acuerdo con sus Estatutos", "Son oficiales en todo el territorio nacional, junto al castellano", "Son oficiales en las respectivas Comunidades Autónomas, pero solo cuando lo establezca una ley orgánica estatal"]'::jsonb,1,'Art. 3.2 CE','Son oficiales en sus Comunidades Autónomas de acuerdo con sus Estatutos.',null),
('adm-cm:1-506b8ac6e1','adm-cm',1,'Mediante ley podrán regularse los deberes de los ciudadanos en los casos de:','["Cambio de Gobierno o estado de alarma", "Grave riesgo, catástrofe o calamidad pública", "Huelga general", "Crisis económica grave declarada por el Gobierno"]'::jsonb,1,'Art. 30.4 CE','Podrán regularse los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad pública.',null),
('adm-cm:1-fba5b84135','adm-cm',1,'La libertad ideológica, religiosa y de culto tiene como única limitación en sus manifestaciones:','["La moral pública y las buenas costumbres, según determine la ley", "La autorización gubernativa previa", "La que fije cada confesión religiosa", "La necesaria para el mantenimiento del orden público protegido por la ley"]'::jsonb,3,'Art. 16.1 CE','Sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.',null),
('adm-cm:1-4803bfcca9','adm-cm',1,'Según el art. 16.3, ¿alguna confesión tendrá carácter estatal?','["Sí, las que reconozca una ley orgánica", "No, ninguna confesión tendrá carácter estatal", "Sí, la católica", "Las que tengan más de un millón de fieles"]'::jsonb,1,'Art. 16.3 CE','Ninguna confesión tendrá carácter estatal, aunque los poderes públicos mantendrán relaciones de cooperación con la Iglesia Católica y las demás confesiones.',null),
('adm-cm:1-5d020603b4','adm-cm',1,'Los principios del Capítulo III del Título I (principios rectores de la política social y económica):','["Son directamente exigibles ante el Tribunal Constitucional en recurso de amparo", "Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos", "Informarán la legislación positiva, pero no la práctica judicial ni la actuación de la Administración", "Solo vinculan al Parlamento, y son directamente exigibles ante los tribunales ordinarios por cualquier ciudadano"]'::jsonb,1,'Art. 53.3 CE','Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos; solo podrán alegarse ante la jurisdicción ordinaria según las leyes que los desarrollen.',null),
('adm-cm:1-27b2603a21','adm-cm',1,'El derecho a comunicar o recibir información, según el art. 20.1 d), se refiere a información:','["Veraz", "Oficial", "Gratuita", "Autorizada"]'::jsonb,0,'Art. 20.1 d) CE','Se reconoce el derecho a comunicar o recibir libremente información veraz por cualquier medio de difusión.',null),
('adm-cm:1-591f255400','adm-cm',1,'Los poderes públicos garantizan el derecho de los padres a que sus hijos reciban:','["Educación en su lengua materna en todo caso", "La formación religiosa y moral que esté de acuerdo con sus propias convicciones", "La formación religiosa y moral de la confesión mayoritaria, salvo renuncia expresa de los padres o tutores", "Educación exclusivamente pública"]'::jsonb,1,'Art. 27.3 CE','Garantizan que los hijos reciban la formación religiosa y moral acorde con las convicciones de sus padres.',null),
('adm-cm:1-0a4820b163','adm-cm',1,'El principio de legalidad del art. 25.1 establece que nadie puede ser condenado o sancionado por acciones u omisiones que:','["En el momento de dictarse la resolución no constituyan delito, falta o infracción administrativa", "En el momento de producirse no constituyan delito, falta o infracción administrativa, según la legislación vigente", "En el momento de producirse no constituyan delito según la ley penal, aunque sí infracción según un reglamento", "Sean contrarias a la moral o hayan causado alarma social"]'::jsonb,1,'Art. 25.1 CE','Nadie puede ser condenado o sancionado por acciones u omisiones que, cuando se produjeron, no constituían delito, falta o infracción administrativa.',null),
('adm-cm:1-18e1e51754','adm-cm',1,'Según el art. 14, los españoles son iguales ante la ley sin que pueda prevalecer discriminación por razón de:','["Nacimiento, raza, sexo, religión u opinión, sin incluir otras circunstancias", "Sexo, raza, nacionalidad, ideología y orientación sexual, pero no por cualquier otra condición o circunstancia personal o social", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición, salvo las circunstancias económicas y sociales, que regulan las leyes"]'::jsonb,2,'Art. 14 CE','No puede prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.','abr. 2026 · 1.er ejercicio'),
('adm-cm:1-0c9bd3ccb1','adm-cm',1,'Son ilegales las asociaciones que:','["Reciban subvenciones públicas sin haberse inscrito previamente en el registro", "Persigan fines o utilicen medios tipificados como delito", "Tengan menos de diez socios fundadores", "No estén inscritas en un registro"]'::jsonb,1,'Art. 22.2 CE','Las asociaciones que persigan fines o utilicen medios tipificados como delito son ilegales.',null),
('adm-cm:1-e5c9ca4956','adm-cm',1,'La nacionalidad española se adquiere, se conserva y se pierde:','["Solo por nacimiento o por residencia legal continuada", "Según lo que establezca cada Comunidad Autónoma en su Estatuto", "De acuerdo con lo establecido por la ley", "Por decisión del Gobierno, mediante real decreto acordado en Consejo de Ministros"]'::jsonb,2,'Art. 11.1 CE','Se adquiere, conserva y pierde de acuerdo con lo establecido por la ley.',null),
('adm-cm:1-02da845b15','adm-cm',1,'El art. 40.2 encomienda a los poderes públicos garantizar el descanso necesario mediante:','["La jubilación anticipada y la reducción de la edad de jubilación", "La semana laboral de cuatro días y la jornada continua", "La limitación de la jornada laboral y las vacaciones periódicas retribuidas", "La limitación de la jornada laboral y los permisos retribuidos que fije cada convenio colectivo"]'::jsonb,2,'Art. 40.2 CE','Mediante la limitación de la jornada laboral, las vacaciones periódicas retribuidas y la promoción de centros adecuados.',null),
('adm-cm:1-6eeed75495','adm-cm',1,'El derecho de reunión pacífica y sin armas:','["No necesita autorización previa", "Requiere autorización judicial", "Requiere autorización del Delegado del Gobierno", "Solo se ejerce en locales cerrados"]'::jsonb,0,'Art. 21.1 CE','Se reconoce el derecho de reunión pacífica y sin armas, cuyo ejercicio no necesita autorización previa.',null),
('adm-cm:1-fea1c01767','adm-cm',1,'Según el art. 10.1, son fundamento del orden político y de la paz social:','["La monarquía parlamentaria, la soberanía nacional y la unidad de la Nación española", "La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás", "La dignidad de la persona, la soberanía popular, la economía social de mercado, la unidad de la Nación española y la solidaridad entre sus nacionalidades y regiones", "La unidad de mercado y la libertad de empresa"]'::jsonb,1,'Art. 10.1 CE','Lo son la dignidad de la persona, sus derechos inviolables, el libre desarrollo de la personalidad y el respeto a la ley y a los derechos de los demás.','abr. 2026 · 1.er ejercicio'),
('adm-cm:1-c50327545f','adm-cm',1,'La estructura interna y el funcionamiento de los Colegios Profesionales deberán ser:','["Fijados por el Gobierno", "Secretos", "Democráticos", "Jerárquicos"]'::jsonb,2,'Art. 36 CE','La ley regulará los Colegios Profesionales, cuya estructura interna y funcionamiento deberán ser democráticos.',null),
('adm-cm:1-62719165a8','adm-cm',1,'Según el art. 7, los sindicatos de trabajadores y las asociaciones empresariales deben tener:','["Una estructura interna y un funcionamiento democráticos", "Un número mínimo de afiliados que fije la ley orgánica correspondiente", "Autorización administrativa previa", "Inscripción en el Registro de Partidos Políticos"]'::jsonb,0,'Art. 7 CE','Su estructura interna y funcionamiento deberán ser democráticos.',null),
('adm-cm:1-7a361160e2','adm-cm',1,'La riqueza de las distintas modalidades lingüísticas de España es, según la Constitución:','["Un asunto de las Comunidades sin protección constitucional", "Un límite a la libertad de expresión", "Un patrimonio cultural objeto de especial respeto y protección", "Una competencia exclusiva del Estado"]'::jsonb,2,'Art. 3.3 CE','Es un patrimonio cultural que será objeto de especial respeto y protección.',null),
('adm-cm:1-bd199ce697','adm-cm',1,'La ley garantiza el derecho a la negociación colectiva laboral y:','["La prohibición de los convenios de empresa", "El arbitraje obligatorio", "La aprobación de los convenios por el Gobierno", "La fuerza vinculante de los convenios"]'::jsonb,3,'Art. 37.1 CE','La ley garantizará el derecho a la negociación colectiva laboral, así como la fuerza vinculante de los convenios.',null),
('adm-cm:1-742ff13ee5','adm-cm',1,'Los extranjeros gozan en España de las libertades públicas del Título I:','["En ningún caso, salvo los derechos inherentes a la dignidad humana", "En igualdad absoluta con los españoles, incluido el derecho de sufragio en todas las elecciones", "Solo si residen legalmente más de cinco años", "En los términos que establezcan los tratados y la ley"]'::jsonb,3,'Art. 13.1 CE','Gozarán de las libertades públicas que garantiza el Título I en los términos que establezcan los tratados y la ley.',null),
('adm-cm:1-7cea1c00fa','adm-cm',1,'Las libertades del art. 20 tienen su límite, especialmente, en:','["La opinión mayoritaria de la sociedad, los intereses económicos del Estado y las instrucciones del Gobierno sobre la información pública", "Las instrucciones del Gobierno en materia de comunicación", "La seguridad nacional, el orden público, los intereses económicos del Estado y las instrucciones del Gobierno en materia de comunicación", "El derecho al honor, a la intimidad, a la propia imagen y la protección de la juventud y de la infancia"]'::jsonb,3,'Art. 20.4 CE','Tienen su límite en los demás derechos del Título I y, especialmente, en el honor, la intimidad, la propia imagen y la protección de la juventud y la infancia.',null),
('adm-cm:1-b052ceed66','adm-cm',1,'Las penas privativas de libertad y las medidas de seguridad están orientadas a:','["El trabajo obligatorio en beneficio de la comunidad y la compensación económica a la víctima del delito", "La compensación económica a la víctima y a la sociedad", "La reeducación y la reinserción social, y no pueden consistir en trabajos forzados", "La reeducación y la reinserción social, y pueden incluir trabajos forzados en los casos que prevea la ley"]'::jsonb,2,'Art. 25.2 CE','Están orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.',null),
('adm-cm:1-87c9252897','adm-cm',1,'Las Fuerzas Armadas están constituidas, según la Constitución, por:','["El Ejército de Tierra y la Policía Nacional", "El Ejército de Tierra, la Armada y el Ejército del Aire", "Las Fuerzas y Cuerpos de Seguridad del Estado", "El Ejército de Tierra, la Guardia Civil y la Armada"]'::jsonb,1,'Art. 8.1 CE','Las constituyen el Ejército de Tierra, la Armada y el Ejército del Aire.',null),
('adm-cm:1-fdc0e818ca','adm-cm',1,'Según el art. 33.3, nadie podrá ser privado de sus bienes y derechos sino:','["Por deudas con particulares reconocidas en sentencia firme", "Por orden del alcalde", "Por causa justificada de utilidad pública o interés social, sin indemnización cuando así lo decida el Gobierno mediante real decreto", "Por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con la ley"]'::jsonb,3,'Art. 33.3 CE','Solo por causa justificada de utilidad pública o interés social, con indemnización y conforme a la ley.',null),
('adm-cm:1-a5a7619434','adm-cm',1,'Según el art. 30.3, podrá establecerse:','["Un servicio civil para el cumplimiento de fines de interés general", "Un impuesto especial para la defensa nacional y la protección civil", "Un servicio militar universitario", "Una milicia en cada Comunidad Autónoma"]'::jsonb,0,'Art. 30.3 CE','Podrá establecerse un servicio civil para el cumplimiento de fines de interés general.',null),
('adm-cm:1-5205bdfc5f','adm-cm',1,'Según el art. 43.3, los poderes públicos fomentarán:','["El deporte profesional y de alto rendimiento, exclusivamente", "La medicina preventiva privada mediante conciertos con las mutuas sanitarias", "La educación sanitaria, la educación física y el deporte", "La educación física y el deporte escolar, pero no la educación sanitaria"]'::jsonb,2,'Art. 43.3 CE','Fomentarán la educación sanitaria, la educación física y el deporte, y facilitarán la adecuada utilización del ocio.',null),
('adm-cm:1-39a0fd846e','adm-cm',1,'Según el art. 33.1, se reconoce el derecho:','["A la herencia, pero solo entre cónyuges y descendientes", "A la propiedad privada y a la herencia", "A la propiedad privada y a una vivienda en propiedad para cada familia", "A una renta mínima garantizada"]'::jsonb,1,'Art. 33.1 CE','Se reconoce el derecho a la propiedad privada y a la herencia.',null),
('adm-cm:1-b05e7445af','adm-cm',1,'Según el art. 38, se reconoce la libertad de empresa en el marco de:','["La economía de mercado", "La economía cooperativa exclusivamente", "La planificación central obligatoria", "El monopolio estatal"]'::jsonb,0,'Art. 38 CE','Se reconoce la libertad de empresa en el marco de la economía de mercado.',null),
('adm-cm:1-2323b94144','adm-cm',1,'Según el art. 35.1, todos los españoles tienen:','["Solo el derecho al trabajo", "El deber de trabajar y el derecho al trabajo", "Derecho a no trabajar sin consecuencias", "Derecho a un empleo público"]'::jsonb,1,'Art. 35.1 CE','Tienen el deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio y a una remuneración suficiente.',null),
('adm-cm:1-1bb80edc38','adm-cm',1,'Según el art. 28.1, respecto a la libertad sindical:','["La afiliación es obligatoria para los funcionarios", "Nadie podrá ser obligado a afiliarse a un sindicato", "Solo pueden sindicarse los trabajadores fijos", "Los jueces pueden sindicarse sin límites"]'::jsonb,1,'Art. 28.1 CE','Todos tienen derecho a sindicarse libremente y nadie podrá ser obligado a afiliarse a un sindicato.',null),
('adm-cm:1-4a1eccb867','adm-cm',1,'El derecho de petición, según el art. 29.1:','["Solo pueden ejercerlo las asociaciones", "Requiere abogado", "Es individual y colectivo, por escrito", "Solo es individual y verbal"]'::jsonb,2,'Art. 29.1 CE','Todos los españoles tienen el derecho de petición individual y colectiva, por escrito.',null),
('adm-cm:1-e64d76a043','adm-cm',1,'El art. 43 reconoce el derecho a:','["La asistencia sanitaria privada gratuita", "La protección de la salud", "La elección libre de médico en todo caso", "Un seguro de vida"]'::jsonb,1,'Art. 43.1 CE','Se reconoce el derecho a la protección de la salud.',null),
('adm-cm:1-ab54ad4b1f','adm-cm',1,'El art. 47 reconoce a todos los españoles el derecho a:','["Una ayuda pública al alquiler en todo caso, de cuantía fija", "Una vivienda en propiedad a precio tasado", "Disfrutar de una vivienda digna y adecuada", "Disfrutar de una vivienda digna, que los poderes públicos deben adjudicar directamente a quien la solicite"]'::jsonb,2,'Art. 47 CE','Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.',null),
('adm-cm:1-2e6879c529','adm-cm',1,'Los poderes públicos garantizarán la conservación y promoverán el enriquecimiento de:','["Las empresas públicas y su patrimonio", "El patrimonio histórico, cultural y artístico de los pueblos de España", "El patrimonio histórico, cultural y artístico de titularidad pública, pero no el de titularidad privada", "Los bienes de la Corona"]'::jsonb,1,'Art. 46 CE','Garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico.',null),
('adm-cm:1-3a3dc6925d','adm-cm',1,'Según el art. 24.1, todas las personas tienen derecho a obtener la tutela efectiva de los jueces y tribunales:','["Sin que, en ningún caso, pueda producirse indefensión", "Solo en asuntos penales y contencioso-administrativos", "Solo si están asistidas de abogado y procurador", "Previo pago de las tasas judiciales correspondientes"]'::jsonb,0,'Art. 24.1 CE','Tienen derecho a la tutela judicial efectiva sin que, en ningún caso, pueda producirse indefensión.',null),
('adm-cm:1-bf98cb59a5','adm-cm',1,'¿Qué prohíbe el art. 26 de la Constitución?','["Los colegios profesionales con adscripción obligatoria", "Los jurados populares en el ámbito penal", "Los tribunales militares en tiempo de guerra y en los supuestos de estado de sitio declarados por el Congreso", "Los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales"]'::jsonb,3,'Art. 26 CE','Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.',null),
('adm-cm:1-f76380f500','adm-cm',1,'El art. 18.1 garantiza el derecho:','["Al honor, a la intimidad personal y familiar y a la propia imagen", "A la propiedad privada y a la herencia", "A la libertad de empresa en el marco de la economía de mercado", "Al secreto de las comunicaciones"]'::jsonb,0,'Art. 18.1 CE','Garantiza el derecho al honor, a la intimidad personal y familiar y a la propia imagen.',null),
('adm-cm:1-0d465b6571','adm-cm',1,'El derecho de fundación se reconoce:','["Para fines de interés general, con arreglo a la ley", "Solo a las empresas y sociedades mercantiles", "Solo para fines religiosos o benéficos", "Para cualquier fin, incluido el lucrativo, con arreglo a la ley"]'::jsonb,0,'Art. 34.1 CE','Se reconoce el derecho de fundación para fines de interés general, con arreglo a la ley.',null),
('adm-cm:1-ea7f9ff42a','adm-cm',1,'Según el art. 9.1, están sujetos a la Constitución y al resto del ordenamiento jurídico:','["Solo los ciudadanos españoles", "Solo los funcionarios y los poderes públicos", "Solo los poderes públicos y los funcionarios", "Los ciudadanos y los poderes públicos"]'::jsonb,3,'Art. 9.1 CE','Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.',null),
('adm-cm:1-4d46e1516c','adm-cm',1,'Las prestaciones personales o patrimoniales de carácter público solo pueden establecerse:','["Con arreglo a la ley", "Por reglamento", "Por orden ministerial", "Por acuerdo municipal"]'::jsonb,0,'Art. 31.3 CE','Solo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley.',null),
('adm-cm:1-26cec53f8f','adm-cm',1,'Según el art. 44.2, los poderes públicos promoverán:','["La investigación militar y de defensa, y la cooperación científica con las Fuerzas Armadas aliadas", "Solo la investigación sanitaria y farmacéutica", "La investigación privada exclusivamente, mediante incentivos fiscales a las empresas", "La ciencia y la investigación científica y técnica en beneficio del interés general"]'::jsonb,3,'Art. 44.2 CE','Promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.',null),
('adm-cm:1-b08863207a','adm-cm',1,'¿Quién establece los términos en que extranjeros y apátridas pueden gozar del derecho de asilo?','["Los tratados exclusivamente", "La ley", "El Defensor del Pueblo", "El Ministerio del Interior por orden"]'::jsonb,1,'Art. 13.4 CE','La ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo.',null),
('adm-cm:1-a292d5cf52','adm-cm',1,'¿Qué regula la ley según el art. 20.3?','["La censura previa de los medios de comunicación privados", "Las tarifas publicitarias y el régimen de concesión de licencias de los medios de comunicación privados de ámbito estatal", "El control parlamentario de los medios de comunicación social dependientes del Estado o de cualquier ente público", "El control gubernamental de todos los medios de comunicación social, públicos y privados, a través de una autoridad independiente"]'::jsonb,2,'Art. 20.3 CE','La ley regulará la organización y el control parlamentario de los medios dependientes del Estado o de cualquier ente público.',null),
('adm-cm:1-e3469a7fbf','adm-cm',1,'Respecto a la extradición, la Constitución establece que:','["No se consideran delitos políticos los actos de terrorismo", "Solo la concede el Gobierno, sin intervención judicial", "Se concede sin necesidad de tratado ni de ley, por reciprocidad", "Está prohibida en todo caso respecto de los nacionales"]'::jsonb,0,'Art. 13.3 CE','La extradición se concede en cumplimiento de un tratado o de la ley, atendiendo a la reciprocidad; los actos de terrorismo no se consideran delitos políticos.',null),
('adm-cm:1-a45c249e18','adm-cm',1,'Toda persona detenida debe ser informada:','["Solo si lo solicita su abogado o un familiar", "En el plazo máximo de 72 horas, una vez puesta a disposición judicial y en presencia de su abogado", "Solo cuando sea puesta a disposición judicial, en presencia de su abogado y en el plazo de setenta y dos horas", "De forma inmediata y comprensible de sus derechos y de las razones de su detención"]'::jsonb,3,'Art. 17.3 CE','Debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención.',null),
('adm-cm:1-1a86c7095c','adm-cm',1,'Según la Constitución, ¿puede alguien ser obligado a declarar sobre su ideología, religión o creencias?','["No", "Sí, ante un juez", "Sí, en los censos oficiales", "Solo los funcionarios"]'::jsonb,0,'Art. 16.2 CE','Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.',null),
('adm-cm:1-2a7e52153a','adm-cm',1,'Respecto al medio ambiente, el art. 45.1 reconoce:','["El derecho a disfrutar de un medio ambiente adecuado y el deber de conservarlo", "El derecho a disfrutar de un medio ambiente adecuado, sin establecer ningún deber de conservarlo", "El derecho a explotarlo libremente", "El deber de conservarlo, pero no el derecho a disfrutarlo, que se regula en los Estatutos"]'::jsonb,0,'Art. 45.1 CE','Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.',null),
('adm-cm:1-650246c78b','adm-cm',1,'Las banderas propias de las Comunidades Autónomas:','["Las aprueba el Gobierno de la Nación a propuesta de cada Comunidad", "Están prohibidas en los edificios públicos del Estado", "Sustituyen a la bandera de España en los edificios y actos oficiales de su territorio, si así lo dispone su Estatuto", "Pueden ser reconocidas por los Estatutos y se utilizan junto a la bandera de España en sus edificios y actos oficiales"]'::jsonb,3,'Art. 4.2 CE','Los Estatutos pueden reconocerlas; se usan junto a la bandera de España en sus edificios públicos y actos oficiales.',null),
('adm-cm:1-bd9f51bbd1','adm-cm',1,'Las asociaciones solo pueden ser disueltas o suspendidas en sus actividades:','["Por orden del Ministerio del Interior", "Por acuerdo del Consejo de Ministros", "En virtud de resolución judicial motivada", "Por decisión de la Delegación del Gobierno"]'::jsonb,2,'Art. 22.4 CE','Solo podrán ser disueltas o suspendidas en virtud de resolución judicial motivada.',null),
('adm-cm:1-d73d7bea62','adm-cm',1,'Según el art. 27.2, la educación tiene por objeto:','["El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos y a los derechos fundamentales", "Preparar para el acceso al empleo y a la función pública", "La formación profesional exclusivamente", "El pleno desarrollo de la personalidad humana en el respeto a la religión mayoritaria y a las tradiciones de cada Comunidad Autónoma"]'::jsonb,0,'Art. 27.2 CE','Tiene por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.',null),
('adm-cm:1-ea560f08cc','adm-cm',1,'Según el art. 2, la Constitución se fundamenta en:','["La indisoluble unidad de la Nación española, y reconoce el derecho a la autonomía de las nacionalidades y regiones", "La voluntad del Jefe del Estado", "La soberanía compartida del Estado y de las Comunidades Autónomas, y reconoce su derecho a la autodeterminación", "El pacto entre los territorios históricos"]'::jsonb,0,'Art. 2 CE','Se fundamenta en la indisoluble unidad de la Nación española y reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones y la solidaridad entre todas ellas.','oct. 2026 · 1.er ejercicio'),
('adm-cm:1-357f00269c','adm-cm',1,'¿Quién inspecciona y homologa el sistema educativo?','["Los poderes públicos", "Las universidades", "Los colegios profesionales", "Las asociaciones de padres"]'::jsonb,0,'Art. 27.8 CE','Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.',null),
('adm-cm:1-1537084650','adm-cm',1,'Según el art. 41, los poderes públicos mantendrán:','["Mutualidades profesionales obligatorias", "Un seguro médico solo para los trabajadores por cuenta ajena", "Un sistema privado de pensiones obligatorio", "Un régimen público de Seguridad Social para todos los ciudadanos"]'::jsonb,3,'Art. 41 CE','Mantendrán un régimen público de Seguridad Social para todos los ciudadanos.',null),
('adm-cm:1-4366eed851','adm-cm',1,'Según el art. 39.1, los poderes públicos aseguran:','["Una vivienda digna a cada familia", "La protección social, económica y jurídica de la familia", "La protección social, económica y jurídica de la familia, pero solo de la fundada en el matrimonio", "La educación obligatoria hasta los 25 años"]'::jsonb,1,'Art. 39.1 CE','Los poderes públicos aseguran la protección social, económica y jurídica de la familia.','nov. 2024 · 1.er ejercicio'),
('adm-cm:1-7b22554e3b','adm-cm',1,'Según el art. 50, los poderes públicos garantizarán a los ciudadanos durante la tercera edad:','["Una plaza en una residencia pública", "La gratuidad del transporte público", "Una pensión igual para todos, independientemente de lo cotizado", "Pensiones adecuadas y periódicamente actualizadas"]'::jsonb,3,'Art. 50 CE','Garantizarán, mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica en la tercera edad.',null),
('adm-cm:1-ee01cef447','adm-cm',1,'El sistema tributario, según el art. 31.1, debe ser justo, inspirado en la igualdad y la progresividad, y:','["Proporcional a la renta en todo caso", "Igual para todos los contribuyentes, con independencia de su renta", "En ningún caso tendrá alcance confiscatorio", "Exclusivamente estatal"]'::jsonb,2,'Art. 31.1 CE','Se basa en la igualdad y la progresividad, y en ningún caso tendrá alcance confiscatorio.',null),
('adm-cm:1-b3c96b69f0','adm-cm',1,'Se reconoce a las personas físicas y jurídicas la libertad de:','["Expedir títulos oficiales sin necesidad de homologación", "Fijar libremente los planes de estudio oficiales", "Creación de centros docentes, dentro del respeto a los principios constitucionales", "Creación de centros docentes, que solo podrán impartir enseñanzas no regladas"]'::jsonb,2,'Art. 27.6 CE','Se reconoce la libertad de creación de centros docentes, dentro del respeto a los principios constitucionales.',null),
('adm-cm:1-a9970a4239','adm-cm',1,'Según el art. 9.2, corresponde a los poderes públicos:','["Promover las condiciones para que la libertad y la igualdad sean reales y efectivas, y remover los obstáculos que lo impidan", "Regular la vida privada de los ciudadanos", "Limitar la participación política", "Garantizar la igualdad de resultados económicos entre todos los ciudadanos y territorios, y suprimir las diferencias de renta que lo impidan"]'::jsonb,0,'Art. 9.2 CE','Deben promover esas condiciones, remover los obstáculos y facilitar la participación de todos los ciudadanos.',null),
('adm-cm:1-b588f93b64','adm-cm',1,'¿Qué regula la ley según el art. 30.2?','["El servicio militar obligatorio, su duración y las causas de exención", "El ejército profesional exclusivamente", "La participación de España en organizaciones internacionales de defensa", "Las obligaciones militares de los españoles y la objeción de conciencia"]'::jsonb,3,'Art. 30.2 CE','La ley fijará las obligaciones militares de los españoles y regulará la objeción de conciencia.',null),
('adm-cm:1-6012ae0e11','adm-cm',1,'Según el art. 42, el Estado orientará su política hacia el retorno de:','["Los trabajadores españoles en el extranjero", "Los capitales invertidos fuera", "Los funcionarios destinados en el exterior", "Los estudiantes de Erasmus"]'::jsonb,0,'Art. 42 CE','El Estado velará por los derechos de los trabajadores españoles en el extranjero y orientará su política hacia su retorno.',null),
('adm-cm:1-5d92cfccc8','adm-cm',1,'El contenido del derecho de propiedad y de herencia lo delimita:','["Las ordenanzas fiscales de cada municipio", "La voluntad del propietario", "Su función social, de acuerdo con las leyes", "El Registro de la Propiedad"]'::jsonb,2,'Art. 33.2 CE','La función social de estos derechos delimitará su contenido, de acuerdo con las leyes.',null),
('adm-cm:1-d32bc6e911','adm-cm',1,'Según el art. 23.1, los ciudadanos participan en los asuntos públicos:','["Solo por medio de los partidos políticos con representación parlamentaria", "Directamente o por medio de representantes elegidos en elecciones periódicas por sufragio censitario", "Por medio de representantes designados por las Cortes Generales y por los Parlamentos autonómicos", "Directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal"]'::jsonb,3,'Art. 23.1 CE','Participan directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.',null),
('adm-cm:1-1e33ef4167','adm-cm',1,'Las bases de la organización militar se regulan mediante:','["Un real decreto", "Una ley ordinaria", "Una ley orgánica", "Una orden del Ministerio de Defensa"]'::jsonb,2,'Art. 8.2 CE','Una ley orgánica regulará las bases de la organización militar.',null),
('adm-cm:1-1343337e82','adm-cm',1,'Según el art. 51.1, los poderes públicos garantizarán la defensa de:','["Los consumidores y usuarios, protegiendo mediante procedimientos eficaces su seguridad, salud e intereses económicos", "Los comerciantes minoristas exclusivamente", "Las empresas frente a la competencia desleal y los productores frente a las importaciones de terceros países", "Los productores agrarios"]'::jsonb,0,'Art. 51.1 CE','Garantizarán la defensa de los consumidores y usuarios mediante procedimientos eficaces.',null),
('adm-cm:1-dddec6d1e2','adm-cm',1,'En el control y la gestión de los centros sostenidos con fondos públicos intervienen:','["Solo la Administración educativa competente", "Los sindicatos más representativos y la Administración", "Solo el director del centro y el titular, en el caso de los centros concertados", "Los profesores, los padres y, en su caso, los alumnos"]'::jsonb,3,'Art. 27.7 CE','Intervienen los profesores, los padres y, en su caso, los alumnos, en los términos que la ley establezca.',null),
('adm-cm:1-88eda7eb15','adm-cm',1,'Según el art. 19, los españoles tienen derecho a:','["Una vivienda pública en su lugar de residencia", "Cambiar de nacionalidad libremente y entrar y salir de España sin requisitos", "Viajar sin pasaporte a cualquier país y residir en el extranjero sin requisitos", "Elegir libremente su residencia y a circular por el territorio nacional"]'::jsonb,3,'Art. 19 CE','Tienen derecho a elegir libremente su residencia y a circular por el territorio nacional.',null),
('adm-cm:1-fc5725de76','adm-cm',1,'¿Quiénes pueden ejercer la iniciativa de reforma constitucional?','["Gobierno, Congreso, Senado, Asambleas de las CCAA y la iniciativa popular con 500.000 firmas", "Gobierno y Congreso, y el Senado solo a propuesta de las Asambleas de las CCAA", "Gobierno, Congreso y Senado, y también la iniciativa popular respaldada por un millón de firmas", "Gobierno, Congreso, Senado y Asambleas de las CCAA, pero no la iniciativa popular"]'::jsonb,3,'Art. 166 CE','La iniciativa se ejerce según los apartados 1 y 2 del art. 87, que no incluyen la iniciativa popular del art. 87.3.',null),
('adm-cm:1-f18610d35f','adm-cm',1,'Por el procedimiento ordinario del art. 167 CE, los proyectos de reforma constitucional deben aprobarse por:','["Mayoría absoluta de cada una de las Cámaras", "Mayoría de tres quintos de cada una de las Cámaras", "Mayoría de dos tercios de cada una de las Cámaras", "Mayoría de tres quintos del Congreso y absoluta del Senado"]'::jsonb,1,'Art. 167.1 CE','Si no hay acuerdo entre las Cámaras, se intenta obtenerlo mediante una comisión de composición paritaria de Diputados y Senadores.',null),
('adm-cm:1-71a98c43b8','adm-cm',1,'Si no se logra la aprobación de una reforma por el procedimiento del art. 167.1 CE, el Congreso podrá aprobarla:','["Por mayoría absoluta, siempre que el texto hubiera obtenido la mayoría de tres quintos del Senado", "Por mayoría de dos tercios, siempre que el texto hubiera obtenido la mayoría absoluta del Senado", "Por mayoría de dos tercios, aunque el Senado haya rechazado el texto por mayoría absoluta", "Por mayoría de tres quintos, siempre que el texto se someta después a referéndum obligatorio de todos los españoles"]'::jsonb,1,'Art. 167.2 CE','Así lo prevé el art. 167.2 CE.',null),
('adm-cm:1-2c38ddfac5','adm-cm',1,'En la reforma por el procedimiento del art. 167 CE, el referéndum es:','["Facultativo: se celebra si lo solicita, en los 15 días siguientes a la aprobación, una décima parte de los miembros de cualquiera de las Cámaras", "Facultativo: se celebra si lo solicita, en los 15 días siguientes, la mayoría absoluta del Congreso", "Obligatorio en todo caso, y se celebra en los 15 días siguientes a la aprobación del texto por las Cortes Generales, con independencia de lo que soliciten las Cámaras", "Facultativo: se celebra si lo solicitan, en los 30 días siguientes, 50 Diputados o 50 Senadores"]'::jsonb,0,'Art. 167.3 CE','En el procedimiento agravado del art. 168, en cambio, el referéndum es obligatorio.',null),
('adm-cm:1-0d63b2aca2','adm-cm',1,'La revisión total de la Constitución o una parcial que afecte al Título preliminar, a la Sección 1.ª del Capítulo II del Título I o al Título II exige:','["Aprobación por tres quintos de cada Cámara, disolución inmediata de las Cortes y referéndum facultativo", "Aprobación por mayoría absoluta de cada Cámara, disolución inmediata de las Cortes y referéndum obligatorio", "Aprobación por dos tercios de cada Cámara, disolución inmediata de las Cortes, ratificación por las nuevas Cámaras y referéndum", "Aprobación por dos tercios del Congreso y mayoría absoluta del Senado, y después referéndum obligatorio"]'::jsonb,2,'Art. 168 CE','Las nuevas Cámaras deben ratificar la decisión, estudiar el nuevo texto y aprobarlo por mayoría de dos tercios de ambas.',null),
('adm-cm:1-7c7ec76c97','adm-cm',1,'¿Cuándo no podrá iniciarse la reforma constitucional?','["Durante la regencia o la minoría de edad del Rey", "Durante el último año de la legislatura o mientras haya un proceso electoral convocado", "En tiempo de guerra o de vigencia de alguno de los estados del art. 116", "Mientras esté pendiente de resolver un recurso de inconstitucionalidad contra una ley orgánica"]'::jsonb,2,'Art. 169 CE','Los estados del art. 116 son los de alarma, excepción y sitio.',null),
('adm-cm:1-2510d908c7','adm-cm',1,'Según el art. 54 CE, el Defensor del Pueblo es:','["Alto comisionado del Gobierno, designado por el Consejo de Ministros para supervisar a la Administración", "Alto comisionado de las Cortes Generales, designado por estas para la defensa de los derechos del Título I", "Alto comisionado de las Cortes Generales, designado por el Rey a propuesta del Congreso", "Órgano del Poder Judicial encargado de la defensa de los derechos fundamentales"]'::jsonb,1,'Art. 54 CE','Puede supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.',null),
('adm-cm:1-cf4c8100e5','adm-cm',1,'La reforma del artículo 49 de la Constitución aprobada en 2024 sustituyó la expresión «disminuidos físicos, sensoriales y psíquicos» por:','["Personas con discapacidad", "Personas dependientes", "Personas con capacidades diferentes", "Personas con diversidad funcional"]'::jsonb,0,'Art. 49 CE (reforma de 17 de febrero de 2024)','Fue la tercera reforma de la Constitución, tras las de 1992 (art. 13.2) y 2011 (art. 135).',null),
('adm-cm:2-fb98aca8a3','adm-cm',2,'Son leyes orgánicas, entre otras, las relativas a:','["Los presupuestos generales del Estado, los Estatutos de Autonomía, el régimen electoral y los tributos", "El desarrollo de los derechos fundamentales, el sistema tributario y las bases del régimen local", "Las bases del régimen local, los Estatutos de Autonomía y el régimen electoral", "El desarrollo de los derechos fundamentales, los Estatutos de Autonomía y el régimen electoral"]'::jsonb,3,'Art. 81.1 CE','Son orgánicas las relativas al desarrollo de los derechos fundamentales y libertades públicas, las que aprueban los Estatutos de Autonomía y el régimen electoral general, y las demás previstas en la Constitución.',null),
('adm-cm:2-654f8dd0a2','adm-cm',2,'La aprobación, modificación o derogación de las leyes orgánicas exige:','["Mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto", "Mayoría absoluta de ambas Cámaras en una votación final sobre el conjunto", "Mayoría de tres quintos del Congreso en una votación final sobre el conjunto", "Mayoría absoluta del Congreso en la votación de cada uno de los artículos"]'::jsonb,0,'Art. 81.2 CE','Exige mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto.',null),
('adm-cm:2-04daea9a6b','adm-cm',2,'¿Puede delegarse en el Gobierno la potestad de dictar normas con rango de ley sobre materias reservadas a ley orgánica?','["Sí, siempre", "No", "Sí, con autorización del Rey", "Sí, mediante ley de bases"]'::jsonb,1,'Art. 82.1 CE','La delegación solo cabe en materias que no sean objeto de ley orgánica.',null),
('adm-cm:2-2890c8c962','adm-cm',2,'¿Qué ley se usa para delegar la formación de textos articulados?','["Una ley orgánica", "Un decreto-ley", "Una ley de bases", "Una ley ordinaria de refundición"]'::jsonb,2,'Art. 82.2 CE','Para textos articulados se usa una ley de bases; para refundir varios textos legales, una ley ordinaria.','abr. 2026 · 1.er ejercicio'),
('adm-cm:2-db022408ca','adm-cm',2,'La delegación legislativa al Gobierno:','["Puede ser expresa o implícita, para materia concreta y con plazo", "Debe ser expresa, para materia concreta, y puede darse por tiempo indefinido", "Debe ser expresa y puede subdelegarse en los ministros", "Debe ser expresa, para materia concreta y con fijación del plazo"]'::jsonb,3,'Art. 82.3 CE','Debe otorgarse de forma expresa, para materia concreta y con plazo; no puede ser implícita, indefinida ni subdelegarse a autoridades distintas del Gobierno.',null),
('adm-cm:2-fa577abab8','adm-cm',2,'Las disposiciones del Gobierno que contienen legislación delegada se denominan:','["Decretos Legislativos", "Decretos-leyes", "Reales Decretos", "Órdenes ministeriales"]'::jsonb,0,'Art. 85 CE','Reciben el título de Decretos Legislativos.','nov. 2024 · 1.er ejercicio'),
('adm-cm:2-a395b423e3','adm-cm',2,'El Gobierno puede dictar decretos-leyes:','["En cualquier materia y circunstancia", "En caso de extraordinaria y urgente necesidad", "Solo con autorización previa del Congreso", "Solo durante el estado de alarma"]'::jsonb,1,'Art. 86.1 CE','Puede dictarlos en caso de extraordinaria y urgente necesidad, como disposiciones legislativas provisionales.','oct. 2026 · 1.er ejercicio'),
('adm-cm:2-c085bdf60c','adm-cm',2,'Un decreto-ley NO puede afectar a:','["Las medidas económicas urgentes", "La organización de servicios administrativos", "El régimen de las Comunidades Autónomas", "Las ayudas a sectores afectados por una catástrofe"]'::jsonb,2,'Art. 86.1 CE','No puede afectar al ordenamiento de las instituciones básicas del Estado, a los derechos del Título I, al régimen de las CCAA ni al Derecho electoral general.',null),
('adm-cm:2-e60bc2ca7a','adm-cm',2,'¿En qué plazo debe someterse un decreto-ley a debate y votación de totalidad en el Congreso?','["Quince días siguientes a su promulgación", "Un mes siguiente a su publicación en el Boletín Oficial del Estado", "Sesenta días siguientes a su promulgación", "Treinta días siguientes a su promulgación"]'::jsonb,3,'Art. 86.2 CE','Debe someterse a debate y votación de totalidad en los treinta días siguientes a su promulgación.',null),
('adm-cm:2-e013a0e275','adm-cm',2,'La iniciativa legislativa popular exige:','["No menos de 100.000 firmas acreditadas", "No menos de 500.000 firmas acreditadas", "No menos de 1.000.000 de firmas acreditadas ante la Junta Electoral Central", "No menos de 250.000 firmas acreditadas"]'::jsonb,1,'Art. 87.3 CE','Exige no menos de 500.000 firmas acreditadas y no procede en materias de ley orgánica, tributarias, internacionales ni de prerrogativa de gracia.',null),
('adm-cm:2-ab6fd12bc4','adm-cm',2,'¿En qué plazo sanciona el Rey las leyes aprobadas por las Cortes Generales?','["Diez días", "Un mes", "Quince días", "Veinte días"]'::jsonb,2,'Art. 91 CE','El Rey sanciona las leyes en el plazo de quince días.','oct. 2026 · 1.er ejercicio'),
('adm-cm:2-e68c18ff9c','adm-cm',2,'Los tratados internacionales válidamente celebrados forman parte del ordenamiento interno:','["Desde su firma", "Desde su ratificación por el Rey", "Cuando los aprueba el Consejo de Ministros", "Una vez publicados oficialmente en España"]'::jsonb,3,'Art. 96.1 CE','Forman parte del ordenamiento interno una vez publicados oficialmente en España.',null),
('adm-cm:2-386d8d73aa','adm-cm',2,'Las leyes de bases NO pueden:','["Fijar los principios y criterios que han de seguirse en el ejercicio de la delegación", "Autorizar su propia modificación ni facultar para dictar normas con carácter retroactivo", "Delimitar con precisión el objeto y el alcance de la delegación legislativa", "Fijar el plazo para el ejercicio de la delegación"]'::jsonb,1,'Art. 83 CE','Las leyes de bases no pueden autorizar la modificación de la propia ley de bases ni facultar para dictar normas con carácter retroactivo (art. 83 CE). Sí deben delimitar el objeto y alcance, fijar los principios y criterios (art. 82.4) y el plazo (art. 82.3).',null),
('adm-cm:2-8670679cd6','adm-cm',2,'Durante el plazo de convalidación, las Cortes pueden tramitar los decretos-leyes:','["Como proposiciones de ley por el procedimiento ordinario", "Como proyectos de ley por el procedimiento de urgencia", "Como leyes orgánicas por el procedimiento de lectura única", "Como decretos legislativos sujetos a control parlamentario"]'::jsonb,1,'Art. 86.3 CE','Durante el plazo de treinta días, las Cortes pueden tramitarlos como proyectos de ley por el procedimiento de urgencia.',null),
('adm-cm:2-ae7de1bc86','adm-cm',2,'¿En cuál de estas materias NO procede la iniciativa legislativa popular?','["En materia de vivienda", "En materia de medio ambiente", "En materia de educación no universitaria", "En materias propias de ley orgánica"]'::jsonb,3,'Art. 87.3 CE','No procede en materias propias de ley orgánica, tributarias o de carácter internacional, ni en lo relativo a la prerrogativa de gracia.',null),
('adm-cm:2-98ecaba1f1','adm-cm',2,'Según el art. 56.1 CE, el Rey asume la más alta representación del Estado español:','["En las relaciones internacionales, especialmente con las naciones de su comunidad histórica", "En las relaciones internacionales, salvo en las que se reservan al Ministerio de Asuntos Exteriores", "En las relaciones internacionales, especialmente con los Estados miembros de la Unión Europea", "En las relaciones con las Comunidades Autónomas, especialmente con las de régimen foral"]'::jsonb,0,'Art. 56.1 CE','El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones y asume la más alta representación en las relaciones internacionales, especialmente con las naciones de su comunidad histórica.',null),
('adm-cm:2-63c54144ae','adm-cm',2,'La persona del Rey, según el art. 56.3 CE:','["Es inviolable durante su reinado y responde de sus actos tras la abdicación", "Es inviolable, pero responde civilmente de sus actos privados ante el Tribunal Supremo", "No está sujeta a responsabilidad, salvo por los actos que realice sin refrendo", "Es inviolable y no está sujeta a responsabilidad"]'::jsonb,3,'Art. 56.3 CE','Sus actos estarán siempre refrendados en la forma del art. 64 y carecen de validez sin ese refrendo, salvo lo dispuesto en el art. 65.2.',null),
('adm-cm:2-74f2ae1792','adm-cm',2,'¿Qué dignidad corresponde al heredero de la Corona, según el art. 57.2 CE?','["Príncipe de Viana", "Príncipe de Asturias", "Infante de España", "Príncipe de Gerona"]'::jsonb,1,'Art. 57.2 CE','El Príncipe heredero, desde su nacimiento o desde que se produzca el hecho que origine el llamamiento, tendrá la dignidad de Príncipe de Asturias y los demás títulos vinculados tradicionalmente al sucesor de la Corona.',null),
('adm-cm:2-103df48ec2','adm-cm',2,'Extinguidas todas las líneas llamadas en Derecho a la sucesión de la Corona, ¿quién provee a la sucesión?','["El pueblo español, mediante referéndum consultivo convocado por el Presidente del Gobierno", "Las Cortes Generales, en la forma que más convenga a los intereses de España", "El Congreso de los Diputados, por mayoría absoluta y en votación única", "El Gobierno, mediante real decreto acordado en Consejo de Ministros"]'::jsonb,1,'Art. 57.3 CE','Así lo dispone el art. 57.3 CE.',null),
('adm-cm:2-0c0bd16acc','adm-cm',2,'Las abdicaciones y renuncias y cualquier duda de hecho o de derecho en el orden de sucesión a la Corona se resolverán:','["Por una ley orgánica", "Por acuerdo del Consejo de Estado", "Por una ley ordinaria de las Cortes", "Por un real decreto del Gobierno"]'::jsonb,0,'Art. 57.5 CE','El art. 57.5 CE exige ley orgánica. Así se hizo con la abdicación de Juan Carlos I (LO 3/2014).',null),
('adm-cm:2-184af421d4','adm-cm',2,'Las personas con derecho a la sucesión que contrajeran matrimonio contra la expresa prohibición del Rey y de las Cortes Generales:','["Perderán solo la dignidad de Príncipe o Princesa de Asturias, pero no el derecho a suceder", "Quedarán excluidas de la sucesión por sí y sus descendientes", "Podrán ser rehabilitadas por las Cortes por mayoría absoluta", "Quedarán excluidas de la sucesión, pero no sus descendientes"]'::jsonb,1,'Art. 57.4 CE','La exclusión alcanza a la persona y a sus descendientes.',null),
('adm-cm:2-1d4c4bb2ef','adm-cm',2,'La Reina consorte o el consorte de la Reina, según el art. 58 CE:','["Pueden asumir funciones constitucionales por delegación expresa del Rey, refrendada por el Presidente", "No pueden asumir funciones constitucionales, salvo lo dispuesto para la Regencia", "No pueden asumir funciones constitucionales en ningún caso, ni siquiera la Regencia", "Asumen las funciones del Rey durante sus ausencias del territorio nacional"]'::jsonb,1,'Art. 58 CE','La única excepción es la Regencia.',null),
('adm-cm:2-8d22e9cce9','adm-cm',2,'Cuando el Rey fuere menor de edad, ¿quién ejerce inmediatamente la Regencia?','["Una Regencia de una, tres o cinco personas nombrada por las Cortes Generales", "El pariente mayor de edad más próximo a suceder en la Corona y, en su defecto, el padre o la madre del Rey", "El Presidente del Gobierno, hasta que las Cortes nombren una Regencia de tres personas", "El padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona"]'::jsonb,3,'Art. 59.1 CE','Ejercerá la Regencia durante el tiempo de la minoría de edad del Rey, según el orden establecido en la Constitución.',null),
('adm-cm:2-3c1e09cc08','adm-cm',2,'Si no hubiere ninguna persona a quien corresponda la Regencia, ¿cómo la nombran las Cortes Generales?','["Se compondrá de una o dos personas", "Se compondrá siempre de una sola persona, elegida por las Cortes", "Se compondrá de tres o cinco personas", "Se compondrá de una, tres o cinco personas"]'::jsonb,3,'Art. 59.3 CE','Las Cortes Generales nombran la Regencia, que se compondrá de una, tres o cinco personas.',null),
('adm-cm:2-144611dcc7','adm-cm',2,'Para ejercer la Regencia, según el art. 59.4 CE, es preciso:','["Ser español y mayor de edad", "Ser español de origen y mayor de 30 años", "Ser miembro de la Familia Real y mayor de edad", "Ser español y haber jurado la Constitución ante el Congreso"]'::jsonb,0,'Art. 59.4 CE','La Regencia se ejerce por mandato constitucional y siempre en nombre del Rey.',null),
('adm-cm:2-817f2dc824','adm-cm',2,'La inhabilitación del Rey para el ejercicio de su autoridad debe ser reconocida por:','["El Tribunal Constitucional", "El Consejo de Ministros", "El Tribunal Supremo", "Las Cortes Generales"]'::jsonb,3,'Art. 59.2 CE','Si el Rey se inhabilitare y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero, si fuere mayor de edad.',null),
('adm-cm:2-7c633450a3','adm-cm',2,'¿Quién es tutor del Rey menor, según el art. 60.1 CE, en primer lugar?','["El Presidente del Gobierno, mientras las Cortes no designen otra persona mediante una ley orgánica", "La persona que en su testamento hubiese nombrado el Rey difunto, si es mayor de edad y español de nacimiento", "La persona que designen las Cortes Generales por mayoría de tres quintos", "El padre o la madre del Rey, aunque hayan contraído nuevo matrimonio, y en su defecto quien designen las Cortes"]'::jsonb,1,'Art. 60.1 CE','Si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos; en su defecto, lo nombrarán las Cortes Generales.',null),
('adm-cm:2-b18e6914a4','adm-cm',2,'El Rey, al ser proclamado ante las Cortes Generales:','["No presta juramento, porque su legitimidad deriva directamente de la Constitución", "Prestará juramento de desempeñar fielmente sus funciones, guardar y hacer guardar la Constitución y las leyes y respetar los derechos de los ciudadanos y de las CCAA", "Prometerá ante el Presidente del Tribunal Constitucional cumplir y hacer cumplir la Constitución y las leyes, y respetar los derechos de los ciudadanos y de las Comunidades Autónomas", "Prestará juramento ante el Consejo de Ministros, que levantará acta de la proclamación"]'::jsonb,1,'Art. 61.1 CE','El Príncipe heredero, al alcanzar la mayoría de edad, y el Regente o Regentes, al asumir sus funciones, prestan el mismo juramento y el de fidelidad al Rey (art. 61.2).',null),
('adm-cm:2-49bb0d3cb0','adm-cm',2,'¿Cuál de estas funciones corresponde al Rey según el art. 62 CE?','["Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales", "Ejercer el derecho de gracia con arreglo a la ley, incluidos los indultos generales cuando lo acuerde el Consejo de Ministros", "Dirigir la política exterior del Estado y la Administración militar", "Nombrar a los magistrados del Tribunal Supremo a propuesta del Gobierno, previo informe del Consejo General del Poder Judicial"]'::jsonb,0,'Art. 62 i) CE','La dirección de la política interior y exterior corresponde al Gobierno (art. 97 CE).',null),
('adm-cm:2-cfcf724e8a','adm-cm',2,'Según el art. 62 CE, el Rey preside las sesiones del Consejo de Ministros:','["Cuando lo estime oportuno, a petición del Presidente del Gobierno", "Una vez al trimestre, de forma obligatoria", "Siempre que se deliberen asuntos de Estado o de política exterior", "Nunca, porque es un órgano del Gobierno"]'::jsonb,0,'Art. 62 g) CE','Al Rey le corresponde ser informado de los asuntos de Estado y presidir el Consejo de Ministros cuando lo estime oportuno, a petición del Presidente del Gobierno.',null),
('adm-cm:2-5853c3d1ee','adm-cm',2,'¿A quién corresponde, según el art. 63.3 CE, declarar la guerra y hacer la paz?','["Al Rey, previa deliberación del Consejo de Ministros", "Al Rey, previa autorización de las Cortes Generales", "Al Gobierno, previa autorización del Congreso de los Diputados", "A las Cortes Generales, a propuesta del Rey"]'::jsonb,1,'Art. 63.3 CE','Corresponde al Rey, previa autorización de las Cortes Generales.',null),
('adm-cm:2-0f0cf9f1c4','adm-cm',2,'¿Quién refrenda la propuesta y el nombramiento del Presidente del Gobierno y la disolución prevista en el art. 99 CE?','["El Presidente del Senado, como presidente de las Cortes", "El Presidente del Congreso", "El Ministro de Justicia", "El Presidente del Gobierno en funciones"]'::jsonb,1,'Art. 64.1 CE','El resto de actos del Rey los refrendan el Presidente del Gobierno y, en su caso, los ministros competentes.',null),
('adm-cm:2-28feb89481','adm-cm',2,'De los actos del Rey serán responsables:','["Las personas que los refrenden", "El Gobierno de forma solidaria en todo caso", "El Consejo de Estado, que los informa previamente", "El propio Rey, ante las Cortes Generales"]'::jsonb,0,'Art. 64.2 CE','El refrendo traslada la responsabilidad a quien refrenda.',null),
('adm-cm:2-b611a4a635','adm-cm',2,'Según el art. 65 CE, el Rey recibe de los Presupuestos del Estado una cantidad global para el sostenimiento de su Familia y Casa y:','["La distribuye libremente", "La distribuye según el plan que aprueben las Cortes", "La distribuye con autorización del Ministerio de Hacienda", "Debe justificarla anualmente ante el Tribunal de Cuentas"]'::jsonb,0,'Art. 65.1 CE','Además, nombra y releva libremente a los miembros civiles y militares de su Casa (art. 65.2), actos que no necesitan refrendo.',null),
('adm-cm:2-d4359566ea','adm-cm',2,'Según el art. 66.2 CE, las Cortes Generales:','["Ejercen la potestad legislativa, elaboran los Presupuestos y dirigen la política exterior", "Ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno y tienen las demás competencias que les atribuya la Constitución", "Aprueban los Presupuestos y controlan al Gobierno, pero la potestad legislativa es del Congreso", "Ejercen la potestad legislativa y reglamentaria del Estado y dirigen la Administración General del Estado"]'::jsonb,1,'Art. 66.2 CE','Las Cortes representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado (art. 66.1).',null),
('adm-cm:2-157cecf5ee','adm-cm',2,'Según el art. 67 CE, los miembros de las Cortes Generales:','["Están ligados por el mandato del partido con el que concurrieron a las elecciones, salvo en votaciones secretas", "No están ligados por mandato imperativo", "Pueden ser a la vez Diputados y Senadores si lo autoriza la Mesa", "Pueden acumular el acta de Diputado con la de una Asamblea autonómica"]'::jsonb,1,'Art. 67.2 CE','Nadie puede ser miembro de las dos Cámaras simultáneamente ni acumular el acta de una Asamblea de CA con la de Diputado al Congreso (art. 67.1).',null),
('adm-cm:2-66fada6957','adm-cm',2,'¿Entre qué número mínimo y máximo de Diputados puede componerse el Congreso según la Constitución?','["Entre 250 y 400", "Entre 350 y 400", "Entre 300 y 350", "Entre 300 y 400"]'::jsonb,3,'Art. 68.1 CE','La Constitución fija la horquilla y la LOREG concreta el número en 350.',null),
('adm-cm:2-8c0ade8b3a','adm-cm',2,'Según el art. 68 CE, la circunscripción electoral para el Congreso es:','["La Comunidad Autónoma, y Ceuta y Melilla están representadas cada una por dos Diputados", "El municipio de más de 50.000 habitantes y, en los demás casos, la provincia", "La provincia, y Ceuta y Melilla están representadas cada una por un Diputado", "La provincia, y Ceuta y Melilla están representadas cada una por dos Diputados"]'::jsonb,2,'Art. 68.2 CE','La elección se verifica en cada circunscripción atendiendo a criterios de representación proporcional (art. 68.3).',null),
('adm-cm:2-b731f9c143','adm-cm',2,'Las elecciones generales deben tener lugar:','["Entre los 45 y 90 días desde la terminación del mandato", "En los 60 días siguientes a la disolución, sin plazo mínimo", "Entre los 30 y 60 días desde la terminación del mandato", "Entre los 15 y 30 días desde la terminación del mandato"]'::jsonb,2,'Art. 68.6 CE','El Congreso electo debe ser convocado dentro de los 25 días siguientes a la celebración de las elecciones.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:2-7845853d2a','adm-cm',2,'El Congreso electo deberá ser convocado dentro de los:','["25 días siguientes a la celebración de las elecciones", "30 días siguientes a la celebración de las elecciones", "15 días siguientes a la proclamación de los electos", "25 días siguientes a la publicación de los resultados en el BOE"]'::jsonb,0,'Art. 68.6 CE','Así lo dispone el art. 68.6 CE.',null),
('adm-cm:2-89a353efbb','adm-cm',2,'¿Cuántos Senadores elige cada una de las ciudades de Ceuta y Melilla?','["1", "3", "2", "4"]'::jsonb,2,'Art. 69.4 CE','Las provincias eligen 4 Senadores cada una por sufragio universal, libre, igual, directo y secreto.',null),
('adm-cm:2-a5bed08fc5','adm-cm',2,'Las Comunidades Autónomas designan para el Senado:','["Un Senador por cada 500.000 habitantes de su territorio", "Dos Senadores y otro más por cada millón de habitantes de su territorio", "Un Senador por cada provincia de la Comunidad", "Un Senador y otro más por cada millón de habitantes de su territorio"]'::jsonb,3,'Art. 69.5 CE','La designación corresponde a la Asamblea legislativa o, en su defecto, al órgano colegiado superior de la CA, asegurando la representación proporcional.',null),
('adm-cm:2-36069dba0b','adm-cm',2,'Durante su mandato, los Diputados y Senadores solo podrán ser detenidos:','["Con autorización previa del Tribunal Supremo, salvo flagrante delito", "En ningún caso, mientras dure su mandato", "En caso de flagrante delito", "En caso de delito grave, con autorización del Presidente de la Cámara"]'::jsonb,2,'Art. 71.2 CE','Gozan de inmunidad: no pueden ser inculpados ni procesados sin la previa autorización de la Cámara respectiva.',null),
('adm-cm:2-d5d016fd8b','adm-cm',2,'¿Qué órgano es competente en las causas contra Diputados y Senadores?','["El Tribunal Superior de Justicia de su circunscripción", "La Sala de lo Penal de la Audiencia Nacional", "La Sala de lo Penal del Tribunal Supremo", "El Tribunal Constitucional, en única instancia"]'::jsonb,2,'Art. 71.3 CE','Así lo establece el art. 71.3 CE.',null),
('adm-cm:2-03157ea0f3','adm-cm',2,'Los Reglamentos de las Cámaras y su reforma se aprueban:','["Por mayoría absoluta de las Cortes reunidas en sesión conjunta", "Por mayoría de tres quintos, en una votación final sobre su totalidad", "Por mayoría absoluta, en una votación final sobre su totalidad", "Por mayoría simple, artículo por artículo"]'::jsonb,2,'Art. 72.1 CE','Las Cámaras establecen sus propios Reglamentos y aprueban autónomamente sus presupuestos.',null),
('adm-cm:2-59937454e9','adm-cm',2,'Las sesiones conjuntas de ambas Cámaras están presididas por:','["El Presidente de mayor edad", "El Rey", "El Presidente del Congreso", "El Presidente del Senado"]'::jsonb,2,'Art. 72.2 CE','Se rigen por un Reglamento de las Cortes Generales aprobado por mayoría absoluta de cada Cámara.',null),
('adm-cm:2-bbfe755eed','adm-cm',2,'¿Cuáles son los períodos ordinarios de sesiones de las Cámaras?','["De octubre a diciembre y de febrero a julio", "De septiembre a junio, sin interrupción", "De septiembre a diciembre y de febrero a junio", "De septiembre a diciembre y de enero a junio"]'::jsonb,2,'Art. 73.1 CE','Las Cámaras se reúnen anualmente en dos períodos ordinarios de sesiones.',null),
('adm-cm:2-ca9b294f85','adm-cm',2,'Las sesiones extraordinarias de las Cámaras pueden celebrarse a petición de:','["El Gobierno o la Diputación Permanente, pero no de los miembros de las Cámaras", "El Rey, el Gobierno o una quinta parte de los miembros de cualquiera de las Cámaras", "El Gobierno, la Diputación Permanente o la mayoría absoluta de los miembros de cualquiera de las Cámaras", "El Presidente del Gobierno, la Mesa del Congreso o la mitad de los grupos parlamentarios"]'::jsonb,2,'Art. 73.2 CE','Se convocan sobre un orden del día determinado y se clausuran una vez que este haya sido agotado.',null),
('adm-cm:2-b7380bf824','adm-cm',2,'¿Cuál de estas materias NO puede delegar el Pleno en las Comisiones Legislativas Permanentes?','["Una ley ordinaria sobre carreteras del Estado", "Los Presupuestos Generales del Estado", "Una ley sobre el régimen de las asociaciones de consumidores", "Una ley sobre el régimen de los colegios profesionales"]'::jsonb,1,'Art. 75.3 CE','Tampoco la reforma constitucional, las cuestiones internacionales, ni las leyes orgánicas y de bases.',null),
('adm-cm:2-de517903ec','adm-cm',2,'Las conclusiones de las comisiones de investigación de las Cámaras:','["Se remiten siempre al Tribunal Supremo, que decide si abre causa", "No son vinculantes para los Tribunales ni afectan a las resoluciones judiciales", "Vinculan a la Administración, que debe ejecutarlas en el plazo de un mes", "Son vinculantes para los Tribunales cuando se refieran a hechos delictivos"]'::jsonb,1,'Art. 76.1 CE','El resultado puede comunicarse al Ministerio Fiscal para el ejercicio de las acciones oportunas, y es obligatorio comparecer a requerimiento de las Cámaras (art. 76.2).',null),
('adm-cm:2-b7f04d549c','adm-cm',2,'¿Cuántos miembros como mínimo tiene la Diputación Permanente de cada Cámara?','["15", "25", "30", "21"]'::jsonb,3,'Art. 78.1 CE','Representan a los grupos parlamentarios en proporción a su importancia numérica y la preside el Presidente de la Cámara.',null),
('adm-cm:2-42f7afcbef','adm-cm',2,'Para adoptar acuerdos, las Cámaras deben estar reunidas reglamentariamente y con asistencia de:','["La mayoría de sus miembros", "Cualquier número de miembros", "Dos tercios de sus miembros", "Un tercio de sus miembros"]'::jsonb,0,'Art. 79.1 CE','Los acuerdos se aprueban, en general, por mayoría de los miembros presentes (art. 79.2).',null),
('adm-cm:2-ac6d05454d','adm-cm',2,'Según el art. 79.3 CE, el voto de Senadores y Diputados:','["Es personal, pero puede delegarse en otro miembro del mismo grupo", "Es personal, pero el portavoz puede emitirlo por todo el grupo", "Es indelegable, salvo enfermedad acreditada ante la Mesa", "Es personal e indelegable"]'::jsonb,3,'Art. 79.3 CE','Así lo dispone el art. 79.3 CE.',null),
('adm-cm:2-2649ce91d5','adm-cm',2,'Las sesiones plenarias de las Cámaras serán públicas:','["Salvo acuerdo en contrario de cada Cámara por mayoría absoluta o con arreglo al Reglamento", "Salvo acuerdo en contrario de la Mesa de cada Cámara", "En todo caso, sin excepción", "Salvo que lo solicite el Gobierno por razones de seguridad nacional, aunque no lo acuerde la Cámara"]'::jsonb,0,'Art. 80 CE','Así lo dispone el art. 80 CE.',null),
('adm-cm:2-a899c2ae85','adm-cm',2,'¿Quién tiene la iniciativa legislativa según el art. 87.1 CE?','["El Gobierno y el Congreso, pero no el Senado", "El Gobierno, el Congreso, el Senado y el Consejo General del Poder Judicial", "El Congreso y el Senado, y el Gobierno solo en materia presupuestaria", "El Gobierno, el Congreso y el Senado"]'::jsonb,3,'Art. 87.1 CE','Las Asambleas de las CCAA pueden solicitar al Gobierno la adopción de un proyecto o remitir a la Mesa del Congreso una proposición (art. 87.2), y existe la iniciativa popular (art. 87.3).',null),
('adm-cm:2-5815a98c03','adm-cm',2,'¿Cuántas firmas acreditadas exige como mínimo la iniciativa legislativa popular?','["100.000", "1.000.000", "250.000", "500.000"]'::jsonb,3,'Art. 87.3 CE','No procede en materias propias de ley orgánica, tributarias, de carácter internacional ni en lo relativo a la prerrogativa de gracia.',null),
('adm-cm:2-1bafb22362','adm-cm',2,'Una Asamblea de Comunidad Autónoma que remite una proposición de ley a la Mesa del Congreso puede delegar su defensa ante esta Cámara en:','["Un máximo de tres miembros de la Asamblea", "Los Senadores designados por la Comunidad", "Un máximo de cinco miembros de la Asamblea", "El Presidente de la Comunidad Autónoma"]'::jsonb,0,'Art. 87.2 CE','Así lo dispone el art. 87.2 CE.',null),
('adm-cm:2-cdbfecbbb1','adm-cm',2,'¿En qué plazo puede el Senado oponer su veto o introducir enmiendas a un proyecto aprobado por el Congreso?','["Dos meses desde la aprobación en el Congreso, o un mes si el proyecto se declara urgente", "Dos meses desde el día de la recepción del texto, o veinte días naturales si el proyecto se declara urgente", "Un mes desde la recepción del texto, o diez días naturales si el proyecto se declara urgente", "Tres meses desde la recepción del texto, sin reducción por urgencia"]'::jsonb,1,'Art. 90.2 y 90.3 CE','El veto debe aprobarse por mayoría absoluta del Senado.',null),
('adm-cm:2-aa6457d0e9','adm-cm',2,'El veto del Senado puede ser levantado por el Congreso:','["Por mayoría de tres quintos, o por mayoría absoluta una vez transcurrido un mes", "Por mayoría de dos tercios, en sesión conjunta con el Senado", "Por mayoría absoluta, o por mayoría simple una vez transcurridos dos meses desde su interposición", "Por mayoría simple en todo caso, en una nueva votación"]'::jsonb,2,'Art. 90.2 CE','Así lo dispone el art. 90.2 CE.',null),
('adm-cm:2-5dad497147','adm-cm',2,'El Rey sancionará las leyes aprobadas por las Cortes Generales en el plazo de:','["20 días", "10 días", "30 días", "15 días"]'::jsonb,3,'Art. 91 CE','Las promulgará y ordenará su inmediata publicación.',null),
('adm-cm:2-32ce509c98','adm-cm',2,'El referéndum consultivo sobre decisiones políticas de especial trascendencia es convocado por:','["El Presidente del Gobierno, previa autorización de las Cortes Generales por mayoría absoluta", "El Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso", "El Rey, a propuesta del Congreso de los Diputados por mayoría de tres quintos", "El Gobierno, previa deliberación del Consejo de Ministros y dictamen del Consejo de Estado"]'::jsonb,1,'Art. 92.2 CE','Lo regula la LO 2/1980.',null),
('adm-cm:2-0d82b2c6ce','adm-cm',2,'Los tratados por los que se atribuya a una organización internacional el ejercicio de competencias derivadas de la Constitución se autorizan:','["Por acuerdo del Consejo de Ministros", "Mediante ley orgánica", "Mediante referéndum", "Mediante ley ordinaria"]'::jsonb,1,'Art. 93 CE','Así se autorizó la adhesión de España a las Comunidades Europeas.',null),
('adm-cm:3-be054887ab','adm-cm',3,'¿Cuántos miembros tiene el Tribunal Constitucional?','["15", "9", "10", "12"]'::jsonb,3,'Art. 159.1 CE','Los nombra el Rey: 4 a propuesta del Congreso, 4 del Senado, 2 del Gobierno y 2 del Consejo General del Poder Judicial.',null),
('adm-cm:3-30242686e1','adm-cm',3,'¿Cuántos magistrados del Tribunal Constitucional se nombran a propuesta del Gobierno?','["2", "4", "1", "3"]'::jsonb,0,'Art. 159.1 CE','Congreso y Senado proponen 4 cada uno, por mayoría de tres quintos; el Gobierno, 2; y el CGPJ, 2.',null),
('adm-cm:3-720e09aee7','adm-cm',3,'Los magistrados propuestos por el Congreso y el Senado para el Tribunal Constitucional requieren:','["Mayoría de tres quintos de sus miembros", "Mayoría absoluta de sus miembros, en primera votación", "Mayoría de dos tercios de sus miembros, en votación única", "Mayoría simple de los presentes"]'::jsonb,0,'Art. 159.1 CE','Cuatro a propuesta de cada Cámara, por mayoría de tres quintos de sus miembros.',null),
('adm-cm:3-c13fc40526','adm-cm',3,'Los miembros del Tribunal Constitucional deben ser juristas de reconocida competencia con más de:','["20 años de ejercicio profesional", "10 años de ejercicio profesional", "12 años de ejercicio profesional", "15 años de ejercicio profesional"]'::jsonb,3,'Art. 159.2 CE','Se nombran entre magistrados y fiscales, profesores de universidad, funcionarios públicos y abogados.',null),
('adm-cm:3-ea6e2a1beb','adm-cm',3,'¿Por cuánto tiempo son designados los miembros del Tribunal Constitucional y cómo se renueva?','["Por 9 años, renovándose por terceras partes cada 3 años", "Por 6 años, renovándose por mitades cada 3 años", "Por 12 años, renovándose por terceras partes cada 4 años", "Por 9 años, renovándose por mitades cada 4 años y medio"]'::jsonb,0,'Art. 159.3 CE','Así lo dispone el art. 159.3 CE.',null),
('adm-cm:3-aea48dd5be','adm-cm',3,'El Presidente del Tribunal Constitucional es nombrado por el Rey:','["Entre sus miembros, a propuesta del mismo Tribunal en pleno y por un período de tres años", "Entre juristas de reconocida competencia con más de quince años de ejercicio, a propuesta del Congreso, por tres años", "Entre sus miembros, a propuesta del Gobierno, oído el Pleno, y por un período de nueve años", "Entre sus miembros, a propuesta del CGPJ y por un período de cuatro años"]'::jsonb,0,'Art. 160 CE','El Pleno propone y el Rey nombra, por tres años.',null),
('adm-cm:3-747c5c0d64','adm-cm',3,'¿Quiénes están legitimados para interponer el recurso de inconstitucionalidad?','["El Presidente del Gobierno, el Ministerio Fiscal, 50 Diputados, 50 Senadores y los Presidentes y Asambleas de las Comunidades Autónomas", "Cualquier persona natural o jurídica que invoque un interés legítimo, además del Defensor del Pueblo", "El Presidente del Gobierno, el Defensor del Pueblo, 30 Diputados, 30 Senadores y las Asambleas de las CCAA", "El Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores y los órganos colegiados ejecutivos y Asambleas de las CCAA"]'::jsonb,3,'Art. 162.1 a) CE','El Ministerio Fiscal no está legitimado para el recurso de inconstitucionalidad, sí para el de amparo.',null),
('adm-cm:3-8a731e9dab','adm-cm',3,'¿Quiénes están legitimados para interponer el recurso de amparo?','["Toda persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y el Ministerio Fiscal", "El Defensor del Pueblo y el Ministerio Fiscal, a instancia de la persona afectada, que no puede recurrir por sí misma", "Solo la persona directamente afectada por la vulneración del derecho fundamental, asistida de abogado y representada por procurador", "Toda persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y 50 Diputados"]'::jsonb,0,'Art. 162.1 b) CE','Así lo dispone el art. 162.1 b) CE.',null),
('adm-cm:3-f177e2b2ca','adm-cm',3,'Cuando el Gobierno impugna ante el Tribunal Constitucional disposiciones y resoluciones de las CCAA, la impugnación produce la suspensión, que el Tribunal debe ratificar o levantar en un plazo no superior a:','["3 meses", "5 meses", "2 meses", "6 meses"]'::jsonb,1,'Art. 161.2 CE','La suspensión es automática y el Tribunal la ratifica o levanta en un plazo no superior a cinco meses.',null),
('adm-cm:3-306228a347','adm-cm',3,'La cuestión de inconstitucionalidad la plantea:','["El Ministerio Fiscal en cualquier proceso, antes de que se dicte sentencia firme por el órgano judicial", "Un órgano judicial que considere que una norma con rango de ley aplicable al caso pueda ser contraria a la Constitución", "El Defensor del Pueblo cuando una ley vulnere derechos fundamentales, en el plazo de tres meses", "Cualquier ciudadano afectado por una norma con rango de ley que considere inconstitucional, en el plazo de tres meses desde su publicación"]'::jsonb,1,'Art. 163 CE','En ningún caso tiene efectos suspensivos.',null),
('adm-cm:3-28a4c7bb3f','adm-cm',3,'Las sentencias del Tribunal Constitucional tienen el valor de cosa juzgada:','["A partir del día siguiente de su publicación, y no cabe recurso alguno contra ellas", "A partir de su notificación a las partes, y contra ellas cabe recurso de súplica ante el Pleno", "A partir de su publicación en el BOE con los votos particulares, pero cabe recurso ante el Tribunal Supremo", "A partir de los veinte días de su publicación, y no cabe recurso contra ellas"]'::jsonb,0,'Art. 164.1 CE','Se publican en el BOE con los votos particulares, si los hubiere.',null),
('adm-cm:3-a855a606c5','adm-cm',3,'¿Qué órgano NO puede proponer magistrados del Tribunal Constitucional?','["El Gobierno", "El Senado", "El Consejo General del Poder Judicial", "El Tribunal Supremo"]'::jsonb,3,'Art. 159.1 CE','Proponen el Congreso, el Senado, el Gobierno y el CGPJ.',null),
('adm-cm:3-ccf2a123c6','adm-cm',3,'Según el art. 117.1 CE, la justicia emana del pueblo y se administra:','["En nombre del pueblo español por Jueces, Magistrados y Fiscales integrantes del poder judicial", "En nombre del Rey por el Consejo General del Poder Judicial", "En nombre de las Cortes Generales por Jueces y Magistrados", "En nombre del Rey por Jueces y Magistrados integrantes del poder judicial"]'::jsonb,3,'Art. 117.1 CE','Los Jueces y Magistrados son independientes, inamovibles, responsables y están sometidos únicamente al imperio de la ley.',null),
('adm-cm:3-a26059838c','adm-cm',3,'¿Cuál de estas notas NO atribuye el art. 117.1 CE a los Jueces y Magistrados?','["Responsabilidad", "Inamovilidad", "Independencia", "Jerarquía"]'::jsonb,3,'Art. 117.1 CE','Son independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley. La dependencia jerárquica es un principio del Ministerio Fiscal (art. 124.2).',null),
('adm-cm:3-9aacfeb794','adm-cm',3,'Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados:','["En ningún caso antes de cumplir la edad de jubilación forzosa", "Sino por alguna de las causas y con las garantías previstas en la ley", "Sino por sentencia firme de la Sala de lo Penal del Tribunal Supremo, a instancia del Ministerio Fiscal", "Sino por acuerdo del Ministerio de Justicia, oído el interesado"]'::jsonb,1,'Art. 117.2 CE','Es la garantía de inamovilidad.',null),
('adm-cm:3-b1190fe5a7','adm-cm',3,'El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde:','["A los Juzgados y Tribunales y, en materia administrativa, a los órganos de la Administración", "A los Juzgados y Tribunales, salvo la ejecución, que corresponde al Gobierno", "Exclusivamente a los Juzgados y Tribunales determinados por las leyes", "Al Consejo General del Poder Judicial y a los Juzgados y Tribunales"]'::jsonb,2,'Art. 117.3 CE','Se ejerce en todo tipo de procesos, según las normas de competencia y procedimiento que las leyes establezcan.',null),
('adm-cm:3-e53aaab0d3','adm-cm',3,'Según el art. 117.6 CE, los Tribunales de excepción:','["Pueden crearse por ley orgánica", "Están prohibidos", "Solo pueden crearse durante el estado de sitio", "Dependen del Tribunal Supremo"]'::jsonb,1,'Art. 117.6 CE','La ley regula la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio (art. 117.5).',null),
('adm-cm:3-bf2d6a27e1','adm-cm',3,'La justicia será gratuita, según el art. 119 CE:','["Solo para quienes acrediten insuficiencia de recursos, sin otros supuestos", "Solo en los procesos penales y en los procesos laborales", "Cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar", "Siempre, para todos los ciudadanos españoles y para los extranjeros residentes legalmente en España, en cualquier proceso"]'::jsonb,2,'Art. 119 CE','Así lo dispone el art. 119 CE.',null),
('adm-cm:3-f016e0d4db','adm-cm',3,'Según el art. 120 CE, el procedimiento judicial:','["Será oral en todo caso y en todas las jurisdicciones", "Será secreto salvo en el acto del juicio", "Será predominantemente oral, sobre todo en materia criminal", "Será predominantemente escrito, salvo en materia criminal, en la que será oral"]'::jsonb,2,'Art. 120.2 CE','Las actuaciones judiciales son públicas, con las excepciones que prevean las leyes de procedimiento (art. 120.1).',null),
('adm-cm:3-d1d865c88e','adm-cm',3,'Las sentencias, según el art. 120.3 CE:','["Se pronunciarán en audiencia pública solo en materia penal", "Se notificarán por escrito y no se pronuncian en audiencia pública", "Serán motivadas solo cuando sean condenatorias", "Serán siempre motivadas y se pronunciarán en audiencia pública"]'::jsonb,3,'Art. 120.3 CE','Así lo dispone el art. 120.3 CE.',null),
('adm-cm:3-c584a84460','adm-cm',3,'Los daños causados por error judicial y los que sean consecuencia del funcionamiento anormal de la Administración de Justicia:','["Darán derecho a una indemnización a cargo del Estado, conforme a la ley", "Darán derecho a indemnización a cargo del Consejo General del Poder Judicial", "No darán derecho a indemnización, salvo que exista dolo", "Darán derecho a una indemnización a cargo del juez o magistrado responsable"]'::jsonb,0,'Art. 121 CE','Así lo dispone el art. 121 CE.',null),
('adm-cm:3-9f8b6371c0','adm-cm',3,'¿Cuál es el órgano de gobierno del Poder Judicial?','["El Tribunal Constitucional, a través de su Pleno", "El Tribunal Supremo", "El Consejo General del Poder Judicial", "El Ministerio de Justicia"]'::jsonb,2,'Art. 122.2 CE','La ley orgánica establece su estatuto, régimen de incompatibilidades y funciones, en particular en nombramientos, ascensos, inspección y régimen disciplinario.',null),
('adm-cm:3-9c76f56aa3','adm-cm',3,'Según el art. 122.3 CE, el Consejo General del Poder Judicial está integrado por:','["El Ministro de Justicia, que lo preside, y veinte miembros nombrados por el Rey por cinco años", "El Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cuatro años", "El Presidente del Tribunal Supremo, que lo preside, y doce miembros nombrados por el Rey por cinco años", "El Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cinco años"]'::jsonb,3,'Art. 122.3 CE','De los veinte vocales, doce son Jueces y Magistrados y ocho se nombran a propuesta de las Cámaras.',null),
('adm-cm:3-d56733cda2','adm-cm',3,'De los veinte vocales del CGPJ, ¿cuántos se eligen entre Jueces y Magistrados de todas las categorías judiciales?','["12", "8", "10", "16"]'::jsonb,0,'Art. 122.3 CE','Los otros ocho los proponen el Congreso (cuatro) y el Senado (cuatro), por mayoría de tres quintos.',null),
('adm-cm:3-ab487ad74a','adm-cm',3,'Los vocales del CGPJ propuestos por las Cámaras se eligen entre:','["Magistrados del Tribunal Supremo con más de quince años de antigüedad en la carrera", "Abogados y otros juristas de reconocida competencia con más de quince años de ejercicio en su profesión", "Abogados y otros juristas de reconocida competencia con más de diez años de ejercicio en su profesión", "Catedráticos de Derecho y fiscales con más de veinte años de ejercicio profesional"]'::jsonb,1,'Art. 122.3 CE','Cuatro a propuesta del Congreso y cuatro a propuesta del Senado, elegidos en ambos casos por mayoría de tres quintos.',null),
('adm-cm:3-92cf030f12','adm-cm',3,'Según el art. 123 CE, el Tribunal Supremo:','["Es el órgano de gobierno del Poder Judicial y el superior en todos los órdenes", "Es el órgano jurisdiccional superior en todos los órdenes, incluida la materia de garantías constitucionales y el recurso de amparo", "Es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales", "Es el órgano jurisdiccional superior solo en el orden penal y en el contencioso-administrativo"]'::jsonb,2,'Art. 123.1 CE','Tiene jurisdicción en toda España. En garantías constitucionales, el órgano superior es el Tribunal Constitucional.',null),
('adm-cm:3-785849a1a7','adm-cm',3,'El Presidente del Tribunal Supremo será nombrado por el Rey:','["A propuesta del Gobierno, oído el Consejo General del Poder Judicial y la Sala de Gobierno del propio Tribunal", "A propuesta del Consejo General del Poder Judicial, en la forma que determine la ley", "A propuesta de la Sala de Gobierno del propio Tribunal Supremo", "A propuesta del Congreso de los Diputados por mayoría de tres quintos"]'::jsonb,1,'Art. 123.2 CE','Así lo dispone el art. 123.2 CE.',null),
('adm-cm:3-f00bb6f262','adm-cm',3,'¿Dónde tiene su sede el Tribunal Supremo?','["En Granada", "En Barcelona", "En Madrid", "En Valladolid"]'::jsonb,2,'Art. 53 LOPJ','Tiene sede en Madrid y jurisdicción en toda España, y ningún otro órgano puede usar la denominación de «Supremo».',null),
('adm-cm:3-19e4728c2f','adm-cm',3,'¿Cuántas Salas tiene el Tribunal Supremo?','["Cinco: Civil, Penal, Contencioso-administrativo, Social y Militar", "Cuatro: Civil, Penal, Contencioso-administrativo y Social", "Seis: Civil, Penal, Contencioso-administrativo, Social, Militar y de Apelación", "Cinco: Civil, Penal, Contencioso-administrativo, Social y de Apelación"]'::jsonb,0,'Art. 55 LOPJ','Sala Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-administrativo; Cuarta, de lo Social; y Quinta, de lo Militar.',null),
('adm-cm:3-96e16275e9','adm-cm',3,'La Sala Tercera del Tribunal Supremo es la:','["De lo Contencioso-administrativo", "De lo Social y de lo Laboral", "De lo Penal", "De lo Militar"]'::jsonb,0,'Art. 55 LOPJ','La Primera es la de lo Civil, la Segunda la de lo Penal, la Cuarta la de lo Social y la Quinta la de lo Militar.',null),
('adm-cm:3-637c113c53','adm-cm',3,'La Audiencia Nacional:','["Tiene su sede en Madrid y jurisdicción en toda España", "Tiene su sede en Madrid y jurisdicción solo en la Comunidad de Madrid", "No tiene sede fija y se reúne donde lo acuerde el CGPJ", "Tiene su sede en Madrid y es el órgano superior en el orden penal"]'::jsonb,0,'Art. 62 LOPJ','Está integrada por las Salas de Apelación, de lo Penal, de lo Contencioso-administrativo y de lo Social (art. 64 LOPJ).',null),
('adm-cm:3-898c514c57','adm-cm',3,'¿Cuál de estas Salas NO forma parte de la Audiencia Nacional?','["Sala de lo Civil", "Sala de lo Social", "Sala de lo Penal", "Sala de Apelación"]'::jsonb,0,'Art. 64 LOPJ','La Audiencia Nacional tiene Salas de Apelación, de lo Penal, de lo Contencioso-administrativo y de lo Social.',null),
('adm-cm:3-0a196ef40f','adm-cm',3,'A efectos judiciales, el Estado se organiza territorialmente en:','["Municipios, comarcas, provincias y Comunidades Autónomas", "Municipios, partidos, provincias y Comunidades Autónomas", "Distritos, partidos judiciales y Comunidades Autónomas", "Partidos judiciales, provincias y circunscripciones"]'::jsonb,1,'Art. 30 LOPJ','Así lo establece el art. 30 LOPJ.',null),
('adm-cm:3-5e873b610f','adm-cm',3,'Tras la reforma de la LO 1/2025, ¿qué órganos sustituyen a los Juzgados unipersonales de primera instancia, instrucción, penal, social, etc.?','["Las Audiencias Provinciales", "Los Tribunales de Instancia", "Las Oficinas de Justicia en los municipios", "Los Tribunales Superiores de Justicia"]'::jsonb,1,'Art. 26 LOPJ (redacción LO 1/2025)','La potestad jurisdiccional se atribuye a jueces de paz, Tribunales de Instancia, Audiencias Provinciales, TSJ, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo.',null),
('adm-cm:3-baa68547fb','adm-cm',3,'Según el art. 26 LOPJ, en su redacción vigente, ¿cuál de estos órganos tiene atribuida potestad jurisdiccional?','["La Fiscalía General del Estado", "El Tribunal Central de Instancia", "El Consejo General del Poder Judicial", "El Ministerio de Justicia"]'::jsonb,1,'Art. 26 LOPJ','Junto con los jueces de paz, los Tribunales de Instancia, las Audiencias Provinciales, los TSJ, la Audiencia Nacional y el Tribunal Supremo.',null),
('adm-cm:3-217a7a0452','adm-cm',3,'Según el art. 124 CE, el Ministerio Fiscal ejerce sus funciones conforme a los principios de:','["Independencia e inamovilidad, con sujeción en todo caso a los de legalidad y oportunidad", "Unidad de actuación y dependencia jerárquica, con sujeción en todo caso a los de legalidad e imparcialidad", "Jerarquía y oportunidad, con sujeción a los de legalidad e imparcialidad", "Unidad de actuación y autonomía funcional, con sujeción a las instrucciones del Ministerio de Justicia en cada caso"]'::jsonb,1,'Art. 124.2 CE','Lo hace por medio de órganos propios.',null),
('adm-cm:3-b6d3414971','adm-cm',3,'¿Quién nombra al Fiscal General del Estado?','["El Gobierno, a propuesta del Ministro de Justicia, oído el Congreso", "El Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial", "El Rey, a propuesta del Consejo General del Poder Judicial, oído el Gobierno", "El Congreso de los Diputados, por mayoría de tres quintos"]'::jsonb,1,'Art. 124.4 CE','Así lo dispone el art. 124.4 CE.',null),
('adm-cm:3-e6d3cc30b6','adm-cm',3,'Según el art. 124.1 CE, ¿cuál de estas es una misión del Ministerio Fiscal?','["Dirigir la Administración de Justicia, nombrar a los jueces y magistrados y ejercer sobre ellos la potestad disciplinaria, por delegación del CGPJ", "Juzgar los delitos cometidos por los miembros del Gobierno", "Ejercer la potestad disciplinaria sobre jueces y magistrados", "Promover la acción de la justicia en defensa de la legalidad, los derechos de los ciudadanos y el interés público tutelado por la ley"]'::jsonb,3,'Art. 124.1 CE','También velar por la independencia de los Tribunales y procurar ante ellos la satisfacción del interés social.',null),
('adm-cm:3-4bd9422a2b','adm-cm',3,'Según el art. 125 CE, los ciudadanos podrán participar en la Administración de Justicia mediante:','["La acción popular y la elección directa de los jueces de paz en todos los municipios, y la institución del Jurado en los procesos civiles y penales que determine la ley", "La acción popular, pero no la institución del Jurado", "La institución del Jurado en todos los procesos penales y civiles", "La acción popular y la institución del Jurado, en la forma y en los procesos penales que la ley determine, y en los Tribunales consuetudinarios y tradicionales"]'::jsonb,3,'Art. 125 CE','El Tribunal del Jurado se regula en la LO 5/1995.',null),
('adm-cm:3-160b69a0cd','adm-cm',3,'La policía judicial depende, en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente:','["De la Audiencia Nacional", "De los Jueces, de los Tribunales y del Ministerio Fiscal", "Del Ministerio del Interior en exclusiva, a través de las Fuerzas y Cuerpos de Seguridad del Estado", "Del Consejo General del Poder Judicial"]'::jsonb,1,'Art. 126 CE','Así lo dispone el art. 126 CE.',null),
('adm-cm:3-2b4014e9ba','adm-cm',3,'Los Jueces y Magistrados, así como los Fiscales, mientras se hallen en activo:','["Podrán pertenecer a partidos políticos y sindicatos, pero no ocupar cargos directivos en ellos ni desempeñar otros cargos públicos", "No podrán desempeñar otros cargos públicos ni pertenecer a partidos políticos o sindicatos", "No podrán pertenecer a sindicatos, pero sí a partidos políticos", "Podrán desempeñar cargos públicos con autorización del CGPJ"]'::jsonb,1,'Art. 127.1 CE','La ley establece el sistema y modalidades de asociación profesional.',null),
('adm-cm:3-5729d742a3','adm-cm',3,'¿Pueden los Jueces y Magistrados en activo asociarse profesionalmente?','["No, solo pueden afiliarse a sindicatos", "Sí, la ley establece el sistema y las modalidades de asociación profesional", "Sí, pero solo a través de partidos políticos", "No, la asociación está prohibida en todo caso"]'::jsonb,1,'Art. 127.1 CE','Lo que tienen prohibido es pertenecer a partidos políticos o sindicatos.',null),
('adm-cm:3-8fd7dabbc3','adm-cm',3,'Según el art. 118 CE, cumplir las sentencias y demás resoluciones firmes de los Jueces y Tribunales:','["Es obligado, así como prestar la colaboración requerida por estos en el curso del proceso y en la ejecución de lo resuelto", "Es voluntario hasta que se dicte el auto de ejecución", "Es obligado para los particulares, pero no para la Administración, que puede suspender su ejecución por razones de interés público apreciadas por el Gobierno", "Es obligado solo para las partes del proceso"]'::jsonb,0,'Art. 118 CE','Así lo dispone el art. 118 CE.',null),
('adm-cm:3-30b280ddec','adm-cm',3,'El principio de unidad jurisdiccional es, según el art. 117.5 CE:','["La base de la organización y funcionamiento de los Tribunales", "Una excepción aplicable solo a la jurisdicción militar", "La base de la organización del Ministerio Fiscal", "Un principio que rige solo en el Tribunal Supremo"]'::jsonb,0,'Art. 117.5 CE','La ley regula el ejercicio de la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio.',null),
('adm-cm:3-6abcb7035c','adm-cm',3,'¿Qué ley determina la constitución, funcionamiento y gobierno de los Juzgados y Tribunales?','["La Ley de Enjuiciamiento Civil", "El Reglamento del Consejo General del Poder Judicial", "La Ley de Planta y Demarcación Judicial", "La Ley Orgánica del Poder Judicial"]'::jsonb,3,'Art. 122.1 CE','También el estatuto jurídico de los Jueces y Magistrados de carrera y del personal al servicio de la Administración de Justicia.',null),
('adm-cm:4-823907c269','adm-cm',4,'La potestad reglamentaria corresponde, según el art. 97 de la Constitución, a:','["El Gobierno, de acuerdo con la Constitución y las leyes", "Las Cortes Generales, de acuerdo con la Constitución y los Reglamentos de las Cámaras", "El Rey, a propuesta del Consejo de Ministros y previo dictamen", "El Gobierno y el Consejo de Estado, conjuntamente"]'::jsonb,0,'Art. 97 CE','El Gobierno ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.','abr. 2026 · 1.er ejercicio'),
('adm-cm:4-a2c51e6e2a','adm-cm',4,'¿Quién controla la potestad reglamentaria y la legalidad de la actuación administrativa?','["Los Tribunales", "El Defensor del Pueblo", "El Consejo de Estado", "Las Cortes Generales"]'::jsonb,0,'Art. 106.1 CE','Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa.',null),
('adm-cm:4-f2f884efc7','adm-cm',4,'Según el art. 97 CE, el Gobierno dirige:','["La Administración civil y militar, y las Cortes dirigen la política interior y la exterior", "La política interior y exterior, la Administración civil y militar y la defensa del Estado", "La política interior y exterior y la Administración civil, pero no la militar, que corresponde al Rey", "La política interior, mientras que la exterior y la defensa corresponden al Rey como Jefe del Estado"]'::jsonb,1,'Art. 97 CE','Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.',null),
('adm-cm:4-db4a314c62','adm-cm',4,'Según el art. 98.1 CE, el Gobierno se compone de:','["El Presidente, los Vicepresidentes, en su caso, los Ministros y los demás miembros que establezca la ley", "El Presidente, los Vicepresidentes, los Ministros y los Subsecretarios de cada Departamento", "El Presidente, los Vicepresidentes y los Ministros, sin que una ley pueda añadir otros miembros distintos de los citados", "El Presidente, los Ministros y los Secretarios de Estado"]'::jsonb,0,'Art. 98.1 CE','La Ley 50/1997 concreta que el Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros (art. 1.2).',null),
('adm-cm:4-1b941c5420','adm-cm',4,'¿Quién dirige la acción del Gobierno y coordina las funciones de los demás miembros?','["El Consejo de Ministros", "El Ministro de la Presidencia", "El Presidente", "El Vicepresidente primero"]'::jsonb,2,'Art. 98.2 CE','Sin perjuicio de la competencia y responsabilidad directa de los Ministros en su gestión.',null),
('adm-cm:4-7faed49973','adm-cm',4,'Según el art. 98.3 CE, los miembros del Gobierno:','["No pueden ejercer otras funciones representativas que las propias del mandato parlamentario, ni otra función pública que no derive de su cargo, ni actividad profesional o mercantil alguna", "No pueden ser a la vez Diputados ni Senadores", "Pueden compatibilizar su cargo con otra función pública si lo autoriza el Consejo de Ministros", "Pueden ejercer actividades profesionales si no tienen relación con su Departamento"]'::jsonb,0,'Art. 98.3 CE','Por eso sí pueden ser parlamentarios a la vez.',null),
('adm-cm:4-5415a03ed9','adm-cm',4,'Antes de proponer un candidato a la Presidencia del Gobierno, el Rey consulta:','["Al Consejo de Estado y a los presidentes de las Comunidades Autónomas", "A los representantes designados por los grupos políticos con representación parlamentaria", "Al candidato de la lista más votada, que es propuesto en todo caso", "A los Presidentes del Congreso y del Senado y al Presidente del Tribunal Constitucional, por este orden"]'::jsonb,1,'Art. 99.1 CE','La propuesta se hace a través del Presidente del Congreso.',null),
('adm-cm:4-acad8e7d1c','adm-cm',4,'En la investidura, si el candidato no obtiene la mayoría absoluta del Congreso en la primera votación:','["Se somete a nueva votación 48 horas después y la confianza se entiende otorgada por mayoría simple", "Se somete a nueva votación una semana después y basta la mayoría simple", "Se somete a nueva votación 24 horas después y se exige de nuevo la mayoría absoluta de los miembros del Congreso", "Se disuelven las Cámaras y se convocan elecciones generales"]'::jsonb,0,'Art. 99.3 CE','Así lo dispone el art. 99.3 CE.',null),
('adm-cm:4-77e71fc869','adm-cm',4,'Si transcurren dos meses desde la primera votación de investidura sin que ningún candidato obtenga la confianza del Congreso:','["El Rey disuelve el Congreso, pero no el Senado, con el refrendo del Presidente del Gobierno en funciones", "El Rey nombra Presidente al candidato de la lista más votada", "El Rey disuelve ambas Cámaras y convoca nuevas elecciones con el refrendo del Presidente del Congreso", "El Congreso elige Presidente por mayoría simple sin necesidad de propuesta del Rey"]'::jsonb,2,'Art. 99.5 CE','Así lo dispone el art. 99.5 CE.',null),
('adm-cm:4-36e4e4e8e6','adm-cm',4,'Los demás miembros del Gobierno son nombrados y separados:','["Por el Rey, previa autorización del Congreso", "Por el Consejo de Ministros", "Por el Presidente del Gobierno, dando cuenta al Congreso", "Por el Rey, a propuesta de su Presidente"]'::jsonb,3,'Art. 100 CE','Así lo dispone el art. 100 CE.',null),
('adm-cm:4-27c9fda8e2','adm-cm',4,'¿En cuál de estos casos NO cesa el Gobierno según el art. 101 CE?','["Por pérdida de la confianza parlamentaria", "Tras la celebración de elecciones generales", "Por fallecimiento de su Presidente", "Cuando dimite un Vicepresidente"]'::jsonb,3,'Art. 101.1 CE','Cesa tras las elecciones generales, por pérdida de la confianza parlamentaria y por dimisión o fallecimiento de su Presidente.',null),
('adm-cm:4-7148a94551','adm-cm',4,'El Gobierno cesante:','["Es sustituido por la Comisión General de Secretarios de Estado y Subsecretarios", "Continúa en funciones durante un máximo de dos meses", "Continúa en funciones hasta la toma de posesión del nuevo Gobierno", "Cesa inmediatamente y le sustituye el Presidente del Congreso hasta el nuevo nombramiento"]'::jsonb,2,'Art. 101.2 CE','Así lo dispone el art. 101.2 CE.',null),
('adm-cm:4-6977326aba','adm-cm',4,'¿Qué órgano es competente para exigir la responsabilidad criminal del Presidente y los demás miembros del Gobierno?','["El Congreso de los Diputados", "La Sala de lo Penal de la Audiencia Nacional", "La Sala de lo Penal del Tribunal Supremo", "El Tribunal Constitucional"]'::jsonb,2,'Art. 102.1 CE','Así lo dispone el art. 102.1 CE.',null),
('adm-cm:4-fc0e56dee0','adm-cm',4,'Si la acusación contra miembros del Gobierno fuera por traición o por cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones, solo podrá plantearse:','["Por iniciativa de la décima parte de los miembros del Congreso y con la aprobación de la mayoría simple de la Cámara en votación pública", "Por iniciativa de la cuarta parte de los miembros del Congreso y con la aprobación de la mayoría absoluta del mismo", "Por iniciativa del Ministerio Fiscal y con la autorización del Senado", "Por iniciativa de la quinta parte de cada Cámara y con aprobación por tres quintos"]'::jsonb,1,'Art. 102.2 CE','La prerrogativa real de gracia no es aplicable a estos supuestos (art. 102.3).',null),
('adm-cm:4-49db1fdf3a','adm-cm',4,'Según el art. 103.1 CE, la Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de:','["Eficacia, jerarquía, centralización, concentración y coordinación", "Eficiencia, autonomía, descentralización, desconcentración y cooperación", "Eficacia, jerarquía, descentralización, oportunidad y coordinación", "Eficacia, jerarquía, descentralización, desconcentración y coordinación"]'::jsonb,3,'Art. 103.1 CE','Con sometimiento pleno a la ley y al Derecho.',null),
('adm-cm:4-33fc0e64b9','adm-cm',4,'El supremo órgano consultivo del Gobierno es:','["El Consejo de Ministros", "El Consejo Económico y Social", "La Abogacía General del Estado", "El Consejo de Estado"]'::jsonb,3,'Art. 107 CE','Una ley orgánica regula su composición y competencia (LO 3/1980).',null),
('adm-cm:4-1213abb59e','adm-cm',4,'Según el art. 106.1 CE, ¿quién controla la potestad reglamentaria y la legalidad de la actuación administrativa?','["El Consejo de Estado", "El Defensor del Pueblo", "Los Tribunales", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 106.1 CE','También el sometimiento de la actuación administrativa a los fines que la justifican.',null),
('adm-cm:4-8d68d95186','adm-cm',4,'Según la Ley 50/1997, los miembros del Gobierno se reúnen en:','["Consejo de Ministros y en la Comisión General de Secretarios de Estado y Subsecretarios", "Consejo de Ministros solamente", "Consejo de Ministros y en Comisiones Delegadas del Gobierno", "Consejo de Ministros, en Comisiones Delegadas y en Conferencias Sectoriales"]'::jsonb,2,'Art. 1.3 Ley 50/1997','La Comisión General de Secretarios de Estado y Subsecretarios es un órgano de apoyo, no de reunión de los miembros del Gobierno.',null),
('adm-cm:4-a4eb242e8f','adm-cm',4,'¿Cuál de estas competencias corresponde al Presidente del Gobierno según la Ley 50/1997?','["Aprobar los reales decretos-leyes y los reales decretos legislativos", "Declarar el estado de alarma y el de excepción", "Aprobar los reglamentos para el desarrollo y la ejecución de las leyes, previo dictamen del Consejo de Estado, y acordar la negociación de los tratados", "Crear, modificar y suprimir, por real decreto, los Departamentos ministeriales y las Secretarías de Estado"]'::jsonb,3,'Art. 2.2 j) Ley 50/1997','Las otras tres son competencias del Consejo de Ministros (art. 5).',null),
('adm-cm:4-a64dde596f','adm-cm',4,'¿A quién corresponde aprobar los reales decretos-leyes y los reales decretos legislativos?','["Al Ministro competente por razón de la materia, con el visto bueno del Presidente", "Al Presidente del Gobierno", "A las Comisiones Delegadas del Gobierno", "Al Consejo de Ministros"]'::jsonb,3,'Art. 5.1 c) Ley 50/1997','Así lo dispone la Ley del Gobierno.',null),
('adm-cm:4-3c18eee06e','adm-cm',4,'¿Quién ejerce la secretaría del Consejo de Ministros?','["El Ministro de la Presidencia", "El Secretario General Técnico de la Presidencia", "El Subsecretario de la Presidencia", "El Vicepresidente primero del Gobierno"]'::jsonb,0,'Art. 5.3 Ley 50/1997','Las deliberaciones del Consejo de Ministros son secretas.',null),
('adm-cm:4-ab1780656d','adm-cm',4,'Según la Ley 50/1997, las deliberaciones del Consejo de Ministros:','["Son públicas, salvo que el Consejo acuerde lo contrario", "Se recogen en acta, que puede consultar cualquier ciudadano", "Son secretas", "Se publican en el BOE en extracto"]'::jsonb,2,'Art. 5.3 Ley 50/1997','Los documentos que se presenten tienen carácter reservado hasta que se hagan públicos.',null),
('adm-cm:4-8b5a8d9863','adm-cm',4,'Las Comisiones Delegadas del Gobierno se crean, modifican y suprimen:','["Por ley de las Cortes Generales", "Por orden del Ministro de la Presidencia", "Por real decreto del Consejo de Ministros, a propuesta del Presidente del Gobierno", "Por acuerdo de la Comisión General de Secretarios de Estado y Subsecretarios, a propuesta del Ministro competente"]'::jsonb,2,'Art. 6.1 Ley 50/1997','El real decreto de creación indica, entre otras cosas, el miembro del Gobierno que asume la presidencia y sus funciones.',null),
('adm-cm:4-cfb646515f','adm-cm',4,'¿Quién preside la Comisión General de Secretarios de Estado y Subsecretarios?','["Un Vicepresidente del Gobierno o, en su defecto, el Ministro de la Presidencia", "El Subsecretario de la Presidencia", "El Secretario de Estado de Relaciones con las Cortes y con la Comisión General de Codificación", "El Presidente del Gobierno"]'::jsonb,0,'Art. 8.3 Ley 50/1997','El Secretario de la Comisión es el Subsecretario de la Presidencia.',null),
('adm-cm:4-edb79300e1','adm-cm',4,'Para ser miembro del Gobierno se requiere, según la Ley 50/1997:','["Ser español de origen, mayor de 25 años y tener la condición de Diputado o Senador", "Ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo y no estar inhabilitado para ejercer empleo o cargo público por sentencia judicial firme", "Ser español, mayor de edad y tener una titulación universitaria", "Ser español o nacional de un Estado de la UE, mayor de edad y no estar inhabilitado"]'::jsonb,1,'Art. 11 Ley 50/1997','No se exige ser parlamentario.',null),
('adm-cm:4-e835b9fb99','adm-cm',4,'En caso de vacante, ausencia o enfermedad, las funciones del Presidente del Gobierno son asumidas:','["Por el Ministro de mayor edad, como en las Mesas de edad", "Por los Vicepresidentes, de acuerdo con el correspondiente orden de prelación, y en defecto de ellos por los Ministros, según el orden de precedencia de los Departamentos", "Por el Ministro de la Presidencia en todo caso", "Por el Presidente del Congreso hasta la elección de un nuevo Presidente del Gobierno"]'::jsonb,1,'Art. 13.1 Ley 50/1997','Así lo establece la Ley del Gobierno.',null),
('adm-cm:4-8b29813ca8','adm-cm',4,'El Gobierno en funciones NO podrá:','["Aprobar el Proyecto de Ley de Presupuestos Generales del Estado", "Despachar los asuntos públicos ordinarios", "Adoptar medidas en casos de urgencia debidamente acreditados o por razones de interés general", "Aprobar reales decretos de desarrollo de leyes"]'::jsonb,0,'Art. 21.5 Ley 50/1997','Tampoco puede presentar proyectos de ley al Congreso o, en su caso, al Senado. Limita su gestión al despacho ordinario, salvo urgencia o interés general acreditados.',null),
('adm-cm:4-bfca3af0ac','adm-cm',4,'El Presidente del Gobierno en funciones NO puede:','["Presidir el Consejo de Ministros ni refrendar los actos del Rey", "Nombrar Ministros para cubrir vacantes en el Gobierno", "Representar al Gobierno ante las Cortes ni ante otros Estados", "Proponer al Rey la disolución de las Cámaras, plantear la cuestión de confianza ni proponer la convocatoria de un referéndum consultivo"]'::jsonb,3,'Art. 21.4 Ley 50/1997','Además, las delegaciones legislativas otorgadas por las Cortes quedan en suspenso durante todo el tiempo en que el Gobierno esté en funciones (art. 21.6).',null),
('adm-cm:4-a456a8d428','adm-cm',4,'¿Qué forma adoptan las decisiones del Presidente del Gobierno, según el art. 24 de la Ley 50/1997?','["Real Decreto del Presidente del Gobierno", "Real Decreto-ley", "Acuerdo del Consejo de Ministros a propuesta del Presidente", "Orden Ministerial"]'::jsonb,0,'Art. 24.1 b) Ley 50/1997','Las normas de rango reglamentario del Consejo de Ministros adoptan la forma de Real Decreto acordado en Consejo de Ministros.',null),
('adm-cm:4-58275841d1','adm-cm',4,'Según el art. 24 de la Ley 50/1997, ¿qué forma adoptan las disposiciones y resoluciones de los Ministros?','["Real Decreto ministerial", "Instrucción", "Resolución ministerial", "Orden Ministerial"]'::jsonb,3,'Art. 24.1 f) Ley 50/1997','Cuando afectan a varios Departamentos, revisten la forma de orden del Ministro de la Presidencia, a propuesta de los Ministros interesados.',null),
('adm-cm:4-f1cdb1eae7','adm-cm',4,'Según la Ley 50/1997, los reglamentos se ordenan según la siguiente jerarquía:','["Primero los reales decretos del Consejo de Ministros; después los del Presidente; y, por último, las órdenes", "Primero las disposiciones aprobadas por real decreto del Presidente o del Consejo de Ministros; después las aprobadas por orden ministerial", "Todas tienen el mismo rango, y prevalece la más reciente", "Primero las órdenes ministeriales; después los reales decretos del Presidente"]'::jsonb,1,'Art. 24.2 Ley 50/1997','Ningún reglamento puede vulnerar preceptos de otro de jerarquía superior.',null),
('adm-cm:4-661f26c320','adm-cm',4,'Los Ministros, según la Ley 50/1997:','["Son nombrados por el Presidente del Gobierno sin intervención del Rey y responden individualmente ante el Congreso de los Diputados por su gestión al frente del Departamento", "Son los titulares de los Departamentos en que se divide la Administración General del Estado, aunque puede haber Ministros sin cartera", "Son siempre titulares de un Departamento ministerial, sin excepción", "Dependen jerárquicamente del Vicepresidente primero"]'::jsonb,1,'Art. 4 Ley 50/1997','Los Ministros sin cartera tienen atribuida la responsabilidad de determinadas funciones gubernamentales.',null),
('adm-cm:4-c8ec19b68a','adm-cm',4,'Los Secretarios de Estado, según la Ley 50/1997:','["Son órganos de apoyo del Presidente sin funciones ejecutivas", "Son órganos superiores de la AGE directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica", "Son órganos directivos que dependen de los Subsecretarios", "Son miembros del Gobierno y asisten con voz y voto al Consejo de Ministros"]'::jsonb,1,'Art. 7 Ley 50/1997','Pueden asistir a las reuniones del Consejo de Ministros cuando sean convocados, pero no son miembros del Gobierno.',null),
('adm-cm:4-ec51289d03','adm-cm',4,'Según el art. 105 CE, la ley regulará:','["La responsabilidad penal de los funcionarios públicos", "La audiencia de los ciudadanos en la elaboración de las disposiciones administrativas, el acceso a los archivos y registros administrativos y el procedimiento de producción de los actos administrativos", "El régimen de los partidos políticos y de los sindicatos", "El estatuto de los miembros del Gobierno"]'::jsonb,1,'Art. 105 CE','Garantizando, cuando proceda, la audiencia del interesado.',null),
('adm-cm:4-a59ece1cfb','adm-cm',4,'Según el art. 106.2 CE, los particulares tienen derecho a ser indemnizados por toda lesión que sufran en sus bienes y derechos:','["Solo si la lesión se debe a un funcionamiento anormal de los servicios públicos, y siempre que no concurra fuerza mayor", "Salvo que la lesión se produzca en estado de alarma, excepción o sitio", "Siempre que la lesión se deba a dolo o culpa grave de un funcionario", "Siempre que sea consecuencia del funcionamiento de los servicios públicos, salvo fuerza mayor"]'::jsonb,3,'Art. 106.2 CE','En los términos establecidos por la ley.',null),
('adm-cm:4-112801c71f','adm-cm',4,'¿Qué ley regula el Gobierno?','["La Ley 6/1997, de 14 de abril", "La Ley 40/2015, de 1 de octubre, de Régimen Jurídico", "La Ley 50/1997, de 27 de noviembre", "La Ley 30/1992, de 26 de noviembre"]'::jsonb,2,'Ley 50/1997','La Ley 40/2015 regula el Régimen Jurídico del Sector Público, y la antigua Ley 6/1997 (LOFAGE) fue derogada por ella.',null),
('adm-cm:4-540d38ebbd','adm-cm',4,'Según la Ley 40/2015, son órganos superiores de la Administración General del Estado:','["Los Ministros y los Subsecretarios", "Los Secretarios de Estado y los Secretarios generales", "Los Ministros, los Secretarios de Estado y los Directores generales", "Los Ministros y los Secretarios de Estado"]'::jsonb,3,'Art. 55.3 Ley 40/2015','Los demás órganos de la organización central son órganos directivos.',null),
('adm-cm:4-75e61fe37b','adm-cm',4,'¿Cuál de los siguientes es un órgano directivo de la organización central de la AGE?','["El Subdirector general", "El Ministro", "El Secretario de Estado", "El Delegado del Gobierno en la Comunidad Autónoma"]'::jsonb,0,'Art. 55.3 Ley 40/2015','Son órganos directivos los Subsecretarios y Secretarios generales, los Secretarios generales técnicos y Directores generales, y los Subdirectores generales. Los Delegados del Gobierno son órganos directivos, pero de la organización territorial.',null),
('adm-cm:4-4f6c8d2a7d','adm-cm',4,'En la organización territorial de la AGE, son órganos directivos:','["Los Delegados del Gobierno, los Presidentes de las Diputaciones y los Subdelegados", "Los Delegados del Gobierno en las Comunidades Autónomas y los Subdelegados del Gobierno en las provincias", "Los Delegados del Gobierno y los Directores generales de los servicios periféricos", "Los Subdelegados del Gobierno y los Alcaldes de los municipios de más de 50.000 habitantes"]'::jsonb,1,'Art. 55.4 Ley 40/2015','Los Delegados tienen rango de Subsecretario y los Subdelegados nivel de Subdirector general.',null),
('adm-cm:4-eaa665d592','adm-cm',4,'En la Administración General del Estado en el exterior son órganos directivos:','["Los Embajadores y los Representantes permanentes ante organizaciones internacionales", "Los Cónsules generales y los Agregados sectoriales de los distintos Ministerios en el exterior", "Los Embajadores y los Cónsules honorarios", "Los Consejeros de Embajada y los Encargados de negocios"]'::jsonb,0,'Art. 55.5 Ley 40/2015','Así lo establece la Ley 40/2015 para la Administración General del Estado en el exterior.',null),
('adm-cm:4-48a7f69d6b','adm-cm',4,'¿Qué rango tienen los Delegados del Gobierno en las Comunidades Autónomas?','["Rango de Secretario de Estado", "Nivel de Subdirector general", "Rango de Director general", "Rango de Subsecretario"]'::jsonb,3,'Arts. 55.4 y 72.3 Ley 40/2015','Los Subdelegados del Gobierno en las provincias tienen nivel de Subdirector general.',null),
('adm-cm:4-13d1e2577d','adm-cm',4,'Los Subdelegados del Gobierno en las provincias tienen:','["Rango de Secretario general técnico", "Nivel de Subdirector general", "Rango de Director general", "Rango de Subsecretario"]'::jsonb,1,'Arts. 55.4 y 74 Ley 40/2015','Los Delegados del Gobierno, en cambio, tienen rango de Subsecretario.',null),
('adm-cm:4-059d70fda0','adm-cm',4,'Los Secretarios generales técnicos tienen categoría de:','["Subdirector general", "Subsecretario", "Director general", "Secretario de Estado"]'::jsonb,2,'Art. 65.1 Ley 40/2015','Los Secretarios generales, en cambio, tienen categoría de Subsecretario.',null),
('adm-cm:4-47320f3762','adm-cm',4,'Los Secretarios generales de los Ministerios tienen categoría de:','["Director general", "Subdirector general", "Subsecretario", "Secretario de Estado"]'::jsonb,2,'Art. 64.1 Ley 40/2015','Los Secretarios generales técnicos tienen categoría de Director general.',null),
('adm-cm:4-4292a61fc4','adm-cm',4,'¿Cómo se nombran los Subsecretarios?','["Por real decreto del Consejo de Ministros, a propuesta del titular del Ministerio", "Por real decreto del Presidente del Gobierno, a propuesta del Ministro de Hacienda", "Por orden del Ministro del departamento, entre funcionarios del subgrupo A1", "Por acuerdo de la Comisión General de Secretarios de Estado y Subsecretarios"]'::jsonb,0,'Art. 63.3 Ley 40/2015','Se eligen entre funcionarios de carrera del Estado, de las CCAA o de las Entidades Locales del subgrupo A1.',null),
('adm-cm:4-261cc9ddb1','adm-cm',4,'Los Subdirectores generales son nombrados y cesados:','["Por real decreto del Consejo de Ministros, a propuesta del Ministro del departamento", "Por el Ministro, el Secretario de Estado o el Subsecretario del que dependan", "Por el Director general del que dependan, entre personal laboral fijo", "Por el Delegado del Gobierno, a propuesta del Director general del que dependan"]'::jsonb,1,'Art. 67.2 Ley 40/2015','Se nombran atendiendo a los principios de igualdad, mérito y capacidad, entre funcionarios de carrera del subgrupo A1.',null),
('adm-cm:4-7b5d800251','adm-cm',4,'¿Entre quiénes se nombra con carácter general a los Directores generales?','["Solo entre funcionarios de carrera de la Administración General del Estado del subgrupo A2", "Entre cualquier persona mayor de edad con nacionalidad española, sin otros requisitos", "Entre funcionarios de carrera del subgrupo A1, salvo excepción motivada en el real decreto de estructura", "Entre altos cargos que hayan sido antes Subdirectores generales durante dos años"]'::jsonb,2,'Art. 66.2 Ley 40/2015','Se nombran y cesan por real decreto del Consejo de Ministros. El real decreto de estructura puede permitir, motivadamente, que el titular no sea funcionario.',null),
('adm-cm:4-f3544412ab','adm-cm',4,'A diferencia de los Subsecretarios, los Secretarios generales:','["Tienen categoría de Secretario de Estado", "Son nombrados por el Ministro mediante orden ministerial", "Pueden nombrarse entre personas con cualificación y experiencia, sin ser necesariamente funcionarios", "Deben ser siempre funcionarios de carrera del subgrupo A1 con diez años de servicio"]'::jsonb,2,'Art. 64 Ley 40/2015','Se nombran por real decreto del Consejo de Ministros a propuesta del Ministro, atendiendo a criterios de competencia profesional y experiencia.',null),
('adm-cm:4-19b9de40af','adm-cm',4,'¿A quién corresponde la representación ordinaria del Ministerio?','["Al Ministro", "Al Subsecretario", "Al Secretario general técnico", "Al Secretario de Estado"]'::jsonb,1,'Art. 63.1 a) Ley 40/2015','El Subsecretario ostenta la representación ordinaria del Ministerio y dirige sus servicios comunes.',null),
('adm-cm:4-04a6aebb0e','adm-cm',4,'La Secretaría General Técnica depende, dentro de cada Ministerio:','["De la Subsecretaría", "Directamente del Ministro", "De la Secretaría de Estado", "De la Dirección General de Servicios"]'::jsonb,0,'Art. 58 Ley 40/2015','En todo Ministerio existe una Subsecretaría y, dependiendo de ella, una Secretaría General Técnica.',null),
('adm-cm:4-36828e213a','adm-cm',4,'¿Cómo se crean, modifican y suprimen los Ministerios?','["Por ley de las Cortes Generales", "Por real decreto del Consejo de Ministros, a propuesta del Ministro de Hacienda", "Por real decreto del Presidente del Gobierno", "Por orden del Ministro de la Presidencia"]'::jsonb,2,'Art. 2.2 j) Ley 50/1997','Corresponde al Presidente del Gobierno crear, modificar y suprimir por real decreto los Departamentos ministeriales y las Secretarías de Estado.',null),
('adm-cm:4-d873201294','adm-cm',4,'La estructura orgánica básica de cada Ministerio se establece:','["Por resolución del Subsecretario del Ministerio", "Por orden del Ministro del departamento", "Por real decreto del Consejo de Ministros", "Por real decreto del Presidente del Gobierno"]'::jsonb,2,'Art. 59.1 Ley 40/2015','Se aprueba a iniciativa del Ministro interesado y a propuesta del Ministro competente en materia de organización administrativa.',null),
('adm-cm:4-5545b38597','adm-cm',4,'Los órganos de nivel inferior a Subdirección General se crean, modifican y suprimen:','["Por real decreto del Presidente del Gobierno, previo informe del Consejo de Estado", "Por resolución del Subsecretario, sin necesidad de aprobación previa", "Por real decreto del Consejo de Ministros, a propuesta del Ministro respectivo", "Por orden del Ministro respectivo, previa aprobación del Ministro competente en materia de organización"]'::jsonb,3,'Art. 59.2 Ley 40/2015','Las Subdirecciones Generales y órganos superiores se crean por real decreto.',null),
('adm-cm:4-73ccf4b33e','adm-cm',4,'¿Cómo se nombran los Delegados del Gobierno en las Comunidades Autónomas?','["Por orden del Ministro del Interior, oído el Gobierno autonómico", "Por real decreto del Consejo de Ministros, a propuesta del Presidente del Gobierno", "Por elección de la Asamblea Legislativa de la Comunidad Autónoma", "Por real decreto del Consejo de Ministros, a propuesta del Presidente de la Comunidad Autónoma"]'::jsonb,1,'Art. 72.4 Ley 40/2015','Dependen orgánicamente de la Presidencia del Gobierno y tienen rango de Subsecretario.',null),
('adm-cm:4-1c891d8b0f','adm-cm',4,'¿Quién nombra a los Subdelegados del Gobierno en las provincias?','["El Presidente de la Diputación Provincial, oído previamente el Delegado del Gobierno", "El Consejo de Ministros, por real decreto, a propuesta del Ministro del Interior", "El Ministro competente en política territorial, por concurso de méritos entre funcionarios", "El Delegado del Gobierno, por libre designación entre funcionarios de carrera"]'::jsonb,3,'Art. 74 Ley 40/2015','Se nombran entre funcionarios de carrera del Estado, de las CCAA o de las Entidades Locales del subgrupo A1.',null),
('adm-cm:4-6def0aac7b','adm-cm',4,'En las Comunidades Autónomas uniprovinciales:','["Existe un Subdelegado del Gobierno con rango de Subsecretario, nombrado por el Consejo de Ministros", "No existe Subdelegado del Gobierno y el Delegado asume sus competencias", "El Subdelegado asume las funciones del Delegado del Gobierno", "Hay siempre un Subdelegado y un Director insular"]'::jsonb,1,'Art. 74 Ley 40/2015','En las Comunidades Autónomas uniprovinciales el Delegado del Gobierno asume las competencias de los Subdelegados.',null),
('adm-cm:4-68d7c5ca93','adm-cm',4,'¿En qué ámbito se nombran Directores Insulares de la Administración General del Estado?','["En las ciudades de Ceuta y Melilla, por el Ministro de Hacienda, oído el Delegado del Gobierno", "En cada isla, por elección del Cabildo o Consejo insular entre sus propios miembros", "En todas las islas de Baleares y Canarias, por el Consejo de Ministros a propuesta del Delegado", "En las islas que lo determine la normativa, por el Delegado del Gobierno"]'::jsonb,3,'Art. 70 Ley 40/2015','Se nombran por el Delegado del Gobierno por libre designación entre funcionarios de carrera.',null),
('adm-cm:4-078c07e087','adm-cm',4,'¿Qué órgano colegiado asiste al Delegado del Gobierno en cada Comunidad Autónoma?','["La Comisión General de Secretarios de Estado y Subsecretarios del Gobierno", "La Comisión Bilateral de Cooperación entre el Estado y la Comunidad Autónoma", "La Conferencia de Presidentes", "La Comisión territorial de asistencia al Delegado del Gobierno"]'::jsonb,3,'Art. 79 Ley 40/2015','En las Comunidades pluriprovinciales la preside el Delegado del Gobierno y la integran los Subdelegados.',null),
('adm-cm:4-5020b95296','adm-cm',4,'Corresponde a los Delegados del Gobierno, entre otras funciones:','["Proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana", "Nombrar a los Alcaldes de los municipios de su Comunidad Autónoma", "Dictar reglamentos ejecutivos de las leyes estatales en su territorio", "Aprobar los presupuestos de los servicios periféricos de todos los Ministerios"]'::jsonb,0,'Art. 73.3 Ley 40/2015','Lo hacen a través de los Subdelegados y de las Fuerzas y Cuerpos de Seguridad del Estado, cuya jefatura les corresponde.',null),
('adm-cm:4-d62a920afc','adm-cm',4,'¿Qué es un Ministerio, según la Ley 40/2015?','["Una entidad de derecho privado adscrita a la Presidencia del Gobierno", "Un Departamento que comprende uno o varios sectores funcionalmente homogéneos de actividad administrativa", "Un órgano colegiado del Gobierno integrado por los Secretarios de Estado", "Un organismo público con personalidad jurídica propia y autonomía de gestión"]'::jsonb,1,'Art. 57.1 Ley 40/2015','La Administración General del Estado se organiza en Presidencia del Gobierno y en Ministerios.',null),
('adm-cm:4-af75380bda','adm-cm',4,'Los Secretarios de Estado son directamente responsables, bajo la dirección del Ministro:','["De la representación ordinaria del Ministerio y de la jefatura de su personal", "De la ejecución de la acción del Gobierno en un sector de actividad específica del Departamento", "De la asistencia jurídica y de las publicaciones del Ministerio", "De la gestión de una Subdirección General concreta"]'::jsonb,1,'Art. 62.1 Ley 40/2015','La representación ordinaria corresponde al Subsecretario y la asistencia jurídica y publicaciones a la Secretaría General Técnica.',null),
('adm-cm:4-4a9555ede5','adm-cm',4,'La producción normativa, la asistencia jurídica y las publicaciones de un Ministerio corresponden a:','["La Subsecretaría", "La Secretaría de Estado", "La Abogacía General del Estado", "La Secretaría General Técnica"]'::jsonb,3,'Art. 65.1 Ley 40/2015','El Secretario general técnico tiene categoría de Director general.',null),
('adm-cm:4-1500e87685','adm-cm',4,'¿Quién tiene la condición de alto cargo según la Ley 40/2015?','["Los órganos superiores y directivos, salvo los Subdirectores generales y asimilados", "Todos los funcionarios de carrera del subgrupo A1 que presten servicio en la Administración General del Estado", "Solo los Ministros y los Secretarios de Estado, como órganos superiores de la Administración", "Todos los órganos directivos, incluidos los Subdirectores generales y los asimilados a ellos"]'::jsonb,0,'Art. 55.6 Ley 40/2015','Los Subdirectores generales y asimilados no tienen la consideración de alto cargo.',null),
('adm-cm:5-0b9a738ade','adm-cm',5,'Según el art. 152.1 CE, el Tribunal Superior de Justicia:','["Culmina la organización judicial en el ámbito territorial de la Comunidad Autónoma, sin perjuicio de la jurisdicción del Tribunal Supremo", "Es el órgano jurisdiccional superior en todos los órdenes dentro de la Comunidad, sin que quepa recurso ante el Tribunal Supremo", "Es el órgano de gobierno de los jueces de la Comunidad Autónoma", "Depende del Gobierno autonómico, que nombra a su Presidente"]'::jsonb,0,'Art. 152.1 CE','Las sucesivas instancias procesales se agotan ante órganos radicados en el mismo territorio de la CA en que esté el órgano competente en primera instancia.',null),
('adm-cm:5-7e22676430','adm-cm',5,'Según el artículo 137 de la Constitución, el Estado se organiza territorialmente en:','["Provincias, Comunidades Autónomas y Ciudades Autónomas", "Municipios, islas y Comunidades Autónomas", "Municipios, provincias y Comunidades Autónomas", "Municipios, comarcas, provincias y regiones"]'::jsonb,2,'Art. 137 CE','Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.',null),
('adm-cm:5-9d2d673bab','adm-cm',5,'Según la Constitución, el gobierno y la administración de los municipios corresponde a:','["Las Diputaciones Provinciales, a través de sus delegaciones comarcales en cada municipio", "Los Delegados del Gobierno, con la colaboración de los Concejales elegidos por los vecinos", "Las asambleas vecinales abiertas, presididas por el Alcalde y el Secretario municipal", "Sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales"]'::jsonb,3,'Art. 140 CE','Los Concejales son elegidos por los vecinos por sufragio universal, igual, libre, directo y secreto.',null),
('adm-cm:5-0e1d41d6d7','adm-cm',5,'Según el artículo 140 de la Constitución, los Alcaldes serán elegidos:','["Por el Delegado del Gobierno, a propuesta de los Concejales", "Por el Pleno de la Diputación Provincial", "Por los Concejales o por los vecinos", "Siempre por sufragio universal directo de los vecinos"]'::jsonb,2,'Art. 140 CE','La ley regula las condiciones en las que procede el régimen del concejo abierto.',null),
('adm-cm:5-ce41f43327','adm-cm',5,'¿Qué tipo de ley es necesaria para alterar los límites provinciales?','["Una ley orgánica aprobada por las Cortes Generales", "Un real decreto del Consejo de Ministros", "Una ley ordinaria de las Cortes Generales, por mayoría absoluta", "Una ley de la Comunidad Autónoma afectada, previo informe estatal"]'::jsonb,0,'Art. 141.1 CE','La provincia es una entidad local con personalidad jurídica propia, agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado.',null),
('adm-cm:5-31f41b6046','adm-cm',5,'En los archipiélagos, las islas tendrán además su administración propia en forma de:','["Diputaciones forales", "Cabildos o Consejos", "Juntas Generales", "Mancomunidades insulares"]'::jsonb,1,'Art. 141.4 CE','Los Cabildos existen en Canarias y los Consejos Insulares en Baleares.',null),
('adm-cm:5-22a7698b7a','adm-cm',5,'Según el artículo 143.2 de la Constitución, la iniciativa del proceso autonómico corresponde a todas las Diputaciones interesadas o al órgano interinsular correspondiente y a:','["Los municipios que representen un tercio del censo electoral de la región histórica", "Las tres cuartas partes de los municipios que representen la mayoría absoluta de los electores", "La mitad de los municipios de cada provincia, sea cual sea su población", "Las dos terceras partes de los municipios cuya población represente, al menos, la mayoría del censo electoral de cada provincia o isla"]'::jsonb,3,'Art. 143.2 CE','Los requisitos deben cumplirse en el plazo de seis meses desde el primer acuerdo de una Corporación local.',null),
('adm-cm:5-58be9bc3d5','adm-cm',5,'¿En qué plazo deben cumplirse los requisitos de iniciativa autonómica del artículo 143.2 de la Constitución?','["Dos años desde que se constituya la asamblea de parlamentarios", "Seis meses desde el primer acuerdo adoptado por alguna de las Corporaciones locales interesadas", "Tres meses desde el acuerdo de la última de las Diputaciones interesadas", "Un año desde la publicación de la Constitución en el Boletín Oficial del Estado y en los diarios oficiales"]'::jsonb,1,'Art. 143.2 CE','Si la iniciativa no prospera, solo puede reiterarse pasados cinco años.',null),
('adm-cm:5-42387ccc1e','adm-cm',5,'Si la iniciativa autonómica del artículo 143 no prospera:','["Podrá reiterarse pasados tres años", "Solo podrá reiterarse pasados cinco años", "Podrá reiterarse al año siguiente", "No podrá volver a plantearse nunca"]'::jsonb,1,'Art. 143.3 CE','Así lo dispone el artículo 143.3 de la Constitución.',null),
('adm-cm:5-2ded04ceed','adm-cm',5,'Según el artículo 144 de la Constitución, las Cortes Generales, mediante ley orgánica y por motivos de interés nacional, podrán:','["Integrar dos Comunidades Autónomas limítrofes en una sola, sin necesidad de referéndum", "Disolver una Comunidad Autónoma que incumpla de forma grave las obligaciones que le imponen la Constitución u otras leyes", "Suspender la autonomía de una Comunidad Autónoma por un plazo máximo de seis meses", "Autorizar la constitución de una Comunidad Autónoma cuyo ámbito territorial no supere el de una provincia y no reúna las condiciones del artículo 143.1"]'::jsonb,3,'Art. 144 a) CE','El artículo 155 no permite disolver Comunidades, sino adoptar medidas para obligarlas a cumplir.',null),
('adm-cm:5-bd3b6cb572','adm-cm',5,'¿Qué prohíbe el artículo 145 de la Constitución?','["Que una Comunidad Autónoma tenga varias provincias", "La federación de Comunidades Autónomas", "Los convenios entre Comunidades Autónomas", "Que las Comunidades Autónomas tengan himno propio"]'::jsonb,1,'Art. 145.1 CE','Sí se permiten convenios entre Comunidades para la gestión de servicios propios, que deben comunicarse a las Cortes Generales.',null),
('adm-cm:5-b7c080270f','adm-cm',5,'Los acuerdos de cooperación entre Comunidades Autónomas, distintos de los convenios para gestión de servicios propios, requieren:','["El dictamen del Consejo de Estado", "La aprobación del Consejo de Ministros", "La autorización de las Cortes Generales", "Una simple comunicación a las Cortes Generales"]'::jsonb,2,'Art. 145.2 CE','Los convenios para la gestión y prestación de servicios propios solo deben comunicarse a las Cortes.',null),
('adm-cm:5-14285c79c8','adm-cm',5,'Según el artículo 147 de la Constitución, el Estatuto de Autonomía es:','["Un tratado entre el Estado y la Comunidad Autónoma", "Un reglamento del Gobierno de la Nación para cada Comunidad", "La norma institucional básica de cada Comunidad Autónoma", "Una ley ordinaria aprobada por el Parlamento autonómico"]'::jsonb,2,'Art. 147.1 CE','El Estado lo reconoce y ampara como parte integrante de su ordenamiento jurídico.',null),
('adm-cm:5-ba3204f517','adm-cm',5,'¿Cuál de los siguientes contenidos NO exige la Constitución que figure en los Estatutos de Autonomía?','["La delimitación de su territorio", "La denominación de la Comunidad", "La lengua cooficial de la Comunidad", "Las competencias asumidas"]'::jsonb,2,'Art. 147.2 CE','El art. 147.2 exige denominación, delimitación del territorio, denominación, organización y sede de las instituciones propias y competencias asumidas.',null),
('adm-cm:5-8fbee0d64e','adm-cm',5,'La reforma de los Estatutos de Autonomía requiere, en todo caso:','["Un referéndum en todo el territorio nacional", "La aprobación por las Cortes Generales mediante ley orgánica", "El acuerdo del Senado por mayoría de tres quintos", "La aprobación por el Gobierno de la Nación mediante real decreto"]'::jsonb,1,'Art. 147.3 CE','El procedimiento lo fija cada Estatuto.',null),
('adm-cm:5-0518b2a82a','adm-cm',5,'Según el artículo 148.2 de la Constitución, las Comunidades Autónomas podían ampliar sucesivamente sus competencias transcurridos:','["Diez años", "Dos años", "Tres años", "Cinco años"]'::jsonb,3,'Art. 148.2 CE','Mediante la reforma de sus Estatutos, dentro del marco del artículo 149.',null),
('adm-cm:5-422431515a','adm-cm',5,'Las materias no atribuidas expresamente al Estado por la Constitución podrán corresponder a las Comunidades Autónomas:','["Por acuerdo de la Conferencia de Presidentes", "Solo mediante ley de transferencia", "En virtud de sus respectivos Estatutos", "Siempre, de forma automática"]'::jsonb,2,'Art. 149.3 CE','Las no asumidas por los Estatutos corresponden al Estado, cuyo derecho es en todo caso supletorio del de las Comunidades Autónomas.',null),
('adm-cm:5-2a692ef88b','adm-cm',5,'En caso de conflicto, las normas del Estado prevalecen sobre las de las Comunidades Autónomas:','["En todo lo que no esté atribuido a la exclusiva competencia de estas", "Solo en materia de relaciones internacionales", "Solo si la norma estatal es posterior", "En todo caso, sin excepción alguna"]'::jsonb,0,'Art. 149.3 CE','Es la cláusula de prevalencia del derecho estatal.',null),
('adm-cm:5-ff9c7c773d','adm-cm',5,'¿Qué leyes permiten a las Cortes atribuir a las Comunidades Autónomas la facultad de dictar normas legislativas en el marco de principios, bases y directrices fijados por una ley estatal?','["Las leyes de bases", "Las leyes marco", "Las leyes de armonización", "Las leyes orgánicas de transferencia"]'::jsonb,1,'Art. 150.1 CE','Las leyes de bases sirven para delegar en el Gobierno la elaboración de textos articulados.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:5-376420ac4f','adm-cm',5,'La transferencia o delegación a las Comunidades Autónomas de facultades de titularidad estatal se hace mediante:','["Ley ordinaria", "Real decreto legislativo", "Ley orgánica", "Ley marco"]'::jsonb,2,'Art. 150.2 CE','Debe prever la correspondiente transferencia de medios financieros y las formas de control que se reserve el Estado.',null),
('adm-cm:5-98a8a56b8f','adm-cm',5,'¿Quién aprecia la necesidad de dictar una ley de armonización?','["El Senado, por mayoría de dos tercios, a propuesta de la Comisión General de las CCAA", "El Tribunal Constitucional, a instancia del Gobierno o de cincuenta diputados", "Las Cortes Generales, por mayoría absoluta de cada Cámara", "El Gobierno de la Nación, previo dictamen favorable del Consejo de Estado"]'::jsonb,2,'Art. 150.3 CE','Lo exige el interés general, aunque se trate de materias atribuidas a la competencia de las Comunidades Autónomas.',null),
('adm-cm:5-76cec20a27','adm-cm',5,'En la vía del artículo 151 de la Constitución, la iniciativa autonómica debía ratificarse mediante referéndum por:','["La mayoría absoluta de los votos válidos emitidos en el conjunto de toda España", "El voto afirmativo de la mayoría absoluta de los electores de cada provincia", "La mayoría simple de los votos emitidos en el conjunto del territorio de la futura Comunidad", "Dos tercios de los votantes de cada provincia"]'::jsonb,1,'Art. 151.1 CE','Además, la iniciativa debía acordarse por las Diputaciones y por las tres cuartas partes de los municipios de cada provincia.',null),
('adm-cm:5-e538c0d657','adm-cm',5,'Según el artículo 152 de la Constitución, el Presidente de la Comunidad Autónoma es:','["Elegido por el Senado entre los senadores de la Comunidad", "Elegido directamente por los ciudadanos de la Comunidad en las elecciones autonómicas y nombrado por el Rey", "Nombrado por el Presidente del Gobierno, a propuesta de la Asamblea", "Elegido por la Asamblea Legislativa de entre sus miembros y nombrado por el Rey"]'::jsonb,3,'Art. 152.1 CE','Dirige el Consejo de Gobierno y ostenta la suprema representación de la Comunidad y la ordinaria del Estado en ella.',null),
('adm-cm:5-71fa8ffe17','adm-cm',5,'El control económico y presupuestario de los órganos de las Comunidades Autónomas corresponde, según el artículo 153 de la Constitución, a:','["La jurisdicción contencioso-administrativa", "El Tribunal de Cuentas", "El Ministerio de Hacienda", "El Tribunal Constitucional"]'::jsonb,1,'Art. 153 d) CE','El TC controla las disposiciones con fuerza de ley y la jurisdicción contencioso-administrativa, la administración autónoma y sus reglamentos.',null),
('adm-cm:5-dd9cf963b1','adm-cm',5,'¿Quién controla las funciones delegadas a las Comunidades Autónomas conforme al artículo 150.2 de la Constitución?','["El Tribunal de Cuentas, previo informe de la Intervención General", "El Tribunal Constitucional, previo recurso del Senado", "Los Tribunales Superiores de Justicia", "El Gobierno, previo dictamen del Consejo de Estado"]'::jsonb,3,'Art. 153 b) CE','Es una de las cuatro vías de control de la actividad autonómica que enumera el artículo 153.',null),
('adm-cm:5-440db796b1','adm-cm',5,'Para aplicar las medidas del artículo 155 de la Constitución, el Gobierno necesita:','["Requerir previamente al Presidente de la Comunidad Autónoma y la aprobación de la mayoría absoluta del Senado", "La aprobación del Consejo de Estado y del Congreso", "La autorización del Congreso de los Diputados por mayoría de tres quintos", "Un dictamen favorable del Tribunal Constitucional"]'::jsonb,0,'Art. 155.1 CE','Se aplica si una Comunidad no cumple las obligaciones de la Constitución o las leyes o actúa contra el interés general de España.',null),
('adm-cm:5-92a43ec271','adm-cm',5,'¿Qué fondo prevé el artículo 158.2 de la Constitución para corregir desequilibrios económicos interterritoriales?','["El Fondo de Suficiencia Global", "El Fondo de Compensación", "El Fondo de Garantía de Servicios Públicos Fundamentales", "El Fondo de Cohesión Territorial"]'::jsonb,1,'Art. 158.2 CE','Sus recursos se distribuyen por las Cortes Generales entre las Comunidades Autónomas y provincias.',null),
('adm-cm:5-ccacac6acf','adm-cm',5,'Según la Ley 7/1985, son elementos del municipio:','["El territorio, la población y la organización", "El término municipal, el padrón y el presupuesto", "El territorio, los vecinos y el Alcalde", "La población, el patrimonio y el Pleno"]'::jsonb,0,'Art. 11.2 LBRL','El municipio es la entidad local básica de la organización territorial del Estado.',null),
('adm-cm:5-808399455a','adm-cm',5,'La Junta de Gobierno Local existe:','["En los municipios de más de 5.000 habitantes y en los de menos si lo disponen su reglamento orgánico o el Pleno", "Solo en los municipios de más de 20.000 habitantes", "En todos los municipios, sea cual sea su población, como órgano de asistencia permanente al Alcalde en sus funciones", "Solo en los municipios de gran población, regulados en el título X de la Ley 7/1985, reguladora de las Bases del Régimen Local"]'::jsonb,0,'Art. 20.1 b) LBRL','El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los Ayuntamientos.',null),
('adm-cm:5-2ed8abf22a','adm-cm',5,'¿Qué servicio deben prestar los municipios de más de 50.000 habitantes, además de los exigidos a los más pequeños?','["Transporte colectivo urbano de viajeros", "Biblioteca pública", "Instalaciones deportivas de uso público", "Alumbrado público"]'::jsonb,0,'Art. 26.1 d) LBRL','La biblioteca es obligatoria desde 5.000 habitantes, las instalaciones deportivas desde 20.000 y el alumbrado en todos.',null),
('adm-cm:6-2b9be6cc02','adm-cm',6,'Según el Estatuto, el territorio de la Comunidad de Madrid:','["Comprende el de los municipios dentro de los límites de la provincia de Madrid", "Es el que fije en cada legislatura una ley aprobada por la Asamblea", "Coincide con el área metropolitana de la capital y sus municipios limítrofes", "Lo delimita el Gobierno de la Nación mediante real decreto"]'::jsonb,0,'Art. 2 EA','El territorio coincide con los límites de la provincia de Madrid.',null),
('adm-cm:6-e7a0b99a77','adm-cm',6,'¿Cómo es la bandera de la Comunidad de Madrid?','["Roja con cinco estrellas blancas", "Roja carmesí con siete estrellas blancas", "Blanca con siete estrellas rojas", "Carmesí con siete estrellas doradas"]'::jsonb,1,'Art. 4.1 EA','La bandera es roja carmesí, con siete estrellas en blanco de cinco puntas.','nov. 2024 · 1.er ejercicio'),
('adm-cm:6-196e7c1ca9','adm-cm',6,'¿Qué día es la fiesta de la Comunidad de Madrid según el Estatuto?','["El 15 de mayo", "El 12 de octubre", "El 2 de mayo", "El 9 de noviembre"]'::jsonb,2,'Art. 4.4 EA','Se declara fiesta de la Comunidad el 2 de mayo.',null),
('adm-cm:6-5e043f2cf7','adm-cm',6,'El himno de la Comunidad de Madrid se establece:','["Por decreto del Gobierno", "Por acuerdo de la Mesa de la Asamblea", "En el propio texto del Estatuto", "Por ley de la Asamblea"]'::jsonb,3,'Art. 4.3 EA','La Comunidad tiene himno propio, establecido por ley de la Asamblea.',null),
('adm-cm:6-cc8332eb8d','adm-cm',6,'¿Cuál es la capital de la Comunidad de Madrid y sede de sus instituciones?','["Madrid y Alcalá de Henares de forma compartida", "La villa de Madrid, aunque sus organismos pueden ubicarse en otros municipios", "La que fije la Asamblea en cada legislatura", "La villa de Madrid, donde deben estar obligatoriamente todos los organismos"]'::jsonb,1,'Art. 5 EA','La capital es la villa de Madrid, pero los organismos pueden establecerse en otros municipios de la Comunidad.',null),
('adm-cm:6-f52ad3c8c3','adm-cm',6,'El régimen especial de la villa de Madrid como capital del Estado se regula por:','["Una ley de la Asamblea de Madrid", "Un decreto del Gobierno de la Comunidad", "Una ley votada en Cortes Generales", "El reglamento orgánico del Ayuntamiento"]'::jsonb,2,'Art. 6 EA','La villa de Madrid tiene un régimen especial regulado por ley votada en Cortes.',null),
('adm-cm:6-5d838a76e1','adm-cm',6,'Las circunscripciones territoriales propias de la Comunidad se pueden crear:','["Por acuerdo de los plenos de los municipios limítrofes afectados", "Por decreto del Consejo de Gobierno, agrupando municipios limítrofes", "Por ley de las Cortes Generales, agrupando municipios limítrofes", "Por ley de la Asamblea, agrupando municipios limítrofes"]'::jsonb,3,'Art. 3.3 EA','La Asamblea puede establecer por ley circunscripciones territoriales propias agrupando municipios limítrofes.',null),
('adm-cm:6-70eec72b49','adm-cm',6,'¿Cuáles son las instituciones de autogobierno de la Comunidad de Madrid?','["La Asamblea, el Gobierno y el Presidente", "La Asamblea, el Gobierno, el Presidente y el Tribunal Superior de Justicia", "La Asamblea y el Gobierno", "La Asamblea, el Gobierno y el Defensor del Pueblo"]'::jsonb,0,'Art. 8 EA','Los poderes se ejercen a través de la Asamblea, el Gobierno y el Presidente.',null),
('adm-cm:6-6cd1bc7082','adm-cm',6,'¿Gozan de los derechos políticos de los madrileños los españoles residentes en el extranjero?','["No, porque los derechos políticos exigen vecindad administrativa en Madrid", "Sí, si nacieron en la Comunidad de Madrid, aunque nunca residieran en ella", "Sí, si su última vecindad administrativa fue en Madrid y lo acreditan en el Consulado", "Sí, si residieron en Madrid al menos cinco años antes de marchar al extranjero"]'::jsonb,2,'Art. 7.3 EA','Gozan de ellos si su última vecindad administrativa fue Madrid y lo acreditan en el Consulado de España correspondiente.',null),
('adm-cm:6-b58c0ab532','adm-cm',6,'¿Cada cuántos años se elige la Asamblea de Madrid?','["Cinco años", "Tres años", "Seis años", "Cuatro años"]'::jsonb,3,'Art. 10.1 EA','La Asamblea se elige por cuatro años.',null),
('adm-cm:6-8a20953188','adm-cm',6,'¿Cuántos diputados componen la Asamblea de Madrid?','["Uno por cada 50.000 habitantes o fracción superior a 25.000", "Uno por cada 40.000 habitantes o fracción superior a 20.000", "Un número fijo de 129", "Uno por cada 100.000 habitantes"]'::jsonb,0,'Art. 10.2 EA','El número depende de la población: uno por cada 50.000 habitantes o fracción superior a 25.000.','oct. 2026 · 1.er ejercicio'),
('adm-cm:6-fa9a0cf8ea','adm-cm',6,'¿Cuál es la circunscripción electoral para las elecciones a la Asamblea?','["Cada municipio", "La provincia", "Cada partido judicial", "Cada comarca"]'::jsonb,1,'Art. 10.5 EA','La circunscripción electoral es la provincia.',null),
('adm-cm:6-aa57815a72','adm-cm',6,'¿Qué porcentaje mínimo de votos necesita una lista para entrar en el reparto de escaños?','["El 3 % de los votos válidos emitidos", "El 5 % del censo electoral", "El 5 % de los votos válidos emitidos", "El 3 % del censo electoral"]'::jsonb,2,'Art. 10.6 EA','Solo entran en el reparto las listas con al menos el 5 % de los sufragios válidamente emitidos.','nov. 2024 · 1.er ejercicio'),
('adm-cm:6-a856f67158','adm-cm',6,'¿Cuándo se celebran las elecciones a la Asamblea de Madrid?','["El primer domingo de junio", "El último domingo de mayo", "En la fecha que fije libremente el Presidente", "El cuarto domingo de mayo"]'::jsonb,3,'Art. 10.7 EA','Las elecciones se celebran el cuarto domingo de mayo.',null),
('adm-cm:6-5c8bfd4c7c','adm-cm',6,'Respecto al mandato de los diputados de la Asamblea:','["Están sujetos al mandato imperativo de su partido", "No están sujetos a mandato imperativo", "Están sujetos al mandato de su Grupo Parlamentario", "Solo hay mandato imperativo en las votaciones de investidura"]'::jsonb,1,'Art. 10.3 EA','Los diputados no están ligados por mandato imperativo.',null),
('adm-cm:6-7b7ed3b404','adm-cm',6,'¿Quiénes son electores y elegibles en las elecciones a la Asamblea?','["Los madrileños mayores de 18 años en pleno uso de sus derechos políticos", "Los madrileños mayores de 16 años", "Cualquier residente en la Comunidad, sea cual sea su nacionalidad", "Los madrileños mayores de 18 años con dos años de residencia"]'::jsonb,0,'Art. 10.8 EA','Son electores y elegibles los madrileños mayores de 18 años en pleno uso de sus derechos políticos.',null),
('adm-cm:6-bd534d3019','adm-cm',6,'¿Qué mayoría se exige para aprobar el Reglamento de la Asamblea?','["Mayoría simple", "Tres quintos", "Mayoría absoluta", "Dos tercios"]'::jsonb,2,'Art. 12.1 EA','La aprobación y reforma del Reglamento requieren mayoría absoluta de los Diputados.',null),
('adm-cm:6-e337b9cea4','adm-cm',6,'¿Cuáles son los periodos ordinarios de sesiones de la Asamblea?','["De septiembre a diciembre y de febrero a junio", "De septiembre a diciembre y de enero a junio", "De octubre a diciembre y de febrero a julio", "Un único periodo de septiembre a junio"]'::jsonb,0,'Art. 14.1 EA','Hay dos periodos ordinarios: de septiembre a diciembre y de febrero a junio.',null),
('adm-cm:6-559740e8e1','adm-cm',6,'¿Qué órgano actúa entre los periodos de sesiones de la Asamblea?','["La Mesa", "La Junta de Portavoces", "El Gobierno", "La Diputación Permanente"]'::jsonb,3,'Art. 14.2 EA','Entre periodos de sesiones actúa la Diputación Permanente.',null),
('adm-cm:6-3d10c01fb8','adm-cm',6,'Con carácter general, ¿cómo adopta sus acuerdos la Asamblea?','["Por mayoría absoluta de sus miembros, salvo que se exijan mayorías especiales", "Por mayoría de los miembros presentes, salvo que se exijan mayorías especiales", "Por mayoría de tres quintos, salvo que se exija una mayoría distinta", "Por mayoría de los miembros presentes, sin excepción alguna"]'::jsonb,1,'Art. 14.4 EA','Los acuerdos se adoptan por mayoría de los miembros presentes, salvo mayorías especiales.',null),
('adm-cm:6-661fe9bfab','adm-cm',6,'Según el artículo 15, la iniciativa legislativa corresponde a:','["Los diputados, los Grupos Parlamentarios y la Mesa de la Asamblea", "El Gobierno y la Mesa de la Asamblea", "Los diputados, los Grupos Parlamentarios y el Gobierno", "El Presidente de la Comunidad y los Grupos Parlamentarios"]'::jsonb,2,'Art. 15.2 EA','Corresponde a los diputados, a los Grupos Parlamentarios y al Gobierno. Una ley de la Asamblea puede regular además la iniciativa popular y la de los Ayuntamientos.',null),
('adm-cm:6-9137362c03','adm-cm',6,'¿Puede la Asamblea delegar la potestad legislativa en el Gobierno?','["No, la potestad legislativa de la Asamblea es indelegable", "Sí, en los términos de los artículos 82 a 84 de la Constitución", "Sí, en los términos que fije cada año la ley de presupuestos", "Solo en materia tributaria y por un plazo máximo de un año"]'::jsonb,1,'Art. 15.3 EA','Solo en los términos de los arts. 82 a 84 de la Constitución.',null),
('adm-cm:6-70a5f868cd','adm-cm',6,'¿Qué órganos elige la Asamblea de entre sus miembros?','["El Consejo de Gobierno y el Presidente del TSJ", "El Defensor del Pueblo y la Cámara de Cuentas", "La Mesa y la Junta Electoral", "Su Presidente, la Mesa y la Diputación Permanente"]'::jsonb,3,'Art. 13.1 EA','La Asamblea elige de entre sus miembros a su Presidente, a la Mesa y a la Diputación Permanente.',null),
('adm-cm:6-1a6510eefb','adm-cm',6,'¿Cómo funciona la Asamblea de Madrid?','["En Pleno y por Comisiones", "Solo en Pleno", "Por Secciones territoriales", "En Salas especializadas"]'::jsonb,0,'Art. 13.3 EA','La Asamblea funciona en Pleno y por Comisiones.',null),
('adm-cm:6-e17201c75f','adm-cm',6,'¿A quién corresponde designar a los senadores que representan a la Comunidad de Madrid?','["Al Gobierno de la Comunidad", "A la Asamblea de Madrid", "Al Presidente de la Comunidad", "A la Mesa de la Asamblea"]'::jsonb,1,'Art. 16.3.i EA','Corresponde a la Asamblea designar a los senadores que representan a la Comunidad.',null),
('adm-cm:6-1484357ca3','adm-cm',6,'¿Quién elige al Presidente de la Comunidad de Madrid?','["Los ciudadanos, por elección directa", "El Gobierno de la Comunidad", "La Asamblea, de entre sus miembros", "El Rey, a propuesta del Gobierno de la Nación"]'::jsonb,2,'Arts. 16.1 y 18 EA','El Presidente es elegido por la Asamblea de entre sus miembros.',null),
('adm-cm:6-949e6a4bb7','adm-cm',6,'Una vez elegido, el Presidente de la Comunidad es nombrado por:','["El Rey", "El Presidente del Gobierno de la Nación", "El Presidente de la Asamblea", "El Pleno del Tribunal Superior de Justicia"]'::jsonb,0,'Art. 18.3 EA','El candidato elegido por la Asamblea es nombrado Presidente por el Rey.',null),
('adm-cm:6-32e3538b56','adm-cm',6,'En la investidura, ¿qué mayoría necesita el candidato en la primera votación?','["Mayoría simple", "Mayoría absoluta", "Tres quintos", "Dos tercios"]'::jsonb,1,'Art. 18.3 EA','En la primera votación se exige mayoría absoluta.',null),
('adm-cm:6-0e82e99bd8','adm-cm',6,'Si en la primera votación de investidura no hay mayoría absoluta:','["Se vota de nuevo a las 24 horas y se exige mayoría absoluta", "Se vota de nuevo a las 48 horas y se exige mayoría absoluta", "Se vota de nuevo a las 48 horas y basta la mayoría simple", "Se vota de nuevo a los 7 días y basta la mayoría simple"]'::jsonb,2,'Art. 18.3 EA','Se hace una nueva votación 48 horas después y basta la mayoría simple.',null),
('adm-cm:6-7b47c6dc22','adm-cm',6,'Si ningún candidato logra la investidura, ¿en qué plazo queda disuelta la Asamblea?','["Un mes", "Tres meses", "45 días", "Dos meses"]'::jsonb,3,'Art. 18.5 EA','Si en dos meses desde la primera votación ningún candidato es investido, la Asamblea queda disuelta.',null),
('adm-cm:6-c36e44c937','adm-cm',6,'La cuestión de confianza planteada por el Presidente se entiende otorgada cuando vota a favor:','["La mayoría simple", "La mayoría absoluta", "Tres quintos de los diputados", "Dos tercios de los diputados"]'::jsonb,0,'Art. 19.1 EA','La confianza se entiende otorgada por mayoría simple.',null),
('adm-cm:6-050f4f6171','adm-cm',6,'Si la Asamblea niega la confianza al Presidente, el Pleno para elegir uno nuevo debe convocarse en:','["10 días", "15 días", "30 días", "Dos meses"]'::jsonb,1,'Art. 19.2 EA','El Presidente de la Asamblea convoca el Pleno en un plazo máximo de quince días.',null),
('adm-cm:6-7e0ca8d0d5','adm-cm',6,'¿Qué porcentaje mínimo de diputados debe proponer una moción de censura?','["El 10 %", "El 20 %", "El 15 %", "El 25 %"]'::jsonb,2,'Art. 20.1 EA','La moción debe proponerla al menos el 15 % de los diputados.',null),
('adm-cm:6-4584e7f89e','adm-cm',6,'¿Qué mayoría se exige para aprobar una moción de censura?','["Mayoría simple", "Mayoría absoluta", "Tres quintos", "Dos tercios"]'::jsonb,1,'Art. 20.1 EA','La moción de censura se aprueba por mayoría absoluta.',null),
('adm-cm:6-561cb565fd','adm-cm',6,'¿Cuándo puede votarse como pronto una moción de censura?','["A las 48 horas de presentarse", "A los 2 días de presentarse", "A los 10 días de presentarse", "A los 5 días de presentarse"]'::jsonb,3,'Art. 20.2 EA','No puede votarse hasta que pasen cinco días desde su presentación.',null),
('adm-cm:6-1fb3268c04','adm-cm',6,'Si prospera una moción de censura:','["Cesa el Gobierno y el candidato de la moción es nombrado Presidente por el Rey", "Se disuelve la Asamblea y se convocan elecciones en un plazo de dos meses", "Cesa el Gobierno y el candidato es nombrado Presidente por la Asamblea, sin intervención del Rey", "Cesa el Gobierno y la Asamblea abre un plazo de dos meses para elegir Presidente"]'::jsonb,0,'Art. 20.3 EA','Cesan el Presidente y su Gobierno, y el candidato incluido en la moción es nombrado por el Rey.',null),
('adm-cm:6-9e4919aa62','adm-cm',6,'¿En qué caso NO puede el Presidente disolver anticipadamente la Asamblea?','["Durante el segundo año de la legislatura", "Durante el segundo periodo de sesiones de la legislatura", "Durante el primer periodo de sesiones de la legislatura", "Durante los meses de julio y agosto, salvo acuerdo de la Mesa"]'::jsonb,2,'Art. 21.2 EA','No cabe durante el primer periodo de sesiones, con menos de un año de legislatura por delante, con una moción de censura en trámite o con elecciones estatales convocadas.',null),
('adm-cm:6-b810a6dbda','adm-cm',6,'Tras una disolución anticipada, ¿cuándo puede acordarse otra?','["A los seis meses", "Al año", "A los dos años", "A los 18 meses"]'::jsonb,1,'Art. 21.2 EA','No procede nueva disolución antes de que transcurra un año desde la anterior.',null),
('adm-cm:6-9c0121abbe','adm-cm',6,'¿Quiénes componen el Gobierno de la Comunidad de Madrid?','["El Presidente, los Vicepresidentes y el Presidente de la Asamblea", "El Presidente, los Consejeros y los Viceconsejeros", "Los Vicepresidentes, en su caso, y los Consejeros, sin el Presidente", "El Presidente, los Vicepresidentes, en su caso, y los Consejeros"]'::jsonb,3,'Art. 22.2 EA','El Gobierno lo forman el Presidente, los Vicepresidentes si los hay y los Consejeros. Para ser Vicepresidente o Consejero no hace falta ser diputado.',null),
('adm-cm:6-ea6fbec230','adm-cm',6,'¿A quién corresponde la potestad reglamentaria no reservada a la Asamblea?','["A la Mesa de la Asamblea", "Al Gobierno", "A la Diputación Permanente", "Al Presidente de la Asamblea"]'::jsonb,1,'Art. 22.1 EA','El Gobierno ejerce la función ejecutiva y la potestad reglamentaria no reservada a la Asamblea.',null),
('adm-cm:6-6edc5219b5','adm-cm',6,'¿Cómo responde políticamente el Gobierno?','["Solidariamente ante la Asamblea, sin perjuicio de la responsabilidad de cada Consejero", "Individualmente cada Consejero ante la Asamblea, sin responsabilidad solidaria", "Solidariamente ante el Presidente de la Comunidad, que responde ante la Asamblea", "Solidariamente ante la Asamblea y ante el Gobierno de la Nación"]'::jsonb,0,'Art. 23.2 EA','Responde solidariamente ante la Asamblea, sin perjuicio de la responsabilidad directa de cada Consejero por su gestión.',null),
('adm-cm:6-14e2a603d3','adm-cm',6,'Cuando el Gobierno cesa, ¿quién gobierna hasta que toma posesión el nuevo?','["El Presidente de la Asamblea", "El Consejero más antiguo", "El Gobierno cesante, en funciones", "El Delegado del Gobierno en la Comunidad"]'::jsonb,2,'Art. 24.2 EA','El Gobierno cesante sigue en funciones hasta que toma posesión el nuevo.',null),
('adm-cm:6-37d27dbdbf','adm-cm',6,'El Presidente de la Comunidad ostenta:','["La suprema representación de la Comunidad y la de la Asamblea", "La suprema representación de la Comunidad y la ordinaria del Estado en ella", "La representación ordinaria de la Comunidad y la suprema del Estado en ella", "La representación del Gobierno de la Nación en el territorio de Madrid"]'::jsonb,1,'Art. 17.1 EA','Ostenta la suprema representación de la Comunidad y la ordinaria del Estado en ella.',null),
('adm-cm:6-f91e6bdc00','adm-cm',6,'Respecto a sus prerrogativas, los diputados de la Asamblea:','["Son inviolables por las opiniones manifestadas en cualquier ámbito", "Gozan de inmunidad y no pueden ser juzgados sin autorización de la Asamblea", "Son inviolables por las opiniones manifestadas en el ejercicio de sus funciones", "Solo pueden ser detenidos con autorización previa de la Mesa"]'::jsonb,2,'Art. 11.5 EA','Son inviolables por las opiniones manifestadas en el ejercicio de sus funciones.',null),
('adm-cm:6-ae02c51901','adm-cm',6,'¿Qué tribunal decide sobre la inculpación, prisión, procesamiento y juicio de los diputados por delitos cometidos en el territorio de la Comunidad?','["El Tribunal Supremo, Sala de lo Penal", "La Audiencia Nacional, Sala de lo Penal", "La Audiencia Provincial de Madrid", "El Tribunal Superior de Justicia de Madrid"]'::jsonb,3,'Art. 11.6 EA','Corresponde al TSJ de Madrid. Fuera del territorio de la Comunidad, a la Sala de lo Penal del Tribunal Supremo.',null),
('adm-cm:6-ee077ae9aa','adm-cm',6,'En ordenación del territorio, urbanismo y vivienda, la Comunidad de Madrid tiene competencia:','["Exclusiva", "De desarrollo legislativo y ejecución", "Solo de ejecución", "Ninguna: es competencia del Estado"]'::jsonb,0,'Art. 26.1.4 EA','Es una de las materias de competencia exclusiva.',null),
('adm-cm:6-6871e363be','adm-cm',6,'En sanidad e higiene, la Comunidad de Madrid tiene competencia:','["Exclusiva, sin perjuicio de la alta inspección y coordinación general que corresponden al Estado", "Desarrollo legislativo, potestad reglamentaria y ejecución, en el marco de la legislación básica estatal", "Solo de ejecución de la legislación estatal, sin potestad reglamentaria propia en la materia", "Desarrollo legislativo y potestad reglamentaria, pero la ejecución corresponde al Estado"]'::jsonb,1,'Art. 27.4 EA','Desarrollo legislativo, potestad reglamentaria y ejecución en el marco de la legislación básica del Estado.',null),
('adm-cm:6-3874d3c6fe','adm-cm',6,'En propiedad intelectual e industrial, la Comunidad de Madrid tiene competencia:','["Exclusiva", "De desarrollo legislativo", "De ejecución de la legislación del Estado", "De desarrollo legislativo y potestad reglamentaria"]'::jsonb,2,'Art. 28.1.11 EA','La legislación es estatal; a la Comunidad le corresponde su ejecución.',null),
('adm-cm:6-31992e787b','adm-cm',6,'En materia de régimen local, la Comunidad de Madrid tiene, en el marco de la legislación básica del Estado:','["Competencia exclusiva sin límites", "Competencia de desarrollo legislativo, potestad reglamentaria y ejecución", "Competencia de ejecución, pero no de desarrollo legislativo ni de potestad reglamentaria", "Solo competencia de ejecución de la legislación del Estado, sin desarrollo legislativo"]'::jsonb,1,'Art. 27.1 EA','El art. 27 recoge las competencias de desarrollo legislativo.',null),
('adm-cm:6-28a38cee60','adm-cm',6,'Según el art. 45 del Estatuto, el Tribunal Superior de Justicia de Madrid:','["Es un órgano de la Asamblea de Madrid que culmina la organización judicial en la Comunidad, aunque las instancias se agotan ante el Tribunal Supremo", "Culmina la organización judicial en el ámbito territorial de la Comunidad, agotándose ante él las sucesivas instancias procesales", "Depende del Gobierno de la Comunidad, que nombra a su Presidente a propuesta de la Asamblea y del Consejo General del Poder Judicial", "Sustituye al Tribunal Supremo en todo"]'::jsonb,1,'Art. 45 EA','Sin perjuicio de la jurisdicción del Tribunal Supremo.',null),
('adm-cm:6-917f36609c','adm-cm',6,'Según el art. 9 del Estatuto, la Asamblea de Madrid:','["Representa al pueblo de Madrid, ejerce la potestad legislativa, aprueba y controla el Presupuesto e impulsa y controla la acción del Gobierno", "Dirige la Administración autonómica, ejerce la potestad reglamentaria general y nombra a los Consejeros a propuesta del Presidente, a quien elige entre sus miembros", "Nombra a los magistrados del Tribunal Superior de Justicia, dirige la Administración autonómica, ejerce la potestad reglamentaria general y aprueba los decretos", "Ejerce la potestad reglamentaria general"]'::jsonb,0,'Art. 9 EA','Son las funciones básicas de la Asamblea.','abr. 2026 · 1.er ejercicio'),
('adm-cm:6-19ccaccf42','adm-cm',6,'Según el art. 44 del Estatuto, el control económico y presupuestario de la Comunidad de Madrid se ejerce por:','["La Cámara de Cuentas, sin perjuicio de lo que corresponda al Tribunal de Cuentas", "El Banco de España y la Intervención General de la Administración del Estado, conjuntamente", "El Defensor del Pueblo", "El Consejo de Gobierno, a través de la Intervención General, sin perjuicio de lo que corresponda al Tribunal de Cuentas"]'::jsonb,0,'Art. 44 EA','La Cámara de Cuentas es el órgano de control externo autonómico.',null),
('adm-cm:6-1ec42058f3','adm-cm',6,'Según el art. 51 del Estatuto, la Comunidad de Madrid:','["Depende de las transferencias del Estado y de los municipios, sin capacidad tributaria propia", "Tiene un régimen de concierto económico con el Estado, como los territorios forales, con plena capacidad normativa sobre los tributos estatales en su territorio", "Goza de autonomía financiera, dentro de los principios de coordinación con las Haciendas estatal y local y de solidaridad", "Goza de autonomía financiera plena, sin sujeción a principios de coordinación con la Hacienda del Estado ni con las Haciendas locales de su territorio"]'::jsonb,2,'Art. 51 EA','Principio de autonomía financiera.',null),
('adm-cm:6-3331499507','adm-cm',6,'Según el art. 22.1 del Estatuto, el Gobierno de la Comunidad de Madrid es:','["Un organismo autónomo adscrito a la Presidencia", "El órgano colegiado que dirige la política de la Comunidad de Madrid", "El órgano unipersonal que dirige la política y la Administración de la Comunidad", "Un órgano consultivo de la Asamblea, que dirige la Administración de la Comunidad"]'::jsonb,1,'Art. 22.1 EA','Le corresponden las funciones ejecutivas y administrativas y la potestad reglamentaria no reservada a la Asamblea.',null),
('adm-cm:6-f208f7468c','adm-cm',6,'Según el art. 24.1 del Estatuto, el Gobierno cesa:','["Cada dos años, o cuando dimita cualquiera de sus miembros", "Cuando dimita cualquier Consejero, cuando lo decida el Gobierno de la Nación o cuando la Asamblea rechace el proyecto de ley de presupuestos generales de la Comunidad", "Tras la celebración de elecciones a la Asamblea, en los casos de pérdida de la confianza parlamentaria, o por dimisión, incapacidad o fallecimiento del Presidente", "Cuando lo decida el Gobierno de la Nación"]'::jsonb,2,'Art. 24.1 EA','Son las causas de cese del Gobierno.',null),
('adm-cm:6-3be8f32b74','adm-cm',6,'Según el art. 26.1.1 del Estatuto, la Comunidad de Madrid tiene competencia exclusiva en:','["La legislación penal y penitenciaria aplicable a los delitos cometidos en su territorio", "Las relaciones internacionales", "La defensa y las Fuerzas Armadas", "La organización, régimen y funcionamiento de sus instituciones de autogobierno"]'::jsonb,3,'Art. 26.1.1 EA','Es la primera de las materias de competencia exclusiva.',null),
('adm-cm:6-609462f441','adm-cm',6,'Según el art. 1.1 del Estatuto, Madrid organiza su autogobierno como Comunidad Autónoma:','["De conformidad con la Constitución Española y con el propio Estatuto", "Según lo que decida en cada momento el Gobierno de la Nación", "De conformidad con los tratados de la Unión Europea y con las leyes orgánicas de transferencia", "De acuerdo con la Ley de Bases de Régimen Local"]'::jsonb,0,'Art. 1.1 EA','El Estatuto es la norma institucional básica de la Comunidad.',null),
('adm-cm:6-f20f7bfc05','adm-cm',6,'La propuesta de reforma del Estatuto requiere la aprobación de la Asamblea de Madrid por mayoría de:','["Tres quintos, y la aprobación de las Cortes Generales mediante ley ordinaria", "Mayoría absoluta y real decreto", "Dos tercios, y la aprobación de las Cortes Generales mediante ley orgánica", "Mayoría absoluta, y la ratificación posterior mediante referéndum en la Comunidad"]'::jsonb,2,'Art. 64.1 EA','Es el procedimiento de reforma estatutaria.',null),
('adm-cm:6-07bfc9ede4','adm-cm',6,'Según el art. 29.1 del Estatuto, corresponde a la Comunidad de Madrid en materia de enseñanza:','["El desarrollo legislativo y la ejecución de la enseñanza en toda su extensión, niveles y grados", "Solo la ejecución de la legislación estatal en materia de enseñanza no universitaria", "Solo la enseñanza universitaria", "La expedición de títulos académicos con validez estatal sin control del Estado"]'::jsonb,0,'Art. 29.1 EA','Sin perjuicio de las competencias del Estado del art. 149.1.30.ª CE.',null),
('adm-cm:6-34faedc245','adm-cm',6,'Si una propuesta de reforma del Estatuto no es aprobada por la Asamblea, no podrá ser sometida nuevamente a debate y votación hasta que haya transcurrido:','["Seis meses", "Una legislatura completa", "Dos años", "Un año"]'::jsonb,3,'Art. 64.2 EA','Así lo establece el art. 64.2.',null),
('adm-cm:6-0aea50b407','adm-cm',6,'La Comunidad de Madrid puede establecer acuerdos de cooperación con otras Comunidades Autónomas:','["Libremente sin ninguna comunicación", "Previa autorización de las Cortes Generales", "Solo con las Comunidades limítrofes", "Previa autorización del Tribunal Constitucional"]'::jsonb,1,'Art. 31.2 EA','Los convenios para gestión de servicios propios solo requieren comunicación a las Cortes.',null),
('adm-cm:6-02b17af4a9','adm-cm',6,'Según el art. 1.3 del Estatuto, la Comunidad de Madrid aspira a hacer realidad los principios de:','["Seguridad, prosperidad y paz", "Pluralismo, eficacia, jerarquía y coordinación entre sus instituciones", "Unidad, orden y progreso", "Libertad, justicia e igualdad para todos los madrileños"]'::jsonb,3,'Art. 1.3 EA','Así lo recoge el art. 1.3 del Estatuto.',null),
('adm-cm:6-19b282896e','adm-cm',6,'Según el art. 32.1, la Comunidad de Madrid puede solicitar al Gobierno de la Nación:','["La celebración de tratados o convenios internacionales en materias de interés para Madrid", "La disolución anticipada de las Cortes Generales", "El nombramiento de embajadores", "La declaración del estado de alarma en todo caso, en todo o parte de su territorio"]'::jsonb,0,'Art. 32.1 EA','La competencia en relaciones internacionales es del Estado.',null),
('adm-cm:6-4be454ebae','adm-cm',6,'Según el art. 7.1 del Estatuto, los derechos y deberes fundamentales de los ciudadanos de Madrid son:','["Los que fije la Asamblea por mayoría simple", "Los establecidos en la Constitución", "Los del Código Civil", "Los establecidos en una Carta de Derechos madrileña"]'::jsonb,1,'Art. 7.1 EA','El Estatuto se remite a la Constitución.',null),
('adm-cm:6-b34dff4e07','adm-cm',6,'Las leyes de la Asamblea de Madrid se publican en el BOCM y en el BOE y entran en vigor, salvo que dispongan otra cosa:','["A los veinte días de su publicación en el BOE", "El 1 de enero siguiente", "Al día siguiente de su publicación en el Boletín Oficial de la Comunidad de Madrid", "A los veinte días de su publicación en el Boletín Oficial de la Comunidad de Madrid"]'::jsonb,2,'Art. 40.1 EA','La fecha que cuenta es la de publicación en el BOCM.',null),
('adm-cm:6-4584775e97','adm-cm',6,'La iniciativa para la reforma del Estatuto corresponde, entre otros, a la Asamblea de Madrid a propuesta de:','["Cinco diputados", "La mitad más uno de sus miembros", "Un grupo parlamentario cualquiera", "Una tercera parte de sus miembros"]'::jsonb,3,'Art. 64.1 EA','También al Gobierno y a dos tercios de los municipios que representen la mayoría absoluta de la población.',null),
('adm-cm:6-b1592785bc','adm-cm',6,'Según el art. 23.2 del Estatuto, el Gobierno responde políticamente ante la Asamblea:','["Ante el Tribunal Constitucional", "De forma individual exclusivamente, respondiendo cada Consejero por su gestión, sin responsabilidad solidaria", "Solo ante el Rey", "De forma solidaria, sin perjuicio de la responsabilidad directa de cada Consejero por su gestión"]'::jsonb,3,'Art. 23.2 EA','Responsabilidad solidaria del Gobierno.',null),
('adm-cm:6-92e827416b','adm-cm',6,'La Comunidad de Madrid puede asumir competencias no previstas en el Estatuto:','["Por decreto del Consejo de Gobierno, previa autorización de la Asamblea por mayoría absoluta y comunicación al Gobierno de la Nación", "Por acuerdo con otra Comunidad", "Mediante reforma del Estatuto o mediante decisión de las Cortes Generales (leyes de los arts. 150.1 y 150.2 CE)", "Por referéndum municipal convocado en todos los municipios de la Comunidad con el acuerdo de la Asamblea por mayoría de tres quintos"]'::jsonb,2,'Art. 30.1 EA','Vías de ampliación competencial.',null),
('adm-cm:6-0038d027ea','adm-cm',6,'Para adquirir la condición plena de Diputado de la Asamblea de Madrid se requiere:','["Prometer o jurar acatamiento a la Constitución y al Estatuto de Autonomía", "Tener más de 25 años y estar empadronado en un municipio de la Comunidad", "Ser vecino de Madrid capital", "Ser funcionario"]'::jsonb,0,'Art. 11.2 EA','Es requisito para ser Diputado de pleno derecho.',null),
('adm-cm:6-c867a9060b','adm-cm',6,'Según el Estatuto, la Comunidad de Madrid se organiza territorialmente en:','["Distritos y barrios con personalidad jurídica propia", "Mancomunidades obligatorias", "Provincias y comarcas, con personalidad jurídica propia", "Municipios, que gozan de plena personalidad jurídica"]'::jsonb,3,'Art. 3.1 EA','Los municipios pueden agruparse voluntariamente (art. 3.2).',null),
('adm-cm:6-1edd879567','adm-cm',6,'Las leyes de la Asamblea de Madrid están sujetas únicamente al control de constitucionalidad ejercido por:','["La Cámara de Cuentas", "El Tribunal Constitucional", "El Tribunal Superior de Justicia de Madrid", "El Consejo de Estado"]'::jsonb,1,'Art. 42 EA','Los reglamentos y actos se controlan por la jurisdicción contencioso-administrativa (art. 43).',null),
('adm-cm:6-afcee02039','adm-cm',6,'Tienen la condición política de ciudadanos de la Comunidad de Madrid:','["Los empadronados con más de diez años de residencia", "Todos los residentes en la Comunidad de Madrid, sean o no españoles, con independencia de su vecindad", "Los españoles que tengan vecindad administrativa en cualquiera de los municipios de la Comunidad", "Los nacidos en Madrid y los residentes extranjeros con más de diez años de empadronamiento en la Comunidad"]'::jsonb,2,'Art. 7.2 EA','La condición política depende de la vecindad administrativa.',null),
('adm-cm:6-e61de01db0','adm-cm',6,'Según el art. 33 del Estatuto, en las materias de competencia exclusiva de la Comunidad, el Derecho propio de Madrid:','["Es supletorio del Derecho estatal, que se aplica con preferencia en todo el territorio nacional", "Necesita confirmación de las Cortes", "Solo se aplica en la capital", "Es aplicable en su territorio con preferencia a cualquier otro, siendo el Derecho estatal supletorio"]'::jsonb,3,'Art. 33 EA','El Derecho estatal tiene carácter supletorio.',null),
('adm-cm:7-8d86124bdd','adm-cm',7,'Según la Ley 1/1983, ¿cuáles son los órganos superiores de Gobierno y Administración de la Comunidad de Madrid?','["El Presidente, el Consejo de Gobierno y los Consejeros", "El Presidente, la Asamblea y los Consejeros", "El Consejo de Gobierno y los Viceconsejeros", "El Presidente, los Consejeros y los Directores Generales"]'::jsonb,0,'Art. 1.1 Ley 1/1983','Los órganos superiores son el Presidente, el Consejo de Gobierno y los Consejeros.',null),
('adm-cm:7-c5eec221c5','adm-cm',7,'El Presidente de la Comunidad de Madrid, elegido por la Asamblea, es nombrado:','["Por el Presidente del Gobierno de la Nación mediante decreto", "Por el Rey mediante Real Decreto", "Por la Asamblea mediante resolución", "Por el Consejo de Gobierno"]'::jsonb,1,'Art. 4 Ley 1/1983','Es elegido por la Asamblea de entre sus miembros y nombrado por el Rey mediante Real Decreto.',null),
('adm-cm:7-9b7a556c50','adm-cm',7,'¿Qué tratamiento corresponde al Presidente de la Comunidad?','["Ilustrísimo", "Señoría", "Excelencia", "Honorable"]'::jsonb,2,'Art. 5 Ley 1/1983','El Presidente tiene tratamiento de excelencia.',null),
('adm-cm:7-fbbb3a31e6','adm-cm',7,'El sueldo del Presidente de la Comunidad no puede superar el asignado en los Presupuestos Generales del Estado a:','["Un Ministro", "El Presidente del Gobierno", "Un diputado del Congreso", "Un Secretario de Estado"]'::jsonb,3,'Art. 5 Ley 1/1983','No puede ser superior al de un Secretario de Estado.',null),
('adm-cm:7-5b9f007071','adm-cm',7,'El cargo de Presidente de la Comunidad es compatible con:','["La condición de Diputado de la Asamblea", "El cargo de alcalde de un municipio de la Comunidad de Madrid", "La condición de senador por designación autonómica", "La condición de Diputado en el Congreso"]'::jsonb,0,'Art. 6 Ley 1/1983','Es incompatible con otras funciones públicas, salvo la de Diputado de la Asamblea, y con cualquier actividad laboral, profesional o empresarial.','nov. 2024 · 1.er ejercicio'),
('adm-cm:7-3832267c00','adm-cm',7,'El Presidente de la Comunidad promulga las Leyes de la Asamblea y los Decretos legislativos:','["En nombre de la Asamblea", "En nombre del Rey", "En nombre del pueblo de Madrid", "No los promulga: lo hace el Presidente de la Asamblea"]'::jsonb,1,'Art. 8 a) Ley 1/1983','Los promulga en nombre del Rey.',null),
('adm-cm:7-2cc9187e41','adm-cm',7,'¿Quién convoca las elecciones a la Asamblea de Madrid?','["El Presidente de la Asamblea", "El Consejo de Gobierno", "El Presidente de la Comunidad", "La Junta Electoral"]'::jsonb,2,'Art. 7 c) Ley 1/1983','Las convoca el Presidente de la Comunidad, en los términos del art. 11 del Estatuto.',null),
('adm-cm:7-a09d50ec30','adm-cm',7,'El Presidente plantea ante la Asamblea la cuestión de confianza:','["Previa autorización de la Asamblea", "Previo acuerdo de cuatro quintos del Consejo", "Sin ningún trámite previo", "Previa deliberación del Consejo de Gobierno"]'::jsonb,3,'Art. 9 l) Ley 1/1983','La plantea previa deliberación del Consejo de Gobierno.',null),
('adm-cm:7-6449d6352c','adm-cm',7,'Cuando el Presidente delega funciones ejecutivas o de representación, debe dar cuenta a la Asamblea en:','["48 horas, y publicar la delegación en el BOCM", "15 días, y publicar la delegación en el BOCM", "72 horas, sin necesidad de publicarla en ningún boletín", "Un mes, y publicar la delegación en el BOE"]'::jsonb,0,'Art. 10.1 Ley 1/1983','Da cuenta a la Asamblea en 48 horas y publica la delegación en el BOCM.',null),
('adm-cm:7-8e96507e68','adm-cm',7,'¿Cuál de estas atribuciones NO puede delegar el Presidente?','["La representación en un acto oficial", "Nombrar y separar a los Consejeros", "Funciones ejecutivas propias en un Vicepresidente", "Funciones de representación en un Consejero"]'::jsonb,1,'Art. 10.2 Ley 1/1983','No son delegables, entre otras, las del art. 9 a): nombrar y separar a los Consejeros.',null),
('adm-cm:7-3069042591','adm-cm',7,'¿Cuántos asesores puede tener como máximo el Gabinete del Presidente?','["Cuatro", "Cinco", "Seis", "Ocho"]'::jsonb,2,'Art. 11.2 Ley 1/1983','El Gabinete tiene hasta seis asesores.',null),
('adm-cm:7-5ce407792f','adm-cm',7,'El Jefe del Gabinete del Presidente tiene rango de:','["Viceconsejero", "Secretario General Técnico", "Consejero", "Director general"]'::jsonb,3,'Art. 11.3 Ley 1/1983','Tiene rango de Director general y lo nombra el Consejo de Gobierno a propuesta del Presidente.',null),
('adm-cm:7-3033b6ba7d','adm-cm',7,'Las ausencias temporales del Presidente de más de un mes requieren:','["Autorización previa de la Asamblea", "Acuerdo del Consejo de Gobierno", "Autorización del Rey", "Ningún requisito"]'::jsonb,0,'Art. 12 Ley 1/1983','Requieren autorización previa de la Asamblea.',null),
('adm-cm:7-21d507548e','adm-cm',7,'La incapacidad transitoria del Presidente exige un acuerdo del Consejo de Gobierno adoptado por:','["Mayoría absoluta", "Cuatro quintas partes de sus miembros", "Dos tercios de sus miembros", "Tres quintas partes de sus miembros"]'::jsonb,1,'Art. 13.1 Ley 1/1983','Se exige acuerdo del Consejo por cuatro quintas partes de sus miembros.',null),
('adm-cm:7-f9c5ad1267','adm-cm',7,'La Asamblea puede revocar el acuerdo de incapacidad transitoria del Presidente por:','["Mayoría simple", "Tres quintos", "Mayoría absoluta", "Dos tercios"]'::jsonb,2,'Art. 13.3 Ley 1/1983','La Asamblea puede revocarlo por mayoría absoluta.',null),
('adm-cm:7-0316ef17d0','adm-cm',7,'¿Qué limitación tiene el Presidente interino?','["No puede presidir el Consejo de Gobierno ni firmar decretos de estructura de las Consejerías", "No puede firmar ningún acto ni disposición administrativa sin autorización de la Asamblea", "No puede nombrar Consejeros, pero sí separarlos de su cargo", "No puede definir el programa de Gobierno ni nombrar o separar Consejeros"]'::jsonb,3,'Art. 14 Ley 1/1983','No puede definir el programa de Gobierno ni nombrar o separar Consejeros.',null),
('adm-cm:7-f0731bc9e7','adm-cm',7,'¿Cuánto puede durar como máximo la interinidad en la Presidencia?','["Dos meses, ampliables otros dos por acuerdo de la Asamblea por mayoría absoluta", "Un mes, ampliable otro más por acuerdo de la Asamblea por mayoría simple", "Seis meses, sin posibilidad de prórroga", "Tres meses, ampliables otros tres por acuerdo del Consejo de Gobierno"]'::jsonb,0,'Art. 15.1 Ley 1/1983','No puede superar dos meses, ampliables en otros dos con acuerdo de la Asamblea por mayoría absoluta.',null),
('adm-cm:7-7933ce7e55','adm-cm',7,'¿Cuál de las siguientes NO es causa de cese del Presidente?','["Dimisión comunicada a la Asamblea", "Fallecimiento o incapacidad física permanente", "Incapacidad permanente declarada por la Asamblea", "Pérdida de la afiliación a su partido"]'::jsonb,3,'Art. 16.1 Ley 1/1983','Las causas son: renovación de la Asamblea, moción de censura, denegación de la cuestión de confianza, dimisión, incapacidad permanente y fallecimiento.',null),
('adm-cm:7-56c859ca52','adm-cm',7,'¿Quién sustituye al Presidente?','["El Presidente de la Asamblea y, después, los Vicepresidentes", "Los Vicepresidentes y, después, los Consejeros por el orden establecido", "El Consejero más antiguo y, después, el de mayor edad, por orden de nombramiento", "Los Consejeros por orden de antigüedad, sin pasar por los Vicepresidentes"]'::jsonb,1,'Art. 17.1 Ley 1/1983','Primero los Vicepresidentes y después los Consejeros, por el orden del art. 19.2.',null),
('adm-cm:7-ee94aafc0f','adm-cm',7,'El Presidente en funciones:','["Puede ser objeto de moción de censura, pero no plantear la cuestión de confianza", "Puede plantear la cuestión de confianza, pero no ser objeto de moción de censura", "No puede ser objeto de moción de censura ni plantear la cuestión de confianza", "Puede disolver la Asamblea, pero no plantear la cuestión de confianza"]'::jsonb,2,'Art. 17.2 Ley 1/1983','No puede ser objeto de moción de censura ni plantear la cuestión de confianza.',null),
('adm-cm:7-ec71c75bd9','adm-cm',7,'Según el art. 18, el Consejo de Gobierno ejerce:','["La potestad legislativa, la función ejecutiva y la potestad reglamentaria", "La iniciativa legislativa, la función ejecutiva y el control de la Asamblea", "La iniciativa legislativa, la función ejecutiva y la potestad reglamentaria", "La función ejecutiva y la potestad reglamentaria, pero no la iniciativa legislativa"]'::jsonb,2,'Art. 18 Ley 1/1983','Dirige la política y la Administración, y ejerce la iniciativa legislativa, la función ejecutiva y la potestad reglamentaria.',null),
('adm-cm:7-3154382594','adm-cm',7,'¿Con qué periodicidad se reúne el Consejo de Gobierno?','["Con una periodicidad igual o menor a un mes, salvo convocatoria urgente", "Con una periodicidad igual o menor a una semana", "Cuando lo convoque su Presidente, sin periodicidad fija", "Con una periodicidad igual o menor a quince días"]'::jsonb,3,'Art. 23.1 Ley 1/1983','Se reúne por convocatoria del Presidente con una periodicidad igual o menor a quince días.',null),
('adm-cm:7-3c25ba6f18','adm-cm',7,'Para que las reuniones del Consejo de Gobierno sean válidas se requiere la presencia de:','["El Presidente o su sustituto y, al menos, la mitad de los Consejeros", "El Presidente o su sustituto y, al menos, dos tercios de los Consejeros", "El Presidente y, al menos, un tercio de los Consejeros", "El Presidente, sin sustitución posible, y la mayoría de los Consejeros"]'::jsonb,0,'Art. 24 Ley 1/1983','Presidente o sustituto y, al menos, la mitad de los Consejeros.',null),
('adm-cm:7-51ddca4a60','adm-cm',7,'En caso de empate en una votación del Consejo de Gobierno:','["Se repite la votación en la siguiente sesión", "Decide el voto del Presidente", "Decide la Asamblea", "Se entiende rechazada la propuesta"]'::jsonb,1,'Art. 24 Ley 1/1983','El voto del Presidente es dirimente.',null),
('adm-cm:7-490c877f80','adm-cm',7,'Las deliberaciones del Consejo de Gobierno:','["Son públicas, salvo que el Consejo acuerde lo contrario", "Se recogen íntegramente en actas que se publican en el BOCM", "Tienen carácter reservado y sus miembros deben guardar secreto", "Son reservadas, pero cualquier Consejero puede difundir su voto"]'::jsonb,2,'Art. 25.1 Ley 1/1983','Tienen carácter reservado y sus miembros deben guardar secreto.',null),
('adm-cm:7-d41dc58288','adm-cm',7,'¿Quién actúa como Secretario del Consejo de Gobierno y extiende las actas?','["El Consejero de Hacienda", "El Vicepresidente primero de la Comunidad", "El Secretario General Técnico de la Consejería de Presidencia", "El Consejero de la Presidencia"]'::jsonb,3,'Art. 25.3 Ley 1/1983','Extiende las actas el Consejero de la Presidencia como Secretario.',null),
('adm-cm:7-07fd40912f','adm-cm',7,'Las Comisiones Delegadas del Consejo de Gobierno están presididas por:','["El Presidente, que puede delegar en el Consejero de la Presidencia", "El Presidente, que puede delegar en el Consejero más antiguo", "El Consejero de la Presidencia, sin posibilidad de delegación", "El Vicepresidente primero, que puede delegar en un Viceconsejero"]'::jsonb,0,'Art. 26 Ley 1/1983','Las preside el Presidente, que puede delegar en el Consejero de la Presidencia.',null),
('adm-cm:7-d6aa735934','adm-cm',7,'¿Quién refrenda los Decretos aprobados a propuesta de una Consejería?','["El Presidente de la Asamblea", "El Consejero correspondiente", "El Secretario General Técnico", "Nadie: no requieren refrendo"]'::jsonb,1,'Art. 31 b) Ley 1/1983','Los Consejeros proponen los proyectos de Decreto de su Consejería y los refrendan una vez aprobados.',null),
('adm-cm:7-a141d9c7f7','adm-cm',7,'El Consejo de Gobierno responde de su política:','["Individualmente cada Consejero ante la Asamblea, sin responsabilidad solidaria", "Solidariamente ante el Tribunal Superior de Justicia de Madrid", "Solidariamente ante la Asamblea, sin perjuicio de la responsabilidad de cada Consejero", "Solidariamente ante el Presidente, que responde ante la Asamblea"]'::jsonb,2,'Art. 34.1 Ley 1/1983','Responde solidariamente ante la Asamblea, sin perjuicio de la responsabilidad individual de cada Consejero.',null),
('adm-cm:7-cdb7e32809','adm-cm',7,'¿Cómo se nombra a los Viceconsejeros, Secretarios Generales Técnicos y Directores Generales?','["Por orden del Consejero correspondiente, dando cuenta al Consejo de Gobierno", "Por decreto del Presidente, a propuesta del Consejero correspondiente", "Por acuerdo de la Asamblea, a propuesta del Consejo de Gobierno", "Por Decreto del Consejo de Gobierno, a propuesta del Consejero correspondiente"]'::jsonb,3,'Arts. 39.3, 44.3 y 45 Ley 1/1983','Se nombran por Decreto del Consejo de Gobierno, a propuesta del Consejero correspondiente.','oct. 2026 · 1.er ejercicio'),
('adm-cm:7-8c51f89d78','adm-cm',7,'¿Cómo se estructuran las Consejerías?','["Secretaría General Técnica y Direcciones Generales, y pueden tener Viceconsejeros", "Direcciones Generales y Subdirecciones Generales, sin Secretaría General Técnica propia", "Subsecretaría y Secretarías Generales, igual que los ministerios del Estado", "Viceconsejería y Delegaciones territoriales en cada zona de la región, sin Direcciones Generales"]'::jsonb,0,'Art. 39.1 Ley 1/1983','Cada Consejería tiene una Secretaría General Técnica, se estructura en Direcciones Generales y puede tener Viceconsejeros.','oct. 2026 · 1.er ejercicio'),
('adm-cm:7-4f01be6487','adm-cm',7,'Si el Presidente delega temporalmente funciones en un Consejero, ¿queda exento de responsabilidad política?','["Sí, la asume el Consejero", "No", "Solo si la delegación se publica en el BOCM", "Solo si la Asamblea la autoriza"]'::jsonb,1,'Art. 35 Ley 1/1983','La delegación temporal no exime al Presidente de responsabilidad política.',null),
('adm-cm:7-bc7b73801f','adm-cm',7,'Según el art. 2 de la Ley 1/1983, el Presidente de la Comunidad ostenta:','["La suprema representación de la Comunidad Autónoma y la ordinaria del Estado en ella", "La jefatura del Consejo de Gobierno, pero no la representación del Estado", "La representación ordinaria de la Comunidad y la suprema del Estado en ella", "La presidencia de la Asamblea"]'::jsonb,0,'Art. 2 Ley 1/1983','Así lo establece el art. 2.',null),
('adm-cm:7-1edaba5e3d','adm-cm',7,'Corresponde al Presidente, como Presidente del Consejo de Gobierno, resolver:','["Los conflictos de competencias entre las distintas Consejerías", "Los recursos contencioso-administrativos", "Los conflictos de competencias entre la Comunidad y los municipios de su territorio", "Los recursos de amparo y los conflictos con otras Comunidades Autónomas"]'::jsonb,0,'Art. 9 e) Ley 1/1983','Es una atribución presidencial indelegable.',null),
('adm-cm:7-febd193923','adm-cm',7,'Según el art. 37.2 de la Ley 1/1983, la actuación de la Administración de la Comunidad se rige, entre otros, por los principios de:','["Objetividad, publicidad, celeridad, eficacia y economía", "Centralización, jerarquía, unidad de mando y reserva de las actuaciones", "Secreto y discrecionalidad", "Jerarquía, reserva de las actuaciones y libre arbitrio del órgano"]'::jsonb,0,'Art. 37.2 Ley 1/1983','Son principios de actuación administrativa.',null),
('adm-cm:7-f990d31bb5','adm-cm',7,'Corresponde al Consejo de Gobierno dictar Decretos legislativos:','["Libremente", "Previa autorización de las Cortes Generales", "Previo dictamen del Tribunal Constitucional", "Previa autorización de la Asamblea"]'::jsonb,3,'Art. 21 e) Ley 1/1983','Es la delegación legislativa autonómica.',null),
('adm-cm:7-bec9451af6','adm-cm',7,'Los Consejeros cesan:','["Solo por moción de censura individual aprobada por la Asamblea", "Por decisión de la Asamblea en todo caso", "Por dimisión aceptada por el Presidente, por cese decretado por el Presidente o por fallecimiento", "Por cese acordado por el Consejo de Gobierno, por dimisión aceptada por la Asamblea o por fallecimiento"]'::jsonb,2,'Art. 29 Ley 1/1983','También cesan cuando cesa el Presidente que los nombró.',null),
('adm-cm:7-78daf28fd3','adm-cm',7,'Las reclamaciones previas a la vía judicial civil y laboral en la Comunidad de Madrid las resuelven:','["Los Directores generales", "El Consejo de Gobierno", "El Presidente de la Comunidad", "Los Consejeros respectivos"]'::jsonb,3,'Art. 53.7 Ley 1/1983','Según el art. 53.7 de la Ley 1/1983.',null),
('adm-cm:7-d12b350017','adm-cm',7,'Según la Ley 1/1983, conoce en única instancia de las reclamaciones económico-administrativas en la Comunidad de Madrid:','["El Tribunal Económico-Administrativo Central", "La Cámara de Cuentas", "La Junta Superior de Hacienda", "El Consejo de Gobierno"]'::jsonb,2,'Art. 54.2 Ley 1/1983','Órgano de la Comunidad para reclamaciones económico-administrativas.',null),
('adm-cm:7-0899cc3b35','adm-cm',7,'Corresponde al Consejo de Gobierno, según la Ley 1/1983:','["Interponer recursos de inconstitucionalidad y personarse ante el Tribunal Constitucional", "Designar a los Senadores que corresponden a la Comunidad y proponer su cese a la Asamblea", "Juzgar a los Consejeros y exigirles responsabilidad penal y civil por los actos cometidos en el ejercicio de su cargo", "Aprobar el Reglamento de la Asamblea"]'::jsonb,0,'Art. 21 l) Ley 1/1983','Es una atribución del Consejo de Gobierno.',null),
('adm-cm:7-d73dc5b6be','adm-cm',7,'Corresponde al Consejo de Gobierno nombrar y separar a los altos cargos de la Comunidad con categoría:','["De Jefe de Negociado", "Igual o superior a Director general", "Igual o superior a Jefe de Servicio", "De funcionario de carrera"]'::jsonb,1,'Art. 21 m) Ley 1/1983','Los nombramientos se hacen por Decreto.',null),
('adm-cm:7-28f4172036','adm-cm',7,'Ponen fin a la vía administrativa, según la Ley 1/1983:','["Los actos de trámite que decidan directa o indirectamente el fondo del asunto", "Las resoluciones del Presidente, del Consejo de Gobierno y sus Comisiones, y de los Consejeros, entre otras", "Las resoluciones de los Directores generales y de los Secretarios Generales Técnicos, en todo caso", "Las resoluciones de los Jefes de Servicio"]'::jsonb,1,'Art. 53.1 Ley 1/1983','Salvo que una ley establezca otra cosa.',null),
('adm-cm:7-a11ee30ee5','adm-cm',7,'El Consejo de Gobierno puede variar la denominación y el número de las Consejerías:','["Solo mediante ley de la Asamblea", "Por Decreto, dentro del límite establecido en el Estatuto", "Por orden del Consejero de Presidencia, previa deliberación del Consejo de Gobierno", "Solo mediante reforma del Estatuto"]'::jsonb,1,'Art. 19.3 Ley 1/1983','La estructura de Consejerías se fija por Decreto.',null),
('adm-cm:7-7d86ff06da','adm-cm',7,'Las disposiciones de los Consejeros adoptan la forma de:','["Decretos", "Acuerdos", "Decretos legislativos", "Órdenes"]'::jsonb,3,'Art. 50 Ley 1/1983','Las de los órganos inferiores se llaman Resoluciones.',null),
('adm-cm:7-9fde2258e0','adm-cm',7,'Los Directores generales deben elevar anualmente al Consejero:','["Su declaración de bienes y actividades", "La memoria anual de la Cámara de Cuentas sobre su centro directivo", "Un informe sobre la marcha, rendimiento y costes de sus servicios", "El anteproyecto de presupuesto de su Dirección General, que aprueba directamente el Consejero"]'::jsonb,2,'Art. 47 c) Ley 1/1983','Es una atribución de los Directores generales.',null),
('adm-cm:7-a2addd09f4','adm-cm',7,'Según la Ley 1/1983, la tramitación de los expedientes de gasto de la Consejería corresponde a:','["La Dirección General de Presupuestos en todo caso", "La Intervención General", "La Secretaría General Técnica", "El Gabinete del Consejero"]'::jsonb,2,'Art. 46.5 Ley 1/1983','Es una de las funciones de la Secretaría General Técnica.',null),
('adm-cm:7-279f1bd763','adm-cm',7,'En caso de ausencia de un Consejero, el Presidente puede encargar el despacho de su Consejería a otro Consejero:','["Previa autorización del Tribunal Superior de Justicia", "Sin ninguna comunicación", "Dando cuenta por escrito a la Asamblea", "Previo acuerdo de la Mesa de la Asamblea"]'::jsonb,2,'Art. 9 i) Ley 1/1983','Debe comunicarse por escrito a la Asamblea.',null),
('adm-cm:7-5e0cd31f4b','adm-cm',7,'La competencia para resolver los procedimientos de responsabilidad patrimonial corresponde, según la Ley 1/1983:','["Al Consejero respectivo", "Al Presidente de la Comunidad", "A la Asamblea", "Al Tribunal Superior de Justicia"]'::jsonb,0,'Art. 55.2 Ley 1/1983','Salvo los supuestos atribuidos a otros órganos.',null),
('adm-cm:7-85bdd63e69','adm-cm',7,'Según el art. 30.3 de la Ley 1/1983, la denominación de «Consejero»:','["Puede usarla cualquier asesor del Gobierno", "Es la que corresponde a los diputados de la Asamblea que forman parte de las comisiones de gobierno", "Corresponde también a los Viceconsejeros y a los Directores generales, cuando asistan al Consejo de Gobierno", "Queda reservada a los miembros del Gobierno o de determinadas instituciones de la Comunidad"]'::jsonb,3,'Art. 30.3 Ley 1/1983','Apartado añadido por la Ley 3/2007.',null),
('adm-cm:7-dee37d4725','adm-cm',7,'Las disposiciones y resoluciones del Consejo de Gobierno adoptan la forma de:','["Decretos del Consejo de Gobierno o Acuerdos", "Instrucciones", "Leyes o Decretos legislativos del Gobierno regional", "Órdenes del Consejo de Gobierno o Resoluciones"]'::jsonb,0,'Art. 50 Ley 1/1983','Las de los Consejeros adoptan la forma de Órdenes y las de órganos inferiores, Resoluciones.',null),
('adm-cm:7-57ce187c07','adm-cm',7,'Según la Ley 1/1983, las disposiciones administrativas de carácter general entran en vigor, salvo que dispongan otra cosa:','["Al día siguiente de su publicación en el Boletín Oficial del Estado", "A los veinte días de su publicación en el Boletín Oficial de la Comunidad de Madrid", "A los tres meses", "Al mes de su aprobación"]'::jsonb,1,'Art. 51.3 Ley 1/1983','Distinto de las leyes, que entran en vigor al día siguiente de su publicación en el BOCM (art. 40 EA).',null),
('adm-cm:7-9eb0a1a1ff','adm-cm',7,'Los Consejeros tienen la obligación de:','["Residir en la sede de la Asamblea", "Formar parte de la Mesa de la Asamblea y asistir a todas las sesiones de las comisiones parlamentarias", "Pedir autorización a la Asamblea para cada Orden", "Acudir a la Asamblea cuando esta lo reclame y contestar a sus preguntas e interpelaciones"]'::jsonb,3,'Art. 32.1 Ley 1/1983','Es parte del control parlamentario.',null),
('adm-cm:7-054d5bca12','adm-cm',7,'El cargo de Viceconsejero es:','["Compatible con el de Senador y con el de Diputado al mismo tiempo, acumulando sus dietas", "Compatible con el de Diputado de la Asamblea, sin acumular las dietas de este", "Un cargo electivo designado por la Asamblea a propuesta del Consejero correspondiente", "Incompatible con el de Diputado"]'::jsonb,1,'Art. 44.4 Ley 1/1983','Así lo dispone la Ley 1/1983.',null),
('adm-cm:8-6776e6b248','adm-cm',8,'¿Qué tratado creó en 1951 la Comunidad Europea del Carbón y del Acero?','["El Tratado de Roma", "El Tratado de Bruselas", "El Tratado de Maastricht", "El Tratado de París"]'::jsonb,3,'Tratados constitutivos','Los Tratados de Roma de 1957 crearon la CEE y la Comunidad Europea de la Energía Atómica (Euratom).',null),
('adm-cm:8-f5761dad8e','adm-cm',8,'Los Tratados de Roma de 1957 crearon:','["La Comunidad Europea del Carbón y del Acero y el Consejo de Europa con sede en Estrasburgo", "La Comunidad Económica Europea y la Comunidad Europea de la Energía Atómica", "La Unión Europea y el Banco Central Europeo como su institución monetaria común", "El Espacio Económico Europeo y la Unión Europea Occidental de defensa común"]'::jsonb,1,'Tratados constitutivos','La CECA se creó en 1951 por el Tratado de París.',null),
('adm-cm:8-aa9b1478e5','adm-cm',8,'¿Qué tratado creó la Unión Europea?','["El Tratado de Maastricht de 1992", "El Tratado de Ámsterdam de 1997", "El Tratado de Lisboa de 2007", "El Acta Única Europea de 1986"]'::jsonb,0,'Tratado de la Unión Europea','Se firmó en 1992 y entró en vigor en noviembre de 1993.',null),
('adm-cm:8-8f9bc182e1','adm-cm',8,'¿Cuándo entró en vigor el Tratado de Lisboa?','["El 1 de enero de 2008", "El 13 de diciembre de 2007", "El 1 de diciembre de 2009", "El 1 de noviembre de 1993"]'::jsonb,2,'Tratado de Lisboa','Se firmó el 13 de diciembre de 2007.',null),
('adm-cm:8-6e4d36b25f','adm-cm',8,'¿Desde qué fecha es España miembro de las Comunidades Europeas?','["Desde el 1 de enero de 1986", "Desde el 1 de enero de 1981", "Desde el 1 de noviembre de 1993", "Desde el 12 de junio de 1985"]'::jsonb,0,'Adhesión de España','El Tratado de adhesión se firmó el 12 de junio de 1985, junto con Portugal.',null),
('adm-cm:8-e6a795c94b','adm-cm',8,'¿Cuántas instituciones enumera el artículo 13 del Tratado de la Unión Europea?','["Cinco", "Seis", "Nueve", "Siete"]'::jsonb,3,'Art. 13 TUE','Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la UE, Banco Central Europeo y Tribunal de Cuentas.',null),
('adm-cm:8-cf380e4fcb','adm-cm',8,'¿Cuál de los siguientes NO es una institución de la Unión según el artículo 13 del TUE?','["El Comité de las Regiones", "El Tribunal de Cuentas", "El Banco Central Europeo", "El Consejo Europeo"]'::jsonb,0,'Art. 13 TUE','El Comité de las Regiones y el Comité Económico y Social son órganos consultivos, no instituciones.',null),
('adm-cm:8-c7e8d3b894','adm-cm',8,'¿Por cuánto tiempo se elige a los miembros del Parlamento Europeo?','["Cinco años", "Cuatro años", "Dos años y medio", "Seis años"]'::jsonb,0,'Art. 14.3 TUE','Se eligen por sufragio universal directo, libre y secreto.',null),
('adm-cm:8-55407166f5','adm-cm',8,'El número de miembros del Parlamento Europeo no puede exceder de:','["700, incluido el Presidente", "750, más el Presidente", "751, más el Presidente", "800, más el Presidente"]'::jsonb,1,'Art. 14.2 TUE','Ningún Estado puede tener más de 96 escaños ni menos de 6.',null),
('adm-cm:8-4314eeb997','adm-cm',8,'¿Dónde tiene su sede oficial el Parlamento Europeo?','["En Fráncfort", "En Luxemburgo", "En Bruselas", "En Estrasburgo"]'::jsonb,3,'Sedes de las instituciones','También trabaja en Bruselas y su Secretaría General está en Luxemburgo.',null),
('adm-cm:8-dcf5e10bed','adm-cm',8,'¿Quiénes componen el Consejo Europeo?','["Los Ministros de Asuntos Exteriores de los Estados miembros, el Alto Representante y el Presidente de la Comisión", "Un representante de cada Estado miembro de rango ministerial", "Los Presidentes de los Parlamentos nacionales de los Estados miembros y el Presidente del Parlamento Europeo", "Los Jefes de Estado o de Gobierno de los Estados miembros, su Presidente y el Presidente de la Comisión"]'::jsonb,3,'Art. 15.2 TUE','El Alto Representante participa en sus trabajos, pero no es miembro.',null),
('adm-cm:8-674f0e7e85','adm-cm',8,'El Presidente del Consejo Europeo es elegido por un mandato de:','["Seis meses, coincidiendo con la presidencia rotatoria", "Cinco años, no renovable", "Dos años, renovable indefinidamente", "Dos años y medio, renovable una sola vez"]'::jsonb,3,'Art. 15.5 TUE','Lo elige el propio Consejo Europeo por mayoría cualificada.',null),
('adm-cm:8-4a12198dae','adm-cm',8,'El Consejo de la Unión Europea está compuesto por:','["Un representante de cada Estado miembro de rango ministerial", "Un comisario por cada Estado miembro, nombrado por su Gobierno nacional", "Los Jefes de Estado o de Gobierno de los Estados miembros y su Presidente", "Los embajadores de los Estados miembros ante la Unión, con rango de representantes permanentes"]'::jsonb,0,'Art. 16.2 TUE','Ese representante puede comprometer al Gobierno de su Estado y ejercer el derecho de voto.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:8-187bf9b6ec','adm-cm',8,'¿Cada cuánto tiempo rota la presidencia del Consejo de la Unión Europea entre los Estados miembros?','["Cada año", "Cada dos años y medio", "Cada seis meses", "Cada tres meses"]'::jsonb,2,'Presidencia del Consejo','La única excepción es el Consejo de Asuntos Exteriores, que preside el Alto Representante.',null),
('adm-cm:8-991d8d6fce','adm-cm',8,'Desde 2014, la mayoría cualificada en el Consejo se define como:','["Al menos dos tercios de los Estados miembros que representen como mínimo la mitad de la población de la Unión", "La mayoría absoluta de los Estados miembros, sea cual sea su población, siempre que incluya a los cuatro más poblados", "Al menos el 55 % de los miembros del Consejo que representen al menos el 65 % de la población de la Unión", "Al menos el 65 % de los miembros del Consejo que representen como mínimo el 55 % de la población de la Unión"]'::jsonb,2,'Art. 16.4 TUE','La minoría de bloqueo debe incluir al menos a cuatro miembros del Consejo.',null),
('adm-cm:8-76973ff4a7','adm-cm',8,'¿Qué institución tiene, como regla general, la iniciativa legislativa en la Unión Europea?','["La Comisión Europea", "El Consejo Europeo", "El Consejo de la Unión", "El Parlamento Europeo"]'::jsonb,0,'Art. 17.2 TUE','Los actos legislativos solo pueden adoptarse a propuesta de la Comisión, salvo que los Tratados dispongan otra cosa.',null),
('adm-cm:8-20126f5efb','adm-cm',8,'¿Cómo se elige al Presidente de la Comisión Europea?','["Lo eligen los ciudadanos de la Unión por sufragio universal directo cada cinco años", "Lo nombra el Consejo de la Unión por mayoría simple, a propuesta del Parlamento Europeo", "El Consejo Europeo propone un candidato por mayoría cualificada y el Parlamento Europeo lo elige por mayoría de sus miembros", "Lo elige directamente el Consejo Europeo por unanimidad, sin intervención del Parlamento"]'::jsonb,2,'Art. 17.7 TUE','El Consejo Europeo tiene en cuenta el resultado de las elecciones al Parlamento Europeo.',null),
('adm-cm:8-835612793e','adm-cm',8,'¿Qué cargo ocupa el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad dentro de la Comisión?','["Es su Secretario General, con voz pero sin voto", "Es uno de sus Vicepresidentes", "Es su Presidente, por razón de su cargo", "No forma parte de la Comisión, sino del Consejo Europeo"]'::jsonb,1,'Art. 18.4 TUE','Además preside el Consejo de Asuntos Exteriores.',null),
('adm-cm:8-739469b78f','adm-cm',8,'¿Dónde tiene su sede el Tribunal de Justicia de la Unión Europea?','["En Bruselas", "En Estrasburgo", "En Luxemburgo", "En La Haya"]'::jsonb,2,'Sedes de las instituciones','En La Haya está el Tribunal Internacional de Justicia y en Estrasburgo el Tribunal Europeo de Derechos Humanos, que no son órganos de la UE.',null),
('adm-cm:8-a744911a7d','adm-cm',8,'¿Dónde tiene su sede el Banco Central Europeo?','["En Ámsterdam", "En Luxemburgo", "En Bruselas", "En Fráncfort"]'::jsonb,3,'Sedes de las instituciones','El BCE dirige la política monetaria de la zona euro.',null),
('adm-cm:8-5cec018daf','adm-cm',8,'Según el artículo 288 del TFUE, el reglamento:','["Obliga al Estado destinatario en cuanto al resultado, dejando a las autoridades nacionales la elección de la forma y los medios", "No es vinculante y solo expresa una opinión de las instituciones", "Tiene alcance general, es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro", "Solo es obligatorio para sus destinatarios, que deben estar designados en él"]'::jsonb,2,'Art. 288 TFUE','La segunda opción describe la directiva, la tercera la decisión y la cuarta los dictámenes.',null),
('adm-cm:8-296ba9ef0e','adm-cm',8,'¿Qué acto de la Unión obliga al Estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando a las autoridades nacionales la elección de la forma y de los medios?','["La recomendación", "La decisión", "El reglamento", "La directiva"]'::jsonb,3,'Art. 288 TFUE','Las directivas deben transponerse al derecho interno.',null),
('adm-cm:8-e990657e8d','adm-cm',8,'Según el artículo 288 del TFUE, las recomendaciones y los dictámenes:','["Son obligatorios en todos sus elementos", "Solo obligan a sus destinatarios", "Obligan solo en cuanto al resultado", "No son vinculantes"]'::jsonb,3,'Art. 288 TFUE','Son actos de las instituciones sin fuerza obligatoria.',null),
('adm-cm:8-4af4277374','adm-cm',8,'En el procedimiento legislativo ordinario, los actos se adoptan conjuntamente por:','["El Consejo Europeo y el Parlamento, a propuesta del Consejo", "La Comisión y el Consejo Europeo, oído el Parlamento", "El Parlamento Europeo y el Consejo, a propuesta de la Comisión", "El Consejo de la Unión por unanimidad, previa consulta al Parlamento"]'::jsonb,2,'Art. 294 TFUE','Antes del Tratado de Lisboa se llamaba procedimiento de codecisión.',null),
('adm-cm:8-3b58342af9','adm-cm',8,'¿Quién elige al Defensor del Pueblo Europeo?','["El Tribunal de Justicia", "El Consejo Europeo", "El Parlamento Europeo", "La Comisión Europea"]'::jsonb,2,'Art. 228 TFUE','Recibe reclamaciones sobre casos de mala administración en la acción de las instituciones, órganos y organismos de la Unión.',null),
('adm-cm:8-0923eceabd','adm-cm',8,'¿Cuántos ciudadanos de la Unión, como mínimo, deben respaldar una iniciativa ciudadana europea?','["Quinientos mil, de al menos cinco Estados miembros distintos de la Unión", "Dos millones, procedentes como mínimo de la mitad de los Estados miembros", "Cien mil, sin importar su nacionalidad ni su Estado de residencia", "Un millón, de un número significativo de Estados miembros"]'::jsonb,3,'Art. 11.4 TUE','Con ella se invita a la Comisión a presentar una propuesta legislativa.',null),
('adm-cm:8-5569a567a5','adm-cm',8,'¿Qué artículo del Tratado de la Unión Europea regula la retirada voluntaria de un Estado miembro?','["El artículo 7", "El artículo 49", "El artículo 50", "El artículo 48"]'::jsonb,2,'Art. 50 TUE','El artículo 49 regula la adhesión, el 7 la suspensión de derechos y el 48 la revisión de los Tratados.',null),
('adm-cm:8-8bd6788b0e','adm-cm',8,'¿Cuántos Estados miembros tiene actualmente la Unión Europea?','["28", "25", "26", "27"]'::jsonb,3,'Estados miembros','Son 27 desde la salida del Reino Unido en 2020.',null),
('adm-cm:8-cd514b8a8d','adm-cm',8,'¿A qué institución corresponde el control de las cuentas de la Unión?','["Al Banco Central Europeo", "A la Oficina Europea de Lucha contra el Fraude", "Al Tribunal de Justicia de la Unión", "Al Tribunal de Cuentas Europeo"]'::jsonb,3,'Art. 285 TFUE','Tiene su sede en Luxemburgo y está formado por un nacional de cada Estado miembro.',null),
('adm-cm:9-d246a16197','adm-cm',9,'Según el art. 1.1 del Código Civil, las fuentes del ordenamiento jurídico español son:','["La ley, la costumbre y los principios generales del derecho", "La ley, la jurisprudencia del Tribunal Supremo y los principios generales del derecho", "La ley, la costumbre y la jurisprudencia", "La Constitución, la ley y la costumbre"]'::jsonb,0,'Art. 1.1 CC','Las fuentes son la ley, la costumbre y los principios generales del derecho.','oct. 2026 · 1.er ejercicio | nov. 2024 · 1.er ejercicio'),
('adm-cm:9-f9280f5337','adm-cm',9,'Según el Código Civil, las disposiciones que contradigan otra de rango superior:','["Son válidas si son posteriores", "Carecerán de validez", "Prevalecen si son más específicas", "Solo son anulables a instancia de parte"]'::jsonb,1,'Art. 1.2 CC','Carecerán de validez las disposiciones que contradigan otra de rango superior.',null),
('adm-cm:9-ad161133fe','adm-cm',9,'La costumbre rige:','["En defecto de ley aplicable, aunque sea contraria a la moral, siempre que resulte probada ante el juez", "En igualdad de rango con la ley, siempre que resulte probada y no sea contraria al orden público ni a la moral", "En defecto de ley aplicable, si no es contraria a la moral ni al orden público y resulta probada", "Solo cuando la reconozca expresamente una sentencia firme del Tribunal Supremo"]'::jsonb,2,'Art. 1.3 CC','La costumbre solo rige en defecto de ley aplicable, siempre que no sea contraria a la moral o al orden público y que resulte probada.',null),
('adm-cm:9-2c2dabc7ec','adm-cm',9,'Los principios generales del derecho se aplican:','["Antes que la costumbre, por su carácter informador de todo el ordenamiento jurídico", "Solo cuando así lo prevea expresamente una ley", "En igualdad de rango con la ley y con la costumbre, según el caso concreto", "En defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento"]'::jsonb,3,'Art. 1.4 CC','Se aplican en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.',null),
('adm-cm:9-67276a6f39','adm-cm',9,'Según el Código Civil, la jurisprudencia:','["Complementa el ordenamiento con la doctrina reiterada del Tribunal Supremo", "Es fuente directa del ordenamiento, al mismo nivel que la ley", "Complementa el ordenamiento con la doctrina de cualquier juzgado o tribunal", "Complementa el ordenamiento con la doctrina reiterada del Tribunal Constitucional"]'::jsonb,0,'Art. 1.6 CC','Complementa el ordenamiento con la doctrina reiterada del Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales.',null),
('adm-cm:9-815ca613d9','adm-cm',9,'Los jueces y tribunales, ante un asunto del que conozcan:','["Pueden abstenerse de resolver si no encuentran ley aplicable", "Tienen el deber inexcusable de resolver, ateniéndose al sistema de fuentes", "Tienen el deber de resolver solo si existe ley o jurisprudencia previa", "Deben elevar consulta al Tribunal Supremo si no hay ley aplicable"]'::jsonb,1,'Art. 1.7 CC','Tienen el deber inexcusable de resolver en todo caso, ateniéndose al sistema de fuentes establecido.',null),
('adm-cm:9-e528fa043d','adm-cm',9,'Si una ley no dice otra cosa, ¿cuándo entra en vigor?','["Al día siguiente de su completa publicación en el BOE", "Al mes de su completa publicación en el Boletín Oficial del Estado", "A los veinte días de su completa publicación en el BOE", "A los quince días hábiles de su completa publicación en el Boletín Oficial del Estado"]'::jsonb,2,'Art. 2.1 CC','Las leyes entran en vigor a los veinte días de su completa publicación en el BOE, si en ellas no se dispone otra cosa.',null),
('adm-cm:9-c72e19db00','adm-cm',9,'Según el Código Civil, las leyes se derogan:','["Por el desuso", "Por la costumbre contraria", "Por sentencia de cualquier juez", "Solo por otras leyes posteriores"]'::jsonb,3,'Art. 2.2 CC','Las leyes solo se derogan por otras posteriores.',null),
('adm-cm:9-b446e92343','adm-cm',9,'Según el Código Civil, las leyes:','["No tienen efecto retroactivo si no dispusieren lo contrario", "Tienen efecto retroactivo si no dispusieren lo contrario", "No pueden tener efecto retroactivo en ningún caso, aunque lo disponga expresamente la propia ley", "Solo tienen efecto retroactivo si son favorables y así lo dicen"]'::jsonb,0,'Art. 2.3 CC','Las leyes no tienen efecto retroactivo si no dispusieren lo contrario.',null),
('adm-cm:9-9b20924022','adm-cm',9,'La ignorancia de las leyes:','["Excusa de su cumplimiento", "No excusa de su cumplimiento", "Excusa solo a los extranjeros", "Excusa durante el primer año de vigencia"]'::jsonb,1,'Art. 6.1 CC','La ignorancia de las leyes no excusa de su cumplimiento.',null),
('adm-cm:9-a420f6b08b','adm-cm',9,'Podrá prescindirse de los trámites de consulta, audiencia e información públicas en el caso de normas:','["Tributarias o sancionadoras, o cuando concurran razones graves de interés público", "Que afecten a derechos de los ciudadanos, o cuando concurran razones de urgencia", "Sancionadoras y de organización del procedimiento", "Presupuestarias u organizativas, o cuando concurran razones graves de interés público"]'::jsonb,3,'Art. 133.4 Ley 39/2015','Excepción prevista para normas presupuestarias u organizativas o razones graves de interés público.',null),
('adm-cm:9-1a6b8fcfdc','adm-cm',9,'Con carácter previo a la elaboración de un proyecto de ley o reglamento, se sustanciará una consulta pública a través del portal web sobre:','["El coste de la publicación de la norma en el BOE", "La opinión del Consejo de Estado y del órgano proponente", "Los problemas que se pretenden solucionar, la necesidad y oportunidad, los objetivos y las posibles soluciones alternativas", "El texto articulado completo del proyecto, el informe de impacto normativo, la memoria económica y el dictamen del Consejo de Estado"]'::jsonb,2,'Art. 133.1 Ley 39/2015','Son los cuatro aspectos de la consulta pública previa.',null),
('adm-cm:9-eb665216e3','adm-cm',9,'Para que entren en vigor y produzcan efectos jurídicos, las normas con rango de ley, los reglamentos y disposiciones administrativas habrán de:','["Publicarse en el diario oficial correspondiente", "Firmarse por el Rey y comunicarse a las Cortes Generales", "Comunicarse a todos los Ayuntamientos y Diputaciones afectados", "Aprobarse por referéndum"]'::jsonb,0,'Art. 131 Ley 39/2015','La publicación en el diario oficial es requisito de entrada en vigor.',null),
('adm-cm:9-5a819fe6d9','adm-cm',9,'¿Cuáles son los principios de buena regulación del art. 129 de la Ley 39/2015?','["Eficacia, jerarquía, descentralización, desconcentración y coordinación", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia", "Igualdad, mérito, capacidad y publicidad", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, publicidad y jerarquía"]'::jsonb,1,'Art. 129.1 Ley 39/2015','Son seis principios de buena regulación.',null),
('adm-cm:9-33d53e9ab4','adm-cm',9,'Los reglamentos y disposiciones administrativas NO podrán:','["Desarrollar una ley", "Publicarse en el BOE", "Regular la organización interna de la Administración ni el funcionamiento de sus órganos colegiados y unidades administrativas", "Tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, ni tributos"]'::jsonb,3,'Art. 128.2 Ley 39/2015','Tampoco vulnerar la Constitución o las leyes ni regular materias reservadas a las Cortes o a las Asambleas autonómicas.',null),
('adm-cm:9-140a90c80d','adm-cm',9,'Según la Ley 39/2015, el Gobierno de la Nación ejercerá la iniciativa legislativa en los términos de la Constitución mediante:','["La iniciativa legislativa popular", "Las proposiciones de ley del Senado", "La elaboración y aprobación de los anteproyectos de ley y la remisión de los proyectos de ley a las Cortes Generales", "La elaboración de proposiciones de ley que remite a las Cortes Generales a través del Consejo de Estado"]'::jsonb,2,'Art. 127 Ley 39/2015','También podrá aprobar reales decretos-leyes y reales decretos legislativos.',null),
('adm-cm:9-d5710db4cf','adm-cm',9,'Según el principio de eficiencia del art. 129.6, la iniciativa normativa debe:','["Aumentar los trámites para garantizar el control", "Aprobarse sin consulta pública previa ni trámite de audiencia, para reducir la duración del procedimiento normativo", "Evitar cargas administrativas innecesarias o accesorias y racionalizar la gestión de los recursos públicos", "Evitar cargas administrativas innecesarias, aunque suponga aumentar el gasto público y crear nuevos órganos"]'::jsonb,2,'Art. 129.6 Ley 39/2015','Eficiencia: evitar cargas innecesarias o accesorias.',null),
('adm-cm:9-3ea6857090','adm-cm',9,'El Plan Anual Normativo que deben aprobar las Administraciones contiene:','["Los presupuestos y las normas fiscales del año siguiente", "Las iniciativas legales o reglamentarias que vayan a ser elevadas para su aprobación en el año siguiente", "Las iniciativas reglamentarias, pero no las legales, que se aprobarán en los cuatro años siguientes", "Las normas derogadas el año anterior"]'::jsonb,1,'Art. 132.1 Ley 39/2015','Se aprueba anualmente y se publica en el Portal de la Transparencia.',null),
('adm-cm:9-e58eedd5dc','adm-cm',9,'Según el art. 128.3 de la Ley 39/2015, las disposiciones administrativas:','["Se ajustarán al orden de jerarquía y ninguna podrá vulnerar los preceptos de otra de rango superior", "Tienen todas el mismo rango, y prevalece la posterior", "Prevalecen sobre las leyes", "Se ajustarán al orden de jerarquía, salvo que la de rango inferior sea posterior en el tiempo y regule una materia más específica"]'::jsonb,0,'Art. 128.3 Ley 39/2015','Principio de jerarquía normativa.',null),
('adm-cm:9-c4cfa32d6e','adm-cm',9,'Según el art. 130.1, las Administraciones Públicas revisarán periódicamente su normativa vigente para:','["Derogarla cada cuatro años y aprobar textos refundidos", "Remitirla al Tribunal Constitucional para que verifique su adecuación a la Constitución y a los Estatutos de Autonomía", "Adaptarla a los principios de buena regulación, sin necesidad de evaluar si ha conseguido sus objetivos", "Adaptarla a los principios de buena regulación y comprobar en qué medida han conseguido sus objetivos"]'::jsonb,3,'Art. 130.1 Ley 39/2015','El resultado de la evaluación se plasma en un informe que se hará público.',null),
('adm-cm:9-3257431fd3','adm-cm',9,'Según la Ley 50/1997, del Gobierno, ¿qué reglamentos tienen mayor rango?','["Los aprobados por orden ministerial conjunta de varios Ministros", "Los aprobados por real decreto", "Los aprobados por resolución de un Secretario de Estado", "Los aprobados por instrucción o circular de un Subsecretario"]'::jsonb,1,'Art. 24.2 Ley 50/1997','Primero van las disposiciones aprobadas por real decreto del Presidente del Gobierno o acordado en el Consejo de Ministros, y después las aprobadas por orden ministerial.',null),
('adm-cm:9-803a3e5d41','adm-cm',9,'Según el Código Civil, las normas jurídicas contenidas en los tratados internacionales serán de aplicación directa en España:','["Cuando hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en el BOE", "Desde su ratificación por el Rey, aunque la publicación en el BOE sea solo de un extracto", "Desde su firma por el Gobierno, aunque todavía no se hayan publicado en ningún diario oficial", "A los veinte días de su publicación en el Diario Oficial de la Unión Europea, en todo caso"]'::jsonb,0,'Art. 1.5 CC','El art. 1.5 CC exige que hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en el BOE.',null),
('adm-cm:9-46b5145778','adm-cm',9,'Según el art. 3.1 del Código Civil, las normas se interpretarán atendiendo fundamentalmente a:','["Su sentido literal", "Sus antecedentes históricos", "Su espíritu y finalidad", "La realidad social del momento en que se aprobaron"]'::jsonb,2,'Art. 3.1 CC','Se atiende al sentido de las palabras, el contexto, los antecedentes y la realidad social, pero fundamentalmente al espíritu y finalidad.',null),
('adm-cm:9-29e03bfba9','adm-cm',9,'Según el Código Civil, las resoluciones de los tribunales solo podrán descansar de manera exclusiva en la equidad:','["Cuando no exista costumbre aplicable al caso", "Cuando las partes lo soliciten de común acuerdo", "Cuando la ley expresamente lo permita", "En los asuntos de cuantía inferior a 6.000 euros"]'::jsonb,2,'Art. 3.2 CC','La equidad se pondera en la aplicación de las normas, pero las resoluciones solo pueden basarse exclusivamente en ella cuando la ley lo permita.',null),
('adm-cm:9-cf21c3cf42','adm-cm',9,'Procede la aplicación analógica de las normas cuando estas no contemplen un supuesto específico, pero regulen otro semejante:','["Siempre que se trate de normas penales o sancionadoras", "Aunque no exista identidad de razón entre ambos", "Solo si así lo acuerda la jurisprudencia del Tribunal Supremo", "Entre los que se aprecie identidad de razón"]'::jsonb,3,'Art. 4.1 CC','El art. 4.1 CC exige que entre el supuesto regulado y el no regulado se aprecie identidad de razón.',null),
('adm-cm:9-cefa1de2de','adm-cm',9,'Según el Código Civil, ¿qué leyes NO se aplicarán a supuestos ni en momentos distintos de los comprendidos expresamente en ellas?','["Las orgánicas, las ordinarias y los decretos legislativos", "Las penales, las excepcionales y las de ámbito temporal", "Las de bases, las de armonización y los decretos-leyes", "Las autonómicas, las forales y las de régimen local"]'::jsonb,1,'Art. 4.2 CC','Las leyes penales, las excepcionales y las de ámbito temporal no admiten aplicación analógica.',null),
('adm-cm:9-50dc426aa0','adm-cm',9,'Las disposiciones del Código Civil se aplicarán en las materias regidas por otras leyes:','["Como supletorias", "Solo en defecto de costumbre", "Con carácter preferente", "Solo si lo prevé la otra ley"]'::jsonb,0,'Art. 4.3 CC','El art. 4.3 CC establece la aplicación supletoria del Código Civil en las materias regidas por otras leyes.',null),
('adm-cm:9-012e6dc664','adm-cm',9,'En el cómputo civil de los plazos, según el Código Civil:','["Se excluyen los días inhábiles del mes de agosto", "No se excluyen los días inhábiles", "Se excluyen los sábados y domingos", "Se excluyen solo los días festivos nacionales"]'::jsonb,1,'Art. 5.2 CC','A diferencia del cómputo administrativo, en el cómputo civil no se excluyen los días inhábiles.',null),
('adm-cm:9-263aa6b504','adm-cm',9,'La exclusión voluntaria de la ley aplicable y la renuncia a los derechos en ella reconocidos solo serán válidas:','["Cuando las autorice previamente el juez del domicilio del renunciante", "Cuando consten en documento público otorgado ante notario, en todo caso", "Cuando se refieran a derechos patrimoniales de cuantía inferior a 3.000 euros", "Cuando no contraríen el interés o el orden público ni perjudiquen a terceros"]'::jsonb,3,'Art. 6.2 CC','El art. 6.2 CC solo admite la exclusión o renuncia si no contraría el interés o el orden público ni perjudica a terceros.',null),
('adm-cm:9-bb2c76dd6a','adm-cm',9,'Según el Código Civil, los actos contrarios a las normas imperativas y a las prohibitivas son:','["Anulables a instancia de parte durante el plazo de cuatro años desde su celebración", "Nulos de pleno derecho en todo caso, sin que la norma pueda prever otro efecto", "Nulos de pleno derecho, salvo que en ellas se establezca un efecto distinto para el caso de contravención", "Válidos, aunque quien los realiza debe indemnizar los daños y perjuicios causados"]'::jsonb,2,'Art. 6.3 CC','Son nulos de pleno derecho, salvo que la norma establezca un efecto distinto para el caso de contravención.',null),
('adm-cm:9-a692fa8fed','adm-cm',9,'Los actos realizados al amparo de una norma que persigan un resultado prohibido por el ordenamiento se consideran ejecutados en fraude de ley y:','["No impedirán la debida aplicación de la norma que se hubiere tratado de eludir", "Serán válidos si la norma de cobertura tiene rango de ley", "Darán lugar siempre a responsabilidad penal de sus autores", "Producirán efectos hasta que un juez declare su nulidad"]'::jsonb,0,'Art. 6.4 CC','El fraude de ley no impide la debida aplicación de la norma que se hubiere tratado de eludir.',null),
('adm-cm:9-dd7f5bffb6','adm-cm',9,'Según el art. 7 del Código Civil, la ley no ampara:','["La aplicación supletoria del propio Código Civil", "La renuncia a derechos que no perjudique a terceros", "El ejercicio de los derechos conforme a la buena fe", "El abuso del derecho ni su ejercicio antisocial"]'::jsonb,3,'Art. 7.2 CC','El art. 7.2 CC: la ley no ampara el abuso del derecho o su ejercicio antisocial; el art. 7.1 exige ejercitar los derechos conforme a la buena fe.',null),
('adm-cm:9-c3f1b0c85f','adm-cm',9,'La consulta pública previa a la elaboración de un proyecto normativo, a través del portal web de la Administración competente, es un instrumento de:','["Participación ciudadana en la elaboración de normas", "Rendición de cuentas de los altos cargos ante el Congreso", "Fiscalización económica de la Administración", "Control parlamentario del Gobierno"]'::jsonb,0,'Art. 133.1 Ley 39/2015','Busca la opinión de los sujetos y organizaciones más representativas potencialmente afectados por la futura norma.',null),
('adm-cm:10-404cc06afb','adm-cm',10,'Según la Ley 40/2015, ¿qué carácter tiene la competencia de los órganos administrativos?','["Delegable en todo caso", "Renunciable con autorización del superior", "Transferible a otras Administraciones por convenio", "Irrenunciable"]'::jsonb,3,'Art. 8.1 Ley 40/2015','La competencia es irrenunciable y se ejerce por los órganos que la tengan atribuida como propia, salvo delegación o avocación.',null),
('adm-cm:10-6e6bf57c91','adm-cm',10,'¿Cuál de estas técnicas sí altera la titularidad de la competencia?','["La desconcentración", "La delegación de competencias", "La delegación de firma", "La encomienda de gestión"]'::jsonb,0,'Art. 8 Ley 40/2015','La delegación, la encomienda, la delegación de firma y la suplencia no alteran la titularidad; la desconcentración transfiere titularidad y ejercicio a órganos dependientes.',null),
('adm-cm:10-e9711fb132','adm-cm',10,'Si una norma atribuye una competencia a una Administración sin especificar el órgano, ¿a quién corresponde instruir y resolver?','["Al órgano superior de esa Administración por razón de la materia, en todo caso y sin excepción", "A los órganos inferiores competentes por razón de la materia y del territorio", "Al órgano que designe en cada caso el titular del departamento ministerial correspondiente", "Al órgano que primero conozca del asunto"]'::jsonb,1,'Art. 8.3 Ley 40/2015','Corresponde a los órganos inferiores competentes por materia y territorio; si hay varios, a su superior jerárquico común.',null),
('adm-cm:10-f5bc47695b','adm-cm',10,'¿Puede delegarse la competencia para adoptar disposiciones de carácter general?','["Sí, en órganos dependientes jerárquicamente", "Sí, si lo autoriza el superior jerárquico", "Solo en el ámbito de la Administración local", "No, en ningún caso"]'::jsonb,3,'Art. 9.2 b) Ley 40/2015','No pueden delegarse las competencias relativas a la adopción de disposiciones de carácter general.',null),
('adm-cm:10-90130f901d','adm-cm',10,'¿Puede delegarse la resolución de recursos en el mismo órgano que dictó el acto recurrido?','["Sí, si el recurso es de reposición", "Sí, con publicación en el boletín oficial", "No, está expresamente prohibido", "Solo si lo prevé el reglamento orgánico"]'::jsonb,2,'Art. 9.2 c) Ley 40/2015','No pueden delegarse las competencias relativas a la resolución de recursos en los órganos que hayan dictado los actos recurridos.',null),
('adm-cm:10-2ad4696214','adm-cm',10,'¿Dónde deben publicarse las delegaciones de competencias de un órgano de la Comunidad Autónoma de Canarias?','["No necesitan publicación", "En el Boletín Oficial del Estado", "En el Boletín Oficial de Canarias", "En el tablón de anuncios del órgano"]'::jsonb,2,'Art. 9.3 Ley 40/2015','Las delegaciones y su revocación se publican en el boletín de la Administración a que pertenezca el órgano delegante: para Canarias, el BOC.',null),
('adm-cm:10-e1b18af876','adm-cm',10,'¿A qué órgano se consideran dictadas las resoluciones adoptadas por delegación?','["A ambos de forma solidaria", "Al órgano delegado", "Al superior jerárquico común", "Al órgano delegante"]'::jsonb,3,'Art. 9.4 Ley 40/2015','Las resoluciones adoptadas por delegación indicarán esta circunstancia y se considerarán dictadas por el órgano delegante.',null),
('adm-cm:10-b0ed6d05e0','adm-cm',10,'¿Pueden delegarse las competencias que se ejercen por delegación?','["No, salvo autorización expresa de una ley", "No, en ningún caso, ni siquiera por ley", "Sí, con consentimiento del delegante", "Sí, siempre que se publique"]'::jsonb,0,'Art. 9.5 Ley 40/2015','Salvo autorización expresa de una ley, no podrán delegarse las competencias que se ejerzan por delegación.',null),
('adm-cm:10-1abfbe59ca','adm-cm',10,'¿Cuándo puede revocarse una delegación de competencias?','["Previa audiencia del órgano delegado", "En cualquier momento, por el órgano que la confirió", "Solo al finalizar el plazo fijado", "Solo por el superior jerárquico del delegante"]'::jsonb,1,'Art. 9.6 Ley 40/2015','La delegación es revocable en cualquier momento por el órgano que la haya conferido.',null),
('adm-cm:10-2b95cadff2','adm-cm',10,'¿Cabe recurso contra el acuerdo de avocación?','["Sí, recurso de alzada ante el superior jerárquico del órgano que haya acordado la avocación", "Solo recurso contencioso-administrativo directo", "No, aunque puede impugnarse en el recurso contra la resolución del procedimiento", "Sí, recurso potestativo de reposición"]'::jsonb,2,'Art. 10.2 Ley 40/2015','Contra el acuerdo de avocación no cabe recurso, aunque puede impugnarse en el que se interponga contra la resolución final.',null),
('adm-cm:10-0282267023','adm-cm',10,'¿Qué requisito formal debe cumplir la avocación?','["Publicación en el boletín oficial correspondiente antes de que surta efecto la avocación", "Acuerdo motivado notificado a los interesados antes o a la vez que la resolución final", "Informe previo del órgano delegado", "Autorización del órgano colegiado superior"]'::jsonb,1,'Art. 10.2 Ley 40/2015','La avocación se realiza mediante acuerdo motivado notificado a los interesados con anterioridad o simultáneamente a la resolución final.',null),
('adm-cm:10-9061bc4410','adm-cm',10,'En una delegación en órganos no dependientes jerárquicamente, ¿quién puede avocar un asunto?','["Cualquier órgano superior", "El órgano delegado, devolviéndolo", "El superior jerárquico del órgano delegado", "Únicamente el órgano delegante"]'::jsonb,3,'Art. 10.1 Ley 40/2015','En la delegación en órganos no dependientes jerárquicamente, solo puede avocar el órgano delegante.',null),
('adm-cm:10-700f1e48d7','adm-cm',10,'¿Qué puede ser objeto de encomienda de gestión?','["Actividades de carácter material o técnico", "La adopción de disposiciones generales", "La resolución de procedimientos", "Prestaciones propias de los contratos del sector público"]'::jsonb,0,'Art. 11.1 Ley 40/2015','Se encomienda la realización de actividades de carácter material o técnico; no puede tener por objeto prestaciones propias de los contratos.',null),
('adm-cm:10-463eaa93a5','adm-cm',10,'En una encomienda de gestión, ¿qué condición tiene el órgano encomendado respecto de los datos personales?','["Corresponsable del tratamiento", "Encargado del tratamiento", "Responsable del tratamiento", "Delegado de protección de datos"]'::jsonb,1,'Art. 11.2 Ley 40/2015','El órgano o entidad encomendado tiene la condición de encargado del tratamiento de los datos personales.',null),
('adm-cm:10-b95ed8c591','adm-cm',10,'¿Cómo se formaliza una encomienda de gestión entre órganos de distintas Administraciones?','["Por resolución del órgano encomendado", "Por acuerdo verbal de los titulares", "Mediante convenio publicado en el boletín oficial correspondiente", "Mediante contrato administrativo de servicios adjudicado sin publicidad"]'::jsonb,2,'Art. 11.3 b) Ley 40/2015','Entre distintas Administraciones se formaliza mediante convenio, que debe publicarse en el boletín correspondiente.',null),
('adm-cm:10-63205ad571','adm-cm',10,'¿Necesita publicación la delegación de firma para su validez?','["Sí, en el boletín oficial correspondiente", "Solo si afecta a resoluciones sancionadoras", "Sí, en el tablón de edictos", "No"]'::jsonb,3,'Art. 12.2 Ley 40/2015','La delegación de firma no altera la competencia del delegante y para su validez no es necesaria su publicación.',null),
('adm-cm:10-81415c3291','adm-cm',10,'¿En quién puede delegarse la firma de resoluciones y actos?','["En los titulares de órganos o unidades que dependan del delegante", "En cualquier funcionario de la Administración", "En órganos de otras Administraciones", "Solo en el superior jerárquico"]'::jsonb,0,'Art. 12.1 Ley 40/2015','La firma puede delegarse en los titulares de los órganos o unidades administrativas que dependan del delegante.',null),
('adm-cm:10-0fec3d19d7','adm-cm',10,'Si no se designa suplente para un órgano vacante, ¿quién ejerce su competencia?','["Nadie hasta el nombramiento del nuevo titular", "Quien designe el órgano inmediato superior", "El órgano delegado más reciente", "El funcionario de mayor antigüedad del órgano"]'::jsonb,1,'Art. 13.1 Ley 40/2015','Si no se designa suplente, la competencia se ejerce por quien designe el órgano administrativo inmediato superior.',null),
('adm-cm:10-9788a287f4','adm-cm',10,'¿Entre qué órganos pueden suscitarse conflictos de atribuciones según la Ley 40/2015?','["Entre órganos de una misma Administración no relacionados jerárquicamente", "Entre órganos de distintas Administraciones", "Entre un órgano y su superior jerárquico, cuando discrepen sobre la competencia para resolver", "Entre cualquier órgano y otro de la misma o distinta Administración, una vez finalizado el procedimiento"]'::jsonb,0,'Art. 14.3 Ley 40/2015','Los conflictos de atribuciones solo pueden suscitarse entre órganos de una misma Administración no relacionados jerárquicamente y en procedimientos no finalizados.',null),
('adm-cm:10-a0fe791c15','adm-cm',10,'¿Qué debe hacer el órgano que se estime incompetente para resolver un asunto?','["Solicitar informe al Consejo Consultivo", "Archivar el expediente y notificar a los interesados que deben presentar nueva solicitud ante otro órgano", "Remitir directamente las actuaciones al competente y notificarlo a los interesados", "Devolver la solicitud al interesado para que la presente ante el órgano que considere competente"]'::jsonb,2,'Art. 14.1 Ley 40/2015','Remitirá directamente las actuaciones al órgano que considere competente, notificándolo a los interesados.',null),
('adm-cm:10-44d19492f6','adm-cm',10,'Según la Ley 40/2015, ¿qué unidades administrativas tienen la consideración de órganos administrativos?','["Las creadas por ley, con independencia de sus funciones y de sus efectos", "Las que dirijan un funcionario de carrera del subgrupo A1 con nivel 30", "Las que tengan atribuidas funciones con efectos jurídicos frente a terceros o cuya actuación tenga carácter preceptivo", "Todas las que figuren en la relación de puestos de trabajo del departamento, con independencia de sus funciones y efectos"]'::jsonb,2,'Art. 5.1 Ley 40/2015','El art. 5.1 considera órganos administrativos las unidades con funciones que tengan efectos jurídicos frente a terceros o cuya actuación tenga carácter preceptivo.',null),
('adm-cm:10-04f7967292','adm-cm',10,'¿Cuál de estos requisitos exige como mínimo la Ley 40/2015 para crear un órgano administrativo?','["Su aprobación por ley del Parlamento", "La previa supresión de otro órgano de igual rango", "La dotación de los créditos necesarios para su puesta en marcha y funcionamiento", "El informe favorable del Consejo de Estado"]'::jsonb,2,'Art. 5.3 Ley 40/2015','Se exige determinar su integración y dependencia jerárquica, delimitar sus funciones y competencias y dotar los créditos necesarios.',null),
('adm-cm:10-01096f3f5a','adm-cm',10,'¿Pueden crearse órganos que dupliquen otros ya existentes según la Ley 40/2015?','["No, en ningún caso, aunque se suprima o restrinja debidamente la competencia del órgano existente", "Sí, si actúan sobre distinto colectivo de la misma población", "Solo si al mismo tiempo se suprime o restringe debidamente la competencia de estos", "Sí, siempre que lo autorice el titular del departamento"]'::jsonb,2,'Art. 5.4 Ley 40/2015','El art. 5.4 prohíbe crear órganos que dupliquen otros si al mismo tiempo no se suprime o restringe debidamente la competencia de estos.',null),
('adm-cm:10-a366e2d1a5','adm-cm',10,'¿Quién puede ser secretario de un órgano colegiado según la Ley 40/2015?','["Solo un funcionario de carrera del subgrupo A1 que no sea miembro del órgano ni tenga derecho a voto", "El miembro de menor antigüedad del órgano", "Un letrado de los servicios jurídicos, en todo caso", "Un miembro del propio órgano o una persona al servicio de la Administración correspondiente"]'::jsonb,3,'Art. 16.1 Ley 40/2015','El art. 16.1 permite que el secretario sea miembro del órgano o una persona al servicio de la Administración.',null),
('adm-cm:10-83bd0ba71c','adm-cm',10,'¿Qué asistencia exige la Ley 40/2015 para la válida constitución de un órgano colegiado?','["El presidente y un tercio de sus miembros", "La mayoría absoluta de sus miembros, sin necesidad de la asistencia del secretario ni de su suplente", "Presidente y secretario, o quienes les suplan, y la mitad, al menos, de sus miembros", "Dos tercios de sus miembros, entre ellos el presidente"]'::jsonb,2,'Art. 17.2 Ley 40/2015','Se requiere la asistencia, presencial o a distancia, del presidente y del secretario o de quienes les suplan, y la de la mitad, al menos, de sus miembros.',null),
('adm-cm:10-65bb325914','adm-cm',10,'¿Puede un órgano colegiado reunirse sin convocatoria previa según la Ley 40/2015?','["Solo en segunda convocatoria", "No, la convocatoria es siempre obligatoria", "Sí, si lo decide el presidente por razones de urgencia, con la mayoría de los miembros presentes", "Sí, si están reunidos el secretario y todos los miembros y así lo deciden todos"]'::jsonb,3,'Art. 17.2 Ley 40/2015','Cuando estén reunidos el secretario y todos los miembros, pueden constituirse sin convocatoria previa si así lo deciden todos.',null),
('adm-cm:10-64697238e7','adm-cm',10,'¿Puede deliberarse en un órgano colegiado sobre un asunto que no figure en el orden del día?','["Sí, si lo solicita al menos un tercio de los miembros presentes en la sesión", "Sí, si lo propone el presidente al inicio de la sesión", "Solo si asisten todos los miembros y se declara la urgencia por mayoría", "No, en ningún caso"]'::jsonb,2,'Art. 17.4 Ley 40/2015','No puede tratarse ningún asunto fuera del orden del día salvo que asistan todos los miembros y se declare la urgencia por el voto favorable de la mayoría.',null),
('adm-cm:10-b3e3e6c078','adm-cm',10,'Según la Ley 40/2015, ¿cómo se adoptan los acuerdos de los órganos colegiados?','["Por unanimidad de los presentes", "Por mayoría de dos tercios de los presentes", "Por mayoría absoluta de los miembros", "Por mayoría de votos"]'::jsonb,3,'Art. 17.5 Ley 40/2015','El art. 17.5 dispone que los acuerdos serán adoptados por mayoría de votos.',null),
('adm-cm:10-a7046cff84','adm-cm',10,'Cuando un órgano colegiado se reúne a distancia, ¿dónde se entienden adoptados los acuerdos?','["En la capital de la comunidad autónoma", "Donde se encuentre físicamente la mayoría de los miembros que votaron a favor del acuerdo", "Donde se encuentre el secretario que levanta el acta", "En el lugar donde tenga la sede el órgano y, en su defecto, donde esté la presidencia"]'::jsonb,3,'Art. 17.5 Ley 40/2015','Se entienden adoptados donde tenga la sede el órgano colegiado y, en su defecto, donde esté ubicada la presidencia.',null),
('adm-cm:10-b7334d5e6e','adm-cm',10,'¿Qué efecto tiene que un miembro de un órgano colegiado vote en contra o se abstenga?','["Debe formular voto particular en el plazo de diez días", "Su voto no se computa a efectos de quórum", "Queda exento de la responsabilidad que pueda derivarse de los acuerdos", "Pierde el derecho a pedir certificación del acuerdo"]'::jsonb,2,'Art. 17.6 Ley 40/2015','Quienes voten en contra o se abstengan quedan exentos de la responsabilidad que pueda derivarse de los acuerdos.',null),
('adm-cm:10-d8b7600f26','adm-cm',10,'¿Cuándo puede aprobarse el acta de una sesión de un órgano colegiado según la Ley 40/2015?','["En el plazo de un mes desde la sesión", "Solo en la sesión inmediata siguiente", "Cuando la firmen todos los asistentes, sin plazo", "En la misma reunión o en la inmediata siguiente"]'::jsonb,3,'Art. 18.2 Ley 40/2015','El acta puede aprobarse en la misma reunión o en la inmediata siguiente.',null),
('adm-cm:10-d3b2d131b9','adm-cm',10,'En los órganos colegiados de la Administración General del Estado, ¿quién dirime con su voto los empates?','["El miembro de mayor antigüedad", "El vicepresidente", "El presidente", "El secretario"]'::jsonb,2,'Art. 19.2 Ley 40/2015','Corresponde al presidente dirimir con su voto los empates, salvo en los órganos del art. 15.2, donde depende de sus normas.',null),
('adm-cm:10-495bbcb2ff','adm-cm',10,'¿Con qué antelación mínima deben recibir la convocatoria los miembros de un órgano colegiado de la AGE?','["Tres días hábiles", "Cinco días", "Dos días", "Veinticuatro horas"]'::jsonb,2,'Art. 19.3 Ley 40/2015','Los miembros deben recibir la convocatoria con una antelación mínima de dos días.',null),
('adm-cm:10-320b7d05be','adm-cm',10,'¿Pueden abstenerse en las votaciones los miembros natos de un órgano colegiado que son autoridades o personal público?','["Sí, si lo autoriza el presidente", "Solo en las votaciones sobre asuntos urgentes", "Sí, siempre que lo motiven en el acta", "No, quienes lo son por razón del cargo no pueden abstenerse"]'::jsonb,3,'Art. 19.3 Ley 40/2015','No podrán abstenerse quienes, por su cualidad de autoridades o personal al servicio de las Administraciones, sean miembros natos en virtud del cargo.',null),
('adm-cm:10-08120f52f7','adm-cm',10,'¿En qué plazo pueden formular voto particular por escrito los miembros que discrepen del acuerdo mayoritario?','["Dos días", "Un mes", "Diez días", "Cinco días"]'::jsonb,0,'Art. 19.5 Ley 40/2015','Pueden formular voto particular por escrito en el plazo de dos días, que se incorporará al texto aprobado.',null),
('adm-cm:10-19704855d2','adm-cm',10,'Según la Ley 40/2015, ¿cuántas personas, como mínimo, integran un órgano colegiado de la AGE?','["Cinco", "Siete", "Dos", "Tres"]'::jsonb,3,'Art. 20.1 Ley 40/2015','Son órganos colegiados los que se creen formalmente y estén integrados por tres o más personas.',null),
('adm-cm:10-5b971f8050','adm-cm',10,'¿Qué es un órgano colegiado interministerial según la Ley 40/2015?','["El que tiene miembros procedentes de diferentes ministerios", "El que integra representantes del Estado y de las comunidades autónomas", "El que preside un ministro y asesora a varios departamentos", "El que depende directamente del Consejo de Ministros"]'::jsonb,0,'Art. 21.1 Ley 40/2015','Son interministeriales si sus miembros proceden de diferentes ministerios y ministeriales si proceden de uno solo.',null),
('adm-cm:10-0591b380d6','adm-cm',10,'¿Cuál de estos es un motivo de abstención según la Ley 40/2015?','["Pertenecer al mismo partido político que un interesado", "Haber coincidido con un interesado en el mismo centro de estudios", "Tener parentesco de consanguinidad dentro del cuarto grado con un interesado", "Tener parentesco de afinidad dentro del cuarto grado con cualquiera de los interesados"]'::jsonb,2,'Art. 23.2 Ley 40/2015','Es motivo el parentesco de consanguinidad dentro del cuarto grado o de afinidad dentro del segundo con cualquiera de los interesados.',null),
('adm-cm:10-688a5aadf0','adm-cm',10,'Según la Ley 40/2015, ¿durante cuánto tiempo haber prestado servicios profesionales a un interesado es motivo de abstención?','["En los cinco últimos años", "En los cuatro últimos años", "En el último año", "En los dos últimos años"]'::jsonb,3,'Art. 23.2 Ley 40/2015','Es motivo de abstención haber prestado en los dos últimos años servicios profesionales de cualquier tipo a la persona interesada.',null),
('adm-cm:10-e50c4d91e1','adm-cm',10,'¿Qué efecto tiene sobre los actos la intervención de quien debió abstenerse?','["Son anulables en todo caso", "Son nulos de pleno derecho en todo caso", "No implica necesariamente y en todo caso su invalidez", "Son inexistentes"]'::jsonb,2,'Art. 23.4 Ley 40/2015','La actuación de quien incurre en motivo de abstención no implica, necesariamente y en todo caso, la invalidez de los actos.',null),
('adm-cm:10-9208194a02','adm-cm',10,'Si el recusado niega la causa de recusación, ¿en qué plazo resuelve el superior?','["Tres días", "Un día", "Diez días", "Cinco días"]'::jsonb,0,'Art. 24.4 Ley 40/2015','El superior resolverá en el plazo de tres días, previos los informes y comprobaciones que considere oportunos.',null),
('adm-cm:10-292a968964','adm-cm',10,'¿Cabe recurso contra la resolución que decide sobre una recusación?','["Sí, recurso potestativo de reposición", "Sí, recurso de alzada ante el superior jerárquico del órgano que resolvió la recusación", "No, aunque puede alegarse al recurrir el acto que ponga fin al procedimiento", "Solo recurso contencioso-administrativo directo"]'::jsonb,2,'Art. 24.5 Ley 40/2015','No cabe recurso, sin perjuicio de alegar la recusación al recurrir el acto que ponga fin al procedimiento.',null),
('adm-cm:11-490f7a6c1b','adm-cm',11,'¿Cuál es el plazo máximo para resolver que puede fijar una norma reguladora de un procedimiento?','["3 meses, salvo que una norma con rango de ley establezca uno mayor", "6 meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE", "1 año, salvo que una norma con rango de ley o el Derecho de la Unión Europea establezcan uno menor", "6 meses, sin excepción, cualquiera que sea el rango de la norma reguladora"]'::jsonb,1,'Art. 21.2 Ley 39/2015','El plazo no puede exceder de seis meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE.',null),
('adm-cm:11-42a696cc2f','adm-cm',11,'Si la norma reguladora de un procedimiento no fija plazo máximo para resolver, este será de:','["1 mes", "6 meses", "3 meses", "10 días"]'::jsonb,2,'Art. 21.3 Ley 39/2015','Cuando las normas no fijen el plazo máximo, será de tres meses.',null),
('adm-cm:11-11e34514df','adm-cm',11,'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo es, como regla general:','["Desestimatorio, salvo las excepciones legales", "Causa de caducidad del procedimiento", "Desestimatorio, sin excepción", "Estimatorio, salvo las excepciones legales"]'::jsonb,3,'Art. 24.1 Ley 39/2015','El vencimiento del plazo sin resolución expresa legitima al interesado para entender estimada su solicitud, salvo las excepciones previstas.',null),
('adm-cm:11-e6d15ea44b','adm-cm',11,'En los procedimientos iniciados de oficio en los que la Administración ejerce potestades sancionadoras o de intervención, el vencimiento del plazo sin resolución produce:','["La caducidad", "La estimación por silencio", "La desestimación por silencio", "La prórroga automática del plazo"]'::jsonb,0,'Art. 25.1 b) Ley 39/2015','En esos procedimientos se produce la caducidad.',null),
('adm-cm:11-9cb032bbc9','adm-cm',11,'Cuando los plazos se señalan por días, se entiende que son:','["Naturales, salvo que una ley disponga otro cómputo", "Hábiles, excluyéndose los sábados, los domingos y los festivos", "Hábiles, excluyéndose solo los domingos y los declarados festivos", "Naturales, salvo en el mes de agosto, en que son hábiles"]'::jsonb,1,'Art. 30.2 Ley 39/2015','Los plazos por días son hábiles y se excluyen sábados, domingos y festivos.',null),
('adm-cm:11-8607f1a7e2','adm-cm',11,'Los plazos señalados por horas no pueden tener una duración superior a:','["12 horas", "48 horas", "24 horas", "72 horas"]'::jsonb,2,'Art. 30.1 Ley 39/2015','Son hábiles todas las horas de un día hábil y no pueden superar 24 horas; si no, se expresan en días.',null),
('adm-cm:11-4e2b6783c7','adm-cm',11,'Los plazos fijados en meses o años se computan:','["Por días hábiles, a partir del día siguiente a la notificación o publicación", "Por días naturales, desde el mismo día de la notificación o publicación", "Desde el mismo día de la notificación o publicación del acto", "A partir del día siguiente a la notificación o publicación del acto"]'::jsonb,3,'Art. 30.4 Ley 39/2015','Se computan a partir del día siguiente a la notificación o publicación, de fecha a fecha.',null),
('adm-cm:11-1e76ccc8dc','adm-cm',11,'La ampliación de los plazos establecidos no puede exceder de:','["La mitad de los mismos", "El doble de los mismos", "Un mes en todo caso", "Tres meses"]'::jsonb,0,'Art. 32.1 Ley 39/2015','La ampliación no puede exceder de la mitad del plazo.',null),
('adm-cm:11-33a60e74ab','adm-cm',11,'Cuando en una solicitud figuren varios interesados, las actuaciones se efectuarán:','["Con el que elija la Administración en cada trámite, notificando a los demás", "Con todos a la vez, de forma obligatoria y en igualdad de condiciones, salvo renuncia expresa de alguno de ellos por escrito", "Con el de mayor edad, salvo que todos hayan señalado expresamente a otro, y en su defecto con todos los interesados a la vez", "Con el representante o interesado que expresamente hayan señalado y, en su defecto, con el que figure en primer término"]'::jsonb,3,'Art. 7 Ley 39/2015','En defecto de designación, con el que figure en primer término.',null),
('adm-cm:11-7854bae8a0','adm-cm',11,'La estimación por silencio administrativo tiene a todos los efectos la consideración de:','["Acto administrativo finalizador del procedimiento", "Acto de trámite cualificado, recurrible en alzada", "Propuesta de resolución vinculante para el órgano competente", "Mera ficción sin efectos hasta que se dicte resolución expresa"]'::jsonb,0,'Art. 24.2 Ley 39/2015','La desestimación por silencio solo permite interponer el recurso que proceda.',null),
('adm-cm:11-55f8e5127a','adm-cm',11,'Los titulares de las unidades administrativas que tengan a su cargo la resolución o despacho de los asuntos:','["Serán responsables directos de su tramitación y adoptarán las medidas para remover los obstáculos que retrasen el ejercicio de los derechos de los interesados", "No tienen responsabilidad directa sobre la tramitación, que corresponde en exclusiva al titular del órgano superior jerárquico del que dependan", "Responden solo ante los tribunales penales", "Solo son responsables si lo solicita el interesado"]'::jsonb,0,'Art. 20.1 Ley 39/2015','Son responsables directos de la tramitación.',null),
('adm-cm:11-17008a6366','adm-cm',11,'La Administración instructora deberá traducir al castellano:','["Los documentos que deban surtir efecto fuera del territorio de la Comunidad y los dirigidos a interesados que lo soliciten expresamente", "Todos los documentos redactados en lengua cooficial, sin excepción", "Solo los documentos dirigidos a interesados que residan fuera de la Comunidad Autónoma", "Los documentos que deban surtir efecto en la Comunidad, y los dirigidos a interesados que no conozcan la lengua cooficial aunque no lo pidan"]'::jsonb,0,'Art. 15.3 Ley 39/2015','Se traducen los que deban surtir efecto fuera de la Comunidad y los que pidan los interesados.',null),
('adm-cm:11-70d7fa5e55','adm-cm',11,'Tienen la consideración de Administraciones Públicas según el art. 2.3:','["La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local y los organismos públicos y entidades de derecho público del art. 2.2 a)", "La AGE, las Administraciones de las CCAA y las Entidades Locales, pero no los organismos públicos vinculados o dependientes", "La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local, las universidades privadas, los colegios profesionales y todas las empresas con capital público", "Los colegios profesionales en todo caso"]'::jsonb,0,'Art. 2.3 Ley 39/2015','Son AAPP la AGE, las CCAA, las Entidades Locales y los organismos y entidades de derecho público vinculados o dependientes.',null),
('adm-cm:11-6d26686900','adm-cm',11,'Según su art. 1.1, la Ley 39/2015 regula, entre otros aspectos:','["El régimen jurídico de los funcionarios y del personal laboral al servicio de las Administraciones", "La jurisdicción contencioso-administrativa y sus procedimientos, así como el régimen de los recursos judiciales contra los actos de las Administraciones", "Los requisitos de validez y eficacia de los actos administrativos y el procedimiento administrativo común a todas las Administraciones", "La organización interna de la AGE y de su sector público institucional, y el régimen de los órganos colegiados de todas las Administraciones"]'::jsonb,2,'Art. 1.1 Ley 39/2015','Incluye el procedimiento sancionador, el de responsabilidad patrimonial y los principios de iniciativa legislativa y potestad reglamentaria.',null),
('adm-cm:11-efa4130595','adm-cm',11,'La comparecencia de las personas ante las oficinas públicas solo será obligatoria cuando:','["El interesado tenga más de 65 años", "Lo establezca una circular o instrucción interna del órgano", "Lo decida motivadamente el instructor del procedimiento", "Así esté previsto en una norma con rango de ley"]'::jsonb,3,'Art. 19.1 Ley 39/2015','Solo es obligatoria si una norma con rango de ley lo prevé.',null),
('adm-cm:11-7444af7916','adm-cm',11,'¿Quién determina los órganos que tienen atribuidas las competencias de expedición de copias auténticas?','["Cada Administración Pública", "El Consejo de Estado", "El Ministerio de Justicia para todas", "Los notarios"]'::jsonb,0,'Art. 27.1 Ley 39/2015','Cada Administración determina los órganos competentes para expedir copias auténticas.',null),
('adm-cm:11-9527d5d0fb','adm-cm',11,'El registro electrónico de cada Administración permitirá la presentación de documentos:','["Solo en horario de oficina de cada órgano", "Solo de lunes a viernes, a cualquier hora", "Solo en días hábiles, durante las veinticuatro horas", "Todos los días del año durante las veinticuatro horas"]'::jsonb,3,'Art. 31.2 Ley 39/2015','El registro electrónico funciona 24 horas los 365 días.',null),
('adm-cm:11-ccf7e778fa','adm-cm',11,'El silencio será desestimatorio, entre otros, en los procedimientos relativos a:','["Licencias de obra menor", "Inscripción en registros públicos", "Las solicitudes de subvenciones de concurrencia competitiva, sin excepción", "El ejercicio del derecho de petición del art. 29 de la Constitución"]'::jsonb,3,'Art. 24.1 Ley 39/2015','También en los de dominio o servicio público, medio ambiente, responsabilidad patrimonial, impugnación de actos y revisión de oficio a solicitud.',null),
('adm-cm:11-d49bf8ed88','adm-cm',11,'La representación podrá acreditarse mediante:','["Únicamente escritura notarial de apoderamiento, que deberá presentarse en papel en el registro del órgano competente en cada uno de los procedimientos en que se actúe", "Únicamente comparecencia personal ante el órgano competente", "Cualquier medio válido en Derecho que deje constancia fidedigna, comparecencia personal o electrónica, o inscripción en el registro de apoderamientos", "Cualquier medio, incluida una llamada telefónica o un correo electrónico sin firma, siempre que el funcionario que lo recibe deje constancia escrita en el expediente"]'::jsonb,2,'Art. 5.4 Ley 39/2015','Se admite cualquier medio válido en Derecho que deje constancia fidedigna.',null),
('adm-cm:11-e07e5598c0','adm-cm',11,'Los interesados podrán firmar a través de cualquier medio que permita acreditar:','["La fecha del documento y su número de registro", "Su identidad, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, y la integridad e inalterabilidad del documento"]'::jsonb,3,'Art. 10.1 Ley 39/2015','La firma debe acreditar autenticidad de la voluntad y la integridad del documento.',null),
('adm-cm:11-c56cb25171','adm-cm',11,'Si el interesado actúa por medio de representante:','["Se requiere poder notarial en todo caso", "Las actuaciones se entienden siempre con el interesado, y solo se comunican al representante a título informativo", "Solo puede actuar como representante un abogado colegiado", "Las actuaciones se entenderán con el representante, salvo manifestación expresa en contrario del interesado"]'::jsonb,3,'Art. 5.1 Ley 39/2015','Se entienden con el representante salvo manifestación expresa en contrario.',null),
('adm-cm:11-e1f6832fe5','adm-cm',11,'En los procedimientos iniciados de oficio, si el procedimiento se paraliza por causa imputable al interesado:','["Se produce la caducidad inmediata del procedimiento", "Se interrumpirá el cómputo del plazo para resolver y notificar la resolución", "Se suspenderá el cómputo del plazo, pero solo si así lo acuerda el órgano por resolución motivada notificada al interesado", "Se archiva sin más trámite y se declara la caducidad del procedimiento de forma automática"]'::jsonb,1,'Art. 25.2 Ley 39/2015','La paralización imputable al interesado interrumpe el cómputo del plazo.',null),
('adm-cm:11-258ff4963a','adm-cm',11,'Cuando el último día del plazo sea inhábil:','["Se entenderá vencido el último día hábil anterior", "Se entenderá prorrogado al primer día hábil siguiente", "Se entenderá prorrogado al tercer día hábil siguiente", "El plazo vence ese mismo día"]'::jsonb,1,'Art. 30.5 Ley 39/2015','Se prorroga al primer día hábil siguiente.',null),
('adm-cm:11-814359477b','adm-cm',11,'Cuando la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente:','["No sucede, debiendo iniciar un nuevo procedimiento en el plazo de diez días", "Solo sucede si todavía no se ha abierto la fase de instrucción", "Sucederá en tal condición cualquiera que sea el estado del procedimiento", "Sucederá en tal condición solo si el procedimiento no ha concluido la fase de audiencia a los interesados"]'::jsonb,2,'Art. 4.3 Ley 39/2015','Sucede en la condición de interesado en cualquier estado del procedimiento.',null),
('adm-cm:11-1dffb9d51e','adm-cm',11,'Las asociaciones y organizaciones representativas de intereses económicos y sociales son titulares de:','["Intereses individuales de cada uno de sus asociados", "Intereses legítimos colectivos en los términos que la ley reconozca", "Derechos fundamentales propios en todo procedimiento administrativo que afecte a sus asociados o al sector", "Ningún interés"]'::jsonb,1,'Art. 4.2 Ley 39/2015','Son titulares de intereses legítimos colectivos.',null),
('adm-cm:11-524eed8239','adm-cm',11,'Los documentos presentados de manera presencial ante las Administraciones deberán ser:','["Archivados en papel sin digitalizar en la oficina que los recibió", "Digitalizados por la oficina de registro, conservándose los originales en el expediente", "Enviados por correo postal al órgano competente para su digitalización en destino, junto con el resto del expediente", "Digitalizados por la oficina de asistencia en materia de registros, devolviéndose los originales al interesado"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Se digitalizan y se devuelven los originales, salvo que la norma determine la custodia obligatoria.','abr. 2026 · 1.er ejercicio'),
('adm-cm:11-d97142a0cc','adm-cm',11,'La AGE, las CCAA y las Entidades Locales dispondrán de:','["Un registro electrónico general de apoderamientos", "Un registro de representantes en papel", "Un registro notarial propio", "Un registro único estatal compartido obligatoriamente"]'::jsonb,0,'Art. 6.1 Ley 39/2015','Cada una dispone de un registro electrónico general de apoderamientos.',null),
('adm-cm:11-a0f9ff7a55','adm-cm',11,'En los casos de estimación por silencio, la resolución expresa posterior:','["Podrá ser desestimatoria si así lo aconseja el interés público", "Deberá someterse a dictamen previo del Consejo de Estado", "Solo podrá dictarse de ser confirmatoria del mismo", "Podrá ser confirmatoria o desestimatoria, según el resultado de la instrucción y las alegaciones de los interesados"]'::jsonb,2,'Art. 24.3 a) Ley 39/2015','La resolución expresa posterior a la estimación por silencio solo puede confirmarla.',null),
('adm-cm:11-8a48889ffb','adm-cm',11,'Son interesados en el procedimiento, según el art. 4.1 a):','["Cualquier ciudadano, sin necesidad de acreditar interés alguno", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado", "Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos"]'::jsonb,3,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('adm-cm:11-ebeef3fd90','adm-cm',11,'Contra el acuerdo que resuelva sobre la ampliación del plazo máximo de resolución:','["Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "No cabrá recurso alguno", "Cabe recurso de alzada"]'::jsonb,2,'Art. 23.2 Ley 39/2015','Ese acuerdo no es recurrible.',null),
('adm-cm:11-39cf04c463','adm-cm',11,'La ampliación excepcional del plazo máximo de resolución no podrá ser superior:','["A la mitad del plazo establecido para la tramitación del procedimiento", "Al plazo establecido para la tramitación del procedimiento", "A diez días hábiles", "A un año, cualquiera que sea el plazo inicial"]'::jsonb,1,'Art. 23.1 Ley 39/2015','Contra el acuerdo de ampliación no cabe recurso.',null),
('adm-cm:11-28e6b5f950','adm-cm',11,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Se tramitará en la lengua cooficial", "Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,3,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('adm-cm:11-3dbceb1190','adm-cm',11,'La ampliación de un plazo y su solicitud deberán producirse:','["Solo el último día del plazo de que se trate", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa", "En cualquier momento"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('adm-cm:11-e789ebf885','adm-cm',11,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir todos los plazos a cinco días, incluidos los de recursos", "Suprimir los recursos administrativos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos", "Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos"]'::jsonb,3,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('adm-cm:11-e6fb454cf4','adm-cm',11,'Solicitado el certificado acreditativo del silencio, este deberá emitirse en el plazo máximo de:','["Tres meses", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 24.4 Ley 39/2015','El certificado del silencio se emite en un máximo de quince días.',null),
('adm-cm:11-a23c8604f1','adm-cm',11,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo expira el último día del mes", "El plazo se amplía 10 días", "El plazo expira el primer día del mes siguiente", "El plazo se considera vencido el día 28"]'::jsonb,0,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('adm-cm:11-eedec97538','adm-cm',11,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se comunicará a dichas personas la tramitación del procedimiento", "No se les comunica nada hasta la resolución, que se les notifica", "Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento"]'::jsonb,0,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('adm-cm:11-1a4ce89ef3','adm-cm',11,'La Administración está obligada a dictar resolución expresa y a notificarla:','["Solo en los procedimientos sancionadores", "En todos los procedimientos, cualquiera que sea su forma de iniciación", "Solo en los procedimientos iniciados a solicitud del interesado", "En todos los procedimientos, salvo en los iniciados de oficio, en que basta la caducidad"]'::jsonb,1,'Art. 21.1 Ley 39/2015','La obligación de resolver alcanza a todos los procedimientos, salvo las excepciones legales.',null),
('adm-cm:11-6a8a48a637','adm-cm',11,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se aplica el calendario del órgano", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso", "Se considerará hábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('adm-cm:11-d5e82f6028','adm-cm',11,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo", "Quince días hábiles", "Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran"]'::jsonb,3,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('adm-cm:11-fdce79aff2','adm-cm',11,'Los interesados que conozcan datos que permitan identificar a otros interesados que no hayan comparecido en el procedimiento:','["Tienen prohibido comunicarlos por razones de protección de datos", "Pueden comunicarlos voluntariamente, sin estar obligados a ello", "Tienen el deber de proporcionárselos a la Administración actuante", "Solo deben comunicarlos ante un juez"]'::jsonb,2,'Art. 18.2 Ley 39/2015','Existe el deber de proporcionar esos datos a la Administración.',null),
('adm-cm:11-2fd8dcaeca','adm-cm',11,'Las Administraciones están obligadas a verificar la identidad de los interesados mediante la comprobación de:','["Su huella dactilar o cualquier otro dato biométrico que conste en el DNI o en el documento identificativo equivalente", "Su nombre y apellidos o denominación o razón social, que consten en el DNI o documento identificativo equivalente", "Su dirección de correo electrónico", "Su número de teléfono móvil"]'::jsonb,1,'Art. 9.1 Ley 39/2015','Se verifica con el nombre y apellidos o razón social del DNI o documento equivalente.',null),
('adm-cm:11-f6e1b9738e','adm-cm',11,'El incumplimiento de la obligación de dictar resolución expresa en plazo dará lugar a:','["La nulidad de pleno derecho del procedimiento", "Una sanción al interesado", "La estimación automática de la solicitud en todo caso, sin ninguna otra consecuencia para el órgano o para el personal responsable", "La exigencia de responsabilidad disciplinaria, sin perjuicio de la que hubiere lugar de acuerdo con la normativa aplicable"]'::jsonb,3,'Art. 21.6 Ley 39/2015','El personal y los titulares de órganos son responsables directos y responden disciplinariamente.',null),
('adm-cm:11-8b76d2a98d','adm-cm',11,'Deberá acreditarse la representación para:','["Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos", "Pedir información general sobre los procedimientos", "Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general"]'::jsonb,0,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('adm-cm:11-b171e10abb','adm-cm',11,'Las copias auténticas de documentos realizadas por los órganos competentes:','["Solo tienen validez dentro del mismo procedimiento en el que se expidieron", "Caducan a los seis meses de su expedición", "Tienen menos valor probatorio que el original, salvo que se compulsen ante notario", "Tendrán la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Las copias auténticas tienen la misma validez y eficacia que los originales.',null),
('adm-cm:11-e58deef229','adm-cm',11,'¿Cuál de los siguientes es un sistema de identificación electrónica previsto en el art. 9.2?','["Un mensaje desde un número de teléfono previamente comunicado", "El envío de una fotocopia escaneada del DNI por correo electrónico, junto con la solicitud firmada a mano", "Los sistemas basados en certificados electrónicos cualificados de firma electrónica", "Una llamada telefónica grabada"]'::jsonb,2,'Art. 9.2 Ley 39/2015','También los certificados cualificados de sello electrónico y otros sistemas que las AAPP consideren válidos.','oct. 2026 · 1.er ejercicio'),
('adm-cm:11-13127ddd7f','adm-cm',11,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder especial para actuar ante los juzgados y tribunales penales en nombre del poderdante, en cualquier procedimiento", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('adm-cm:11-389efbcc77','adm-cm',11,'Se entiende por documentos públicos administrativos:','["Los documentos privados presentados en un registro público", "Los documentos autorizados por notario, exclusivamente", "Los válidamente emitidos por los órganos de las Administraciones Públicas", "Cualquier documento firmado electrónicamente por un ciudadano y presentado en la sede electrónica de una Administración"]'::jsonb,2,'Art. 26.1 Ley 39/2015','Se emiten por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',null),
('adm-cm:11-cf0fc0b91a','adm-cm',11,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Las Comunidades Autónomas cuando afecten a varias provincias", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,2,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('adm-cm:11-0cd125f15b','adm-cm',11,'Las Administraciones no exigirán a los interesados la presentación de documentos originales:','["Salvo en los procedimientos iniciados de oficio", "Salvo que, con carácter excepcional, la normativa reguladora aplicable establezca lo contrario", "En ningún caso, sin excepciones", "Salvo que el funcionario que tramite el procedimiento lo considere oportuno para comprobar su autenticidad"]'::jsonb,1,'Art. 28.3 Ley 39/2015','La regla es no exigir originales; solo excepcionalmente por normativa.',null),
('adm-cm:11-418e0c6d34','adm-cm',11,'Cuando se soliciten informes preceptivos a un órgano, el plazo máximo para resolver puede suspenderse por el tiempo que medie entre la petición y la recepción del informe, sin que pueda exceder de:','["Tres meses", "Seis meses", "Un mes", "Diez días"]'::jsonb,0,'Art. 22.1 d) Ley 39/2015','Esta suspensión no puede exceder en ningún caso de tres meses.',null),
('adm-cm:11-6740c00d43','adm-cm',11,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Se personan en el procedimiento en tanto no haya recaído resolución definitiva", "Lo solicitan antes del inicio del procedimiento", "Se personan en cualquier momento, incluso después de la resolución definitiva", "Lo autoriza el instructor"]'::jsonb,0,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('adm-cm:11-6a151cbdeb','adm-cm',11,'En caso de desestimación por silencio, la resolución expresa posterior:','["No puede dictarse", "Se adoptará por la Administración sin vinculación alguna al sentido del silencio", "Debe ser necesariamente desestimatoria, en coherencia con el sentido del silencio producido", "Solo puede ser confirmatoria"]'::jsonb,1,'Art. 24.3 b) Ley 39/2015','En la estimación por silencio, en cambio, la resolución posterior solo puede ser confirmatoria.',null),
('adm-cm:11-aa11600fc4','adm-cm',11,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los españoles mayores de edad", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('adm-cm:11-7718cb75da','adm-cm',11,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender desestimadas sus pretensiones por silencio administrativo", "Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Exigir una indemnización automática"]'::jsonb,0,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('adm-cm:11-9e58acbb11','adm-cm',11,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Siempre, cualquiera que sea su número de miembros", "Cuando tengan más de 20 miembros", "Cuando la ley así lo declare expresamente", "Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen"]'::jsonb,2,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('adm-cm:11-7e48c4e301','adm-cm',11,'En el asiento de registro debe constar, entre otros datos:','["La firma del superior jerárquico del órgano destinatario y el sello de la oficina que lo recibe", "Un número, epígrafe expresivo de su naturaleza, fecha y hora de presentación, identificación del interesado y referencia al contenido", "Un número, fecha de presentación, identificación del interesado y del órgano destinatario, pero no la hora de presentación ni ninguna referencia a su contenido", "El sentido previsible de la resolución"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Se emite recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada.','oct. 2026 · 1.er ejercicio'),
('adm-cm:11-66059ae862','adm-cm',11,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos", "Ser atendidos en la lengua que elijan, cualquiera que sea la Administración"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('adm-cm:11-4db426406c','adm-cm',11,'Los términos y plazos establecidos en las leyes obligan:','["Solo a la Administración, que debe resolver en el plazo máximo", "Solo a los interesados, que pierden su derecho si no los cumplen", "A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,2,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:11-7408b19aa2','adm-cm',11,'No se tendrán por presentados en el registro:','["Aquellos documentos e información cuyo régimen especial establezca otra forma de presentación", "Los presentados por un representante cuya representación no esté inscrita", "Los presentados en día inhábil, que se tendrán por no presentados hasta el siguiente hábil", "Los presentados en las oficinas de Correos sin sello de fechas"]'::jsonb,0,'Art. 16.8 Ley 39/2015','No se tienen por presentados los que tengan un régimen especial con otra forma de presentación.',null),
('adm-cm:11-4ed8d60358','adm-cm',11,'Los plazos expresados en días se contarán:','["Desde que el interesado tenga conocimiento efectivo del acto", "Desde el mismo día de la notificación o publicación del acto", "Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,3,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('adm-cm:11-6700b16249','adm-cm',11,'En los procedimientos tramitados por la AGE, la lengua será:','["Siempre la lengua cooficial del territorio donde tenga su sede el órgano", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,2,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('adm-cm:11-b8e65ba5c7','adm-cm',11,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Un año, renovable por periodos iguales", "Cinco años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('adm-cm:11-ee9122fbdc','adm-cm',11,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso contencioso-administrativo inmediato", "Cabe recurso de alzada", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('adm-cm:11-a0156a3a75','adm-cm',11,'Las Administraciones deben publicar y mantener actualizadas en el portal web:','["Las nóminas de todos sus empleados", "Las resoluciones judiciales que les afecten", "Las relaciones de procedimientos de su competencia, con indicación de los plazos máximos de duración y de los efectos del silencio administrativo", "Las relaciones de procedimientos de su competencia, con los datos de los interesados y el estado de tramitación de cada expediente"]'::jsonb,2,'Art. 21.4 Ley 39/2015','Deben publicar los procedimientos, sus plazos máximos y los efectos del silencio.',null),
('adm-cm:11-1df6567243','adm-cm',11,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Mediante circular o instrucción interna", "Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,3,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('adm-cm:11-b7bb9ce1b4','adm-cm',11,'Para los actos y gestiones de mero trámite, la representación:','["No está permitida", "Se presumirá", "Debe acreditarse ante notario", "Debe inscribirse en el registro de apoderamientos"]'::jsonb,1,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('adm-cm:11-6c1c36d0f9','adm-cm',11,'Según el artículo 13 de la Ley 39/2015, es un derecho de las personas en sus relaciones con las Administraciones Públicas:','["Obtener siempre una resolución favorable cuando cumplan los requisitos formales", "Exigir que se les atienda fuera del horario de atención al público", "Elegir al funcionario que tramitará su procedimiento", "Ser tratadas con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos"]'::jsonb,3,'Art. 13 e) Ley 39/2015','El artículo 13 recoge también, entre otros, el derecho a ser asistidas en el uso de medios electrónicos.',null),
('adm-cm:12-f71521d35b','adm-cm',12,'Los actos administrativos producen efectos:','["Desde su publicación en el boletín oficial, salvo que en ellos se disponga otra cosa", "Desde que son firmes en vía administrativa, salvo que se disponga otra cosa", "Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa", "Desde su notificación, sin que puedan disponer otra cosa"]'::jsonb,2,'Art. 39.1 Ley 39/2015','Se presumen válidos y producen efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.','abr. 2026 · 1.er ejercicio'),
('adm-cm:12-7a2996aaae','adm-cm',12,'¿En qué plazo debe cursarse la notificación de un acto administrativo?','["5 días desde que el acto se dictó", "15 días hábiles desde que el acto se dictó o se firmó", "1 mes desde que el acto se dictó", "10 días desde que el acto se dictó"]'::jsonb,3,'Art. 40.2 Ley 39/2015','La notificación debe cursarse dentro de los diez días siguientes a la fecha en que el acto se dictó.',null),
('adm-cm:12-3d2f360b56','adm-cm',12,'Una notificación electrónica se entiende rechazada cuando pasan sin que se acceda a su contenido:','["10 días naturales desde su puesta a disposición", "10 días hábiles desde su puesta a disposición en la sede electrónica", "15 días naturales desde su puesta a disposición", "5 días hábiles desde su puesta a disposición"]'::jsonb,0,'Art. 43.2 Ley 39/2015','Se entiende rechazada cuando han pasado diez días naturales desde su puesta a disposición sin acceder a su contenido.','abr. 2026 · 1.er ejercicio'),
('adm-cm:12-90bd760ddd','adm-cm',12,'Cuando la notificación ha resultado infructuosa, se hace por medio de un anuncio en:','["El tablón de la sede del órgano", "El Boletín Oficial del Estado", "El boletín oficial de la provincia", "Un periódico de tirada nacional"]'::jsonb,1,'Art. 44 Ley 39/2015','La notificación se hace por medio de un anuncio publicado en el BOE.',null),
('adm-cm:12-bdc24d1629','adm-cm',12,'¿Cuál de estos actos es nulo de pleno derecho?','["El que tiene un defecto de forma que no causa indefensión al interesado ni impide que el acto alcance su fin", "El dictado fuera del plazo establecido, cuando el término no sea esencial", "El dictado por un órgano manifiestamente incompetente por razón de la materia o del territorio", "El que incurre en desviación de poder o en cualquier otra infracción del ordenamiento jurídico aplicable"]'::jsonb,2,'Art. 47.1 b) Ley 39/2015','La incompetencia manifiesta por razón de la materia o del territorio es causa de nulidad de pleno derecho. Las otras opciones son, como mucho, causas de anulabilidad.','abr. 2026 · 1.er ejercicio'),
('adm-cm:12-e4ec133b31','adm-cm',12,'Un acto dictado prescindiendo total y absolutamente del procedimiento legalmente establecido es:','["Anulable", "Válido si se convalida", "Una irregularidad no invalidante", "Nulo de pleno derecho"]'::jsonb,3,'Art. 47.1 e) Ley 39/2015','Es una de las causas de nulidad de pleno derecho.',null),
('adm-cm:12-ea51344225','adm-cm',12,'Los actos que incurren en desviación de poder son:','["Anulables", "Nulos de pleno derecho", "Válidos", "Inexistentes"]'::jsonb,0,'Art. 48.1 Ley 39/2015','Son anulables los actos que incurren en cualquier infracción del ordenamiento, incluso la desviación de poder.',null),
('adm-cm:12-2d97db4297','adm-cm',12,'El defecto de forma determina la anulabilidad del acto:','["Siempre, aunque el acto alcance su fin, reúna los requisitos formales indispensables y no cause indefensión", "Solo cuando el acto carece de los requisitos formales indispensables o da lugar a indefensión", "Nunca, porque el defecto de forma solo genera irregularidades no invalidantes", "Solo cuando el defecto de forma afecta a la motivación del acto, aunque no se haya producido indefensión"]'::jsonb,1,'Art. 48.2 Ley 39/2015','Solo cuando el acto carece de los requisitos formales indispensables para alcanzar su fin o da lugar a indefensión.',null),
('adm-cm:12-e3acded0fd','adm-cm',12,'La realización de actuaciones fuera del tiempo establecido implica la anulabilidad del acto:','["Siempre, cualquiera que sea la naturaleza del término o plazo", "Nunca, ya que la actuación tardía es una mera irregularidad no invalidante", "Solo cuando lo imponga la naturaleza del término o plazo", "Solo si el retraso supera el doble del plazo establecido para la actuación"]'::jsonb,2,'Art. 48.3 Ley 39/2015','Solo implica anulabilidad cuando así lo imponga la naturaleza del término o plazo.',null),
('adm-cm:12-9fd1b3a190','adm-cm',12,'¿Qué actos puede convalidar la Administración subsanando los vicios de que adolezcan?','["Los nulos de pleno derecho", "Los inexistentes", "Cualquier acto", "Los anulables"]'::jsonb,3,'Art. 52.1 Ley 39/2015','La Administración puede convalidar los actos anulables, subsanando los vicios de que adolezcan.',null),
('adm-cm:12-e80036fafa','adm-cm',12,'La revisión de oficio de los actos nulos de pleno derecho requiere:','["Dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma", "Dictamen previo, preceptivo pero no vinculante, del Consejo de Estado u órgano consultivo equivalente autonómico", "Sentencia judicial previa que declare la nulidad, a instancia de la Administración", "Informe favorable del servicio jurídico y audiencia previa de todos los interesados"]'::jsonb,0,'Art. 106.1 Ley 39/2015','Requiere dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere.',null),
('adm-cm:12-6b54000b62','adm-cm',12,'La declaración de lesividad de un acto favorable anulable no puede adoptarse una vez transcurridos desde que se dictó:','["2 años", "4 años", "6 meses", "1 año"]'::jsonb,1,'Art. 107.2 Ley 39/2015','No puede adoptarse una vez transcurridos cuatro años desde que se dictó el acto.',null),
('adm-cm:12-c4ed0c47fd','adm-cm',12,'¿Qué actos pueden revocar las Administraciones mientras no haya transcurrido el plazo de prescripción?','["Los actos favorables", "Los actos firmes de cualquier tipo", "Los actos de gravamen o desfavorables", "Las disposiciones generales"]'::jsonb,2,'Art. 109.1 Ley 39/2015','Pueden revocar sus actos de gravamen o desfavorables mientras no haya transcurrido el plazo de prescripción.',null),
('adm-cm:12-10a1776e5b','adm-cm',12,'Los errores materiales, de hecho o aritméticos de los actos pueden rectificarse:','["En el plazo de un mes desde la notificación, de oficio o a instancia de los interesados", "Solo a instancia de los interesados, mediante el correspondiente recurso de reposición", "Solo antes de la notificación del acto, de oficio por el mismo órgano que lo dictó", "En cualquier momento, de oficio o a instancia de los interesados"]'::jsonb,3,'Art. 109.2 Ley 39/2015','Pueden rectificarse en cualquier momento, de oficio o a instancia de los interesados.',null),
('adm-cm:12-1cdeb8b5bd','adm-cm',12,'¿Pueden revisarse de oficio las disposiciones administrativas nulas del art. 47.2?','["Sí, en cualquier momento y sin necesidad de dictamen del órgano consultivo", "No, la revisión de oficio solo alcanza a los actos, no a las disposiciones", "Sí, previo dictamen favorable del Consejo de Estado u órgano consultivo autonómico equivalente", "Sí, previo dictamen no vinculante del Consejo de Estado u órgano consultivo equivalente, y a instancia del interesado"]'::jsonb,2,'Art. 106.2 Ley 39/2015','Las Administraciones pueden declarar de oficio la nulidad de disposiciones del art. 47.2 previo dictamen favorable.',null),
('adm-cm:12-9c32a71019','adm-cm',12,'Son nulas de pleno derecho las disposiciones administrativas que:','["Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales", "Establezcan la retroactividad de disposiciones favorables o ampliatorias de derechos individuales", "Tengan carácter organizativo y no se hayan sometido previamente al trámite de información pública ni a consulta de los interesados afectados", "Se aprueben por el Consejo de Ministros"]'::jsonb,0,'Art. 47.2 Ley 39/2015','También las que vulneren la Constitución, las leyes o disposiciones de rango superior o regulen materias reservadas a la ley.',null),
('adm-cm:12-0493008fd5','adm-cm',12,'En la AGE, son competentes para la revisión de oficio de sus propios actos y de los dictados por los Ministros:','["El Consejo de Estado", "Los Subsecretarios", "El Presidente del Gobierno en solitario", "El Consejo de Ministros"]'::jsonb,3,'Art. 111 a) Ley 39/2015','El Consejo de Ministros revisa sus propios actos y disposiciones y los de los Ministros.',null),
('adm-cm:12-e271f1f516','adm-cm',12,'Una notificación que contenga el texto íntegro del acto pero omita otro requisito surte efecto:','["A los seis meses de su práctica, si el interesado no ha reclamado", "Desde que el interesado realice actuaciones que supongan el conocimiento del contenido o interponga el recurso procedente", "Inmediatamente desde su envío, aunque el interesado no haya realizado ninguna actuación ni interpuesto recurso", "Nunca"]'::jsonb,1,'Art. 40.3 Ley 39/2015','Surte efecto desde que el interesado realiza actuaciones que suponen conocer su contenido e alcance o interpone recurso.',null),
('adm-cm:12-00cca45d97','adm-cm',12,'Los actos administrativos serán objeto de publicación cuando:','["Lo pida cualquier ciudadano interesado en conocerlos", "Lo establezcan las normas reguladoras de cada procedimiento o lo aconsejen razones de interés público", "Sean desfavorables para el interesado, aunque la norma reguladora no lo prevea", "Lo establezcan las normas reguladoras de cada procedimiento, pero nunca por razones de interés público apreciadas por el órgano"]'::jsonb,1,'Art. 45.1 Ley 39/2015','Se publican cuando lo establezcan sus normas reguladoras o lo aconsejen razones de interés público apreciadas por el órgano competente.',null),
('adm-cm:12-d125337989','adm-cm',12,'Si el procedimiento de revisión de oficio se inició de oficio y transcurren seis meses sin resolución, se produce:','["La estimación por silencio", "La caducidad del mismo", "La prórroga automática del plazo", "La nulidad automática del acto"]'::jsonb,1,'Art. 106.5 Ley 39/2015','Iniciado de oficio: caducidad. Iniciado a solicitud: se podrá entender desestimada.',null),
('adm-cm:12-99c9a4f598','adm-cm',12,'Las notificaciones se practicarán preferentemente:','["Mediante anuncio en el BOE, salvo que el interesado señale un domicilio", "En papel en el domicilio del interesado, salvo que este solicite la notificación electrónica", "Por medios electrónicos o en papel, a elección del órgano que dicte el acto", "Por medios electrónicos y, en todo caso, cuando el interesado esté obligado a recibirlas por esta vía"]'::jsonb,3,'Art. 41.1 Ley 39/2015','Se practicarán preferentemente por medios electrónicos.',null),
('adm-cm:12-095e248e1d','adm-cm',12,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La declaración automática de lesividad", "La nulidad del acto", "La estimación del interesado por silencio", "La caducidad del procedimiento"]'::jsonb,3,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('adm-cm:12-860c3da083','adm-cm',12,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación", "Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "Hayan transcurrido seis meses desde que se dictó el acto"]'::jsonb,1,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.','oct. 2026 · 1.er ejercicio'),
('adm-cm:12-f174bdc1d0','adm-cm',12,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal", "Con remitir un aviso por SMS o correo electrónico", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal"]'::jsonb,2,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('adm-cm:12-9eaf9fe87b','adm-cm',12,'Según el art. 35.1 i), deben motivarse también:','["Las comunicaciones internas entre órganos", "Los actos reglados, sin excepción, aunque no limiten derechos ni intereses", "Los actos que se dicten en el ejercicio de potestades discrecionales", "Los actos de trámite que no decidan el fondo ni produzcan indefensión"]'::jsonb,2,'Art. 35.1 i) Ley 39/2015','Se motivan los actos dictados en ejercicio de potestades discrecionales y los que deban serlo por disposición legal.',null),
('adm-cm:12-07ff20492a','adm-cm',12,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno", "El Alcalde o, en su defecto, el Secretario municipal, previo informe preceptivo del Interventor"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('adm-cm:12-85410a573c','adm-cm',12,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento", "Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Solo la resolución final y los actos de trámite posteriores a la infracción, aunque su contenido hubiera variado"]'::jsonb,0,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('adm-cm:12-ea5a8a022f','adm-cm',12,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados", "Afecte a un único interesado identificado", "Tenga por destinatario a una pluralidad indeterminada de personas", "Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido"]'::jsonb,2,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('adm-cm:12-a2ea5716c1','adm-cm',12,'Si nadie se hace cargo de la notificación en papel en el domicilio, se repetirá:','["Dos veces en la misma semana, en horas distintas", "No se repite, y se publica directamente en el BOE", "Una sola vez y en una hora distinta dentro de los tres días siguientes", "Una sola vez y en la misma hora dentro de los cinco días siguientes"]'::jsonb,2,'Art. 42.2 Ley 39/2015','Se repite por una sola vez y en hora distinta dentro de los tres días siguientes.',null),
('adm-cm:12-de6b14bcb2','adm-cm',12,'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho:','["Solo las disposiciones de carácter general y los actos que pongan fin a la vía administrativa", "Los actos que limiten derechos subjetivos o intereses legítimos", "Solo los actos favorables al interesado", "Todos los actos de trámite, aunque no limiten derechos ni decidan el fondo"]'::jsonb,1,'Art. 35.1 a) Ley 39/2015','El art. 35.1 a) exige motivar los actos que limiten derechos subjetivos o intereses legítimos.',null),
('adm-cm:12-a6bad7a3b8','adm-cm',12,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo tras su confirmación judicial", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('adm-cm:12-697ba457d2','adm-cm',12,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Dejar sin efecto las sentencias dictadas sobre el acto"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('adm-cm:12-ac11af11da','adm-cm',12,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Sean sanciones más favorables que las anteriores", "Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Lo solicite cualquier tercero afectado y el acto restrinja derechos individuales del destinatario", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,3,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('adm-cm:12-40622a6215','adm-cm',12,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "No implica la de los sucesivos en el procedimiento que sean independientes del primero", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "Solo afecta a actos favorables"]'::jsonb,1,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('adm-cm:12-b927c9e865','adm-cm',12,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia", "El Defensor del Pueblo"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('adm-cm:12-c140151527','adm-cm',12,'Las Administraciones podrán practicar notificaciones por medios no electrónicos cuando:','["Para asegurar la eficacia de la actuación sea necesario practicarla por entrega directa de un empleado público", "Sea fin de semana", "La notificación sea favorable al interesado", "El interesado esté obligado a relacionarse electrónicamente con la Administración y no haya accedido a la notificación"]'::jsonb,0,'Art. 41.2 b) Ley 39/2015','También cuando el interesado comparezca espontáneamente en una oficina de asistencia y solicite la comunicación personal.',null),
('adm-cm:12-7d7636dbf4','adm-cm',12,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se enviará al Defensor del Pueblo", "Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo"]'::jsonb,3,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('adm-cm:12-860c10d63d','adm-cm',12,'Las notificaciones por medios electrónicos se entienden practicadas:','["Al día siguiente de su emisión", "Cuando el interesado contesta", "Cuando se envía al interesado el aviso de puesta a disposición por correo electrónico o SMS", "En el momento en que se produzca el acceso a su contenido"]'::jsonb,3,'Art. 43.2 Ley 39/2015','Se entienden practicadas en el momento del acceso a su contenido.',null),
('adm-cm:12-a15335bd6c','adm-cm',12,'La eficacia de un acto quedará demorada cuando:','["Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata", "El interesado lo solicite verbalmente", "Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación"]'::jsonb,2,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('adm-cm:12-97ccb434a4','adm-cm',12,'Como regla general, los actos administrativos se producirán:','["En papel con firma manuscrita del titular del órgano", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,3,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('adm-cm:12-86a59aea34','adm-cm',12,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que procedan de un órgano de jerarquía superior al que dictó la disposición", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null),
('adm-cm:12-fd6407ed08','adm-cm',12,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por cualquier órgano de la misma Administración", "Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho"]'::jsonb,0,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('adm-cm:12-7d449a6d51','adm-cm',12,'La obligación de notificar en plazo se entiende cumplida, en las notificaciones electrónicas, con:','["La puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única", "La publicación de un anuncio en el BOE", "El envío del aviso al correo electrónico del interesado, aunque no se ponga a disposición la notificación", "El acceso efectivo del interesado"]'::jsonb,0,'Art. 43.3 Ley 39/2015','Se entiende cumplida con la puesta a disposición en la sede electrónica o la dirección electrónica habilitada única.',null),
('adm-cm:12-075d61439f','adm-cm',12,'¿A quién debe notificar el órgano que dicte una resolución?','["A los interesados cuyos derechos e intereses sean afectados por ella", "A todos los vecinos del municipio afectado", "Solo al solicitante, aunque haya otros interesados afectados", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,0,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('adm-cm:12-0d16c4d64b','adm-cm',12,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Sea un acto favorable al interesado", "La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,2,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('adm-cm:12-fe8059eb5e','adm-cm',12,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando no haya terceros afectados por la adquisición", "Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,3,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('adm-cm:12-4bd7cbe1de','adm-cm',12,'Es nulo de pleno derecho el acto que:','["Lesione los derechos y libertades susceptibles de amparo constitucional", "Se dicte fuera del plazo establecido", "Tenga un defecto de forma que no produzca indefensión", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,0,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('adm-cm:12-21672372dd','adm-cm',12,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Sean formuladas por personas jurídicas", "Se presenten en papel", "Carezcan manifiestamente de fundamento"]'::jsonb,3,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.','nov. 2024 · 1.er ejercicio'),
('adm-cm:12-a2cb96c945','adm-cm',12,'Si en la notificación en papel en el domicilio el interesado no está presente, podrá hacerse cargo de ella:','["Solo un familiar mayor de 18 años", "Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad", "Cualquier persona mayor de 16 años que se encuentre en el domicilio, sin necesidad de hacer constar su identidad", "Únicamente el interesado"]'::jsonb,1,'Art. 42.2 Ley 39/2015','Puede recogerla cualquier persona mayor de catorce años que esté en el domicilio y haga constar su identidad.',null),
('adm-cm:12-f0c9238f57','adm-cm',12,'Las facultades de revisión no podrán ejercerse cuando:','["Lo solicite el propio interesado", "El acto sea nulo de pleno derecho", "Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,2,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('adm-cm:12-c04b29521f','adm-cm',12,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Revocación", "Conservación de actos y trámites", "Convalidación", "Conversión de actos viciados"]'::jsonb,3,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.','oct. 2026 · 1.er ejercicio'),
('adm-cm:12-b590f90f5b','adm-cm',12,'Es nulo de pleno derecho el acto:','["Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Cuyo defecto de forma no produzca indefensión", "Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Dictado un día inhábil"]'::jsonb,2,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('adm-cm:12-a8c18761eb','adm-cm',12,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Anularlos directamente en vía administrativa"]'::jsonb,2,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('adm-cm:12-1fbdaf4518','adm-cm',12,'Son nulos de pleno derecho los actos:','["Dictados por órgano jerárquicamente incompetente", "Que tengan un contenido imposible", "Que no indiquen los recursos", "Que tengan un error material"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('adm-cm:12-efb0e3caef','adm-cm',12,'Si la Administración no envía el aviso al dispositivo o correo electrónico del interesado de que tiene una notificación electrónica:','["La notificación es nula y debe practicarse de nuevo", "La notificación puede considerarse plenamente válida", "La notificación debe repetirse en papel en el domicilio", "El plazo para acceder a la notificación se amplía diez días"]'::jsonb,1,'Art. 41.6 Ley 39/2015','La falta de práctica del aviso no impide que la notificación sea considerada plenamente válida.',null),
('adm-cm:12-c48fbf78b9','adm-cm',12,'Según el artículo 43 de la Ley 39/2015, la notificación por medios electrónicos se entiende rechazada cuando:','["Han transcurrido cinco días hábiles desde su envío sin que el interesado haya contestado ni presentado alegaciones", "Han transcurrido diez días naturales desde su puesta a disposición sin que se acceda a su contenido", "Han transcurrido quince días hábiles desde que se dictó el acto", "El interesado no contesta en veinticuatro horas al aviso enviado a su dirección de correo electrónico o a su móvil"]'::jsonb,1,'Art. 43.2 Ley 39/2015','Se entiende practicada en el momento en que se produce el acceso a su contenido.',null),
('adm-cm:12-c1e11ec35a','adm-cm',12,'Según la Ley 39/2015, toda notificación debe cursarse dentro del plazo de:','["Tres días a partir de la fecha en que el acto haya adquirido firmeza", "Un mes a partir de la fecha en que el acto haya sido dictado y firmado", "Diez días a partir de la fecha en que el acto haya sido dictado", "Quince días a partir de la fecha en que el acto haya sido publicado"]'::jsonb,2,'Art. 40.2 Ley 39/2015','Debe contener el texto íntegro de la resolución, si pone fin o no a la vía administrativa y los recursos que procedan.',null),
('adm-cm:12-d8de2e1ace','adm-cm',12,'¿Qué es la Dirección Electrónica Habilitada única (DEHú)?','["La dirección postal que el interesado designa para recibir las notificaciones en papel cuando no está obligado a relacionarse electrónicamente", "El punto donde el interesado puede consultar las notificaciones electrónicas que le remitan las Administraciones", "La sede electrónica del Ministerio competente en materia de función pública", "El correo electrónico oficial que la Administración asigna a cada ciudadano y a cada empresa para recibir sus comunicaciones oficiales"]'::jsonb,1,'Art. 43 Ley 39/2015 y RD 203/2021','Las notificaciones pueden practicarse por comparecencia en la sede electrónica o a través de la DEHú.',null),
('adm-cm:13-f2e1dcfda5','adm-cm',13,'¿Cuál de las siguientes NO es una forma de iniciación de oficio del procedimiento?','["Propia iniciativa del órgano", "Orden superior", "Solicitud del interesado", "Petición razonada de otros órganos"]'::jsonb,2,'Art. 58 Ley 39/2015','De oficio se inicia por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia. La solicitud del interesado es la otra vía de inicio.',null),
('adm-cm:13-fb0455c7b4','adm-cm',13,'Si la solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en el plazo de:','["5 días, con indicación de que si no lo hace se archivará sin más trámite", "10 días, con indicación de que si no lo hace se le tendrá por desistido", "15 días, con indicación de que si no lo hace se le tendrá por desistido", "10 días, con indicación de que si no lo hace se declarará la caducidad"]'::jsonb,1,'Art. 68.1 Ley 39/2015','Se le da un plazo de diez días, con apercibimiento de que, si no lo hace, se le tendrá por desistido.','oct. 2026 · 1.er ejercicio'),
('adm-cm:13-120cdd150d','adm-cm',13,'El periodo de prueba en el procedimiento administrativo tiene una duración:','["No superior a 15 días ni inferior a 5", "De 20 días exactos", "No superior a 30 días ni inferior a 10", "No superior a 2 meses"]'::jsonb,2,'Art. 77.2 Ley 39/2015','El periodo de prueba no puede ser superior a treinta días ni inferior a diez.','oct. 2026 · 1.er ejercicio'),
('adm-cm:13-511377ae2f','adm-cm',13,'Salvo disposición expresa en contrario, los informes son:','["Preceptivos y vinculantes", "Preceptivos y no vinculantes", "Facultativos y vinculantes", "Facultativos y no vinculantes"]'::jsonb,3,'Art. 80.1 Ley 39/2015','Salvo disposición expresa, los informes son facultativos y no vinculantes.',null),
('adm-cm:13-d825da30e0','adm-cm',13,'Salvo que se fije otro plazo, los informes deben emitirse en:','["10 días", "15 días", "1 mes", "3 días"]'::jsonb,0,'Art. 80.2 Ley 39/2015','Los informes se emiten en el plazo de diez días, salvo que una disposición o el cumplimiento del resto de plazos exija otro.',null),
('adm-cm:13-920dbb4e2b','adm-cm',13,'En el trámite de audiencia, los interesados disponen de un plazo:','["No inferior a 5 días ni superior a 10", "No inferior a 10 días ni superior a 15", "De 20 días", "No inferior a 15 días ni superior a 30"]'::jsonb,1,'Art. 82.2 Ley 39/2015','El plazo de audiencia no puede ser inferior a diez días ni superior a quince.',null),
('adm-cm:13-5b400da893','adm-cm',13,'El plazo del trámite de información pública no puede ser inferior a:','["10 días", "15 días", "20 días", "1 mes"]'::jsonb,2,'Art. 83.2 Ley 39/2015','El plazo de información pública no puede ser inferior a veinte días.','nov. 2024 · 1.er ejercicio'),
('adm-cm:13-5d3cd64bfa','adm-cm',13,'¿Cuál de las siguientes NO pone fin al procedimiento administrativo?','["La resolución", "El desistimiento", "La declaración de caducidad", "La interposición de un recurso"]'::jsonb,3,'Art. 84.1 Ley 39/2015','Ponen fin al procedimiento la resolución, el desistimiento, la renuncia y la caducidad, y también la imposibilidad material sobrevenida.','nov. 2024 · 1.er ejercicio'),
('adm-cm:13-6f769c6e21','adm-cm',13,'En un procedimiento iniciado a solicitud que se paraliza por causa del interesado, la Administración le advierte de que se producirá la caducidad pasados:','["3 meses", "1 mes", "6 meses", "10 días"]'::jsonb,0,'Art. 95.1 Ley 39/2015','Transcurridos tres meses tras la advertencia sin que el interesado actúe, se produce la caducidad.',null),
('adm-cm:13-4a26913d49','adm-cm',13,'¿Cuál de los siguientes NO es un medio de ejecución forzosa de los actos administrativos?','["El apremio sobre el patrimonio", "La revocación del acto", "La ejecución subsidiaria", "La multa coercitiva"]'::jsonb,1,'Art. 100.1 Ley 39/2015','Los medios son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas.',null),
('adm-cm:13-ef7422dad7','adm-cm',13,'Se podrá prescindir del trámite de audiencia cuando:','["Se trate de un procedimiento sancionador o de responsabilidad patrimonial", "El interesado sea una persona jurídica obligada a relacionarse electrónicamente", "No figuren ni sean tenidos en cuenta otros hechos, alegaciones o pruebas que los aducidos por el interesado", "Lo acuerde motivadamente el instructor por razones de urgencia, aunque se tengan en cuenta hechos nuevos no aportados por el interesado"]'::jsonb,2,'Art. 82.4 Ley 39/2015','Si solo se valora lo aportado por el interesado, la audiencia puede omitirse.',null),
('adm-cm:13-636e5e5ee7','adm-cm',13,'A los interesados que no cumplan lo dispuesto en un trámite:','["Se les tendrá por desistidos de su solicitud y se archivará el procedimiento sin más trámite", "Se les podrá declarar decaídos en su derecho al trámite correspondiente", "Se les impondrá una multa coercitiva", "Se declara la caducidad"]'::jsonb,1,'Art. 73.3 Ley 39/2015','Se admitirá su actuación si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo.',null),
('adm-cm:13-1a28d12182','adm-cm',13,'Según el art. 98.1, tampoco son inmediatamente ejecutivos los actos:','["Que sean favorables al interesado", "Que necesiten aprobación o autorización superior", "Que pongan fin a la vía administrativa y no hayan sido recurridos", "Que hayan sido notificados con indicación de los recursos procedentes"]'::jsonb,1,'Art. 98.1 d) Ley 39/2015','Tampoco cuando se acuerde su suspensión o una disposición establezca lo contrario.',null),
('adm-cm:13-2e0cf6e286','adm-cm',13,'Es un derecho del interesado en el procedimiento:','["Obtener una resolución favorable si la Administración no resuelve en plazo", "Conocer en cualquier momento el estado de la tramitación de los procedimientos en los que sea interesado", "Elegir al instructor del procedimiento", "Conocer en cualquier momento el estado de tramitación de cualquier procedimiento de la Administración, aunque no tenga la condición de interesado"]'::jsonb,1,'Art. 53.1 a) Ley 39/2015','También el sentido del silencio, el órgano competente y obtener copia de los documentos.',null),
('adm-cm:13-6078d99158','adm-cm',13,'La declaración responsable es el documento por el que el interesado manifiesta, bajo su responsabilidad:','["Que acepta cualquier sanción que se derive de la falsedad de los datos aportados", "Que cumple los requisitos de la normativa vigente, dispone de la documentación que lo acredita y la pondrá a disposición de la Administración cuando se le requiera", "Que cumple los requisitos de la normativa vigente y aporta en ese momento toda la documentación que lo acredita, sin que la Administración pueda requerírsela después", "Que pone en conocimiento de la Administración sus datos identificativos"]'::jsonb,1,'Art. 69.1 Ley 39/2015','Definición legal de la declaración responsable.',null),
('adm-cm:13-afdda61927','adm-cm',13,'En ningún caso podrá imponerse a los administrados una obligación pecuniaria que:','["No se haya notificado con al menos quince días de antelación", "Supere los 3.000 euros sin autorización judicial previa y expresa", "No estuviese establecida con arreglo a una norma de rango legal", "No estuviese establecida en una norma de rango reglamentario aprobada por el Consejo de Gobierno o el Consejo de Ministros"]'::jsonb,2,'Art. 101.2 Ley 39/2015','Las obligaciones pecuniarias requieren base en una norma de rango legal.',null),
('adm-cm:13-0657a9cfbf','adm-cm',13,'La petición razonada de iniciación:','["No vincula al órgano competente, que deberá comunicar los motivos por los que, en su caso, no inicia", "Equivale a una denuncia y obliga a iniciar el procedimiento", "Solo puede formularla un ciudadano afectado", "Vincula al órgano competente para iniciar, que solo puede rechazarla si concurre una causa de inadmisión prevista en la ley"]'::jsonb,0,'Art. 61.2 Ley 39/2015','No es vinculante, pero hay que comunicar los motivos de no iniciar.',null),
('adm-cm:13-7e811a231d','adm-cm',13,'La multa coercitiva:','["Requiere autorización judicial previa en todo caso", "Es independiente de las sanciones que puedan imponerse y compatible con ellas", "Sustituye a la sanción que corresponda", "Es incompatible con las sanciones, de modo que si se impone una multa coercitiva no puede imponerse sanción por los mismos hechos"]'::jsonb,1,'Art. 103.2 Ley 39/2015','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('adm-cm:13-d9d6c1dfe8','adm-cm',13,'No podrá acordarse la caducidad del procedimiento por la simple inactividad del interesado en la cumplimentación de trámites:','["En ningún caso, cualquiera que sea el trámite omitido", "Siempre que no sean indispensables para dictar resolución", "Si el interesado es persona jurídica obligada a relacionarse electrónicamente", "Aunque sean indispensables para dictar resolución, si ha transcurrido el plazo"]'::jsonb,1,'Art. 95.2 Ley 39/2015','La inactividad en trámites no indispensables no da lugar a caducidad.',null),
('adm-cm:13-eb7180c55f','adm-cm',13,'En los procedimientos sancionadores, el presunto responsable tiene derecho, además:','["A elegir la sanción entre las previstas para la infracción", "A no declarar contra sí mismo, pero no a la presunción de inocencia, que es exclusiva del proceso penal", "A que se le notifique la sanción", "A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario"]'::jsonb,3,'Art. 53.2 b) Ley 39/2015','Es la presunción de inocencia en el ámbito sancionador.',null),
('adm-cm:13-5e8efdf600','adm-cm',13,'Las Administraciones pueden imponer multas coercitivas:','["Solo los Ayuntamientos, en el ejercicio de su potestad sancionadora", "Solo en materia tributaria", "Cuando así lo autoricen las leyes, y en la forma y cuantía que estas determinen", "Cuando lo autorice un reglamento, en la forma y cuantía que determine el órgano que ordena la ejecución"]'::jsonb,2,'Art. 103.1 Ley 39/2015','Requieren autorización legal y se reiteran por lapsos de tiempo suficientes para cumplir lo ordenado.',null),
('adm-cm:13-8105f06c2f','adm-cm',13,'La efectividad de las reducciones por reconocimiento o pago voluntario está condicionada a:','["El desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción", "Que la sanción sea inferior a 300 euros", "El desistimiento o renuncia de cualquier acción o recurso, tanto en vía administrativa como contencioso-administrativa", "La conformidad de la víctima o del denunciante y la renuncia expresa a la vía contencioso-administrativa"]'::jsonb,0,'Art. 85.3 Ley 39/2015','El infractor debe desistir o renunciar a recursos administrativos.',null),
('adm-cm:13-143ab9bbdc','adm-cm',13,'Si para la ejecución forzosa fuese necesario entrar en el domicilio del afectado, se requiere:','["Su consentimiento o, en su defecto, la oportuna autorización judicial", "Basta la resolución administrativa que ordena la ejecución, notificada al afectado", "Autorización del Delegado del Gobierno o, en su defecto, del alcalde", "Su consentimiento o, en su defecto, autorización del órgano superior jerárquico del que ordenó la ejecución"]'::jsonb,0,'Art. 100.3 Ley 39/2015','Se necesita el consentimiento del afectado o autorización judicial.',null),
('adm-cm:13-15a7078dd8','adm-cm',13,'Los procedimientos caducados:','["Impiden iniciar uno nuevo", "Interrumpen la prescripción", "No interrumpirán el plazo de prescripción", "Producen por sí solos la prescripción de las acciones"]'::jsonb,2,'Art. 95.3 Ley 39/2015','La caducidad no produce por sí sola la prescripción, pero el procedimiento caducado no la interrumpe.',null),
('adm-cm:13-8a353dabf4','adm-cm',13,'En los procedimientos de responsabilidad patrimonial es preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión, que deberá emitirse en un plazo máximo de:','["Dos meses", "Quince días", "Un mes", "Diez días"]'::jsonb,3,'Art. 81.1 Ley 39/2015','El informe del servicio no puede exceder de diez días.',null),
('adm-cm:13-51ab4c2122','adm-cm',13,'En los procedimientos sancionadores, los hechos declarados probados por resoluciones judiciales penales firmes:','["No vinculan a la Administración, que debe valorarlos libremente", "Solo vinculan si el interesado lo solicita expresamente en sus alegaciones al acuerdo de iniciación", "Vincularán a las Administraciones Públicas en los procedimientos sancionadores que substancien", "Vincularán a las Administraciones solo si la sentencia penal es condenatoria y se dictó antes de iniciarse el procedimiento"]'::jsonb,2,'Art. 77.4 Ley 39/2015','Los hechos probados en sentencia penal firme vinculan a la Administración.',null),
('adm-cm:13-329b08a074','adm-cm',13,'La resolución del procedimiento se dictará:','["Por escrito en papel, firmado por el titular del órgano", "Electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento", "Electrónicamente o en papel, a elección del órgano, garantizando solo la identidad del firmante y no la integridad del documento", "Verbalmente, con constancia en acta"]'::jsonb,1,'Art. 88.4 Ley 39/2015','La resolución se dicta electrónicamente.',null),
('adm-cm:13-6942d13add','adm-cm',13,'¿Quién puede acordar un período de información pública?','["El órgano al que corresponda la resolución del procedimiento, cuando su naturaleza lo requiera", "El instructor del procedimiento, a petición de cualquier interesado y siempre que lo autorice el órgano superior jerárquico", "Cualquier interesado, comunicándolo al órgano instructor, siempre que lo considere útil para su defensa", "El órgano que inició el procedimiento, solo en los procedimientos sancionadores"]'::jsonb,0,'Art. 83.1 Ley 39/2015','Lo acuerda el órgano competente para resolver.',null),
('adm-cm:13-e601f97250','adm-cm',13,'Excepcionalmente, cuando al iniciar el procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos, esta podrá realizarse en una fase posterior mediante:','["Una propuesta de resolución que deberá notificarse a los interesados", "La elaboración de un Pliego de cargos, que deberá ser notificado a los interesados", "La elaboración de un Pliego de cargos, que no se notifica a los interesados hasta la propuesta de resolución definitiva del instructor", "Un nuevo acuerdo de iniciación"]'::jsonb,1,'Art. 64.3 Ley 39/2015','Se elabora un Pliego de cargos que se notifica a los interesados.',null),
('adm-cm:13-8e0cf61dc0','adm-cm',13,'NO será inmediatamente ejecutiva la resolución:','["De un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición", "De un procedimiento sancionador contra la que quepa recurso de alzada, pero no si solo cabe el potestativo de reposición", "De una solicitud de licencia que haya sido estimada", "De un recurso de alzada"]'::jsonb,0,'Art. 98.1 b) Ley 39/2015','Las sanciones no son ejecutivas mientras quepa recurso administrativo.',null),
('adm-cm:13-b45909a70b','adm-cm',13,'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad:','["Se reduce la sanción a la mitad de forma automática", "Se archiva el procedimiento sin imponer sanción, si el infractor paga voluntariamente", "Se podrá resolver el procedimiento con la imposición de la sanción que proceda", "Se podrá resolver el procedimiento sin imponer sanción, salvo que la infracción sea muy grave o el infractor sea reincidente"]'::jsonb,2,'Art. 85.1 Ley 39/2015','El reconocimiento permite resolver con la sanción procedente.',null),
('adm-cm:13-4eac878cd2','adm-cm',13,'La ejecución subsidiaria procede respecto de actos que:','["Impongan obligaciones de no hacer o de soportar, previo apercibimiento al obligado", "Impongan al obligado el pago de cantidades líquidas", "Sean personalísimos de hacer y el obligado se niegue a realizarlos en el plazo fijado", "Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado"]'::jsonb,3,'Art. 102.1 Ley 39/2015','Cabe cuando el acto no es personalísimo y otro sujeto puede realizarlo.',null),
('adm-cm:13-82b5a2d685','adm-cm',13,'Si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones:','["Se tendrá por decaído su derecho y se archivará el procedimiento", "Se tendrá por realizado el trámite", "Se ampliará de oficio el plazo para que puedan reconsiderar su decisión, que no será vinculante hasta su vencimiento", "Se suspenderá el procedimiento"]'::jsonb,1,'Art. 82.3 Ley 39/2015','El trámite se tiene por realizado.',null),
('adm-cm:13-5ef8d66f84','adm-cm',13,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Quince días", "Diez días", "Cinco días", "Un mes"]'::jsonb,0,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('adm-cm:13-1d22e6f7cb','adm-cm',13,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Diez días a partir del siguiente al de la notificación del correspondiente acto", "Cinco días a partir del siguiente al de la notificación", "Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,0,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.','abr. 2026 · 1.er ejercicio'),
('adm-cm:13-8f58dec223','adm-cm',13,'La ejecución forzosa de los actos administrativos se efectuará:','["Solo con autorización judicial previa", "Siempre mediante compulsión sobre las personas", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual", "Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('adm-cm:13-c2d5cb4914','adm-cm',13,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio o a solicitud del interesado", "Solo de oficio, por propia iniciativa del órgano", "De oficio, a solicitud del interesado o por orden judicial", "Solo a solicitud"]'::jsonb,0,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('adm-cm:13-b52dc424c1','adm-cm',13,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["En ningún caso", "Sí, si lo autoriza el superior", "Sí, cuando la ley sea oscura", "Sí, en los procedimientos de oficio"]'::jsonb,0,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('adm-cm:13-fdc8efb74d','adm-cm',13,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["El infractor sea reincidente y reconozca su responsabilidad", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave", "La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('adm-cm:13-537ade7a38','adm-cm',13,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Un mes", "Quince días", "Siete días", "Tres meses"]'::jsonb,1,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('adm-cm:13-5bbfdd780a','adm-cm',13,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación de no hacer", "Una cantidad líquida", "Una obligación de soportar", "Una obligación personalísima"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('adm-cm:13-f61dfab907','adm-cm',13,'También producirá la terminación del procedimiento:','["La falta de crédito presupuestario adecuado y suficiente", "La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo"]'::jsonb,1,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('adm-cm:13-2538f093c4','adm-cm',13,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Por el instructor, a propuesta del Consejo de Estado", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,3,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('adm-cm:13-fb25487ce4','adm-cm',13,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La culpa del funcionario causante del daño", "La sanción disciplinaria del empleado público responsable", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La cuantía y el modo de indemnización"]'::jsonb,3,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('adm-cm:13-965e1f61cc','adm-cm',13,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Libremente y sin necesidad de motivación", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Solo con autorización judicial", "Motivadamente, en cualquier supuesto, sin necesidad de previsión legal"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('adm-cm:13-1ac5edaf23','adm-cm',13,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial", "No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Se refieran a sanciones de cuantía inferior a 3.000 euros", "Lo autorice un juez"]'::jsonb,1,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('adm-cm:13-32a5b4b9e0','adm-cm',13,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin informe favorable del Consejo de Estado u órgano consultivo equivalente", "Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico", "Sin autorización judicial en todo caso"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('adm-cm:13-3d3ded3957','adm-cm',13,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada", "Sean improcedentes a su juicio, sin necesidad de motivar el rechazo ni notificarlo a los interesados", "Se propongan fuera del plazo de diez días"]'::jsonb,1,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('adm-cm:13-eaf484ff6c','adm-cm',13,'El procedimiento está sometido al principio de:','["Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos", "Secreto de las actuaciones", "Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel"]'::jsonb,1,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.','abr. 2026 · 1.er ejercicio'),
('adm-cm:13-a8f3effab3','adm-cm',13,'En la petición de un informe se concretará:','["El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita", "El sentido que debe tener el informe y el plazo para emitirlo", "El nombre del funcionario que debe emitirlo"]'::jsonb,1,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('adm-cm:13-042cb4711d','adm-cm',13,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Lo soliciten todos los interesados por escrito", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('adm-cm:13-c5bf7fcade','adm-cm',13,'Según el art. 53.1 d), los interesados pueden formular alegaciones y aportar documentos:','["Solo en la solicitud inicial", "Solo en el período de prueba", "En cualquier fase del procedimiento anterior al trámite de audiencia", "En cualquier fase del procedimiento, incluso después de dictarse la resolución"]'::jsonb,2,'Art. 53.1 d) Ley 39/2015','Hasta el trámite de audiencia, que deberán ser tenidos en cuenta al redactar la propuesta de resolución.',null),
('adm-cm:13-cb41475b09','adm-cm',13,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento del procedimiento anterior al trámite de audiencia", "En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "Solo en los diez primeros días desde el inicio del procedimiento"]'::jsonb,0,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('adm-cm:13-2921ca9b50','adm-cm',13,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria", "Se archiva el procedimiento", "Se resuelve igualmente según la propuesta de resolución", "El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada"]'::jsonb,0,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('adm-cm:13-3cd319dad0','adm-cm',13,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "El 30 % solo por pronto pago", "El 10 %, no acumulable", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí"]'::jsonb,3,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('adm-cm:13-e197a8c3fe','adm-cm',13,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["Suspenden la tramitación, salvo la abstención", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "No suspenderán la tramitación del procedimiento, salvo la recusación", "Suspenden siempre la tramitación"]'::jsonb,2,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('adm-cm:13-89a21ff98b','adm-cm',13,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["Todos los recursos de un mismo interesado frente a actos distintos", "La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites de un mismo interesado, aunque sea obligado su cumplimiento sucesivo", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo"]'::jsonb,3,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('adm-cm:13-7ff74ade8e','adm-cm',13,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Obligaciones no personalísimas de hacer que puedan cumplirse por otro", "Cobrar cantidades líquidas", "Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar"]'::jsonb,3,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('adm-cm:13-242718433c','adm-cm',13,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["De tres días", "De un mes", "No superior a quince días", "No inferior a veinte días"]'::jsonb,2,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('adm-cm:13-bf23561577','adm-cm',13,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Las realiza el denunciante y el órgano competente, respectivamente", "Se tramitan como una sola fase", "Se encomendarán a órganos distintos"]'::jsonb,3,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('adm-cm:13-9dc80fb08e','adm-cm',13,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "No puede asistir a su práctica", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('adm-cm:13-11797912e5','adm-cm',13,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El sentido de la resolución que deba dictarse", "La sanción que corresponda imponer, el órgano competente para resolver, el instructor designado y el plazo máximo para dictar resolución", "El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,3,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('adm-cm:13-0776ba74bc','adm-cm',13,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva", "Por el doble de su coste, en concepto de sanción", "Nunca, porque los gastos los asume siempre la Administración que ejecuta", "Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional"]'::jsonb,0,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('adm-cm:13-e7fb149d54','adm-cm',13,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Todos los acuerdos convencionales que pongan fin a cualquier procedimiento", "Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,2,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null),
('adm-cm:13-c12d59b65e','adm-cm',13,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Ministro respectivo", "El Subsecretario", "El Presidente del Gobierno", "El Delegado del Gobierno"]'::jsonb,0,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('adm-cm:13-56f9b31b2a','adm-cm',13,'En ningún caso se podrá imponer una sanción:','["Sin que se haya tramitado el oportuno procedimiento", "A una persona jurídica", "Superior a 600 euros sin autorización judicial", "Sin que el infractor esté asistido de abogado"]'::jsonb,0,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('adm-cm:13-98e567f4b7','adm-cm',13,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Cinco días", "Quince días", "Diez días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('adm-cm:13-259ff30e1c','adm-cm',13,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "Es obligatoria para poder recurrir después la resolución", "Convierte en interesado al compareciente", "No otorga, por sí misma, la condición de interesado"]'::jsonb,3,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null),
('adm-cm:13-8420527056','adm-cm',13,'Contra el acuerdo de acumulación de procedimientos:','["No procederá recurso alguno", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "Cabe recurso de alzada"]'::jsonb,0,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('adm-cm:13-b504487245','adm-cm',13,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "Se mantiene la tramitación simplificada", "Se mantiene la tramitación simplificada si el órgano lo motiva", "La Administración deberá seguir la tramitación ordinaria"]'::jsonb,3,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('adm-cm:13-3c58a89cee','adm-cm',13,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Lo decida motivadamente el instructor del procedimiento", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada", "Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('adm-cm:13-3a9b25d22a','adm-cm',13,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Deberá archivar el procedimiento", "Deberá pedir dictamen al Consejo de Estado"]'::jsonb,0,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('adm-cm:13-e0f9ee3a2c','adm-cm',13,'Si un informe preceptivo no se emite en plazo:','["Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable", "Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se archiva el procedimiento"]'::jsonb,2,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('adm-cm:13-dac16d1a6b','adm-cm',13,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, sin posibilidad de recurso", "Un mes desde su presentación, con recurso de alzada", "Diez días desde su presentación, con recurso de alzada", "Cinco días desde su presentación, con recurso potestativo de reposición"]'::jsonb,0,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('adm-cm:13-d30c479fea','adm-cm',13,'Los expedientes tendrán formato electrónico y se formarán mediante la agregación ordenada de documentos, con:','["Un sello en papel en cada documento", "Un resumen elaborado por el instructor con la relación de los interesados y de los trámites realizados", "La firma de todos los interesados en cada uno de los documentos que contenga", "Un índice numerado de todos los documentos que contenga cuando se remita"]'::jsonb,3,'Art. 70.2 Ley 39/2015','Deben incluir un índice numerado de todos los documentos.',null),
('adm-cm:13-aec0ba32e3','adm-cm',13,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer", "La sanción disciplinaria al funcionario responsable y la cuantía de la indemnización", "La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración"]'::jsonb,2,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('adm-cm:13-c280885dff','adm-cm',13,'No se podrán adoptar medidas provisionales que:','["Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia", "Se adopten una vez iniciado el procedimiento, sin audiencia previa del interesado", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes"]'::jsonb,3,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('adm-cm:13-dea671228b','adm-cm',13,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["Nunca, porque la tramitación simplificada lo suprime en todo caso", "Siempre, como en la tramitación ordinaria", "Lo pida cualquier tercero que no sea interesado", "La resolución vaya a ser desfavorable para el interesado"]'::jsonb,3,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('adm-cm:13-5f75c1890a','adm-cm',13,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["De uso obligatorio por los interesados", "Solo orientativos", "Exclusivos para personas jurídicas", "De uso voluntario"]'::jsonb,0,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('adm-cm:13-fb60ffc9c6','adm-cm',13,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El más rápido para la Administración", "El que elija el interesado de entre los admisibles", "El más económico para la Administración actuante", "El menos restrictivo de la libertad individual"]'::jsonb,3,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('adm-cm:13-b34e3d6cc0','adm-cm',13,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Los recursos contencioso-administrativos", "Las acciones posesorias", "Los recursos de alzada", "Las reclamaciones de responsabilidad"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('adm-cm:13-f52422bb76','adm-cm',13,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una copia firmada por el titular del órgano destinatario", "La devolución de las tasas abonadas", "Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación"]'::jsonb,3,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('adm-cm:13-341aa3b681','adm-cm',13,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Un mes desde que fueron notificados", "Quince días desde que fueron notificados", "Diez días desde que fueron notificados"]'::jsonb,3,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:13-0b712d4004','adm-cm',13,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno", "Nada, la obligación se extingue", "Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil"]'::jsonb,0,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('adm-cm:13-f845a12570','adm-cm',13,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["El período de prueba", "Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento", "El trámite de información pública"]'::jsonb,1,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('adm-cm:13-ee7724519b','adm-cm',13,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["La sanción que corresponda sea muy grave", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,2,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('adm-cm:13-a58c01574d','adm-cm',13,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se entiende estimada la reclamación", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,3,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('adm-cm:13-1a3d16d0b8','adm-cm',13,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro del mes siguiente a su adopción", "Dentro de los tres meses siguientes", "Dentro de los quince días siguientes a su adopción", "Dentro de los diez días siguientes a su adopción"]'::jsonb,2,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.','oct. 2026 · 1.er ejercicio'),
('adm-cm:13-946969346d','adm-cm',13,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento", "No tienen valor probatorio", "Harán prueba de estos salvo que se acredite lo contrario"]'::jsonb,3,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('adm-cm:13-2fa63fd8ab','adm-cm',13,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Tres meses desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Seis meses desde el inicio del procedimiento", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('adm-cm:13-53560b6a9f','adm-cm',13,'Se entiende por propia iniciativa:','["La petición de un órgano sin competencia de iniciación", "La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,2,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('adm-cm:13-540ebeb51c','adm-cm',13,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que lo pida el denunciante", "Con independencia de su diferente valoración jurídica"]'::jsonb,3,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('adm-cm:13-67d6714607','adm-cm',13,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Un mes", "Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('adm-cm:13-6e040053be','adm-cm',13,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Solo si el instructor lo propone y el interesado no se opone", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Salvo que sea una persona jurídica", "Sin que en ningún caso pueda agravar su situación inicial"]'::jsonb,3,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('adm-cm:13-416dc40f6f','adm-cm',13,'La presentación de una denuncia:','["Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "Obliga a iniciar el procedimiento y a sancionar", "No confiere, por sí sola, la condición de interesado en el procedimiento", "Requiere asistencia de abogado"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('adm-cm:13-17b514610d','adm-cm',13,'Según el art. 62.1, se entiende por denuncia:','["La solicitud de un interesado para que se inicie un procedimiento en su favor", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "La orden de un superior"]'::jsonb,1,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('adm-cm:13-3fe28a2dbe','adm-cm',13,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "6.000 euros", "100.000 euros", "30.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('adm-cm:13-f7142ada05','adm-cm',13,'En el despacho de los expedientes se guardará:','["El orden que prefiera el funcionario responsable", "El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('adm-cm:13-84aac65304','adm-cm',13,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal", "Solicitar autorización judicial", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Notificar al particular interesado la resolución que autorice la actuación administrativa"]'::jsonb,3,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('adm-cm:13-a79f6e9427','adm-cm',13,'NO forma parte del expediente administrativo:','["La información auxiliar o de apoyo, como notas, borradores u opiniones, salvo los informes solicitados antes de la resolución", "Las notificaciones practicadas", "Las pruebas practicadas", "Los informes preceptivos, que se incorporan a un expediente auxiliar distinto del principal y no se remiten al juzgado"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Notas, borradores, opiniones, resúmenes y comunicaciones internas no forman parte del expediente.',null),
('adm-cm:13-32feafbfaa','adm-cm',13,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "A los tres meses de su presentación si la Administración no se opone", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('adm-cm:13-9162a96ffe','adm-cm',13,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["No está permitido una vez iniciado el procedimiento", "Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "Solo afectará a aquellos que la hubiesen formulado", "Afectará a todos los interesados, salvo que alguno inste la continuación en diez días"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('adm-cm:13-d559588246','adm-cm',13,'Según la Ley 39/2015, el expediente administrativo es:','["La carpeta física en la que se archivan los escritos de los interesados", "El acto administrativo que pone fin al procedimiento", "Cualquier documento que se presente en un registro electrónico", "El conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa, y las diligencias encaminadas a ejecutarla"]'::jsonb,3,'Art. 70.1 Ley 39/2015','Los expedientes tienen formato electrónico.',null),
('adm-cm:13-42ca464f9b','adm-cm',13,'¿Forman parte del expediente administrativo las notas, borradores y opiniones de carácter auxiliar?','["Sí, todos ellos, porque reflejan la actividad del órgano", "No, y además deben destruirse al terminar el procedimiento", "No, salvo que se trate de informes preceptivos o facultativos solicitados antes de la resolución", "Sí, todos ellos, porque reflejan la actividad interna del órgano y deben estar a disposición de los interesados"]'::jsonb,2,'Art. 70.4 Ley 39/2015','Tampoco forman parte las comunicaciones e informes internos o entre órganos o entidades administrativas, ni los juicios de valor emitidos por las Administraciones.',null),
('adm-cm:13-32546f981d','adm-cm',13,'Al remitir un expediente electrónico, este debe ir acompañado de:','["El original en papel de cada uno de los documentos que lo integran", "La firma manuscrita del jefe de la unidad que lo tramita y lo remite", "Una copia completa en soporte óptico, como un CD o un DVD", "Un índice numerado de todos los documentos que contenga"]'::jsonb,3,'Art. 70.2 Ley 39/2015','El índice garantiza la integridad del expediente y permite su recuperación.',null),
('adm-cm:14-f7f901536b','adm-cm',14,'Contra las resoluciones y los actos de trámite cualificados caben los recursos de:','["Alzada y potestativo de reposición", "Alzada y extraordinario de revisión, únicamente", "Reposición obligatoria y alzada", "Súplica y potestativo de reposición"]'::jsonb,0,'Art. 112.1 Ley 39/2015','Caben el recurso de alzada y el potestativo de reposición.',null),
('adm-cm:14-0c3c3469df','adm-cm',14,'La interposición de un recurso administrativo, como regla general:','["Suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "No suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "Suspende la ejecución del acto durante el plazo para resolver el recurso, salvo que el órgano acuerde lo contrario", "No suspende la ejecución del acto, sin que ninguna disposición normativa pueda establecer otra cosa"]'::jsonb,1,'Art. 117.1 Ley 39/2015','La interposición de cualquier recurso no suspende la ejecución del acto impugnado, salvo disposición en contrario.',null),
('adm-cm:14-a04123c88f','adm-cm',14,'Si se solicita la suspensión de la ejecución al recurrir y no hay resolución expresa, la ejecución se entiende suspendida cuando pasa:','["10 días desde la solicitud", "15 días hábiles desde la solicitud", "1 mes desde la solicitud", "3 meses desde la solicitud"]'::jsonb,2,'Art. 117.3 Ley 39/2015','Se entiende suspendida si transcurre un mes desde la solicitud sin resolución expresa.',null),
('adm-cm:14-92c434a7e6','adm-cm',14,'El recurso de alzada se interpone contra:','["Actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Disposiciones de carácter general y actos que no ponen fin a la vía administrativa", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el mismo órgano administrativo que los dictó", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico"]'::jsonb,3,'Art. 121.1 Ley 39/2015','Procede contra los actos que no ponen fin a la vía administrativa y se resuelve por el superior jerárquico.',null),
('adm-cm:14-afd0c20457','adm-cm',14,'Si el acto es expreso, el plazo para interponer recurso de alzada es de:','["1 mes", "2 meses", "15 días", "3 meses"]'::jsonb,0,'Art. 122.1 Ley 39/2015','Es de un mes si el acto es expreso; si no lo es, puede interponerse en cualquier momento desde el día siguiente a los efectos del silencio.',null),
('adm-cm:14-b7f843756b','adm-cm',14,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de alzada?','["1 mes; pasado ese plazo, se podrá entender estimado", "3 meses; pasado ese plazo, se podrá entender desestimado", "6 meses; pasado ese plazo, se podrá entender desestimado", "3 meses; pasado ese plazo sin resolución expresa, se entenderá siempre estimado"]'::jsonb,1,'Art. 122.2 Ley 39/2015','El plazo es de tres meses. Transcurrido sin resolución, se podrá entender desestimado el recurso, salvo excepción.',null),
('adm-cm:14-ea503eb10a','adm-cm',14,'El recurso de reposición:','["Es obligatorio antes de acudir a los tribunales contencioso-administrativos", "Es potestativo, contra actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico del que los dictó", "Es potestativo, contra actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Es obligatorio, contra actos que ponen fin a la vía administrativa, ante el mismo órgano"]'::jsonb,2,'Art. 123.1 Ley 39/2015','Es potestativo y se interpone ante el mismo órgano que dictó el acto que pone fin a la vía administrativa.',null),
('adm-cm:14-a8044d9792','adm-cm',14,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de reposición?','["3 meses", "15 días", "2 meses", "1 mes"]'::jsonb,3,'Art. 124.2 Ley 39/2015','El plazo máximo es de un mes.',null),
('adm-cm:14-76b0f117ce','adm-cm',14,'El recurso extraordinario de revisión por error de hecho que resulte de los documentos del expediente se interpone en el plazo de:','["4 años desde la notificación de la resolución", "3 meses desde la notificación de la resolución", "1 año desde la notificación de la resolución", "2 meses desde que se tuvo conocimiento del error"]'::jsonb,0,'Art. 125.2 Ley 39/2015','Cuatro años desde la notificación en la causa a); tres meses en las demás causas.',null),
('adm-cm:14-84ac2a1812','adm-cm',14,'Contra la resolución de un recurso de alzada:','["Cabe recurso potestativo de reposición ante el mismo órgano que resolvió la alzada", "Solo cabe el recurso extraordinario de revisión, en los casos del art. 125.1", "Cabe un nuevo recurso de alzada ante el superior jerárquico del que resolvió", "Solo cabe recurso potestativo de reposición ante el mismo órgano, en los casos del art. 125.1"]'::jsonb,1,'Art. 122.3 Ley 39/2015','No cabe ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos previstos.',null),
('adm-cm:14-9eed31ec48','adm-cm',14,'Según el art. 1.1 de la Ley 29/1998, los órganos del orden contencioso-administrativo conocen de las pretensiones relativas a:','["La actuación de las Administraciones sujeta al Derecho Administrativo, las disposiciones de rango inferior a la ley y los Decretos legislativos que excedan la delegación", "La actuación de las Administraciones sujeta al Derecho privado y laboral, así como las leyes de las Cortes Generales y autonómicas que vulneren la Constitución", "Las disposiciones de rango inferior a la ley, pero no los Decretos legislativos, que solo controla el Tribunal Constitucional", "Cualquier conflicto entre particulares y Administraciones, sea cual sea el Derecho aplicable a la relación"]'::jsonb,0,'Art. 1.1 Ley 29/1998','Conocen de la actuación administrativa sujeta al Derecho Administrativo, de las disposiciones generales de rango inferior a la ley y de los Decretos legislativos que excedan los límites de la delegación.',null),
('adm-cm:14-25c5e98a4e','adm-cm',14,'¿Cuál de los siguientes NO es un órgano del orden jurisdiccional contencioso-administrativo?','["Los Juzgados Centrales de lo Contencioso-administrativo", "Los Juzgados de lo Social", "La Sala de lo Contencioso-administrativo de la Audiencia Nacional", "Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia"]'::jsonb,1,'Art. 6 Ley 29/1998','Son órganos de este orden los Juzgados de lo C-A, los Juzgados Centrales de lo C-A, las Salas de lo C-A de los TSJ, la de la Audiencia Nacional y la del Tribunal Supremo. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('adm-cm:14-0514e2f86f','adm-cm',14,'Los recursos contra los actos de las Entidades locales (salvo los instrumentos de planeamiento urbanístico) corresponden, en única o primera instancia, a:','["La Sala de lo Contencioso-administrativo del Tribunal Superior de Justicia", "La Sala de lo Contencioso-administrativo de la Audiencia Nacional", "Los Juzgados de lo Contencioso-administrativo", "Los Juzgados Centrales de lo Contencioso-administrativo"]'::jsonb,2,'Art. 8.1 Ley 29/1998','Corresponden a los Juzgados de lo Contencioso-administrativo, excluidas las impugnaciones de instrumentos de planeamiento urbanístico. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('adm-cm:14-edfe71bd84','adm-cm',14,'Según el art. 19.1 a), están legitimadas ante el orden contencioso-administrativo:','["Las personas físicas de nacionalidad española que ostenten un derecho subjetivo", "Las personas físicas o jurídicas que hayan sido parte en el procedimiento administrativo", "Las personas jurídicas inscritas en un registro público que acrediten un interés directo", "Las personas físicas o jurídicas que ostenten un derecho o interés legítimo"]'::jsonb,3,'Art. 19.1 a) Ley 29/1998','Están legitimadas las personas físicas o jurídicas que ostenten un derecho o interés legítimo.',null),
('adm-cm:14-ddc2bfebe5','adm-cm',14,'Los funcionarios públicos pueden comparecer por sí mismos, sin abogado ni procurador:','["En defensa de sus derechos estatutarios, en cuestiones de personal que no impliquen separación de empleados inamovibles", "En defensa de sus derechos estatutarios, en cualquier cuestión de personal, incluida la separación de empleados públicos inamovibles", "Solo en los recursos de casación y en los procedimientos de cuantía inferior a 30.000 euros", "En ningún caso, pues en este orden siempre es preceptiva la asistencia de abogado"]'::jsonb,0,'Art. 23.3 Ley 29/1998','Pueden hacerlo en defensa de sus derechos estatutarios, cuando se trate de cuestiones de personal que no impliquen separación de empleados públicos inamovibles.',null),
('adm-cm:14-979010b5df','adm-cm',14,'El recurso contencioso-administrativo es admisible contra:','["Las disposiciones de carácter general y los actos expresos que pongan fin a la vía administrativa, pero no los presuntos", "Las disposiciones de carácter general y los actos expresos y presuntos que pongan fin a la vía administrativa", "Los actos expresos y presuntos que no pongan fin a la vía administrativa, pero no las disposiciones generales", "Las leyes de las Cortes Generales y los actos expresos de la Administración"]'::jsonb,1,'Art. 25.1 Ley 29/1998','Contra disposiciones de carácter general y actos expresos y presuntos que pongan fin a la vía administrativa, definitivos o de trámite cualificados.',null),
('adm-cm:14-bb29f4d965','adm-cm',14,'Además de contra actos y disposiciones, el recurso contencioso-administrativo cabe contra:','["Las decisiones del Gobierno en sus relaciones con las Cortes Generales", "La inactividad de la Administración, pero no sus actuaciones materiales", "La inactividad de la Administración y sus actuaciones materiales que constituyan vía de hecho", "Los contratos privados celebrados entre particulares y las actuaciones materiales derivadas de ellos"]'::jsonb,2,'Art. 25.2 Ley 29/1998','También es admisible contra la inactividad de la Administración y contra sus actuaciones materiales constitutivas de vía de hecho.',null),
('adm-cm:14-9f25c4dc16','adm-cm',14,'Con carácter general, el recurso contencioso-administrativo se inicia:','["Por escrito de demanda, con la que se acompañan las pruebas y el expediente administrativo completo remitido por la Administración", "Mediante comparecencia verbal ante el Letrado de la Administración de Justicia del juzgado", "Mediante solicitud previa a la Administración demandada para que remita el expediente al juzgado", "Por escrito que cita el acto o actuación impugnados y solicita que se tenga por interpuesto el recurso"]'::jsonb,3,'Art. 45.1 Ley 29/1998','Se inicia por un escrito reducido a citar lo que se impugna y a pedir que se tenga por interpuesto el recurso.',null),
('adm-cm:14-eef06d3671','adm-cm',14,'Si el acto que pone fin a la vía administrativa es expreso, el plazo para interponer el recurso contencioso-administrativo es de:','["Dos meses desde el día siguiente a su publicación o notificación", "Un mes desde el día siguiente a su publicación o notificación", "Seis meses desde el día siguiente a su publicación o notificación", "Dos meses desde el mismo día de su publicación o notificación"]'::jsonb,0,'Art. 46.1 Ley 29/1998','Dos meses contados desde el día siguiente a la publicación o notificación del acto.','abr. 2026 · 1.er ejercicio'),
('adm-cm:14-87350ec320','adm-cm',14,'Contra una vía de hecho sin requerimiento previo a la Administración, el plazo para recurrir es de:','["Diez días desde que se inició la actuación", "Veinte días desde que se inició la actuación", "Dos meses desde que se inició la actuación", "Un mes desde que terminó la actuación material"]'::jsonb,1,'Art. 46.3 Ley 29/1998','Si no hubo requerimiento, veinte días desde que se inició la actuación. Si lo hubo, diez días desde que terminó el plazo del requerimiento.',null),
('adm-cm:14-274e4e67de','adm-cm',14,'¿De qué plazo dispone el recurrente para formalizar la demanda?','["Diez días", "Quince días", "Veinte días", "Un mes"]'::jsonb,2,'Art. 52.1 Ley 29/1998','La demanda se deduce en el plazo de veinte días.',null),
('adm-cm:14-09aebd3d19','adm-cm',14,'¿De qué plazo dispone la Administración demandada para contestar a la demanda?','["Diez días", "Un mes", "Quince días", "Veinte días"]'::jsonb,3,'Art. 54.1 Ley 29/1998','La contestación se presenta en el plazo de veinte días.','oct. 2026 · 1.er ejercicio'),
('adm-cm:14-496056a090','adm-cm',14,'Se sigue el procedimiento abreviado, entre otros casos, en los asuntos cuya cuantía no supere:','["30.000 euros", "6.000 euros", "60.000 euros", "100.000 euros"]'::jsonb,0,'Art. 78.1 Ley 29/1998','Se tramitan por el procedimiento abreviado, entre otros, los asuntos cuya cuantía no supere los 30.000 euros.',null),
('adm-cm:14-ba1badb1cc','adm-cm',14,'No son apelables las sentencias de los Juzgados dictadas en asuntos cuya cuantía no exceda de:','["6.000 euros", "30.000 euros", "18.000 euros", "600.000 euros"]'::jsonb,1,'Art. 81.1 a) Ley 29/1998','No son apelables cuando la cuantía no excede de 30.000 euros, salvo los supuestos del art. 81.2. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('adm-cm:14-7b24984438','adm-cm',14,'Las sentencias que declaren la inadmisión del recurso:','["Nunca son apelables", "Solo son apelables si la cuantía supera 30.000 euros", "Son siempre apelables", "Solo admiten recurso de reposición"]'::jsonb,2,'Art. 81.2 a) Ley 29/1998','Las sentencias que declaren la inadmisión del recurso son siempre apelables.',null),
('adm-cm:14-54727389e0','adm-cm',14,'El recurso de apelación se interpone dentro de:','["Los diez días siguientes a la notificación de la sentencia", "El mes siguiente", "Los dos meses siguientes", "Los quince días siguientes a la notificación de la sentencia"]'::jsonb,3,'Art. 85.1 Ley 29/1998','Se interpone dentro de los quince días siguientes al de la notificación de la sentencia.',null),
('adm-cm:14-0e59697630','adm-cm',14,'¿Cuándo puede instarse la ejecución forzosa de una sentencia que la Administración no ha cumplido?','["Transcurridos dos meses desde su comunicación, o el plazo fijado para su cumplimiento", "Transcurridos seis meses desde su firmeza, sin que la sentencia pueda fijar otro plazo para su cumplimiento", "Transcurridos tres meses desde su comunicación al órgano obligado, salvo que la sentencia fije otro plazo", "Transcurrido un mes desde su comunicación, o el plazo fijado para su cumplimiento"]'::jsonb,0,'Art. 104.2 Ley 29/1998','Transcurridos dos meses desde la comunicación de la sentencia, o el plazo fijado en ella, cualquiera de las partes y personas afectadas puede instar su ejecución forzosa.',null),
('adm-cm:14-7431dfe564','adm-cm',14,'La tramitación del recurso para la protección de los derechos fundamentales de la persona tiene carácter:','["Ordinario", "Preferente", "Facultativo", "Secreto"]'::jsonb,1,'Art. 114.3 Ley 29/1998','La tramitación de estos recursos tiene carácter preferente.',null),
('adm-cm:14-67d99fbc00','adm-cm',14,'El plazo para interponer el recurso especial de protección de los derechos fundamentales es de:','["Dos meses", "Veinte días", "Diez días", "Un mes"]'::jsonb,2,'Art. 115.1 Ley 29/1998','El plazo es de diez días.',null),
('adm-cm:14-01cd83e2eb','adm-cm',14,'¿Cuándo pueden solicitar los interesados la adopción de medidas cautelares?','["Solo al presentar la demanda", "Solo antes de la vista", "Solo en apelación", "En cualquier estado del proceso"]'::jsonb,3,'Art. 129.1 Ley 29/1998','Pueden solicitarlas en cualquier estado del proceso para asegurar la efectividad de la sentencia.',null),
('adm-cm:14-b3ccf1a325','adm-cm',14,'Cuando se alegan circunstancias de especial urgencia, el juez puede resolver sobre las medidas cautelares:','["Sin oír a la parte contraria, en el plazo de dos días", "Solo tras oír a todas las partes durante diez días", "Solo tras la sentencia", "Únicamente si lo autoriza la Administración"]'::jsonb,0,'Art. 135.1 Ley 29/1998','Puede decidir sin oír a la parte contraria, en el plazo de dos días.',null),
('adm-cm:14-80b8715bae','adm-cm',14,'En primera o única instancia, las costas se imponen como regla general:','["A la Administración demandada en todo caso, salvo que el recurso sea temerario", "A quien vea rechazadas todas sus pretensiones, salvo que el órgano aprecie y razone serias dudas de hecho o de derecho", "A cada parte las causadas a su instancia y las comunes por mitad, en todo caso y sin que el órgano pueda apreciar temeridad", "Al demandante que vea rechazada cualquiera de sus pretensiones, aunque haya dudas de derecho"]'::jsonb,1,'Art. 139.1 Ley 29/1998','Rige el criterio del vencimiento, salvo que el órgano aprecie y razone que el caso presentaba serias dudas de hecho o de derecho.',null),
('adm-cm:14-533f0943bb','adm-cm',14,'Si el recurso de alzada se interpone ante el órgano que dictó el acto, este deberá remitirlo al competente:','["En el plazo de un mes, con su informe y una copia completa y ordenada del expediente", "En el plazo de diez días, con su informe y una copia completa y ordenada del expediente", "En el plazo de quince días, sin necesidad de informe", "En el plazo de tres días, con el expediente original"]'::jsonb,1,'Art. 121.2 Ley 39/2015','Debe remitirlo en 10 días con informe y copia del expediente.',null),
('adm-cm:14-6ee41c485f','adm-cm',14,'Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente original, se pondrán de manifiesto a los interesados para alegaciones en un plazo:','["De un mes, prorrogable por otro mes a petición del interesado", "No inferior a diez días ni superior a quince", "No inferior a cinco días ni superior a diez", "De veinte días hábiles, prorrogable por otros diez"]'::jsonb,1,'Art. 118.1 Ley 39/2015','El plazo es de 10 a 15 días.',null),
('adm-cm:14-b633005178','adm-cm',14,'También es causa del recurso extraordinario de revisión que la resolución se haya dictado como consecuencia de:','["Prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible declarada en sentencia judicial firme", "Un cambio de criterio de la Administración posterior a la resolución", "Una denuncia de un tercero por prevaricación o cohecho, aunque todavía no haya recaído sentencia judicial firme", "Un error de calificación del recurso"]'::jsonb,0,'Art. 125.1 d) Ley 39/2015','Exige que la conducta se haya declarado en sentencia judicial firme.',null),
('adm-cm:14-a885a63cbb','adm-cm',14,'La resolución de un recurso será congruente con las peticiones del recurrente:','["Salvo en materia de personal, en que puede agravarse su situación inicial", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Solo si el recurrente lo autoriza expresamente", "Sin que en ningún caso pueda agravarse su situación inicial"]'::jsonb,3,'Art. 119.3 Ley 39/2015','Es la prohibición de la reformatio in peius.',null),
('adm-cm:14-378222ce67','adm-cm',14,'Si el acto no es expreso, el recurso de alzada podrá interponerse:','["En el plazo de un mes desde el día siguiente a aquel en que se produzcan los efectos del silencio", "En el plazo de tres meses desde la presentación de la solicitud", "En el plazo de dos meses", "En cualquier momento a partir del día siguiente a aquel en que se produzcan los efectos del silencio"]'::jsonb,3,'Art. 122.1 Ley 39/2015','Contra actos presuntos, en cualquier momento desde que se producen los efectos del silencio.',null),
('adm-cm:14-a765429018','adm-cm',14,'Interpuesto un recurso de reposición, no se podrá interponer recurso contencioso-administrativo hasta que:','["Sea resuelto expresamente o se haya producido su desestimación presunta", "Pasen seis meses desde su interposición, aunque se haya resuelto antes", "Sea resuelto expresamente, sin que baste la desestimación presunta", "Lo autorice el órgano que dictó el acto"]'::jsonb,0,'Art. 123.2 Ley 39/2015','Hay que esperar a la resolución expresa o la desestimación presunta.',null),
('adm-cm:14-def83a365d','adm-cm',14,'También pone fin a la vía administrativa:','["El acuerdo de iniciación del procedimiento sancionador o de responsabilidad", "La providencia de apertura del periodo de prueba", "El informe preceptivo y vinculante emitido por un órgano consultivo", "La resolución de los procedimientos de responsabilidad patrimonial"]'::jsonb,3,'Art. 114.1 e) Ley 39/2015','Las resoluciones en materia de responsabilidad patrimonial ponen fin a la vía administrativa, cualquiera que sea el tipo de relación.','nov. 2024 · 1.er ejercicio'),
('adm-cm:14-71af6b1281','adm-cm',14,'Contra las disposiciones administrativas de carácter general:','["No cabe recurso en vía administrativa", "Cabe recurso de alzada", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión"]'::jsonb,0,'Art. 112.3 Ley 39/2015','Contra las disposiciones de carácter general no cabe recurso administrativo.',null),
('adm-cm:14-603da2bdf1','adm-cm',14,'¿Ante quién se interpone el recurso extraordinario de revisión?','["Ante el Tribunal Superior de Justicia competente", "Ante el superior jerárquico del órgano que dictó el acto, que es competente para resolverlo", "Ante el órgano administrativo que dictó el acto, que también es competente para resolverlo", "Ante el superior jerárquico del órgano que dictó el acto, previo dictamen del Consejo de Estado"]'::jsonb,2,'Art. 125.1 Ley 39/2015','Se interpone y resuelve por el mismo órgano que dictó el acto.',null),
('adm-cm:14-2ea802e053','adm-cm',14,'Ponen fin a la vía administrativa:','["Los actos de trámite simples", "Las propuestas de resolución", "Las resoluciones de los recursos de alzada", "Los actos de órganos con superior jerárquico, como regla general"]'::jsonb,2,'Art. 114.1 a) Ley 39/2015','Las resoluciones de alzada ponen fin a la vía administrativa.',null),
('adm-cm:14-9569b780a1','adm-cm',14,'El órgano que resuelva el recurso podrá suspender la ejecución del acto impugnado cuando:','["La impugnación se fundamente en alguna de las causas de nulidad de pleno derecho del art. 47.1", "La impugnación se fundamente en cualquier causa de anulabilidad, aunque la ejecución no cause perjuicios", "Lo pida un tercero no interesado en el procedimiento", "El acto sea favorable"]'::jsonb,0,'Art. 117.2 b) Ley 39/2015','También cuando la ejecución pueda causar perjuicios de imposible o difícil reparación.',null),
('adm-cm:14-80456a728a','adm-cm',14,'Contra la resolución de un recurso de reposición:','["Cabe recurso de alzada", "No puede interponerse de nuevo dicho recurso", "Cabe un segundo recurso de reposición", "Cabe recurso de reposición ante el superior"]'::jsonb,1,'Art. 124.3 Ley 39/2015','No cabe reiterar la reposición.',null),
('adm-cm:14-8af0985752','adm-cm',14,'Es causa de inadmisión de un recurso:','["Que se presente en una oficina de Correos sin sello de fechas", "Que el recurrente no esté asistido de abogado", "Haber transcurrido el plazo para su interposición", "Que el recurrente haya calificado erróneamente el recurso, aunque se deduzca su verdadero carácter"]'::jsonb,2,'Art. 116 d) Ley 39/2015','Otras causas: incompetencia, falta de legitimación, acto no recurrible y carecer manifiestamente de fundamento.',null),
('adm-cm:14-38ae6fb91c','adm-cm',14,'Transcurridos tres meses desde la interposición del recurso extraordinario de revisión sin resolución:','["Caducará el procedimiento", "Se entenderá desestimado, quedando expedita la vía contencioso-administrativa", "Se entenderá estimado, salvo que el recurso se base en un error de hecho resultante de los documentos del expediente", "Se prorrogará otros tres meses"]'::jsonb,1,'Art. 126.3 Ley 39/2015','El silencio en el recurso extraordinario de revisión es desestimatorio.',null),
('adm-cm:14-837c99d90c','adm-cm',14,'El error o la ausencia de calificación del recurso por parte del recurrente:','["No será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter", "Obliga a presentarlo de nuevo", "Solo puede subsanarse si el recurrente está asistido de abogado", "Determina su inadmisión, salvo que el recurrente lo subsane en el plazo de diez días desde el requerimiento"]'::jsonb,0,'Art. 115.2 Ley 39/2015','Lo importante es que se deduzca el verdadero carácter del recurso.',null),
('adm-cm:14-d8dbb7ec35','adm-cm',14,'Los vicios y defectos que hagan anulable un acto:','["Solo pueden alegarse en vía judicial", "No podrán ser alegados por quienes los hubieren causado", "Determinan siempre la nulidad de pleno derecho del acto, aunque no causen indefensión", "Pueden alegarse por cualquier persona, incluidos quienes los hubieran causado"]'::jsonb,1,'Art. 115.3 Ley 39/2015','Quien causó el vicio no puede alegarlo.',null),
('adm-cm:14-384dfa49f2','adm-cm',14,'El recurso de alzada se interpone ante:','["El Tribunal Superior de Justicia de la Comunidad Autónoma", "El Consejo de Estado", "El órgano superior jerárquico del que dictó el acto, pudiendo presentarse ante el que lo dictó o ante el competente para resolver", "El mismo órgano que dictó el acto, que lo resuelve en el plazo de un mes, sin que pueda presentarse ante el superior jerárquico ni ante otro órgano"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Lo resuelve el superior jerárquico; puede presentarse ante cualquiera de los dos.',null),
('adm-cm:14-81833e0313','adm-cm',14,'¿Cuál de las siguientes NO es causa de inadmisión del art. 116?','["Tratarse de un acto no susceptible de recurso", "Carecer de legitimación el recurrente", "Carecer el recurso manifiestamente de fundamento", "Que el recurso se haya calificado erróneamente"]'::jsonb,3,'Art. 116 Ley 39/2015','El error en la calificación no impide la tramitación (art. 115.2).',null),
('adm-cm:14-1ddbf1bb31','adm-cm',14,'Si existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano que resuelve el recurso:','["Dictará resolución favorable", "Inadmitirá el recurso", "Ordenará la retroacción del procedimiento al momento en que el vicio fue cometido", "Anulará todo el expediente y ordenará iniciar uno nuevo desde el principio"]'::jsonb,2,'Art. 119.2 Ley 39/2015','Se ordena retrotraer el procedimiento al momento del vicio.',null),
('adm-cm:14-1e868695fe','adm-cm',14,'Cuando deban resolverse una pluralidad de recursos derivados de un mismo acto y se haya interpuesto recurso judicial contra una resolución administrativa o contra el correspondiente acto presunto:','["El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial", "Deberá inadmitir todos los recursos pendientes", "Deberá estimar todos los recursos", "Deberá resolver todos los recursos en el plazo ordinario, sin esperar al pronunciamiento judicial, para no perjudicar a los interesados que no han acudido a los tribunales"]'::jsonb,0,'Art. 120.1 Ley 39/2015','El órgano puede suspender el plazo hasta que haya pronunciamiento judicial.',null),
('adm-cm:14-9edf429620','adm-cm',14,'El recurso extraordinario de revisión se interpone contra:','["Los actos que no ponen fin a la vía administrativa, en cualquier momento", "Los actos firmes en vía administrativa, cuando concurra alguna de las circunstancias del art. 125.1", "Cualquier acto de trámite", "Las disposiciones de carácter general, cuando concurra alguna de las circunstancias del art. 125.1"]'::jsonb,1,'Art. 113 Ley 39/2015','Procede contra actos firmes en vía administrativa en los casos del art. 125.1.',null),
('adm-cm:14-f7b3efaff2','adm-cm',14,'Es causa del recurso extraordinario de revisión:','["Que haya transcurrido el plazo para interponer el recurso de alzada sin haberlo hecho, por causa no imputable al interesado", "Que el interesado cambie de opinión", "Que el acto sea desfavorable y el interesado aporte cualquier documento nuevo, aunque no evidencie error alguno en la resolución", "Que aparezcan documentos de valor esencial para la resolución que evidencien el error de la resolución recurrida"]'::jsonb,3,'Art. 125.1 b) Ley 39/2015','Las causas son: error de hecho, documentos esenciales nuevos, documentos o testimonios falsos declarados en sentencia firme y conducta punible declarada en sentencia firme.',null),
('adm-cm:14-5742df1c51','adm-cm',14,'El recurso de casación podrá ser admitido cuando presente:','["Interés casacional objetivo para la formación de jurisprudencia", "La conformidad de ambas partes", "Una cuantía superior a 600.000 euros, sin necesidad de interés casacional", "Un error de hecho del juez"]'::jsonb,0,'Art. 88.1 Ley 29/1998','La admisión se basa en el interés casacional objetivo.',null),
('adm-cm:14-b0fa377d90','adm-cm',14,'Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia conocen en segunda instancia de:','["Los recursos contra actos de los Ministros y Secretarios de Estado", "Los recursos de casación autonómicos", "Los recursos contra actos del Consejo de Ministros y de las Comisiones Delegadas del Gobierno", "Los recursos de apelación contra sentencias y autos de los Juzgados de lo Contencioso-administrativo"]'::jsonb,3,'Art. 10.2 Ley 29/1998','En única instancia conocen, entre otros, de las disposiciones generales autonómicas y locales. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('adm-cm:14-83481bac01','adm-cm',14,'El recurso de casación se preparará ante la Sala que dictó la resolución recurrida en el plazo de:','["Dos meses desde su notificación", "Quince días desde su notificación", "Treinta días desde su notificación", "Diez días desde su notificación"]'::jsonb,2,'Art. 89.1 Ley 29/1998','La casación se prepara en treinta días.',null),
('adm-cm:14-5b7ce09838','adm-cm',14,'Según el art. 19.1 h), cualquier ciudadano puede actuar ante la jurisdicción contencioso-administrativa:','["Mediante la acción popular, en los casos expresamente previstos por las leyes", "Solo si es funcionario o acredita un interés legítimo directo y personal en el asunto", "Solo a través del Defensor del Pueblo", "Mediante la acción popular, en cualquier caso, sin necesidad de previsión legal ni de interés propio"]'::jsonb,0,'Art. 19.1 h) Ley 29/1998','La acción popular solo cabe en los casos previstos legalmente.',null),
('adm-cm:14-4cb50c4c1b','adm-cm',14,'Los recursos contra disposiciones generales se consideran, a efectos de cuantía:','["De cuantía indeterminada", "De cuantía de 30.000 euros", "De cuantía mínima", "Sin efectos de cuantía"]'::jsonb,0,'Art. 42.2 Ley 29/1998','Se reputan de cuantía indeterminada.',null),
('adm-cm:14-c91722fcbd','adm-cm',14,'Cuando se adopten medidas cautelares antes de interponer el recurso, el interesado deberá pedir su ratificación al interponerlo, en el plazo de:','["Un mes desde su notificación", "Dos meses desde su notificación", "Cinco días desde su notificación", "Diez días desde su notificación"]'::jsonb,3,'Art. 136.2 Ley 29/1998','Si no se ratifican, las medidas quedan sin efecto.',null),
('adm-cm:14-ddf1b5e582','adm-cm',14,'NO pueden interponer recurso contencioso-administrativo contra la actividad de una Administración pública:','["Los sindicatos", "Las personas jurídicas", "Las asociaciones de consumidores y usuarios inscritas en el registro correspondiente, salvo que una ley lo autorice", "Los órganos de la misma, salvo que una ley lo autorice expresamente"]'::jsonb,3,'Art. 20 a) Ley 29/1998','Los órganos de una Administración no pueden recurrir la actividad de esta salvo autorización legal expresa.',null),
('adm-cm:14-31e298e8c7','adm-cm',14,'En sus actuaciones ante órganos unipersonales, las partes:','["No necesitan abogado en ningún caso", "Deben actuar siempre representadas por Procurador, y la asistencia de Abogado solo es necesaria cuando la cuantía del asunto exceda de 30.000 euros", "Solo pueden actuar por sí mismas, sin representación", "Podrán conferir su representación a un Procurador y serán asistidas, en todo caso, por Abogado"]'::jsonb,3,'Art. 23.1 Ley 29/1998','Ante órganos colegiados deben conferir representación a Procurador y ser asistidas por Abogado.',null),
('adm-cm:14-92d4507aa9','adm-cm',14,'En los litigios entre Administraciones, el requerimiento previo deberá producirse en el plazo de:','["Un mes", "Diez días", "Seis meses", "Dos meses"]'::jsonb,3,'Art. 44.2 Ley 29/1998','Se entiende rechazado si no se contesta en el mes siguiente a su recepción.',null),
('adm-cm:14-1e88d41e38','adm-cm',14,'Corresponde al orden contencioso-administrativo conocer de las cuestiones relativas a:','["Los conflictos de jurisdicción entre juzgados y Administración", "Los despidos del personal laboral", "Los delitos cometidos por funcionarios", "La responsabilidad patrimonial de las Administraciones públicas"]'::jsonb,3,'Art. 2 e) Ley 29/1998','El art. 2 incluye, entre otras, la responsabilidad patrimonial y los contratos administrativos.',null),
('adm-cm:14-e799b4c635','adm-cm',14,'El plazo para interponer el recurso de lesividad es de:','["Dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad", "Cuatro años desde que se dictó el acto", "Seis meses desde la notificación del acto", "Dos meses a contar desde el día siguiente a la notificación del acto lesivo"]'::jsonb,0,'Art. 46.5 Ley 29/1998','El recurso de lesividad se interpone en dos meses desde la declaración.',null),
('adm-cm:14-32a5798d81','adm-cm',14,'Si el acto impugnado no es expreso, el plazo para interponer recurso contencioso-administrativo es de:','["Un mes", "Un año", "Dos meses", "Seis meses"]'::jsonb,3,'Art. 46.1 Ley 29/1998','Para actos expresos el plazo es de dos meses.','nov. 2024 · 1.er ejercicio'),
('adm-cm:14-16ceb68f77','adm-cm',14,'La sentencia en el procedimiento contencioso-administrativo ordinario se dictará en el plazo de:','["Un mes desde que el pleito haya sido declarado concluso", "Dos meses desde la vista", "Veinte días desde la contestación a la demanda", "Diez días desde que el pleito haya sido declarado concluso"]'::jsonb,3,'Art. 67.1 Ley 29/1998','Diez días desde que el pleito queda concluso.',null),
('adm-cm:14-ed1bad765a','adm-cm',14,'Según el art. 3 de la Ley 29/1998, NO corresponde al orden contencioso-administrativo:','["Los contratos administrativos", "La responsabilidad patrimonial de las Administraciones", "Los actos de las Entidades locales", "El recurso contencioso-disciplinario militar"]'::jsonb,3,'Art. 3 b) Ley 29/1998','Tampoco los conflictos de jurisdicción y los conflictos de atribuciones.',null),
('adm-cm:14-7530e8bdf5','adm-cm',14,'Si la Administración no ejecuta sus actos firmes, los afectados pueden solicitar su ejecución y, si no se produce en el plazo de un mes, interponer recurso que se tramitará por:','["El procedimiento ordinario con jurado", "El procedimiento de derechos fundamentales", "El procedimiento abreviado", "La cuestión de ilegalidad"]'::jsonb,2,'Art. 29.2 Ley 29/1998','Se tramita por el procedimiento abreviado del art. 78.',null),
('adm-cm:14-3c29e84430','adm-cm',14,'El plazo para practicar la prueba en el procedimiento ordinario es de:','["Dos meses", "Treinta días", "Quince días", "Diez días"]'::jsonb,1,'Art. 60.4 Ley 29/1998','La prueba se practica en un plazo de treinta días.',null),
('adm-cm:14-031126acdb','adm-cm',14,'Cuando la Administración autora de un acto pretenda demandar su anulación ante la jurisdicción contencioso-administrativa, deberá previamente:','["Notificarlo de nuevo a los interesados", "Declararlo lesivo para el interés público", "Revocarlo en vía administrativa", "Solicitar dictamen favorable del Consejo de Estado"]'::jsonb,1,'Art. 43 Ley 29/1998','Es el recurso de lesividad.',null),
('adm-cm:14-11ad83be65','adm-cm',14,'Según el art. 105.1, respecto de la ejecución de las sentencias:','["No podrá suspenderse el cumplimiento ni declararse la inejecución total o parcial del fallo", "Podrá suspenderse el cumplimiento cuando lo solicite la Administración condenada por razones de interés público, sin intervención del órgano judicial", "La Administración puede suspenderla libremente", "Podrá declararse la inejecución parcial del fallo si lo autoriza el Gobierno"]'::jsonb,0,'Art. 105.1 Ley 29/1998','Solo cabe imposibilidad material o legal por el cauce del art. 105.2.',null),
('adm-cm:14-99698e3df3','adm-cm',14,'En el procedimiento de protección de derechos fundamentales, la demanda se formalizará en el plazo de:','["Quince días", "Ocho días", "Diez días", "Veinte días"]'::jsonb,1,'Art. 118 Ley 29/1998','El plazo de demanda es de ocho días.',null),
('adm-cm:14-b270fc78fb','adm-cm',14,'La declaración de incompetencia de un órgano contencioso-administrativo adopta la forma de:','["Sentencia", "Diligencia de ordenación", "Auto", "Providencia"]'::jsonb,2,'Art. 7.3 Ley 29/1998','Se remiten las actuaciones al órgano competente y las partes tienen diez días para comparecer ante él.',null),
('adm-cm:14-2b3048be08','adm-cm',14,'La jurisdicción contencioso-administrativa es:','["Prorrogable por decisión del Gobierno", "Voluntaria", "Prorrogable por acuerdo de las partes", "Improrrogable"]'::jsonb,3,'Art. 5.1 Ley 29/1998','Los órganos apreciarán de oficio la falta de jurisdicción.',null),
('adm-cm:14-4dea40df87','adm-cm',14,'La Sala de lo Contencioso-administrativo del Tribunal Supremo conoce en única instancia de los recursos contra actos y disposiciones de:','["El Consejo de Ministros", "Los Alcaldes", "Los Delegados del Gobierno", "Los Consejeros de las Comunidades Autónomas"]'::jsonb,0,'Art. 12.1 a) Ley 29/1998','También del CGPJ y del Fiscal General del Estado, entre otros.',null),
('adm-cm:14-12f80cbc05','adm-cm',14,'Los Juzgados de lo Contencioso-administrativo conocen de los recursos contra actos de la Administración autonómica en materia de responsabilidad patrimonial cuya cuantía no exceda de:','["100.000 euros", "60.000 euros", "30.050 euros", "18.000 euros"]'::jsonb,2,'Art. 8.2 c) Ley 29/1998','También de sanciones con multa no superior a 60.000 euros, entre otros supuestos. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('adm-cm:14-407fc96d19','adm-cm',14,'En caso de inactividad, si la Administración no da cumplimiento a lo reclamado o no llega a un acuerdo con los interesados, estos pueden recurrir si transcurre desde la reclamación un plazo de:','["Seis meses", "Tres meses", "Un mes", "Diez días"]'::jsonb,1,'Art. 29.1 Ley 29/1998','Pasados tres meses desde la reclamación, cabe recurso contra la inactividad.',null),
('adm-cm:14-89791c9010','adm-cm',14,'El recurso de apelación contra sentencias es admisible, salvo que la ley disponga otra cosa:','["Sin efectos", "En ambos efectos", "Solo en un efecto", "Solo en efecto devolutivo"]'::jsonb,1,'Art. 83.1 Ley 29/1998','La apelación no impide la ejecución provisional de la sentencia (art. 84).',null),
('adm-cm:14-6fc22a0e4c','adm-cm',14,'La Administración debe remitir el expediente administrativo al juzgado o tribunal en el plazo improrrogable de:','["Un mes natural", "Diez días hábiles desde la reclamación", "Veinte días", "Dos meses"]'::jsonb,2,'Art. 48.3 Ley 29/1998','El expediente se remite en veinte días.',null),
('adm-cm:14-30500fd045','adm-cm',14,'En el procedimiento abreviado, el juez dictará sentencia en el plazo de:','["Veinte días", "Un mes desde la presentación de la demanda", "Diez días desde la celebración de la vista", "Cinco días desde la presentación de la demanda"]'::jsonb,2,'Art. 78.20 Ley 29/1998','Se dicta en diez días desde la vista.',null),
('adm-cm:14-14ad11945a','adm-cm',14,'En caso de vía de hecho, el interesado puede formular requerimiento a la Administración y, si no es atendido en el plazo de:','["Tres meses, podrá interponer recurso de alzada ante el superior jerárquico", "Un mes, podrá interponer recurso de alzada ante el superior jerárquico del órgano", "Diez días, podrá deducir directamente recurso contencioso-administrativo", "Veinte días"]'::jsonb,2,'Art. 30 Ley 29/1998','Si el requerimiento no se formula o no se atiende en diez días, cabe recurso directo.',null),
('adm-cm:14-be66159b68','adm-cm',14,'Las decisiones que adopte el juez sobre cuestiones prejudiciales o incidentales no pertenecientes al orden contencioso-administrativo:','["Deben confirmarse por el Tribunal Supremo", "Vinculan a los tribunales penales", "Producen efectos de cosa juzgada en todos los órdenes", "No producirán efectos fuera del proceso en que se dicten"]'::jsonb,3,'Art. 4.2 Ley 29/1998','Solo producen efectos en el proceso en que se dictan.',null),
('adm-cm:14-391d9b16f8','adm-cm',14,'Los Juzgados Centrales de lo Contencioso-administrativo conocen, entre otros, de los recursos contra actos de los organismos públicos con competencia en:','["Una Comunidad Autónoma", "Un solo municipio", "Una sola provincia o un solo partido judicial", "Todo el territorio nacional"]'::jsonb,3,'Art. 9.1 c) Ley 29/1998','Conocen en primera o única instancia de los recursos contra disposiciones y actos de esos organismos en los términos del art. 9. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('adm-cm:14-3a9332f481','adm-cm',14,'Las medidas cautelares podrán acordarse cuando la ejecución del acto o la aplicación de la disposición:','["Pudieran hacer perder su finalidad legítima al recurso, previa valoración de todos los intereses en conflicto", "Lo pida el Ministerio Fiscal o la Administración demandada, sin necesidad de valorar los intereses en conflicto ni la finalidad del recurso", "Haya sido recurrida en alzada o en reposición y no se haya resuelto el recurso", "Cause cualquier molestia o perjuicio al recurrente, aunque no haga perder su finalidad al recurso ni se valoren los intereses en conflicto"]'::jsonb,0,'Art. 130.1 Ley 29/1998','Pueden denegarse si causan perturbación grave de los intereses generales o de tercero.',null),
('adm-cm:14-1dcd120b04','adm-cm',14,'La sentencia estimará el recurso contencioso-administrativo cuando la disposición o el acto incurran en:','["Defectos de forma que produzcan indefensión, pero no la desviación de poder", "Cualquier infracción del ordenamiento jurídico, incluso la desviación de poder", "Vulneración de derechos fundamentales y libertades públicas susceptibles de amparo constitucional", "Causas de nulidad de pleno derecho, pero no en meros vicios de anulabilidad del acto"]'::jsonb,1,'Art. 70.2 Ley 29/1998','Si se ajusta a Derecho, el recurso se desestima.',null),
('adm-cm:14-851ea8c77c','adm-cm',14,'En los recursos con estimación parcial de las pretensiones, como regla general:','["Las paga siempre el recurrente que haya visto rechazada cualquiera de sus pretensiones", "Cada parte abonará las costas causadas a su instancia y las comunes por mitad", "Las paga la parte cuyas pretensiones hayan sido desestimadas en mayor medida, salvo que el órgano aprecie temeridad", "Las paga siempre la Administración demandada"]'::jsonb,1,'Art. 139.1 Ley 29/1998','Salvo que el órgano aprecie mala fe o temeridad en alguna de las partes.',null),
('adm-cm:14-419fea0e27','adm-cm',14,'La cuestión de ilegalidad se plantea por el juez o tribunal mediante auto que deberá dictarse:','["Antes de dictar sentencia, dentro del plazo para dictarla y previa audiencia de las partes por diez días", "En el plazo de un mes desde la firmeza de la sentencia", "Dentro de los cinco días siguientes a que conste en las actuaciones la firmeza de la sentencia", "En el plazo de dos meses"]'::jsonb,2,'Art. 123.1 Ley 29/1998','Se plantea en cinco días desde la firmeza de la sentencia.',null),
('adm-cm:14-302c5cb564','adm-cm',14,'La Sala de lo Contencioso-administrativo de la Audiencia Nacional conoce en única instancia de los recursos contra:','["Los actos de los Ayuntamientos de municipios de gran población", "Los actos del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y del Consejo General del Poder Judicial, en todo caso", "Las disposiciones generales y los actos de los Ministros y Secretarios de Estado, en los términos del art. 11", "Las sentencias de los TSJ"]'::jsonb,2,'Art. 11.1 a) Ley 29/1998','También conoce de las apelaciones contra resoluciones de los Juzgados Centrales. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('adm-cm:14-c18db35b09','adm-cm',14,'En el procedimiento para la protección de los derechos fundamentales, la sentencia se dictará en el plazo de:','["Diez días desde que las actuaciones queden conclusas", "Un mes", "Veinte días desde la contestación", "Cinco días desde que las actuaciones queden conclusas"]'::jsonb,3,'Art. 121.1 Ley 29/1998','Es un procedimiento preferente y sumario.',null),
('adm-cm:14-2b6a04baf2','adm-cm',14,'En la imposición de costas, la cantidad a satisfacer no podrá exceder de:','["6.000 euros por cada parte", "La cuantía total del proceso", "La mitad de la cuantía del proceso, salvo circunstancias que lo justifiquen", "La tercera parte de la cuantía del proceso, salvo circunstancias que lo justifiquen"]'::jsonb,3,'Art. 139.4 Ley 29/1998','Las pretensiones de cuantía indeterminada se valoran en 18.000 euros a estos efectos.',null),
('adm-cm:14-16eadb53d0','adm-cm',14,'Con carácter general, es competente territorialmente el órgano jurisdiccional en cuya circunscripción:','["Lo elija libremente el recurrente en todo caso", "Tenga su domicilio el recurrente, en todo caso, cualquiera que sea la materia", "Tenga su sede el órgano que hubiera dictado la disposición o el acto impugnado", "Se haya publicado el acto"]'::jsonb,2,'Art. 14.1 Ley 29/1998','Es la regla primera del art. 14.',null),
('adm-cm:14-0db7ad6bc8','adm-cm',14,'NO es admisible el recurso contencioso-administrativo respecto de:','["Los actos que sean reproducción de otros anteriores definitivos y firmes", "Los actos que pongan fin a la vía administrativa", "La inactividad de la Administración", "Las actuaciones materiales de la Administración que constituyan vía de hecho"]'::jsonb,0,'Art. 28 Ley 29/1998','Tampoco contra los actos confirmatorios de actos consentidos por no haber sido recurridos en tiempo y forma.',null),
('adm-cm:15-f7b13237e0','adm-cm',15,'Los daños causados por el personal al servicio de la Administración:','["Los particulares los reclaman directamente al empleado que los causó", "Los particulares los reclaman directamente a la Administración correspondiente", "Los particulares los reclaman al empleado y, subsidiariamente, a la Administración", "Solo pueden reclamarse por vía penal, como responsabilidad civil derivada del delito"]'::jsonb,1,'Art. 36.1 Ley 40/2015','Los particulares exigen directamente a la Administración las indemnizaciones por los daños causados por sus autoridades y personal.',null),
('adm-cm:15-354e895a28','adm-cm',15,'Cuando la Administración ha indemnizado a un particular, exige de oficio a su personal la responsabilidad en que haya incurrido por:','["Cualquier error", "Culpa leve", "Dolo, o culpa o negligencia graves", "Nada: no puede repetir contra su personal"]'::jsonb,2,'Art. 36.2 Ley 40/2015','Exige de oficio, en vía administrativa, la responsabilidad por dolo, o culpa o negligencia graves.',null),
('adm-cm:15-9106bf8537','adm-cm',15,'Según la Ley 40/2015, ¿cuándo tienen derecho los particulares a ser indemnizados por las Administraciones?','["Solo por las lesiones derivadas del funcionamiento anormal de los servicios, nunca del normal", "Por cualquier daño, incluida la fuerza mayor", "Solo cuando un tribunal declare la culpa del funcionario", "Por toda lesión consecuencia del funcionamiento normal o anormal de los servicios públicos"]'::jsonb,3,'Art. 32.1 Ley 40/2015','Hay derecho a indemnización por toda lesión consecuencia del funcionamiento normal o anormal de los servicios públicos, salvo fuerza mayor o deber jurídico de soportarlo.',null),
('adm-cm:15-95af1360b0','adm-cm',15,'¿Presupone por sí misma derecho a indemnización la anulación de un acto administrativo?','["No", "Sí, en todo caso", "Sí, si el acto era nulo de pleno derecho", "Sí, si la anulación es en vía judicial"]'::jsonb,0,'Art. 32.1 Ley 40/2015','La anulación en vía administrativa o contencioso-administrativa no presupone, por sí misma, derecho a la indemnización.',null),
('adm-cm:15-d65a7ff551','adm-cm',15,'¿Qué características debe tener el daño alegado según la Ley 40/2015?','["Directo, superior a 600 euros y personal", "Cierto, futuro y compartido por la colectividad", "Efectivo, evaluable económicamente e individualizado", "Grave, permanente y probado por sentencia"]'::jsonb,2,'Art. 32.2 Ley 40/2015','El daño habrá de ser efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas.',null),
('adm-cm:15-0124ec34f1','adm-cm',15,'¿Por qué ley se rige la responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia?','["Por la Ley Orgánica del Poder Judicial", "Por la Ley 40/2015", "Por la Ley 39/2015", "Por la Ley de la Jurisdicción Contencioso-administrativa"]'::jsonb,0,'Art. 32.7 Ley 40/2015','Se rige por la Ley Orgánica 6/1985, del Poder Judicial.',null),
('adm-cm:15-c83ebe33a8','adm-cm',15,'Si el daño deriva de fórmulas conjuntas de actuación entre varias Administraciones, ¿cómo responden frente al particular?','["Responde la de mayor población", "De forma mancomunada, según su participación", "Responde solo la que tramitó el expediente", "De forma solidaria"]'::jsonb,3,'Art. 33.1 Ley 40/2015','Las Administraciones intervinientes responderán frente al particular, en todo caso, de forma solidaria.',null),
('adm-cm:15-4f7c2eacd4','adm-cm',15,'En la responsabilidad concurrente, a falta de estatutos, ¿qué Administración es competente para tramitar el procedimiento?','["La de ámbito territorial más amplio", "La primera que reciba la reclamación", "La de mayor participación en la financiación del servicio", "La que designe el particular en su reclamación"]'::jsonb,2,'Art. 33.3 Ley 40/2015','En defecto de estatutos o reglas, la competencia corresponde a la Administración con mayor participación en la financiación del servicio.',null),
('adm-cm:15-a9babd7409','adm-cm',15,'¿Son indemnizables los daños que no se pudieron prever o evitar según el estado de la ciencia o de la técnica?','["No, sin perjuicio de las prestaciones que puedan establecer las leyes", "Solo si se trata de daños personales", "Sí, en todo caso, porque la responsabilidad patrimonial de la Administración es objetiva", "Sí, si el daño supera los 50.000 euros"]'::jsonb,0,'Art. 34.1 Ley 40/2015','No son indemnizables los daños derivados de hechos que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica.',null),
('adm-cm:15-e5acadf50e','adm-cm',15,'¿Con referencia a qué día se calcula la cuantía de la indemnización?','["Al día del pago efectivo de la indemnización", "Al día de la resolución del procedimiento", "Al día en que se presentó la reclamación", "Al día en que la lesión efectivamente se produjo"]'::jsonb,3,'Art. 34.3 Ley 40/2015','Se calcula con referencia al día de la lesión, sin perjuicio de su actualización con el Índice de Garantía de la Competitividad y los intereses de demora.',null),
('adm-cm:15-93aebfbb0f','adm-cm',15,'¿Con qué índice se actualiza la cuantía de la indemnización por responsabilidad patrimonial?','["El Índice de Garantía de la Competitividad", "El índice de revisión de precios de los contratos públicos", "El Índice de Precios de Consumo", "El interés legal del dinero"]'::jsonb,0,'Art. 34.3 Ley 40/2015','Se actualiza con arreglo al Índice de Garantía de la Competitividad fijado por el INE.',null),
('adm-cm:15-78fbc9e54b','adm-cm',15,'¿Puede sustituirse la indemnización por una compensación en especie?','["Sí, por decisión unilateral de la Administración cuando lo considere más conveniente para el interés público", "No, siempre debe pagarse en dinero", "Solo en los daños a bienes inmuebles", "Sí, cuando sea más adecuado y convenga al interés público, con acuerdo del interesado"]'::jsonb,3,'Art. 34.4 Ley 40/2015','Puede sustituirse por una compensación en especie o pagos periódicos si es más adecuado, conviene al interés público y hay acuerdo con el interesado.',null),
('adm-cm:15-b9416ba0b8','adm-cm',15,'¿A quién exigen los particulares la indemnización por los daños causados por el personal al servicio de la Administración?','["A la aseguradora del funcionario", "Al funcionario y a la Administración solidariamente", "Directamente a la Administración Pública correspondiente", "Directamente a la autoridad o funcionario causante"]'::jsonb,2,'Art. 36.1 Ley 40/2015','Los particulares exigirán directamente a la Administración las indemnizaciones por los daños causados por las autoridades y personal a su servicio.',null),
('adm-cm:15-93e42a58f2','adm-cm',15,'¿Cuándo debe la Administración exigir la responsabilidad a su personal tras indemnizar al lesionado?','["Solo si hay condena penal firme", "Cuando la indemnización supere los 50.000 euros", "Siempre que haya indemnizado, sea cual sea la culpa", "Cuando haya incurrido en dolo, o culpa o negligencia graves"]'::jsonb,3,'Art. 36.2 Ley 40/2015','Exigirá de oficio la responsabilidad en que hubieran incurrido por dolo, o culpa o negligencia graves.',null),
('adm-cm:15-cf3451bfb9','adm-cm',15,'En el procedimiento para exigir responsabilidad al personal, ¿qué plazo de alegaciones prevé la Ley 40/2015?','["Quince días", "Un mes", "Cinco días", "Diez días"]'::jsonb,0,'Art. 36.4 Ley 40/2015','El procedimiento incluye alegaciones durante quince días, prueba quince días, audiencia diez días, propuesta en cinco y resolución en cinco.',null),
('adm-cm:15-25fd6124c7','adm-cm',15,'¿Suspende la exigencia de responsabilidad penal del personal el procedimiento de responsabilidad patrimonial?','["Sí, si lo solicita el funcionario imputado", "Sí, en todo caso, hasta que se dicte sentencia firme en el orden jurisdiccional penal sobre los hechos", "No, salvo que los hechos penales sean necesarios para fijar la responsabilidad patrimonial", "No, en ningún caso"]'::jsonb,2,'Art. 37.2 Ley 40/2015','No suspende los procedimientos salvo que la determinación de los hechos en el orden penal sea necesaria para fijar la responsabilidad patrimonial.',null),
('adm-cm:15-4aba6497c3','adm-cm',15,'¿Cuándo prescribe el derecho a reclamar responsabilidad patrimonial según la Ley 39/2015?','["A los cuatro años del hecho lesivo", "A los seis meses del hecho lesivo", "Al año de producirse el hecho o acto que motive la indemnización", "A los dos años desde que el perjudicado tuvo conocimiento efectivo del daño causado"]'::jsonb,2,'Art. 67.1 Ley 39/2015','El derecho a reclamar prescribe al año de producido el hecho o el acto que motive la indemnización o de manifestarse su efecto lesivo.',null),
('adm-cm:15-99c8bfc186','adm-cm',15,'En daños de carácter físico o psíquico, ¿desde cuándo se computa el plazo para reclamar?','["Desde el día del accidente", "Desde la primera asistencia sanitaria", "Desde que se emite el alta laboral", "Desde la curación o la determinación del alcance de las secuelas"]'::jsonb,3,'Art. 67.1 Ley 39/2015','En daños físicos o psíquicos, el plazo empieza a computarse desde la curación o la determinación del alcance de las secuelas.',null),
('adm-cm:15-3ed09ea5a7','adm-cm',15,'¿Qué plazo máximo tiene el servicio causante de la lesión para emitir su informe preceptivo?','["Diez días", "Un mes", "Quince días", "Cinco días"]'::jsonb,0,'Art. 81.1 Ley 39/2015','El informe del servicio cuyo funcionamiento haya ocasionado la lesión es preceptivo y no puede exceder de diez días.',null),
('adm-cm:15-6d831d3389','adm-cm',15,'¿A partir de qué cuantía es preceptivo el dictamen del Consejo de Estado o del órgano consultivo autonómico?','["6.000 euros o más", "100.000 euros o más", "50.000 euros o más", "30.000 euros o más"]'::jsonb,2,'Art. 81.2 Ley 39/2015','El dictamen es preceptivo cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros.',null),
('adm-cm:15-934ea378a8','adm-cm',15,'¿En qué plazo debe emitirse el dictamen del órgano consultivo en un procedimiento de responsabilidad patrimonial?','["Un mes", "Diez días", "Tres meses", "Dos meses"]'::jsonb,3,'Art. 81.2 Ley 39/2015','El dictamen se emitirá en el plazo de dos meses.',null),
('adm-cm:15-5aac8504dd','adm-cm',15,'Si transcurren seis meses sin resolución expresa en un procedimiento de responsabilidad patrimonial, ¿cómo puede entenderse?','["Favorable a la indemnización solicitada", "Contraria a la indemnización del particular", "Caducado el procedimiento", "Favorable si no superaba los 50.000 euros"]'::jsonb,1,'Art. 91.3 Ley 39/2015','Transcurridos seis meses sin resolución expresa podrá entenderse que la resolución es contraria a la indemnización.',null),
('adm-cm:15-072bb0362f','adm-cm',15,'En la Administración General del Estado, ¿quién resuelve, con carácter general, los procedimientos de responsabilidad patrimonial?','["El ministro respectivo", "El Consejo de Ministros en todo caso", "El subsecretario del departamento", "El Consejo de Estado"]'::jsonb,0,'Art. 92 Ley 39/2015','Los resuelve el ministro respectivo o el Consejo de Ministros en los casos del art. 32.3 de la Ley 40/2015 o cuando una ley lo disponga.',null),
('adm-cm:15-57a4e9444f','adm-cm',15,'¿Sobre qué debe pronunciarse necesariamente la resolución de un procedimiento de responsabilidad patrimonial?','["Sobre la sanción que corresponda al responsable", "Sobre la relación de causalidad y, en su caso, la valoración del daño y la indemnización", "Sobre la culpa del funcionario causante del daño", "Solo sobre la cuantía reclamada por el interesado y sobre la forma y el plazo de pago de la indemnización"]'::jsonb,1,'Art. 91.2 Ley 39/2015','Debe pronunciarse sobre la existencia o no de relación de causalidad y, en su caso, sobre la valoración del daño y la cuantía de la indemnización.',null),
('adm-cm:16-b48d8ecf18','adm-cm',16,'Según la Ley 40/2015, ¿cuándo puede ejercerse la potestad sancionadora?','["Cuando lo prevea cualquier norma reglamentaria", "Cuando lo autorice una instrucción del superior jerárquico", "Cuando haya sido expresamente reconocida por una norma con rango de ley", "Cuando lo acuerde el órgano competente por razón de la materia mediante resolución motivada"]'::jsonb,2,'Art. 25.1 Ley 40/2015','La potestad sancionadora se ejerce cuando haya sido expresamente reconocida por una norma con rango de ley.',null),
('adm-cm:16-bd23ea1480','adm-cm',16,'¿Se aplica el capítulo de la Ley 40/2015 sobre potestad sancionadora a la potestad disciplinaria sobre el personal?','["Sí, sea cual sea la naturaleza jurídica de la relación de empleo", "Solo al personal laboral", "Solo al personal funcionario de carrera", "No, la potestad disciplinaria se rige solo por el TREBEP"]'::jsonb,0,'Art. 25.3 Ley 40/2015','Las disposiciones del capítulo son extensivas a la potestad disciplinaria sobre el personal, cualquiera que sea la naturaleza de su relación de empleo.',null),
('adm-cm:16-e4babe2c4b','adm-cm',16,'¿A quién NO se aplica el capítulo de potestad sancionadora de la Ley 40/2015?','["A las personas jurídicas", "A los extranjeros residentes", "A los funcionarios interinos y al personal eventual de confianza de los altos cargos", "A quienes estén vinculados a la Administración por contratos del sector público"]'::jsonb,3,'Art. 25.4 Ley 40/2015','No se aplica respecto de quienes estén vinculados por relaciones reguladas por la legislación de contratos del sector público o patrimonial.',null),
('adm-cm:16-cc6e25a497','adm-cm',16,'¿Cuándo tienen efecto retroactivo las disposiciones sancionadoras?','["Solo respecto de las sanciones ya cumplidas", "Cuando lo disponga la propia norma, aunque perjudique", "Cuando favorezcan al presunto infractor o al infractor", "Nunca, por el principio de irretroactividad"]'::jsonb,2,'Art. 26.2 Ley 40/2015','Producen efecto retroactivo en cuanto favorezcan al presunto infractor o al infractor, incluso respecto de sanciones pendientes de cumplimiento.',null),
('adm-cm:16-c85f4455d1','adm-cm',16,'¿Cómo clasifica la ley las infracciones administrativas según la Ley 40/2015?','["En simples, cualificadas y continuadas", "En leves y graves", "En faltas y delitos administrativos", "En leves, graves y muy graves"]'::jsonb,3,'Art. 27.1 Ley 40/2015','Las infracciones administrativas se clasificarán por la ley en leves, graves y muy graves.',null),
('adm-cm:16-45d4c4c12c','adm-cm',16,'¿Pueden aplicarse por analogía las normas que definen infracciones y sanciones?','["No", "Sí, cuando exista identidad de razón", "Sí, si favorecen a la Administración", "Solo en el ámbito local"]'::jsonb,0,'Art. 27.4 Ley 40/2015','Las normas definidoras de infracciones y sanciones no son susceptibles de aplicación analógica.',null),
('adm-cm:16-695c91aa8f','adm-cm',16,'¿Qué pueden hacer los reglamentos de desarrollo respecto del cuadro de infracciones y sanciones?','["Crear nuevas infracciones leves", "Introducir especificaciones o graduaciones sin crear nuevas infracciones ni sanciones", "Aumentar la cuantía máxima de las sanciones", "Tipificar nuevas infracciones leves cuando la ley no lo haga, siempre que no establezcan sanciones"]'::jsonb,1,'Art. 27.3 Ley 40/2015','Pueden introducir especificaciones o graduaciones que, sin constituir nuevas infracciones o sanciones ni alterar sus límites, contribuyan a su identificación.',null),
('adm-cm:16-2ed2265247','adm-cm',16,'¿A qué título deben ser responsables los sujetos para poder ser sancionados según la Ley 40/2015?','["Por negligencia grave únicamente", "A título de dolo o culpa", "Solo a título de dolo", "Por el mero resultado, aun sin culpa"]'::jsonb,1,'Art. 28.1 Ley 40/2015','Solo pueden ser sancionados quienes resulten responsables de los hechos a título de dolo o culpa.',null),
('adm-cm:16-0e7328523e','adm-cm',16,'Cuando una obligación legal corresponde a varias personas conjuntamente, ¿cómo responden de las infracciones?','["De forma mancomunada", "Responde solo el de mayor participación", "De forma solidaria", "Responde solo quien la incumplió primero"]'::jsonb,2,'Art. 28.3 Ley 40/2015','Responderán de forma solidaria, aunque si la sanción es pecuniaria y es posible se individualizará según el grado de participación.',null),
('adm-cm:16-71e4957b59','adm-cm',16,'¿Pueden las sanciones administrativas implicar privación de libertad?','["Solo en el ámbito militar y penitenciario", "Sí, hasta un máximo de 72 horas", "Sí, de forma subsidiaria si no se paga la multa", "No, en ningún caso, ni directa ni subsidiariamente"]'::jsonb,3,'Art. 29.1 Ley 40/2015','Las sanciones administrativas en ningún caso pueden implicar, directa o subsidiariamente, privación de libertad.',null),
('adm-cm:16-39d2383827','adm-cm',16,'¿Cuál de estos criterios de graduación de la sanción recoge el art. 29.3 de la Ley 40/2015?','["La continuidad o persistencia en la conducta infractora", "El número de interesados personados en el procedimiento", "La capacidad económica del órgano sancionador", "La duración del procedimiento sancionador"]'::jsonb,0,'Art. 29.3 Ley 40/2015','Se consideran el grado de culpabilidad o intencionalidad, la continuidad o persistencia, la naturaleza de los perjuicios y la reincidencia.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:16-0cddd59103','adm-cm',16,'A efectos de graduación, ¿cuándo existe reincidencia según la Ley 40/2015?','["Por comisión en un año de más de una infracción de la misma naturaleza declarada por resolución firme", "Por haber sido sancionado alguna vez por la misma Administración", "Por comisión en seis meses de dos infracciones de cualquier naturaleza, aunque las resoluciones no sean firmes", "Por comisión en dos años de cualquier infracción"]'::jsonb,0,'Art. 29.3 Ley 40/2015','La reincidencia es la comisión en el término de un año de más de una infracción de la misma naturaleza declarada por resolución firme en vía administrativa.',null),
('adm-cm:16-535842cb49','adm-cm',16,'Si de una infracción deriva necesariamente la comisión de otra, ¿qué sanción se impone?','["La de la primera infracción cometida", "La suma de las sanciones de todas las infracciones", "Únicamente la correspondiente a la infracción más grave", "La de la infracción menos grave, en su grado máximo"]'::jsonb,2,'Art. 29.5 Ley 40/2015','Se impondrá únicamente la sanción correspondiente a la infracción más grave cometida.',null),
('adm-cm:16-8ad73ee49e','adm-cm',16,'Si la ley no fija plazos, ¿cuándo prescriben las infracciones muy graves según la Ley 40/2015?','["A los cinco años", "A los tres años", "A los cuatro años", "A los dos años"]'::jsonb,1,'Art. 30.1 Ley 40/2015','Las infracciones muy graves prescriben a los tres años, las graves a los dos y las leves a los seis meses.',null),
('adm-cm:16-62850ae36c','adm-cm',16,'Si la ley no fija plazos, ¿cuándo prescriben las infracciones leves?','["A los dos años", "A los tres meses", "Al año", "A los seis meses"]'::jsonb,3,'Art. 30.1 Ley 40/2015','Las infracciones leves prescriben a los seis meses; las sanciones por faltas leves, al año.',null),
('adm-cm:16-a0d44c6017','adm-cm',16,'Si la ley no fija plazos, ¿cuándo prescriben las sanciones impuestas por faltas leves?','["A los seis meses", "A los tres meses", "A los dos años", "Al año"]'::jsonb,3,'Art. 30.1 Ley 40/2015','Las sanciones por faltas muy graves prescriben a los tres años, por graves a los dos y por leves al año.',null),
('adm-cm:16-38204278ad','adm-cm',16,'¿Cuándo se reanuda el plazo de prescripción de la infracción interrumpido por el procedimiento sancionador?','["Cuando se dicta la propuesta de resolución", "Si el expediente está paralizado más de tres meses por cualquier causa, incluso imputable al interesado", "Si el expediente está paralizado más de un mes por causa no imputable al presunto responsable", "Nunca, la interrupción es definitiva"]'::jsonb,2,'Art. 30.2 Ley 40/2015','Se reinicia el plazo si el expediente sancionador estuviera paralizado durante más de un mes por causa no imputable al presunto responsable.',null),
('adm-cm:16-b808fa5dbf','adm-cm',16,'¿Cuándo no pueden sancionarse unos hechos ya sancionados penal o administrativamente?','["Cuando haya identidad del sujeto, hecho y fundamento", "Cuando haya identidad de hecho, aunque cambie el sujeto", "Solo si la primera sanción fue penal", "Cuando la primera sanción fuera de otra Administración"]'::jsonb,0,'Art. 31.1 Ley 40/2015','No pueden sancionarse los hechos ya sancionados cuando se aprecie identidad del sujeto, hecho y fundamento.',null),
('adm-cm:16-722d06b256','adm-cm',16,'Según la Ley 39/2015, ¿cómo se inician los procedimientos sancionadores?','["De oficio o a solicitud de cualquier interesado", "Siempre de oficio", "A solicitud del perjudicado", "Por denuncia obligatoriamente"]'::jsonb,1,'Art. 63.1 Ley 39/2015','Los procedimientos de naturaleza sancionadora se iniciarán siempre de oficio, con separación entre la fase instructora y la sancionadora.',null),
('adm-cm:16-078ebf0195','adm-cm',16,'¿Qué exige el art. 63.1 de la Ley 39/2015 en cuanto a los órganos del procedimiento sancionador?','["Separación entre la fase instructora y la sancionadora, encomendadas a órganos distintos", "Que un mismo órgano instruya y resuelva el procedimiento para garantizar la coherencia de la decisión", "Que resuelva el superior jerárquico del denunciante", "Que el instructor sea siempre un órgano colegiado"]'::jsonb,0,'Art. 63.1 Ley 39/2015','Debe establecerse la debida separación entre la fase instructora y la sancionadora, que se encomendará a órganos distintos.',null),
('adm-cm:16-c399427618','adm-cm',16,'Si el presunto infractor no presenta alegaciones al acuerdo de iniciación, ¿qué puede ocurrir?','["Se archiva el procedimiento", "El procedimiento caduca automáticamente", "Se entiende que reconoce la infracción y la sanción pecuniaria se reduce automáticamente a la mitad de su importe inicial", "El acuerdo puede considerarse propuesta de resolución si contiene un pronunciamiento preciso sobre la responsabilidad"]'::jsonb,3,'Art. 64.2 Ley 39/2015','Si no se presentan alegaciones, el acuerdo de iniciación podrá considerarse propuesta de resolución cuando contenga un pronunciamiento preciso sobre la responsabilidad.',null),
('adm-cm:16-512358b41b','adm-cm',16,'¿Qué reducción mínima prevé la Ley 39/2015 por el reconocimiento de responsabilidad o el pago voluntario en sanciones pecuniarias?','["El 25 %, solo si no se recurre", "Al menos el 20 %, acumulable entre sí", "El 50 %, no acumulable", "El 10 %, solo por pronto pago"]'::jsonb,1,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % sobre el importe de la sanción, acumulables entre sí y condicionadas al desistimiento de cualquier recurso administrativo.',null),
('adm-cm:16-c67bac7b82','adm-cm',16,'¿Cuándo es ejecutiva la resolución de un procedimiento sancionador?','["Cuando la ratifique el superior jerárquico", "Cuando sea firme en vía judicial", "Cuando no quepa contra ella ningún recurso ordinario en vía administrativa", "Desde el día siguiente a su notificación"]'::jsonb,2,'Art. 90.3 Ley 39/2015','La resolución que ponga fin al procedimiento será ejecutiva cuando no quepa contra ella ningún recurso ordinario en vía administrativa.',null),
('adm-cm:17-574377c2d2','adm-cm',17,'Según la Ley de Expropiación Forzosa, ¿qué comprende la expropiación forzosa?','["Las ventas forzosas reguladas por la legislación de abastecimientos y comercio exterior", "Solo la transmisión forzosa del dominio de bienes inmuebles", "Cualquier forma de privación singular de la propiedad privada o de derechos o intereses patrimoniales legítimos acordada imperativamente", "Las limitaciones generales del derecho de propiedad impuestas por los planes urbanísticos y las ventas forzosas de la legislación de abastecimientos y divisas"]'::jsonb,2,'Art. 1 LEF','Comprende cualquier forma de privación singular de la propiedad o de derechos o intereses patrimoniales legítimos; las ventas forzosas de abastecimientos quedan fuera.',null),
('adm-cm:17-90a5971af1','adm-cm',17,'Según la Ley de Expropiación Forzosa, ¿qué Administraciones pueden acordar la expropiación?','["El Estado, la provincia o el municipio", "El Estado y los concesionarios de servicios públicos", "Cualquier entidad de derecho público", "Solo el Estado"]'::jsonb,0,'Art. 2 LEF','La expropiación solo podrá ser acordada por el Estado, la provincia o el municipio; los concesionarios pueden ser beneficiarios.',null),
('adm-cm:17-be071cc4de','adm-cm',17,'¿Quién puede ser beneficiario de una expropiación por causa de interés social?','["Solo los concesionarios de obras públicas", "Solo las entidades sin ánimo de lucro", "Solo las Administraciones públicas", "Cualquier persona física o jurídica que reúna los requisitos de la ley especial"]'::jsonb,3,'Art. 2 LEF','Por causa de interés social puede ser beneficiaria cualquier persona natural o jurídica en la que concurran los requisitos de la ley especial.',null),
('adm-cm:17-92817dbad2','adm-cm',17,'¿A quién considera propietario la Administración expropiante, salvo prueba en contrario?','["A quien aparezca en el catastro inmobiliario, con preferencia sobre el Registro de la Propiedad", "A quien conste como tal en registros públicos que produzcan presunción de titularidad", "A quien pague el impuesto sobre bienes inmuebles", "A quien ocupe materialmente el bien"]'::jsonb,1,'Art. 3 LEF','Considera propietario a quien conste en registros públicos con presunción de titularidad; en su defecto, en registros fiscales; y finalmente a quien lo sea pública y notoriamente.',null),
('adm-cm:17-4ecf9f5b91','adm-cm',17,'¿Con quién se entienden las diligencias cuando no comparecen los propietarios o la propiedad es litigiosa?','["Con el Ministerio Fiscal", "Con el alcalde del municipio", "Con el registrador de la propiedad", "Con el abogado del Estado"]'::jsonb,0,'Art. 5 LEF','Se entienden con el Ministerio Fiscal si no comparecen los titulares, están incapacitados sin representante o la propiedad es litigiosa.',null),
('adm-cm:17-adf98004ff','adm-cm',17,'¿Qué es indispensable para proceder a la expropiación forzosa?','["La previa inscripción del bien en el inventario de la Administración", "La previa declaración de utilidad pública o interés social del fin", "La previa consignación del justo precio", "El acuerdo previo con el propietario"]'::jsonb,1,'Art. 9 LEF','Es indispensable la previa declaración de utilidad pública o interés social del fin a que haya de afectarse el objeto expropiado.',null),
('adm-cm:17-0c97a455e4','adm-cm',17,'¿En qué planes se entiende implícita la utilidad pública para expropiar inmuebles?','["En los planes de vivienda protegida exclusivamente", "Solo en los planes aprobados por ley", "En todos los planes de obras y servicios del Estado, provincia y municipio", "En ninguno; la utilidad pública debe declararse siempre, caso por caso, por acuerdo del Consejo de Ministros"]'::jsonb,2,'Art. 10 LEF','La utilidad pública se entiende implícita, para inmuebles, en todos los planes de obras y servicios del Estado, provincia y municipio.',null),
('adm-cm:17-71eb3b1060','adm-cm',17,'Declarada la utilidad pública, ¿sobre qué resuelve la Administración?','["Sobre la reversión de los bienes no utilizados", "Sobre el justo precio de los bienes", "Sobre la urgencia de la ocupación", "Sobre la necesidad concreta de ocupar los bienes estrictamente indispensables"]'::jsonb,3,'Art. 15 LEF','La Administración resuelve sobre la necesidad concreta de ocupar los bienes o adquirir los derechos estrictamente indispensables.',null),
('adm-cm:17-d3fe6c3a89','adm-cm',17,'¿Quién debe formular la relación concreta e individualizada de los bienes de necesaria expropiación?','["El registrador de la propiedad", "El propietario afectado", "El Jurado de Expropiación", "El beneficiario de la expropiación"]'::jsonb,3,'Art. 17 LEF','El beneficiario está obligado a formular una relación concreta e individualizada de los bienes o derechos de necesaria expropiación.',null),
('adm-cm:17-21a5e681d6','adm-cm',17,'Recibida la relación de bienes, ¿durante cuánto tiempo se abre información pública?','["Un mes", "Diez días", "Quince días", "Veinte días"]'::jsonb,2,'Art. 18 LEF','Se abre información pública durante un plazo de quince días.',null),
('adm-cm:17-28f110bddb','adm-cm',17,'¿En qué plazo máximo se resuelve sobre la necesidad de ocupación tras la información pública?','["Veinte días", "Quince días", "Un mes", "Diez días"]'::jsonb,0,'Art. 20 LEF','Se resuelve en el plazo máximo de veinte días, describiendo los bienes y designando a los interesados.',null),
('adm-cm:17-250e5c6734','adm-cm',17,'¿Qué acto inicia el expediente expropiatorio?','["El acta previa a la ocupación", "El acuerdo de necesidad de ocupación", "La hoja de aprecio del propietario", "La declaración de utilidad pública"]'::jsonb,1,'Art. 21 LEF','El acuerdo de necesidad de ocupación inicia el expediente expropiatorio.',null),
('adm-cm:17-759a6f3fc0','adm-cm',17,'Si no hay acuerdo de adquisición amistosa, ¿en qué plazo se sigue con el procedimiento de justiprecio?','["Diez días", "Quince días", "Veinte días", "Un mes"]'::jsonb,1,'Art. 24 LEF','Si en quince días no se llega al mutuo acuerdo, se sigue el procedimiento, aunque las partes pueden convenir después en cualquier momento.',null),
('adm-cm:17-aa2c18e178','adm-cm',17,'¿Cómo se tramita la fijación del justo precio?','["En el mismo expediente de necesidad de ocupación", "Ante el juzgado de primera instancia", "Como pieza separada, con un expediente individual para cada propietario", "Mediante un único expediente para todos los propietarios afectados por la misma obra"]'::jsonb,2,'Art. 26 LEF','La fijación del justo precio se tramita como pieza separada, con un expediente individual por propietario, salvo comunidad o unidad económica.',null),
('adm-cm:17-7c58359e3f','adm-cm',17,'¿De qué plazo disponen los propietarios para presentar su hoja de aprecio?','["Quince días hábiles desde la notificación", "Un mes desde el acuerdo de necesidad de ocupación", "Diez días desde la publicación en el boletín", "Veinte días desde el siguiente a la notificación"]'::jsonb,3,'Art. 29 LEF','La Administración requiere a los propietarios para que en veinte días presenten hoja de aprecio motivada.',null),
('adm-cm:17-9666812937','adm-cm',17,'¿De quién son los honorarios del perito que avala la hoja de aprecio del propietario?','["De los propietarios", "Del beneficiario de la expropiación", "De la Administración expropiante", "Se reparten por mitades"]'::jsonb,0,'Art. 29 LEF','La valoración puede estar avalada por un perito, cuyos honorarios son siempre de cuenta de los propietarios.',null),
('adm-cm:17-f781daae9d','adm-cm',17,'Si el propietario recibe la hoja de aprecio de la Administración, ¿en qué plazo puede aceptarla o rechazarla?','["Quince días", "Diez días", "Veinte días", "Cinco días"]'::jsonb,1,'Art. 30 LEF','El propietario puede aceptarla o rechazarla dentro de los diez días siguientes, con las alegaciones y pruebas que estime oportunas.',null),
('adm-cm:17-cb350a2cb2','adm-cm',17,'Si el propietario rechaza el precio ofrecido por la Administración, ¿quién fija el justiprecio?','["El Tribunal Superior de Justicia", "El Consejo de Ministros", "El juez de primera instancia", "El Jurado provincial de expropiación"]'::jsonb,3,'Art. 31 LEF','Si el propietario rechaza el precio fundado de la Administración, el expediente pasa al Jurado provincial de expropiación.',null),
('adm-cm:17-eec0edb9bd','adm-cm',17,'¿Quién preside el Jurado provincial de expropiación?','["Un notario designado por el colegio notarial", "El delegado del Gobierno en la provincia", "El magistrado que designe el presidente de la audiencia", "El abogado del Estado de la Delegación de Hacienda"]'::jsonb,2,'Art. 32 LEF','Lo preside el magistrado que designe el presidente de la audiencia correspondiente.',null),
('adm-cm:17-8c0c96c039','adm-cm',17,'¿Qué recurso cabe contra la resolución del Jurado de expropiación?','["Solo el recurso contencioso-administrativo", "Recurso extraordinario de revisión, únicamente", "Recurso de reposición y después alzada", "Recurso de alzada ante el ministro"]'::jsonb,0,'Art. 35 LEF','La resolución del Jurado ultima la vía gubernativa y contra ella procede tan solo el recurso contencioso-administrativo.',null),
('adm-cm:17-60ac6b0254','adm-cm',17,'¿Con arreglo a qué valor se efectúan las tasaciones de los bienes expropiados?','["El que tengan en la fecha del pago efectivo", "El que tengan al iniciarse el expediente de justiprecio, sin las plusvalías del proyecto", "El valor catastral del último ejercicio", "El que tengan en la fecha de la ocupación efectiva, incluidas las plusvalías derivadas del proyecto"]'::jsonb,1,'Art. 36 LEF','Se tasan según su valor al iniciarse el expediente de justiprecio, sin las plusvalías consecuencia del proyecto ni las previsibles.',null),
('adm-cm:17-326d032f5c','adm-cm',17,'Una vez determinado el justo precio, ¿en qué plazo máximo debe pagarse?','["Tres meses", "Dos meses", "Seis meses", "Un año"]'::jsonb,2,'Art. 48 LEF','Se procede al pago en el plazo máximo de seis meses.',null),
('adm-cm:17-e6777135d3','adm-cm',17,'¿Dónde se consigna el justiprecio cuando el propietario rehúsa recibirlo o existe litigio?','["En una entidad bancaria elegida por el expropiado", "En el juzgado de primera instancia", "En la cuenta del Jurado de Expropiación", "En la Caja General de Depósitos"]'::jsonb,3,'Art. 50 LEF','Se consigna en la Caja General de Depósitos, a disposición de la autoridad o tribunal competente.',null),
('adm-cm:17-1df198b619','adm-cm',17,'¿Quién puede declarar la urgente ocupación de los bienes afectados por una expropiación?','["El Consejo de Ministros, excepcionalmente", "El alcalde del municipio afectado", "El delegado del Gobierno", "El Jurado provincial de expropiación"]'::jsonb,0,'Art. 52 LEF','Excepcionalmente y mediante acuerdo del Consejo de Ministros podrá declararse urgente la ocupación.',null),
('adm-cm:17-b4a775e510','adm-cm',17,'En la expropiación urgente, ¿con qué antelación mínima se notifica el levantamiento del acta previa a la ocupación?','["Quince días", "Ocho días", "Diez días", "Tres días"]'::jsonb,1,'Art. 52 LEF','La notificación del día y hora del acta previa se hace con una antelación mínima de ocho días y mediante cédula.',null),
('adm-cm:17-ed908ef325','adm-cm',17,'Si no se ejecuta la obra que motivó la expropiación, ¿qué derecho tiene el primitivo dueño?','["El derecho de reversión", "El derecho de tanteo", "El derecho de retasación", "El derecho de retracto"]'::jsonb,0,'Art. 54 LEF','Si no se ejecuta la obra o no se establece el servicio, el primitivo dueño o sus causahabientes pueden recobrar lo expropiado (reversión).',null),
('adm-cm:17-2a2cd33fd5','adm-cm',17,'¿Cuándo no hay derecho de reversión por prolongarse la afectación?','["Cuando la afectación dure cinco años desde la ocupación", "Cuando la afectación dure dos años, sea cual sea el uso", "Cuando la afectación dure diez años desde la terminación de la obra o el establecimiento del servicio", "Cuando hayan pasado veinte años desde el pago del justiprecio, aunque no se haya ejecutado nunca la obra prevista"]'::jsonb,2,'Art. 54 LEF','No hay reversión cuando la afectación se prolongue durante diez años desde la terminación de la obra o el establecimiento del servicio.',null),
('adm-cm:17-0c054cfe85','adm-cm',17,'Notificada la desafectación por la Administración, ¿en qué plazo puede solicitarse la reversión?','["Un año", "Un mes", "Seis meses", "Tres meses"]'::jsonb,3,'Art. 54 LEF','El plazo para solicitar la reversión es de tres meses desde la notificación del exceso, la desafectación o el propósito de no ejecutar la obra.',null),
('adm-cm:17-2f722e91aa','adm-cm',17,'¿Cuándo procede la retasación de los bienes expropiados?','["Si transcurren cuatro años sin pagar ni consignar el justo precio", "Si transcurren dos años sin ocupar el bien", "Siempre que el expropiado lo solicite antes del pago", "Si el justo precio no se fija en seis meses"]'::jsonb,0,'Art. 58 LEF','Si pasan cuatro años sin pagar o consignar el justo precio, hay que evaluar de nuevo los bienes; tras el pago o consignación no procede.',null),
('adm-cm:17-07cc278047','adm-cm',17,'Si pasan seis meses desde la iniciación del expediente sin fijar el justo precio, ¿qué debe abonar la Administración culpable?','["Un recargo del 20 % sobre el justo precio", "El doble del interés legal desde el inicio", "Una indemnización fija por daños morales", "El interés legal del justo precio hasta que se determine"]'::jsonb,3,'Art. 56 LEF','Debe abonar el interés legal del justo precio hasta su determinación, liquidado con efectos retroactivos.',null),
('adm-cm:18-a283444904','adm-cm',18,'La Ley 9/2017 de Contratos del Sector Público califica como contratos de obras, concesión de obras, concesión de servicios, suministro y servicios a:','["Los contratos que regula en su sección de calificación de contratos", "Los contratos privados de las Administraciones Públicas", "Los convenios de colaboración entre Administraciones", "Los contratos patrimoniales de compraventa y arrendamiento de bienes inmuebles"]'::jsonb,0,'Art. 12.1 LCSP','Son los contratos que se califican según las normas de esa sección: obras, concesión de obras, concesión de servicios, suministro y servicios.',null),
('adm-cm:18-e95392416c','adm-cm',18,'El contrato de obras tiene por objeto, entre otros:','["La adquisición o el arrendamiento de bienes muebles necesarios para una obra", "La ejecución de una obra, aislada o conjuntamente con la redacción del proyecto", "La redacción de un proyecto de obra, sin incluir su ejecución material", "La gestión de un servicio público, con o sin ejecución previa de una obra por el contratista"]'::jsonb,1,'Art. 13.1 LCSP','Tiene por objeto la ejecución de una obra, aislada o conjuntamente con la redacción del proyecto, o los trabajos del Anexo I.','nov. 2024 · 1.er ejercicio'),
('adm-cm:18-92512ffb82','adm-cm',18,'Los contratos de suministro tienen por objeto:','["La ejecución de obras, aislada o conjuntamente con la redacción del proyecto", "La prestación de una actividad o de un resultado distinto de una obra, a cambio de un precio cierto", "La adquisición, el arrendamiento financiero o el arrendamiento de productos o bienes muebles", "La adquisición o el arrendamiento de bienes inmuebles, con o sin opción de compra, y de derechos sobre ellos"]'::jsonb,2,'Art. 16.1 LCSP','Tienen por objeto la adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.','nov. 2024 · 1.er ejercicio'),
('adm-cm:18-48d6f9d819','adm-cm',18,'Los contratos de servicios son aquellos cuyo objeto son:','["La adquisición o el arrendamiento de bienes inmuebles, valores negociables o derechos de propiedad incorporal sobre ellos", "La adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles", "La ejecución de obras públicas, aislada o conjuntamente con la redacción del proyecto", "Prestaciones de hacer consistentes en una actividad o dirigidas a un resultado distinto de una obra o suministro"]'::jsonb,3,'Art. 17 LCSP','Son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a un resultado distinto de una obra o un suministro.',null),
('adm-cm:18-eecc26630e','adm-cm',18,'Los contratos de suministros y servicios de prestación sucesiva tienen un plazo máximo de duración de:','["Cinco años, incluidas las posibles prórrogas", "Tres años, sin posibilidad de prórroga", "Cuatro años, más dos de posibles prórrogas anuales", "Diez años, incluidas las posibles prórrogas"]'::jsonb,0,'Art. 29.4 LCSP','Cinco años, incluyendo las posibles prórrogas.',null),
('adm-cm:18-be3ce63f11','adm-cm',18,'Los contratos menores:','["Pueden durar hasta dos años, sin posibilidad de prórroga", "No pueden durar más de un año ni ser objeto de prórroga", "No pueden durar más de un año, pero pueden prorrogarse una vez", "No pueden durar más de seis meses ni ser objeto de prórroga"]'::jsonb,1,'Art. 29.8 LCSP','No pueden tener una duración superior a un año ni ser objeto de prórroga.',null),
('adm-cm:18-8e300959f2','adm-cm',18,'El recurso especial en materia de contratación tiene carácter:','["Obligatorio", "Previo al recurso de alzada", "Potestativo", "Exclusivo de las empresas adjudicatarias"]'::jsonb,2,'Art. 44.7 LCSP','Tiene carácter potestativo y es gratuito para los recurrentes.',null),
('adm-cm:18-b9db848e25','adm-cm',18,'El plazo para interponer el recurso especial en materia de contratación es de:','["Un mes", "Diez días naturales", "Dos meses", "Quince días hábiles"]'::jsonb,3,'Art. 50.1 LCSP','El plazo es de quince días hábiles.',null),
('adm-cm:18-49c4c37b89','adm-cm',18,'El perfil de contratante se difunde:','["Exclusivamente a través de Internet", "En el BOE", "En el tablón de anuncios del órgano", "En la prensa nacional"]'::jsonb,0,'Art. 63 LCSP','Los órganos de contratación difunden exclusivamente a través de Internet su perfil de contratante.',null),
('adm-cm:18-d084755801','adm-cm',18,'Pueden contratar con el sector público las personas naturales o jurídicas que:','["Tengan domicilio social en España y plena capacidad de obrar, estén inscritas en el Registro Mercantil y acrediten su solvencia", "Tengan plena capacidad de obrar, no estén incursas en prohibición de contratar y acrediten su solvencia", "Tengan plena capacidad de obrar y estén inscritas en el registro mercantil desde hace al menos cinco años", "No estén incursas en prohibición de contratar y hayan contratado antes con la Administración"]'::jsonb,1,'Art. 65.1 LCSP','Se exige plena capacidad de obrar, no estar incursas en prohibición de contratar y acreditar la solvencia (o clasificación cuando se exija).',null),
('adm-cm:18-1350e2055b','adm-cm',18,'La garantía provisional, cuando se exige, no puede ser superior al:','["5 % del precio de adjudicación, IVA excluido", "10 % del presupuesto base de licitación, IVA incluido", "3 % del presupuesto base de licitación, IVA excluido", "2 % del valor estimado del contrato, IVA excluido"]'::jsonb,2,'Art. 106.2 LCSP','No puede superar el 3 % del presupuesto base de licitación, excluido el IVA.',null),
('adm-cm:18-639bdbb6c4','adm-cm',18,'La garantía definitiva es, con carácter general, del:','["3 % del presupuesto base de licitación", "10 % del precio con IVA", "2 % del valor estimado", "5 % del precio final ofertado, IVA excluido"]'::jsonb,3,'Art. 107.1 LCSP','Es del 5 % del precio final ofertado, excluido el IVA.',null),
('adm-cm:18-9e63906135','adm-cm',18,'Son contratos menores de obras los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "50.000 euros", "100.000 euros"]'::jsonb,0,'Art. 118.1 LCSP','Obras: valor estimado inferior a 40.000 €. Suministro o servicios: inferior a 15.000 €.','oct. 2026 · 1.er ejercicio'),
('adm-cm:18-e933b29b98','adm-cm',18,'Son contratos menores de suministro o de servicios los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "6.000 euros", "30.000 euros"]'::jsonb,1,'Art. 118.1 LCSP','Suministro o servicios: inferior a 15.000 €. Obras: inferior a 40.000 €.',null),
('adm-cm:18-8df98cc983','adm-cm',18,'Con carácter ordinario, la adjudicación se realiza por:','["El procedimiento negociado con publicidad, con pluralidad de criterios basados en la mejor relación calidad-precio", "El diálogo competitivo, utilizando como único criterio el precio más bajo ofertado", "El procedimiento abierto o el restringido, con pluralidad de criterios basados en la mejor relación calidad-precio", "El procedimiento abierto simplificado, con un único criterio de adjudicación"]'::jsonb,2,'Art. 131.2 LCSP','Ordinariamente por procedimiento abierto o restringido, con pluralidad de criterios basados en la mejor relación calidad-precio.',null),
('adm-cm:18-8bccd5a135','adm-cm',18,'Los contratos se adjudican utilizando una pluralidad de criterios en base a:','["El precio más bajo ofertado", "La mayor experiencia acreditada de la empresa", "La menor huella de carbono", "La mejor relación calidad-precio"]'::jsonb,3,'Art. 145.1 LCSP','Se adjudican con pluralidad de criterios en base a la mejor relación calidad-precio.',null),
('adm-cm:18-e863196ed4','adm-cm',18,'Si el contrato no es susceptible de recurso especial, la formalización debe hacerse:','["No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación", "No más tarde de un mes desde la notificación de la adjudicación a todos los licitadores participantes", "No más tarde de los quince días naturales siguientes a la publicación de la adjudicación", "No más tarde de los diez días hábiles siguientes a la notificación de la adjudicación"]'::jsonb,0,'Art. 153.3 LCSP','No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación.',null),
('adm-cm:18-2566b6de9c','adm-cm',18,'En el procedimiento abierto:','["Solo pueden presentar proposición las empresas invitadas por el órgano de contratación", "Todo empresario interesado puede presentar una proposición, excluida toda negociación", "Todo empresario interesado puede presentar una proposición, que luego se negocia con él", "Solo pueden presentar proposición las empresas inscritas en el Registro Oficial de Licitadores"]'::jsonb,1,'Art. 156.1 LCSP','Todo empresario interesado puede presentar una proposición, quedando excluida toda negociación.','oct. 2026 · 1.er ejercicio'),
('adm-cm:18-e9f26330e1','adm-cm',18,'En el procedimiento restringido pueden presentar proposiciones:','["Todos los empresarios interesados, excluida toda negociación de los términos del contrato", "Solo las pequeñas y medianas empresas que acrediten su solvencia técnica", "Solo los empresarios que, a su solicitud y en atención a su solvencia, sean seleccionados", "Solo los empresarios inscritos en el Registro Oficial de Licitadores y Empresas Clasificadas"]'::jsonb,2,'Art. 160.2 LCSP','Cualquier empresa puede solicitar participar, pero solo presentan proposiciones las seleccionadas.',null),
('adm-cm:18-dcf6581061','adm-cm',18,'En el procedimiento restringido, el número mínimo de empresarios invitados no puede ser inferior a:','["Tres", "Diez", "Dos", "Cinco"]'::jsonb,3,'Art. 162.2 LCSP','No puede ser inferior a cinco.',null),
('adm-cm:18-27c25b5f25','adm-cm',18,'En los procedimientos con negociación, la adjudicación recae en el licitador elegido:','["Tras negociar las condiciones del contrato con uno o varios candidatos", "Por sorteo público entre los candidatos que hayan acreditado la solvencia exigida en los pliegos", "Por orden de presentación de las ofertas, sin negociación", "Atendiendo únicamente al precio más bajo, sin negociación"]'::jsonb,0,'Art. 166.1 LCSP','Recae en el licitador justificadamente elegido tras negociar las condiciones con uno o varios candidatos.',null),
('adm-cm:18-cdc8edba0e','adm-cm',18,'En la tramitación urgente del expediente, el plazo de inicio de la ejecución del contrato no podrá exceder de:','["Quince días, contados desde la formalización", "Tres meses, contados desde la adjudicación", "Una semana, contada desde la formalización", "Un mes, contado desde la formalización"]'::jsonb,3,'Art. 119.2 c) LCSP','La urgencia reduce además a la mitad los plazos de licitación, adjudicación y formalización.',null),
('adm-cm:18-30fd0a6450','adm-cm',18,'El orden jurisdiccional contencioso-administrativo es competente para resolver las cuestiones relativas a:','["Los delitos cometidos por el contratista en la ejecución", "Los efectos y extinción de los contratos privados de los poderes adjudicadores que no sean Administraciones", "La preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos", "Los despidos del personal del contratista y las reclamaciones de los subcontratistas por los pagos pendientes"]'::jsonb,2,'Art. 27.1 a) LCSP','El orden civil conoce de los efectos y extinción de los contratos privados.',null),
('adm-cm:18-db2dc12c6e','adm-cm',18,'Es causa de resolución del contrato la demora en el cumplimiento de los plazos que suponga un retraso injustificado superior a:','["La mitad del plazo de duración inicial del contrato", "Un mes, en todo caso", "Un quinto del plazo de duración inicial del contrato, sin incluir las prórrogas", "Un tercio del plazo de duración inicial del contrato, incluidas las prórrogas"]'::jsonb,3,'Art. 211.1 d) LCSP','Es una de las causas de resolución del art. 211.',null),
('adm-cm:18-82c307e2ff','adm-cm',18,'Un encargo a un medio propio personificado que cumpla los requisitos legales:','["Es un contrato menor, si no supera los 15.000 euros", "Es un contrato de servicios no armonizado", "Requiere licitación pública", "No tendrá la consideración de contrato"]'::jsonb,3,'Art. 32.1 LCSP','Requiere, entre otros, que más del 80 % de la actividad del ente se realice para el poder adjudicador que lo controla.',null),
('adm-cm:18-9da4585636','adm-cm',18,'En el procedimiento de licitación con negociación, cuando se limite el número de candidatos, el mínimo será de:','["Cinco", "Dos", "Tres", "Diez"]'::jsonb,2,'Art. 169.2 LCSP','El número mínimo de invitados es tres.',null),
('adm-cm:18-57041f8b20','adm-cm',18,'La garantía definitiva puede constituirse, entre otras formas:','["Solo en efectivo, ingresado en la Caja General de Depósitos", "En efectivo o valores, mediante aval o mediante contrato de seguro de caución", "Mediante pagaré personal del contratista o mediante prenda sobre maquinaria, sin necesidad de aval", "Mediante hipoteca sobre bienes inmuebles del contratista o de un tercero, o mediante prenda sobre sus bienes muebles"]'::jsonb,1,'Art. 108.1 LCSP','Son las formas de constitución de la garantía.',null),
('adm-cm:18-5ce80c9945','adm-cm',18,'En el ámbito de la AGE, el conocimiento y resolución de los recursos especiales en materia de contratación corresponde a:','["La Audiencia Nacional", "La Junta Consultiva de Contratación Pública del Estado", "El Tribunal Administrativo Central de Recursos Contractuales", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 45.1 LCSP','Las CCAA pueden crear órganos propios o atribuir la competencia al Tribunal estatal por convenio.',null),
('adm-cm:18-eda2a20bee','adm-cm',18,'En la AGE, el anuncio de licitación se publica en el perfil de contratante y, además:','["En un periódico de tirada nacional", "En el BOCM", "En el BOE", "En el tablón de anuncios del Ministerio exclusivamente"]'::jsonb,2,'Art. 135.1 LCSP','Si el contrato está sujeto a regulación armonizada, también en el DOUE.',null),
('adm-cm:18-81aae62a8d','adm-cm',18,'La información publicada en el perfil de contratante debe mantenerse durante un periodo de tiempo de, al menos:','["6 meses", "10 años", "1 año", "5 años"]'::jsonb,3,'Art. 63.1 LCSP','El acceso al perfil es libre y se difunde exclusivamente a través de Internet.',null),
('adm-cm:18-0b2e0cbd7f','adm-cm',18,'Con carácter general, la duración de la prohibición de contratar no podrá exceder de:','["Diez años", "Cinco años", "Un año", "Tres años"]'::jsonb,3,'Art. 72.6 LCSP','Salvo que la sentencia o resolución firme establezca otro plazo.',null),
('adm-cm:18-fccccca990','adm-cm',18,'Según el art. 2.1 LCSP, un contrato es oneroso cuando:','["El contratista obtiene algún tipo de beneficio económico, directo o indirecto", "Supera los 15.000 euros de valor estimado, en el caso de los contratos de servicios y suministros", "Lo celebra una Administración territorial", "Se paga siempre en metálico"]'::jsonb,0,'Art. 2.1 LCSP','La ley se aplica a los contratos onerosos celebrados por las entidades del sector público.',null),
('adm-cm:18-d9be20c333','adm-cm',18,'El valor estimado de los contratos de obras, suministros y servicios se calcula:','["Por el importe total pagadero, incluido el IVA", "Por el importe total pagadero, sin incluir el IVA", "Sin incluir las posibles prórrogas", "Solo con el precio del primer año de ejecución"]'::jsonb,1,'Art. 101.1 a) LCSP','Se tienen en cuenta las eventuales prórrogas y modificaciones previstas.',null),
('adm-cm:18-660286f366','adm-cm',18,'La publicación de la información de los contratos menores en el perfil de contratante se realizará:','["Anualmente", "Al menos trimestralmente", "Diariamente", "Solo si superan 15.000 euros"]'::jsonb,1,'Art. 63.4 LCSP','Quedan exceptuados los de valor inferior a 5.000 euros pagados mediante anticipo de caja fija o similar.',null),
('adm-cm:18-b510024b89','adm-cm',18,'Los contratos podrán modificarse durante su vigencia, cuando así se haya advertido expresamente en el pliego, hasta un máximo del:','["50 % del precio inicial", "20 % del precio inicial", "100 % del precio inicial", "10 % del precio inicial"]'::jsonb,1,'Art. 204.1 LCSP','Para las modificaciones no previstas en el pliego rige el art. 205.',null),
('adm-cm:18-7590b4f1bb','adm-cm',18,'En la tramitación de emergencia:','["Hay que tramitar siempre un procedimiento abierto con plazos reducidos a la mitad, como en la tramitación urgente", "Se requiere autorización judicial", "No puede contratarse", "El órgano de contratación puede ordenar la ejecución sin obligación de tramitar expediente de contratación"]'::jsonb,3,'Art. 120.1 a) LCSP','El inicio de la ejecución no puede exceder de un mes desde el acuerdo.',null),
('adm-cm:18-711662874a','adm-cm',18,'Cuando haya varios criterios de adjudicación, el plazo máximo para adjudicar será de:','["Quince días desde la apertura de las proposiciones, sin que el pliego pueda fijar otro", "Dos meses desde la apertura de las proposiciones, salvo que el pliego indique otro", "Seis meses desde la apertura de las proposiciones", "Un mes desde la apertura de las proposiciones, salvo que el pliego indique otro"]'::jsonb,1,'Art. 158.2 LCSP','Con un único criterio (el precio), el plazo es de quince días.',null),
('adm-cm:18-39829fb324','adm-cm',18,'Los contratos de suministro de la AGE y sus organismos están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "40.000 euros", "5.404.000 euros", "140.000 euros"]'::jsonb,3,'Art. 21.1 LCSP','Para otras entidades el umbral es de 216.000 euros.',null),
('adm-cm:18-3f8e7eeb0e','adm-cm',18,'Las concesiones de obras y de servicios que comprendan la ejecución de obras tendrán un plazo de duración máximo de:','["40 años", "10 años", "25 años", "5 años"]'::jsonb,0,'Art. 29.6 a) LCSP','Las concesiones de servicios sin obras no sanitarios, 25 años; los sanitarios del art. 29.6 c), 10 años.',null),
('adm-cm:18-64535b332b','adm-cm',18,'Para que el contratista pueda ceder sus derechos y obligaciones a un tercero, es requisito que el cedente tenga ejecutado al menos:','["La totalidad de la prestación", "Un 10 % del importe del contrato", "Un 20 % del importe del contrato", "Un 50 % del importe del contrato o de su duración"]'::jsonb,2,'Art. 214.2 b) LCSP','Además, se necesita autorización previa del órgano de contratación.',null),
('adm-cm:18-b256b43f07','adm-cm',18,'La duración de un acuerdo marco no podrá exceder, salvo casos excepcionales justificados, de:','["Diez años", "Cuatro años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 219.2 LCSP','Es la duración máxima ordinaria de los acuerdos marco.',null),
('adm-cm:18-fa75add585','adm-cm',18,'La prórroga de un contrato será obligatoria para el empresario siempre que su preaviso se produzca, al menos, con una antelación de:','["Quince días respecto de la finalización del plazo de duración del contrato", "Dos meses respecto de la finalización del plazo de duración del contrato", "Seis meses respecto de la finalización del plazo de duración del contrato", "Un mes"]'::jsonb,1,'Art. 29.2 LCSP','La prórroga no puede producirse por consentimiento tácito de las partes.',null),
('adm-cm:18-40b34c558a','adm-cm',18,'Los contratos de servicios sociales y otros del anexo IV están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["140.000 euros", "750.000 euros", "5.404.000 euros", "216.000 euros"]'::jsonb,1,'Art. 22.1 LCSP','Es un umbral específico para los servicios del anexo IV.',null),
('adm-cm:18-762d76f033','adm-cm',18,'Tanto en la concesión de obras como en la de servicios es necesaria la transferencia al concesionario de:','["La propiedad del dominio público", "La titularidad del servicio público", "El riesgo operacional", "La potestad sancionadora"]'::jsonb,2,'Arts. 14.4 y 15.2 LCSP','El concesionario asume el riesgo operacional en la explotación.',null),
('adm-cm:18-ec3108c7bd','adm-cm',18,'La inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acredita, salvo prueba en contrario:','["Las condiciones de aptitud del empresario frente a todos los órganos de contratación del sector público", "Que la empresa ha constituido la garantía definitiva exigida", "Las condiciones de aptitud del empresario solo frente a los órganos de contratación de la Administración General del Estado", "Las condiciones de aptitud del empresario, pero solo frente a los órganos de contratación de la Administración General del Estado"]'::jsonb,0,'Art. 96.1 LCSP','Acredita personalidad, capacidad, representación, solvencia y ausencia de prohibiciones.',null),
('adm-cm:18-7a7a1856fa','adm-cm',18,'Las entidades del sector público no podrán celebrar otros contratos que:','["Aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales", "Los que apruebe previamente el Parlamento", "Los que demanden los ciudadanos a través de los procesos de participación ciudadana y presupuestos participativos", "Los que superen 40.000 euros y estén previstos en el plan anual de contratación aprobado por el órgano"]'::jsonb,0,'Art. 28.1 LCSP','Principio de necesidad e idoneidad del contrato.',null),
('adm-cm:18-b16939de41','adm-cm',18,'Según el art. 197 LCSP, la ejecución del contrato se realizará:','["A riesgo y ventura del contratista", "A riesgo del responsable del contrato", "A riesgo de la Administración", "A riesgo compartido al 50 %"]'::jsonb,0,'Art. 197 LCSP','Sin perjuicio de lo previsto para el contrato de obras en el art. 239.',null),
('adm-cm:18-b35a308833','adm-cm',18,'Están sujetos a regulación armonizada los contratos de obras y concesiones de valor estimado igual o superior a:','["5.404.000 euros", "1.000.000 euros", "750.000 euros", "216.000 euros"]'::jsonb,0,'Art. 20.1 LCSP','Umbral vigente según el texto consolidado del BOE (los umbrales se revisan periódicamente).',null),
('adm-cm:18-c65b110247','adm-cm',18,'Para que un ente sea medio propio personificado, más del ___ de sus actividades deben llevarse a cabo en el ejercicio de los cometidos que le confíe el poder adjudicador:','["50 %", "80 %", "100 %", "20 %"]'::jsonb,1,'Art. 32.2 b) LCSP','Más del 80 % de su actividad debe dirigirse al poder adjudicador que lo controla.',null),
('adm-cm:18-3095be0dc6','adm-cm',18,'En la concesión de obras, la contraprestación a favor del concesionario consiste en:','["Un precio fijo pagado por adelantado por la Administración, sin derecho a explotar la obra", "Una subvención anual a cargo de la Administración concedente, sin derecho a explotar la obra", "El derecho a explotar la obra, o dicho derecho acompañado del de percibir un precio", "La propiedad de la obra"]'::jsonb,2,'Art. 14.1 LCSP','La concesión implica la transferencia del riesgo operacional al concesionario.',null),
('adm-cm:18-879974a0b2','adm-cm',18,'Si transcurren dos meses desde la interposición del recurso especial sin que se notifique su resolución:','["Se prorroga otros dos meses", "El contrato se anula", "Se entiende estimado por silencio administrativo y la adjudicación queda sin efecto, debiendo el órgano de contratación adjudicar al siguiente licitador", "El interesado podrá considerarlo desestimado a efectos de interponer recurso contencioso-administrativo"]'::jsonb,3,'Art. 57.5 LCSP','El silencio en el recurso especial es desestimatorio.',null),
('adm-cm:18-c65937e21a','adm-cm',18,'Si el licitador propuesto no cumplimenta adecuadamente el requerimiento de documentación en plazo, se le exigirá una penalidad del:','["10 % del precio de adjudicación", "3 % del presupuesto base de licitación, IVA excluido", "1 % del valor estimado", "5 % del presupuesto base de licitación, IVA incluido"]'::jsonb,1,'Art. 150.2 LCSP','Se entiende que ha retirado su oferta.',null),
('adm-cm:18-436484a1b4','adm-cm',18,'Los expedientes de resolución contractual deberán ser instruidos y resueltos en el plazo máximo de:','["Ocho meses", "Tres meses", "Un año", "Seis meses"]'::jsonb,0,'Art. 212.8 LCSP','Plazo máximo de ocho meses.',null),
('adm-cm:18-13d3c51f1f','adm-cm',18,'Los órganos de contratación designarán un responsable del contrato al que corresponderá:','["Fijar el precio del contrato y resolver las reclamaciones de los licitadores sobre la adjudicación, previo informe de la mesa de contratación y de los servicios jurídicos", "Resolver el recurso especial", "Supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias para asegurar la correcta realización de la prestación", "Adjudicar el contrato, fijar el precio de licitación y resolver el recurso especial en materia de contratación que interpongan los licitadores excluidos"]'::jsonb,2,'Art. 62.1 LCSP','Su designación es obligatoria.',null),
('adm-cm:18-dfa081f95e','adm-cm',18,'Las penalidades por demora en la ejecución, salvo que el pliego disponga otras, serán diarias en la proporción de:','["0,10 euros por cada 1.000 euros", "1 euro por cada 100 euros", "5 euros por cada 1.000 euros del precio del contrato, IVA incluido", "0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido"]'::jsonb,3,'Art. 193.3 LCSP','Cada vez que las penalidades alcancen un múltiplo del 5 % del precio se puede resolver el contrato.',null),
('adm-cm:18-0593415104','adm-cm',18,'Si se interpone recurso especial contra la adjudicación, como regla general:','["El recurso no produce efectos suspensivos", "Quedará en suspenso la tramitación del procedimiento", "La adjudicación se anula automáticamente y se retrotrae el procedimiento", "El contrato se formaliza igualmente"]'::jsonb,1,'Art. 53 LCSP','Salvo en contratos basados en acuerdos marco o sistemas dinámicos de adquisición.',null),
('adm-cm:18-273706328f','adm-cm',18,'El procedimiento abierto simplificado puede utilizarse en contratos de obras de valor estimado igual o inferior a:','["2.000.000 de euros", "5.538.000 euros", "500.000 euros, IVA excluido", "100.000 euros, IVA excluido"]'::jsonb,0,'Art. 159.1 LCSP','Para suministros y servicios hay un umbral inferior.',null),
('adm-cm:18-ffda3c8c30','adm-cm',18,'Contra la resolución del recurso especial en materia de contratación:','["Solo procederá la interposición de recurso contencioso-administrativo", "Cabe recurso de alzada ante el titular del departamento", "Cabe recurso potestativo de reposición ante el mismo tribunal administrativo, y después recurso contencioso-administrativo", "No cabe ningún recurso"]'::jsonb,0,'Art. 59.1 LCSP','La resolución es directamente ejecutiva.',null),
('adm-cm:18-fabd225b73','adm-cm',18,'En los contratos de servicios del anexo IV y en los que tengan por objeto prestaciones de carácter intelectual, los criterios relacionados con la calidad deben representar, al menos:','["El 51 % de la puntuación asignable", "El 30 % de la puntuación asignable", "El 75 % de la puntuación asignable", "El 40 % de la puntuación asignable"]'::jsonb,0,'Art. 145.4 LCSP','Garantiza que la calidad pese más que el precio en esos contratos.',null),
('adm-cm:18-770e7dcbd2','adm-cm',18,'NO procede el recurso especial en materia de contratación respecto de los procedimientos de adjudicación que se sigan:','["Mediante procedimiento restringido", "Mediante procedimiento abierto", "Por el trámite de emergencia", "En contratos de servicios"]'::jsonb,2,'Art. 44.4 LCSP','No cabe recurso especial en la tramitación de emergencia.',null),
('adm-cm:18-c0fd228e6e','adm-cm',18,'Si la demora en el pago por la Administración fuese superior a seis meses, el contratista tendrá derecho a:','["Ceder el contrato a un tercero sin necesidad de autorización del órgano de contratación", "Resolver el contrato y al resarcimiento de los perjuicios", "Una prórroga del contrato por un plazo igual al de la demora", "Suspender la ejecución, pero no resolver el contrato"]'::jsonb,1,'Art. 198.6 LCSP','Si la demora supera cuatro meses puede suspender el cumplimiento del contrato.',null),
('adm-cm:18-25de464a2d','adm-cm',18,'La garantía complementaria que puede exigirse en casos especiales puede ser de hasta un 5 %, de modo que la garantía total pueda alcanzar:','["Un 15 % del precio del contrato", "Un 8 % del precio del contrato, IVA incluido", "Un 10 % del precio del contrato", "Un 20 % del precio del contrato"]'::jsonb,2,'Art. 107.2 LCSP','La garantía definitiva ordinaria es del 5 % y la complementaria hasta otro 5 %.',null),
('adm-cm:18-73a660e2ef','adm-cm',18,'La Administración tiene la obligación de abonar el precio dentro de los ___ siguientes a la fecha de aprobación de las certificaciones o documentos de conformidad:','["Noventa días", "Quince días", "Sesenta días", "Treinta días"]'::jsonb,3,'Art. 198.4 LCSP','Si se retrasa, debe abonar intereses de demora y la indemnización por costes de cobro.',null),
('adm-cm:18-7b54871c37','adm-cm',18,'Contra las actuaciones susceptibles de recurso especial en materia de contratación:','["No procederá la interposición de recursos administrativos ordinarios", "Cabe además recurso de alzada ante el titular del departamento ministerial", "Cabe recurso de reposición obligatorio, previo al recurso especial", "Cabe recurso extraordinario de revisión previo, en los supuestos del art. 125 de la Ley 39/2015"]'::jsonb,0,'Art. 44.5 LCSP','El recurso especial sustituye a los recursos ordinarios.',null),
('adm-cm:18-4f0bc53586','adm-cm',18,'¿Puede prorrogarse un contrato por consentimiento tácito de las partes?','["Sí, si lo autoriza el responsable del contrato", "Sí, siempre", "Sí, si es un contrato menor", "No, en ningún caso"]'::jsonb,3,'Art. 29.2 LCSP','La prórroga la acuerda el órgano de contratación y nunca es tácita.',null),
('adm-cm:18-d24fc36791','adm-cm',18,'Es una prohibición de contratar del art. 71.1:','["Haber sido adjudicatario de otro contrato con la misma Administración en los últimos tres años", "Tener menos de diez trabajadores", "Haber sido condenado mediante sentencia firme por determinados delitos, como cohecho o prevaricación", "No disponer de sede social en España"]'::jsonb,2,'Art. 71.1 a) LCSP','Otras: sanciones firmes, concurso, incumplimiento de obligaciones tributarias o de Seguridad Social…',null),
('adm-cm:18-f546d94349','adm-cm',18,'Cada una de las penalidades no podrá ser superior al ___ del precio del contrato, ni el total superar el 50 %:','["5 %", "20 %", "10 %", "30 %"]'::jsonb,2,'Art. 192.1 LCSP','Límites de las penalidades contractuales.',null),
('adm-cm:18-73e7bd9ce1','adm-cm',18,'En los contratos de las Administraciones Públicas, el pago aplazado del precio:','["Está prohibido, salvo excepciones como el arrendamiento financiero", "Está permitido siempre que lo acepte el contratista", "Solo se permite en contratos menores y en los de suministro de bienes", "Es obligatorio en los contratos de obras de valor estimado superior a 5.000.000 de euros"]'::jsonb,0,'Art. 102.8 LCSP','Se prohíbe salvo los supuestos legalmente previstos.',null),
('adm-cm:19-40e3185a45','adm-cm',19,'Según la Ley 38/2003, General de Subvenciones, ¿cuál de los siguientes es un requisito del concepto de subvención?','["Que la entrega se formalice mediante convenio con el beneficiario", "Que el importe no supere el crédito anual del órgano concedente", "Que la entrega se realice a favor de personas privadas exclusivamente, nunca públicas", "Que la entrega se realice sin contraprestación directa de los beneficiarios"]'::jsonb,3,'Art. 2.1 Ley 38/2003','El art. 2.1 a) exige que la entrega se realice sin contraprestación directa de los beneficiarios; además, puede hacerse a personas públicas o privadas.',null),
('adm-cm:19-195db67ecc','adm-cm',19,'Según la Ley 38/2003, ¿tienen carácter de subvención los beneficios fiscales?','["Solo cuando los otorga una entidad local", "Sí, si están previstos nominativamente en los presupuestos", "Sí, cuando se conceden en concurrencia competitiva", "No, la ley los excluye expresamente"]'::jsonb,3,'Art. 2.4 Ley 38/2003','El art. 2.4 g) dice que no tienen carácter de subvenciones los beneficios fiscales ni los beneficios en la cotización a la Seguridad Social.',null),
('adm-cm:19-1d49d70512','adm-cm',19,'Según la Ley 38/2003, ¿qué deben concretar con carácter previo los órganos que propongan el establecimiento de subvenciones?','["Un programa anual de inspección financiera", "Un informe previo y favorable de la Intervención General de la Administración", "Un plan estratégico de subvenciones", "Una memoria de impacto normativo"]'::jsonb,2,'Art. 8.1 Ley 38/2003','Deberán concretar en un plan estratégico de subvenciones los objetivos y efectos, el plazo, los costes previsibles y sus fuentes de financiación.',null),
('adm-cm:19-47c45c23a7','adm-cm',19,'¿Cuál de estos principios de gestión de las subvenciones recoge expresamente el art. 8.3 de la Ley 38/2003?','["Discrecionalidad técnica del órgano concedente en la selección", "Eficiencia en la asignación y utilización de los recursos públicos", "Preferencia de las entidades sin ánimo de lucro", "Confidencialidad de los beneficiarios y de las cuantías concedidas"]'::jsonb,1,'Art. 8.3 Ley 38/2003','Los principios son publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación; eficacia en los objetivos y eficiencia en la asignación y utilización de los recursos públicos.',null),
('adm-cm:19-995ea6c628','adm-cm',19,'Según la Ley 38/2003, ¿qué debe aprobarse con carácter previo al otorgamiento de las subvenciones?','["Las normas que establezcan las bases reguladoras de concesión", "El informe del órgano colegiado de evaluación", "La resolución de concesión provisional, publicada junto con el extracto de la convocatoria", "La cuenta justificativa del ejercicio anterior presentada por los solicitantes"]'::jsonb,0,'Art. 9.2 Ley 38/2003','Con carácter previo al otorgamiento deben aprobarse las normas que establezcan las bases reguladoras de concesión.',null),
('adm-cm:19-f53a359c53','adm-cm',19,'¿Cuál de los siguientes NO figura entre los requisitos del otorgamiento de una subvención del art. 9.4 de la Ley 38/2003?','["La aceptación previa por escrito de todos los solicitantes", "La aprobación del gasto por el órgano competente", "La competencia del órgano administrativo concedente", "La existencia de crédito adecuado y suficiente"]'::jsonb,0,'Art. 9.4 Ley 38/2003','El art. 9.4 exige competencia del órgano, crédito adecuado y suficiente, tramitación conforme a las normas, fiscalización previa y aprobación del gasto.',null),
('adm-cm:19-25cccb6021','adm-cm',19,'Según la Ley 38/2003, ¿quién tiene la consideración de beneficiario de subvenciones?','["La entidad colaboradora que, actuando en nombre y por cuenta del órgano concedente, entrega y distribuye los fondos públicos", "Únicamente la persona jurídica que firma la solicitud", "La persona que haya de realizar la actividad que fundamentó su otorgamiento o que se encuentre en la situación que legitima su concesión", "Cualquier persona que haya presentado una solicitud admitida a trámite en plazo, aunque no realice la actividad"]'::jsonb,2,'Art. 11.1 Ley 38/2003','Así lo define el art. 11.1 de la Ley General de Subvenciones.',null),
('adm-cm:19-a217908fd0','adm-cm',19,'En una agrupación de personas sin personalidad beneficiaria de una subvención, ¿hasta cuándo no puede disolverse la agrupación?','["Hasta un año después de presentar la cuenta justificativa ante el órgano concedente", "Hasta que transcurra el plazo de prescripción de los arts. 39 y 65 de la ley", "Hasta que se dicte la resolución de concesión", "Hasta que se pague la totalidad de la subvención concedida a la agrupación"]'::jsonb,1,'Art. 11.3 Ley 38/2003','No podrá disolverse la agrupación hasta que haya transcurrido el plazo de prescripción previsto en los artículos 39 y 65.',null),
('adm-cm:19-d409a7148f','adm-cm',19,'Según la Ley 38/2003, ¿puede obtener la condición de beneficiario quien tenga la residencia fiscal en un paraíso fiscal?','["Solo con autorización del Consejo de Ministros", "Sí, si acredita estar al corriente con la Hacienda española", "Sí, salvo en las subvenciones de concesión directa", "No, es una de las prohibiciones del art. 13.2"]'::jsonb,3,'Art. 13.2 Ley 38/2003','El art. 13.2 f) impide obtener la condición de beneficiario a quien tenga la residencia fiscal en un país o territorio calificado reglamentariamente como paraíso fiscal.',null),
('adm-cm:19-6e0dd9fadc','adm-cm',19,'Si la prohibición de obtener subvenciones no deriva de sentencia firme, ¿cuál es su alcance máximo según la Ley 38/2003?','["Tres años", "Dos años", "Diez años", "Cinco años"]'::jsonb,3,'Art. 13.5 Ley 38/2003','El alcance se fija según el procedimiento reglamentario, sin que pueda exceder de cinco años cuando la prohibición no derive de sentencia firme.',null),
('adm-cm:19-27f3c19efa','adm-cm',19,'Para subvenciones de importe superior a 30.000 euros, ¿qué deben acreditar las empresas sujetas a la Ley 3/2004 para ser beneficiarias?','["Que no han recibido otras ayudas en el mismo ejercicio", "Que cumplen los plazos de pago a proveedores de la ley de morosidad", "Que han auditado sus cuentas de los tres últimos ejercicios", "Que tienen una plantilla mínima de diez trabajadores"]'::jsonb,1,'Art. 13.3 bis Ley 38/2003','El apartado 3 bis exige acreditar el cumplimiento de los plazos de pago de la Ley 3/2004, de lucha contra la morosidad.',null),
('adm-cm:19-eb1615b4c6','adm-cm',19,'¿Cuándo debe comunicar el beneficiario la obtención de otras subvenciones que financien la misma actividad?','["Tan pronto como se conozca y, en todo caso, antes de la justificación de los fondos", "Solo si lo pide expresamente el órgano concedente", "Al finalizar el plazo de ejecución de la actividad, junto con la memoria final de actuación", "En el plazo de un mes desde la resolución de concesión"]'::jsonb,0,'Art. 14.1 Ley 38/2003','El art. 14.1 d) obliga a comunicarlo tan pronto como se conozca y, en todo caso, con anterioridad a la justificación de la aplicación dada a los fondos percibidos.',null),
('adm-cm:19-a309889884','adm-cm',19,'En el ámbito de la Administración General del Estado, ¿cómo se aprueban las bases reguladoras de las subvenciones?','["Por real decreto del Consejo de Ministros, a propuesta del ministro de Hacienda y previo informe del Consejo de Estado", "Por resolución del secretario de Estado de Presupuestos", "Por orden ministerial, previo informe de los servicios jurídicos y de la Intervención Delegada", "Por acuerdo de la Comisión Delegada para Asuntos Económicos"]'::jsonb,2,'Art. 17.1 Ley 38/2003','Las bases se aprueban por orden ministerial, previo informe de los servicios jurídicos y de la Intervención Delegada, y se publican en el BOE.',null),
('adm-cm:19-c65ccb5055','adm-cm',19,'¿Cómo deben aprobar las corporaciones locales las bases reguladoras de sus subvenciones?','["Mediante resolución de la junta de gobierno local, sin necesidad de ordenanza", "Por acuerdo del pleno publicado solo en el tablón de anuncios de la corporación local", "Por decreto del alcalde o del presidente", "En el marco de las bases de ejecución del presupuesto, mediante una ordenanza general o específica"]'::jsonb,3,'Art. 17.2 Ley 38/2003','Se aprueban en el marco de las bases de ejecución del presupuesto, a través de una ordenanza general de subvenciones o una ordenanza específica.',null),
('adm-cm:19-700c54ea05','adm-cm',19,'Según la Ley 38/2003, ¿cuál es el procedimiento ordinario de concesión de subvenciones?','["La concurrencia competitiva", "La adjudicación por sorteo público", "La concesión por orden de presentación de solicitudes", "La concesión directa"]'::jsonb,0,'Art. 22.1 Ley 38/2003','El procedimiento ordinario se tramita en régimen de concurrencia competitiva, comparando solicitudes según criterios de valoración previamente fijados.',null),
('adm-cm:19-e8be9c0dbd','adm-cm',19,'En la concurrencia competitiva, ¿quién formula la propuesta de concesión al órgano concedente?','["Una comisión formada por los propios solicitantes", "Un órgano colegiado a través del órgano instructor", "La Intervención Delegada, tras fiscalizar las solicitudes presentadas", "El órgano instructor sin intervención de ningún otro"]'::jsonb,1,'Art. 22.1 Ley 38/2003','La propuesta se formula al órgano concedente por un órgano colegiado a través del órgano instructor; su composición la fijan las bases.',null),
('adm-cm:19-c38456e0e9','adm-cm',19,'¿Cuál de estas subvenciones puede concederse de forma directa según la Ley 38/2003?','["Las solicitadas fuera de plazo por causa justificada", "Todas las que conceda una entidad local", "Las previstas nominativamente en los presupuestos", "Las de importe inferior a 3.000 euros"]'::jsonb,2,'Art. 22.2 Ley 38/2003','Pueden concederse de forma directa las nominativas, las impuestas por norma con rango de ley y, excepcionalmente, las que acrediten razones de interés público, social, económico o humanitario.',null),
('adm-cm:19-6b542496f2','adm-cm',19,'Durante la instrucción, ¿cuál es el plazo general para emitir los informes que pida el órgano instructor?','["15 días", "5 días", "10 días", "Un mes"]'::jsonb,2,'Art. 24.3 Ley 38/2003','El plazo es de 10 días, salvo que el instructor pida un plazo menor o mayor, que en este caso no puede exceder de dos meses.',null),
('adm-cm:19-1fcd24d5db','adm-cm',19,'Notificada la propuesta de resolución provisional, ¿de qué plazo disponen los interesados para presentar alegaciones?','["5 días", "10 días", "20 días", "15 días"]'::jsonb,1,'Art. 24.4 Ley 38/2003','La propuesta de resolución provisional se notifica a los interesados y se concede un plazo de 10 días para presentar alegaciones.',null),
('adm-cm:19-4020b462c4','adm-cm',19,'¿Crean derecho a favor del beneficiario las propuestas de resolución provisional y definitiva?','["No, mientras no se le haya notificado la resolución de concesión", "Sí, si el beneficiario ya ha comunicado su aceptación de la propuesta en el plazo previsto", "Sí, desde que se notifica la propuesta definitiva, aunque aún no se haya dictado la resolución", "Solo la definitiva, cuando no hubo trámite de audiencia"]'::jsonb,0,'Art. 24.6 Ley 38/2003','Las propuestas no crean derecho alguno frente a la Administración mientras no se haya notificado la resolución de concesión.',null),
('adm-cm:19-79f13d081d','adm-cm',19,'Salvo norma con rango de ley o normativa de la UE, ¿cuál es el plazo máximo para resolver y notificar el procedimiento de concesión?','["Tres meses", "Cuatro meses", "Un año", "Seis meses"]'::jsonb,3,'Art. 25.4 Ley 38/2003','El plazo máximo no puede exceder de seis meses y se computa desde la publicación de la convocatoria, salvo que esta posponga sus efectos.',null),
('adm-cm:19-9319f3534d','adm-cm',19,'Si vence el plazo máximo sin notificar la resolución de concesión, ¿cómo puede entenderse la solicitud?','["Estimada por silencio administrativo", "Caducada, con archivo de las actuaciones", "Estimada solo si la convocatoria lo prevé", "Desestimada por silencio administrativo"]'::jsonb,3,'Art. 25.5 Ley 38/2003','El vencimiento del plazo legitima a los interesados para entender desestimada por silencio administrativo la solicitud de concesión.',null),
('adm-cm:19-7c4560f7f4','adm-cm',19,'A falta de previsión en las bases reguladoras, ¿en qué plazo máximo debe presentarse la cuenta justificativa?','["Tres meses desde la finalización del plazo para realizar la actividad", "Un mes desde la notificación de la resolución de concesión", "Dos meses desde la finalización de la actividad", "Seis meses desde el cobro efectivo de la subvención"]'::jsonb,0,'Art. 30.2 Ley 38/2003','La cuenta se presentará, como máximo, en el plazo de tres meses desde la finalización del plazo para la realización de la actividad.',null),
('adm-cm:19-f37b749101','adm-cm',19,'En la adquisición de bienes inmuebles con una subvención, ¿qué debe aportarse además de las facturas?','["Nota simple del Catastro", "Escritura pública inscrita en el Registro de la Propiedad del lugar donde radique el inmueble", "Certificado de tasador independiente inscrito en el registro oficial", "Informe del arquitecto municipal"]'::jsonb,2,'Art. 30.5 Ley 38/2003','Debe aportarse certificado de tasador independiente debidamente acreditado e inscrito en el correspondiente registro oficial.',null),
('adm-cm:19-bc3b799b99','adm-cm',19,'Según la Ley 38/2003, ¿cuál es una causa de nulidad de la resolución de concesión, además de las generales del procedimiento administrativo?','["La justificación insuficiente de la subvención", "La carencia o insuficiencia de crédito", "El incumplimiento de las medidas de difusión", "La obtención de otras ayudas, ingresos o recursos para la misma finalidad"]'::jsonb,1,'Art. 36.1 Ley 38/2003','Son causas de nulidad las generales de la ley de procedimiento y la carencia o insuficiencia de crédito.',null),
('adm-cm:19-a37a473ba8','adm-cm',19,'¿Cuál de las siguientes es una causa de reintegro según la Ley 38/2003?','["El incumplimiento de la obligación de justificación o la justificación insuficiente", "La carencia o insuficiencia de crédito", "La anulación de la convocatoria por defecto de forma en la publicación del extracto", "La falta de competencia del órgano concedente que dictó la resolución"]'::jsonb,0,'Art. 37.1 Ley 38/2003','El art. 37.1 c) incluye el incumplimiento de la obligación de justificación o la justificación insuficiente; la falta de crédito es causa de nulidad.',null),
('adm-cm:19-c3a31b22d7','adm-cm',19,'¿En qué plazo prescribe el derecho de la Administración a reconocer o liquidar el reintegro de una subvención?','["Cinco años", "Cuatro años", "Tres años", "Dos años"]'::jsonb,1,'Art. 39.1 Ley 38/2003','Prescribe a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro.',null),
('adm-cm:19-d2e5079e0b','adm-cm',19,'En las subvenciones concedidas por la concurrencia de una situación en el perceptor, ¿desde cuándo se computa la prescripción del reintegro?','["Desde la publicación de la convocatoria", "Desde el pago de la subvención", "Desde que venció el plazo de justificación", "Desde el momento de la concesión"]'::jsonb,3,'Art. 39.2 Ley 38/2003','En el supuesto del art. 30.7 el plazo se computa desde el momento de la concesión.',null),
('adm-cm:20-593f7e2b5c','adm-cm',20,'La información de publicidad activa debe publicarse:','["En las sedes electrónicas o páginas web, de forma clara y estructurada, preferiblemente en formatos reutilizables", "En el boletín oficial correspondiente y, si el organismo dispone de ella, también en su página web, en formato no reutilizable", "En el tablón de anuncios físico de cada organismo y en su sede electrónica, en formato papel", "En la página web, pero solo a petición del interesado y en el formato que este elija, sin obligación de que sean reutilizables ni de actualizarla periódicamente"]'::jsonb,0,'Art. 5.4 Ley 19/2013','Se publica en las sedes electrónicas o páginas web, de manera clara, estructurada y entendible, y preferiblemente en formatos reutilizables.',null),
('adm-cm:20-d1d5898c53','adm-cm',20,'El Portal de la Transparencia de la Administración General del Estado depende:','["Del Consejo de Transparencia y Buen Gobierno", "Del Ministerio de la Presidencia", "Del Defensor del Pueblo", "De las Cortes Generales"]'::jsonb,1,'Art. 10.1 Ley 19/2013','El Portal de la Transparencia depende del Ministerio de la Presidencia.',null),
('adm-cm:20-1e5037e2d1','adm-cm',20,'¿Quién tiene derecho a acceder a la información pública según la Ley 19/2013?','["Los ciudadanos españoles y los extranjeros residentes legalmente en España", "Solo quienes tengan la condición de interesados en un procedimiento administrativo", "Todas las personas, en los términos del art. 105.b) de la Constitución", "Los mayores de edad empadronados en España, en los términos de la Ley 39/2015"]'::jsonb,2,'Art. 12 Ley 19/2013','Todas las personas tienen derecho a acceder a la información pública, en los términos del art. 105.b) de la Constitución.','abr. 2026 · 1.er ejercicio'),
('adm-cm:20-37085b21c4','adm-cm',20,'Según la Ley 19/2013, se entiende por información pública:','["Los documentos publicados en el BOE y en los boletines autonómicos y provinciales", "Los contenidos o documentos en poder de los sujetos obligados, cualquiera que sea su origen, autor o finalidad, incluidos los privados", "Los documentos que los ciudadanos entregan a la Administración en un procedimiento", "Los contenidos o documentos en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones"]'::jsonb,3,'Art. 13 Ley 19/2013','Son los contenidos o documentos, cualquiera que sea su formato o soporte, en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones.',null),
('adm-cm:20-5b699f59ac','adm-cm',20,'Al presentar una solicitud de acceso a la información pública, el solicitante:','["No está obligado a motivarla", "Debe motivarla siempre", "Debe acreditar un interés legítimo", "Debe pagar una tasa previa"]'::jsonb,0,'Art. 17.3 Ley 19/2013','El solicitante no está obligado a motivar su solicitud, aunque puede exponer los motivos.',null),
('adm-cm:20-fbb8776634','adm-cm',20,'¿En qué plazo debe resolverse una solicitud de acceso a la información pública?','["Diez días desde su recepción por el órgano competente, ampliable por otros diez", "Un mes desde su recepción por el órgano competente, ampliable por otro mes", "Tres meses desde su presentación, ampliable por otros tres", "Quince días hábiles desde su presentación, sin posibilidad de ampliación"]'::jsonb,1,'Art. 20.1 Ley 19/2013','El plazo máximo es de un mes desde la recepción por el órgano competente, ampliable por otro mes por el volumen o la complejidad de la información.',null),
('adm-cm:20-b2a57fd8ae','adm-cm',20,'Si no se resuelve en plazo una solicitud de acceso a la información pública, se entiende:','["Estimada", "Caducada", "Desestimada", "Remitida al Consejo de Transparencia"]'::jsonb,2,'Art. 20.4 Ley 19/2013','Transcurrido el plazo sin resolución expresa, la solicitud se entiende desestimada.',null),
('adm-cm:20-0e5027600e','adm-cm',20,'El acceso a la información pública es:','["De pago, conforme a las tasas que fije cada Administración", "Gratuito sin excepción alguna, incluidas la expedición de copias y la transposición a otro formato", "Gratuito para las personas físicas y de pago para las empresas", "Gratuito, sin perjuicio de las exacciones por expedición de copias o cambio de formato"]'::jsonb,3,'Art. 22.4 Ley 19/2013','El acceso es gratuito, aunque pueden exigirse exacciones por la expedición de copias o la transposición a formatos distintos del original.',null),
('adm-cm:20-c58f86d54a','adm-cm',20,'La reclamación ante el Consejo de Transparencia y Buen Gobierno:','["Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es obligatoria y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de tres meses", "Sustituye al recurso contencioso-administrativo, y se presenta en el plazo de dos meses"]'::jsonb,0,'Art. 24 Ley 19/2013','Es potestativa y previa a la impugnación en vía contencioso-administrativa. Se presenta en el plazo de un mes.',null),
('adm-cm:20-e4bf4e607c','adm-cm',20,'¿En qué plazo debe resolver el Consejo de Transparencia y Buen Gobierno una reclamación?','["Un mes; transcurrido ese plazo sin resolución, se entiende estimada", "Tres meses; transcurrido ese plazo, se entiende desestimada", "Seis meses; transcurrido ese plazo, se entiende desestimada", "Tres meses; transcurrido ese plazo sin resolución expresa, se entiende estimada"]'::jsonb,1,'Art. 24.4 Ley 19/2013','El plazo máximo es de tres meses. Transcurrido sin resolución, la reclamación se entiende desestimada.','nov. 2024 · 1.er ejercicio'),
('adm-cm:20-c2db6420c6','adm-cm',20,'El Presidente del Consejo de Transparencia y Buen Gobierno es nombrado por un periodo de:','["Cuatro años renovables", "Seis años", "Cinco años no renovable", "Tres años renovables una vez"]'::jsonb,2,'Art. 37.1 Ley 19/2013','Es nombrado por un período no renovable de cinco años.',null),
('adm-cm:20-dec8c2d1bf','adm-cm',20,'¿Cuál de los siguientes es un límite al derecho de acceso a la información pública?','["Que el solicitante no motive su solicitud ni explique para qué la quiere", "Que la información tenga más de cinco años de antigüedad", "Que la información solo esté disponible en formato papel", "Que el acceso suponga un perjuicio para la seguridad nacional"]'::jsonb,3,'Art. 14.1 Ley 19/2013','Entre los límites están la seguridad nacional, la defensa y las relaciones exteriores, entre otros.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:20-613599b161','adm-cm',20,'Según la Ley 19/2013, el Consejo de Transparencia y Buen Gobierno es:','["Un organismo público con personalidad jurídica propia", "Una dirección general del Ministerio de Hacienda", "Un órgano de las Cortes Generales", "Un órgano del Poder Judicial"]'::jsonb,0,'Art. 33 Ley 19/2013','Es un organismo público con personalidad jurídica propia y plena capacidad de obrar.',null),
('adm-cm:20-20e6b072a5','adm-cm',20,'Las infracciones muy graves de buen gobierno de la Ley 19/2013 prescriben a los:','["Tres años", "Dos años", "Un año", "Cinco años"]'::jsonb,3,'Art. 32 Ley 19/2013','Las graves a los tres años y las leves al año.',null),
('adm-cm:20-27d4a6e072','adm-cm',20,'Entre la información económica que debe publicarse según el art. 8 de la Ley 19/2013 se encuentran:','["Los datos de salud y las bajas laborales de los empleados públicos de cada departamento", "Las nóminas de todos los funcionarios y del personal laboral, con su nombre y puesto de trabajo", "Las declaraciones del IRPF de los ciudadanos", "Las retribuciones percibidas anualmente por los altos cargos y máximos responsables"]'::jsonb,3,'Art. 8.1 f) Ley 19/2013','También contratos, convenios, subvenciones y presupuestos.',null),
('adm-cm:20-9351b63380','adm-cm',20,'Según la Ley 19/2013, la sanción por infracciones muy graves de buen gobierno incluye:','["Una multa de entre 600 y 6.000 euros y una amonestación pública en el boletín oficial correspondiente", "La destitución y la imposibilidad de ser nombrado alto cargo durante un periodo de entre cinco y diez años", "La suspensión de empleo por un día", "Una amonestación"]'::jsonb,1,'Art. 30 Ley 19/2013','Las infracciones leves se sancionan con amonestación.',null),
('adm-cm:20-b8a13bc6a8','adm-cm',20,'Según la Ley 19/2013, están obligadas a cumplir las obligaciones de publicidad activa las entidades privadas que perciban durante un año ayudas o subvenciones públicas en una cuantía superior a:','["10.000 euros", "100.000 euros", "50.000 euros", "1.000.000 de euros"]'::jsonb,1,'Art. 3 b) Ley 19/2013','O cuando al menos el 40 % de sus ingresos anuales tengan carácter de ayuda pública, con un mínimo de 5.000 euros.',null),
('adm-cm:20-4836f966bc','adm-cm',20,'El Consejo de Transparencia y Buen Gobierno se estructura en:','["Un Pleno y una Junta de Portavoces de los grupos parlamentarios del Congreso", "Una Sala de lo Contencioso y una Sala de lo Penal", "La Comisión de Transparencia y Buen Gobierno y el Presidente del Consejo", "Un Presidente, un Vicepresidente y una Secretaría General, con un Pleno de doce miembros"]'::jsonb,2,'Art. 35 Ley 19/2013','La Comisión incluye, entre otros, un Diputado y un Senador.',null),
('adm-cm:20-4270b68a73','adm-cm',20,'Forman parte de la Comisión de Transparencia y Buen Gobierno, entre otros:','["Un Diputado, un Senador, un representante del Tribunal de Cuentas y uno del Defensor del Pueblo", "Los Presidentes de las Comunidades Autónomas", "Los Alcaldes de capitales de provincia", "Un Diputado, un Senador, un representante del Consejo General del Poder Judicial y uno del Tribunal Supremo"]'::jsonb,0,'Art. 36.2 Ley 19/2013','También representantes de la AEPD, de la Secretaría de Estado de Administraciones Públicas y de la AIReF.',null),
('adm-cm:20-21942f985e','adm-cm',20,'Si la información solicitada puede afectar a derechos o intereses de terceros, se les concederá para alegaciones un plazo de:','["Cinco días", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 19.3 Ley 19/2013','El plazo para resolver se suspende hasta recibir las alegaciones o transcurrir el plazo.',null),
('adm-cm:20-047e1c7d52','adm-cm',20,'Según la Ley 19/2013, se inadmitirán a trámite las solicitudes de acceso:','["Presentadas por personas extranjeras no residentes en España o por quien no acredite un interés legítimo directo", "Que no estén motivadas o en las que el solicitante no acredite un interés directo en la información", "Relativas a información que tenga carácter auxiliar o de apoyo, como notas, borradores u opiniones", "Presentadas por personas jurídicas o por entidades sin personalidad jurídica"]'::jsonb,2,'Art. 18.1 b) Ley 19/2013','También las que requieran reelaboración, las referidas a información en elaboración o las manifiestamente repetitivas o abusivas.',null),
('adm-cm:20-ead047869c','adm-cm',20,'Si el acceso a la información no puede realizarse en el momento de la notificación de la resolución, deberá otorgarse en un plazo no superior a:','["Quince días", "Diez días", "Un mes", "Tres días"]'::jsonb,1,'Art. 22.1 Ley 19/2013','El acceso se realizará preferentemente por vía electrónica.',null),
('adm-cm:20-5aee0bb4fa','adm-cm',20,'Según el art. 23 de la Ley 19/2013, la reclamación ante el Consejo de Transparencia y Buen Gobierno:','["No tiene efectos", "Es previa y obligatoria al recurso de alzada", "Sustituye a los recursos administrativos", "Es posterior al recurso de reposición"]'::jsonb,2,'Art. 23.1 Ley 19/2013','Tiene la consideración de sustitutiva de los recursos administrativos.',null),
('adm-cm:20-fa929a46ce','adm-cm',20,'¿Qué ley estatal regula la transparencia de la actividad pública y el derecho de acceso a la información?','["La Ley 19/2013, de 9 de diciembre", "La LO 3/2018, de 5 de diciembre", "La Ley 39/2015, de 1 de octubre", "La Ley 37/2007, de 16 de noviembre"]'::jsonb,0,'Ley 19/2013','La Ley 37/2007 regula la reutilización de la información del sector público y la LO 3/2018, la protección de datos.',null),
('adm-cm:20-772db7a863','adm-cm',20,'Según el artículo 6 de la Ley 19/2013, los sujetos obligados deben publicar, como información institucional y organizativa:','["Las funciones que desarrollan, la normativa que les sea de aplicación y su estructura organizativa", "Los expedientes de los procedimientos sancionadores que tramiten", "Las retribuciones de todos los empleados públicos, con su nombre y apellidos", "Las actas completas de todas las reuniones de sus órganos colegiados"]'::jsonb,0,'Art. 6.1 Ley 19/2013','Incluyen un organigrama actualizado que identifique a los responsables de los diferentes órganos y su perfil y trayectoria profesional.',null),
('adm-cm:20-207ce7dc1d','adm-cm',20,'Según el artículo 7 de la Ley 19/2013, ¿qué información de relevancia jurídica debe publicarse?','["Los informes de los servicios jurídicos sobre cualquier asunto en tramitación", "Las denuncias presentadas por los ciudadanos contra las autoridades", "Los anteproyectos de ley y los proyectos de reglamento, entre otros documentos", "Las sentencias firmes dictadas contra la Administración en los últimos cinco años"]'::jsonb,2,'Art. 7 Ley 19/2013','También las directrices, instrucciones y circulares que supongan una interpretación del Derecho o tengan efectos jurídicos y las memorias e informes de los expedientes normativos.',null),
('adm-cm:20-1bbd52f6e0','adm-cm',20,'Según la Ley 19/2013, ¿deben publicarse las retribuciones percibidas anualmente por los altos cargos?','["Sí, como información económica, presupuestaria y estadística", "No, porque son datos personales protegidos", "Solo si lo solicita un ciudadano mediante el derecho de acceso", "Las de los Ministros y Secretarios de Estado, pero no las del resto"]'::jsonb,0,'Art. 8.1 f) Ley 19/2013','También se publican las indemnizaciones percibidas con ocasión del abandono del cargo.',null),
('adm-cm:20-94cc0c678e','adm-cm',20,'¿Cuándo entraron en vigor los títulos preliminar, I y III de la Ley 19/2013 para la Administración General del Estado?','["A los dos años de su publicación en el Boletín Oficial del Estado", "A los seis meses de su publicación en el Boletín Oficial del Estado", "Al año de su publicación en el Boletín Oficial del Estado", "Al día siguiente de su publicación en el Boletín Oficial del Estado"]'::jsonb,2,'Disposición final novena Ley 19/2013','El título II (buen gobierno) entró en vigor al día siguiente de su publicación. Las CCAA y Entidades Locales tuvieron dos años para adaptarse.',null),
('adm-cm:20-3770c8def7','adm-cm',20,'El título II de la Ley 19/2013 regula:','["El buen gobierno", "La publicidad activa", "El derecho de acceso a la información pública", "El Consejo de Transparencia y Buen Gobierno"]'::jsonb,0,'Ley 19/2013','El título I regula la transparencia (publicidad activa y derecho de acceso) y el título III el Consejo de Transparencia y Buen Gobierno.',null),
('adm-cm:20-5ab451fc23','adm-cm',20,'Cuando un límite al derecho de acceso no afecte a la totalidad de la información solicitada:','["Se deniega el acceso a la totalidad de la información, aunque el límite afecte solo a una parte de ella, para evitar que se conozca el resto", "Se remite la solicitud al Consejo de Transparencia y Buen Gobierno", "Se suspende el procedimiento hasta que el límite deje de aplicarse y se notifica esta circunstancia al solicitante y a los terceros afectados", "Se concede el acceso parcial, omitiendo la información afectada por el límite, salvo que resulte una información distorsionada o sin sentido"]'::jsonb,3,'Art. 16 Ley 19/2013','Debe indicarse al solicitante qué parte de la información ha sido omitida.',null),
('adm-cm:20-64ccb5b3f4','adm-cm',20,'Según la Ley 19/2013, la solicitud de acceso que se refiera a información cuya divulgación requiera una acción previa de reelaboración:','["Se inadmitirá a trámite mediante resolución motivada", "Se remitirá al órgano que elaboró la información originalmente", "Se tramitará con un plazo ampliado de tres meses", "Se estimará, pero el solicitante deberá abonar el coste de la reelaboración"]'::jsonb,0,'Art. 18.1 c) Ley 19/2013','Es una de las causas de inadmisión, junto con la información en curso de elaboración o de carácter auxiliar, entre otras.',null),
('adm-cm:20-899d51d7b6','adm-cm',20,'Si la solicitud de acceso se refiere a información que no obre en poder del sujeto al que se dirige:','["Este la archivará y el solicitante deberá presentar una nueva solicitud ante el órgano que corresponda", "Este deberá recabar la información del órgano que la posea y resolver la solicitud en el plazo ordinario", "Este la remitirá al competente, si lo conoce, e informará de esta circunstancia al solicitante", "Este la inadmitirá a trámite, aunque conozca cuál es el órgano o entidad competente para resolver"]'::jsonb,2,'Art. 19.1 Ley 19/2013','Si desconoce el órgano competente, procede la inadmisión.',null),
('adm-cm:20-06887cec03','adm-cm',20,'El plazo para resolver una solicitud de acceso a la información puede ampliarse:','["Por tres meses más, sin necesidad de comunicarlo previamente al solicitante, cuando así lo acuerde el titular del órgano que debe resolver", "No puede ampliarse, porque es un plazo improrrogable", "Por otro mes, en el caso de que el volumen o la complejidad de la información lo hagan necesario, previa notificación al solicitante", "Por quince días hábiles, solo si hay terceros afectados"]'::jsonb,2,'Art. 20.1 Ley 19/2013','El plazo ordinario es de un mes desde la recepción de la solicitud por el órgano competente.',null),
('adm-cm:20-e6afd1355f','adm-cm',20,'Según la Ley 19/2013, ¿qué resoluciones sobre el derecho de acceso deben ser motivadas?','["Las que denieguen totalmente el acceso a la información", "Todas las resoluciones, tanto si conceden como si deniegan el acceso", "Las que denieguen el acceso, las que concedan el acceso parcial o a través de una modalidad distinta a la solicitada y las que permitan el acceso con oposición de un tercero", "Las que concedan el acceso, porque afectan a la confidencialidad de la información"]'::jsonb,2,'Art. 20.2 Ley 19/2013','Así lo exige el artículo 20.2.',null),
('adm-cm:20-73d48b5738','adm-cm',20,'El acceso a la información pública, según la Ley 19/2013:','["Es gratuito, aunque la expedición de copias o la transposición a formatos diferentes del original puede dar lugar a exacciones", "Es gratuito solo para los ciudadanos españoles residentes en España", "Está sujeto al pago de una tasa por cada solicitud presentada, cuya cuantía fija cada año la Ley de Presupuestos Generales del Estado", "Es gratuito, incluida también la expedición de copias en papel o en soporte electrónico y la transposición a otros formatos"]'::jsonb,0,'Art. 22.4 Ley 19/2013','La forma preferente de acceso es la electrónica.',null),
('adm-cm:20-f14b7667e0','adm-cm',20,'¿Qué unidades deben existir en la Administración General del Estado para facilitar el conocimiento y acceso a la información pública?','["Delegaciones de protección de datos", "Unidades de información", "Oficinas de asistencia en materia de registros", "Inspecciones generales de servicios"]'::jsonb,1,'Art. 21 Ley 19/2013','Se encargan, entre otras funciones, de recabar y difundir la información de publicidad activa y de recibir y tramitar las solicitudes de acceso.',null),
('adm-cm:20-679ff93db4','adm-cm',20,'Según la Ley 19/2013, la información de publicidad activa se publicará:','["De forma periódica y actualizada, en las sedes electrónicas o páginas web, de una manera clara, estructurada y entendible y preferiblemente en formatos reutilizables", "Cuando lo solicite cualquier ciudadano por escrito", "Una vez al año, en el Boletín Oficial del Estado y en los diarios oficiales de las Comunidades Autónomas, en un anexo específico que recoja toda la información obligatoria", "En el tablón de anuncios físico de cada órgano"]'::jsonb,0,'Arts. 5.1 y 5.4 Ley 19/2013','Se establecen los mecanismos adecuados para facilitar la accesibilidad, la interoperabilidad y la calidad de la información.',null),
('adm-cm:20-b2d42a2422','adm-cm',20,'Según el artículo 26 de la Ley 19/2013, ¿cuál de los siguientes es un principio general de actuación de los altos cargos?','["Mantener en secreto todas sus reuniones con grupos de interés", "Actuar con transparencia en la gestión de los asuntos públicos", "Afiliarse obligatoriamente a un partido político", "Percibir una retribución acorde con la de su sector privado de origen"]'::jsonb,1,'Art. 26.2 a) Ley 19/2013','Otros principios son la dedicación al servicio público, la imparcialidad, la igualdad de trato y la diligencia.',null),
('adm-cm:21-8aa274255b','adm-cm',21,'La Ley Orgánica 3/2007 tiene por objeto:','["Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres", "Establecer medidas de protección integral contra la violencia de género y de igualdad de oportunidades en el empleo", "Hacer efectivo el derecho de igualdad de trato entre mujeres y hombres, pero solo en el ámbito del empleo público y de la negociación colectiva", "Regular la igualdad de trato y la no discriminación por cualquier circunstancia personal"]'::jsonb,0,'Art. 1.1 LO 3/2007','Su objeto es hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres.',null),
('adm-cm:21-2252623534','adm-cm',21,'El principio de igualdad de trato entre mujeres y hombres supone:','["La igualdad en el ámbito laboral y en el acceso al empleo", "La ausencia de toda discriminación, directa o indirecta, por razón de sexo", "La ausencia de discriminación directa por razón de sexo, pero no de la indirecta, que se rige por la normativa laboral", "La paridad obligatoria en todos los órganos públicos y privados, con independencia de su composición"]'::jsonb,1,'Art. 3 LO 3/2007','Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, especialmente por maternidad, obligaciones familiares y estado civil.','abr. 2026 · 1.er ejercicio'),
('adm-cm:21-3ac2278c37','adm-cm',21,'Se considera discriminación directa por razón de sexo la situación en que una persona:','["Recibe una medida de acción positiva destinada a corregir situaciones de desigualdad", "Es tratada igual que otra persona en una situación distinta", "Es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable", "Sufre una desventaja particular respecto de personas del otro sexo por una disposición, criterio o práctica aparentemente neutros"]'::jsonb,2,'Art. 6.1 LO 3/2007','Es la situación de quien es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable. El trato por disposición aparentemente neutra es la discriminación indirecta.',null),
('adm-cm:21-7e55e7f095','adm-cm',21,'El acoso sexual es cualquier comportamiento, verbal o físico, de naturaleza sexual que:','["Se produzca fuera del lugar de trabajo", "Se repita al menos tres veces y lo denuncie la persona afectada o un tercero", "Produzca una lesión física acreditada", "Tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona"]'::jsonb,3,'Art. 7.1 LO 3/2007','Tiene el propósito o produce el efecto de atentar contra la dignidad de una persona, en particular cuando crea un entorno intimidatorio, degradante u ofensivo.',null),
('adm-cm:21-79931ad6bf','adm-cm',21,'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:','["Discriminación directa por razón de sexo", "Discriminación indirecta por razón de sexo, salvo que la empresa acredite una justificación objetiva", "Acoso por razón de sexo", "Una infracción laboral leve"]'::jsonb,0,'Art. 8 LO 3/2007','Constituye discriminación directa por razón de sexo.',null),
('adm-cm:21-e634868f98','adm-cm',21,'Según la LO 3/2007, el principio de igualdad de trato y oportunidades informará la actuación de todos los Poderes Públicos con carácter:','["Excepcional", "Transversal", "Subsidiario", "Voluntario"]'::jsonb,1,'Art. 15 LO 3/2007','Informará, con carácter transversal, la actuación de todos los Poderes Públicos.',null),
('adm-cm:21-521a224df1','adm-cm',21,'¿Qué empresas deben elaborar y aplicar un plan de igualdad?','["Todas, cualquiera que sea su plantilla", "Las de más de 250 trabajadores", "Las de cincuenta o más trabajadores", "Solo las empresas públicas y las que contraten con la Administración, cualquiera que sea su plantilla"]'::jsonb,2,'Art. 45.2 LO 3/2007','Las empresas de cincuenta o más trabajadores.',null),
('adm-cm:21-b8aed379b6','adm-cm',21,'Según la LO 3/2007, hay composición equilibrada cuando las personas de cada sexo:','["Son exactamente el 50 %", "No superan el 70 % ni son menos del 30 %", "No superan el 55 % ni son menos del 45 %", "No superan el 60 % ni son menos del 40 %"]'::jsonb,3,'Disp. adicional 1.ª LO 3/2007','Las personas de cada sexo no superan el sesenta por ciento ni son menos del cuarenta por ciento.',null),
('adm-cm:21-ad7bd60a80','adm-cm',21,'La LO 1/2004 actúa contra la violencia que se ejerce sobre las mujeres por parte de quienes sean o hayan sido sus cónyuges o parejas:','["Aun sin convivencia", "Solo si conviven", "Solo si están casados", "Solo si hay hijos en común"]'::jsonb,0,'Art. 1.1 LO 1/2004','Comprende a quienes sean o hayan sido sus cónyuges o hayan estado ligados por relaciones similares de afectividad, aun sin convivencia.','nov. 2024 · 1.er ejercicio'),
('adm-cm:21-f366ff5ea3','adm-cm',21,'Según la LO 1/2004, la violencia de género comprende:','["Solo la violencia física que cause lesiones", "Todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad", "Todo acto de violencia física, incluidas las agresiones a la libertad sexual, pero no la violencia psicológica, las amenazas ni las coacciones, que se rigen por el Código Penal", "Solo la violencia física ejercida en el domicilio familiar que cause lesiones acreditadas por un médico, excluidas las amenazas, las coacciones y la violencia psicológica"]'::jsonb,1,'Art. 1.3 LO 1/2004','Comprende todo acto de violencia física y psicológica, incluidas agresiones a la libertad sexual, amenazas, coacciones o privación arbitraria de libertad.',null),
('adm-cm:21-514cf58c29','adm-cm',21,'¿Cuál de estos derechos tiene la trabajadora víctima de violencia de género?','["Una indemnización automática a cargo de su empresa", "El ascenso de categoría", "La reducción o reordenación de su tiempo de trabajo, la movilidad geográfica o la suspensión con reserva de puesto", "La reducción de jornada sin disminución proporcional del salario, la movilidad geográfica y el cambio de empresa dentro del grupo"]'::jsonb,2,'Art. 21.1 LO 1/2004','Tiene derecho, entre otros, a la reducción o reordenación de jornada, la movilidad geográfica, el cambio de centro, la suspensión con reserva de puesto y la extinción del contrato.',null),
('adm-cm:21-f26f2e40de','adm-cm',21,'Para acreditar la situación de violencia de género y acceder a los derechos laborales sirve, entre otros:','["Una declaración jurada de un vecino o familiar", "El certificado de empadronamiento junto con una declaración jurada de la propia trabajadora", "Un parte de lesiones expedido por una clínica privada sin intervención judicial ni fiscal", "La orden de protección o el informe del Ministerio Fiscal"]'::jsonb,3,'Art. 23 LO 1/2004','Se acredita con sentencia condenatoria, orden de protección, informe del Ministerio Fiscal, informe de los servicios sociales o especializados u otro título previsto.',null),
('adm-cm:21-4193a321a2','adm-cm',21,'La funcionaria víctima de violencia de género tiene derecho, entre otros, a:','["La excedencia, la reducción o reordenación de su tiempo de trabajo y la movilidad geográfica", "El cambio automático de cuerpo o escala", "Un permiso retribuido de un año, la reducción de jornada sin merma de retribuciones y la jubilación anticipada voluntaria", "La jubilación anticipada sin reducción de la pensión y un permiso retribuido de un año completo"]'::jsonb,0,'Art. 24 LO 1/2004','Tiene derecho a la reducción o reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia.',null),
('adm-cm:21-9f5b599c0b','adm-cm',21,'¿Qué órganos judiciales creó la LO 1/2004?','["Las Audiencias de Familia", "Los Juzgados de Violencia sobre la Mujer", "Los Tribunales de Igualdad", "Las Salas de Género del Tribunal Supremo"]'::jsonb,1,'Art. 43 LO 1/2004','Creó los Juzgados de Violencia sobre la Mujer, añadiendo el art. 87 bis a la LOPJ.',null),
('adm-cm:21-251e251706','adm-cm',21,'El Fiscal contra la Violencia sobre la Mujer:','["Es elegido por el Congreso por mayoría de tres quintos", "Depende orgánicamente del Ministerio de Igualdad, que lo nombra a propuesta del Consejo de Ministros", "Es nombrado, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala", "Es un fiscal de cada provincia"]'::jsonb,2,'Art. 70 LO 1/2004','Se nombra, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala.',null),
('adm-cm:21-19c27ac08a','adm-cm',21,'Según la Ley 4/2023, ¿a partir de qué edad puede una persona solicitar por sí misma la rectificación registral de la mención relativa al sexo?','["Doce años", "Catorce años", "Dieciocho años", "Dieciséis años"]'::jsonb,3,'Art. 43 Ley 4/2023','Las personas de nacionalidad española mayores de dieciséis años pueden solicitarla por sí mismas.',null),
('adm-cm:21-3ecd683a77','adm-cm',21,'Según la Ley 4/2023, las personas mayores de 14 y menores de 16 años pueden solicitar la rectificación registral del sexo:','["Por sí mismas, asistidas por sus representantes legales", "Por sí mismas, sin necesidad de asistencia de sus representantes legales", "Solo mediante autorización judicial previa", "Solo a través de sus representantes legales, con informe médico"]'::jsonb,0,'Art. 43 Ley 4/2023','Pueden presentar la solicitud por sí mismas, asistidas por sus representantes legales.',null),
('adm-cm:21-6ba1d1de0a','adm-cm',21,'Según la Ley 4/2023, las personas mayores de 12 y menores de 14 años:','["Pueden solicitar la rectificación por sí mismas, asistidas por sus representantes legales", "Pueden solicitar la autorización judicial para la modificación", "No pueden solicitar ni la rectificación ni la autorización judicial hasta cumplir los catorce años", "Solo pueden cambiar el nombre"]'::jsonb,1,'Art. 43 Ley 4/2023','Pueden solicitar la autorización judicial para la modificación de la mención registral del sexo.',null),
('adm-cm:21-fcc5456e56','adm-cm',21,'¿Cuál es la ley integral contra la violencia de género de la Comunidad de Madrid?','["Ley Orgánica 1/2004, de 28 de diciembre", "Ley 3/2016, de 22 de julio, de Madrid", "Ley 5/2005, de 20 de diciembre", "Ley 2/2016, de 29 de marzo"]'::jsonb,2,'Ley 5/2005 CM','Es la Ley 5/2005, de 20 de diciembre, integral contra la violencia de género de la Comunidad de Madrid.',null),
('adm-cm:21-382f7c0afd','adm-cm',21,'Tras la reforma de la Ley 18/2023, la Ley 3/2016 de la Comunidad de Madrid se denomina:','["Ley de Protección Integral contra la LGTBIfobia y la Discriminación por Razón de Orientación e Identidad Sexual", "Ley de Identidad y Expresión de Género e Igualdad Social y no Discriminación", "Ley de Igualdad de Trato y no Discriminación por razón de orientación e identidad sexual de la Comunidad de Madrid", "Ley de protección, igualdad efectiva y no discriminación de las personas LGTBI de la Comunidad de Madrid"]'::jsonb,3,'Ley 3/2016 CM (modif. Ley 18/2023)','La Ley 18/2023, de 27 de diciembre, cambió su título por el de protección, igualdad efectiva y no discriminación de las personas LGTBI de la Comunidad de Madrid.',null),
('adm-cm:21-1f4b738aec','adm-cm',21,'El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado se aprueba por el Gobierno:','["Cada diez años", "Cada año", "Solo cuando lo pide el Congreso", "Al inicio de cada legislatura"]'::jsonb,3,'Art. 64 LO 3/2007','Su cumplimiento se evalúa anualmente por el Consejo de Ministros.',null),
('adm-cm:21-0e45795dec','adm-cm',21,'Según la LO 1/2004, la víctima de violencia de género tiene derecho a recibir asesoramiento jurídico gratuito:','["Solo si es funcionaria o empleada pública", "Solo después de que recaiga sentencia condenatoria firme contra el agresor", "En el momento inmediatamente previo a la interposición de la denuncia", "Solo si tiene hijos menores a su cargo"]'::jsonb,2,'Art. 20.1 LO 1/2004','También tienen derecho a defensa y representación gratuitas.',null),
('adm-cm:21-22a85654c7','adm-cm',21,'Según la LO 1/2004, en cada partido judicial habrá:','["Uno o más Juzgados de Violencia sobre la Mujer", "Un Juzgado de Paz especializado", "Un Tribunal de Violencia de Género con jurado", "Una Audiencia especializada"]'::jsonb,0,'Art. 43 LO 1/2004 (art. 87 bis LOPJ)','La LO 1/2004 añadió el art. 87 bis a la LOPJ.',null),
('adm-cm:21-cc4677f806','adm-cm',21,'En los litigios sobre acoso sexual y acoso por razón de sexo, está legitimada:','["Cualquier ciudadano", "Únicamente la persona acosada", "El sindicato mayoritario en todo caso", "El Ministerio Fiscal en exclusiva"]'::jsonb,1,'Art. 12.3 LO 3/2007','La persona acosada es la única legitimada.',null),
('adm-cm:21-c3d531d27e','adm-cm',21,'Según el art. 6.3 de la LO 3/2007, toda orden de discriminar, directa o indirectamente, por razón de sexo:','["Se considerará en todo caso discriminatoria", "No tiene relevancia jurídica si no llega a ejecutarse", "Solo es discriminatoria si se ejecuta", "Es válida si procede de un superior"]'::jsonb,0,'Art. 6.3 LO 3/2007','La orden de discriminar es en sí misma discriminación.',null),
('adm-cm:21-ec0fa733e6','adm-cm',21,'Las acciones positivas para hacer efectivo el derecho a la igualdad pueden adoptarlas:','["Solo el Gobierno y las Administraciones públicas", "Solo los jueces y tribunales en sus sentencias", "Solo las empresas de más de 250 trabajadores, dentro de su plan de igualdad negociado con la representación legal de los trabajadores", "Los poderes públicos y también las personas físicas y jurídicas privadas"]'::jsonb,3,'Art. 11 LO 3/2007','Deben ser razonables y proporcionadas.',null),
('adm-cm:21-434789799f','adm-cm',21,'La información a las víctimas de violencia de género sobre sus derechos se garantizará también a las mujeres que, por sus circunstancias personales y sociales, tengan dificultad de acceso, como:','["Solo las mujeres extranjeras en situación irregular", "Solo las empleadas públicas", "Solo las menores de edad, a través de sus representantes legales", "Las mujeres con discapacidad, en formato accesible"]'::jsonb,3,'Art. 18.2 LO 1/2004','También a quienes no dominen las lenguas oficiales (art. 18.3).',null),
('adm-cm:21-f7f5327c2d','adm-cm',21,'El Observatorio Estatal de Violencia sobre la Mujer es:','["Una organización no gubernamental de ámbito estatal declarada de utilidad pública", "Un órgano colegiado de asesoramiento, evaluación y colaboración institucional", "Una sección especializada de la Fiscalía", "Un juzgado especializado en violencia sobre la mujer con competencia en toda España"]'::jsonb,1,'Art. 30.1 LO 1/2004','Remite al Gobierno y a las CCAA un informe anual.',null),
('adm-cm:21-6891166660','adm-cm',21,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe del Consejo de Estado en todo caso", "Un informe sobre su impacto por razón de género", "Un informe económico de la UE", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('adm-cm:21-300099f705','adm-cm',21,'La suspensión y la extinción del contrato de trabajo de la trabajadora víctima de violencia de género:','["Darán lugar a situación legal de desempleo", "Requieren autorización judicial previa", "No dan derecho a prestación por desempleo, salvo que lo reconozca una sentencia", "Se consideran despido disciplinario"]'::jsonb,0,'Art. 21.2 LO 1/2004','El tiempo de suspensión se considera periodo de cotización efectiva.',null),
('adm-cm:21-64dfc7dca2','adm-cm',21,'Las ausencias o faltas de puntualidad al trabajo de la trabajadora víctima de violencia de género motivadas por su situación física o psicológica:','["Se descuentan del sueldo en todo caso, aunque los servicios sociales de atención o de salud acrediten que están motivadas por su situación física o psicológica", "Se considerarán justificadas y serán remuneradas cuando así lo determinen los servicios sociales de atención o de salud", "Requieren autorización judicial", "Serán siempre sancionadas como falta leve, aunque los servicios sociales de atención o de salud acrediten que derivan de su situación"]'::jsonb,1,'Art. 21.4 LO 1/2004','Deben comunicarse a la empresa a la mayor brevedad.',null),
('adm-cm:21-ced9d4a332','adm-cm',21,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su afiliación a un partido político o a un sindicato", "Su cambio de domicilio", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('adm-cm:21-e9fc83e76e','adm-cm',21,'Los servicios de asistencia social integral a las víctimas de violencia de género responderán, entre otros, a los principios de:','["Gratuidad parcial, voluntariedad, subsidiariedad respecto de los servicios generales y atención exclusiva en horario de oficina", "Secreto, discrecionalidad, gratuidad parcial, subsidiariedad respecto de los servicios generales y atención en horario de oficina", "Centralización y uniformidad", "Atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional"]'::jsonb,3,'Art. 19.1 LO 1/2004','Son los principios de la asistencia social integral.',null),
('adm-cm:21-88665b8057','adm-cm',21,'La Delegación del Gobierno contra la Violencia de Género, entre otras funciones:','["Dicta resoluciones vinculantes para los juzgados de violencia sobre la mujer", "Dirige y coordina a la policía judicial en las investigaciones de violencia de género y dicta instrucciones a los juzgados especializados", "Elabora la Macroencuesta de Violencia contra las Mujeres y está legitimada ante los órganos jurisdiccionales", "Impone sanciones administrativas a los agresores y dirige las investigaciones de la policía judicial en los casos más graves"]'::jsonb,2,'Art. 29 LO 1/2004','Formula las políticas públicas en materia de violencia de género.',null),
('adm-cm:21-9f1554c259','adm-cm',21,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración", "Suprimir los planes de igualdad", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Reservar los puestos directivos a la persona más antigua"]'::jsonb,0,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('adm-cm:21-b5ecc15d4e','adm-cm',21,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El Ministerio Fiscal", "La persona demandada", "El juez"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.','oct. 2026 · 1.er ejercicio'),
('adm-cm:21-56c1cad406','adm-cm',21,'Según la Ley 15/2022, la discriminación por asociación se produce cuando una persona es tratada de modo discriminatorio:','["Debido a su relación con otra persona sobre la que concurra alguna de las causas de discriminación previstas en la ley", "Por concurrir en ella dos o más de las causas de discriminación previstas en la ley, de manera simultánea o consecutiva", "Por una apreciación incorrecta acerca de las características de la propia persona discriminada", "Por pertenecer a una asociación que defiende los derechos de un colectivo protegido por la ley"]'::jsonb,0,'Art. 6.2 a) Ley 15/2022','Hay discriminación por asociación cuando se discrimina a alguien por su relación con otra persona en la que concurre una causa de discriminación.',null),
('adm-cm:21-59ede6d28b','adm-cm',21,'La discriminación por error, según la Ley 15/2022, es la que se funda en:','["La relación de la persona discriminada con otra persona en la que concurre alguna de las causas de discriminación", "Una apreciación incorrecta acerca de las características de la persona discriminada", "La interacción de varios motivos que genera una forma específica de discriminación", "Una disposición aparentemente neutra que ocasiona una desventaja particular"]'::jsonb,1,'Art. 6.2 b) Ley 15/2022','La discriminación por error es la que se funda en una apreciación incorrecta acerca de las características de la persona.',null),
('adm-cm:21-d2240da880','adm-cm',21,'Cuando una persona es discriminada de manera simultánea o consecutiva por dos o más causas de las previstas en la Ley 15/2022, se produce:','["Discriminación interseccional", "Discriminación por asociación", "Discriminación indirecta", "Discriminación múltiple"]'::jsonb,3,'Art. 6.3 a) Ley 15/2022','Es discriminación múltiple; la interseccional se da cuando la interacción de varios motivos genera una forma específica de discriminación.',null),
('adm-cm:21-7314c149ed','adm-cm',21,'Según la Ley 15/2022, la denegación de ajustes razonables a las personas con discapacidad se considera:','["Discriminación indirecta", "Una infracción leve sin efecto discriminatorio", "Discriminación directa", "Discriminación por error"]'::jsonb,2,'Art. 6.1 a) Ley 15/2022','El art. 6.1 a) considera discriminación directa la denegación de ajustes razonables a las personas con discapacidad.',null),
('adm-cm:21-f4b209a13d','adm-cm',21,'En la Ley 15/2022, cuando la parte actora aporta indicios fundados de discriminación, corresponde a la parte demandada:','["Solicitar un informe preceptivo de la Autoridad Independiente antes de contestar", "Probar que la parte actora no pertenece a ninguno de los colectivos protegidos por la ley", "Nada, porque la carga de la prueba corresponde siempre a quien alega la discriminación", "Aportar una justificación objetiva y razonable, suficientemente probada, de las medidas adoptadas"]'::jsonb,3,'Art. 30.1 Ley 15/2022','Es la regla de la carga de la prueba del art. 30.1, que no se aplica a los procesos penales ni a los procedimientos administrativos sancionadores.',null),
('adm-cm:21-d3ccb83e84','adm-cm',21,'La regla de la Ley 15/2022 sobre la carga de la prueba en casos de discriminación NO se aplica:','["A los procedimientos que se inicien de oficio o a instancia de la Autoridad Independiente para la Igualdad de Trato", "A los procesos penales ni a los procedimientos administrativos sancionadores", "A los procesos laborales ni a los contencioso-administrativos", "A los procesos civiles en los que se reclame una indemnización"]'::jsonb,1,'Art. 30.3 Ley 15/2022','El art. 30.3 excluye los procesos penales y los procedimientos administrativos sancionadores, entre otros.',null),
('adm-cm:21-1f875f24e8','adm-cm',21,'Según la Ley 15/2022, acreditada la discriminación:','["Se presume la existencia de daño moral", "La indemnización se limita a los daños materiales probados", "La víctima debe probar en todo caso el daño moral sufrido", "Se impone siempre una sanción muy grave al responsable"]'::jsonb,0,'Art. 27.1 Ley 15/2022','El art. 27.1 establece que, acreditada la discriminación, se presume la existencia de daño moral.',null),
('adm-cm:21-26d9bdd402','adm-cm',21,'La persona titular de la Presidencia de la Autoridad Independiente para la Igualdad de Trato y la No Discriminación tiene un mandato de:','["Cuatro años, renovable una sola vez", "Cinco años, renovable una sola vez", "Cinco años, no renovable", "Seis años, no renovable"]'::jsonb,2,'Art. 41.4 Ley 15/2022','La nombra el Gobierno por real decreto, tras comparecer ante el Congreso y el Senado, para un mandato de cinco años no renovable.',null),
('adm-cm:21-7c19224500','adm-cm',21,'En la Ley 15/2022, las infracciones muy graves se sancionan con multa de:','["60.001 a 1.000.000 de euros", "10.001 a 40.000 euros", "40.001 a 300.000 euros", "40.001 a 500.000 euros"]'::jsonb,3,'Art. 48 Ley 15/2022','Leves, de 300 a 10.000 euros; graves, de 10.001 a 40.000 euros; muy graves, de 40.001 a 500.000 euros.',null),
('adm-cm:21-1abba5f66f','adm-cm',21,'Según la Ley 15/2022, las infracciones graves prescriben a los:','["Dos años", "Tres años", "Cinco años", "Cuatro años"]'::jsonb,1,'Art. 51 Ley 15/2022','Las infracciones leves prescriben al año, las graves a los tres años y las muy graves a los cuatro años.',null),
('adm-cm:21-ef599a66c4','adm-cm',21,'¿Qué ley se aprobó en 2023 para la igualdad real y efectiva de las personas trans y para la garantía de los derechos de las personas LGTBI?','["La Ley 4/2023, de 28 de febrero", "La LO 2/2024, de 1 de agosto", "La LO 10/2022, de 6 de septiembre", "La Ley 15/2022, de 12 de julio"]'::jsonb,0,'Ley 4/2023','La Ley 15/2022 es la ley integral para la igualdad de trato y la no discriminación.',null),
('adm-cm:21-e333c621ea','adm-cm',21,'Según la Ley 4/2023, las terapias de conversión dirigidas a modificar la orientación sexual, la identidad sexual o la expresión de género de las personas:','["Están prohibidas, incluso con el consentimiento de la persona o de sus representantes", "Están permitidas únicamente en centros sanitarios autorizados previamente por la Comunidad Autónoma", "Están permitidas si la persona es mayor de edad y presta su consentimiento expreso y por escrito", "Solo están prohibidas cuando se apliquen a menores de catorce años o a personas con la capacidad modificada"]'::jsonb,0,'Art. 17 Ley 4/2023','Se prohíbe la práctica de métodos, programas y terapias de aversión, conversión o contracondicionamiento.',null),
('adm-cm:21-eccb61d5bf','adm-cm',21,'Según la Ley 4/2023, las empresas de más de cincuenta personas trabajadoras deben contar con:','["Un plan de igualdad entre mujeres y hombres negociado y registrado ante el Instituto de las Mujeres y la autoridad laboral de su Comunidad", "Un conjunto planificado de medidas y recursos para la igualdad real de las personas LGTBI, con un protocolo frente al acoso", "Un delegado de diversidad nombrado por la Inspección de Trabajo", "Un cupo de reserva del 2 % de su plantilla para personas trans y un delegado de diversidad elegido por la representación sindical"]'::jsonb,1,'Art. 15 Ley 4/2023','Las medidas se pactan a través de la negociación colectiva.',null),
('adm-cm:21-1a1b73c7af','adm-cm',21,'¿Qué autoridad crea la Ley 15/2022 para proteger y promover la igualdad de trato y la no discriminación?','["La Autoridad Independiente para la Igualdad de Trato y la No Discriminación", "El Observatorio Estatal de la Discriminación, adscrito al Instituto de las Mujeres", "El Consejo de Participación de las personas LGTBI", "El Defensor de la Igualdad y la Diversidad, dependiente del Ministerio del Interior"]'::jsonb,0,'Ley 15/2022','Es un órgano independiente con funciones de asistencia a las víctimas, investigación y mediación.',null),
('adm-cm:22-f808a61024','adm-cm',22,'¿Qué sistema de identificación electrónica menciona expresamente el art. 9.2 de la Ley 39/2015?','["Los certificados electrónicos cualificados de firma electrónica", "El reconocimiento facial mediante la cámara del dispositivo", "La huella dactilar registrada en el DNI", "El número de teléfono móvil asociado a una cuenta bancaria del interesado"]'::jsonb,0,'Art. 9.2 Ley 39/2015','Menciona los certificados cualificados de firma, los de sello electrónico y cualquier otro sistema que las Administraciones consideren válido.','oct. 2026 · 1.er ejercicio'),
('adm-cm:22-8cd6260bbf','adm-cm',22,'Con carácter general, para realizar cualquier actuación en el procedimiento, los interesados deben:','["Firmar electrónicamente todo", "Acreditar previamente su identidad", "Presentarse en persona", "Aportar un certificado de antecedentes"]'::jsonb,1,'Art. 11.1 Ley 39/2015','Basta con que acrediten previamente su identidad.',null),
('adm-cm:22-5219e969ec','adm-cm',22,'¿Para cuál de estas actuaciones exige la Ley 39/2015 el uso de la firma?','["Consultar el estado de un expediente", "Pedir información general", "Interponer recursos", "Solicitar cita previa"]'::jsonb,2,'Art. 11.2 Ley 39/2015','Se exige firma para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos.',null),
('adm-cm:22-5c708628e7','adm-cm',22,'Las Administraciones deben asistir en el uso de medios electrónicos a:','["Las empresas y demás personas jurídicas", "Los empleados públicos, para los trámites relacionados con su condición de tales", "Las entidades sin personalidad jurídica que carezcan de medios electrónicos propios", "Las personas físicas que no estén obligadas a relacionarse electrónicamente"]'::jsonb,3,'Art. 12.2 Ley 39/2015','Deben asistir a las personas físicas no obligadas, especialmente en identificación y firma, presentación de solicitudes y obtención de copias auténticas.',null),
('adm-cm:22-4b86947131','adm-cm',22,'Las personas físicas, ¿pueden elegir si se comunican con las Administraciones por medios electrónicos?','["Sí, en todo momento, salvo que estén obligadas", "No, siempre deben usar medios electrónicos", "No, siempre deben ir en persona", "Solo si son mayores de 65 años"]'::jsonb,0,'Art. 14.1 Ley 39/2015','Pueden elegir en todo momento, salvo que estén obligadas a relacionarse electrónicamente.',null),
('adm-cm:22-c3161772c8','adm-cm',22,'¿Cuál de los siguientes NO está obligado, con carácter general, a relacionarse electrónicamente con las Administraciones?','["Una persona jurídica", "Una persona física que actúa en su propio nombre", "Una entidad sin personalidad jurídica", "Un empleado público en trámites por razón de su condición"]'::jsonb,1,'Art. 14.2 Ley 39/2015','Están obligados las personas jurídicas, las entidades sin personalidad, los profesionales con colegiación obligatoria, los representantes de obligados y los empleados públicos en esos trámites.',null),
('adm-cm:22-e6544ee5e6','adm-cm',22,'Las personas tienen derecho a comunicarse con las Administraciones a través de:','["Un número de WhatsApp oficial de cada organismo", "Su correo electrónico personal, que tiene la misma validez que el registro", "Un Punto de Acceso General electrónico", "Los perfiles oficiales en redes sociales"]'::jsonb,2,'Art. 13 a) Ley 39/2015','Tienen derecho a comunicarse a través de un Punto de Acceso General electrónico de la Administración.',null),
('adm-cm:22-98410a8fd2','adm-cm',22,'La sede electrónica es:','["Un edificio de la Administración donde se atiende al público", "Un programa informático de gestión", "La dirección de correo electrónico oficial de un organismo público, a través de la cual se presentan escritos con plena validez jurídica", "Una dirección electrónica disponible a través de redes de telecomunicaciones cuya titularidad corresponde a una Administración"]'::jsonb,3,'Art. 38.1 Ley 40/2015','Es una dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración u organismo público.',null),
('adm-cm:22-02859a497f','adm-cm',22,'El portal de internet de una Administración es:','["El punto de acceso electrónico que permite acceder a la información publicada y, en su caso, a la sede electrónica", "Lo mismo que la sede electrónica, con la misma responsabilidad sobre la integridad y actualización de la información y los servicios", "Un registro electrónico general en el que se presentan escritos dirigidos a cualquier órgano de esa Administración o de otras", "Un tablón de anuncios físico"]'::jsonb,0,'Art. 39 Ley 40/2015','Es el punto de acceso electrónico de titularidad pública que permite acceder a la información publicada y, en su caso, a la sede electrónica.',null),
('adm-cm:22-597a904834','adm-cm',22,'Se entiende por actuación administrativa automatizada la realizada íntegramente por medios electrónicos y:','["En la que un empleado público valide y firme cada acto con su certificado personal", "En la que no haya intervenido de forma directa un empleado público", "En la que intervenga un empleado público solo en la fase de notificación", "Que se publique en la sede electrónica"]'::jsonb,1,'Art. 41.1 Ley 40/2015','Es la realizada íntegramente por medios electrónicos en un procedimiento y sin intervención directa de un empleado público.',null),
('adm-cm:22-5b220b240a','adm-cm',22,'¿Qué norma regula la atención al ciudadano en la Comunidad de Madrid?','["La Ley 1/1983, de Gobierno y Administración", "La Ley 10/2019, de Transparencia y de Participación", "El Decreto 21/2002, de 24 de enero", "El Decreto 85/2002, de 23 de mayo"]'::jsonb,2,'Decreto 21/2002 CM','El Decreto 21/2002, de 24 de enero, regula la atención al ciudadano en la Comunidad de Madrid. El Decreto 85/2002 trata de la evaluación de la calidad.',null),
('adm-cm:22-7c8698ce96','adm-cm',22,'Las sugerencias y reclamaciones deberán formularse:','["Por teléfono exclusivamente", "De forma anónima, para proteger al reclamante, a través del buzón habilitado en cada oficina, sin necesidad de identificar el objeto de la reclamación ni al reclamante", "Por escrito, con los datos que permitan identificar y localizar al reclamante y el objeto de la sugerencia o reclamación", "De forma presencial en la oficina afectada"]'::jsonb,2,'Art. 30.1 Decreto 21/2002 CM','Pueden presentarse en los lugares del art. 16, por fax o por Internet.',null),
('adm-cm:22-eb6f4cfb93','adm-cm',22,'La información general versa, entre otros aspectos, sobre:','["Las deliberaciones internas del Consejo de Gobierno", "El estado de tramitación de un expediente concreto, la identidad del personal responsable y los datos de los demás interesados en el procedimiento, dirigida a cualquier ciudadano que la pida", "Los datos personales de otros interesados, el estado de tramitación de sus expedientes y la identidad de las autoridades responsables, a petición de cualquiera", "Los fines, competencias y funcionamiento de los órganos y servicios, la localización y horarios de las oficinas y los trámites y documentación exigidos"]'::jsonb,3,'Art. 7.1 Decreto 21/2002 CM','La información sobre un expediente concreto es información particular.',null),
('adm-cm:22-8259e9e3e6','adm-cm',22,'La Comisión para la Coordinación de la Atención al Ciudadano se reunirá, según el Decreto 21/2002:','["Una vez cada cuatro años", "Todas las semanas", "Al menos dos veces al año", "Solo cuando lo pida un ciudadano"]'::jsonb,2,'Art. 38 Decreto 21/2002 CM','La preside el Director General competente en atención al ciudadano.',null),
('adm-cm:22-ba16a38e28','adm-cm',22,'Según el Decreto 21/2002, la información particular la facilitará:','["El servicio 012 en exclusiva", "El órgano gestor", "Cualquier oficina de registro", "El Defensor del Pueblo"]'::jsonb,1,'Art. 9 Decreto 21/2002 CM','Corresponde al órgano que tramita el procedimiento.','nov. 2024 · 1.er ejercicio'),
('adm-cm:22-63d974325d','adm-cm',22,'Las Oficinas de Información Especializada son, según el Decreto 21/2002:','["Los juzgados de lo contencioso-administrativo", "Las que ofrecen información específica de su ámbito, dependientes de la unidad a la que se adscriben", "Las que ofrecen información general de toda la Comunidad, dependientes de la Dirección General de Atención al Ciudadano", "Las oficinas consulares y las delegaciones de la Comunidad de Madrid en el exterior y en Bruselas, adscritas a Presidencia"]'::jsonb,1,'Art. 36 Decreto 21/2002 CM','Se coordinan con la Oficina de Atención al Ciudadano.',null),
('adm-cm:22-7670d7d16e','adm-cm',22,'Las quejas por retrasos o anomalías en el funcionamiento de los servicios tributarios de la Comunidad de Madrid se enviarán de inmediato a:','["El Defensor del Contribuyente", "La Asamblea de Madrid", "El Tribunal Económico-Administrativo", "La Agencia Tributaria estatal"]'::jsonb,0,'Art. 30.4 Decreto 21/2002 CM','La Oficina de Atención al Ciudadano las remite al Defensor del Contribuyente.',null),
('adm-cm:22-3503906eab','adm-cm',22,'La información particular es la relativa a:','["La normativa vigente, las funciones de los órganos y los horarios de las oficinas, dirigida a cualquier ciudadano que la solicite sin necesidad de acreditar interés", "Las funciones de los órganos", "El estado de tramitación de los procedimientos y la identificación de las autoridades y personal responsables, dirigida a los interesados o sus representantes", "Los horarios de las oficinas"]'::jsonb,2,'Art. 9.1 Decreto 21/2002 CM','Solo se facilita a quienes tengan la condición de interesado o a sus representantes.',null),
('adm-cm:22-c510211694','adm-cm',22,'Según el Decreto 21/2002, ¿cuál de estas actividades integra la atención al ciudadano?','["Las sugerencias y reclamaciones", "La potestad sancionadora", "La resolución de recursos de alzada", "La aprobación de presupuestos"]'::jsonb,0,'Art. 1.2 Decreto 21/2002 CM','Integran la atención al ciudadano la información, el registro y las sugerencias y reclamaciones, entre otras.',null),
('adm-cm:22-637e726425','adm-cm',22,'Los Registros de la Comunidad de Madrid NO podrán utilizarse para:','["Presentar recursos administrativos", "Presentar solicitudes", "Presentar sugerencias y quejas sobre el funcionamiento de los servicios públicos de la Comunidad de Madrid", "La remisión masiva de documentos de carácter comercial o publicitario"]'::jsonb,3,'Art. 15.2 Decreto 21/2002 CM','Así lo excluye el Decreto.',null),
('adm-cm:22-ee5e4776cd','adm-cm',22,'La información especializada, según el Decreto 21/2002, es la que:','["Se refiere al expediente propio del interesado y a la identidad del personal que lo tramita", "Se publica en el BOCM y en el portal de transparencia de la Comunidad", "Se presta por teléfono a través del 012", "Requiere una mayor profundización o consultas complementarias"]'::jsonb,3,'Art. 8.1 Decreto 21/2002 CM','Se distingue de la general y de la particular.',null),
('adm-cm:22-fd70a1d397','adm-cm',22,'Según el Decreto 21/2002, la información facilitada al ciudadano:','["No interrumpe ni suspende los plazos establecidos en los procedimientos", "Suspende los plazos del procedimiento durante un mes desde que se solicita", "Interrumpe los plazos de los procedimientos hasta que se notifica la respuesta", "Sustituye a la notificación cuando se presta por escrito"]'::jsonb,0,'Art. 14 Decreto 21/2002 CM','No tiene efectos sobre el procedimiento.',null),
('adm-cm:22-01a105e678','adm-cm',22,'Según el Decreto 21/2002, la atención al ciudadano es:','["La tramitación de recursos administrativos y reclamaciones que presentan los ciudadanos frente a los actos de la Administración de la Comunidad, a través de las oficinas de registro", "El conjunto de actividades y medios que la Administración de la Comunidad pone a disposición de los ciudadanos para el ejercicio de sus derechos y el cumplimiento de sus obligaciones", "Solo el servicio telefónico 012", "El registro de entrada de documentos exclusivamente"]'::jsonb,1,'Art. 1 Decreto 21/2002 CM','El art. 1 define así la atención al ciudadano.',null),
('adm-cm:22-8845a39209','adm-cm',22,'Según el Decreto 21/2002, la respuesta a la sugerencia o reclamación debe procurar producirse dentro de:','["Los tres meses siguientes a su recepción", "Los diez días naturales siguientes a su recepción", "Un mes desde su recepción, ampliable por otro mes si la complejidad lo exige", "Los quince días hábiles siguientes a su recepción"]'::jsonb,3,'Art. 31.4 Decreto 21/2002 CM','Se procura contestar en quince días hábiles.',null),
('adm-cm:22-e673c72e8d','adm-cm',22,'En el esquema del Decreto 21/2002, en cada Consejería existe:','["Un Punto de Información y Atención al Ciudadano, dependiente de su Secretaría General Técnica", "Una Oficina de Atención al Ciudadano, dependiente directamente del Consejero", "Una Oficina del Defensor del Pueblo", "Un Punto de Información y Atención al Ciudadano, dependiente de la Dirección General de Calidad de los Servicios y Atención al Ciudadano"]'::jsonb,0,'Art. 35 Decreto 21/2002 CM','Los Coordinadores de Atención al Ciudadano se designan en las Secretarías Generales Técnicas.',null),
('adm-cm:22-b6919c6578','adm-cm',22,'La información que se facilita al ciudadano tiene carácter:','["De notificación oficial a efectos del cómputo de plazos", "Vinculante para la Administración que la facilita", "Meramente ilustrativo, sin que pueda entenderse como interpretación normativa ni generar derechos", "Meramente ilustrativo, aunque vincula a la Administración cuando se facilita por escrito y genera derechos para quien la recibe"]'::jsonb,2,'Art. 14 Decreto 21/2002 CM','No interrumpe ni suspende plazos ni sirve de notificación.',null),
('adm-cm:22-b1db63c2d2','adm-cm',22,'Según el Decreto 21/2002, las sugerencias y reclamaciones:','["Tienen naturaleza de recurso de alzada", "No tienen la calificación de recurso administrativo y su presentación no suspende los plazos", "No tienen la calificación de recurso, pero su presentación suspende los plazos de los procedimientos", "Suspenden los plazos de recurso"]'::jsonb,1,'Art. 29.2 Decreto 21/2002 CM','No condicionan el ejercicio de otras acciones.',null),
('adm-cm:22-44ff680ca7','adm-cm',22,'Según la Ley 40/2015, el titular de la sede electrónica responde de:','["La integridad, veracidad y actualización de la información y los servicios a los que pueda accederse a través de ella", "Únicamente de la disponibilidad técnica de la sede durante el horario de atención presencial", "La integridad de la información publicada, mientras que su actualización y la de los servicios corresponde al proveedor tecnológico contratado", "La veracidad de la información publicada en el portal, pero no de los servicios electrónicos de la sede"]'::jsonb,0,'Art. 38.2 Ley 40/2015','El titular de la sede responde de la integridad, veracidad y actualización de la información y los servicios accesibles a través de ella.',null),
('adm-cm:22-8fd3195502','adm-cm',22,'Para identificarse y garantizar una comunicación segura, las sedes electrónicas utilizan:','["El código seguro de verificación del órgano titular de la sede", "Un sello de tiempo cualificado emitido por la Fábrica Nacional de Moneda y Timbre-Real Casa de la Moneda", "Certificados cualificados de autenticación de sitio web o medio equivalente", "La firma electrónica personal de la persona titular del órgano"]'::jsonb,2,'Art. 38.6 Ley 40/2015','El art. 38.6 prevé certificados reconocidos o cualificados de autenticación de sitio web o un medio equivalente.',null),
('adm-cm:22-9c1e60e7a8','adm-cm',22,'Según el art. 40 de la Ley 40/2015, las Administraciones Públicas pueden identificarse mediante:','["La firma electrónica personal del titular del departamento ministerial o de la consejería, de forma exclusiva", "Un código seguro de verificación generado por el propio interesado", "Un sello electrónico basado en un certificado electrónico reconocido o cualificado", "El número de identificación profesional de cada uno de sus empleados"]'::jsonb,2,'Art. 40.1 Ley 40/2015','El sello electrónico se basa en un certificado reconocido o cualificado que incluye el NIF y la denominación de la Administración.',null),
('adm-cm:22-73dbdb8735','adm-cm',22,'Respecto de la información que publique como propia en su portal de internet, la Administración:','["Se entiende identificada", "Debe identificarse además con la firma electrónica cualificada del órgano", "Solo se entiende identificada si incorpora un código seguro de verificación", "Debe indicar el nombre del empleado público que elaboró la información"]'::jsonb,0,'Art. 40.1 Ley 40/2015','Se entenderá identificada la Administración respecto de la información que publique como propia en su portal de internet.',null),
('adm-cm:22-7ab2566337','adm-cm',22,'En la actuación administrativa automatizada, cada Administración puede determinar como sistema de firma:','["El certificado de autenticación de sitio web de la sede electrónica", "Solo la firma electrónica cualificada de la persona titular del órgano", "La firma manuscrita digitalizada del empleado que supervisa el sistema", "Un sello electrónico o un código seguro de verificación vinculado a la Administración"]'::jsonb,3,'Art. 42 Ley 40/2015','El art. 42 permite el sello electrónico de Administración, órgano u organismo, o el código seguro de verificación.',null),
('adm-cm:22-80aab7df78','adm-cm',22,'El código seguro de verificación (CSV) permite en todo caso:','["Prorrogar durante cinco años la validez del documento al que se vincula", "Comprobar la integridad del documento mediante el acceso a la sede electrónica correspondiente", "Identificar al empleado público que tramitó el expediente, su puesto de trabajo y el órgano al que está adscrito", "Sustituir la firma del interesado en las solicitudes que presente por registro"]'::jsonb,1,'Art. 42 b) Ley 40/2015','El CSV vinculado a la Administración permite en todo caso la comprobación de la integridad del documento accediendo a la sede.',null),
('adm-cm:22-803edab1ca','adm-cm',22,'Por razones de seguridad pública, los sistemas de firma electrónica del personal al servicio de la Administración:','["Podrán referirse solo al número de identificación profesional del empleado público", "Solo podrán utilizarse previa autorización judicial en cada procedimiento", "Podrán omitir cualquier dato que identifique al empleado público y a su órgano", "Deberán incluir siempre el nombre, los apellidos y el número del DNI del empleado público que firma la actuación"]'::jsonb,0,'Art. 43.2 Ley 40/2015','Por razones de seguridad pública, los sistemas de firma pueden referirse solo al número de identificación profesional del empleado.',null),
('adm-cm:22-ffba92bc38','adm-cm',22,'Si los participantes en un entorno cerrado de comunicación pertenecen a distintas Administraciones, las condiciones y garantías se fijan:','["Por orden del ministerio competente en materia de función pública", "Mediante real decreto aprobado por el Consejo de Ministros", "Mediante convenio", "Por decisión del órgano emisor de los datos, sin más requisitos"]'::jsonb,2,'Art. 44.3 Ley 40/2015','Entre distintas Administraciones, las condiciones y garantías del entorno cerrado se establecen mediante convenio.',null),
('adm-cm:22-ed582c46e5','adm-cm',22,'Según el art. 46 de la Ley 40/2015, los documentos utilizados en las actuaciones administrativas se almacenan:','["En soporte electrónico solo si lo solicita el interesado", "En papel y en soporte electrónico, siempre por duplicado", "Por medios electrónicos durante cinco años y después en papel", "Por medios electrónicos, salvo cuando no sea posible"]'::jsonb,3,'Art. 46.1 Ley 40/2015','Todos los documentos utilizados en las actuaciones administrativas se almacenan por medios electrónicos, salvo cuando no sea posible.',null),
('adm-cm:22-78ae97fa68','adm-cm',22,'Si un interesado no obligado a relacionarse electrónicamente carece de los medios necesarios, su firma electrónica puede realizarla:','["Cualquier empleado público de la oficina, sin necesidad de consentimiento expreso del interesado", "Un funcionario habilitado, si el interesado se identifica ante él y presta su consentimiento expreso", "Un funcionario habilitado, pero solo en los procedimientos que se inician de oficio", "Un familiar del interesado, previa presentación de una declaración responsable"]'::jsonb,1,'Art. 12.2 Ley 39/2015','El funcionario firma con su propio sistema; el interesado debe identificarse y prestar consentimiento expreso, del que queda constancia.',null),
('adm-cm:22-3722e3be45','adm-cm',22,'Los funcionarios habilitados para la identificación o firma de los interesados que no disponen de medios electrónicos constan en:','["Un registro u otro sistema equivalente que cada Administración mantiene actualizado", "El Registro Central de Personal, en una sección específica de firma electrónica", "Un listado único estatal publicado en la sede electrónica del Ministerio para la Transformación Digital y de la Función Pública", "El registro electrónico de apoderamientos de la Administración correspondiente"]'::jsonb,0,'Art. 12.3 Ley 39/2015','La AGE, las CCAA y las Entidades Locales mantienen actualizado un registro u otro sistema equivalente de funcionarios habilitados.',null),
('adm-cm:22-17ca17e074','adm-cm',22,'La obligación de relacionarse electrónicamente con la Administración para ciertos colectivos de personas físicas puede establecerse:','["Reglamentariamente, para cualquier persona física mayor de edad", "Por resolución del órgano instructor en cada procedimiento concreto", "Reglamentariamente, si queda acreditado que tienen acceso y disponibilidad de los medios electrónicos", "Solo por ley y únicamente para los profesionales que estén colegiados"]'::jsonb,2,'Art. 14.3 Ley 39/2015','Puede imponerse por reglamento a colectivos que, por capacidad económica, técnica o dedicación profesional, tengan acceso a esos medios.',null),
('adm-cm:22-7836b5f734','adm-cm',22,'Según el artículo 9 de la Ley 39/2015, ¿cuál de los siguientes es un sistema válido para que los interesados se identifiquen electrónicamente ante las Administraciones?','["La fotocopia del DNI enviada por correo electrónico", "Los sistemas de clave concertada", "El número de teléfono móvil", "La firma manuscrita escaneada"]'::jsonb,1,'Art. 9.2 Ley 39/2015','También los certificados electrónicos cualificados de firma y de sello y cualquier otro sistema que las Administraciones consideren válido en los términos y condiciones que se establezcan.',null),
('adm-cm:22-c58b57e519','adm-cm',22,'¿Cuál de los siguientes está obligado a relacionarse electrónicamente con las Administraciones según el artículo 14.2 de la Ley 39/2015?','["Las personas físicas mayores de 65 años", "Los extranjeros residentes en España", "Las personas jurídicas", "Los autónomos sin colegiación obligatoria"]'::jsonb,2,'Art. 14.2 Ley 39/2015','También las entidades sin personalidad jurídica, los profesionales de colegiación obligatoria en el ejercicio de su actividad, sus representantes y los empleados públicos en los trámites por su condición de tales.',null),
('adm-cm:22-5dc1faa20d','adm-cm',22,'Según la Ley 40/2015, la sede electrónica es:','["Cualquier página web en la que aparezca el escudo de una Administración", "El edificio en el que se ubican los servidores informáticos de un Ministerio", "La dirección electrónica disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública", "El buzón de correo electrónico de una unidad administrativa"]'::jsonb,2,'Art. 38.1 Ley 40/2015','El titular de la sede responde de la integridad, veracidad y actualización de la información y de los servicios a los que pueda accederse a través de ella.',null),
('adm-cm:22-1d761f493e','adm-cm',22,'Según la Ley 40/2015, la actuación administrativa automatizada es:','["Cualquier acto dictado por un funcionario usando un ordenador", "El envío de avisos por SMS a los interesados", "Cualquier acto o actuación realizada íntegramente a través de medios electrónicos por una Administración en el marco de un procedimiento, sin intervención directa de un empleado público", "La digitalización de documentos en papel"]'::jsonb,2,'Art. 41.1 Ley 40/2015','Debe establecerse previamente el órgano u órganos competentes para definir las especificaciones, programación, mantenimiento, supervisión y control de calidad y auditoría del sistema.',null),
('adm-cm:22-61befdb231','adm-cm',22,'En la actuación administrativa automatizada, ¿qué sistema de firma puede utilizar cada Administración?','["Sello electrónico de órgano o código seguro de verificación", "El certificado electrónico personal del ciudadano que inició el procedimiento", "La clave concertada del interesado, comunicada previamente por SMS", "La firma manuscrita del titular del órgano, digitalizada mediante escáner"]'::jsonb,0,'Art. 42 Ley 40/2015','El código seguro de verificación permite comprobar la integridad del documento mediante el acceso a la sede electrónica correspondiente.',null),
('adm-cm:22-13bc3b3acb','adm-cm',22,'El código seguro de verificación (CSV) permite:','["Cifrar el documento para que solo pueda leerlo el destinatario que disponga de la clave privada correspondiente", "Firmar documentos en papel con valor de original", "Identificar al ciudadano ante cualquier Administración sin necesidad de disponer de un certificado electrónico", "Comprobar la integridad y autenticidad de un documento accediendo a la sede electrónica correspondiente"]'::jsonb,3,'Art. 42 b) Ley 40/2015','Se vincula a la Administración, órgano u organismo y, en su caso, a la persona firmante del documento.',null),
('adm-cm:22-0c85b6136a','adm-cm',22,'Según la Ley 39/2015, los interesados no estarán obligados a aportar documentos que:','["Tengan una antigüedad inferior a cinco años desde su expedición, salvo que el órgano competente los requiera por resolución motivada", "Hayan sido elaborados por cualquier Administración o que hayan sido aportados anteriormente por el interesado a cualquier Administración", "Estén redactados en una lengua cooficial distinta del castellano", "Hayan sido firmados electrónicamente por el propio interesado o por su representante con un certificado cualificado expedido por un prestador de confianza"]'::jsonb,1,'Art. 28.2 y 28.3 Ley 39/2015','La Administración los consultará o recabará, salvo oposición expresa del interesado o que una ley especial exija su consentimiento expreso.',null),
('adm-cm:22-6ca86a76aa','adm-cm',22,'Según la Ley 39/2015, si el interesado no dispone de los medios electrónicos necesarios, su identificación o firma electrónica en el procedimiento puede ser válidamente realizada por:','["Cualquier familiar del interesado, con su propio certificado", "El representante sindical del interesado", "Un notario de libre elección del interesado, que deberá dar fe del acto realizado y de la identidad del firmante", "Un funcionario público habilitado, mediante el uso del sistema de firma electrónica del que esté dotado"]'::jsonb,3,'Art. 12.2 Ley 39/2015','El interesado debe identificarse ante el funcionario y prestar su consentimiento expreso, que debe quedar constancia.',null),
('adm-cm:22-f11907511d','adm-cm',22,'El portal de internet, según la Ley 40/2015, es:','["El punto de acceso electrónico cuya titularidad corresponde a una Administración Pública u organismo y que permite el acceso a través de internet a la información publicada y, en su caso, a la sede electrónica", "La sede electrónica de cada Ministerio", "Un servidor de correo electrónico de la Administración", "El programa informático que permite firmar documentos"]'::jsonb,0,'Art. 39 Ley 40/2015','No todo portal es una sede electrónica: la sede tiene garantías de integridad, veracidad y actualización.',null),
('adm-cm:22-ecd03ea1dc','adm-cm',22,'El sello electrónico, como sistema de firma de las Administraciones, se basa en:','["Una contraseña que conoce solo el funcionario que tramita", "Un certificado electrónico reconocido o cualificado que reúna los requisitos de la legislación de firma electrónica", "El número de registro de entrada asignado al documento", "La firma manuscrita digitalizada del titular del órgano, incorporada como imagen a todos los documentos que se emitan"]'::jsonb,1,'Art. 40 Ley 40/2015','Los certificados incluyen el número de identificación fiscal y la denominación correspondiente.',null),
('adm-cm:23-73ba7843b5','adm-cm',23,'Según la Ley 39/2015, cada Administración dispondrá de:','["Un Registro Electrónico General", "Un registro en papel por cada órgano", "Un registro único estatal", "Ningún registro propio"]'::jsonb,0,'Art. 16.1 Ley 39/2015','Cada Administración dispondrá de un Registro Electrónico General.',null),
('adm-cm:23-becd9119ac','adm-cm',23,'¿Dónde NO se pueden presentar documentos dirigidos a las Administraciones según el art. 16.4 de la Ley 39/2015?','["En las oficinas de Correos", "En las representaciones diplomáticas u oficinas consulares", "En las oficinas de asistencia en materia de registros", "En cualquier comercio colaborador"]'::jsonb,3,'Art. 16.4 Ley 39/2015','Se pueden presentar en los registros electrónicos, en Correos, en representaciones diplomáticas u oficinas consulares, en las oficinas de asistencia en materia de registros y donde establezcan las disposiciones vigentes.',null),
('adm-cm:23-421d8f25a3','adm-cm',23,'Cada Administración debe mantener, para los documentos electrónicos de procedimientos finalizados:','["Un archivo en papel", "Un archivo electrónico único", "Un archivo por cada funcionario", "Copias en el BOE"]'::jsonb,1,'Art. 17.1 Ley 39/2015','Debe mantener un archivo electrónico único de los documentos electrónicos de procedimientos finalizados.','oct. 2026 · 1.er ejercicio'),
('adm-cm:23-4e330987d7','adm-cm',23,'¿Cuál es uno de los requisitos de validez de los documentos administrativos electrónicos?','["Estar impresos y llevar el sello del órgano que los emite", "Llevar firma manuscrita escaneada y el sello del órgano emisor en cada página", "Incorporar la fecha de emisión y los metadatos mínimos exigidos", "Incorporar la fecha de emisión y estar disponibles en papel, con la firma original del titular del órgano"]'::jsonb,2,'Art. 26.2 Ley 39/2015','Deben contener información en soporte electrónico, datos de identificación, firmas electrónicas, fecha de emisión y metadatos mínimos.','nov. 2024 · 1.er ejercicio'),
('adm-cm:23-1adb4068b2','adm-cm',23,'Los interesados, ¿están obligados a aportar documentos elaborados por cualquier Administración?','["Sí, siempre", "Sí, si son originales", "Solo en papel", "No"]'::jsonb,3,'Art. 28.2 Ley 39/2015','No están obligados a aportar documentos elaborados por cualquier Administración; esta puede consultarlos salvo oposición del interesado.',null),
('adm-cm:23-279bd4afbc','adm-cm',23,'La presentación de un documento en el registro electrónico en un día inhábil se entiende realizada:','["En la primera hora del primer día hábil siguiente", "En la última hora del último día hábil anterior al de la presentación", "El mismo día inhábil, a la hora en que se presentó", "A las 9 horas del tercer día hábil siguiente"]'::jsonb,0,'Art. 31.2 b) Ley 39/2015','Se entiende realizada en la primera hora del primer día hábil siguiente, salvo que una norma permita la recepción en día inhábil.',null),
('adm-cm:23-3bcd84c6ff','adm-cm',23,'¿Qué ley regula actualmente los archivos y documentos de la Comunidad de Madrid?','["La Ley 4/1993, de 21 de abril, de Archivos y Patrimonio Documental", "La Ley 6/2023, de 30 de marzo, de Archivos y Documentos de la Comunidad de Madrid", "La Ley 16/1985, de 25 de junio, del Patrimonio Histórico Español", "La Ley 10/2019, de 10 de abril, de Transparencia de la Comunidad de Madrid"]'::jsonb,1,'Ley 6/2023 CM','La Ley 6/2023 sustituyó a la Ley 4/1993, de Archivos y Patrimonio Documental. Entró en vigor en mayo de 2023. Muchos temarios siguen citando la ley antigua.',null),
('adm-cm:23-42f99480d4','adm-cm',23,'Según la Ley 6/2023 de la Comunidad de Madrid, los archivos que corresponden a las fases del ciclo de vida de los documentos son:','["Archivo de oficina, central, regional e histórico", "Archivo de gestión, provisional y definitivo", "Archivo de gestión, central, intermedio e histórico", "Archivo de gestión, central e histórico, sin archivo intermedio"]'::jsonb,2,'Arts. 9 a 12 Ley 6/2023 CM','Archivo de gestión, archivo central, archivo intermedio y archivo histórico.',null),
('adm-cm:23-25e93fd703','adm-cm',23,'Según la Ley 6/2023, el archivo de gestión custodia:','["Los documentos de conservación permanente, una vez transferidos desde el archivo intermedio", "Los documentos cuya tramitación ha concluido hace más de cinco años", "Los documentos de valor histórico de otras Administraciones", "Los documentos en tramitación o de uso administrativo continuo"]'::jsonb,3,'Art. 9.1 Ley 6/2023 CM','Custodia los documentos en tramitación o sometidos a uso administrativo continuo.',null),
('adm-cm:23-edacd346b4','adm-cm',23,'Según la Ley 6/2023, el archivo histórico custodia:','["Los documentos de conservación permanente", "Los documentos en tramitación", "Los borradores", "Los documentos pendientes de eliminación"]'::jsonb,0,'Art. 12.1 Ley 6/2023 CM','Custodia los documentos de conservación permanente.',null),
('adm-cm:23-8f4afdfb46','adm-cm',23,'El Consejo de Archivos de la Comunidad de Madrid es:','["Un órgano de gestión directa de los archivos de la Comunidad, adscrito a la consejería competente en cultura", "Un órgano colegiado consultivo, multidisciplinar y técnico", "Un órgano colegiado ejecutivo que aprueba las eliminaciones de documentos", "Un órgano unipersonal de coordinación"]'::jsonb,1,'Art. 23.1 Ley 6/2023 CM','Es un órgano colegiado consultivo, multidisciplinar y técnico.',null),
('adm-cm:23-e6f0d3d7cb','adm-cm',23,'Según la Ley 6/2023, se entiende por archivo:','["El edificio o local en el que se custodian documentos de cualquier procedencia", "Solo el conjunto de documentos de valor histórico ya transferidos desde los archivos centrales", "El conjunto orgánico de documentos producidos o recibidos en el ejercicio de sus funciones", "El conjunto de documentos producidos por una persona o entidad, sea cual sea su organización, origen o finalidad"]'::jsonb,2,'Art. 3.1 h) Ley 6/2023 CM','Es el conjunto orgánico de documentos producidos o recibidos en el ejercicio de sus funciones.',null),
('adm-cm:23-6ec689cd92','adm-cm',23,'Según la Ley 6/2023, el documento electrónico es:','["Un documento en papel digitalizado mediante escáner, aunque no incorpore firma electrónica ni los metadatos mínimos exigidos por la normativa", "Cualquier archivo digital de imagen o sonido", "Un correo electrónico personal", "La información de cualquier naturaleza en forma electrónica, archivada en un soporte electrónico según un formato determinado"]'::jsonb,3,'Art. 3.2 a) Ley 6/2023 CM','Es la información de cualquier naturaleza en forma electrónica, archivada en un soporte electrónico según un formato determinado.',null),
('adm-cm:23-354f54687d','adm-cm',23,'Según el art. 20 de la Ley 6/2023, es un órgano colegiado del Sistema de Archivos de la Comunidad de Madrid:','["El Consejo de Estado", "La Agencia Española de Protección de Datos", "La Comisión de Acceso y Valoración de Documentos", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 20 b) Ley 6/2023 CM','También el Consejo de Archivos, la Comisión de Archivo de la Asamblea y la Junta de Expurgo de Documentos Judiciales.',null),
('adm-cm:23-614996fea8','adm-cm',23,'Las personas al servicio del sector público, al cesar en sus funciones, deberán:','["Entregar los documentos a su cargo a quien les suceda o al archivo público correspondiente", "Entregar los documentos al representante sindical del centro", "Llevárselos a su domicilio", "Conservar una copia de los documentos a su cargo y entregar los originales al órgano que los nombró"]'::jsonb,0,'Art. 73.3 Ley 6/2023 CM','Tienen el deber de custodiarlos y no destruirlos indebidamente.',null),
('adm-cm:23-a66dac8ace','adm-cm',23,'Según el art. 8.1 de la Ley 6/2023, los archivos se clasifican, en función del ciclo vital, en:','["Archivos estatales, autonómicos y municipales", "Archivos digitales y en papel", "Archivos de gestión, centrales, intermedios e históricos", "Archivos de oficina, centrales, provinciales e históricos"]'::jsonb,2,'Art. 8.1 Ley 6/2023 CM','Son las cuatro fases del ciclo vital.',null),
('adm-cm:23-6af3e5c619','adm-cm',23,'A falta de Tabla de Valoración, los documentos permanecen en el archivo intermedio:','["Quince años desde su ingreso", "Cuarenta años desde su ingreso", "Diez años desde su ingreso", "Cinco años desde su ingreso"]'::jsonb,0,'Art. 51.2 c) Ley 6/2023 CM','Después se eliminan o se transfieren al histórico.',null),
('adm-cm:23-7f373df281','adm-cm',23,'Forman parte del Patrimonio Documental Madrileño, sin necesidad de valoración, los documentos públicos no valorados con una antigüedad superior a:','["Treinta años", "Cuarenta años", "Cien años", "Diez años"]'::jsonb,0,'Art. 80.1 Ley 6/2023 CM','Los privados de entidades religiosas, políticas, sindicales, etc., con más de cuarenta años; otros privados, más de cincuenta.',null),
('adm-cm:23-ab3c7e86f4','adm-cm',23,'El archivo central, según la Ley 6/2023:','["Gestiona los documentos transferidos desde los archivos de gestión hasta su eliminación o transferencia al archivo intermedio", "Custodia los documentos en tramitación", "Custodia los documentos de valor histórico permanente", "Gestiona los documentos transferidos desde el archivo intermedio hasta su eliminación o transferencia al archivo histórico"]'::jsonb,0,'Art. 10 Ley 6/2023 CM','Es la segunda fase del ciclo vital.',null),
('adm-cm:23-645cbd3e7b','adm-cm',23,'El archivo intermedio, según la Ley 6/2023:','["Custodia los documentos en tramitación o de uso administrativo continuo hasta su transferencia al archivo central, sin conservar documentos de consulta esporádica", "Custodia de forma centralizada los documentos de consulta esporádica hasta su eliminación o transferencia al archivo histórico", "Es el archivo de las oficinas", "Custodia los documentos en tramitación"]'::jsonb,1,'Art. 11 Ley 6/2023 CM','Recibe los documentos del archivo central.',null),
('adm-cm:23-08b617dd2d','adm-cm',23,'A falta de Tabla de Valoración, los documentos permanecen en el archivo central hasta su transferencia durante:','["Cinco años desde su ingreso", "Treinta años desde su ingreso", "Quince años desde su ingreso", "Diez años desde su ingreso"]'::jsonb,3,'Art. 51.2 b) Ley 6/2023 CM','Después pasan al archivo intermedio.',null),
('adm-cm:23-75c2f51ae5','adm-cm',23,'La valoración y el régimen de acceso de los documentos judiciales corresponde a:','["La Junta de Expurgo de Documentos Judiciales", "La Comisión de Acceso y Valoración de Documentos", "El Consejo de Archivos", "Cada juzgado individualmente"]'::jsonb,0,'Art. 26.1 Ley 6/2023 CM','La Comisión de Acceso y Valoración excluye los documentos judiciales y los de la Asamblea.',null),
('adm-cm:23-1efcc80267','adm-cm',23,'Las infracciones muy graves de la Ley 6/2023 se sancionan con multa de:','["De 6.001 a 60.000 euros por cada infracción", "De 60.001 a 600.000 euros", "Hasta 6.000 euros", "De 300.001 a 1.000.000 de euros"]'::jsonb,3,'Art. 107.1 Ley 6/2023 CM','Graves: 60.001 a 300.000 €; leves: apercibimiento o multa de hasta 60.000 €.',null),
('adm-cm:23-d49e100bb6','adm-cm',23,'A falta de Tabla de Valoración, los documentos se transfieren del archivo de gestión al central a los:','["Dos años desde la finalización de su tramitación", "Cinco años desde la finalización de su tramitación", "Diez años desde la finalización de su tramitación", "Un año desde el inicio de su tramitación"]'::jsonb,1,'Art. 51.2 a) Ley 6/2023 CM','Plazos subsidiarios: gestión 5 años, central 10 años, intermedio 15 años.',null),
('adm-cm:23-3051c6e62c','adm-cm',23,'Según la Ley 6/2023, el derecho de acceso a los documentos de titularidad pública:','["Exige siempre motivar la solicitud", "Solo lo tienen los investigadores acreditados", "No exige acreditar interés personal ni motivar la solicitud", "Exige acreditar un interés personal, aunque no es necesario motivar la solicitud"]'::jsonb,2,'Art. 62.2 Ley 6/2023 CM','Todas las personas tienen derecho de acceso (art. 62.1).',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:23-413f7993d3','adm-cm',23,'El Sistema de Archivos de la Comunidad de Madrid forma parte:','["Del Archivo General de Simancas", "Del Sistema Español de Archivos", "De la Biblioteca Nacional", "Del Consejo de Europa"]'::jsonb,1,'Art. 17.1 Ley 6/2023 CM','Su finalidad es servir a la gestión administrativa, garantizar el acceso y proteger el patrimonio documental.',null),
('adm-cm:23-bf10518b58','adm-cm',23,'La Comisión de Acceso y Valoración de Documentos emite dictamen preceptivo y vinculante sobre:','["Los recursos de alzada contra las resoluciones de los archivos", "Los presupuestos de la Comunidad", "Las oposiciones de archiveros", "Las Tablas de Valoración y la autorización de eliminación de documentos"]'::jsonb,3,'Art. 24.3 Ley 6/2023 CM','Es un órgano colegiado técnico, multidisciplinar y de participación.',null),
('adm-cm:23-905491a39c','adm-cm',23,'Según la Ley 6/2023 de la Comunidad de Madrid, el ciclo vital de los documentos es:','["El tiempo de tramitación de un expediente", "El periodo de vigencia administrativa de los documentos, que termina cuando concluye la tramitación del expediente y se transfieren al archivo histórico", "El plazo de prescripción de las acciones derivadas de los documentos, durante el cual deben conservarse en el archivo de gestión sin posibilidad de eliminación", "El conjunto de fases por las que pasan los documentos desde su producción hasta su eliminación o conservación permanente"]'::jsonb,3,'Art. 3.1 d) Ley 6/2023 CM','Definición legal de ciclo vital.',null),
('adm-cm:23-28eda9ccb7','adm-cm',23,'No podrán destruirse documentos de titularidad pública mientras:','["No lo pida el interesado", "Subsista su valor probatorio de derechos y obligaciones de las personas o de los entes públicos", "Estén digitalizados con copia auténtica en un sistema de gestión documental homologado por la Comunidad", "No haya pasado un año"]'::jsonb,1,'Art. 55.1 Ley 6/2023 CM','Tampoco si pueden tener valor informativo o histórico.',null),
('adm-cm:23-12de56cbe6','adm-cm',23,'Según la Ley 6/2023, la eliminación de documentos de titularidad pública:','["Está prohibida en todo caso", "Solo la autoriza un juez", "Solo puede hacerse conforme a las Tablas de Valoración dictaminadas favorablemente por la Comisión competente", "Puede hacerla libremente cada órgano productor una vez transcurridos los plazos de conservación fijados en su normativa interna"]'::jsonb,2,'Art. 55.2 Ley 6/2023 CM','Debe expedirse certificación de la destrucción.',null),
('adm-cm:23-617127763d','adm-cm',23,'Las funciones archivísticas según el art. 41.1 de la Ley 6/2023 incluyen:','["La imposición de sanciones", "La aprobación de las normas sobre archivos, la imposición de sanciones y la eliminación libre de documentos", "Solo la custodia y conservación de los documentos, sin incluir su descripción, valoración ni el servicio a los ciudadanos", "Identificación, valoración, organización, descripción, conservación, custodia, acceso y servicio"]'::jsonb,3,'Art. 41.1 Ley 6/2023 CM','Son funciones de carácter transversal.',null),
('adm-cm:23-f2ad98e490','adm-cm',23,'El plazo máximo para resolver los procedimientos sancionadores de la Ley 6/2023 es de:','["Un año", "Dos meses", "Seis meses", "Tres meses"]'::jsonb,2,'Art. 114 Ley 6/2023 CM','Plazo de resolución de seis meses.',null),
('adm-cm:23-d3b4740d92','adm-cm',23,'Las Tablas de Valoración se aprueban mediante:','["Decreto del Presidente de la Comunidad", "Orden de la Consejería competente en materia de archivos", "Ley de la Asamblea de Madrid, a propuesta del Gobierno", "Resolución de cada archivo"]'::jsonb,1,'Art. 56.1 a) Ley 6/2023 CM','Previo dictamen de la Comisión competente.',null),
('adm-cm:23-3a66f2bf95','adm-cm',23,'Según la Ley 6/2023, el órgano competente para imponer sanciones por infracciones muy graves es:','["La Dirección General competente", "El Ayuntamiento", "El Consejo de Gobierno", "La Consejería competente"]'::jsonb,2,'Art. 109 Ley 6/2023 CM','Leves: Dirección General; graves: Consejería.',null),
('adm-cm:23-23bcbd66fa','adm-cm',23,'Según la Ley 6/2023, las infracciones muy graves prescriben a los:','["Cinco años", "Diez años", "Seis meses", "Tres años"]'::jsonb,1,'Art. 113.1 Ley 6/2023 CM','Las graves a los tres años y las leves a los seis meses.',null),
('adm-cm:23-d8147c35aa','adm-cm',23,'Tras presentar un documento en el registro electrónico se emite automáticamente:','["Un recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada", "Una resolución de admisión a trámite firmada por el órgano competente para resolver, con indicación del plazo máximo para hacerlo", "Un justificante sin fecha, que se completa el primer día hábil siguiente", "Un código para consultar el expediente, sin copia del documento presentado"]'::jsonb,0,'Art. 16.3 Ley 39/2015','El registro emite automáticamente un recibo consistente en una copia autenticada del documento, con fecha, hora y número de entrada.',null),
('adm-cm:23-6ccd1067be','adm-cm',23,'Una vez digitalizados por la oficina de asistencia, los documentos originales presentados presencialmente:','["Se remiten siempre al archivo central de la consejería que tramita el expediente, para su custodia hasta que se dicte la resolución", "Se destruyen una vez transcurridos quince días hábiles desde su presentación", "Se conservan en la oficina de asistencia durante un año y después se devuelven", "Se devuelven al interesado, salvo que una norma determine su custodia por la Administración"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Los originales se devuelven al interesado, sin perjuicio de los supuestos en que la norma determine la custodia por la Administración.',null),
('adm-cm:23-af0c07293b','adm-cm',23,'Las Administraciones deben hacer pública y mantener actualizada:','["La lista de los funcionarios que digitalizan documentos en cada oficina", "La lista de los interesados que han presentado documentos en papel durante el último año", "Una relación de las oficinas en las que se presta asistencia para la presentación electrónica de documentos", "Una relación de los documentos que no pueden presentarse en el registro electrónico"]'::jsonb,2,'Art. 16.7 Ley 39/2015','El art. 16.7 obliga a publicar y actualizar la relación de oficinas de asistencia en materia de registros.',null),
('adm-cm:23-6358c420a8','adm-cm',23,'Los documentos electrónicos deben conservarse en un formato que permita garantizar:','["Su autenticidad, integridad y conservación, y su consulta con independencia del tiempo transcurrido", "Su consulta durante los cinco años siguientes a la finalización del procedimiento, plazo tras el cual pueden eliminarse sin más trámite", "Su conversión obligatoria a papel cuando el procedimiento termine", "Su integridad mientras el procedimiento esté en tramitación, pero no después"]'::jsonb,0,'Art. 17.2 Ley 39/2015','El art. 17.2 exige un formato que garantice autenticidad, integridad y conservación, y la consulta sin importar el tiempo transcurrido.',null),
('adm-cm:23-d8382d38c9','adm-cm',23,'Con carácter general, ¿pueden las Administraciones exigir a los interesados la presentación de documentos originales?','["Sí, siempre que el procedimiento se haya iniciado a solicitud del interesado", "Sí, en todo caso, cuando se trate de documentos de carácter público", "No, en ningún caso, ni siquiera cuando lo establezca una norma reguladora", "No, salvo que excepcionalmente la normativa reguladora aplicable establezca lo contrario"]'::jsonb,3,'Art. 28.3 Ley 39/2015','Las Administraciones no exigen originales, salvo que con carácter excepcional la normativa aplicable establezca lo contrario.',null),
('adm-cm:23-f05aef82c6','adm-cm',23,'Si existen dudas derivadas de la calidad de la copia aportada por el interesado, la Administración puede:','["Tener la copia por no presentada y archivar el procedimiento de oficio", "Exigir que el interesado aporte en el plazo de un mes una copia compulsada por notario o por el secretario de un ayuntamiento", "Solicitar de manera motivada el cotejo de la copia, requiriendo la exhibición del original", "Inadmitir la solicitud sin más trámite, por falta de un requisito esencial"]'::jsonb,2,'Art. 28.5 Ley 39/2015','Excepcionalmente, la Administración puede solicitar motivadamente el cotejo y requerir la exhibición del documento original.',null),
('adm-cm:23-627ca70a1b','adm-cm',23,'Según el art. 28.7 de la Ley 39/2015, de la veracidad de los documentos que presentan responden:','["El funcionario que digitaliza los documentos", "Los interesados", "El órgano instructor del procedimiento", "La oficina de asistencia que los registra"]'::jsonb,1,'Art. 28.7 Ley 39/2015','Los interesados se responsabilizarán de la veracidad de los documentos que presenten.',null),
('adm-cm:23-7c663c8477','adm-cm',23,'La presentación de documentos en el registro electrónico en un día inhábil se entiende realizada:','["Al día siguiente, aunque también sea inhábil", "El último día hábil anterior", "En el mismo día inhábil, a todos los efectos", "En la primera hora del primer día hábil siguiente, salvo que una norma permita expresamente la recepción en día inhábil"]'::jsonb,3,'Art. 31.2 b) Ley 39/2015','Los documentos se consideran presentados por el orden de hora efectiva en el que lo fueron en el día inhábil.',null),
('adm-cm:23-feb6cfddb8','adm-cm',23,'El registro electrónico de cada Administración permite la presentación de documentos:','["Todos los días del año, durante las veinticuatro horas", "En días hábiles, pero durante las veinticuatro horas de cada día", "En días hábiles, de 9 a 14 horas, como las oficinas presenciales", "Todos los días del año, pero solo en el horario de atención al público"]'::jsonb,0,'Art. 31.2 a) Ley 39/2015','El cómputo de plazos se rige por la fecha y hora oficial de la sede electrónica.',null),
('adm-cm:23-cbb14359a3','adm-cm',23,'Los asientos en el registro electrónico se anotan:','["Agrupados por procedimientos administrativos al final de cada jornada de trabajo", "Respetando el orden temporal de recepción o salida de los documentos", "Por orden alfabético del apellido del interesado", "Por orden de importancia del asunto, según decida el responsable del registro"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Indican la fecha del día en que se producen.',null),
('adm-cm:23-d6bb40d2e6','adm-cm',23,'Los documentos que los interesados presenten en papel en las oficinas de asistencia en materia de registros:','["Se destruyen tras su presentación para evitar duplicidades", "Se archivan en papel en la oficina, sin digitalizarlos", "Se digitalizan para incorporarlos al expediente electrónico y se devuelven los originales al interesado", "Se remiten por valija a la unidad tramitadora, que los conserva en papel junto con el resto del expediente"]'::jsonb,2,'Art. 16.5 Ley 39/2015','Salvo que la norma determine la custodia de los documentos por la Administración o que se trate de objetos o documentos en un soporte específico no susceptibles de digitalización.',null),
('adm-cm:23-c0af7bd1ee','adm-cm',23,'¿Qué registro deben mantener las Administraciones de los funcionarios habilitados para expedir copias auténticas y asistir en la presentación electrónica?','["Un registro o sistema equivalente de funcionarios habilitados", "Un registro electrónico de apoderamientos otorgados por los interesados", "Un registro de convenios suscritos con otras Administraciones públicas", "Un registro de órganos colegiados y de sus miembros titulares y suplentes"]'::jsonb,0,'Art. 12.3 Ley 39/2015','El registro electrónico de apoderamientos recoge las representaciones otorgadas por los interesados.',null),
('adm-cm:23-13b0b2b8fb','adm-cm',23,'Las copias auténticas de documentos públicos administrativos o privados realizadas por las Administraciones:','["Tienen valor informativo y no pueden aportarse a otros procedimientos", "Valen durante seis meses desde su expedición", "Son válidas dentro de la Administración que las expide y en sus organismos públicos", "Tienen la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Pueden expedirse en papel o en soporte electrónico.',null),
('adm-cm:23-141a3d2147','adm-cm',23,'Cada Administración debe mantener un archivo electrónico único de:','["Todos los escritos en papel presentados por los ciudadanos", "Los documentos electrónicos que correspondan a procedimientos finalizados", "Las resoluciones judiciales que le afecten", "Los expedientes de personal de todos sus funcionarios y del personal laboral a su servicio"]'::jsonb,1,'Art. 17.1 Ley 39/2015','Los documentos se conservan en un formato que permita garantizar su autenticidad, integridad y conservación.',null),
('adm-cm:24-48dc2ad11f','adm-cm',24,'La LO 3/2018 de Protección de Datos tiene por objeto:','["Sustituir al Reglamento (UE) 2016/679 y regular los derechos digitales", "Adaptar el ordenamiento español al Reglamento (UE) 2016/679 y garantizar los derechos digitales", "Trasponer la Directiva 95/46/CE y regular la videovigilancia", "Adaptar el ordenamiento al Reglamento (UE) 2016/679, pero sin regular los llamados derechos digitales"]'::jsonb,1,'Art. 1 LO 3/2018','Adapta el ordenamiento al Reglamento (UE) 2016/679 y garantiza los derechos digitales conforme al art. 18.4 de la Constitución.',null),
('adm-cm:24-d47b200084','adm-cm',24,'El deber de confidencialidad de quienes intervienen en el tratamiento de datos:','["Termina al finalizar la relación con el responsable", "Dura un año tras finalizar la relación", "Se mantiene aun cuando haya finalizado la relación", "Solo afecta al responsable del tratamiento"]'::jsonb,2,'Art. 5 LO 3/2018','Afecta a responsables, encargados y demás intervinientes, y se mantiene aun cuando haya finalizado la relación.',null),
('adm-cm:24-334d721da9','adm-cm',24,'¿Cómo define la LO 3/2018 el consentimiento del afectado?','["Toda manifestación de voluntad libre, informada e inequívoca, aunque sea tácita o derive del silencio", "Toda manifestación de voluntad expresa y por escrito, firmada en papel o electrónicamente", "La aceptación tácita de las condiciones, siempre que se haya informado previamente", "Toda manifestación de voluntad libre, específica, informada e inequívoca"]'::jsonb,3,'Art. 6.1 LO 3/2018','Es toda manifestación de voluntad libre, específica, informada e inequívoca, mediante una declaración o una clara acción afirmativa.',null),
('adm-cm:24-9defd8904b','adm-cm',24,'El tratamiento de los datos de un menor puede basarse en su propio consentimiento cuando sea mayor de:','["Catorce años", "Dieciséis años", "Doce años", "Dieciocho años"]'::jsonb,0,'Art. 7.1 LO 3/2018','Solo cuando sea mayor de catorce años, salvo que la ley exija la asistencia de los titulares de la patria potestad o tutela.','abr. 2026 · 1.er ejercicio'),
('adm-cm:24-2e2a886f63','adm-cm',24,'¿Basta el consentimiento del afectado para tratar datos cuya finalidad principal sea identificar su ideología o religión?','["Sí, siempre", "No, el solo consentimiento no basta para levantar la prohibición", "Sí, si es por escrito", "Solo si lo autoriza la Agencia Española de Protección de Datos"]'::jsonb,1,'Art. 9.1 LO 3/2018','El solo consentimiento no basta para tratar datos cuya finalidad principal sea identificar ideología, afiliación sindical, religión, orientación sexual, creencias u origen racial o étnico.',null),
('adm-cm:24-f465072d37','adm-cm',24,'Los artículos 13 a 18 de la LO 3/2018 regulan los derechos de:','["Petición, queja, sugerencia, acceso a archivos y registros públicos, y reclamación ante la Agencia", "Acceso a la información pública, rectificación, reclamación y oposición", "Acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición", "Rectificación, réplica, supresión y olvido en medios de comunicación"]'::jsonb,2,'Arts. 13 a 18 LO 3/2018','Regulan, en este orden, los derechos de acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición.','oct. 2026 · 1.er ejercicio'),
('adm-cm:24-cb5bcb6ae6','adm-cm',24,'¿Cuándo deben designar un delegado de protección de datos los responsables y encargados del tratamiento?','["Solo cuando tengan más de 250 empleados o traten datos de más de 10.000 personas", "En ningún caso es obligatorio, aunque la ley recomienda su designación a las entidades públicas", "Solo cuando lo requiera expresamente la Agencia Española de Protección de Datos", "En los supuestos del art. 37.1 del Reglamento (UE) 2016/679 y en las entidades que enumera la ley"]'::jsonb,3,'Art. 34.1 LO 3/2018','Deben designarlo en los supuestos del art. 37.1 del Reglamento europeo y, en todo caso, en las entidades que enumera el propio artículo.',null),
('adm-cm:24-1e0e681962','adm-cm',24,'La Agencia Española de Protección de Datos es:','["Una autoridad administrativa independiente de ámbito estatal", "Una dirección general adscrita al Ministerio del Interior, sin personalidad jurídica", "Un órgano adscrito al Consejo General del Poder Judicial", "Una agencia de la Unión Europea con sede en España"]'::jsonb,0,'Art. 44.1 LO 3/2018','Es una autoridad administrativa independiente de ámbito estatal.',null),
('adm-cm:24-a1483b86a7','adm-cm',24,'El mandato de la Presidencia de la Agencia Española de Protección de Datos es de:','["Cuatro años, no renovable", "Cinco años, renovable por otro periodo de igual duración", "Seis años, no renovable, contados desde su toma de posesión", "Cuatro años, renovable por otro periodo de igual duración"]'::jsonb,1,'Art. 48.5 LO 3/2018','El mandato es de cinco años y puede renovarse por otro periodo de igual duración.',null),
('adm-cm:24-cb11a53015','adm-cm',24,'¿Cuándo prescriben las infracciones leves en materia de protección de datos?','["A los seis meses", "A los dos años", "Al año", "A los tres años"]'::jsonb,2,'Art. 74 LO 3/2018','Las infracciones muy graves prescriben a los tres años (art. 72), las graves a los dos años (art. 73) y las leves al año (art. 74).',null),
('adm-cm:24-f858cbe811','adm-cm',24,'Las sanciones de protección de datos de importe superior a 300.000 euros prescriben a:','["Al año", "Los dos años", "Los seis meses", "Los tres años"]'::jsonb,3,'Art. 78.1 LO 3/2018','Hasta 40.000 € prescriben al año; entre 40.001 y 300.000 €, a los dos años; y las superiores a 300.000 €, a los tres años.',null),
('adm-cm:24-2bdb49d573','adm-cm',24,'¿Se aplica el régimen sancionador de la LO 3/2018 al delegado de protección de datos?','["No", "Sí, en todo caso", "Solo por infracciones muy graves", "Solo si es personal laboral"]'::jsonb,0,'Art. 70.2 LO 3/2018','El régimen sancionador de la ley no es de aplicación al delegado de protección de datos.',null),
('adm-cm:24-b6e6cda164','adm-cm',24,'Los herederos de una persona fallecida, ¿pueden solicitar el acceso, la rectificación o la supresión de sus datos?','["No, salvo que el fallecido lo hubiese autorizado expresamente en vida", "Sí, salvo que el fallecido lo hubiese prohibido expresamente o lo establezca una ley", "Sí, pero solo con autorización judicial y acreditando un interés legítimo", "Sí, durante el primer año tras el fallecimiento, salvo prohibición expresa del fallecido"]'::jsonb,1,'Art. 3.1 LO 3/2018','Pueden hacerlo las personas vinculadas al fallecido por razones familiares o de hecho y sus herederos, salvo prohibición expresa del fallecido o de una ley.',null),
('adm-cm:24-c1bb174363','adm-cm',24,'El derecho al olvido en búsquedas de Internet permite pedir a los motores de búsqueda:','["Que eliminen de los resultados de una búsqueda por el nombre los enlaces a información inadecuada, inexacta, no pertinente, no actualizada o excesiva", "Que paguen una indemnización automática", "Que borren la página web original en todo caso, junto con todas sus copias y enlaces, aunque la información sea exacta, pertinente y actualizada y su difusión sea lícita", "Que cierren la cuenta del usuario"]'::jsonb,0,'Art. 93.1 LO 3/2018','Es el derecho al olvido frente a buscadores.',null),
('adm-cm:24-54de055a92','adm-cm',24,'El acceso a los contenidos gestionados por prestadores de servicios digitales de personas fallecidas se regula en la LO 3/2018 como:','["Testamento digital", "Herencia yacente", "Derecho de rectificación", "Derecho de portabilidad"]'::jsonb,0,'Art. 96 LO 3/2018','Salvo que el fallecido lo hubiese prohibido expresamente.',null),
('adm-cm:24-d54a0d64a2','adm-cm',24,'En ningún caso se admitirá la instalación de sistemas de grabación de sonidos o videovigilancia en:','["Las entradas de los edificios", "Los aparcamientos", "Lugares destinados al descanso o esparcimiento de los trabajadores, como vestuarios, aseos o comedores", "Las zonas de caja y de atención al público, aunque se informe previamente a los trabajadores"]'::jsonb,2,'Art. 89.2 LO 3/2018','Protección de la intimidad en el trabajo.',null),
('adm-cm:24-5b07e83928','adm-cm',24,'En los sistemas de información crediticia, los datos solo pueden mantenerse mientras persista el incumplimiento, con el límite máximo de:','["Cinco años desde la fecha de vencimiento de la obligación", "Diez años", "Un año", "Seis años desde la fecha de inclusión en el sistema"]'::jsonb,0,'Art. 20.1 d) LO 3/2018','Límite temporal de los ficheros de morosos.',null),
('adm-cm:24-0ab72dbf83','adm-cm',24,'Quienes pretendan realizar comunicaciones de mercadotecnia directa deben consultar previamente:','["El censo electoral", "El Registro Civil", "El padrón municipal de habitantes y el censo de empresas", "Los sistemas de exclusión publicitaria"]'::jsonb,3,'Art. 23.4 LO 3/2018','Salvo que el afectado haya prestado su consentimiento a recibirlas.',null),
('adm-cm:24-2d40697a01','adm-cm',24,'El tratamiento de los datos de un menor de catorce años fundado en el consentimiento solo es lícito si consta:','["El consentimiento del propio menor, si tiene madurez suficiente", "El consentimiento del titular de la patria potestad o tutela", "El consentimiento del centro escolar", "Una autorización judicial en todo caso"]'::jsonb,1,'Art. 7.2 LO 3/2018','A partir de los 14 años el menor puede consentir por sí mismo.',null),
('adm-cm:24-97c296445d','adm-cm',24,'La prueba del cumplimiento del deber de responder a la solicitud de ejercicio de derechos corresponde a:','["El encargado del tratamiento", "La AEPD", "El responsable del tratamiento", "El afectado"]'::jsonb,2,'Art. 12.4 LO 3/2018','La carga de la prueba recae en el responsable.',null),
('adm-cm:24-6cfc7761f8','adm-cm',24,'El procedimiento sancionador en materia de protección de datos tendrá una duración máxima de:','["Doce meses desde la fecha del acuerdo de inicio", "Dos años desde la fecha de la reclamación del interesado", "Seis meses desde la fecha de presentación de la denuncia", "Tres meses"]'::jsonb,0,'Art. 64.2 LO 3/2018','Así lo establece el art. 64.2.',null),
('adm-cm:24-85a084044b','adm-cm',24,'El plazo para resolver el procedimiento cuando se reclama exclusivamente la falta de atención de una solicitud de ejercicio de derechos es de:','["Un mes", "Doce meses", "Tres meses", "Seis meses"]'::jsonb,3,'Art. 64.1 LO 3/2018','El procedimiento sancionador tiene una duración máxima de doce meses (art. 64.2).',null),
('adm-cm:24-3a507fd39d','adm-cm',24,'Las imágenes captadas por sistemas de videovigilancia deben suprimirse, con carácter general, en el plazo máximo de:','["Una semana desde su captación", "Un mes desde su captación", "Tres meses desde su captación", "Un año desde su captación"]'::jsonb,1,'Art. 22.3 LO 3/2018','Salvo que deban conservarse para acreditar actos contra personas, bienes o instalaciones.','nov. 2024 · 1.er ejercicio'),
('adm-cm:24-c98fa13d60','adm-cm',24,'Según el art. 2.2 de la LO 3/2018, la ley NO se aplica, sin perjuicio de su art. 3, a:','["Los tratamientos de las Administraciones Públicas", "Los datos de menores", "Los tratamientos de datos de personas fallecidas", "Los datos de salud"]'::jsonb,2,'Art. 2.2 LO 3/2018','También quedan excluidos los tratamientos fuera del RGPD y las materias clasificadas.',null),
('adm-cm:24-250b2ee352','adm-cm',24,'La Presidencia y el Adjunto de la AEPD son nombrados:','["Por elección directa de los ciudadanos entre los candidatos propuestos por el Congreso, el Senado y el Consejo General del Poder Judicial, por cinco años", "Por el Consejo de Ministros mediante real decreto, a propuesta del Gobierno y tras su ratificación por la Comisión de Justicia del Congreso", "Por el Consejo General del Poder Judicial", "Por el Rey a propuesta del Senado, por mayoría de tres quintos, tras una comparecencia pública ante la Comisión Constitucional y previo informe favorable del Consejo de Estado"]'::jsonb,1,'Art. 48.3 LO 3/2018','El mandato es de cinco años renovable.',null),
('adm-cm:24-f36342148c','adm-cm',24,'Las actuaciones del responsable para atender las solicitudes de ejercicio de derechos serán, con carácter general:','["De pago obligatorio", "Gratuitas solo para menores", "Sujetas a tasa estatal", "Gratuitas"]'::jsonb,3,'Art. 12.7 LO 3/2018','Sin perjuicio de lo dispuesto en el RGPD para solicitudes infundadas o excesivas.',null),
('adm-cm:24-9c34aee146','adm-cm',24,'Las infracciones graves en materia de protección de datos prescriben a los:','["Seis meses", "Tres años", "Dos años", "Un año"]'::jsonb,2,'Art. 73 LO 3/2018','Las muy graves a los tres años.',null),
('adm-cm:24-8a072081c3','adm-cm',24,'Según el art. 81 de la LO 3/2018:','["Solo los mayores de edad pueden acceder a Internet", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica", "El acceso a Internet depende de autorización administrativa", "Todos tienen derecho a acceder a Internet, salvo las limitaciones que establezca cada prestador por razones económicas o geográficas"]'::jsonb,1,'Art. 81.1 LO 3/2018','Derecho de acceso universal a Internet.',null),
('adm-cm:24-afc1146cf0','adm-cm',24,'Las infracciones muy graves en materia de protección de datos prescriben a los:','["Un año", "Tres años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 72.1 LO 3/2018','Las graves a los dos años y las leves al año.',null),
('adm-cm:24-1a8ae62b34','adm-cm',24,'Los responsables y encargados deben comunicar a la AEPD o autoridad autonómica las designaciones, nombramientos y ceses de los delegados de protección de datos en el plazo de:','["Un mes", "Tres días", "Diez días", "Quince días"]'::jsonb,2,'Art. 34.3 LO 3/2018','Plazo de diez días.',null),
('adm-cm:24-846bd25a8b','adm-cm',24,'El derecho a la desconexión digital garantiza a los trabajadores y empleados públicos:','["El uso libre de redes sociales en el trabajo", "Que puedan desconectar los dispositivos de la oficina durante la jornada laboral cuando lo consideren necesario para concentrarse en sus tareas", "Que no se use el correo electrónico en la empresa", "El respeto de su tiempo de descanso, permisos y vacaciones fuera del tiempo de trabajo legal o convencionalmente establecido"]'::jsonb,3,'Art. 88.1 LO 3/2018','El empleador debe elaborar una política interna, previa audiencia de los representantes.',null),
('adm-cm:24-a7239d845f','adm-cm',24,'El ejercicio del derecho de acceso más de una vez durante el plazo de ___ podrá considerarse repetitivo, salvo causa legítima:','["Seis meses", "Tres meses", "Un año", "Un mes"]'::jsonb,0,'Art. 13.3 LO 3/2018','Así lo dispone el art. 13.3.',null),
('adm-cm:24-7e2cace560','adm-cm',24,'Transcurrido el plazo de prescripción de las posibles responsabilidades, los datos bloqueados deberán ser:','["Destruidos", "Transferidos a la AEPD", "Publicados", "Conservados indefinidamente"]'::jsonb,0,'Art. 32.2 LO 3/2018','El bloqueo es temporal hasta la prescripción.',null),
('adm-cm:24-05f22c005e','adm-cm',24,'Si el afectado presenta una reclamación previa ante el delegado de protección de datos, este deberá comunicar su decisión en el plazo máximo de:','["Un mes", "Diez días", "Seis meses", "Dos meses"]'::jsonb,3,'Art. 37.1 LO 3/2018','Si la AEPD remite la reclamación al delegado, este responde en un mes (art. 37.2).',null),
('adm-cm:25-9a3342dead','adm-cm',25,'Según el art. 8.2 del TREBEP, los empleados públicos se clasifican en:','["Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual", "Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal directivo profesional", "Funcionarios de carrera, personal laboral, personal eventual y personal directivo", "Funcionarios de carrera, funcionarios interinos y personal laboral fijo o temporal"]'::jsonb,0,'Art. 8.2 TREBEP','Se clasifican en funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual.','abr. 2026 · 1.er ejercicio'),
('adm-cm:25-5b04e4287c','adm-cm',25,'Las funciones que implican participación directa o indirecta en el ejercicio de potestades públicas corresponden:','["A cualquier empleado público, sea funcionario o laboral", "Exclusivamente a los funcionarios públicos", "Al personal laboral fijo y a los funcionarios de carrera, en los términos que establezca la ley de cada Administración", "Exclusivamente a los funcionarios de carrera, nunca a los interinos"]'::jsonb,1,'Art. 9.2 TREBEP','Corresponden exclusivamente a los funcionarios públicos, en los términos que establezca la ley de desarrollo de cada Administración.',null),
('adm-cm:25-fb86a3b5d9','adm-cm',25,'Un funcionario interino nombrado para cubrir una plaza vacante puede ocuparla como máximo:','["Un año", "Dos años", "Tres años", "Cinco años"]'::jsonb,2,'Art. 10.1 a) TREBEP','Las plazas vacantes pueden cubrirse por interinos cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.',null),
('adm-cm:25-22947fe7c3','adm-cm',25,'El nombramiento de interinos por exceso o acumulación de tareas tiene un plazo máximo de:','["Seis meses dentro de un periodo de doce", "Doce meses dentro de un periodo de veinticuatro", "Tres años", "Nueve meses dentro de un periodo de dieciocho"]'::jsonb,3,'Art. 10.1 d) TREBEP','El plazo máximo es de nueve meses dentro de un periodo de dieciocho meses.',null),
('adm-cm:25-71a4bb4e93','adm-cm',25,'El nombramiento de interinos para ejecutar programas de carácter temporal no puede superar:','["Tres años, ampliable hasta doce meses más por las leyes de Función Pública", "Dos años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo del Estatuto", "Tres años, sin posibilidad de ampliación", "Cuatro años, ampliable hasta doce meses más por las leyes de Función Pública"]'::jsonb,0,'Art. 10.1 c) TREBEP','No puede ser superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública de cada Administración.',null),
('adm-cm:25-9fd3d0d0ef','adm-cm',25,'El personal eventual realiza funciones:','["De carácter técnico permanente, previstas en la relación de puestos de trabajo de cada Administración", "Expresamente calificadas como de confianza o asesoramiento especial", "De inspección y control, expresamente calificadas como tales", "De confianza, pero que implican el ejercicio de potestades públicas"]'::jsonb,1,'Art. 12.1 TREBEP','El personal eventual solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.',null),
('adm-cm:25-ffa2129553','adm-cm',25,'Haber sido personal eventual, ¿puede constituir mérito para el acceso a la función pública?','["Sí, siempre", "Sí, si se prestaron servicios más de un año", "No", "Solo en la promoción interna"]'::jsonb,2,'Art. 12.4 TREBEP','La condición de personal eventual no puede constituir mérito para el acceso a la Función Pública o para la promoción interna.',null),
('adm-cm:25-fb1083c9a9','adm-cm',25,'¿Qué titulación se exige para acceder a un cuerpo del subgrupo C2?','["Bachiller o Técnico", "Graduado en Educación Secundaria Obligatoria", "Técnico Superior o equivalente a efectos profesionales", "Certificado de escolaridad o de estudios primarios"]'::jsonb,1,'Art. 76 TREBEP','Para el subgrupo C2 se exige el título de Graduado en ESO; para el C1, Bachiller o Técnico.',null),
('adm-cm:25-ada34b9833','adm-cm',25,'Según la Ley 1/1986 de la Función Pública de la Comunidad de Madrid, su personal se integra por:','["Funcionarios de carrera y personal eventual", "Funcionarios de carrera, personal laboral y personal directivo", "Únicamente funcionarios de carrera", "Funcionarios de carrera, funcionarios interinos y personal laboral"]'::jsonb,3,'Art. 5 Ley 1/1986 CM','La ley madrileña distingue funcionarios de carrera, funcionarios interinos y personal laboral.',null),
('adm-cm:25-1e7b618c1c','adm-cm',25,'En la Comunidad de Madrid, ¿quién aprueba la oferta anual de empleo público?','["El Consejo de Gobierno", "La Asamblea de Madrid", "La Dirección General de Función Pública", "El Presidente de la Comunidad"]'::jsonb,0,'Art. 7.2 e) Ley 1/1986 CM','Corresponde al Consejo de Gobierno aprobar la oferta anual de empleo público.',null),
('adm-cm:25-3eef4dc8f9','adm-cm',25,'Según la Ley 1/1986, ¿puede alguien ser incluido en la nómina sin estar inscrito en el Registro de Personal?','["Sí, de forma provisional durante un mes", "No", "Sí, si es personal laboral", "Sí, con autorización del Consejero"]'::jsonb,1,'Art. 11.3 Ley 1/1986 CM','Nadie puede ser incluido en nómina sin haber sido inscrito antes en el Registro de Personal.',null),
('adm-cm:25-34ff2223e1','adm-cm',25,'¿En cuántos niveles se clasifican los puestos de trabajo reservados a funcionarios en la Comunidad de Madrid?','["Veinte", "Veinticinco", "Treinta", "Cuarenta"]'::jsonb,2,'Art. 42.1 Ley 1/1986 CM','Los puestos reservados a funcionarios se clasifican en treinta niveles.',null),
('adm-cm:25-a00dd0dfba','adm-cm',25,'El grado personal se adquiere por el desempeño de puestos del nivel correspondiente durante:','["Un año consecutivo o dos con interrupción", "Tres años consecutivos o cuatro con interrupción, en puestos de nivel igual o superior", "Cinco años consecutivos", "Dos años consecutivos o tres con interrupción"]'::jsonb,3,'Art. 44.2 Ley 1/1986 CM','Se adquiere tras desempeñar uno o más puestos del nivel correspondiente durante dos años consecutivos o tres con interrupción.',null),
('adm-cm:25-bb3612176f','adm-cm',25,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Menos de 6 funcionarios", "Entre 6 y 49 funcionarios", "Más de 250 funcionarios"]'::jsonb,2,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null),
('adm-cm:25-136b2ba37c','adm-cm',25,'El personal eventual:','["Tiene derecho a la inamovilidad tras dos años de servicio, y su nombramiento corresponde al órgano de selección tras un concurso de méritos con convocatoria pública", "Ocupa puestos reservados a funcionarios de carrera", "Solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, y su nombramiento y cese son libres", "Accede mediante concurso de méritos"]'::jsonb,2,'Art. 12.1 y 12.3 TREBEP','El cese tiene lugar, en todo caso, cuando se produzca el de la autoridad a la que preste su función de confianza.',null),
('adm-cm:25-59ab978ae8','adm-cm',25,'La oferta de empleo público deberá desarrollarse dentro del plazo improrrogable de:','["Tres años", "Un año", "Dos años", "Cinco años"]'::jsonb,0,'Art. 70.1 TREBEP','La oferta puede contener hasta un 10 % adicional de plazas.',null),
('adm-cm:25-030f8b6bea','adm-cm',25,'Quedan excluidas de la obligatoriedad de la negociación:','["Las retribuciones complementarias de los funcionarios", "Las decisiones que afecten a las potestades de organización de las Administraciones Públicas", "Los criterios generales de acceso, carrera, provisión, sistemas de clasificación de puestos y planes de recursos humanos", "La evaluación del desempeño"]'::jsonb,1,'Art. 37.2 a) TREBEP','Las demás opciones son materias objeto de negociación (art. 37.1).',null),
('adm-cm:25-f5d32b2bc7','adm-cm',25,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado", "Pasa a ser plaza de personal laboral", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('adm-cm:25-d75dcb88e1','adm-cm',25,'La designación del personal directivo profesional atenderá a principios de:','["Libre designación política por el titular del órgano superior", "Sorteo entre funcionarios del subgrupo A1", "Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia"]'::jsonb,3,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('adm-cm:25-059bb2021f','adm-cm',25,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación", "Duran cuatro años improrrogables"]'::jsonb,0,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('adm-cm:25-8f688d7462','adm-cm',25,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["El 10 % de los miembros de los órganos unitarios de representación", "La totalidad de los miembros de los órganos unitarios de representación", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate"]'::jsonb,2,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('adm-cm:25-de3a58eca6','adm-cm',25,'La duración del mandato de los Delegados de Personal y de las Juntas de Personal es de:','["Tres años", "Cinco años", "Dos años", "Cuatro años"]'::jsonb,3,'Art. 42 TREBEP','Pueden ser reelegidos en sucesivos procesos electorales.',null),
('adm-cm:26-de39acc919','adm-cm',26,'¿Qué edad mínima se exige para participar en los procesos selectivos?','["Dieciséis años", "Dieciocho años", "Diecisiete años", "Veintiún años"]'::jsonb,0,'Art. 56.1 c) TREBEP','Tener cumplidos dieciséis años y no exceder, en su caso, la edad máxima de jubilación forzosa.',null),
('adm-cm:26-bbff3d3256','adm-cm',26,'¿Cuáles son los sistemas selectivos de los funcionarios de carrera?','["Concurso y libre designación con convocatoria pública", "Oposición y concurso-oposición; el concurso, solo con carácter excepcional y en virtud de ley", "Oposición y concurso-oposición; el concurso, con carácter ordinario y sin necesidad de previsión en una ley", "Oposición, concurso y entrevista personal, que pueden utilizarse indistintamente según lo que decida cada convocatoria"]'::jsonb,1,'Art. 61.6 TREBEP','Son la oposición y el concurso-oposición. El concurso de valoración de méritos solo cabe excepcionalmente y en virtud de ley.',null),
('adm-cm:26-4522d5e48c','adm-cm',26,'¿Cuál de los siguientes NO es un requisito para adquirir la condición de funcionario de carrera?','["Superar el proceso selectivo", "Acatar la Constitución", "Haber prestado servicios previos como interino", "Tomar posesión dentro del plazo establecido"]'::jsonb,2,'Art. 62.1 TREBEP','Se requiere superar el proceso selectivo, el nombramiento publicado en el diario oficial, el acatamiento de la Constitución (y Estatuto de Autonomía y resto del ordenamiento) y la toma de posesión.',null),
('adm-cm:26-5991c78f4a','adm-cm',26,'¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?','["La renuncia", "La jubilación total", "La pérdida de la nacionalidad", "La excedencia voluntaria"]'::jsonb,3,'Art. 63 TREBEP','Son causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la pena de inhabilitación firme y la sanción firme de separación del servicio. La excedencia es una situación administrativa.',null),
('adm-cm:26-f807c9d425','adm-cm',26,'La jubilación forzosa de los funcionarios se declara al cumplir:','["65 años, pudiendo solicitar la prolongación hasta los 70", "67 años, sin posibilidad de solicitar la prolongación de la permanencia en el servicio activo", "65 años, pudiendo solicitar la prolongación hasta los 72", "60 años, pudiendo solicitar la prolongación hasta los 65"]'::jsonb,0,'Art. 67.3 TREBEP','Se declara a los sesenta y cinco años, aunque el funcionario puede solicitar la prolongación de la permanencia hasta los setenta.',null),
('adm-cm:26-f10bad8393','adm-cm',26,'En las ofertas de empleo público se reservará un cupo para personas con discapacidad no inferior al:','["2 % de las vacantes", "5 % de las vacantes", "10 % de las vacantes", "7 % de las vacantes"]'::jsonb,3,'Art. 59.1 TREBEP','De ese cupo, al menos el 2 % de las plazas para personas con discapacidad intelectual.',null),
('adm-cm:26-ca478f71f1','adm-cm',26,'Los funcionarios pueden solicitar la prolongación de la permanencia en el servicio activo, una vez cumplida la edad de jubilación forzosa, como máximo hasta:','["Sin límite", "Los setenta años", "Los sesenta y siete años", "Los sesenta y ocho años"]'::jsonb,1,'Art. 67.3 TREBEP','La jubilación forzosa se declara al cumplir 65 años.',null),
('adm-cm:26-4b47392ec7','adm-cm',26,'Los procedimientos de provisión de puestos de trabajo de los funcionarios de carrera son, con carácter general:','["La entrevista y la valoración del currículum", "La oposición y el concurso-oposición", "El concurso y la libre designación con convocatoria pública", "El concurso y la libre designación sin convocatoria pública"]'::jsonb,2,'Art. 78.2 TREBEP','El concurso es el procedimiento normal de provisión.',null),
('adm-cm:26-8fd755646f','adm-cm',26,'La libre designación con convocatoria pública consiste en:','["Una prueba de conocimientos eliminatoria sobre las funciones del puesto, seguida de la valoración de méritos por una comisión técnica independiente", "La antigüedad del candidato", "Un sorteo entre los candidatos", "La apreciación discrecional por el órgano competente de la idoneidad de los candidatos en relación con los requisitos del puesto"]'::jsonb,3,'Art. 80.1 TREBEP','Se aplica a los puestos que determinen las leyes por su especial responsabilidad.',null),
('adm-cm:26-06da7d6933','adm-cm',26,'NO pueden formar parte de los órganos de selección:','["Los funcionarios de carrera de otras Administraciones públicas", "Los funcionarios del mismo cuerpo o escala al que se aspira a ingresar y el personal laboral fijo de la misma Administración", "El personal de elección o designación política, los funcionarios interinos y el personal eventual", "El personal laboral fijo y los funcionarios de carrera que hayan preparado a aspirantes en los cinco años anteriores"]'::jsonb,2,'Art. 60.2 TREBEP','Los órganos de selección son colegiados y tienden a la paridad.',null),
('adm-cm:26-21f3323ae1','adm-cm',26,'Los nacionales de los Estados miembros de la Unión Europea pueden acceder como funcionarios en igualdad de condiciones que los españoles, salvo a los empleos que impliquen:','["Funciones de atención al público en lengua cooficial", "Participación en el ejercicio del poder público o en las funciones de salvaguardia de los intereses del Estado", "Trabajos en entidades locales", "Funciones administrativas, de gestión o de auxilio, aunque no impliquen ejercicio de potestades públicas"]'::jsonb,1,'Art. 57.1 TREBEP','Los extranjeros con residencia legal pueden acceder como personal laboral (art. 57.4).',null),
('adm-cm:26-118d4e3cbf','adm-cm',26,'La renuncia voluntaria a la condición de funcionario:','["Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado", "Puede manifestarse verbalmente ante el superior jerárquico", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público"]'::jsonb,0,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('adm-cm:26-a7d9e8e4d1','adm-cm',26,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["Salvo en la Administración Local, cuando lo acuerde el Pleno", "Salvo que la convocatoria prevea otra cosa", "En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que lo solicite el tribunal"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('adm-cm:26-9640cc0d02','adm-cm',26,'Según el TREBEP, ¿cuál es el procedimiento normal de provisión de puestos de trabajo de los funcionarios de carrera?','["La adscripción provisional", "El concurso", "La comisión de servicios", "La libre designación"]'::jsonb,1,'Art. 78 TREBEP','La libre designación con convocatoria pública es el otro procedimiento ordinario, reservado a puestos determinados por su especial responsabilidad o confianza.',null),
('adm-cm:26-3d389c5e5a','adm-cm',26,'Según el TREBEP, en las ofertas de empleo público se reserva para personas con discapacidad intelectual, dentro del cupo general, al menos:','["El 7 % de las plazas ofertadas", "El 2 % de las plazas ofertadas", "El 1 % de las plazas ofertadas", "El 5 % de las plazas ofertadas"]'::jsonb,1,'Art. 59.1 TREBEP','El cupo total para personas con discapacidad no es inferior al 7 %, y de él al menos el 2 % es para personas con discapacidad intelectual.',null),
('adm-cm:27-c9a41f4f24','adm-cm',27,'¿Cuál de estos es un derecho individual que se ejerce de forma colectiva?','["La inamovilidad en la condición de funcionario", "La formación continua", "Las vacaciones", "El ejercicio de la huelga"]'::jsonb,3,'Art. 15 TREBEP','Son derechos individuales ejercidos colectivamente la libertad sindical, la negociación colectiva y participación, la huelga, el planteamiento de conflictos colectivos y la reunión.',null),
('adm-cm:27-a9df4fca5c','adm-cm',27,'¿Cuántos días de permiso por asuntos particulares tienen los funcionarios al año?','["Seis días", "Cuatro días", "Tres días", "Ocho días"]'::jsonb,0,'Art. 48 k) TREBEP','Por asuntos particulares, seis días al año.',null),
('adm-cm:27-d71a3710ba','adm-cm',27,'¿Cuántos días de permiso corresponden por matrimonio o registro de pareja de hecho?','["Diez días", "Quince días", "Veinte días", "Siete días"]'::jsonb,1,'Art. 48 l) TREBEP','Quince días por matrimonio o registro o constitución formalizada por documento público de pareja de hecho.',null),
('adm-cm:27-fcf9be38d6','adm-cm',27,'¿Qué duración tiene el permiso por nacimiento para la madre biológica según el TREBEP vigente?','["Dieciséis semanas", "Doce semanas", "Diecinueve semanas", "Veinticuatro semanas"]'::jsonb,2,'Art. 49 a) TREBEP','Tras la última reforma son diecinueve semanas (treinta y dos en caso de familia monoparental). Muchos tests antiguos siguen diciendo dieciséis.',null),
('adm-cm:27-a9130b5e20','adm-cm',27,'¿Cuántos días de vacaciones retribuidas tienen los funcionarios por año completo de servicio?','["Treinta días naturales", "Veinte días hábiles", "Veinticinco días hábiles", "Veintidós días hábiles"]'::jsonb,3,'Art. 50.1 TREBEP','Veintidós días hábiles, o los que correspondan proporcionalmente si el tiempo de servicio fue menor.',null),
('adm-cm:27-0201fb536e','adm-cm',27,'Según el art. 54.11, los empleados públicos garantizarán la atención al ciudadano en:','["La lengua oficial que solicite y, si lo pide, también en inglés", "Castellano exclusivamente", "La lengua que lo solicite siempre que sea oficial en el territorio", "La lengua que elija el funcionario"]'::jsonb,2,'Art. 54.11 TREBEP','Es otro principio de conducta.',null),
('adm-cm:27-e5aaf6a92a','adm-cm',27,'Por traslado de domicilio sin cambio de residencia, el funcionario tiene un permiso de:','["Ningún día", "Dos días", "Un día", "Tres días"]'::jsonb,2,'Art. 48 b) TREBEP','Permiso de un día por traslado de domicilio.',null),
('adm-cm:27-07d632e82f','adm-cm',27,'La funcionaria víctima de violencia de género que reduzca su jornada en un tercio o menos:','["Pierde las retribuciones básicas", "Solo cobra el 50 %", "Mantendrá sus retribuciones íntegras", "Pierde todas sus retribuciones"]'::jsonb,2,'Art. 49 d) TREBEP','Si la reducción es mayor, la disminución de retribuciones es proporcional.',null),
('adm-cm:27-941b314597','adm-cm',27,'El permiso parental para el cuidado de hijo o menor acogido por tiempo superior a un año, hasta que cumpla ocho años, tiene una duración máxima de:','["Ocho semanas, y no es retribuido", "Un año", "Dieciséis semanas retribuidas", "Cuatro semanas retribuidas"]'::jsonb,0,'Art. 49 g) TREBEP','Se requiere un preaviso de quince días.',null),
('adm-cm:27-170209b383','adm-cm',27,'El teletrabajo de los empleados públicos:','["Es irreversible una vez concedido y solo puede revocarse como sanción disciplinaria tras el expediente correspondiente", "Solo se permite al personal interino", "Es obligatorio para los puestos cuyas funciones permitan prestarse a distancia, salvo renuncia justificada del empleado", "Tendrá carácter voluntario y reversible, salvo en supuestos excepcionales debidamente justificados"]'::jsonb,3,'Art. 47 bis.2 TREBEP','Se realizará en los términos de las normas que se dicten en desarrollo del Estatuto.',null),
('adm-cm:27-81b14ba8f6','adm-cm',27,'Por accidente o enfermedad grave de un familiar de primer grado de consanguinidad o afinidad, el funcionario tiene un permiso de:','["Cinco días hábiles", "Diez días hábiles", "Tres días naturales", "Dos días hábiles"]'::jsonb,0,'Art. 48 a) TREBEP','Para familiares de segundo grado, cuatro días hábiles.',null),
('adm-cm:27-9bc20410d3','adm-cm',27,'Según el art. 54.6 TREBEP, los empleados públicos:','["Pueden aceptar regalos de cualquier valor siempre que los declaren a su superior jerárquico en el plazo de diez días desde su recepción y los inscriban en el registro", "Deben declarar los regalos recibidos en su declaración de bienes", "Solo pueden aceptar regalos de otros empleados públicos o de los ciudadanos, siempre que no superen el valor que fije cada Administración en su código ético", "Rechazarán cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía"]'::jsonb,3,'Art. 54.6 TREBEP','Es un principio de conducta.',null),
('adm-cm:27-44cb7333fd','adm-cm',27,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La formación continua y la actualización permanente de sus conocimientos", "La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad", "El planteamiento de conflictos colectivos de trabajo"]'::jsonb,0,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('adm-cm:27-da12b76869','adm-cm',27,'A efectos de vacaciones de los funcionarios, los sábados:','["No se consideran días hábiles, salvo en los horarios especiales", "Computan doble", "Se consideran hábiles solo en agosto", "Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario"]'::jsonb,0,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('adm-cm:27-e29493c705','adm-cm',27,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Un año de servicio activo en el mismo cuerpo o escala", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración", "Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('adm-cm:27-45ccf459a6','adm-cm',27,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Tres días hábiles", "Dos días hábiles", "Un día"]'::jsonb,1,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('adm-cm:27-39e9ef683e','adm-cm',27,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Un año a partir del final del año en que se hayan originado", "Tres años", "Seis meses a partir del final del año en que se hayan originado", "Dieciocho meses a partir del final del año en que se hayan originado"]'::jsonb,3,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('adm-cm:27-f3bf44ca5c','adm-cm',27,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Dos semanas", "Seis semanas", "Diez semanas", "Cuatro semanas"]'::jsonb,1,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('adm-cm:28-f7d5da4687','adm-cm',28,'¿Cuál de estas NO es una situación administrativa de los funcionarios de carrera?','["Servicios especiales", "Excedencia", "Comisión de servicios", "Suspensión de funciones"]'::jsonb,2,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones. La comisión de servicios es una forma de provisión de puestos.','oct. 2026 · 1.er ejercicio'),
('adm-cm:28-9f4e2816e7','adm-cm',28,'Para obtener la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante un mínimo de:','["Un año inmediatamente anterior a la solicitud", "Dos años inmediatamente anteriores", "Tres años, consecutivos o no, en cualquier Administración", "Cinco años inmediatamente anteriores"]'::jsonb,3,'Art. 89.2 TREBEP','Se exige haber prestado servicios efectivos en cualquier Administración durante un mínimo de cinco años inmediatamente anteriores.',null),
('adm-cm:28-ea8e04dd43','adm-cm',28,'La excedencia por cuidado de cada hijo tiene una duración:','["No superior a tres años", "No superior a un año", "No superior a cinco años", "Sin límite"]'::jsonb,0,'Art. 89.4 TREBEP','El periodo de excedencia por cuidado de cada hijo no puede ser superior a tres años.',null),
('adm-cm:28-f142c8ee7d','adm-cm',28,'La suspensión firme de funciones por sanción disciplinaria no puede exceder de:','["Tres años", "Seis años", "Dos años", "Un año"]'::jsonb,1,'Art. 90.2 TREBEP','No puede exceder de seis años. Si supera seis meses, el funcionario pierde su puesto de trabajo (art. 90.1).',null),
('adm-cm:28-2c43e53a6b','adm-cm',28,'Según el TREBEP, las faltas disciplinarias se clasifican en:','["Graves y leves", "Penales y administrativas", "Muy graves, graves y leves", "Muy graves y graves"]'::jsonb,2,'Art. 95.1 TREBEP','Las faltas disciplinarias pueden ser muy graves, graves y leves.',null),
('adm-cm:28-3a335bf7a9','adm-cm',28,'¿Cuál de las siguientes sanciones NO aparece expresamente en la lista del art. 96.1 del TREBEP?','["Apercibimiento", "Demérito", "Traslado forzoso", "Multa económica"]'::jsonb,3,'Art. 96.1 TREBEP','Recoge la separación del servicio, el despido disciplinario, la suspensión firme de funciones, el traslado forzoso, el demérito, el apercibimiento y cualquier otra que establezca una ley.',null),
('adm-cm:28-663ed39c97','adm-cm',28,'¿Cuándo prescriben las faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres meses"]'::jsonb,0,'Art. 97 TREBEP','Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses.',null),
('adm-cm:28-c7f15e5bdb','adm-cm',28,'¿Cuándo prescriben las sanciones impuestas por faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres años"]'::jsonb,1,'Art. 97 TREBEP','Las sanciones por faltas muy graves prescriben a los tres años, las graves a los dos años y las leves al año.','oct. 2026 · 1.er ejercicio'),
('adm-cm:28-bcc3aa10a8','adm-cm',28,'La suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:','["Tres meses, salvo paralización del procedimiento imputable al interesado", "Un año, salvo paralización del procedimiento imputable a la Administración que lo tramita", "Seis meses, salvo paralización del procedimiento imputable al interesado", "Seis meses, sin excepción alguna"]'::jsonb,2,'Art. 98.3 TREBEP','No puede exceder de seis meses, salvo en caso de paralización del procedimiento imputable al interesado.',null),
('adm-cm:28-55ebbab79e','adm-cm',28,'El plazo de prescripción de las sanciones comenzará a contarse:','["Desde la firmeza de la resolución sancionadora", "Desde la notificación del pliego de cargos", "Desde la incoación del expediente", "Desde la comisión de la falta"]'::jsonb,0,'Art. 97 TREBEP','El de las faltas, desde que se hubieran cometido, o desde el cese de su comisión si son continuadas.',null),
('adm-cm:28-ee58187867','adm-cm',28,'Las faltas leves se sancionarán:','["Solo por un juez", "Sin procedimiento", "Por el procedimiento previsto para las faltas graves y muy graves", "Por un procedimiento sumario con audiencia al interesado"]'::jsonb,3,'Art. 98.1 TREBEP','Las faltas muy graves y graves exigen el procedimiento previamente establecido.',null),
('adm-cm:28-b5334a28b3','adm-cm',28,'La suspensión de funciones determinará la pérdida del puesto de trabajo cuando exceda de:','["Un año", "Tres meses", "Un mes", "Seis meses"]'::jsonb,3,'Art. 90.1 TREBEP','El funcionario suspenso queda privado del ejercicio de sus funciones.',null),
('adm-cm:28-43d44fd226','adm-cm',28,'Durante la suspensión provisional como medida cautelar, el funcionario:','["Percibe íntegramente sus retribuciones hasta que se resuelva el expediente disciplinario", "No percibe ninguna retribución", "Percibirá las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo", "Percibirá las retribuciones complementarias, pero no las básicas"]'::jsonb,2,'Art. 98.3 TREBEP','Si la suspensión se eleva a definitiva, deberá devolver lo percibido.',null),
('adm-cm:28-a062ed9c72','adm-cm',28,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Ascender automáticamente de grado", "Nada, salvo el cómputo de antigüedad", "La reserva del puesto de trabajo que desempeñaba", "Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad"]'::jsonb,2,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('adm-cm:28-27d42b52b6','adm-cm',28,'Las sanciones impuestas por faltas graves prescriben a los:','["Un año", "Dos años", "Tres años", "Seis meses"]'::jsonb,1,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('adm-cm:28-1082ba238b','adm-cm',28,'Las faltas muy graves prescriben a los:','["Dos años", "Seis meses", "Cinco años", "Tres años"]'::jsonb,3,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('adm-cm:28-0029c292e3','adm-cm',28,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad", "Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir el 50 % de sus retribuciones básicas y complementarias", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo"]'::jsonb,1,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('adm-cm:28-26d384f094','adm-cm',28,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Dos años", "Cinco años", "Un año"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('adm-cm:28-f3f0a931f4','adm-cm',28,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "El abandono del servicio", "La falta de puntualidad ocasional", "Un retraso de diez minutos"]'::jsonb,1,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.','nov. 2024 · 1.er ejercicio'),
('adm-cm:28-3df95677b7','adm-cm',28,'La sanción de separación del servicio de los funcionarios solo podrá imponerse por:','["Faltas graves reiteradas en el plazo de un año", "Cualquier falta", "La comisión de faltas muy graves", "Faltas graves cometidas de forma reiterada"]'::jsonb,2,'Art. 96.1 a) TREBEP','En los interinos implica la revocación del nombramiento.',null),
('adm-cm:28-3558366430','adm-cm',28,'¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera según el artículo 85 del TREBEP?','["Servicios especiales", "Suspensión de funciones", "Servicio en otras Administraciones Públicas", "Expectativa de destino indefinida"]'::jsonb,3,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.',null),
('adm-cm:28-b20ea97764','adm-cm',28,'Los funcionarios que acceden a la condición de diputado o senador de las Cortes Generales pasan a la situación de:','["Suspensión provisional de funciones", "Servicio activo con dispensa de funciones", "Excedencia voluntaria por interés particular", "Servicios especiales"]'::jsonb,3,'Art. 87.1 TREBEP','Tienen derecho a reingresar al servicio activo en la misma localidad y en las mismas condiciones y con las retribuciones correspondientes a su categoría.',null),
('adm-cm:28-88c5f0ee26','adm-cm',28,'Según el TREBEP, los funcionarios en situación de servicios especiales:','["Pierden la condición de funcionario mientras dure la situación", "No tienen derecho a reserva de puesto ni a que se les compute el tiempo a ningún efecto", "Solo tienen derecho al cómputo de trienios, pero no a la reserva de puesto", "Tienen derecho a que se les compute el tiempo en esa situación a efectos de ascensos, reconocimiento de trienios y derechos en el régimen de Seguridad Social"]'::jsonb,3,'Art. 87.2 TREBEP','No se les aplica, sin embargo, el régimen de derechos pasivos si les corresponde otro.',null),
('adm-cm:29-6367240502','adm-cm',29,'Según el TREBEP, ¿por qué normas se rige el personal laboral al servicio de las Administraciones públicas?','["Por el TREBEP en su totalidad, igual que los funcionarios de carrera, sin aplicar la legislación laboral", "Por la ley de función pública de cada comunidad autónoma", "Por la legislación laboral, las normas convencionales y los preceptos del Estatuto que así lo dispongan", "Exclusivamente por el Estatuto de los Trabajadores"]'::jsonb,2,'Art. 7 TREBEP','El personal laboral se rige por la legislación laboral, las normas convencionales y los preceptos del Estatuto que así lo dispongan.',null),
('adm-cm:29-349408f252','adm-cm',29,'¿Qué norma se aplica al personal laboral de las Administraciones en materia de permiso por nacimiento o lactancia?','["El Estatuto de los Trabajadores, en todo caso", "El TREBEP, y no las suspensiones del contrato del Estatuto de los Trabajadores", "La Ley General de la Seguridad Social exclusivamente", "El convenio colectivo, con preferencia sobre cualquier ley"]'::jsonb,1,'Art. 7 TREBEP','En permisos de nacimiento, adopción, del otro progenitor, lactancia y parental, el personal laboral se rige por el TREBEP.',null),
('adm-cm:29-dbc905f20d','adm-cm',29,'Según el TREBEP, ¿cómo debe formalizarse el contrato del personal laboral de las Administraciones?','["Mediante resolución publicada en el boletín oficial", "Por escrito", "De palabra o por escrito, indistintamente", "En documento administrativo ante el secretario general técnico"]'::jsonb,1,'Art. 11.1 TREBEP','Es personal laboral el que, en virtud de contrato de trabajo formalizado por escrito, presta servicios retribuidos por las Administraciones.',null),
('adm-cm:29-523088010a','adm-cm',29,'Según su duración, ¿cómo puede ser el contrato del personal laboral de las Administraciones?','["Estable, discontinuo o de obra", "Indefinido o de interinidad", "Fijo, por tiempo indefinido o temporal", "Fijo o eventual"]'::jsonb,2,'Art. 11.1 TREBEP','En función de la duración del contrato, el personal laboral puede ser fijo, por tiempo indefinido o temporal.',null),
('adm-cm:29-4eb2681522','adm-cm',29,'¿Por qué principios se rige la selección del personal laboral temporal según el TREBEP?','["Igualdad, mérito, capacidad y celeridad", "Antigüedad y proximidad geográfica", "Igualdad y antigüedad únicamente", "Libre designación y confianza"]'::jsonb,0,'Art. 11.3 TREBEP','La selección del personal laboral es pública y se rige por igualdad, mérito y capacidad; la del temporal, además, por la celeridad.',null),
('adm-cm:29-eacea1704c','adm-cm',29,'¿Por qué se rige la negociación colectiva del personal laboral de las Administraciones?','["Por la Ley Orgánica de Libertad Sindical únicamente", "Exclusivamente por el TREBEP", "Por los acuerdos de las mesas generales de funcionarios", "Por la legislación laboral, sin perjuicio de los preceptos del TREBEP aplicables"]'::jsonb,3,'Art. 32.1 TREBEP','La negociación colectiva, representación y participación del personal laboral se rige por la legislación laboral, con los preceptos del capítulo aplicables.',null),
('adm-cm:29-ab9c9a3930','adm-cm',29,'¿Pueden los órganos de gobierno de las Administraciones suspender un convenio colectivo del personal laboral ya firmado?','["Solo si lo aprueba la mayoría de los trabajadores", "Sí, por simple decisión del titular de la consejería afectada, sin necesidad de causa justificada ni de informar a los sindicatos", "No, en ningún caso", "Sí, excepcionalmente y por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas"]'::jsonb,3,'Art. 32.2 TREBEP','Excepcionalmente, por causa grave de interés público derivada de una alteración sustancial de las circunstancias económicas, pueden suspenderse o modificarse en lo estrictamente necesario.',null),
('adm-cm:29-21774ca5cb','adm-cm',29,'Si se suspende o modifica un convenio del personal laboral, ¿a quién debe informar la Administración?','["Al Tribunal Superior de Justicia", "A las organizaciones sindicales", "A la Inspección de Trabajo exclusivamente", "Al Parlamento autonómico"]'::jsonb,1,'Art. 32.2 TREBEP','Las Administraciones deberán informar a las organizaciones sindicales de las causas de la suspensión o modificación.',null),
('adm-cm:29-3fb5697cda','adm-cm',29,'¿Cómo se realiza la provisión de puestos y la movilidad del personal laboral según el TREBEP?','["Por concurso de méritos convocado en todo caso por la Dirección General de Función Pública de la comunidad", "Por el sistema del Estatuto de los Trabajadores exclusivamente", "Según los convenios colectivos y, en su defecto, por el sistema del personal funcionario de carrera", "Siempre por libre designación"]'::jsonb,2,'Art. 83 TREBEP','Se realiza conforme a los convenios colectivos y, en su defecto, por el sistema de provisión y movilidad del personal funcionario de carrera.',null),
('adm-cm:29-338a73ef02','adm-cm',29,'¿Por qué normas se rigen las situaciones del personal laboral según el TREBEP?','["Por el Estatuto de los Trabajadores y los convenios colectivos", "Por el reglamento de situaciones de los funcionarios del Estado", "Por el capítulo de situaciones administrativas del TREBEP", "Por la ley de función pública autonómica"]'::jsonb,0,'Art. 92 TREBEP','Se rigen por el Estatuto de los Trabajadores y los convenios; estos pueden aplicar el capítulo del TREBEP en lo compatible.',null),
('adm-cm:29-4dba9aa69f','adm-cm',29,'¿Cómo se determinan las retribuciones del personal laboral según el TREBEP?','["Libremente por el órgano contratante", "Por decreto del Consejo de Gobierno cada año", "Según las mismas tablas retributivas que los funcionarios del grupo equivalente, fijadas cada año por decreto del Gobierno", "Según la legislación laboral, el convenio colectivo y el contrato, respetando los límites de la ley de presupuestos"]'::jsonb,3,'Art. 27 TREBEP','Se determinan de acuerdo con la legislación laboral, el convenio aplicable y el contrato, respetando el art. 21 del TREBEP.',null),
('adm-cm:30-14233d5cfc','adm-cm',30,'Según el Estatuto de los Trabajadores, ¿a quién se aplica la ley?','["A los trabajadores autónomos económicamente dependientes", "A quienes presten voluntariamente servicios retribuidos por cuenta ajena dentro del ámbito de organización y dirección de otra persona", "A cualquier persona que realice un trabajo, sea o no retribuido", "A todas las personas que presten servicios a una Administración pública, ya sean funcionarios, personal eventual o personal laboral"]'::jsonb,1,'Art. 1.1 ET','El ET se aplica a quienes voluntariamente presten servicios retribuidos por cuenta ajena y dentro del ámbito de organización y dirección del empleador.',null),
('adm-cm:30-2fdd5b4544','adm-cm',30,'¿Cuál de estas relaciones excluye el Estatuto de los Trabajadores de su ámbito?','["Los trabajos realizados a título de amistad, benevolencia o buena vecindad", "La del personal laboral de las Administraciones públicas", "La de los trabajadores a tiempo parcial", "La de los trabajadores contratados por empresas de trabajo temporal y cedidos a empresas usuarias"]'::jsonb,0,'Art. 1.3 ET','Se excluyen, entre otros, los trabajos a título de amistad, benevolencia o buena vecindad; el personal laboral público sí se rige por el ET.',null),
('adm-cm:30-3742d393dd','adm-cm',30,'¿A partir de qué edad se permite la admisión al trabajo según el Estatuto de los Trabajadores?','["Quince años", "Dieciocho años", "Dieciséis años", "Catorce años"]'::jsonb,2,'Art. 6.1 ET','Se prohíbe la admisión al trabajo a los menores de dieciséis años.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:30-5117ffd71c','adm-cm',30,'¿Pueden realizar horas extraordinarias los menores de dieciocho años?','["Sí, con autorización de sus padres", "Sí, hasta un máximo de 40 al año", "Sí, si lo prevé el convenio colectivo", "No"]'::jsonb,3,'Art. 6.3 ET','Se prohíbe realizar horas extraordinarias a los menores de dieciocho años.',null),
('adm-cm:30-c25c9b230d','adm-cm',30,'¿Cómo puede celebrarse el contrato de trabajo según el Estatuto de los Trabajadores?','["De palabra solo si dura menos de una semana", "Por escrito o de palabra", "Por escrito y ante la oficina de empleo", "Solo por escrito"]'::jsonb,1,'Art. 8.1 ET','El contrato de trabajo se podrá celebrar por escrito o de palabra.',null),
('adm-cm:30-056b6c8131','adm-cm',30,'Si no se formaliza por escrito un contrato que debía serlo, ¿cómo se presume celebrado?','["Por tiempo indefinido y a jornada completa, salvo prueba en contrario", "Por obra o servicio determinado y a tiempo parcial, salvo prueba en contrario", "Nulo de pleno derecho", "Por seis meses y a jornada completa"]'::jsonb,0,'Art. 8.2 ET','Se presumirá celebrado por tiempo indefinido y a jornada completa, salvo prueba en contrario.',null),
('adm-cm:30-a2171c0cd1','adm-cm',30,'¿En qué plazo debe comunicar el empresario a la oficina pública de empleo el contenido de los contratos?','["Quince días", "Cinco días", "Diez días", "Un mes"]'::jsonb,2,'Art. 8.3 ET','El empresario debe comunicarlo en los diez días siguientes a su concertación.',null),
('adm-cm:30-b274e7fbf3','adm-cm',30,'¿Cuál es la duración mínima y máxima del contrato de formación en alternancia?','["Mínimo tres meses y máximo dos años", "Mínimo seis meses y máximo un año", "Mínimo seis meses y máximo dos años", "Mínimo un mes y máximo tres años"]'::jsonb,0,'Art. 11.2 ET','La duración será la del plan formativo, con un mínimo de tres meses y un máximo de dos años.',null),
('adm-cm:30-0a858dd092','adm-cm',30,'En el contrato de formación en alternancia, ¿qué porcentaje máximo de tiempo de trabajo efectivo se permite el primer año?','["El 85 % de la jornada máxima", "El 65 % de la jornada máxima", "El 50 % de la jornada máxima", "El 75 % de la jornada máxima"]'::jsonb,1,'Art. 11.2 ET','No puede superar el 65 % el primer año ni el 85 % el segundo, de la jornada máxima de convenio o legal.',null),
('adm-cm:30-311ca7ed85','adm-cm',30,'¿Puede establecerse periodo de prueba en el contrato de formación en alternancia?','["Sí, el que fije el convenio colectivo", "Sí, de un mes como máximo", "No", "Sí, de quince días"]'::jsonb,2,'Art. 11.2 ET','No podrá establecerse periodo de prueba en el contrato de formación en alternancia.',null),
('adm-cm:30-11cd269e14','adm-cm',30,'¿Dentro de qué plazo tras terminar los estudios debe concertarse el contrato para la obtención de práctica profesional?','["Cinco años, o siete si es una persona con discapacidad", "Cuatro años desde la obtención del título", "Dos años, sin excepciones", "Tres años, o cinco si se trata de una persona con discapacidad"]'::jsonb,3,'Art. 11.3 ET','Debe concertarse dentro de los tres años, o cinco si se trata de una persona con discapacidad, siguientes a la terminación de los estudios.',null),
('adm-cm:30-d658f430bb','adm-cm',30,'¿Qué duración tiene el contrato para la obtención de práctica profesional?','["No inferior a un año ni superior a tres", "No inferior a seis meses ni superior a un año", "No inferior a un mes ni superior a seis meses", "No inferior a tres meses ni superior a dos años"]'::jsonb,1,'Art. 11.3 ET','La duración no podrá ser inferior a seis meses ni exceder de un año.',null),
('adm-cm:30-2b9639e21e','adm-cm',30,'Salvo justificación en convenio, ¿cuál es la duración máxima del periodo de prueba para técnicos titulados?','["Dos meses", "Tres meses", "Un año", "Seis meses"]'::jsonb,3,'Art. 14.1 ET','No podrá exceder de seis meses para técnicos titulados ni de dos meses para las demás personas trabajadoras.',null),
('adm-cm:30-e96860a4d7','adm-cm',30,'En empresas de menos de veinticinco trabajadores, ¿cuál es el periodo de prueba máximo para quienes no son técnicos titulados?','["Seis meses", "Dos meses", "Tres meses", "Un mes"]'::jsonb,2,'Art. 14.1 ET','En empresas de menos de veinticinco personas trabajadoras no podrá exceder de tres meses para quienes no sean técnicos titulados.',null),
('adm-cm:30-2c48381c09','adm-cm',30,'En contratos de duración determinada de seis meses o más, ¿cuál es el periodo de prueba máximo?','["Un mes", "Tres meses", "Quince días", "Dos meses"]'::jsonb,0,'Art. 14.1 ET','En contratos de duración determinada por periodo igual o superior a seis meses, el periodo de prueba no podrá exceder de un mes.',null),
('adm-cm:30-693863f22d','adm-cm',30,'¿Es válido un periodo de prueba si el trabajador ya desempeñó las mismas funciones en la empresa?','["No, el pacto es nulo", "Sí, si lo prevé el convenio colectivo", "Sí, si se reduce a la mitad", "Sí, si ha pasado más de un año"]'::jsonb,0,'Art. 14.1 ET','Es nulo el pacto de periodo de prueba cuando la persona ya haya desempeñado las mismas funciones en la empresa bajo cualquier modalidad.',null),
('adm-cm:30-dbfe4ea9da','adm-cm',30,'¿Cómo se presume concertado el contrato de trabajo según el art. 15 del Estatuto?','["A tiempo parcial", "Por obra o servicio determinado", "Por tiempo determinado de un año", "Por tiempo indefinido"]'::jsonb,3,'Art. 15.1 ET','El contrato de trabajo se presume concertado por tiempo indefinido.',null),
('adm-cm:30-047baae2fb','adm-cm',30,'¿Por qué causas puede celebrarse un contrato de duración determinada según el Estatuto?','["Por circunstancias de la producción, obra o servicio y sustitución", "Por obra o servicio determinado o por lanzamiento de nueva actividad", "Por circunstancias de la producción o por sustitución de persona trabajadora", "Por cualquier causa que se especifique en el contrato"]'::jsonb,2,'Art. 15.1 ET','Solo puede celebrarse por circunstancias de la producción o por sustitución de persona trabajadora.',null),
('adm-cm:30-79ed606553','adm-cm',30,'¿Cuál es la duración máxima legal del contrato por circunstancias de la producción imprevisibles?','["Tres meses, sin posibilidad de ampliación", "Seis meses, ampliable a un año por convenio sectorial", "Doce meses en un periodo de dieciocho", "Un año, ampliable a dieciocho meses por convenio"]'::jsonb,1,'Art. 15.2 ET','No podrá ser superior a seis meses; por convenio sectorial podrá ampliarse hasta un año.',null),
('adm-cm:30-40888c6b04','adm-cm',30,'¿Cuántos días al año pueden usar las empresas, con carácter general, el contrato por circunstancias de la producción previsibles y de duración reducida?','["Treinta días por trimestre", "Sesenta días en el año natural", "Noventa días en el año natural", "Ciento veinte días en el año natural"]'::jsonb,2,'Art. 15.2 ET','Solo podrán utilizarlo un máximo de noventa días en el año natural (120 en el sector agrario y agroalimentario), sin uso continuado.',null),
('adm-cm:30-16696e90ff','adm-cm',30,'Cuando el contrato de sustitución cubre un puesto durante un proceso de selección, ¿cuál es su duración máxima legal?','["Seis meses", "Tres meses", "Hasta que termine el proceso, sin límite", "Un año"]'::jsonb,1,'Art. 15.3 ET','No podrá ser superior a tres meses, o el plazo inferior del convenio colectivo.',null),
('adm-cm:30-64ebae726c','adm-cm',30,'¿Cuándo adquiere la condición de fija una persona encadenando contratos por circunstancias de la producción?','["Si en doce meses ha estado contratada más de seis", "Si en treinta meses ha estado contratada más de veinticuatro mediante tres o más contratos temporales", "Si encadena tres contratos, sea cual sea su duración total", "Si en veinticuatro meses ha estado contratada más de dieciocho meses mediante dos o más contratos"]'::jsonb,3,'Art. 15.5 ET','Adquiere la condición de fija quien en veinticuatro meses haya estado contratado más de dieciocho mediante dos o más contratos por circunstancias de la producción.',null),
('adm-cm:30-bc4532c81c','adm-cm',30,'Al finalizar un contrato temporal por circunstancias de la producción, ¿qué indemnización corresponde?','["La parte proporcional de doce días de salario por año de servicio", "Ninguna, al tratarse de un contrato temporal", "Veinte días de salario por año de servicio", "Ocho días de salario por año de servicio"]'::jsonb,0,'Art. 49.1 ET','Excepto en los formativos y de sustitución, corresponde la parte proporcional de doce días de salario por año de servicio.',null),
('adm-cm:30-a22a06512a','adm-cm',30,'Si un contrato de duración determinada es superior a un año, ¿con qué antelación debe notificarse su terminación?','["Un mes", "Quince días", "Siete días", "Diez días"]'::jsonb,1,'Art. 49.1 ET','La parte que formule la denuncia debe notificar la terminación con una antelación mínima de quince días.',null),
('adm-cm:30-4198b09ea6','adm-cm',30,'En caso de muerte, jubilación o incapacidad del empresario persona física, ¿a qué tiene derecho el trabajador?','["Al abono de una cantidad equivalente a un mes de salario", "A la readmisión por los herederos en todo caso", "A veinte días de salario por año de servicio", "A treinta y tres días de salario por año de servicio"]'::jsonb,0,'Art. 49.1 ET','En los casos de muerte, jubilación o incapacidad del empresario, el trabajador tiene derecho a una cantidad equivalente a un mes de salario.',null),
('adm-cm:30-61c754b8eb','adm-cm',30,'¿Qué indemnización corresponde por la extinción del contrato por causas objetivas?','["Cuarenta y cinco días por año, con un máximo de cuarenta y dos mensualidades", "Treinta y tres días por año, con un máximo de veinticuatro mensualidades", "Veinte días por año de servicio, con un máximo de doce mensualidades", "Doce días por año, sin máximo"]'::jsonb,2,'Art. 53.1 ET','Se debe poner a disposición la indemnización de veinte días por año de servicio, con un máximo de doce mensualidades.',null),
('adm-cm:30-244ce2edd1','adm-cm',30,'Declarado improcedente un despido, ¿en qué plazo puede optar el empresario entre readmisión o indemnización?','["Quince días desde la firmeza de la sentencia", "Tres días desde el acto de conciliación", "Diez días desde la notificación de la sentencia", "Cinco días desde la notificación de la sentencia"]'::jsonb,3,'Art. 56.1 ET','El empresario puede optar en el plazo de cinco días desde la notificación de la sentencia.',null),
('adm-cm:30-ab6f0ba076','adm-cm',30,'¿Qué indemnización corresponde por despido improcedente si el empresario no readmite?','["Treinta días de salario por año, hasta dieciocho mensualidades", "Cuarenta y cinco días de salario por año, hasta cuarenta y dos mensualidades", "Treinta y tres días de salario por año, hasta veinticuatro mensualidades", "Veinte días de salario por año, hasta doce mensualidades"]'::jsonb,2,'Art. 56.1 ET','La indemnización equivale a treinta y tres días de salario por año de servicio, hasta un máximo de veinticuatro mensualidades.',null),
('adm-cm:31-491461492d','adm-cm',31,'El sistema de la Seguridad Social se fundamenta en los principios de:','["Universalidad, unidad, solidaridad e igualdad", "Contributividad, capitalización y rentabilidad", "Descentralización y autonomía", "Voluntariedad y suficiencia"]'::jsonb,0,'Art. 2.1 TRLGSS','Se fundamenta en los principios de universalidad, unidad, solidaridad e igualdad.','abr. 2026 · 1.er ejercicio'),
('adm-cm:31-367bb8a014','adm-cm',31,'El sistema de la Seguridad Social se integra por:','["Un único régimen para todos los trabajadores, sean o no autónomos", "El Régimen General y los Regímenes Especiales", "El Régimen General, los regímenes autonómicos y las mutualidades privadas de previsión social", "El Régimen de Autónomos y el de funcionarios"]'::jsonb,1,'Art. 9.1 TRLGSS','Lo integran el Régimen General y los Regímenes Especiales.','abr. 2026 · 1.er ejercicio'),
('adm-cm:31-1144cb14fb','adm-cm',31,'La afiliación a la Seguridad Social es:','["Voluntaria, y se renueva al comienzo de cada actividad o empleo", "Obligatoria solo para los trabajadores por cuenta ajena, y distinta para cada uno de sus empleos o actividades", "Obligatoria para las personas del art. 7.1 y única para toda su vida y para todo el sistema", "Obligatoria, pero se renueva para cada régimen en que se trabaje"]'::jsonb,2,'Art. 15 TRLGSS','Es obligatoria para las personas del art. 7.1 y única para toda su vida y para todo el sistema.',null),
('adm-cm:31-713a5b9624','adm-cm',31,'La obligación de cotizar nace:','["Al año del inicio de la actividad", "Con la firma del contrato de trabajo, aunque la actividad comience más tarde", "Al cobrar la primera nómina", "Desde el momento de iniciación de la actividad correspondiente"]'::jsonb,3,'Art. 18.2 TRLGSS','Nace desde el momento de iniciación de la actividad correspondiente.',null),
('adm-cm:31-99e5437f19','adm-cm',31,'¿En qué plazo prescribe el derecho de la Administración a determinar y exigir las deudas por cuotas?','["Cuatro años", "Cinco años", "Tres años", "Diez años"]'::jsonb,0,'Art. 24.1 TRLGSS','Prescriben a los cuatro años.',null),
('adm-cm:31-26bce6dd02','adm-cm',31,'En el Régimen General de la Seguridad Social están comprendidos:','["Los trabajadores autónomos y asimilados", "Los trabajadores por cuenta ajena y asimilados", "Los trabajadores por cuenta ajena, salvo los que presten servicios en Administraciones públicas o en empresas públicas", "Los funcionarios de carrera de todas las Administraciones"]'::jsonb,1,'Art. 136.1 TRLGSS','Están comprendidos los trabajadores por cuenta ajena y los asimilados, salvo que deban estar en un régimen especial.',null),
('adm-cm:31-d707bfec79','adm-cm',31,'Según el art. 137 TRLGSS, NO dan lugar a inclusión en el Régimen General:','["Los trabajos por cuenta ajena de carácter temporal", "Los funcionarios incluidos por ley", "Los trabajos ocasionales realizados por servicios amistosos, benévolos o de buena vecindad", "Los socios trabajadores de cooperativas asimilados por ley a trabajadores por cuenta ajena"]'::jsonb,2,'Art. 137 a) TRLGSS','Es una de las exclusiones del Régimen General.',null),
('adm-cm:31-145ecd86c2','adm-cm',31,'Si se ingresan las cuotas durante el primer mes natural siguiente al vencimiento del plazo reglamentario, habiendo presentado los documentos de cotización en plazo, el recargo es del:','["10 %", "20 %", "35 %", "5 %"]'::jsonb,0,'Art. 30.1 a) TRLGSS','Si se pagan a partir del segundo mes, el recargo es del 20 %.',null),
('adm-cm:31-7d4955a134','adm-cm',31,'Las bases y tipos de cotización a la Seguridad Social se fijan cada año en:','["Una orden de la Tesorería General de la Seguridad Social", "Los convenios colectivos de cada sector", "La Ley de Presupuestos Generales del Estado", "Un real decreto del Gobierno, previo acuerdo con los agentes sociales"]'::jsonb,2,'Art. 19.1 TRLGSS','La base mínima es, salvo disposición en contrario, el SMI incrementado en un sexto.','abr. 2026 · 1.er ejercicio'),
('adm-cm:31-d18c78405e','adm-cm',31,'Es un régimen especial de la Seguridad Social según el art. 10.2 TRLGSS:','["El de los trabajadores por cuenta propia o autónomos", "El de los empleados de comercio", "El de los trabajadores de banca y entidades financieras", "El de los trabajadores de la construcción"]'::jsonb,0,'Art. 10.2 a) TRLGSS','También el de trabajadores del mar, funcionarios públicos civiles y militares y estudiantes.',null),
('adm-cm:31-3acb5d3937','adm-cm',31,'El derecho a la devolución de ingresos indebidos en materia de Seguridad Social prescribe a los:','["Cinco años desde el día siguiente al ingreso", "Diez años desde el día siguiente al ingreso", "Un año desde el día siguiente al ingreso", "Cuatro años desde el día siguiente al ingreso"]'::jsonb,3,'Art. 26.3 TRLGSS','Coincide con el plazo de prescripción de las deudas por cuotas.',null),
('adm-cm:31-e788b8bc0f','adm-cm',31,'Están comprendidos en el sistema de la Seguridad Social, a efectos de las prestaciones contributivas, los trabajadores por cuenta propia o autónomos:','["Mayores de dieciocho años", "Mayores de dieciséis años", "Mayores de veintiún años", "De cualquier edad"]'::jsonb,0,'Art. 7.1 b) TRLGSS','El art. 7.1 enumera los incluidos en el campo de aplicación contributivo.',null),
('adm-cm:32-5c931b8b14','adm-cm',32,'La acción protectora de la Seguridad Social comprende, entre otras:','["Las becas universitarias, las ayudas a la vivienda para jóvenes y los préstamos personales sin interés a los afiliados y a sus familiares directos", "La asistencia sanitaria y las prestaciones por incapacidad temporal, nacimiento y cuidado de menor, incapacidad permanente y jubilación", "La asistencia sanitaria, las becas de estudio, las ayudas a la vivienda y los préstamos personales sin interés a los afiliados y a sus familiares", "Las prestaciones por jubilación, pero no la asistencia sanitaria"]'::jsonb,1,'Art. 42.1 TRLGSS','Incluye la asistencia sanitaria y prestaciones por incapacidad temporal, nacimiento y cuidado de menor, incapacidad permanente, jubilación, desempleo y muerte y supervivencia, entre otras.',null),
('adm-cm:32-625e8fb5d1','adm-cm',32,'¿Cuál de las siguientes NO figura entre las entidades gestoras del art. 66.1 del TRLGSS?','["El Instituto Nacional de la Seguridad Social", "El Instituto de Mayores y Servicios Sociales", "La Tesorería General de la Seguridad Social", "El Instituto Nacional de Gestión Sanitaria"]'::jsonb,2,'Arts. 66.1 y 74.1 TRLGSS','Las entidades gestoras son el INSS, el INGESA y el IMSERSO. La Tesorería General es un servicio común.','oct. 2026 · 1.er ejercicio'),
('adm-cm:32-9a49545059','adm-cm',32,'La Tesorería General de la Seguridad Social es:','["Una entidad gestora con personalidad jurídica propia", "Una mutua colaboradora con la Seguridad Social, sin ánimo de lucro", "Un organismo autónomo dependiente de cada Comunidad Autónoma, que gestiona sus recursos financieros propios", "Un servicio común con personalidad jurídica propia, en el que se unifican los recursos financieros"]'::jsonb,3,'Art. 74.1 TRLGSS','Es un servicio común con personalidad jurídica propia que aplica los principios de solidaridad financiera y caja única.',null),
('adm-cm:32-1fd85cbf42','adm-cm',32,'Las mutuas colaboradoras con la Seguridad Social son:','["Asociaciones privadas de empresarios, sin ánimo de lucro", "Asociaciones privadas de trabajadores, sin ánimo de lucro, autorizadas por el Ministerio competente en materia de Seguridad Social", "Empresas públicas de la Administración del Estado", "Compañías de seguros con ánimo de lucro"]'::jsonb,0,'Art. 80.1 TRLGSS','Son asociaciones privadas de empresarios, autorizadas por el Ministerio, que actúan sin ánimo de lucro.',null),
('adm-cm:32-a96fd0231b','adm-cm',32,'Se entiende por accidente de trabajo:','["Toda enfermedad del trabajador, aunque no tenga relación con el trabajo que realiza", "Solo la lesión sufrida en el centro de trabajo durante la jornada", "Toda lesión corporal sufrida durante la jornada, aunque sea por fuerza mayor extraña al trabajo y por imprudencia temeraria del trabajador", "Toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo por cuenta ajena"]'::jsonb,3,'Art. 156.1 TRLGSS','Es toda lesión corporal que el trabajador sufra con ocasión o por consecuencia del trabajo que ejecute por cuenta ajena.',null),
('adm-cm:32-f0e3bb44e5','adm-cm',32,'El accidente que sufre el trabajador al ir o volver del lugar de trabajo:','["Tiene la consideración de accidente de trabajo", "Es siempre accidente no laboral", "Solo es accidente de trabajo si ocurre en transporte público", "Es una enfermedad profesional"]'::jsonb,0,'Art. 156.2 a) TRLGSS','Tienen la consideración de accidente de trabajo los sufridos al ir o volver del lugar de trabajo (accidente in itinere).',null),
('adm-cm:32-b7be5eb933','adm-cm',32,'La enfermedad profesional es la contraída a consecuencia del trabajo por cuenta ajena:','["En cualquier actividad, siempre que lo acredite un informe médico", "En las actividades del cuadro aprobado reglamentariamente, provocada por los elementos o sustancias que en él se indiquen", "En las actividades que fije cada convenio colectivo, provocada por los elementos o sustancias que señale la mutua o la empresa en cada caso concreto", "En la industria química y minera, tras al menos diez años de trabajo"]'::jsonb,1,'Art. 157 TRLGSS','Es la contraída en las actividades del cuadro reglamentario y provocada por los elementos o sustancias que ese cuadro indica.',null),
('adm-cm:32-f894c89284','adm-cm',32,'La incapacidad temporal por enfermedad o accidente tiene una duración máxima de:','["180 días, prorrogables por otros 180", "Dos años, prorrogables por otros seis meses cuando se prevea el alta", "365 días, prorrogables por otros 180 cuando se prevea el alta médica por curación", "365 días, prorrogables por otros 365 cuando se prevea el alta médica por curación o mejoría"]'::jsonb,2,'Art. 169.1 a) TRLGSS','Trescientos sesenta y cinco días, prorrogables por otros ciento ochenta cuando se presuma que el trabajador será dado de alta por curación.',null),
('adm-cm:32-28d028f7cb','adm-cm',32,'¿Cuál de estas situaciones protege la prestación del art. 177 del TRLGSS?','["La jubilación anticipada por voluntad del interesado o por causa no imputable", "La situación legal de desempleo derivada de la extinción del contrato por cuidado de menores", "La incapacidad permanente total para la profesión habitual del trabajador", "El nacimiento, la adopción, la guarda con fines de adopción y el acogimiento"]'::jsonb,3,'Art. 177 TRLGSS','Protege el nacimiento, la adopción, la guarda con fines de adopción y el acogimiento.',null),
('adm-cm:32-c673766368','adm-cm',32,'La incapacidad permanente se clasifica en los grados de:','["Parcial, total, absoluta y gran incapacidad", "Leve, moderada, grave y gran dependencia, según el baremo", "Parcial, total y absoluta, sin más grados", "Temporal, parcial, total, absoluta y gran incapacidad"]'::jsonb,0,'Art. 194.1 TRLGSS','Incapacidad permanente parcial, total, absoluta y gran incapacidad.',null),
('adm-cm:32-705d3abe0d','adm-cm',32,'Para causar derecho a la pensión de jubilación se exige un periodo mínimo de cotización de:','["Diez años, de los cuales al menos dos dentro de los diez inmediatamente anteriores", "Quince años, de los cuales al menos dos dentro de los quince inmediatamente anteriores", "Quince años, de los cuales al menos cinco dentro de los quince inmediatamente anteriores al hecho causante", "Veinte años, de los cuales al menos cinco dentro de los quince inmediatamente anteriores"]'::jsonb,1,'Art. 205.1 b) TRLGSS','Quince años, de los cuales al menos dos deben estar dentro de los quince años inmediatamente anteriores.',null),
('adm-cm:32-fabbc6fc63','adm-cm',32,'La pensión de viudedad de un causante en alta exige, con carácter general, un periodo de cotización de:','["Quinientos días dentro de un periodo ininterrumpido de cinco años inmediatamente anteriores al hecho causante", "Ninguno, si el causante estaba en alta", "Quinientos días dentro de un periodo ininterrumpido de diez años inmediatamente anteriores al hecho causante", "Quince años, de los cuales al menos dos en los últimos quince"]'::jsonb,0,'Art. 219.1 TRLGSS','Si el causante no estaba en alta ni en situación asimilada, se exigen quince años.',null),
('adm-cm:32-49196e93ad','adm-cm',32,'La gestión de las pensiones no contributivas de invalidez y jubilación corresponde a:','["El INGESA", "La TGSS", "El INSS", "El IMSERSO"]'::jsonb,3,'Art. 66.1 c) TRLGSS','El INSS gestiona las prestaciones económicas del sistema, salvo las del IMSERSO.',null),
('adm-cm:32-89011d523a','adm-cm',32,'En la jubilación parcial, la reducción de la jornada debe estar comprendida entre:','["Un mínimo del 10 % y un máximo del 50 %", "Un mínimo del 30 % y un máximo del 60 %", "Un mínimo del 25 % y un máximo del 75 %", "Un mínimo del 50 % y un máximo del 90 %"]'::jsonb,2,'Art. 215.1 TRLGSS','Según el art. 215 en su redacción consolidada.',null),
('adm-cm:32-4ba984bb0d','adm-cm',32,'Con carácter general, la edad ordinaria de jubilación es de 67 años, o de 65 años cuando se acrediten:','["40 años de cotización", "38 años y 6 meses de cotización", "35 años de cotización", "36 años y 6 meses de cotización"]'::jsonb,1,'Art. 205.1 a) TRLGSS','Según el texto consolidado del TRLGSS en el BOE.',null),
('adm-cm:32-ad77f59ea3','adm-cm',32,'La prestación por riesgo durante el embarazo consiste en un subsidio equivalente al:','["50 % de la base reguladora de contingencias comunes", "100 % de la base reguladora de la incapacidad temporal derivada de contingencias profesionales", "75 % de la base reguladora de la incapacidad temporal derivada de contingencias comunes", "60 % de la base"]'::jsonb,1,'Art. 187.3 TRLGSS','Se trata como contingencia profesional.',null),
('adm-cm:32-45f8f383bf','adm-cm',32,'La incapacidad temporal se puede prorrogar, tras los 365 días, por otros:','["30 días", "365 días", "180 días, cuando se presuma que durante ellos el trabajador puede ser dado de alta por curación", "90 días, cuando se presuma que durante ellos el trabajador puede ser dado de alta por curación"]'::jsonb,2,'Art. 169.1 a) TRLGSS','La duración máxima es de 365 días prorrogables por otros 180.',null),
('adm-cm:32-3ff44a9c77','adm-cm',32,'Las prestaciones por muerte y supervivencia incluyen:','["Solo la pensión de viudedad, la pensión de orfandad y, en su caso, la pensión de jubilación que hubiera correspondido al fallecido, que se transmite a sus herederos", "Auxilio por defunción, pensión de viudedad, prestación temporal de viudedad, pensión de orfandad y pensión en favor de familiares", "La pensión de jubilación del fallecido", "Solo el auxilio por defunción"]'::jsonb,1,'Art. 216.1 TRLGSS','Se enumeran en el art. 216.1.',null),
('adm-cm:32-81953098fc','adm-cm',32,'Las prestaciones de la Seguridad Social, con carácter general:','["Pueden compensarse con cualquier deuda del beneficiario con la Administración y retenerse por el empresario hasta su liquidación definitiva", "Pueden cederse libremente a terceros y compensarse con las deudas que el beneficiario tenga con la Seguridad Social", "No pueden ser objeto de retención, cesión total o parcial, compensación o descuento, salvo excepciones", "Pueden retenerse por el empresario"]'::jsonb,2,'Art. 44.1 TRLGSS','Excepciones: obligaciones alimenticias a favor del cónyuge e hijos y obligaciones contraídas con la Seguridad Social.','nov. 2024 · 1.er ejercicio'),
('adm-cm:32-def460297e','adm-cm',32,'La jubilación anticipada voluntaria exige tener una edad que sea, como máximo, dos años inferior a la ordinaria y acreditar un periodo mínimo de cotización efectiva de:','["33 años", "38 años y 6 meses", "15 años", "35 años"]'::jsonb,3,'Art. 208.1 TRLGSS','El importe de la pensión debe superar la mínima que correspondería a los 65 años.',null),
('adm-cm:32-f132c27df2','adm-cm',32,'Los bienes y derechos que integran el patrimonio de la Seguridad Social son:','["Embargables por cualquier acreedor", "Inembargables", "Embargables solo por Hacienda", "Transmisibles libremente"]'::jsonb,1,'Art. 108 TRLGSS','El patrimonio de la Seguridad Social es inembargable.',null),
('adm-cm:32-e069774b52','adm-cm',32,'La incapacidad permanente parcial para la profesión habitual se abona mediante:','["Un subsidio temporal", "Una pensión vitalicia del 100 %", "Una pensión vitalicia del 55 %", "Una cantidad a tanto alzado"]'::jsonb,3,'Art. 196.1 TRLGSS','La total y la absoluta dan lugar a pensión vitalicia.',null),
('adm-cm:32-3a15fba24d','adm-cm',32,'El sistema financiero de todos los regímenes que integran el sistema de la Seguridad Social es el de:','["Reparto, para todas las contingencias y situaciones amparadas", "Mixto obligatorio, con una parte de capitalización", "Capitalización individual para la jubilación y reparto para el resto de contingencias", "Capitalización colectiva"]'::jsonb,0,'Art. 110.1 TRLGSS','El sistema funciona por reparto.',null),
('adm-cm:32-45e771caf9','adm-cm',32,'El derecho al reconocimiento de la pensión de jubilación:','["Es imprescriptible", "Prescribe a los cuatro años", "Prescribe a los cinco años", "Caduca al año"]'::jsonb,0,'Art. 212 TRLGSS','Los efectos en alta se retrotraen hasta tres meses antes de la solicitud.',null),
('adm-cm:32-68962fea3a','adm-cm',32,'Se considera recaída en un mismo proceso de incapacidad temporal cuando se produzca una nueva baja médica por la misma o similar patología dentro de los:','["90 días naturales siguientes a la fecha de efectos del alta médica anterior", "180 días naturales siguientes a la fecha de efectos del alta médica anterior", "365 días siguientes", "30 días siguientes"]'::jsonb,1,'Art. 169.2 TRLGSS','Se computan juntos ambos periodos.',null),
('adm-cm:32-5d133a4442','adm-cm',32,'La obligación de reintegrar el importe de las prestaciones indebidamente percibidas prescribe a los:','["Diez años", "Cuatro años", "Cinco años", "Un año"]'::jsonb,1,'Art. 55.3 TRLGSS','Desde la fecha de su cobro o desde que fue posible ejercitar la acción.',null),
('adm-cm:32-3c757f77b4','adm-cm',32,'La jubilación anticipada por causa no imputable al trabajador permite anticipar la jubilación, como máximo:','["Seis años antes de la edad ordinaria, con 35 años de cotización", "Cuatro años antes de la edad ordinaria, con 33 años de cotización", "Diez años antes", "Dos años antes de la edad ordinaria, con 30 años de cotización"]'::jsonb,1,'Art. 207.1 TRLGSS','Además se exige inscripción como demandante de empleo durante seis meses.',null),
('adm-cm:32-875d5ba430','adm-cm',32,'En la gran incapacidad, el pensionista tiene derecho a una pensión vitalicia incrementada con:','["Un complemento destinado a que pueda remunerar a la persona que le atienda", "Un complemento por mínimos, siempre que carezca de otras rentas", "Una indemnización a tanto alzado por una sola vez, equivalente a veinticuatro mensualidades de la base reguladora", "Una vivienda adaptada a cargo de la entidad gestora y una indemnización a tanto alzado"]'::jsonb,0,'Art. 196.4 TRLGSS','El complemento es el 45 % de la base mínima de cotización más el 30 % de la última base, con un mínimo del 45 % de la pensión.',null),
('adm-cm:32-ed62464e1e','adm-cm',32,'En la incapacidad temporal por accidente de trabajo o enfermedad profesional, el subsidio se abona:','["Desde el decimosexto día de baja, a cargo de la mutua", "Desde el primer día del mes siguiente", "Desde el cuarto día de baja, a cargo del empresario hasta el decimoquinto", "Desde el día siguiente al de la baja en el trabajo"]'::jsonb,3,'Art. 173.1 TRLGSS','El salario del día de la baja corre a cargo del empresario.',null),
('adm-cm:32-0053d4ba23','adm-cm',32,'Se presume, salvo prueba en contrario, que son constitutivas de accidente de trabajo:','["Todas las enfermedades comunes padecidas durante la vigencia del contrato", "Las lesiones sufridas durante las vacaciones anuales retribuidas", "Las lesiones sufridas en el domicilio un domingo", "Las lesiones que sufra el trabajador durante el tiempo y en el lugar del trabajo"]'::jsonb,3,'Art. 156.3 TRLGSS','Presunción iuris tantum de accidente de trabajo.',null),
('adm-cm:32-8eeceb4ccb','adm-cm',32,'La prestación por cuidado de menores afectados por cáncer u otra enfermedad grave exige una reducción de jornada de, al menos:','["Un 50 % de su duración", "Un 25 % de su duración", "Un 10 % de su duración", "Un 33 % de su duración"]'::jsonb,0,'Art. 190.1 TRLGSS','Puede mantenerse hasta los 23 años del hijo (26 con discapacidad ≥ 65 % acreditada antes).',null),
('adm-cm:32-cce521cdec','adm-cm',32,'Las lesiones permanentes no incapacitantes causadas por accidente de trabajo o enfermedad profesional se indemnizan:','["Con un subsidio mensual mientras dure la lesión", "Con una pensión vitalicia del 55 % de la base reguladora, incompatible con la continuación en la empresa y con cualquier otra prestación de la Seguridad Social", "Por una sola vez, con las cantidades alzadas fijadas en el baremo, sin perjuicio del derecho a continuar en la empresa", "No se indemnizan"]'::jsonb,2,'Art. 201 TRLGSS','Son incompatibles con las prestaciones de incapacidad permanente salvo lesiones independientes.',null),
('adm-cm:32-699c1d83e1','adm-cm',32,'Para tener derecho a la incapacidad temporal derivada de enfermedad común se exige un periodo de cotización de:','["180 días dentro de los cinco años inmediatamente anteriores al hecho causante", "Un año dentro de los diez años inmediatamente anteriores al hecho causante", "365 días en el último año", "No se exige cotización previa"]'::jsonb,0,'Art. 172 a) TRLGSS','En accidente (sea o no de trabajo) y enfermedad profesional no se exige periodo previo.',null),
('adm-cm:32-03102b4039','adm-cm',32,'El derecho al subsidio por incapacidad temporal se extingue, entre otras causas, por el transcurso de:','["365 días naturales desde la baja médica", "545 días naturales desde la baja médica", "730 días naturales desde la primera baja médica", "180 días naturales desde la baja médica"]'::jsonb,1,'Art. 174.1 TRLGSS','Es el plazo máximo total del proceso.',null),
('adm-cm:32-6d73c8af26','adm-cm',32,'La prestación por riesgo durante la lactancia natural se extingue cuando el hijo cumple:','["Dieciocho meses", "Doce meses", "Nueve meses", "Seis meses"]'::jsonb,2,'Art. 189 TRLGSS','Salvo que la beneficiaria se haya reincorporado antes a su puesto.',null),
('adm-cm:32-31803110ab','adm-cm',32,'Las pensiones contributivas se revalorizan al comienzo de cada año en función de:','["El valor medio de las tasas de variación interanual del IPC de los doce meses previos a diciembre del año anterior", "El IPREM", "El SMI", "El crecimiento del PIB y la evolución de la masa salarial de los afiliados en los doce meses previos"]'::jsonb,0,'Art. 58.2 TRLGSS','Si el valor es negativo, el importe de las pensiones no varía.',null),
('adm-cm:32-b500b97c9c','adm-cm',32,'La administración y gestión de servicios sanitarios corresponde, como entidad gestora, a:','["Las mutuas colaboradoras con la Seguridad Social", "La TGSS", "El Instituto Nacional de Gestión Sanitaria (INGESA)", "El IMSERSO"]'::jsonb,2,'Art. 66.1 b) TRLGSS','El INGESA es la entidad gestora sanitaria.',null),
('adm-cm:32-235c3fe573','adm-cm',32,'La pensión vitalicia por incapacidad permanente total puede sustituirse excepcionalmente por una indemnización a tanto alzado cuando el beneficiario sea menor de:','["Cuarenta y cinco años", "Cincuenta años", "Sesenta y cinco años", "Sesenta años"]'::jsonb,3,'Art. 196.2 TRLGSS','Es una sustitución excepcional.',null),
('adm-cm:32-e51356371a','adm-cm',32,'Para tener derecho a la prestación por nacimiento y cuidado de menor, a las personas trabajadoras menores de 21 años:','["No se les exige periodo mínimo de cotización", "Se les exigen 90 días cotizados dentro de los siete años inmediatamente anteriores al inicio del descanso", "Se les exige un año cotizado a lo largo de su vida laboral", "Se les exigen 180 días cotizados"]'::jsonb,0,'Art. 178.1 a) TRLGSS','Entre 21 y 26 años no cumplidos se exigen 90 días en los siete años anteriores (o 180 en la vida laboral).',null),
('adm-cm:32-c6744d98f0','adm-cm',32,'La prestación temporal de viudedad tiene una duración de:','["Seis meses", "Cinco años", "Un año", "Dos años"]'::jsonb,3,'Art. 222 TRLGSS','Se concede cuando no se reúnen los requisitos de la pensión de viudedad por el periodo de matrimonio.',null),
('adm-cm:32-a61f2e16e3','adm-cm',32,'El derecho al percibo de las prestaciones a tanto alzado y por una sola vez caduca:','["A los cinco años, a contar desde el día siguiente a su notificación", "Nunca", "A los tres meses, a contar desde el día siguiente a su notificación", "Al año, a contar desde el día siguiente a su notificación"]'::jsonb,3,'Art. 54.1 TRLGSS','En las prestaciones periódicas, cada mensualidad caduca al año de su vencimiento.',null),
('adm-cm:32-05302f7850','adm-cm',32,'El derecho al reconocimiento de las prestaciones de la Seguridad Social prescribe, con carácter general, a los:','["Cuatro años, contados desde el día siguiente al hecho causante", "Cinco años, contados desde el día siguiente al hecho causante", "Diez años", "Un año, contado desde el día siguiente al hecho causante"]'::jsonb,1,'Art. 53.1 TRLGSS','Sin perjuicio de las excepciones legales.',null),
('adm-cm:32-582980e977','adm-cm',32,'En caso de enfermedad común o accidente no laboral, el subsidio de incapacidad temporal se abona:','["Desde el primer día de baja", "Desde el día siguiente a la baja en el trabajo", "A partir del decimosexto día de baja, a cargo de la entidad gestora", "A partir del cuarto día de baja en el trabajo"]'::jsonb,3,'Art. 173.1 TRLGSS','Del cuarto al decimoquinto día el abono corresponde al empresario.',null),
('adm-cm:32-7226172b58','adm-cm',32,'El subsidio por nacimiento y cuidado de menor consiste en un subsidio equivalente al:','["60 % de la base reguladora correspondiente", "75 % de la base reguladora durante las seis primeras semanas", "100 % de la base reguladora correspondiente", "75 % de la base reguladora de contingencias comunes"]'::jsonb,2,'Art. 179.1 TRLGSS','La base reguladora es la de incapacidad temporal por contingencias comunes.',null),
('adm-cm:32-c2b682bb36','adm-cm',32,'Tienen derecho a la pensión de orfandad, con carácter general, los hijos del causante:','["Menores de dieciocho años solamente", "Menores de dieciséis años o incapacitados para el trabajo", "Menores de veintiún años o incapacitados para el trabajo", "De cualquier edad"]'::jsonb,2,'Art. 224.1 TRLGSS','Puede extenderse hasta los 25 años si el huérfano no trabaja o sus ingresos son inferiores a determinados límites.',null),
('adm-cm:33-c65fc0f548','adm-cm',33,'Según la Ley General Tributaria, ¿cómo se clasifican los tributos?','["En tasas, contribuciones especiales e impuestos", "En impuestos directos, indirectos y precios públicos", "En impuestos, cotizaciones sociales y tasas", "En tasas, precios públicos e impuestos"]'::jsonb,0,'Art. 2.2 LGT','Los tributos, cualquiera que sea su denominación, se clasifican en tasas, contribuciones especiales e impuestos.',null),
('adm-cm:33-0567bcd603','adm-cm',33,'¿Qué son los impuestos según la Ley General Tributaria?','["Tributos por el beneficio obtenido con obras públicas", "Prestaciones voluntarias por servicios que también presta el sector privado en régimen de concurrencia", "Tributos por la utilización privativa del dominio público", "Tributos exigidos sin contraprestación cuyo hecho imponible pone de manifiesto la capacidad económica"]'::jsonb,3,'Art. 2.2 c) LGT','Impuestos son los tributos exigidos sin contraprestación cuyo hecho imponible está constituido por negocios, actos o hechos que ponen de manifiesto la capacidad económica.',null),
('adm-cm:33-59a9398fa6','adm-cm',33,'¿Qué tributo tiene como hecho imponible el beneficio o aumento de valor de los bienes por obras o servicios públicos?','["La tasa", "La contribución especial", "El impuesto", "El precio público"]'::jsonb,1,'Art. 2.2 b) LGT','Las contribuciones especiales gravan el beneficio o aumento de valor de los bienes del obligado por obras públicas o servicios públicos.',null),
('adm-cm:33-5334ff2ab8','adm-cm',33,'¿Qué tributo grava la utilización privativa o el aprovechamiento especial del dominio público?','["El recargo", "El impuesto", "La tasa", "La contribución especial"]'::jsonb,2,'Art. 2.2 a) LGT','Las tasas gravan la utilización privativa o el aprovechamiento especial del dominio público y ciertos servicios o actividades en régimen de derecho público.',null),
('adm-cm:33-6983c4ecc2','adm-cm',33,'¿En qué principios se basa la ordenación del sistema tributario según la Ley General Tributaria?','["Capacidad económica, justicia, generalidad, igualdad, progresividad, equitativa distribución y no confiscatoriedad", "Eficacia, eficiencia, economía, limitación de costes indirectos y respeto de los derechos y garantías de los obligados", "Legalidad, seguridad jurídica, jerarquía e irretroactividad", "Proporcionalidad, simplicidad, neutralidad y suficiencia"]'::jsonb,0,'Art. 3.1 LGT','La ordenación se basa en la capacidad económica y en los principios de justicia, generalidad, igualdad, progresividad, equitativa distribución de la carga y no confiscatoriedad.',null),
('adm-cm:33-d2fce9db7f','adm-cm',33,'¿A quién corresponde la potestad originaria para establecer tributos?','["A las Cortes y a los parlamentos autonómicos indistintamente", "Exclusivamente al Estado, mediante ley", "Al Gobierno, mediante real decreto", "Al Estado y a las comunidades autónomas por igual"]'::jsonb,1,'Art. 4.1 LGT','La potestad originaria para establecer tributos corresponde exclusivamente al Estado, mediante ley.',null),
('adm-cm:33-8685f95ab8','adm-cm',33,'¿Qué carácter tienen en el ordenamiento tributario las disposiciones generales del derecho administrativo?','["Interpretativo únicamente", "Ninguno, no se aplican a los tributos", "Preferente sobre la Ley General Tributaria", "Supletorio"]'::jsonb,3,'Art. 7.2 LGT','Tienen carácter supletorio las disposiciones generales del derecho administrativo y los preceptos del derecho común.',null),
('adm-cm:33-3c6e98814a','adm-cm',33,'¿Cuál de estas materias está reservada a la ley según el art. 8 de la Ley General Tributaria?','["La organización de la Agencia Tributaria", "El calendario del contribuyente", "La aprobación de los modelos de autoliquidación", "El establecimiento y modificación de los plazos de prescripción y caducidad"]'::jsonb,3,'Art. 8 LGT','Se regulan por ley, entre otros, los plazos de prescripción y caducidad, el hecho imponible, el tipo, las exenciones y las infracciones y sanciones.',null),
('adm-cm:33-4b99ae1827','adm-cm',33,'Si no disponen otra cosa, ¿cuándo entran en vigor las normas tributarias?','["Al día siguiente de su publicación", "A los veinte días naturales de su completa publicación", "El 1 de enero del año siguiente", "A los veinte días hábiles de su publicación"]'::jsonb,1,'Art. 10.1 LGT','Entran en vigor a los veinte días naturales de su completa publicación en el boletín oficial, si en ellas no se dispone otra cosa.',null),
('adm-cm:33-ae11874531','adm-cm',33,'¿Qué normas tributarias tienen efecto retroactivo respecto de actos no firmes cuando son más favorables?','["Las que regulan infracciones, sanciones y recargos", "Las que regulan el hecho imponible y el tipo", "Todas las normas tributarias", "Las que regulan los plazos de prescripción"]'::jsonb,0,'Art. 10.2 LGT','Las normas sobre infracciones, sanciones y recargos tienen efecto retroactivo respecto de actos no firmes cuando resulten más favorables.',null),
('adm-cm:33-7abd7e6a3a','adm-cm',33,'¿Pueden los particulares alterar mediante convenios los elementos de la obligación tributaria?','["Sí, si los aprueba la Administración", "Solo en los tributos locales", "No producen efectos ante la Administración, sin perjuicio de sus consecuencias privadas", "Sí, si se formalizan en escritura pública y se comunican después a la Administración tributaria"]'::jsonb,2,'Art. 17.5 LGT','Los elementos de la obligación tributaria no pueden ser alterados por actos o convenios de los particulares, que no producirán efectos ante la Administración.',null),
('adm-cm:33-e8249480e1','adm-cm',33,'¿Cuál es el objeto de la obligación tributaria principal?','["La llevanza de libros registro", "El pago de la cuota tributaria", "La presentación de la declaración", "El pago de los intereses de demora"]'::jsonb,1,'Art. 19 LGT','La obligación tributaria principal tiene por objeto el pago de la cuota tributaria.',null),
('adm-cm:33-2bd94ca7d6','adm-cm',33,'¿Qué es el hecho imponible según la Ley General Tributaria?','["El acto de la Administración que liquida el tributo", "La cantidad sobre la que se aplica el tipo de gravamen para calcular la cuota íntegra del tributo", "El presupuesto fijado por la ley cuya realización origina la obligación tributaria principal", "El momento en que se exige el pago del tributo"]'::jsonb,2,'Art. 20.1 LGT','Es el presupuesto fijado por la ley para configurar cada tributo cuya realización origina el nacimiento de la obligación tributaria principal.',null),
('adm-cm:33-401610aaff','adm-cm',33,'¿Qué es el devengo?','["La fecha de notificación de la liquidación", "El momento en que la deuda no pagada en periodo voluntario pasa a periodo ejecutivo con recargo", "El plazo de pago en periodo voluntario", "El momento en que se entiende realizado el hecho imponible y nace la obligación tributaria principal"]'::jsonb,3,'Art. 21.1 LGT','El devengo es el momento en que se entiende realizado el hecho imponible y se produce el nacimiento de la obligación tributaria principal.',null),
('adm-cm:33-eca8a553d0','adm-cm',33,'¿Requiere la exigencia del interés de demora tributario la previa intimación de la Administración?','["No, ni la intimación ni un retraso culpable", "Sí, siempre debe intimarse antes", "Sí, salvo que el retraso sea culpable", "Solo si el retraso supera seis meses"]'::jsonb,0,'Art. 26.1 LGT','La exigencia del interés de demora no requiere la previa intimación de la Administración ni la concurrencia de un retraso culpable.',null),
('adm-cm:33-84568db17a','adm-cm',33,'Salvo que la Ley de Presupuestos disponga otro, ¿cuál es el interés de demora tributario?','["El interés legal incrementado en un 50 %", "El interés legal del dinero sin incremento", "El interés legal del dinero incrementado en un 25 %", "El tipo de interés del Banco Central Europeo"]'::jsonb,2,'Art. 26.6 LGT','Es el interés legal del dinero vigente incrementado en un 25 %, salvo que la Ley de Presupuestos establezca otro.',null),
('adm-cm:33-12b400fb47','adm-cm',33,'¿Qué recargo se aplica a una autoliquidación presentada sin requerimiento previo con tres meses completos de retraso?','["El 5 %", "El 10 %", "El 3 %", "El 4 %"]'::jsonb,3,'Art. 27.2 LGT','El recargo es del 1 % más otro 1 % por cada mes completo de retraso: con tres meses completos, el 4 %.',null),
('adm-cm:33-e9b5a96e48','adm-cm',33,'¿Qué recargo se aplica si la autoliquidación se presenta transcurridos doce meses desde el fin del plazo, sin requerimiento previo?','["El 15 %, excluyendo las sanciones", "El 20 %, con sanciones", "El 13 %, sin intereses", "El 25 %, con intereses de demora"]'::jsonb,0,'Art. 27.2 LGT','Transcurridos 12 meses el recargo es del 15 % y excluye las sanciones, con intereses desde el día siguiente a esos 12 meses.',null),
('adm-cm:33-ef5c57b96f','adm-cm',33,'¿En qué porcentaje se reduce el recargo por declaración extemporánea si se paga en plazo?','["En el 10 %", "En el 25 %", "En el 50 %", "En el 30 %"]'::jsonb,1,'Art. 27.5 LGT','El importe del recargo se reduce en el 25 % si se realiza el ingreso total en los plazos previstos.',null),
('adm-cm:33-fb322cdcb7','adm-cm',33,'¿Quién es contribuyente según la Ley General Tributaria?','["El sujeto pasivo que realiza el hecho imponible", "Quien soporta la repercusión del tributo", "Quien, por ley, cumple la obligación en lugar del que realiza el hecho imponible", "Quien responde de la deuda de otro"]'::jsonb,0,'Art. 36.2 LGT','Es contribuyente el sujeto pasivo que realiza el hecho imponible; el sustituto cumple en su lugar por imposición de la ley.',null),
('adm-cm:33-5e638d513f','adm-cm',33,'Cuando concurren varios obligados tributarios en un mismo presupuesto, ¿cómo quedan obligados?','["Subsidiariamente, por orden de participación", "Responde solo el primero que figure en la declaración", "Mancomunadamente, por partes iguales", "Solidariamente, salvo que la ley disponga otra cosa"]'::jsonb,3,'Art. 35.7 LGT','La concurrencia determina que queden solidariamente obligados, salvo que por ley se disponga expresamente otra cosa.',null),
('adm-cm:33-e5cc8e5d72','adm-cm',33,'¿Forman parte de la deuda tributaria las sanciones tributarias?','["Sí, como prestación accesoria", "No, aunque en su recaudación se aplican las normas de la deuda", "Solo las sanciones por infracciones graves", "Sí, junto con el interés de demora"]'::jsonb,1,'Art. 58.3 LGT','Las sanciones tributarias no forman parte de la deuda tributaria, pero en su recaudación se aplican las normas del capítulo V del título III.',null),
('adm-cm:33-2f46d75c0c','adm-cm',33,'¿Cuál de estos conceptos forma parte de la deuda tributaria además de la cuota?','["Las costas judiciales", "Las sanciones tributarias", "Los recargos del periodo ejecutivo", "Las multas de tráfico"]'::jsonb,2,'Art. 58.2 LGT','La deuda tributaria incluye, en su caso, el interés de demora, los recargos por declaración extemporánea, los del periodo ejecutivo y otros recargos legales.',null),
('adm-cm:33-870f881e80','adm-cm',33,'¿En qué plazo prescribe el derecho de la Administración a determinar la deuda tributaria mediante liquidación?','["Cuatro años", "Cinco años", "Seis años", "Tres años"]'::jsonb,0,'Art. 66 LGT','Prescriben a los cuatro años el derecho a liquidar, a exigir el pago, a solicitar devoluciones y a obtenerlas.',null),
('adm-cm:33-ca2f16c3a0','adm-cm',33,'¿Desde cuándo se computa la prescripción del derecho a liquidar?','["Desde la fecha en que el obligado tributario presentó efectivamente la declaración o la autoliquidación", "Desde el día siguiente al fin del plazo reglamentario para presentar la declaración o autoliquidación", "Desde el día del devengo en todos los casos", "Desde el 1 de enero del año siguiente al devengo"]'::jsonb,1,'Art. 67.1 LGT','Se computa desde el día siguiente a aquel en que finalice el plazo reglamentario para presentar la declaración o autoliquidación; en tributos periódicos por recibo, desde el devengo.',null),
('adm-cm:33-dff36243c4','adm-cm',33,'Producida la interrupción de la prescripción tributaria, ¿qué ocurre con el plazo?','["Se reanuda por el tiempo que quedaba", "Se amplía en seis meses", "Queda suspendido hasta que resuelva el tribunal", "Se inicia de nuevo el cómputo"]'::jsonb,3,'Art. 68.6 LGT','Producida la interrupción, se iniciará de nuevo el cómputo del plazo de prescripción, salvo las excepciones del apartado 7.',null),
('adm-cm:34-091b4742d8','adm-cm',34,'Según la Ley 5/2025, el sector público autonómico está formado por:','["La Administración de la Comunidad de Madrid y el sector público institucional", "La Administración de la Comunidad de Madrid, el sector público institucional y las entidades locales de su territorio", "La Administración de la Comunidad de Madrid, sin incluir el sector público institucional", "La Asamblea, el Gobierno y la Administración"]'::jsonb,0,'Art. 2.1 Ley 5/2025 CM','Lo forman la Administración de la Comunidad de Madrid y el sector público institucional.',null),
('adm-cm:34-ab39b84fe0','adm-cm',34,'A efectos de la Ley de Hacienda, la Cámara de Cuentas:','["Queda totalmente fuera de su ámbito de aplicación", "Forma parte del sector público autonómico, con las peculiaridades de su independencia funcional", "Forma parte del sector público institucional como organismo autónomo, sometido a la tutela de la Consejería competente en hacienda", "Es una entidad de Derecho público dependiente del Gobierno"]'::jsonb,1,'Art. 2.3 Ley 5/2025 CM','Forma parte del sector público autonómico a efectos de la ley, con las peculiaridades derivadas de su independencia funcional.',null),
('adm-cm:34-b06c8bcfe6','adm-cm',34,'Según la Ley 5/2025, los organismos autónomos se clasifican en:','["Estatales y autonómicos", "Públicos y privados", "Generales y de régimen especial", "Administrativos y mercantiles"]'::jsonb,3,'Art. 4.2 Ley 5/2025 CM','Los organismos autónomos son administrativos o mercantiles.',null),
('adm-cm:34-e4b0151018','adm-cm',34,'Las sociedades mercantiles de la Comunidad de Madrid, ¿pueden ejercer facultades que impliquen autoridad pública?','["No, salvo que una ley lo prevea excepcionalmente", "Sí, siempre", "Sí, si lo autoriza su consejo de administración", "Solo en materia tributaria"]'::jsonb,0,'Art. 7.2 Ley 5/2025 CM','No pueden ejercer facultades que impliquen autoridad pública, salvo excepción legal.',null),
('adm-cm:34-49ba8dd353','adm-cm',34,'La Hacienda Pública de la Comunidad de Madrid está formada por:','["Los bienes inmuebles y derechos reales de la Comunidad", "Los derechos y obligaciones económicos de la Administración, sus organismos autónomos y sus entes de Derecho público de régimen especial", "Los derechos y obligaciones económicos de la Administración, sus organismos autónomos, sus sociedades mercantiles, sus fundaciones y las universidades públicas", "Los tributos propios y cedidos, sin incluir las obligaciones"]'::jsonb,1,'Art. 11 Ley 5/2025 CM','La integran los derechos y obligaciones de contenido económico de la Administración, sus organismos autónomos y sus entes de Derecho público de régimen especial.',null),
('adm-cm:34-f5b28546a8','adm-cm',34,'¿Cuál de los siguientes NO figura entre los principios de la actividad económico-financiera del art. 13?','["Legalidad", "Solidaridad intrarregional", "Coordinación", "Rentabilidad"]'::jsonb,3,'Art. 13 Ley 5/2025 CM','Los principios son legalidad, eficacia, control, universalidad, solidaridad intrarregional y coordinación.',null),
('adm-cm:34-9e75f31dab','adm-cm',34,'La concesión de créditos extraordinarios y suplementos de crédito se regula:','["Por orden del Consejero de Hacienda", "Por ley de la Asamblea", "Por decreto del Presidente", "Por resolución de la Intervención General"]'::jsonb,1,'Art. 14 b) Ley 5/2025 CM','Está reservada a ley de la Asamblea, igual que los presupuestos generales.',null),
('adm-cm:34-3617ce831d','adm-cm',34,'¿Qué principio implica que la Tesorería Central integra y custodia los recursos financieros de la Administración y sus organismos autónomos?','["Principio de caja única", "Principio de especialidad", "Principio de anualidad", "Principio de no afectación"]'::jsonb,0,'Art. 19 Ley 5/2025 CM','Es el principio de caja única.',null),
('adm-cm:34-8f952b40d6','adm-cm',34,'El principio de no afectación significa que los recursos de la Hacienda Pública:','["Se destinan preferentemente a gastos de personal y, después, al resto de obligaciones", "Se destinan a satisfacer el conjunto de sus obligaciones, salvo que una ley los afecte a fines concretos", "Se destinan a satisfacer el conjunto de sus obligaciones, sin que ninguna norma, ni siquiera con rango de ley, pueda afectarlos a fines concretos", "Deben destinarse a inversiones"]'::jsonb,1,'Art. 28 Ley 5/2025 CM','Se destinan al conjunto de las obligaciones, salvo que una ley establezca su afectación a fines determinados.',null),
('adm-cm:34-ba566ca5b2','adm-cm',34,'¿Cómo se puede transigir judicial o extrajudicialmente sobre los derechos de la Hacienda Pública de la Comunidad?','["Por orden del Consejero competente en hacienda", "Por resolución del Director General de Patrimonio, previo informe de los Servicios Jurídicos", "Mediante decreto acordado en Consejo de Gobierno", "Mediante ley de la Asamblea"]'::jsonb,2,'Art. 31.3 Ley 5/2025 CM','Solo mediante decreto acordado en Consejo de Gobierno.',null),
('adm-cm:34-fa5c9a900e','adm-cm',34,'Salvo que la Ley de Presupuestos Generales del Estado establezca otro, el interés de demora es:','["El interés legal del dinero", "El interés legal del dinero incrementado en un 10 %", "El doble del interés legal", "El interés legal del dinero incrementado en un 25 %"]'::jsonb,3,'Art. 36.2 Ley 5/2025 CM','Es el interés legal del dinero incrementado en un 25 por ciento, salvo que la LPGE fije otro.',null),
('adm-cm:34-395c4ee476','adm-cm',34,'¿En qué plazo prescriben los derechos de naturaleza pública de la Hacienda de la Comunidad de Madrid?','["Cuatro años", "Cinco años", "Tres años", "Diez años"]'::jsonb,0,'Art. 39.1 Ley 5/2025 CM','Prescriben a los cuatro años, tanto para reconocer o liquidar como para cobrar.',null),
('adm-cm:34-a16f5aeead','adm-cm',34,'La prescripción de los derechos de naturaleza pública de la Hacienda:','["Solo se aplica si la alega el deudor", "Se aplica de oficio", "Requiere sentencia judicial", "No existe"]'::jsonb,1,'Art. 39.2 Ley 5/2025 CM','Se aplica de oficio.',null),
('adm-cm:34-9bedf3d603','adm-cm',34,'Salvo leyes especiales, las obligaciones de la Hacienda Pública de la Comunidad prescriben a los:','["Cinco años", "Dos años", "Cuatro años", "Quince años"]'::jsonb,2,'Art. 47.1 Ley 5/2025 CM','Prescriben a los cuatro años, salvo lo que dispongan leyes especiales.',null),
('adm-cm:34-32fd1244dc','adm-cm',34,'¿Quién elabora el anteproyecto de ley de presupuestos y quién aprueba el proyecto y lo remite a la Asamblea?','["Lo elabora la Consejería competente en hacienda y lo aprueba la Asamblea", "Lo elabora el Consejo de Gobierno y lo aprueba y remite a la Asamblea el Presidente de la Comunidad", "Lo elabora cada Consejería por separado y lo aprueba la Intervención General antes de remitirlo a la Asamblea", "Lo elabora la Consejería competente en hacienda y lo aprueba y remite el Consejo de Gobierno"]'::jsonb,3,'Arts. 15 b) y 16.2 b) Ley 5/2025 CM','La Consejería de hacienda elabora el anteproyecto y el Consejo de Gobierno aprueba el proyecto y lo remite a la Asamblea.',null),
('adm-cm:34-4ab3aa3788','adm-cm',34,'El ejercicio presupuestario de la Comunidad de Madrid:','["Coincide con el año natural", "Va de julio a junio", "Va de septiembre a agosto", "Lo fija cada año el Consejo de Gobierno"]'::jsonb,0,'Art. 57.1 Ley 5/2025 CM','El ejercicio presupuestario coincide con el año natural.',null),
('adm-cm:34-f80ce44f9e','adm-cm',34,'¿Antes de qué fecha debe remitirse a la Asamblea el proyecto de ley de presupuestos?','["Antes del 1 de octubre de cada año", "Antes del 1 de noviembre de cada año", "Antes del 15 de diciembre de cada año", "Antes del 1 de septiembre de cada año"]'::jsonb,1,'Art. 71 Ley 5/2025 CM','El proyecto y su documentación se remiten antes del 1 de noviembre de cada año.',null),
('adm-cm:34-410d1c6385','adm-cm',34,'Si la ley de presupuestos no se ha aprobado antes del primer día del ejercicio:','["No se puede realizar ningún gasto hasta su aprobación, salvo los de personal, que se abonan con cargo a anticipos de tesorería", "El Consejo de Gobierno aprueba unos presupuestos provisionales por decreto hasta la publicación de los nuevos", "Se prorrogan automáticamente los presupuestos del ejercicio anterior hasta la publicación de los nuevos", "Se prorrogan los del ejercicio anterior durante un máximo de seis meses"]'::jsonb,2,'Art. 72.1 Ley 5/2025 CM','Se prorrogan automáticamente los del ejercicio anterior hasta la publicación de los nuevos en el BOCM.','abr. 2026 · 1.er ejercicio'),
('adm-cm:34-bb2979b0c6','adm-cm',34,'Entre los principios presupuestarios del art. 50.1 se encuentra:','["La rentabilidad máxima", "La confidencialidad", "La estabilidad presupuestaria", "La provisionalidad del gasto público"]'::jsonb,2,'Art. 50.1 Ley 5/2025 CM','Estabilidad presupuestaria, sostenibilidad financiera, plurianualidad, transparencia, eficiencia, responsabilidad y lealtad institucional.',null),
('adm-cm:34-57395b4275','adm-cm',34,'Según la Ley 5/2025, no son embargables los bienes de la Hacienda Pública de la Comunidad:','["Que estén situados en el extranjero", "Que tengan menos de diez años", "Materialmente afectados a un servicio público o a una función pública, entre otros supuestos", "De ningún tipo, salvo los bienes muebles y los derechos de crédito, que son embargables por mandato judicial en todo caso"]'::jsonb,2,'Art. 44 Ley 5/2025 CM','Privilegio de inembargabilidad.',null),
('adm-cm:34-accf724948','adm-cm',34,'El fondo de contingencia de la Comunidad de Madrid no será inferior al:','["2 % del presupuesto consolidado, incluidos gastos financieros", "5 % del presupuesto no financiero", "0,1 % del presupuesto no financiero", "0,5 % del presupuesto no financiero"]'::jsonb,3,'Art. 53.2 Ley 5/2025 CM','Atiende necesidades imprevistas.',null),
('adm-cm:34-817b6c2e58','adm-cm',34,'Ante un riesgo de incumplimiento de los objetivos de estabilidad, el Consejo de Gobierno puede:','["Declarar la no disponibilidad de créditos", "Disolver la Asamblea", "Subir los impuestos propios por decreto", "Suspender los pagos de nóminas"]'::jsonb,0,'Art. 51.3 Ley 5/2025 CM','Es una medida preventiva.',null),
('adm-cm:34-3086c7ea26','adm-cm',34,'Si la Hacienda de la Comunidad no paga una obligación en los ___ siguientes a la notificación de la resolución que la reconoce, deberá abonar intereses:','["Un año", "Seis meses", "Diez días", "Tres meses"]'::jsonb,3,'Art. 46.1 Ley 5/2025 CM','Desde que el acreedor reclame por escrito el cumplimiento.',null),
('adm-cm:34-14cd9712a3','adm-cm',34,'Según su art. 1, la Ley 5/2025 de Hacienda de la Comunidad de Madrid tiene por objeto:','["El régimen jurídico de los funcionarios de la Comunidad, su sistema retributivo y la gestión de las nóminas de todo el personal del sector público autonómico", "La organización y funcionamiento de la Asamblea de Madrid", "La regulación del régimen presupuestario, económico-financiero, de contabilidad, intervención y control financiero del sector público autonómico", "La regulación de los tributos propios, cedidos y locales del territorio de la Comunidad de Madrid, así como el régimen de los funcionarios encargados de su gestión, inspección y recaudación"]'::jsonb,2,'Art. 1 Ley 5/2025 CM','Es el objeto de la ley.',null),
('adm-cm:34-7370e956c6','adm-cm',34,'Según la Ley 5/2025, el presupuesto de la Asamblea de Madrid:','["No forma parte de los presupuestos generales", "Lo aprueba el Ministerio de Hacienda a propuesta de la Mesa de la Asamblea", "Lo aprueba el Consejo de Gobierno a propuesta de la Mesa de la Asamblea", "Se integra en los presupuestos generales de la Comunidad de Madrid"]'::jsonb,3,'Art. 3 Ley 5/2025 CM','Conforme al art. 61 del Estatuto.',null),
('adm-cm:34-fb83bf4ebd','adm-cm',34,'Según la Ley 5/2025, las universidades públicas madrileñas están obligadas a:','["Rendir cuentas solo ante el Ministerio de Universidades", "Rendir sus cuentas ante la Cámara de Cuentas de la Comunidad de Madrid", "Rendir cuentas ante el Tribunal de Cuentas, pero no ante la Cámara de Cuentas de la Comunidad", "Integrar su presupuesto en los presupuestos generales"]'::jsonb,1,'Art. 10 Ley 5/2025 CM','Sus presupuestos no se integran en los generales (art. 56.3).',null),
('adm-cm:34-0dbd8889ee','adm-cm',34,'Los escenarios presupuestarios plurianuales abarcan:','["Los dos ejercicios siguientes", "Los cuatro ejercicios siguientes", "Los diez ejercicios siguientes", "Solo el ejercicio corriente"]'::jsonb,1,'Art. 65.4 Ley 5/2025 CM','Según el art. 65.4.',null),
('adm-cm:34-c8590c52fc','adm-cm',34,'Según la Ley 5/2025, la superior autoridad sobre la ordenación de los pagos y su efectiva realización corresponde a:','["La Consejería competente en materia de Hacienda", "Cada Consejería respecto de sus propios créditos", "El Consejo de Gobierno, a propuesta de la Intervención General", "La Asamblea de Madrid"]'::jsonb,0,'Art. 16 f) Ley 5/2025 CM','El pago se ejerce bajo la autoridad del titular de Hacienda o del tesorero central (art. 99.3).',null),
('adm-cm:34-da3f3f8848','adm-cm',34,'Las obligaciones de pago de la Hacienda de la Comunidad son exigibles cuando resulten:','["De una noticia publicada en prensa", "De una reclamación escrita del acreedor dirigida a la Consejería competente, aunque no derive de los presupuestos ni de sentencia judicial", "De la voluntad del funcionario", "De la ejecución de los presupuestos, de sentencia judicial firme o de operaciones de tesorería legalmente autorizadas"]'::jsonb,3,'Art. 42.1 Ley 5/2025 CM','Son los títulos de exigibilidad.',null),
('adm-cm:34-97b446c3a0','adm-cm',34,'Según la Ley 5/2025, quienes tengan deudas en periodo ejecutivo con la Comunidad de Madrid:','["Solo pueden recibir subvenciones", "No pueden contratar ni recibir subvenciones, salvo que estén aplazadas, fraccionadas o suspendidas", "Pueden contratar y recibir subvenciones, pero las cantidades se compensan con la deuda", "Quedan inhabilitados de por vida"]'::jsonb,1,'Art. 33.5 Ley 5/2025 CM','Así lo establece la ley.',null),
('adm-cm:34-a05d16ab59','adm-cm',34,'La clasificación económica agrupa los créditos por:','["Programas", "Consejerías", "Capítulos", "Municipios"]'::jsonb,2,'Art. 62.1 Ley 5/2025 CM','La clasificación funcional agrupa los gastos por programas (art. 61).',null),
('adm-cm:34-d6e0922c67','adm-cm',34,'Los empleados públicos de la Comunidad de Madrid, según la Ley 5/2025:','["Pueden percibir un porcentaje de lo recaudado cuando así lo prevea la relación de puestos de trabajo", "No pueden percibir participación alguna en los tributos u otros ingresos de la Hacienda, salvo sus retribuciones", "Pueden quedarse con las multas", "Cobran comisiones por cada expediente"]'::jsonb,1,'Art. 29.3 Ley 5/2025 CM','Así lo prohíbe la ley.',null),
('adm-cm:34-66879a0aa1','adm-cm',34,'Según la Ley 5/2025, el estado de gastos de los presupuestos se estructura de acuerdo con las clasificaciones:','["Territorial y sectorial", "Orgánica, funcional y económica", "Por fondos europeos exclusivamente", "Alfabética"]'::jsonb,1,'Art. 59 Ley 5/2025 CM','La funcional agrupa por programas y la económica por capítulos.',null),
('adm-cm:34-ea3edb80dd','adm-cm',34,'En los encargos a medios propios personificados, los anticipos no podrán superar:','["El 10 % del importe del encargo", "El 25 % del importe del encargo", "El 50 %", "El 100 %"]'::jsonb,0,'Art. 42.3 Ley 5/2025 CM','En convenios con entes del sector público autonómico pueden llegar al 100 %.',null),
('adm-cm:35-d8542191e6','adm-cm',35,'Los créditos para gastos tienen carácter:','["Orientativo", "Estimativo", "Ampliable en todo caso", "Limitativo y vinculante"]'::jsonb,3,'Art. 73 Ley 5/2025 CM','Se destinan exclusivamente a la finalidad para la que fueron autorizados y tienen carácter limitativo y vinculante.',null),
('adm-cm:35-dfc0a9d19e','adm-cm',35,'¿A cuántos ejercicios futuros pueden extenderse, con carácter general, los compromisos de gasto plurianual?','["Cuatro ejercicios", "Dos ejercicios siguientes", "Seis ejercicios", "Tres ejercicios siguientes"]'::jsonb,0,'Art. 74.2 Ley 5/2025 CM','Hasta cuatro ejercicios. Límites sobre el crédito inicial: 70 % el primero, 60 % el segundo y 50 % el tercero y el cuarto.',null),
('adm-cm:35-b1cda494e4','adm-cm',35,'En los gastos plurianuales, el límite para el primer ejercicio siguiente, sobre el crédito inicial, es del:','["50 %", "70 %", "60 %", "100 %"]'::jsonb,1,'Art. 74.2 Ley 5/2025 CM','70 % el primer ejercicio siguiente, 60 % el segundo y 50 % el tercero y el cuarto (100 % en gastos corrientes en bienes y servicios).',null),
('adm-cm:35-b7c6eb606a','adm-cm',35,'La concesión de un crédito extraordinario en la Administración de la Comunidad se tramita:','["Por orden del Consejero competente en hacienda", "Por decreto del Consejo de Gobierno, dando cuenta posteriormente a la Comisión de Presupuestos de la Asamblea", "Mediante un proyecto de ley que el Consejo de Gobierno remite a la Asamblea", "Por acuerdo de la Mesa de la Asamblea"]'::jsonb,2,'Art. 83.1 Ley 5/2025 CM','El titular de Hacienda lo eleva al Consejo de Gobierno, que remite a la Asamblea un proyecto de ley.',null),
('adm-cm:35-8eb9ecef96','adm-cm',35,'¿Cuál es una limitación de las transferencias de crédito?','["Solo pueden acordarse en el último trimestre del ejercicio", "Requieren siempre una ley de la Asamblea", "Solo pueden afectar a créditos de gastos de personal del mismo programa", "No pueden minorar créditos que ya hayan sido incrementados con transferencias"]'::jsonb,3,'Art. 86.2 Ley 5/2025 CM','No afectan a créditos ampliables ni extraordinarios concedidos en el ejercicio, no minoran créditos ya incrementados y no incrementan créditos ya minorados.',null),
('adm-cm:35-9823f16630','adm-cm',35,'Las generaciones de crédito incrementan los créditos como consecuencia de:','["Ingresos no previstos o superiores a los estimados", "La reducción de otros créditos del mismo programa o de otro programa distinto del presupuesto", "La aprobación de un crédito extraordinario", "Préstamos de otras Administraciones"]'::jsonb,0,'Art. 88.1 Ley 5/2025 CM','Se producen por ingresos no previstos o superiores a los estimados.',null),
('adm-cm:35-850f8e4c6d','adm-cm',35,'Según el principio de especialidad cualitativa, los créditos para gastos:','["Solo pueden gastarse en gastos de personal", "Se destinan a lo que decida cada gestor dentro de su sección presupuestaria, sin vinculación a una finalidad concreta", "Se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados", "Se destinarán a la finalidad para la que hayan sido autorizados o a cualquier otra del mismo capítulo"]'::jsonb,2,'Art. 73.1 Ley 5/2025 CM','La especialidad cuantitativa impide comprometer gasto por encima del crédito (art. 73.3).',null),
('adm-cm:35-d55d21fec1','adm-cm',35,'Los créditos para gastos que el último día del ejercicio no estén afectados al cumplimiento de obligaciones reconocidas:','["Pasan al fondo de contingencia", "Se transfieren a la Asamblea", "Se incorporan automáticamente al ejercicio siguiente", "Quedarán anulados de pleno derecho"]'::jsonb,3,'Art. 81 Ley 5/2025 CM','Es una manifestación del principio de anualidad.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:35-3565732971','adm-cm',35,'Según la Ley 5/2025, son créditos ampliables:','["Los que se relacionen de forma taxativa en la ley de presupuestos", "Los de inversiones reales en todo caso", "Cualquier crédito, a petición motivada del centro gestor y con autorización del Consejero de Hacienda", "Todos los créditos de personal"]'::jsonb,0,'Art. 85.2 Ley 5/2025 CM','La relación es taxativa.',null),
('adm-cm:35-09e8900d6e','adm-cm',35,'Las incorporaciones de crédito requieren:','["Un informe favorable del Tribunal de Cuentas", "La existencia de remanente de tesorería positivo", "Que el crédito sea de personal", "Autorización previa de la Asamblea en todo caso, mediante ley"]'::jsonb,1,'Art. 90.1 Ley 5/2025 CM','Según el art. 90.1.',null),
('adm-cm:35-d1a9f8b563','adm-cm',35,'En los gastos plurianuales corrientes en bienes y servicios, el porcentaje máximo aplicable a cada ejercicio futuro es:','["El 100 %", "El 50 %", "El 60 %", "El 70 %"]'::jsonb,0,'Art. 74.2 Ley 5/2025 CM','Para el resto, los límites son el 70 %, 60 % y 50 %.',null),
('adm-cm:35-a938279fc7','adm-cm',35,'Según la Ley 5/2025 de Hacienda de la Comunidad de Madrid, ¿a cuántos ejercicios futuros pueden aplicarse, como regla general, los gastos plurianuales?','["Cinco", "Tres", "Cuatro", "Seis"]'::jsonb,2,'Art. 74 Ley 5/2025 CM','El número de ejercicios futuros a que pueden aplicarse los gastos plurianuales no será superior a cuatro.',null),
('adm-cm:35-6da6b28a17','adm-cm',35,'En los gastos plurianuales, ¿qué porcentaje del crédito inicial puede imputarse, como máximo, al ejercicio inmediato siguiente?','["El 50 %", "El 70 %", "El 100 %", "El 60 %"]'::jsonb,1,'Art. 74 Ley 5/2025 CM','Los límites son el 70 % en el ejercicio inmediato siguiente, el 60 % en el segundo y el 50 % en el tercero y el cuarto.',null),
('adm-cm:35-7ba9451762','adm-cm',35,'En los gastos plurianuales, ¿qué porcentaje se aplica en los ejercicios tercero y cuarto?','["El 50 %", "El 40 %", "El 60 %", "El 70 %"]'::jsonb,0,'Art. 74 Ley 5/2025 CM','En los ejercicios tercero y cuarto el límite es el 50 % del crédito inicial.',null),
('adm-cm:35-340a98afc0','adm-cm',35,'En los gastos corrientes en bienes y servicios de carácter plurianual, ¿qué porcentaje puede imputarse a cada ejercicio posterior?','["El 70 %", "El 80 %", "El 50 %", "El 100 %"]'::jsonb,3,'Art. 74 Ley 5/2025 CM','En los gastos corrientes en bienes y servicios el porcentaje aplicable a cada ejercicio posterior es el 100 %.',null),
('adm-cm:35-3c12b94442','adm-cm',35,'En los contratos de obra plurianuales, salvo abono total del precio, ¿qué retención adicional de crédito se practica al adjudicar?','["El 3 % del valor estimado", "El 5 % del importe de adjudicación", "El 10 % del importe de adjudicación", "El 20 % del presupuesto de licitación"]'::jsonb,2,'Art. 74 Ley 5/2025 CM','Se efectúa una retención adicional de crédito del 10 % del importe de adjudicación en el momento de la adjudicación.',null),
('adm-cm:35-2d2ce7f24a','adm-cm',35,'¿A cuál de estos compromisos NO se aplican los límites de anualidades y porcentajes de los gastos plurianuales?','["A las subvenciones en concurrencia competitiva", "A los arrendamientos de inmuebles", "A los contratos de obras ordinarios", "A los contratos de suministro"]'::jsonb,1,'Art. 74 Ley 5/2025 CM','No se aplican a la carga financiera de la deuda, la contratación de personal temporal, ciertos interinos y los arrendamientos de inmuebles.',null),
('adm-cm:35-a64904c18a','adm-cm',35,'¿Quién puede modificar excepcionalmente los porcentajes y anualidades de los gastos plurianuales?','["El titular de cada consejería en su ámbito", "El Consejo de Gobierno, previo informe de la Asamblea", "El titular de la consejería competente en materia de hacienda", "La Intervención General"]'::jsonb,2,'Art. 74 Ley 5/2025 CM','En casos especialmente justificados, el titular de la consejería de hacienda puede modificar los límites, a solicitud de la consejería correspondiente.',null),
('adm-cm:35-acb97a5399','adm-cm',35,'¿Hasta qué momento puede llegar la tramitación anticipada de un expediente de gasto?','["Hasta el momento inmediatamente anterior a la autorización del compromiso de gasto", "Hasta la aprobación del gasto incluida", "Hasta la propuesta de pago", "Hasta el reconocimiento de la obligación, siempre que exista crédito en el ejercicio"]'::jsonb,0,'Art. 77 Ley 5/2025 CM','Puede iniciarse en el ejercicio anterior y alcanzar, como máximo, hasta el momento inmediatamente anterior a la autorización del compromiso de gasto.',null),
('adm-cm:35-e18c8ae283','adm-cm',35,'¿Qué ocurre con los créditos no afectados a obligaciones reconocidas el último día del ejercicio?','["Se incorporan automáticamente al ejercicio siguiente", "Se mantienen vigentes tres meses más", "Se transfieren al Fondo de Contingencia", "Quedan anulados de pleno derecho, salvo incorporación"]'::jsonb,3,'Art. 81 Ley 5/2025 CM','Los créditos no afectados a obligaciones reconocidas quedan anulados de pleno derecho, sin perjuicio de las incorporaciones del art. 90.',null),
('adm-cm:35-262f063da3','adm-cm',35,'Si es necesario un gasto inaplazable y no existe crédito, ¿qué se remite a la Asamblea de Madrid?','["Una orden de generación de crédito", "Un proyecto de ley de crédito extraordinario", "Una solicitud de ampliación de crédito", "Un proyecto de ley de suplemento de crédito"]'::jsonb,1,'Art. 83 Ley 5/2025 CM','Si no existe crédito se tramita un crédito extraordinario; si es insuficiente y no ampliable, un suplemento de crédito, ambos por ley.',null),
('adm-cm:35-7b772f6c3c','adm-cm',35,'En un organismo autónomo, ¿quién concede un crédito extraordinario sin aumento del presupuesto general si no excede del 2 % de su presupuesto de gastos?','["La Asamblea de Madrid", "El Consejo de Gobierno", "El gerente del organismo", "El titular de la consejería de hacienda"]'::jsonb,3,'Art. 83 Ley 5/2025 CM','Hasta el 2 % lo concede el titular de la consejería de hacienda; del 2 % al 5 %, el Consejo de Gobierno; en el resto de casos, la Asamblea.',null),
('adm-cm:35-c43c4be9c8','adm-cm',35,'¿Quién autoriza las ampliaciones de crédito según la Ley 5/2025 de Hacienda de Madrid?','["La Comisión de Presupuestos de la Asamblea", "El titular de la consejería afectada", "El titular de la consejería competente en materia de hacienda", "El Consejo de Gobierno"]'::jsonb,2,'Art. 85 Ley 5/2025 CM','Las ampliaciones de crédito son autorizadas por el titular de la consejería competente en materia de hacienda.',null),
('adm-cm:35-d4e4f84616','adm-cm',35,'¿Cuál de estas es una limitación general de las transferencias de crédito?','["No pueden minorar créditos incrementados con suplementos o transferencias", "Necesitan siempre autorización de la Asamblea", "No pueden afectar a créditos de personal", "Solo pueden hacerse en el último trimestre"]'::jsonb,0,'Art. 86 Ley 5/2025 CM','Las transferencias no afectan a créditos ampliables ni extraordinarios del ejercicio, no minoran créditos incrementados y no incrementan créditos minorados.',null),
('adm-cm:35-d6e541f7cb','adm-cm',35,'¿A qué transferencias de crédito NO se aplican las limitaciones generales?','["A las que afecten exclusivamente a créditos para gastos de personal", "A las que creen subvenciones nominativas nuevas", "A todas las que autorice el Consejo de Gobierno", "A las que afecten a créditos ampliables"]'::jsonb,0,'Art. 86 Ley 5/2025 CM','Entre otras, quedan exceptuadas las que afecten exclusivamente a créditos para gastos de personal.',null),
('adm-cm:35-24d8dd7271','adm-cm',35,'¿Qué órgano autoriza las transferencias entre gastos corrientes y de capital de distintas secciones?','["El titular de la consejería de hacienda, sin más trámite ni informe previo de ningún otro órgano", "El Consejo de Gobierno, previo informe favorable de la Comisión de Presupuestos de la Asamblea", "El titular de cada consejería afectada", "La Asamblea de Madrid mediante ley"]'::jsonb,1,'Art. 87 Ley 5/2025 CM','Las autoriza el Consejo de Gobierno, a propuesta del titular de hacienda, previo informe favorable de la comisión de presupuestos de la Asamblea.',null),
('adm-cm:35-83857de2ad','adm-cm',35,'¿Qué requisito exige la incorporación de remanentes de crédito al ejercicio siguiente?','["Que se trate de créditos de personal", "Que lo apruebe la Asamblea en todo caso", "Que exista remanente de tesorería positivo", "Que el crédito se hubiera comprometido en enero"]'::jsonb,2,'Art. 90 Ley 5/2025 CM','Cuando exista remanente de tesorería positivo, el titular de hacienda puede autorizar la incorporación de determinados créditos al ejercicio siguiente.',null),
('adm-cm:35-b98a9f80bb','adm-cm',35,'¿Qué precisa la incorporación de remanentes no comprometidos de ejercicios anteriores?','["Informe de la Cámara de Cuentas", "Acuerdo del Consejo de Gobierno", "Nada especial", "Informe favorable de la Comisión de Presupuestos de la Asamblea de Madrid"]'::jsonb,3,'Art. 90 Ley 5/2025 CM','La incorporación de remanentes no comprometidos precisa informe favorable de la comisión de presupuestos de la Asamblea.',null),
('adm-cm:35-202f1ff680','adm-cm',35,'¿Qué producen los ingresos obtenidos por reintegro de pagos indebidos con cargo a créditos presupuestarios?','["Un mayor remanente de tesorería afectado", "Una generación de crédito previa autorización", "Un ingreso en el Fondo de Contingencia", "La reposición automática del crédito"]'::jsonb,3,'Art. 91 Ley 5/2025 CM','Dan lugar a reposición automática de crédito en la respectiva aplicación presupuestaria.',null),
('adm-cm:36-120c52c5ce','adm-cm',36,'¿Cuál es el orden de las fases de ejecución del gasto?','["Disposición, autorización, reconocimiento de la obligación y propuesta de pago", "Autorización, disposición, reconocimiento de la obligación y propuesta de pago", "Reconocimiento de la obligación, autorización, disposición y propuesta de pago", "Autorización, reconocimiento de la obligación, disposición y propuesta de pago"]'::jsonb,1,'Art. 92 Ley 5/2025 CM','Autorización, disposición, reconocimiento de la obligación y propuesta de pago, en ese orden, aunque pueden acumularse.',null),
('adm-cm:36-1cebf14322','adm-cm',36,'Los anticipos de caja fija son, según la Ley 5/2025:','["Créditos extraordinarios", "Préstamos a empleados públicos", "Provisiones de fondos de carácter permanente para atender gastos periódicos o repetitivos, consideradas operaciones extrapresupuestarias", "Provisiones de fondos de carácter puntual para gastos de inversión, que se aplican al presupuesto antes del pago y se consideran operaciones presupuestarias"]'::jsonb,2,'Art. 102 Ley 5/2025 CM','Son operaciones extrapresupuestarias.',null),
('adm-cm:36-59db60c99d','adm-cm',36,'En los organismos autónomos, la competencia para autorizar y comprometer gastos corresponde, con carácter general, a:','["El Interventor General", "El Consejo de Gobierno", "Sus gerentes", "La Asamblea"]'::jsonb,2,'Art. 94.1 Ley 5/2025 CM','Según el art. 94.1.',null),
('adm-cm:36-211b9d54d2','adm-cm',36,'Según la Ley 5/2025, el proceso de pago comprende las fases de:','["Ordenación del pago y realización del pago", "Autorización y disposición", "Propuesta y fiscalización", "Reconocimiento de la obligación y liquidación"]'::jsonb,0,'Art. 99.1 Ley 5/2025 CM','Ambas se ejercen bajo la autoridad de Hacienda.',null),
('adm-cm:36-19c81edfaf','adm-cm',36,'Corresponde al Consejo de Gobierno autorizar los gastos:','["De capítulo 1 de cada Consejería en todo caso", "De caja fija", "De menos de 3.000 euros", "De cuantía indeterminada, entre otros"]'::jsonb,3,'Art. 95.1 Ley 5/2025 CM','También los plurianuales que superen el límite legal y los que excedan los importes fijados.',null),
('adm-cm:36-ff19d303d8','adm-cm',36,'Según la Ley 5/2025 de Hacienda de Madrid, ¿cuál es el orden de las fases del proceso del gasto?','["Disposición, autorización, propuesta de pago y reconocimiento de la obligación, por este orden", "Autorización, disposición, reconocimiento de la obligación y propuesta de pago", "Compromiso, autorización, ordenación y pago", "Autorización, reconocimiento, disposición y pago material"]'::jsonb,1,'Art. 92 Ley 5/2025 CM','Las fases son autorización, disposición, reconocimiento de la obligación y propuesta de pago, sin omisiones y en ese orden.',null),
('adm-cm:36-706bda9f7a','adm-cm',36,'¿Qué fase del gasto es el acto por el que se acepta una propuesta de gasto y se reserva el crédito adecuado?','["La disposición", "La propuesta de pago", "La autorización", "El reconocimiento de la obligación"]'::jsonb,2,'Art. 92 Ley 5/2025 CM','La autorización es el acto de previsión por el que se acepta una propuesta de gasto, reservando el importe del crédito adecuado.',null),
('adm-cm:36-0596c969b3','adm-cm',36,'¿Con qué fase del gasto queda formalizada la reserva del crédito por importe y condiciones exactamente determinadas?','["Con la disposición o compromiso", "Con la ordenación del pago", "Con la autorización", "Con el reconocimiento de la obligación"]'::jsonb,0,'Art. 92 Ley 5/2025 CM','Con los actos de disposición o compromiso queda formalizada la reserva del crédito por un importe y condiciones exactamente determinadas.',null),
('adm-cm:36-73547dbe0b','adm-cm',36,'¿Qué es el reconocimiento de la obligación?','["La salida material de fondos de la tesorería", "La operación por la que se contraen en cuentas los créditos exigibles contra la Administración", "La solicitud de pago que el centro gestor dirige a la consejería competente en materia de hacienda", "El acto por el que se reserva el crédito"]'::jsonb,1,'Art. 92 Ley 5/2025 CM','Es la operación por la que se contraen en cuentas los créditos exigibles, reconociendo la obligación de cumplir una prestación dineraria.',null),
('adm-cm:36-40ca980f5c','adm-cm',36,'¿Pueden acumularse varias fases del gasto en un solo acto?','["Sí, si el procedimiento y el control previo lo permiten", "Solo la autorización y el pago", "No, cada fase exige un acto distinto", "Solo en los gastos de personal"]'::jsonb,0,'Art. 92 Ley 5/2025 CM','Pueden acumularse en un solo acto y documento siempre que el procedimiento administrativo y el control previo lo permitan.',null),
('adm-cm:36-3b5189e804','adm-cm',36,'¿Quién autoriza o compromete en todo caso los gastos del capítulo 1, Gastos de personal, en la Administración de la Comunidad de Madrid?','["El Consejo de Gobierno", "El titular de la consejería de hacienda", "La Dirección General de Función Pública", "El titular de cada consejería"]'::jsonb,3,'Art. 93 Ley 5/2025 CM','Corresponde en todo caso al titular de cada consejería la autorización o el compromiso de los gastos del capítulo 1.',null),
('adm-cm:36-a4fc156416','adm-cm',36,'¿Quién autoriza el gasto cuando afecta a créditos de la sección Deuda Pública?','["El titular de cada consejería", "El Consejo de Gobierno", "El titular de la consejería competente en materia de hacienda", "La Asamblea de Madrid"]'::jsonb,2,'Art. 93 Ley 5/2025 CM','Es competencia del titular de la consejería de hacienda la autorización o el compromiso de gasto que afecte a la sección Deuda Pública.',null),
('adm-cm:36-33c1418e70','adm-cm',36,'En los organismos autónomos, ¿a quién corresponden, con carácter general, los actos del proceso del gasto?','["Al titular de la consejería de adscripción", "A los gerentes", "Al Consejo de Gobierno", "A la Intervención Delegada"]'::jsonb,1,'Art. 94 Ley 5/2025 CM','Salvo los supuestos reservados al Consejo de Gobierno, compete a los gerentes de los organismos autónomos.',null),
('adm-cm:36-6a7b3f0267','adm-cm',36,'¿Cuál de estos gastos está reservado en todo caso al Consejo de Gobierno?','["Los gastos de cuantía indeterminada", "Los gastos menores de 5.000 euros", "Los gastos de arrendamientos prorrogados", "Los gastos de personal de cada consejería"]'::jsonb,0,'Art. 95 Ley 5/2025 CM','Se reservan al Consejo de Gobierno, entre otros, los gastos de cuantía indeterminada y los plurianuales o corrientes que superen los importes de la ley de presupuestos.',null),
('adm-cm:36-adb491317b','adm-cm',36,'¿Qué debe acreditarse antes de reconocer una obligación con cargo a los presupuestos?','["La firma del contrato ante notario", "El informe de la Cámara de Cuentas", "La existencia de remanente de tesorería", "La realización de la prestación o el derecho del acreedor"]'::jsonb,3,'Art. 96 Ley 5/2025 CM','Debe acreditarse documentalmente la realización de la prestación o el derecho del acreedor conforme a los acuerdos de autorización y compromiso.',null),
('adm-cm:36-cc24e0cfe3','adm-cm',36,'¿Qué es el reconocimiento de un derecho económico en la gestión del presupuesto de ingresos?','["La recaudación efectiva del ingreso en la tesorería", "La previsión de ingresos del estado de ingresos", "La operación por la que se contrae en cuentas la deuda exigible a un tercero a favor de la Administración", "El compromiso de un tercero de aportar fondos en el futuro mediante un convenio o un contrato ya firmado"]'::jsonb,2,'Art. 97 Ley 5/2025 CM','Es la operación por la que se contrae en cuentas la deuda a favor de la Administración exigible a un tercero.',null),
('adm-cm:37-d83f711da7','adm-cm',37,'¿Qué modalidades comprende el control interno de la Intervención General de la Comunidad de Madrid?','["Control de legalidad, de oportunidad y de eficacia", "Fiscalización previa, auditoría externa y control parlamentario", "Función interventora, control financiero y control contable", "Intervención formal, material y de pagos"]'::jsonb,2,'Art. 115 Ley 5/2025 CM','El control interno comprende las modalidades de función interventora, control financiero y control contable.',null),
('adm-cm:37-4d8140c9fa','adm-cm',37,'¿Qué carácter tiene la Intervención General de la Comunidad de Madrid?','["Órgano superior de control interno y órgano directivo y gestor de la contabilidad pública", "Órgano consultivo del Consejo de Gobierno", "Unidad administrativa de la secretaría general técnica de la consejería competente en materia de hacienda", "Órgano de control externo dependiente de la Asamblea"]'::jsonb,0,'Art. 111 Ley 5/2025 CM','Es el órgano superior de control interno del sector público autonómico y órgano directivo y gestor de su contabilidad pública.',null),
('adm-cm:37-dc31d93857','adm-cm',37,'¿Con qué principios desarrolla sus funciones la Intervención General de la Comunidad de Madrid?','["Legalidad, publicidad, concurrencia e igualdad", "Autonomía, ejercicio desconcentrado, jerarquía interna y procedimiento contradictorio", "Coordinación, cooperación, lealtad institucional, subsidiariedad y eficacia en la gestión", "Oportunidad, eficacia, economía y celeridad"]'::jsonb,1,'Art. 112 Ley 5/2025 CM','Sus principios son autonomía, ejercicio desconcentrado, jerarquía interna y procedimiento contradictorio.',null),
('adm-cm:37-da8601761c','adm-cm',37,'¿Qué consideración tiene el personal de la Intervención General en el control financiero de subvenciones?','["Auditor externo", "Policía judicial", "Inspector tributario", "Agente de la autoridad"]'::jsonb,3,'Art. 113 Ley 5/2025 CM','En el control financiero de subvenciones, el personal de la Intervención General es considerado agente de la autoridad.',null),
('adm-cm:37-7c590fb693','adm-cm',37,'¿Qué tiene por objeto la función interventora?','["Auditar las cuentas anuales de las empresas públicas", "Controlar, antes de su aprobación, los actos que den lugar a derechos, gastos, ingresos y pagos, para verificar su legalidad", "Comprobar a posteriori, mediante auditorías anuales, la buena gestión financiera de todo el sector público autonómico madrileño", "Verificar la aplicación del plan general de contabilidad pública"]'::jsonb,1,'Art. 116 Ley 5/2025 CM','La función interventora controla previamente los actos que puedan dar lugar a derechos, gastos, ingresos y pagos, para verificar su legalidad.',null),
('adm-cm:37-d63243a6df','adm-cm',37,'¿Por qué se sustituye la fiscalización previa de los derechos?','["Por el control financiero permanente", "Por la intervención material del cobro", "Por la toma de razón en contabilidad", "Por la auditoría pública anual"]'::jsonb,2,'Art. 116 Ley 5/2025 CM','La fiscalización previa de los derechos se sustituye por la inherente a la toma de razón en contabilidad.',null),
('adm-cm:37-f71fa0ea78','adm-cm',37,'¿Quién puede sustituir la función interventora por el control financiero permanente en un organismo?','["El titular de la consejería de hacienda", "El Interventor General", "La Asamblea de Madrid", "El Consejo de Gobierno"]'::jsonb,3,'Art. 116 Ley 5/2025 CM','El Consejo de Gobierno puede sustituir la función interventora por el control financiero permanente en toda la actividad de un organismo o en algunas áreas.',null),
('adm-cm:37-c915571925','adm-cm',37,'¿Qué diferencia la intervención formal de la material?','["La formal verifica los requisitos legales del expediente y la material comprueba la aplicación real de los fondos", "La formal la ejercen siempre los interventores delegados y la material, en exclusiva, el Interventor General en persona", "La formal es previa y la material siempre posterior al pago", "La formal se hace por escrito y la material de palabra"]'::jsonb,0,'Art. 117 Ley 5/2025 CM','La intervención formal verifica los requisitos legales mediante el examen de los documentos; en la material se comprueba la real y efectiva aplicación de los fondos.',null),
('adm-cm:37-e38b09d9fa','adm-cm',37,'En la fiscalización previa de requisitos esenciales, ¿qué se comprueba en todo caso?','["Solo la firma del órgano gestor", "La existencia de crédito adecuado y la competencia del órgano", "La oportunidad del gasto y su eficacia", "La totalidad de los documentos del expediente"]'::jsonb,1,'Art. 118 Ley 5/2025 CM','Se comprueba la existencia de crédito adecuado, la competencia del órgano y que las obligaciones correspondan a gastos aprobados y fiscalizados, más los extremos que fije el Consejo de Gobierno.',null),
('adm-cm:37-e1ad4d1eed','adm-cm',37,'¿Sobre qué gastos puede ejercerse la función interventora sobre una muestra y no sobre el total?','["Los contratos de obras de más de un millón de euros", "Los gastos que aprueba el Consejo de Gobierno", "Los gastos de cuantía indeterminada", "Los gastos de personal y de subvenciones, entre otros de gran volumen"]'::jsonb,3,'Art. 119 Ley 5/2025 CM','Puede ejercerse sobre una muestra en gastos de personal y subvenciones y en otros que afecten a un gran número de actos.',null),
('adm-cm:37-a2b96dad1c','adm-cm',37,'¿Cuál de estos gastos está exento de fiscalización previa en sus fases de autorización y disposición?','["Las subvenciones en concurrencia competitiva", "Los convenios con entidades locales", "Los contratos menores", "Los contratos de obras"]'::jsonb,2,'Art. 120 Ley 5/2025 CM','Están exentos, entre otros, los contratos menores, los gastos periódicos tras el inicial y las subvenciones nominativas.',null),
('adm-cm:37-48fd25da66','adm-cm',37,'¿Hasta qué importe están exentos de fiscalización previa los gastos pagados por anticipo de caja fija?','["Menores de 5.000 euros", "Menores de 50.000 euros", "Menores de 3.000 euros", "Menores de 15.000 euros"]'::jsonb,0,'Art. 120 Ley 5/2025 CM','Están exentos los gastos menores de 5.000 euros cuyo pago se realice mediante anticipo de caja fija.',null),
('adm-cm:37-4103e9ac28','adm-cm',37,'¿Qué es la comprobación material del gasto?','["El examen de la contabilidad del órgano gestor", "La verificación material de la efectiva realización de contratos, convenios y subvenciones", "La comprobación de la existencia de crédito", "La revisión de las cuentas anuales de la Comunidad que realiza cada año la Cámara de Cuentas"]'::jsonb,1,'Art. 122 Ley 5/2025 CM','Es la facultad de verificar materialmente la efectiva realización de los contratos, convenios y subvenciones financiados con fondos públicos.',null),
('adm-cm:37-b1d43d7403','adm-cm',37,'¿Qué efecto tiene la formulación de un reparo por la Intervención?','["Anula el expediente de pleno derecho", "Obliga a remitir el expediente a la Asamblea", "Suspende la tramitación del expediente hasta que se solvente", "Ninguno, es una mera observación"]'::jsonb,2,'Art. 123 Ley 5/2025 CM','El reparo suspende la tramitación del expediente hasta que se subsane o se resuelva la discrepancia.',null),
('adm-cm:37-c7cd1c939b','adm-cm',37,'¿Cuál de estos es un supuesto de reparo en el régimen general de fiscalización previa?','["Que el gasto se proponga a un órgano sin competencia para aprobarlo", "Que el gasto sea inferior al previsto", "Que el gasto se tramite al final del ejercicio", "Que el expediente tenga erratas no esenciales"]'::jsonb,0,'Art. 123 Ley 5/2025 CM','Procede reparo, entre otros, por insuficiencia o inadecuación del crédito, incompetencia del órgano u omisión de requisitos que puedan causar nulidad.',null),
('adm-cm:37-fdde5374c0','adm-cm',37,'¿Tienen efectos suspensivos las observaciones complementarias de la Intervención?','["Solo en gastos superiores a 50.000 euros", "Sí, como los reparos", "Solo si las formula el Interventor General", "No, en ningún caso"]'::jsonb,3,'Art. 123 Ley 5/2025 CM','Las observaciones complementarias no tienen, en ningún caso, efectos suspensivos.',null),
('adm-cm:37-df41e7391d','adm-cm',37,'Si el reparo lo formuló o confirmó la Intervención General y persiste la discrepancia, ¿quién resuelve?','["El Consejo de Gobierno", "La Asamblea de Madrid", "El titular de la consejería de hacienda", "El Tribunal de Cuentas"]'::jsonb,0,'Art. 124 Ley 5/2025 CM','Si el reparo lo formuló o confirmó la Intervención General y subsiste la discrepancia, adopta la resolución definitiva el Consejo de Gobierno.',null),
('adm-cm:37-41243247f4','adm-cm',37,'Si una intervención delegada formula un reparo y el gestor discrepa, ¿quién conoce de la discrepancia?','["La Cámara de Cuentas", "La Intervención General de la Comunidad de Madrid", "El Consejo de Gobierno directamente", "El titular de la consejería afectada"]'::jsonb,1,'Art. 124 Ley 5/2025 CM','Cuando el reparo lo formula una intervención delegada, conoce de la discrepancia la Intervención General, cuya resolución es obligatoria para aquella.',null),
('adm-cm:37-c8378efe7f','adm-cm',37,'Si se ha omitido la fiscalización previa preceptiva, ¿quién acuerda someter la cuestión al Consejo de Gobierno?','["La Intervención General de oficio", "El titular de la consejería de hacienda en todo caso", "El órgano gestor que omitió la fiscalización", "El titular de la consejería del órgano tramitador, sin posibilidad de delegación"]'::jsonb,3,'Art. 125 Ley 5/2025 CM','Corresponde al titular de la consejería del órgano responsable, sin que pueda delegarse, previo informe de la Intervención General.',null),
('adm-cm:38-29b2dc02a7','adm-cm',38,'Las retribuciones básicas están integradas por:','["La productividad y las gratificaciones por servicios extraordinarios", "El sueldo asignado a cada subgrupo o grupo y los trienios", "El complemento de destino y el complemento específico", "El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.','abr. 2026 · 1.er ejercicio'),
('adm-cm:38-a7fe881a27','adm-cm',38,'Las pagas extraordinarias de los funcionarios serán:','["Una al año, por el importe de una mensualidad de retribuciones básicas", "Cuatro al año", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones"]'::jsonb,3,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('adm-cm:38-19f5a0dba6','adm-cm',38,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana", "La separación del servicio", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('adm-cm:38-13b9d0a400','adm-cm',38,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Año de servicio", "Cinco años de servicio", "Dos años de servicio", "Tres años de servicio"]'::jsonb,3,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('adm-cm:38-193f3ac39d','adm-cm',38,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Ordinarias y extraordinarias", "Directas e indirectas", "Básicas y complementarias", "Fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('adm-cm:38-3cbb6e59cd','adm-cm',38,'Según el TREBEP, ¿dónde deben reflejarse cada año las cuantías de las retribuciones básicas y el incremento de la masa salarial del personal laboral?','["En la relación de puestos de trabajo", "En el convenio colectivo de cada Administración", "En la correspondiente ley de presupuestos", "En un decreto del Consejo de Gobierno"]'::jsonb,2,'Art. 21.1 TREBEP','Deben reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos.',null),
('adm-cm:38-db99c03c3a','adm-cm',38,'¿Cómo se clasifican las retribuciones de los funcionarios de carrera según el TREBEP?','["En ordinarias y extraordinarias", "En salariales y extrasalariales", "En básicas y complementarias", "En fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las retribuciones de los funcionarios de carrera se clasifican en básicas y complementarias.',null),
('adm-cm:38-d973d934ff','adm-cm',38,'¿Qué retribuyen las retribuciones básicas de los funcionarios?','["Los servicios extraordinarios fuera de la jornada", "Las características del puesto de trabajo", "El rendimiento y los resultados alcanzados", "La adscripción del cuerpo o escala a un subgrupo o grupo y la antigüedad en él"]'::jsonb,3,'Art. 22.2 TREBEP','Retribuyen según la adscripción del cuerpo o escala a un subgrupo o grupo de clasificación profesional y la antigüedad en el mismo.',null),
('adm-cm:38-e33648b9e6','adm-cm',38,'¿Cuántas pagas extraordinarias al año perciben los funcionarios según el TREBEP?','["Dos", "Una", "Tres", "Catorce"]'::jsonb,0,'Art. 22.4 TREBEP','Las pagas extraordinarias serán dos al año.',null),
('adm-cm:38-ea2e98bd6b','adm-cm',38,'¿Qué incluye cada paga extraordinaria de los funcionarios?','["La mitad de las retribuciones anuales", "Una mensualidad de retribuciones básicas y la totalidad de las complementarias, salvo las de productividad y gratificaciones", "Solo el sueldo base y los trienios correspondientes al mes de junio o de diciembre, sin incluir ningún complemento retributivo", "El sueldo y los trienios, sin complementos"]'::jsonb,1,'Art. 22.4 TREBEP','Cada paga incluye una mensualidad de básicas y la totalidad de complementarias, salvo las de las letras c) y d) del art. 24.',null),
('adm-cm:38-ba8ac64e58','adm-cm',38,'¿Por qué está integrado, única y exclusivamente, el conjunto de retribuciones básicas?','["Por el sueldo y los trienios", "Por el sueldo, los trienios y el complemento de destino", "Por el sueldo y el complemento específico", "Por el sueldo, los trienios y la productividad"]'::jsonb,0,'Art. 23 TREBEP','Las retribuciones básicas están integradas única y exclusivamente por el sueldo y los trienios.',null),
('adm-cm:38-77e37d719c','adm-cm',38,'¿Cada cuánto tiempo de servicio se devenga un trienio?','["Cada cuatro años", "Cada tres años", "Cada cinco años", "Cada dos años"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad igual para cada subgrupo o grupo por cada tres años de servicio.',null),
('adm-cm:38-3136a26cb8','adm-cm',38,'¿Qué factor retribuyen los servicios extraordinarios prestados fuera de la jornada normal?','["El complemento de puesto", "Los trienios", "Un complemento ligado a los servicios extraordinarios fuera de la jornada", "El complemento de carrera"]'::jsonb,2,'Art. 24 d) TREBEP','Entre los factores de las retribuciones complementarias está la retribución de los servicios extraordinarios prestados fuera de la jornada normal.',null),
('adm-cm:38-3adc6c00cb','adm-cm',38,'¿Qué retribuciones complementarias perciben los funcionarios interinos según el TREBEP?','["Todas las del funcionario de carrera, incluida la progresión alcanzada en la carrera administrativa", "Solo las gratificaciones extraordinarias", "Ninguna, solo las básicas", "Las de los apartados b), c) y d) del art. 24 y las de la categoría de entrada"]'::jsonb,3,'Art. 25.1 TREBEP','Perciben las complementarias de las letras b), c) y d) del art. 24 y las de la categoría de entrada en el cuerpo o escala.',null),
('adm-cm:38-4930f14f6f','adm-cm',38,'¿Cuál es la retribución mínima de los funcionarios en prácticas según el TREBEP?','["Las retribuciones íntegras del puesto que ocuparán", "El salario mínimo interprofesional", "El sueldo del subgrupo o grupo al que aspiran a ingresar", "El 80 % de las retribuciones del puesto"]'::jsonb,2,'Art. 26 TREBEP','Como mínimo, corresponderán al sueldo del subgrupo o grupo en que aspiren a ingresar.',null),
('adm-cm:38-88eb37d27b','adm-cm',38,'¿Qué consideración tienen las cantidades destinadas a planes de pensiones de empleo del personal público?','["Retribución diferida", "Indemnización por razón del servicio", "Complemento personal transitorio", "Acción social"]'::jsonb,0,'Art. 29 TREBEP','Las cantidades destinadas a financiar aportaciones a planes de pensiones o seguros tienen la consideración de retribución diferida.',null),
('adm-cm:38-936149faed','adm-cm',38,'¿Qué carácter tiene la deducción proporcional de haberes por la parte de jornada no realizada?','["Es una sanción disciplinaria grave", "No tiene carácter sancionador", "Solo procede si hay expediente disciplinario", "Es una sanción disciplinaria leve"]'::jsonb,1,'Art. 30.1 TREBEP','La parte de jornada no realizada da lugar a la deducción proporcional de haberes, que no tendrá carácter sancionador.',null),
('adm-cm:38-36b9be2174','adm-cm',38,'¿Afecta a sus prestaciones sociales la deducción de haberes de quien ejerce el derecho de huelga?','["Solo afecta a los trienios", "Sí, si la huelga dura más de tres días", "Sí, reduce proporcionalmente la pensión", "No, ni tiene carácter de sanción"]'::jsonb,3,'Art. 30.2 TREBEP','La deducción de haberes por huelga no tiene carácter de sanción ni afecta al régimen de sus prestaciones sociales.',null),
('adm-cm:39-cc8af42622','adm-cm',39,'Según el marco conceptual del Plan General de Contabilidad Pública, ¿qué documentos forman las cuentas anuales?','["Balance, estado de liquidación del presupuesto, cuenta general de la comunidad autónoma, memoria de gestión del ejercicio, inventario de bienes y estado de la deuda", "Balance de sumas y saldos, libro diario y memoria", "Balance, cuenta del resultado económico patrimonial, estado de cambios en el patrimonio neto, estado de liquidación del presupuesto, estado de flujos de efectivo y memoria", "Balance, cuenta de pérdidas y ganancias e informe de gestión"]'::jsonb,2,'PGCP, 1.ª parte, 1.º Orden EHA/1037/2010','Las cuentas anuales comprenden el balance, la cuenta del resultado económico patrimonial, el estado de cambios en el patrimonio neto, el de liquidación del presupuesto, el de flujos de efectivo y la memoria.',null),
('adm-cm:39-2c766208fb','adm-cm',39,'Según el PGCP, ¿qué constituye la entidad contable?','["Todo ente con personalidad jurídica y presupuesto propio que deba formar y rendir cuentas", "Toda unidad administrativa que gestione fondos públicos, aunque carezca de personalidad jurídica propia", "Todo órgano administrativo con crédito asignado", "Solo la Administración General de cada comunidad"]'::jsonb,0,'PGCP, 1.ª parte, 1.º Orden EHA/1037/2010','Constituye la entidad contable todo ente con personalidad jurídica y presupuesto propio que deba formar y rendir cuentas.',null),
('adm-cm:39-1fcabaaf3d','adm-cm',39,'En la contabilización de las operaciones según el PGCP, ¿a qué se atenderá?','["Exclusivamente a su forma jurídica", "Al criterio del órgano gestor", "A su incidencia presupuestaria únicamente", "A su realidad económica y no solo a su forma jurídica"]'::jsonb,3,'PGCP, 1.ª parte, 1.º Orden EHA/1037/2010','Se atenderá a la realidad económica de las operaciones y no solo a su forma jurídica.',null),
('adm-cm:39-e1027cf894','adm-cm',39,'¿Cuál de estos es un requisito de la información de las cuentas anuales según el PGCP?','["La exhaustividad presupuestaria", "La comparabilidad", "La confidencialidad", "La inmediatez"]'::jsonb,1,'PGCP, 1.ª parte, 2.º Orden EHA/1037/2010','Los requisitos son claridad, relevancia, fiabilidad y comparabilidad.',null),
('adm-cm:39-9bd19d9fe2','adm-cm',39,'¿Qué principio contable presume que la actividad de la entidad continúa por tiempo indefinido?','["Gestión continuada", "Uniformidad", "Devengo", "Prudencia"]'::jsonb,0,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Por el principio de gestión continuada se presume, salvo prueba en contrario, que la actividad continúa por tiempo indefinido.',null),
('adm-cm:39-ca6906abdf','adm-cm',39,'¿Qué principio exige reconocer las transacciones según la corriente real de bienes y servicios y no según la corriente monetaria?','["Gestión continuada", "Devengo", "Imputación presupuestaria", "No compensación"]'::jsonb,1,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','El principio de devengo exige reconocer las transacciones en función de la corriente real de bienes y servicios.',null),
('adm-cm:39-8cdc395fee','adm-cm',39,'¿Qué principio obliga a mantener en el tiempo el criterio contable adoptado entre las alternativas permitidas?','["Prudencia", "Desafectación", "Importancia relativa", "Uniformidad"]'::jsonb,3,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Por el principio de uniformidad, el criterio adoptado debe mantenerse en el tiempo mientras no se alteren los supuestos de su elección.',null),
('adm-cm:39-acc359cac9','adm-cm',39,'¿Qué principio impide compensar partidas del activo y del pasivo o de gastos e ingresos?','["Devengo", "Uniformidad", "No compensación", "Importancia relativa"]'::jsonb,2,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Por el principio de no compensación no pueden compensarse partidas del activo y pasivo ni de gastos e ingresos, salvo regulación excepcional.',null),
('adm-cm:39-cf1e2e3647','adm-cm',39,'En caso de conflicto entre principios contables, ¿cuál debe prevalecer según el PGCP?','["El que mejor conduzca a que las cuentas expresen la imagen fiel", "Siempre el de devengo", "El que establezca la Intervención General", "Siempre el de prudencia"]'::jsonb,0,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Debe prevalecer el principio que mejor conduzca a que las cuentas anuales expresen la imagen fiel.',null),
('adm-cm:39-2ca1189dca','adm-cm',39,'¿Cuál de estos es un principio contable de carácter presupuestario según el PGCP?','["Gestión continuada", "No compensación", "Desafectación", "Prudencia"]'::jsonb,2,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Los principios presupuestarios destacados son el de imputación presupuestaria y el de desafectación.',null),
('adm-cm:39-13e71e108d','adm-cm',39,'Según el principio de desafectación, ¿cómo se destinan, con carácter general, los ingresos presupuestarios?','["Cada ingreso a un gasto concreto previamente determinado", "A los gastos de la misma consejería que los recauda", "Primero a la deuda y después al resto de gastos", "A financiar la totalidad de los gastos, sin relación directa entre unos y otros"]'::jsonb,3,'PGCP, 1.ª parte, 3.º Orden EHA/1037/2010','Con carácter general, los ingresos presupuestarios financian la totalidad de los gastos sin relación directa entre unos y otros.',null),
('adm-cm:39-bef42e76e6','adm-cm',39,'Según el marco conceptual del PGCP, ¿qué es el patrimonio neto?','["El conjunto de bienes de dominio público", "La parte residual de los activos una vez deducidos todos los pasivos", "El resultado económico patrimonial del ejercicio", "La suma de activos y pasivos de la entidad"]'::jsonb,1,'PGCP, 1.ª parte, 4.º Orden EHA/1037/2010','El patrimonio neto constituye la parte residual de los activos de la entidad, una vez deducidos todos sus pasivos.',null),
('adm-cm:39-7dda6fa9cd','adm-cm',39,'¿Qué son los pasivos según el PGCP?','["Obligaciones futuras derivadas de compromisos aún no firmados que previsiblemente se asumirán el año siguiente", "Las partidas del presupuesto de gastos", "Obligaciones actuales surgidas de sucesos pasados cuya extinción probablemente disminuirá los recursos", "Los bienes y derechos controlados por la entidad"]'::jsonb,2,'PGCP, 1.ª parte, 4.º Orden EHA/1037/2010','Son obligaciones actuales surgidas de sucesos pasados cuya extinción es probable que dé lugar a una disminución de recursos; incluyen las provisiones.',null),
('adm-cm:39-1b6cecbe7d','adm-cm',39,'¿Qué activos son portadores de potencial de servicio según el PGCP?','["Solo los bienes inmuebles de uso administrativo", "Los que generan flujos de efectivo por su venta", "Los que se poseen para obtener un beneficio comercial", "Los que se poseen con una finalidad distinta a la de generar un rendimiento comercial"]'::jsonb,3,'PGCP, 1.ª parte, 4.º Orden EHA/1037/2010','Los activos portadores de potencial de servicio se poseen con una finalidad distinta a la de generar un rendimiento comercial.',null),
('adm-cm:39-084de8cb49','adm-cm',39,'¿Cuándo se reconoce un gasto presupuestario en el estado de liquidación del presupuesto?','["Cuando se autoriza el gasto", "Cuando se dicta el acto de reconocimiento y liquidación de la obligación presupuestaria", "Cuando se aprueba el presupuesto y se consigna el crédito correspondiente en el estado de gastos", "Cuando se paga la obligación"]'::jsonb,1,'PGCP, 1.ª parte, 5.º Orden EHA/1037/2010','Se reconoce cuando se dicta el acto administrativo de reconocimiento y liquidación de la obligación presupuestaria.',null),
('adm-cm:39-db820bdee3','adm-cm',39,'Según el PGCP, ¿qué es el importe recuperable de un activo?','["El mayor entre su valor razonable menos los costes de venta y su valor en uso", "El valor catastral actualizado", "Su precio de adquisición menos la amortización", "El menor entre su valor contable y su valor razonable"]'::jsonb,0,'PGCP, 1.ª parte, 6.º Orden EHA/1037/2010','El importe recuperable es el mayor entre el valor razonable menos los costes de venta y el valor en uso.',null),
('adm-cm:39-671596838e','adm-cm',39,'¿Cómo se determina el valor en uso de los activos portadores de potencial de servicio?','["Por su valor razonable menos costes de venta", "Por el coste de reposición depreciado", "Por su precio de adquisición actualizado con el IPC", "Por el valor actual de sus flujos de efectivo"]'::jsonb,1,'PGCP, 1.ª parte, 6.º Orden EHA/1037/2010','El valor en uso de los activos portadores de potencial de servicio se determina por el coste de reposición depreciado.',null),
('adm-cm:39-069cce3d14','adm-cm',39,'¿Tiene la consideración de valor razonable el resultado de una transacción forzada o urgente?','["No, en ningún caso", "Sí, si la acepta la Intervención", "Solo si se trata de bienes muebles", "Sí, si se formaliza ante notario"]'::jsonb,0,'PGCP, 1.ª parte, 6.º Orden EHA/1037/2010','No tendrá en ningún caso el carácter de valor razonable el que resulte de una transacción forzada, urgente o de una liquidación involuntaria.',null),
('adm-cm:40-7202659c3a','adm-cm',40,'¿Cuántos bytes tiene un kilobyte (KB) en el sistema binario tradicional?','["1.000 bytes", "1.024 bytes", "1.048 bytes", "512 bytes"]'::jsonb,1,'Unidades de información','1 KB = 2^10 bytes = 1.024 bytes. En el sistema internacional, 1 kB = 1.000 bytes (y 1 KiB = 1.024).',null),
('adm-cm:40-2cdfc77b4e','adm-cm',40,'¿Cuántos bits forman un byte?','["8", "10", "16", "4"]'::jsonb,0,'Unidades de información','Un byte permite representar 256 valores distintos.',null),
('adm-cm:40-f276c7bed2','adm-cm',40,'¿Qué unidad de almacenamiento es mayor?','["Un terabyte", "Un kilobyte", "Un megabyte", "Un gigabyte"]'::jsonb,0,'Unidades de información','Orden creciente: kilobyte, megabyte, gigabyte, terabyte, petabyte.',null),
('adm-cm:40-3c70ed2ad7','adm-cm',40,'La memoria RAM se caracteriza por ser:','["Volátil, de lectura y escritura", "No volátil, de lectura y escritura", "Volátil y de solo lectura", "No volátil y de solo lectura"]'::jsonb,0,'Memoria','Su contenido se pierde al apagar el equipo. La ROM es no volátil y, en principio, de solo lectura.',null),
('adm-cm:40-6aeb633448','adm-cm',40,'¿Qué componente del ordenador ejecuta las instrucciones de los programas?','["La tarjeta de red", "La fuente de alimentación", "El procesador o CPU", "El disco duro"]'::jsonb,2,'Hardware','La CPU incluye la unidad de control y la unidad aritmético-lógica.',null),
('adm-cm:40-4b48ea3a5a','adm-cm',40,'¿Qué parte de la CPU realiza las operaciones aritméticas y lógicas?','["La unidad de control del procesador", "La unidad aritmético-lógica (ALU)", "La memoria caché interna del procesador", "El bus de datos y direcciones del sistema"]'::jsonb,1,'Hardware','La unidad de control interpreta las instrucciones y coordina el resto de componentes.',null),
('adm-cm:40-abd600c32f','adm-cm',40,'¿Cuál de los siguientes es un periférico de entrada?','["Los altavoces", "El monitor", "La impresora", "El escáner"]'::jsonb,3,'Periféricos','Impresora, monitor y altavoces son periféricos de salida.',null),
('adm-cm:40-978f59f8fb','adm-cm',40,'Una pantalla táctil es un periférico:','["De almacenamiento", "De entrada y salida", "Exclusivamente de salida", "Exclusivamente de entrada"]'::jsonb,1,'Periféricos','Muestra información y a la vez recibe órdenes del usuario.',null),
('adm-cm:40-a64bad3c85','adm-cm',40,'¿Qué tipo de unidad de almacenamiento no tiene partes mecánicas móviles?','["El SSD", "El disco duro HDD", "El disquete", "La unidad de cinta"]'::jsonb,0,'Almacenamiento','Los SSD usan memoria flash; por eso son más rápidos y resistentes a golpes que los HDD.',null),
('adm-cm:40-5260294ef1','adm-cm',40,'El firmware que inicia el hardware al encender el ordenador y arranca el sistema operativo es, en los equipos actuales:','["La UEFI, sucesora de la BIOS", "El controlador de la tarjeta gráfica", "El gestor de arranque de la memoria RAM", "El sistema de archivos NTFS"]'::jsonb,0,'Arranque del equipo','La BIOS es el firmware tradicional; la UEFI la sustituye en los equipos modernos.',null),
('adm-cm:40-83d479c7be','adm-cm',40,'¿Cuál de los siguientes es un sistema operativo?','["Chrome", "Excel", "Linux", "Java"]'::jsonb,2,'Software','Excel es una aplicación, Chrome un navegador y Java un lenguaje de programación.',null),
('adm-cm:40-bbbfc921f9','adm-cm',40,'El software cuyo código fuente puede estudiarse, modificarse y redistribuirse libremente se denomina:','["Freeware", "Software propietario", "Shareware", "Software libre"]'::jsonb,3,'Tipos de software','El freeware es gratuito pero no necesariamente permite acceder al código ni modificarlo.',null),
('adm-cm:40-d15fce67f6','adm-cm',40,'¿Qué sistema de numeración utiliza internamente el ordenador?','["El octal", "El decimal", "El binario", "El romano"]'::jsonb,2,'Representación de la información','Solo usa los dígitos 0 y 1.',null),
('adm-cm:40-94422f0671','adm-cm',40,'El número decimal 10 se representa en binario como:','["1100", "1010", "0110", "1001"]'::jsonb,1,'Representación de la información','1010 = 8 + 0 + 2 + 0 = 10.',null),
('adm-cm:40-27986409b5','adm-cm',40,'Una red que conecta los ordenadores de un mismo edificio u oficina se denomina:','["VPN", "MAN", "WAN", "LAN"]'::jsonb,3,'Redes','LAN es red de área local; WAN, de área extensa; MAN, metropolitana; VPN, red privada virtual.',null),
('adm-cm:40-59b0b0da10','adm-cm',40,'¿Qué tipo de puerto se usa habitualmente para conectar un monitor con audio y vídeo digital?','["VGA", "RJ-45", "PS/2", "HDMI"]'::jsonb,3,'Puertos','El RJ-45 se usa para la red, el PS/2 para teclados y ratones antiguos, y el VGA transmite solo vídeo analógico.',null),
('adm-cm:40-2f10b08edc','adm-cm',40,'El malware que cifra los archivos del usuario y pide un rescate para recuperarlos se llama:','["Ransomware", "Spyware", "Gusano", "Adware"]'::jsonb,0,'Seguridad','El spyware espía la actividad del usuario y el adware muestra publicidad no deseada.',null),
('adm-cm:40-13ab6cd066','adm-cm',40,'Un troyano es:','["Un programa malicioso que se presenta como legítimo para que el usuario lo instale", "Un programa que se replica por sí solo a través de la red sin intervención del usuario", "Un programa que muestra publicidad emergente", "Un correo que suplanta a una entidad para robar contraseñas"]'::jsonb,0,'Seguridad','El gusano se replica solo; la suplantación por correo es phishing; la publicidad emergente, adware.',null),
('adm-cm:40-936615f1f0','adm-cm',40,'El phishing consiste en:','["Infectar un equipo a través de una memoria USB que ejecuta automáticamente un programa", "Bloquear un servidor saturándolo con miles de peticiones simultáneas desde muchos equipos", "Suplantar la identidad de una entidad de confianza para obtener datos confidenciales", "Instalar en secreto un programa que registra todas las pulsaciones del teclado del usuario"]'::jsonb,2,'Seguridad','Bloquear un servidor con peticiones masivas es un ataque de denegación de servicio (DoS); registrar pulsaciones, un keylogger.',null),
('adm-cm:40-4291a0991c','adm-cm',40,'Una copia de seguridad incremental guarda:','["Solo los archivos modificados desde la última copia completa, sin tener en cuenta las demás", "Todos los archivos del equipo cada vez", "Solo los archivos modificados desde la última copia, sea completa o incremental", "Únicamente los archivos del sistema operativo"]'::jsonb,2,'Copias de seguridad','La copia diferencial guarda los cambios desde la última copia completa.',null),
('adm-cm:40-00b44b2f8a','adm-cm',40,'La memoria caché es:','["Una memoria de solo lectura que contiene la BIOS", "Un espacio del disco duro que el sistema operativo utiliza como memoria cuando la RAM se llena", "Una memoria muy rápida y pequeña que guarda los datos que el procesador usa con más frecuencia", "La memoria secundaria, como el disco duro o el SSD, donde se instalan los programas y se guardan los archivos"]'::jsonb,2,'Memoria','El espacio en disco usado cuando la RAM se llena es la memoria virtual o archivo de paginación.',null),
('adm-cm:40-1529d23754','adm-cm',40,'¿Qué es un controlador o driver?','["Una aplicación del sistema operativo para crear y restaurar copias de seguridad de los archivos", "El usuario con permisos de administrador que puede instalar y desinstalar programas en el equipo", "Un componente físico de la placa base que conecta el procesador con el resto de dispositivos", "Un programa que permite al sistema operativo comunicarse con un dispositivo de hardware"]'::jsonb,3,'Software','Cada dispositivo necesita su controlador para funcionar correctamente.',null),
('adm-cm:40-7d0fcb6d79','adm-cm',40,'La computación en la nube (cloud computing) consiste en:','["Conectar varios ordenadores de una misma oficina en una red local sin cables mediante tecnología wifi", "Guardar archivos en una memoria USB externa", "Usar recursos informáticos, como almacenamiento o aplicaciones, ofrecidos a través de internet", "Instalar programas solo desde un CD o DVD"]'::jsonb,2,'Cloud computing','Ejemplos: OneDrive, Google Drive o Microsoft 365.',null),
('adm-cm:40-22290331f6','adm-cm',40,'¿Qué significan las siglas SaaS en la computación en la nube?','["Servidor de aplicaciones en red", "Seguridad como servicio", "Sistema de almacenamiento seguro", "Software como servicio"]'::jsonb,3,'Cloud computing','Junto a SaaS están IaaS (infraestructura como servicio) y PaaS (plataforma como servicio).',null),
('adm-cm:40-1490c87c58','adm-cm',40,'¿Cuántos bits forman un nibble o cuarteto?','["2", "4", "16", "8"]'::jsonb,1,'Unidades de información','Un nibble son 4 bits, la mitad de un byte.',null),
('adm-cm:40-b50afb37a3','adm-cm',40,'En el sistema binario tradicional, un gigabyte equivale a:','["1.024 megabytes", "1.000 megabytes", "2.048 megabytes", "512 megabytes"]'::jsonb,0,'Unidades de información','Cada unidad es 1.024 veces la anterior: 1 GB = 1.024 MB.',null),
('adm-cm:40-916444c7e7','adm-cm',40,'El número binario 1111 equivale en decimal a:','["11", "15", "14", "16"]'::jsonb,1,'Representación de la información','8 + 4 + 2 + 1 = 15.',null),
('adm-cm:40-6ab5e04fc8','adm-cm',40,'¿Qué sistema de numeración utiliza los dígitos del 0 al 9 y las letras de la A a la F?','["El hexadecimal", "El binario", "El octal", "El decimal"]'::jsonb,0,'Representación de la información','El sistema hexadecimal tiene base 16: 0-9 y A-F.',null),
('adm-cm:40-92e653e1aa','adm-cm',40,'La memoria ROM se caracteriza por ser:','["Volátil y de solo lectura", "No volátil y, en principio, de solo lectura", "Volátil y de lectura y escritura", "Una memoria de almacenamiento masivo externa"]'::jsonb,1,'Memoria','La ROM conserva los datos sin corriente y está pensada para leerse, no para escribirse en el uso normal.',null),
('adm-cm:40-ddb6f8af2e','adm-cm',40,'¿Qué componente conecta todos los elementos internos del ordenador y permite que se comuniquen?','["La placa base", "El disipador", "La fuente de alimentación", "La tarjeta gráfica"]'::jsonb,0,'Hardware','La placa base aloja y comunica el procesador, la memoria y el resto de componentes.',null),
('adm-cm:40-9772830649','adm-cm',40,'La GPU de un ordenador es:','["La unidad principal de almacenamiento", "El procesador especializado en gráficos", "El controlador de la red inalámbrica", "La memoria intermedia del disco duro"]'::jsonb,1,'Hardware','La GPU (unidad de procesamiento gráfico) se encarga de calcular y mostrar las imágenes.',null),
('adm-cm:40-130ced6056','adm-cm',40,'¿Cuál de los siguientes es un periférico de salida?','["El micrófono", "El lector de códigos de barras", "La impresora", "El ratón"]'::jsonb,2,'Periféricos','La impresora saca información del ordenador; los otros tres la introducen.',null),
('adm-cm:40-8b0dd827b2','adm-cm',40,'Un disco duro tradicional (HDD) guarda la información:','["En platos magnéticos que giran", "En chips de memoria flash", "En la memoria RAM del equipo", "En discos ópticos grabados con láser"]'::jsonb,0,'Almacenamiento','El HDD usa platos magnéticos y un cabezal móvil; el SSD usa memoria flash sin partes móviles.',null),
('adm-cm:40-740962317a','adm-cm',40,'Un procesador de textos es un ejemplo de:','["Controlador de dispositivo", "Software de aplicación", "Firmware", "Software de sistema"]'::jsonb,1,'Tipos de software','Los programas para tareas del usuario (textos, hojas de cálculo) son software de aplicación.',null),
('adm-cm:40-60ca95cf6a','adm-cm',40,'En la computación en la nube, IaaS significa:','["Integración como servicio", "Internet como servicio", "Infraestructura como servicio", "Información como servicio"]'::jsonb,2,'Cloud computing','IaaS ofrece servidores, almacenamiento y redes virtuales como servicio.',null),
('adm-cm:40-6065490d5a','adm-cm',40,'Un gusano informático se caracteriza por:','["Propagarse por sí mismo a otros equipos a través de la red", "Cifrar los archivos del usuario y pedir un rescate económico para liberarlos", "Mostrar publicidad no deseada en el navegador", "Registrar las teclas que pulsa el usuario"]'::jsonb,0,'Seguridad','El gusano se replica solo; el ransomware cifra, el adware muestra anuncios y el keylogger registra pulsaciones.',null),
('adm-cm:40-cff4eefa02','adm-cm',40,'Una copia de seguridad diferencial guarda:','["Los archivos modificados desde la última copia de cualquier tipo", "Solo los archivos creados ese mismo día", "Todos los archivos del equipo cada vez", "Los archivos modificados desde la última copia completa"]'::jsonb,3,'Copias de seguridad','La diferencial toma como referencia la última copia completa; la incremental, la última copia de cualquier tipo.',null),
('adm-cm:40-f409a95b55','adm-cm',40,'La verificación en dos pasos consiste en:','["Iniciar sesión a la vez desde dos dispositivos", "Usar dos contraseñas distintas, una para el usuario y otra para el equipo, en cada acceso", "Cambiar la contraseña cada dos meses", "Pedir, además de la contraseña, un segundo factor, como un código en el móvil"]'::jsonb,3,'Seguridad','Combina algo que sabes (contraseña) con algo que tienes (móvil, llave) o que eres (huella).',null),
('adm-cm:40-32985bce1a','adm-cm',40,'Una red que abarca una zona geográfica amplia, como un país, se denomina:','["WAN", "PAN", "WLAN", "LAN"]'::jsonb,0,'Redes','WAN es red de área amplia; LAN, local; PAN, personal; WLAN, local inalámbrica.',null),
('adm-cm:40-07c723aed2','adm-cm',40,'¿Qué protocolo se usa para transferir páginas web de forma cifrada?','["SMTP", "HTTPS", "HTTP", "FTP"]'::jsonb,1,'Protocolos de internet','HTTPS es HTTP sobre una conexión cifrada con TLS. FTP transfiere archivos y SMTP envía correo.',null),
('adm-cm:40-80f100689e','adm-cm',40,'¿Qué función cumple el sistema DNS en internet?','["Asignar una dirección de correo a cada usuario", "Traducir los nombres de dominio en direcciones IP", "Bloquear el acceso a páginas peligrosas", "Cifrar las comunicaciones entre el navegador y el servidor"]'::jsonb,1,'DNS','Gracias al DNS escribimos «boe.es» en lugar de la dirección IP del servidor.',null),
('adm-cm:40-c92959ffef','adm-cm',40,'En la dirección https://www.boe.es/diario_boe/, ¿cuál es el dominio de primer nivel?','["boe", "diario_boe", ".es", "www"]'::jsonb,2,'Dominios','El dominio de primer nivel es la última parte del nombre: .es, .com, .org, etc.',null),
('adm-cm:40-5183c7f897','adm-cm',40,'¿Qué protocolo se utiliza para enviar correo electrónico?','["HTTP", "POP3", "SMTP", "IMAP"]'::jsonb,2,'Correo electrónico','POP3 e IMAP se usan para recibir o consultar el correo.',null),
('adm-cm:40-e3dcabf7de','adm-cm',40,'¿Quién creó la World Wide Web?','["Bill Gates, en la empresa Microsoft", "Tim Berners-Lee, en el CERN", "Linus Torvalds, en la Universidad de Helsinki", "Vinton Cerf, en el proyecto ARPANET"]'::jsonb,1,'Historia de internet','La propuso en 1989 y desarrolló el primer navegador y servidor web.',null),
('adm-cm:40-341866bae8','adm-cm',40,'El lenguaje de marcado con el que se escriben las páginas web es:','["HTML", "XML", "CSS", "SQL"]'::jsonb,0,'Lenguajes web','CSS se usa para el diseño o estilo, SQL para bases de datos y XML para intercambio de datos.',null),
('adm-cm:40-91904ce258','adm-cm',40,'Una cookie es:','["Un programa malicioso que se instala en el equipo al visitar determinadas páginas web sin que el usuario lo sepa", "Un pequeño archivo que el sitio web guarda en el navegador del usuario para recordar información", "Un buscador alternativo a Google", "Un certificado digital que acredita que la web es segura y que pertenece a la organización que dice ser"]'::jsonb,1,'Navegación','Sirve, por ejemplo, para recordar el idioma, la sesión iniciada o el carrito de compra.',null),
('adm-cm:40-266ddb4f8a','adm-cm',40,'La navegación InPrivate o de incógnito:','["Impide que el proveedor de internet vea las páginas visitadas", "No guarda en el equipo el historial, las cookies ni los datos de formularios al cerrar la ventana", "Oculta la dirección IP del usuario a todos los sitios web que visita, de modo que navega de forma anónima", "Protege el equipo frente a cualquier virus"]'::jsonb,1,'Navegación privada','No hace al usuario anónimo frente a los sitios web, su empresa o su proveedor de internet.',null),
('adm-cm:40-b263a0333e','adm-cm',40,'En Microsoft Edge, ¿qué combinación abre una nueva ventana InPrivate?','["Ctrl + Mayús + I", "Ctrl + Mayús + P", "Ctrl + Mayús + N", "Ctrl + N"]'::jsonb,2,'Atajos del navegador','En Firefox, la ventana privada se abre con Ctrl + Mayús + P.',null),
('adm-cm:40-f47670038e','adm-cm',40,'En los navegadores, Ctrl + Mayús + T sirve para:','["Traducir la página al idioma configurado en el navegador", "Cerrar todas las pestañas abiertas salvo la actual", "Abrir una nueva pestaña en blanco junto a la actual", "Volver a abrir la última pestaña cerrada"]'::jsonb,3,'Atajos del navegador','Ctrl + T abre una pestaña nueva y Ctrl + W cierra la actual.',null),
('adm-cm:40-12cb63d7a9','adm-cm',40,'¿Qué combinación de teclas añade la página actual a Favoritos o Marcadores?','["Ctrl + D", "Ctrl + B", "Ctrl + F", "Ctrl + H"]'::jsonb,0,'Atajos del navegador','Ctrl + F busca en la página y Ctrl + H abre el historial.',null),
('adm-cm:40-09d98b1aed','adm-cm',40,'En los navegadores, Ctrl + J abre:','["Las descargas", "Los favoritos", "El historial", "Una pestaña nueva"]'::jsonb,0,'Atajos del navegador','Ctrl + H abre el historial.',null),
('adm-cm:40-4465a91f37','adm-cm',40,'La tecla F5 en un navegador sirve para:','["Actualizar o recargar la página", "Ir a la página de inicio configurada en el navegador", "Activar o desactivar el modo de pantalla completa", "Imprimir la página o guardarla como PDF"]'::jsonb,0,'Atajos del navegador','F11 activa la pantalla completa.',null),
('adm-cm:40-840dc631c4','adm-cm',40,'Una intranet es:','["La parte de internet que solo puede visitarse con navegadores especiales y que no aparece indexada en los buscadores", "Una red que conecta varias organizaciones entre sí a través de satélites", "Una red privada de una organización que usa las tecnologías de internet y solo es accesible para sus miembros", "Una red pública mundial accesible para cualquier persona"]'::jsonb,2,'Redes','Si se abre a usuarios externos autorizados (proveedores, clientes), se habla de extranet.',null),
('adm-cm:40-39fcc90de4','adm-cm',40,'¿Qué es una dirección IP?','["El nombre de dominio con el que se identifica una página web en internet", "La contraseña que protege el acceso a la red wifi de una casa u oficina", "Un número que identifica a un dispositivo dentro de una red", "El código de un certificado digital"]'::jsonb,2,'Direccionamiento','Existen direcciones IPv4 (32 bits) e IPv6 (128 bits).',null),
('adm-cm:40-4690cc0d7e','adm-cm',40,'¿Cuántos bits tiene una dirección IPv6?','["256", "128", "64", "32"]'::jsonb,1,'Direccionamiento','Las direcciones IPv4 tienen 32 bits.',null),
('adm-cm:40-e3bb5f82aa','adm-cm',40,'La URL es:','["El nombre del programa que se usa para navegar por internet", "El protocolo de cifrado que utilizan las páginas web seguras", "La dirección que identifica un recurso en internet", "El servidor físico en el que se aloja una página web"]'::jsonb,2,'Navegación','Por ejemplo, https://administracion.gob.es.',null),
('adm-cm:40-0dcae52c2b','adm-cm',40,'¿Qué indica el candado que aparece junto a la dirección en el navegador?','["Que la conexión con el sitio está cifrada", "Que el sitio es oficial y no puede ser fraudulento", "Que la web está bloqueada", "Que la página no usa cookies"]'::jsonb,0,'Seguridad','Una web fraudulenta también puede tener conexión cifrada; el candado no garantiza que sea legítima.',null),
('adm-cm:40-f3695db272','adm-cm',40,'Un motor de búsqueda o buscador es:','["La aplicación que muestra las páginas web en pantalla", "Un programa para descargar archivos de forma más rápida", "Un sistema que localiza páginas web según las palabras clave que introduce el usuario", "Un servidor que asigna los nombres de dominio a las organizaciones que los solicitan y pagan por ellos"]'::jsonb,2,'Buscadores','La aplicación que muestra las páginas es el navegador.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:40-beef377c0e','adm-cm',40,'En la mayoría de buscadores, escribir una frase entre comillas sirve para:','["Excluir esas palabras de la búsqueda", "Buscar exactamente esa frase", "Buscar sinónimos", "Buscar solo imágenes"]'::jsonb,1,'Buscadores','El signo menos delante de una palabra la excluye de los resultados.',null),
('adm-cm:40-56479b523d','adm-cm',40,'El protocolo FTP se usa para:','["Cifrar las páginas web que contienen datos personales", "Enviar mensajes de correo electrónico a otros usuarios", "Transferir archivos entre equipos", "Resolver los nombres de dominio en direcciones IP"]'::jsonb,2,'Protocolos de internet','Existe una versión segura llamada SFTP o FTPS.',null),
('adm-cm:40-81563429f8','adm-cm',40,'¿Qué es la caché del navegador?','["La lista de contraseñas y datos de inicio de sesión que el usuario ha decidido guardar en el navegador", "La carpeta del disco duro en la que se guardan por defecto todos los archivos descargados de internet", "Un almacenamiento temporal de elementos de las páginas visitadas para cargarlas más rápido", "El registro de las páginas marcadas como favoritas"]'::jsonb,2,'Navegación','Borrar la caché puede resolver problemas de visualización de algunas páginas.',null),
('adm-cm:40-a7c19de8d1','adm-cm',40,'¿Qué es un navegador web?','["Una red privada virtual", "Un servidor que almacena páginas web y las envía a los usuarios que las solicitan", "Un protocolo de transferencia de archivos", "Una aplicación que permite acceder a las páginas web y visualizarlas"]'::jsonb,3,'Navegadores','Ejemplos: Microsoft Edge, Google Chrome, Mozilla Firefox o Safari.',null),
('adm-cm:40-1b763140d4','adm-cm',40,'¿Qué es una VPN?','["Un servidor de correo electrónico seguro", "Una red privada virtual que crea una conexión cifrada a través de internet", "Un tipo de virus que se propaga por la red infectando los equipos conectados a ella", "Un navegador especial que deben usar los empleados públicos para acceder a la sede"]'::jsonb,1,'Redes','Permite, por ejemplo, teletrabajar accediendo a la red interna de la organización.',null),
('adm-cm:40-725432b36f','adm-cm',40,'¿Qué protocolo permite leer el correo manteniendo los mensajes sincronizados en el servidor?','["FTP", "SMTP", "IMAP", "POP3"]'::jsonb,2,'Correo electrónico','IMAP sincroniza con el servidor; POP3 descarga los mensajes y SMTP sirve para enviar.',null),
('adm-cm:40-232d50e5b1','adm-cm',40,'¿Cuántos bits tiene una dirección IPv4?','["64", "128", "32", "16"]'::jsonb,2,'Direccionamiento','IPv4 usa 32 bits (cuatro números de 0 a 255); IPv6, 128.',null),
('adm-cm:40-335c621b91','adm-cm',40,'¿Cuál de estos es un dominio de primer nivel genérico?','[".fr", ".es", ".org", ".mx"]'::jsonb,2,'Dominios','.org es genérico; .es, .fr y .mx son dominios territoriales de países.',null),
('adm-cm:40-13dd4b0819','adm-cm',40,'¿Qué puerto usa por defecto el protocolo HTTPS?','["21", "443", "25", "80"]'::jsonb,1,'Protocolos de internet','HTTPS usa el 443; HTTP, el 80; FTP, el 21, y SMTP, el 25.',null),
('adm-cm:40-66a0f349a1','adm-cm',40,'En un correo electrónico, los destinatarios añadidos en CCO:','["Pueden modificar el mensaje antes de leerlo", "Reciben el mensaje solo si lo abre el destinatario principal", "Reciben una copia sin los archivos adjuntos", "No son visibles para el resto de destinatarios"]'::jsonb,3,'Correo electrónico','CCO (copia oculta) envía el mensaje sin mostrar esas direcciones a los demás.',null),
('adm-cm:40-1417587f04','adm-cm',40,'Un router es un dispositivo que:','["Almacena las páginas web que se visitan", "Traduce los nombres de dominio de las páginas a sus direcciones IP numéricas", "Protege el equipo frente a los virus", "Conecta redes distintas y encamina los paquetes de datos entre ellas"]'::jsonb,3,'Redes','El router interconecta redes (por ejemplo, la de casa con internet) y decide por dónde enviar los datos.',null),
('adm-cm:40-f096487b2d','adm-cm',40,'¿Qué entidad pública gestiona el registro de los dominios .es?','["El Ministerio de Hacienda", "Red.es", "El Instituto Nacional de Ciberseguridad", "La ICANN directamente"]'::jsonb,1,'Dominios','El registro de nombres de dominio bajo .es lo gestiona la entidad pública Red.es.',null),
('adm-cm:40-d354cab4aa','adm-cm',40,'¿Cuál de los siguientes NO es un navegador web?','["Outlook", "Mozilla Firefox", "Microsoft Edge", "Google Chrome"]'::jsonb,0,'Navegadores','Outlook es un gestor de correo y calendario; los otros tres son navegadores.',null),
('adm-cm:40-756fe36fc9','adm-cm',40,'En los navegadores, Ctrl + T sirve para:','["Volver a abrir la última pestaña cerrada", "Abrir una pestaña nueva", "Cerrar la pestaña actual", "Abrir una ventana privada"]'::jsonb,1,'Atajos del navegador','Ctrl + T abre una pestaña; Ctrl + W la cierra y Ctrl + Mayús + T reabre la última cerrada.',null),
('adm-cm:40-fa76334d87','adm-cm',40,'En los navegadores, Ctrl + W sirve para:','["Guardar la página", "Abrir el historial", "Cerrar la pestaña actual", "Abrir una pestaña nueva"]'::jsonb,2,'Atajos del navegador','Ctrl + W cierra la pestaña activa.',null),
('adm-cm:40-c54e16b9dd','adm-cm',40,'El ancho de banda de una conexión indica:','["La distancia máxima entre el equipo y el router", "La cantidad de datos que puede transmitir por unidad de tiempo", "El número de dispositivos que se pueden conectar", "El tiempo que tarda en cargar por completo una página web concreta"]'::jsonb,1,'Redes','Se mide en bits por segundo (Mbps, Gbps).',null),
('adm-cm:40-4b43009330','adm-cm',40,'Un hipervínculo es:','["Un archivo temporal del navegador", "Un elemento que, al pulsarlo, lleva a otra página o recurso", "Un tipo de dirección IP", "Un programa del navegador que bloquea las ventanas emergentes publicitarias"]'::jsonb,1,'Navegación','Los hipervínculos o enlaces conectan páginas y recursos en la web.',null),
('adm-cm:41-4ff58ecb65','adm-cm',41,'En Windows 11, ¿qué combinación de teclas muestra u oculta el escritorio?','["Windows + L", "Windows + D", "Windows + M + Mayús", "Windows + E"]'::jsonb,1,'Atajos de Windows','Windows + E abre el Explorador de archivos y Windows + L bloquea el equipo.',null),
('adm-cm:41-409a2e2c1e','adm-cm',41,'En Windows 11, la combinación Windows + L sirve para:','["Abrir el Explorador de archivos", "Cerrar la sesión y apagar el equipo", "Bloquear el equipo", "Abrir la configuración de idioma"]'::jsonb,2,'Atajos de Windows','Para volver a entrar hay que identificarse (contraseña, PIN o Windows Hello).',null),
('adm-cm:41-44b382f58e','adm-cm',41,'¿Qué combinación de teclas abre el historial del portapapeles en Windows 11?','["Windows + V", "Ctrl + V", "Ctrl + Mayús + V", "Windows + C"]'::jsonb,0,'Atajos de Windows','Ctrl + V pega el último elemento copiado. El historial debe estar activado en Configuración.',null),
('adm-cm:41-2d6af7ca93','adm-cm',41,'En Windows 11, Windows + Mayús + S permite:','["Abrir el menú de apagado, reinicio y suspensión del sistema operativo", "Capturar una parte de la pantalla con la herramienta Recortes", "Cambiar entre los distintos escritorios virtuales creados por el usuario", "Guardar el documento que está abierto con otro nombre o en otra carpeta"]'::jsonb,1,'Atajos de Windows','La captura se copia en el portapapeles y puede editarse en Recortes.',null),
('adm-cm:41-7410e0b814','adm-cm',41,'¿Qué combinación abre directamente el Administrador de tareas?','["Windows + Ctrl + Esc", "Ctrl + Mayús + Esc", "Windows + Tab", "Alt + F4"]'::jsonb,1,'Atajos de Windows','Ctrl + Alt + Supr muestra una pantalla desde la que también puede abrirse.',null),
('adm-cm:41-9c129f8dcb','adm-cm',41,'En Windows 11, la combinación Windows + Tab abre:','["El menú Inicio con las aplicaciones ancladas y los archivos recomendados recientemente", "El centro de notificaciones", "El cuadro Ejecutar para escribir el nombre de un programa, carpeta o comando", "La vista de tareas, con las ventanas abiertas y los escritorios virtuales"]'::jsonb,3,'Atajos de Windows','Alt + Tab permite cambiar rápidamente entre ventanas abiertas.',null),
('adm-cm:41-2788971d44','adm-cm',41,'En Windows 11, la combinación Windows + I abre:','["Configuración", "El Explorador de archivos", "El Panel de control", "La búsqueda de Windows"]'::jsonb,0,'Atajos de Windows','La aplicación Configuración sustituye progresivamente al Panel de control.',null),
('adm-cm:41-339eed0dc9','adm-cm',41,'¿Qué combinación de teclas abre el cuadro de diálogo Ejecutar?','["Windows + E", "Ctrl + R", "Windows + R", "Alt + R"]'::jsonb,2,'Atajos de Windows','Permite abrir programas, carpetas o comandos escribiendo su nombre, por ejemplo «cmd».',null),
('adm-cm:41-645f3d54be','adm-cm',41,'Al eliminar un archivo del disco duro con Mayús + Supr en Windows:','["Se oculta al usuario, pero sigue ocupando espacio en la misma carpeta del disco", "Se envía a la Papelera de reciclaje, igual que si se pulsara solo la tecla Supr", "Se mueve a la carpeta Documentos", "Se elimina de forma permanente, sin pasar por la Papelera de reciclaje"]'::jsonb,3,'Papelera de reciclaje','Normalmente Windows pide confirmación antes de eliminarlo definitivamente.',null),
('adm-cm:41-4dd33da07a','adm-cm',41,'¿Qué es Copilot en Windows 11?','["El antivirus que viene integrado en el sistema operativo Windows", "Una herramienta para hacer copias de seguridad de los archivos en la nube", "El gestor de contraseñas integrado en el navegador Microsoft Edge", "Un asistente de inteligencia artificial de Microsoft"]'::jsonb,3,'Copilot','Permite hacer preguntas, redactar textos o resumir contenidos en lenguaje natural. Algunos teclados recientes incluyen una tecla Copilot.',null),
('adm-cm:41-68a8c17f64','adm-cm',41,'¿Qué antivirus incluye Windows 11 de forma integrada?','["BitLocker", "Windows Hello", "Microsoft Defender", "OneDrive"]'::jsonb,2,'Seguridad de Windows','Windows Hello sirve para iniciar sesión con rostro, huella o PIN; BitLocker cifra unidades y OneDrive es almacenamiento en la nube.',null),
('adm-cm:41-6e5207130f','adm-cm',41,'BitLocker es una función de Windows que sirve para:','["Limitar el tiempo que cada usuario puede usar los programas del equipo", "Cifrar unidades de disco para proteger los datos", "Comprimir carpetas y archivos en formato ZIP para que ocupen menos", "Bloquear las ventanas emergentes que abren las páginas web en el navegador"]'::jsonb,1,'Seguridad de Windows','Si se pierde el equipo, los datos no pueden leerse sin la clave.',null),
('adm-cm:41-838c963031','adm-cm',41,'Windows Hello permite:','["Traducir automáticamente al español el texto que aparece en la pantalla", "Iniciar sesión con reconocimiento facial, huella dactilar o PIN", "Saludar al usuario con un mensaje de voz al arrancar", "Hacer videollamadas con otros usuarios de Windows a través de la cámara del equipo"]'::jsonb,1,'Inicio de sesión','Es una alternativa más segura y cómoda a la contraseña.',null),
('adm-cm:41-fc55779ddf','adm-cm',41,'¿Qué función de Windows 11 permite organizar las ventanas en distintas disposiciones de la pantalla al pasar el ratón por el botón Maximizar?','["Los escritorios virtuales de la vista de tareas", "La vista de tareas con todas las ventanas abiertas", "Los diseños de ajuste (Snap layouts)", "El modo tableta para pantallas táctiles"]'::jsonb,2,'Ventanas','También pueden abrirse con Windows + Z.',null),
('adm-cm:41-29719ddad5','adm-cm',41,'¿Qué ocurre con un archivo eliminado de una memoria USB en Windows?','["Se mueve a una carpeta oculta de la propia memoria", "Se elimina definitivamente, porque las unidades extraíbles no usan la Papelera de reciclaje", "Se guarda una copia en OneDrive", "Se envía a la Papelera de reciclaje del ordenador, desde donde puede restaurarse en cualquier momento"]'::jsonb,1,'Papelera de reciclaje','Por eso conviene tener cuidado al borrar archivos de unidades extraíbles.',null),
('adm-cm:41-4dc77e6cc3','adm-cm',41,'¿Qué sistema de archivos no admite archivos individuales mayores de 4 GB?','["exFAT", "FAT32", "ReFS", "NTFS"]'::jsonb,1,'Sistemas de archivos','NTFS es el sistema de archivos habitual de Windows; exFAT es frecuente en memorias USB y tarjetas.',null),
('adm-cm:41-a21cfbdb91','adm-cm',41,'El Control de cuentas de usuario (UAC) de Windows:','["Pide confirmación antes de realizar cambios que requieren permisos de administrador", "Registra las horas de conexión y desconexión de cada usuario para controlar su jornada", "Limita el número máximo de cuentas de usuario que pueden crearse en un mismo equipo", "Elimina las cuentas que no se usan en treinta días"]'::jsonb,0,'Cuentas de usuario','Ayuda a evitar que programas maliciosos hagan cambios sin que el usuario lo sepa.',null),
('adm-cm:41-8be3eeed8d','adm-cm',41,'¿En qué se diferencia la hibernación de la suspensión en Windows?','["La suspensión apaga por completo el equipo y la hibernación solo apaga la pantalla", "La hibernación guarda la sesión en el disco y apaga el equipo; la suspensión la mantiene en la memoria con un consumo mínimo", "La hibernación cierra todos los programas sin guardar los cambios; la suspensión los guarda automáticamente en el disco duro del equipo", "No hay ninguna diferencia, son dos nombres de la misma función"]'::jsonb,1,'Opciones de energía','Por eso la reanudación desde la suspensión es más rápida.',null),
('adm-cm:41-3fac0a6a4f','adm-cm',41,'¿Qué combinación abre el menú de vínculo rápido (clic derecho del botón Inicio) en Windows 11?','["Windows + X", "Windows + Q", "Alt + Inicio", "Ctrl + X"]'::jsonb,0,'Atajos de Windows','Da acceso a herramientas como el Administrador de dispositivos, la Administración de discos o Terminal.',null),
('adm-cm:41-ee854daeed','adm-cm',41,'La tecla Windows + Impr Pant en Windows 11:','["Imprime directamente la pantalla completa en la impresora que esté configurada como predeterminada", "Abre el cuadro de diálogo de impresión del programa activo", "Captura la pantalla completa y la guarda como imagen en la carpeta Capturas de pantalla", "Copia solo la ventana activa en el portapapeles"]'::jsonb,2,'Capturas de pantalla','La carpeta Capturas de pantalla está dentro de Imágenes. Alt + Impr Pant copia solo la ventana activa.',null),
