('adm-cm:43-20384edf46','adm-cm',43,'Para que una tabla de Word repita la fila de encabezado en cada página, se usa la opción:','["Autoajustar", "Dividir tabla por páginas", "Combinar celdas", "Repetir filas de título"]'::jsonb,3,'Word · Tablas','Se encuentra en Disposición de tabla.',null),
('adm-cm:43-f2dea64bd0','adm-cm',43,'El Control de cambios de Word se activa desde la pestaña:','["Vista", "Inicio", "Insertar", "Revisar"]'::jsonb,3,'Word · Revisar','Registra inserciones, eliminaciones y cambios de formato para aceptarlos o rechazarlos.',null),
('adm-cm:43-5453099872','adm-cm',43,'En Word, la tecla F7 abre:','["La vista previa de impresión y la configuración de página", "El cuadro Guardar como", "La revisión de ortografía y gramática (panel Editor)", "El cuadro Buscar"]'::jsonb,2,'Word · Revisar','Es un atajo independiente del idioma.',null),
('adm-cm:43-71010067ea','adm-cm',43,'Las notas al pie se insertan en Word desde la pestaña:','["Insertar > Nota", "Diseño", "Revisar", "Referencias"]'::jsonb,3,'Word · Referencias','También desde ahí se insertan notas al final, citas y bibliografía.',null),
('adm-cm:43-5c7add2b43','adm-cm',43,'En Word, la tecla F4 sirve para:','["Cerrar el documento activo", "Abrir el cuadro de diálogo Guardar como", "Repetir la última acción", "Insertar la fecha actual"]'::jsonb,2,'Word · Edición','Ctrl+Y también rehace o repite.',null),
('adm-cm:43-018b8a35ab','adm-cm',43,'En la combinación de correspondencia, el documento que contiene el texto común y los campos de combinación se llama:','["Origen de datos", "Documento principal", "Plantilla de correo", "Documento maestro de esquema"]'::jsonb,1,'Word · Correspondencia','El origen de datos contiene la lista de destinatarios (por ejemplo, una hoja de Excel).',null),
('adm-cm:43-495103625d','adm-cm',43,'El botón Mostrar todo (¶) de Word sirve para:','["Mostrar los comentarios y los cambios registrados", "Ver las marcas de párrafo y otros símbolos de formato ocultos", "Mostrar las fuentes instaladas", "Mostrar todas las páginas del documento a la vez en miniatura"]'::jsonb,1,'Word · Inicio','Las marcas ocultas no se imprimen.',null),
('adm-cm:43-25b125b61b','adm-cm',43,'Para que encabezados y pies de página distintos se apliquen a partes diferentes del documento, se insertan:','["Saltos de sección", "Saltos de página", "Marcadores", "Saltos de línea"]'::jsonb,0,'Word · Disposición','Cada sección puede tener su propia orientación, márgenes y encabezados.','feb. 2025 · 2.º ejercicio'),
('adm-cm:43-2c6e8fb486','adm-cm',43,'La opción de Word que compara dos versiones de un documento y muestra sus diferencias está en:','["Insertar > Objeto", "Inicio > Buscar", "Revisar > Comparar", "Vista > Dividir"]'::jsonb,2,'Word · Revisar','Genera un documento con las diferencias como cambios marcados.',null),
('adm-cm:43-28b0fbf71e','adm-cm',43,'En Word, la vista Esquema es especialmente útil para:','["Revisar la ortografía y la gramática del documento", "Organizar la estructura del documento por niveles de título", "Ver la página como se mostraría en un navegador web, sin saltos de página", "Imprimir etiquetas y sobres con los datos de una lista de contactos"]'::jsonb,1,'Word · Vista','Permite subir y bajar niveles y mover bloques.',null),
('adm-cm:43-c5fe23561f','adm-cm',43,'¿En qué pestaña de Word se encuentra la combinación de correspondencia?','["Disposición", "Insertar > Combinar", "Correspondencia", "Referencias y citas"]'::jsonb,2,'Word · Correspondencia','Permite generar cartas, sobres o etiquetas a partir de una lista de destinatarios.',null),
('adm-cm:43-cdc6acf9f1','adm-cm',43,'En Word, la vista que muestra el documento tal como se imprimirá, con márgenes y encabezados, es:','["Modo de lectura", "Esquema con encabezados y márgenes", "Diseño de impresión", "Diseño web con márgenes"]'::jsonb,2,'Word · Vista','Es la vista predeterminada.','abr. 2026 · 2.º ejercicio'),
('adm-cm:43-7750d3c69a','adm-cm',43,'La sangría francesa en Word consiste en:','["Centrar el párrafo entre los márgenes", "Que todas las líneas del párrafo, excepto la primera, queden sangradas", "Que solo la primera línea del párrafo quede sangrada respecto del margen izquierdo", "Justificar el texto"]'::jsonb,1,'Word · Párrafo','Se usa mucho en bibliografías.',null),
('adm-cm:43-296ab841a9','adm-cm',43,'En Word, Mayús + F3 sobre un texto seleccionado:','["Alterna entre mayúsculas, minúsculas y tipo título", "Traduce el texto seleccionado al idioma predeterminado", "Lo pone en negrita, cursiva y subrayado", "Abre el cuadro de diálogo Fuente"]'::jsonb,0,'Word · Formato','Cambia el uso de mayúsculas del texto.',null),
('adm-cm:43-bfc9925d2a','adm-cm',43,'La extensión .dotx corresponde a:','["Un libro de Excel", "Un documento de Word con macros", "Una base de datos de Access", "Una plantilla de Word sin macros"]'::jsonb,3,'Word · Formatos','.dotm es una plantilla con macros.',null),
('adm-cm:43-7c4df3beac','adm-cm',43,'Para que Word genere automáticamente una tabla de contenido, los títulos deben tener aplicados:','["Color azul y negrita", "Negrita, subrayado y un tamaño de letra mayor", "Estilos de título (Título 1, Título 2…)", "Tamaño de letra superior a 14 y una marca de índice en cada título"]'::jsonb,2,'Word · Referencias','La tabla de contenido se inserta desde la pestaña Referencias.',null),
('adm-cm:43-157a0ce905','adm-cm',43,'Para impedir que otras personas modifiquen un documento, Word ofrece en la pestaña Revisar la opción:','["Restringir edición", "Mostrar marcas", "Traducir", "Contar palabras y caracteres"]'::jsonb,0,'Word · Revisar','Permite limitar formato y edición o permitir solo comentarios.',null),
('adm-cm:43-f8d0018f01','adm-cm',43,'Para cambiar la orientación de la página a horizontal en Word se usa la pestaña:','["Disposición", "Vista", "Inicio", "Referencias"]'::jsonb,0,'Word · Disposición','Ahí están también márgenes, tamaño y columnas.',null),
('adm-cm:43-a853ae1703','adm-cm',43,'La herramienta Copiar formato de Word (icono de brocha) permite:','["Aplicar el formato de un texto a otro texto", "Copiar el texto sin formato para pegarlo en otro documento", "Copiar el documento entero", "Copiar la tabla completa con su formato a otra parte"]'::jsonb,0,'Word · Inicio','Con doble clic sobre la brocha se puede aplicar el formato varias veces.',null),
('adm-cm:43-9ed15cc07a','adm-cm',43,'La opción Interlineado de Word controla:','["El espacio entre los caracteres de una palabra", "El margen izquierdo del párrafo seleccionado", "El número de columnas", "El espacio entre las líneas de un párrafo"]'::jsonb,3,'Word · Párrafo','El espaciado anterior y posterior controla el espacio entre párrafos.','abr. 2026 · 2.º ejercicio'),
('adm-cm:43-d6e62c6231','adm-cm',43,'Para guardar un documento de Word como PDF se usa:','["Vista > Macros", "Insertar > Objeto > Texto de archivo PDF", "Revisar > Comparar > Exportar documento", "Archivo > Guardar como (o Exportar) eligiendo el tipo PDF"]'::jsonb,3,'Word · Archivo','Word permite crear PDF sin programas adicionales.',null),
('adm-cm:43-a3f47fce03','adm-cm',43,'En una tabla de Word, «Combinar celdas»:','["Une varias celdas seleccionadas en una sola", "Divide una celda seleccionada en varias filas o columnas", "Suma los valores de las celdas", "Ordena las filas"]'::jsonb,0,'Word · Tablas','«Dividir celdas» hace lo contrario.',null),
('adm-cm:43-36cb4e96fc','adm-cm',43,'¿Qué extensión tiene por defecto un documento de Word sin macros?','[".docm", ".docx", ".dotx", ".xlsx"]'::jsonb,1,'Word · Formatos','.docm admite macros y .dotx es una plantilla.',null),
('adm-cm:43-e289a098ba','adm-cm',43,'En Word, la combinación Ctrl + Entrar inserta:','["Una tabla", "Un salto de columna", "Un salto de línea", "Un salto de página"]'::jsonb,3,'Word · Saltos','Ctrl+Mayús+Entrar inserta un salto de columna.',null),
('adm-cm:43-9d06b61271','adm-cm',43,'Un marcador en Word sirve para:','["Resaltar texto en amarillo para revisarlo más tarde", "Identificar una ubicación del documento para ir a ella o hacer referencias cruzadas", "Proteger una parte del documento para que solo la modifiquen determinadas personas con permiso", "Insertar en el margen un comentario visible que identifique la ubicación del texto para el resto de revisores"]'::jsonb,1,'Word · Insertar','Se inserta desde Insertar > Marcador.',null),
('adm-cm:43-840697a44f','adm-cm',43,'En Word, Mayús + Entrar inserta:','["Un salto de sección continuo", "Un salto de línea manual sin crear un párrafo nuevo", "Un salto de página que inicia una nueva sección del documento", "Un párrafo nuevo con el mismo estilo que el anterior"]'::jsonb,1,'Word · Saltos','Entrar crea un párrafo nuevo.',null),
('adm-cm:43-c843c2416c','adm-cm',43,'La función de Word que guarda un texto o imagen reutilizable para insertarlo rápidamente se llama:','["Marcadores", "Referencias cruzadas a títulos y marcadores del documento", "Elementos rápidos (bloques de creación / Autotexto)", "Hipervínculos a archivos"]'::jsonb,2,'Word · Insertar','Se encuentra en Insertar > Elementos rápidos.',null),
('adm-cm:43-a91d0a7180','adm-cm',43,'Para añadir propiedades personalizadas a un documento de Word se usa:','["Revisar > Restringir edición", "Insertar > Elementos rápidos > Propiedad del documento", "No es posible", "Archivo > Información > Propiedades > Propiedades avanzadas"]'::jsonb,3,'Word · Propiedades','En la pestaña Personalizar se definen nombre, tipo y valor.','feb. 2025 · 2.º ejercicio'),
('adm-cm:43-2a732c85d7','adm-cm',43,'Para que un capítulo use numeración de páginas en romanos y el siguiente empiece en 1 con números arábigos, hay que insertar entre ellos:','["Un salto de columna", "Un salto de sección de página siguiente", "Un salto de página con numeración reiniciada", "Un salto de sección continuo con la opción Vincular al anterior activada"]'::jsonb,1,'Word · Saltos','Cada sección puede tener su propio formato y numeración.','oct. 2026 · 2.º ejercicio'),
('adm-cm:43-5f10e5de6d','adm-cm',43,'La diferencia entre una lista con viñetas y una numerada es que:','["La de viñetas usa símbolos y la numerada usa números o letras ordenados", "La numerada no se puede personalizar ni continuar después de un párrafo sin numerar, mientras que la de viñetas sí", "La de viñetas solo sirve para índices", "No hay diferencia"]'::jsonb,0,'Word · Listas','Ambas se pueden personalizar.','feb. 2025 · 2.º ejercicio'),
('adm-cm:43-501b22ef85','adm-cm',43,'Si creas un documento nuevo en Word, nunca lo guardas y se cierra, puedes intentar recuperarlo con:','["Archivo > Información > Administrar documento > Recuperar documentos no guardados", "Archivo > Abrir > Examinar > Abrir y reparar, eligiendo el archivo temporal", "Revisar > Comparar", "Vista > Mostrar"]'::jsonb,0,'Word · Recuperación','Depende de que Autorrecuperación esté activada.','oct. 2026 · 2.º ejercicio'),
('adm-cm:43-8e5cfe7ee3','adm-cm',43,'En la búsqueda avanzada de Word con caracteres comodín, ¿qué símbolo excluye los caracteres indicados entre corchetes, como en [!a-c]?','["*", "!", "-", "?"]'::jsonb,1,'Word · Buscar','? sustituye a un carácter y * a cualquier cadena.','feb. 2025 · 2.º ejercicio'),
('adm-cm:43-cbc94a61f3','adm-cm',43,'Si vinculas una lista multinivel a los estilos Título 1, 2 y 3, la tabla de contenido generada:','["Duplica la numeración", "Muestra solo el texto de los títulos sin números", "Incluye los números de la lista junto al texto de cada título", "No muestra los títulos"]'::jsonb,2,'Word · Referencias','La tabla de contenido toma el texto y la numeración de los títulos.',null),
('adm-cm:43-81a78577e4','adm-cm',43,'La barra de herramientas de acceso rápido de Word se puede colocar debajo de la cinta mediante la opción:','["Anclar barra de herramientas a la cinta", "Restablecer el diseño predeterminado de la cinta", "Mostrar debajo de la cinta de opciones", "Cambiar posición de paneles"]'::jsonb,2,'Word · Interfaz','Se elige desde el menú de personalización de la propia barra.','oct. 2026 · 2.º ejercicio'),
('adm-cm:43-0375508dbe','adm-cm',43,'El panel Editor de Word sirve para:','["Registrar los cambios de cada revisor para aceptarlos o rechazarlos uno a uno", "Editar el documento a la vez con otras personas", "Revisar ortografía y gramática y ofrecer sugerencias de claridad, concisión y estilo", "Convertir el documento a PDF"]'::jsonb,2,'Word · Revisar','Se abre con F7 o desde Inicio > Editor.','oct. 2026 · 2.º ejercicio'),
('adm-cm:43-b51a7e17e8','adm-cm',43,'Para insertar el contenido de otro documento de Word dentro del documento actual se usa:','["Insertar > Objeto > Texto de archivo", "No es posible", "Referencias > Referencia cruzada", "Insertar > Cuadro de texto"]'::jsonb,0,'Word · Insertar','Inserta el texto del otro archivo en la posición del cursor.','feb. 2025 · 2.º ejercicio'),
('adm-cm:43-af62b36535','adm-cm',43,'Para que varias personas editen un documento de Word a la vez (coautoría), el documento debe:','["Enviarse como adjunto por correo a todos los coautores con permiso de edición", "Estar guardado en OneDrive o SharePoint y compartido con permiso de edición", "Estar en el escritorio de cada usuario", "Ser de la misma organización obligatoriamente"]'::jsonb,1,'Word · Coautoría','Se ven en tiempo real los cambios de los demás.','oct. 2026 · 2.º ejercicio'),
('adm-cm:43-f95f50f1c3','adm-cm',43,'El botón Dictar de Word se encuentra en:','["La pestaña Insertar, e inserta un archivo de audio", "La pestaña Revisar, y lee el documento en voz alta con la voz predeterminada", "La pestaña Vista, y activa el lector de pantalla", "La pestaña Inicio, y convierte en texto lo que dices por el micrófono"]'::jsonb,3,'Word · Inicio','Leer en voz alta está en la pestaña Revisar.','oct. 2026 · 2.º ejercicio'),
('adm-cm:44-6492cccbda','adm-cm',44,'En Excel, Ctrl + ; (punto y coma) inserta:','["La hora actual", "La función HOY(), que se actualiza", "La fecha actual como valor fijo", "La fecha y la hora actuales, que se actualizan al recalcular"]'::jsonb,2,'Excel · Atajos','Ctrl+Mayús+: inserta la hora actual.',null),
('adm-cm:44-4e981328d2','adm-cm',44,'En Excel, Ctrl + Inicio lleva a:','["La última celda con datos", "La hoja anterior", "La primera celda de la fila actual", "La celda A1"]'::jsonb,3,'Excel · Navegación','Ctrl+Fin lleva a la última celda utilizada.',null),
('adm-cm:44-4e0328bc60','adm-cm',44,'La función CONTAR de Excel cuenta:','["Las celdas vacías", "Todas las celdas que no están vacías", "Las celdas que contienen números", "Las celdas con texto"]'::jsonb,2,'Excel · Funciones','Para contar celdas no vacías de cualquier tipo se usa CONTARA.',null),
('adm-cm:44-b4c4596abb','adm-cm',44,'La función BUSCARV de Excel busca un valor:','["En la primera columna de un rango y devuelve un valor de la misma fila en otra columna", "Solo en tablas dinámicas", "En la primera fila de un rango y devuelve un valor de la misma columna en otra fila", "En cualquier celda y devuelve su posición"]'::jsonb,0,'Excel · Funciones','BUSCARH busca en la primera fila; BUSCARX es la función moderna que sustituye a ambas.',null),
('adm-cm:44-1e3dc32d02','adm-cm',44,'La función SI.ERROR de Excel:','["Muestra siempre un mensaje de error personalizado, aunque la fórmula no contenga ningún error", "Cuenta los errores de un rango", "Corrige automáticamente las fórmulas que devuelven un error y muestra el resultado corregido", "Devuelve un valor alternativo si la fórmula da error y, si no, el resultado de la fórmula"]'::jsonb,3,'Excel · Funciones','Ejemplo: =SI.ERROR(A1/B1;0).',null),
('adm-cm:44-aa227ecd12','adm-cm',44,'El error #¡REF! en Excel aparece cuando:','["Se usa texto en una operación matemática", "Se divide entre cero", "Falta un valor en una búsqueda de BUSCARV o de COINCIDIR y no se encuentra la coincidencia", "Una fórmula hace referencia a una celda que no es válida, por ejemplo porque se ha eliminado"]'::jsonb,3,'Excel · Errores','#¡VALOR! aparece cuando se usa un tipo de dato incorrecto.',null),
('adm-cm:44-bca6080981','adm-cm',44,'En Excel, al editar una fórmula, la tecla F4 sobre una referencia:','["Repite la fórmula", "Recalcula la hoja", "Alterna entre referencia relativa, absoluta y mixta", "Abre el asistente de funciones con los argumentos de la fórmula"]'::jsonb,2,'Excel · Referencias','Recorre A1 → $A$1 → A$1 → $A1.',null),
('adm-cm:44-9f34032422','adm-cm',44,'Si una celda muestra ##### en Excel, normalmente significa que:','["La columna no es lo bastante ancha para mostrar el valor", "La fórmula contiene una referencia circular o un error de sintaxis", "La celda está protegida y bloqueada con contraseña por el autor", "El valor es un texto demasiado largo"]'::jsonb,0,'Excel · Errores','Basta con ensanchar la columna.',null),
('adm-cm:44-b45a4daa29','adm-cm',44,'La opción Inmovilizar paneles de Excel sirve para:','["Proteger la hoja con contraseña para que no se modifiquen los paneles", "Mantener visibles filas o columnas al desplazarse por la hoja", "Impedir que se impriman las filas y columnas seleccionadas", "Ocultar filas o columnas para que no se vean al desplazarse por la hoja"]'::jsonb,1,'Excel · Vista','Se encuentra en la pestaña Vista.',null),
('adm-cm:44-5fbac6d919','adm-cm',44,'En Excel, Alt + Entrar dentro de una celda:','["Abre el cuadro Formato de celdas", "Inserta una fila nueva encima de la celda activa", "Confirma la entrada y baja a la siguiente celda", "Inserta un salto de línea en la misma celda"]'::jsonb,3,'Excel · Atajos','Permite escribir varias líneas en una celda.',null),
('adm-cm:44-b57ef0553d','adm-cm',44,'La herramienta de Excel que resume grandes cantidades de datos permitiendo reorganizar filas y columnas arrastrando campos es:','["El filtro avanzado", "La validación de datos", "La tabla dinámica", "El formato condicional"]'::jsonb,2,'Excel · Análisis','Se inserta desde Insertar > Tabla dinámica.','abr. 2026 · 2.º ejercicio'),
('adm-cm:44-149b2c6d11','adm-cm',44,'En Excel, ¿qué referencia permanece fija al copiar una fórmula a otras celdas?','["$A$1", "A1", "$A1", "A$1"]'::jsonb,0,'Excel · Referencias','$A$1 es absoluta; A$1 y $A1 son mixtas; A1 es relativa.',null),
('adm-cm:44-35a122ca9a','adm-cm',44,'En Excel, la tecla F2 sirve para:','["Insertar un gráfico", "Editar la celda activa", "Abrir el cuadro Ir a", "Guardar como"]'::jsonb,1,'Excel · Atajos','F5 abre el cuadro Ir a.',null),
('adm-cm:44-266b3d7d98','adm-cm',44,'¿Cuántas filas tiene como máximo una hoja de cálculo de Excel actual (formato .xlsx)?','["1.000.000", "1.048.576", "65.536", "16.384"]'::jsonb,1,'Excel · Especificaciones','65.536 era el límite del antiguo formato .xls.','oct. 2026 · 2.º ejercicio'),
('adm-cm:44-02942b8673','adm-cm',44,'¿Qué error muestra Excel al dividir un número entre cero?','["#N/A", "#¡DIV/0!", "#¡REF!", "#¿NOMBRE?"]'::jsonb,1,'Excel · Errores','#N/A indica valor no disponible, por ejemplo en una búsqueda sin coincidencia.',null),
('adm-cm:44-4602ebaeee','adm-cm',44,'¿Qué devuelve la función HOY() de Excel?','["El año actual", "La fecha y la hora actuales", "La fecha actual", "El día de la semana"]'::jsonb,2,'Excel · Funciones','AHORA() devuelve fecha y hora.',null),
('adm-cm:44-d11d091efd','adm-cm',44,'El error #¿NOMBRE? en Excel suele indicar que:','["Excel no reconoce un texto de la fórmula, por ejemplo una función mal escrita", "La columna es demasiado estrecha para mostrar el resultado", "Se divide entre cero", "Una referencia no es válida porque se ha eliminado la celda o la hoja a la que apunta"]'::jsonb,0,'Excel · Errores','#¡REF! aparece cuando una fórmula apunta a una celda eliminada.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:44-8b467969b5','adm-cm',44,'El formato condicional de Excel sirve para:','["Combinar automáticamente las celdas que tienen el mismo valor en una columna o fila", "Proteger la hoja", "Ordenar y filtrar automáticamente los datos de una tabla según los valores de una columna", "Aplicar formato automáticamente a las celdas que cumplen determinadas condiciones"]'::jsonb,3,'Excel · Inicio','Por ejemplo, colorear en rojo los valores negativos.',null),
('adm-cm:44-2175582ae8','adm-cm',44,'En Excel, Mayús + F11:','["Cierra el libro activo sin guardar", "Crea un gráfico con los datos seleccionados", "Inserta una hoja de cálculo nueva", "Inserta una fila"]'::jsonb,2,'Excel · Atajos','Es un atajo independiente del idioma.',null),
('adm-cm:44-6e4d9ef1b6','adm-cm',44,'¿Qué operador de Excel une textos de varias celdas?','["%", "&", "#", "+"]'::jsonb,1,'Excel · Operadores','Ejemplo: =A1&" "&B1. También pueden usarse CONCAT o UNIRCADENAS.',null),
('adm-cm:44-64488e67e9','adm-cm',44,'¿Qué extensión tiene un libro de Excel que contiene macros?','[".xlsm", ".csv", ".xltx", ".xlsx"]'::jsonb,0,'Excel · Formatos','.xlsx no admite macros y .xltx es una plantilla.',null),
